function localStorageOrNull() {
  return typeof localStorage === 'undefined' ? null : localStorage;
}

function deploymentStorageSuffix() {
  const manifestHash = String(appConfig.vault?.deploymentManifestHash ?? '').replace(/^0x/i, '').toLowerCase();
  if (/^[0-9a-f]{64}$/.test(manifestHash)) return manifestHash.slice(0, 16);
  const vaultAddress = String(appConfig.vault?.address ?? '').replace(/[^a-z0-9_-]/gi, '');
  return vaultAddress.slice(-16) || 'no-deployment';
}

function scopedStorageKey(baseKey) {
  return `${baseKey}:${deploymentStorageSuffix()}`;
}

function scopedIndexedDbName(baseName) {
  return `${baseName}.${deploymentStorageSuffix()}`;
}

// Profile-avatar media now lives in IndexedDB (per-record writes, large quota) instead of localStorage —
// whose iOS whole-store re-serialization on every write was the Vault-freeze root. Deployment-scoped (NOT
// wallet-scoped): avatars are content-addressed (sha256) and the public feed needs them before unlock.
// A single lazy DB open, cached as a promise; null if IndexedDB is unavailable (reads/writes then no-op).
const profileAvatarMediaStorePromise = (() => {
  try {
    return createProfileAvatarMediaStore({ dbName: scopedIndexedDbName('platho-profile-avatar-media-v1') }).catch(() => null);
  } catch {
    return Promise.resolve(null);
  }
})();
function profileAvatarMediaStore() {
  return profileAvatarMediaStorePromise;
}

// DURABLE cache of a post's loaded comments (assembled bodies + image data URLs), keyed `${channelId}:${entryId}`
// in IndexedDB. localStorage strips image data URLs (omitHeavyFeedMediaForPersist), so the feed cache cannot hold
// them; IndexedDB can. Survives a full reload, so re-opening a post shows its comments (WITH images) instantly
// instead of re-walking the chain + re-downloading every ~32KB comment image (owner-flagged). Reuses the media
// store shape as a generic key->JSON string KV (its LRU cap bounds growth).
const publicCommentCacheStorePromise = (() => {
  try {
    return createProfileAvatarMediaStore({ dbName: scopedIndexedDbName('platho-public-comments-v1'), cap: 50 }).catch(() => null);
  } catch {
    return Promise.resolve(null);
  }
})();

async function readCachedPublicComments(cacheKey) {
  if (!cacheKey) return null;
  try {
    const store = await publicCommentCacheStorePromise;
    const record = await store?.get(cacheKey);
    if (typeof record?.url !== 'string' || record.url.length === 0) return null;
    const parsed = JSON.parse(record.url);
    return Array.isArray(parsed?.comments) ? parsed : null;
  } catch {
    return null;
  }
}

async function writeCachedPublicComments(cacheKey, comments, parentExists, latestLink) {
  if (!cacheKey || !Array.isArray(comments)) return;
  try {
    const store = await publicCommentCacheStorePromise;
    await store?.put(cacheKey, JSON.stringify({
      comments,
      parentExists: parentExists === true,
      // The parent index's latest_entry_link at load time — the incremental cursor (append-only chain): an
      // unchanged link on the next open means ZERO body re-reads.
      latestLink: latestLink === undefined || latestLink === null ? null : String(latestLink),
    }));
  } catch {
    /* ignore (quota / unavailable) */
  }
}

// PER-ENTRY durable cache of resolved PUBLIC ENTRY BODIES (raw base64 BoC + hash) — the faithful private-message
// model applied at the RIGHT level. Private message bodies persist UNCONDITIONALLY + INDIVIDUALLY the moment they
// resolve and are restored from IndexedDB, so a private image NEVER re-downloads. Public bodies (posts, comments,
// every multipart image part) previously lived only in the provider's in-memory publishBodyCache: getPublicEntry
// returns body_boc:null, so after a reload EVERY body was a live ~32KB getMessages read again (cache-bypassed by
// messageCacheTtlMs:0) — the owner-flagged "images re-download from the blockchain on every reload", for the FEED
// SYNC as much as the post detail. This store sits inside resolvePublicEntryPayload — the single funnel all 7
// public body readers go through — keyed by entry_id with the entry's body_hash pinned: bodies are immutable +
// content-addressed, so a hash-matched hit is authoritative and never stale. Caching the raw BoC (a base64
// string, JSON-safe by construction) means the cached path re-parses through the EXACT same
// tryReadPublicEntryPayload pipeline as a live read — zero decode drift. Deployment-scoped (public content,
// readable before unlock), never wallet-scoped. LRU-capped; eviction just re-downloads.
const publicEntryBodyStorePromise = (() => {
  try {
    return createProfileAvatarMediaStore({ dbName: scopedIndexedDbName('platho-public-entry-bodies-v1'), cap: 500 }).catch(() => null);
  } catch {
    return Promise.resolve(null);
  }
})();

async function readCachedPublicEntryBody(entryId) {
  if (entryId === undefined || entryId === null) return null;
  try {
    const store = await publicEntryBodyStorePromise;
    const record = await store?.get(`entry:${entryId}`);
    if (typeof record?.url !== 'string' || record.url.length === 0) return null;
    const parsed = JSON.parse(record.url);
    if (typeof parsed?.body_boc !== 'string' || parsed.body_boc.length === 0) return null;
    return parsed; // { body_boc, body_hash }
  } catch {
    return null;
  }
}

async function writeCachedPublicEntryBody(entryId, bodyBoc, bodyHashHex) {
  if (entryId === undefined || entryId === null || typeof bodyBoc !== 'string' || bodyBoc.length === 0) return;
  try {
    const store = await publicEntryBodyStorePromise;
    await store?.put(`entry:${entryId}`, JSON.stringify({ body_boc: bodyBoc, body_hash: bodyHashHex ?? null }));
  } catch {
    /* ignore (quota / unavailable) */
  }
}

// DECODED public POST image media persists as data-urls in IndexedDB — the SAME durable-media model as author
// avatars (platho-profile-avatar-media-v1, warmed before the first render) and post-detail comments
// (platho-public-comments-v1). Why a decoded store on top of the per-entry BODY cache: the localStorage feed
// cache STRIPS every image data-url on persist (omitHeavyFeedMediaForPersist — the iOS whole-store re-serialize
// freeze), so on reload a post loads image-LESS and the image previously only came back after the full serial
// chain re-walk (~a minute — owner-flagged "looks like it re-downloads from the blockchain every time"). The
// body IS a cache HIT, but the durable body cache is keyed by per-PART entry_ids that are NOT persisted, and it
// has no header_boc, so it can only be consulted from INSIDE the walk that rediscovers those ids — that walk is
// the minute. Warming THIS store before the first render restores the image in milliseconds with zero chain
// reads, exactly like the avatar warm. Keyed by post.id (stable, persisted, present by construction); value =
// JSON {imageUrl, blocks} — the exact render-consumed media, overlaid onto the stripped light item (chain posts
// are immutable, so captured media is authoritative forever). Deployment-scoped (public, pre-unlock), LRU-capped
// (eviction just re-decodes from the body cache on the next sync).
const publicPostMediaStorePromise = (() => {
  try {
    return createProfileAvatarMediaStore({ dbName: scopedIndexedDbName('platho-public-post-media-v1'), cap: 400 }).catch(() => null);
  } catch {
    return Promise.resolve(null);
  }
})();
function publicPostMediaStore() {
  return publicPostMediaStorePromise;
}

// The heavy render-consumed image media a post carries (its OWN image — the author avatar has its own store).
// Returns null when the post has no image. Keeps the FULL blocks array so a text+image post restores the image
// in its original position among text blocks; imageUrl covers the legacy image-only post shape.
function publicPostRenderableImageMedia(post) {
  if (!post || typeof post !== 'object') return null;
  const imageUrl = typeof post.imageUrl === 'string' && post.imageUrl.length > 0 ? post.imageUrl : null;
  const hasImageBlock = Array.isArray(post.blocks)
    && post.blocks.some((block) => block?.type === 'image' && typeof block.url === 'string' && block.url.length > 0);
  if (!imageUrl && !hasImageBlock) return null;
  return { imageUrl, blocks: Array.isArray(post.blocks) ? post.blocks : null };
}

function publicPostCacheKey(post) {
  return typeof post?.id === 'string' && post.id.length > 0 ? post.id : null;
}

// Overlay durable media back onto a stripped light item. Only fills what is MISSING so a freshly-synced post
// that already carries its image is never churned. Returns whether anything changed.
function applyPublicPostMediaRecord(post, media) {
  if (!post || typeof post !== 'object' || !media || typeof media !== 'object') return false;
  if (publicPostRenderableImageMedia(post)) return false; // already has a renderable image — leave it
  let changed = false;
  if (Array.isArray(media.blocks)
    && media.blocks.some((block) => block?.type === 'image' && typeof block.url === 'string' && block.url.length > 0)) {
    post.blocks = media.blocks;
    changed = true;
  }
  if ((typeof post.imageUrl !== 'string' || post.imageUrl.length === 0)
    && typeof media.imageUrl === 'string' && media.imageUrl.length > 0) {
    post.imageUrl = media.imageUrl;
    changed = true;
  }
  return changed;
}

function eachCachedPublicPost(callback) {
  for (const record of Object.values(publicChannelFeedCache ?? {})) {
    const feed = record?.feed ?? record;
    const posts = Array.isArray(feed?.posts) ? feed.posts : (Array.isArray(feed) ? feed : []);
    for (const post of posts) callback(post);
  }
}

// LOAD-TIME hydration: fill post images from IndexedDB into the in-memory feed cache BEFORE the first render,
// so a reloaded post shows its image in ms without waiting for the serial chain walk. Mutates cache posts in
// place (rebuildThreadsFromPublicSubscriptions then reads them). Returns whether anything changed.
async function warmPublicPostImagesFromCache() {
  try {
    const pending = [];
    eachCachedPublicPost((post) => {
      if (publicPostRenderableImageMedia(post)) return; // already carries its image
      const key = publicPostCacheKey(post);
      if (key) pending.push({ post, key });
    });
    if (pending.length === 0) return false;
    const store = await publicPostMediaStore();
    if (!store) return false;
    const raws = await store.getMany(pending.map((entry) => entry.key));
    let changed = false;
    for (const { post, key } of pending) {
      const raw = raws.get(key);
      if (!raw) continue;
      let media = null;
      try { media = JSON.parse(raw); } catch { media = null; }
      if (applyPublicPostMediaRecord(post, media)) changed = true;
    }
    return changed;
  } catch {
    return false;
  }
}

// Media is immutable per post → persist a given post.id's media at most once per session.
const persistedPublicPostMediaKeys = new Set();
function schedulePublicPostImageMediaPersist() {
  setTimeout(() => { void persistPublicPostImageMedia(); }, 0);
}
async function persistPublicPostImageMedia() {
  try {
    let store = null;
    const targets = [];
    eachCachedPublicPost((post) => {
      const key = publicPostCacheKey(post);
      if (!key || persistedPublicPostMediaKeys.has(key)) return;
      const media = publicPostRenderableImageMedia(post);
      if (!media) return; // no image yet — leave the key unmarked so a later sync persists it
      targets.push({ key, media });
    });
    if (targets.length === 0) return;
    store = await publicPostMediaStore();
    if (!store) return;
    for (const { key, media } of targets) {
      if (persistedPublicPostMediaKeys.has(key)) continue;
      await store.put(key, JSON.stringify(media));
      persistedPublicPostMediaKeys.add(key);
    }
  } catch {
    /* best effort (quota / unavailable) */
  }
}

// Single choke point for persisting the public feed cache: the light text/metadata goes to localStorage (image
// data-urls stripped to dodge the iOS freeze) and — SYMMETRICALLY — the heavy decoded image media goes to
// IndexedDB, so the strip never costs a chain re-walk on reload. Every feed-cache write goes through here.
function commitPublicChannelFeedCache() {
  writePublicChannelFeedCache(publicChannelStorage(), publicChannelFeedCache);
  schedulePublicPostImageMediaPersist();
}

function walletIndexedDbSuffix(walletAddress = plathoWallet?.address) {
  if (!walletAddress) return 'wallet-locked';
  try {
    const parsed = parseTonAddress(walletAddress).raw;
    return String(parsed).replace(/[^a-z0-9_-]/gi, '').slice(-18) || 'wallet-unknown';
  } catch {
    return String(walletAddress).replace(/[^a-z0-9_-]/gi, '').slice(-18) || 'wallet-unknown';
  }
}

function walletScopedIndexedDbName(baseName, walletAddress = plathoWallet?.address) {
  return `${scopedIndexedDbName(baseName)}.${walletIndexedDbSuffix(walletAddress)}`;
}

function currentMessageHistoryDbName(walletAddress = plathoWallet?.address) {
  return walletScopedIndexedDbName(LEGACY_MESSAGE_HISTORY_DB_NAME, walletAddress);
}

function currentReplayDbName(walletAddress = plathoWallet?.address) {
  return walletScopedIndexedDbName(LEGACY_REPLAY_DB_NAME, walletAddress);
}

// The direct-pay CONV lane's sealed K_root store lives in a WALLET-SCOPED IndexedDB so one wallet's conversation keys
// never bleed into another's ([[cross-wallet-identity-bleed]]); the seal key is device-local within that DB.
function currentConvKeyDbName(walletAddress = plathoWallet?.address) {
  return walletScopedIndexedDbName('platho-conv-keys-v1', walletAddress);
}

function deploymentScopedStorage(storage, scopedKeys) {
  if (!storage) return storage;
  const keyFor = (key) => (scopedKeys.has(key) ? scopedStorageKey(key) : key);
  return {
    getItem(key) {
      return storage.getItem(keyFor(key));
    },
    setItem(key, value) {
      return storage.setItem(keyFor(key), value);
    },
    removeItem(key) {
      return storage.removeItem(keyFor(key));
    },
  };
}

const PUBLIC_CHANNEL_STORAGE_KEYS = new Set([
  PUBLIC_CHANNEL_SUBSCRIPTIONS_KEY,
  PUBLIC_CHANNEL_FEED_CACHE_KEY,
]);

function publicChannelStorage() {
  return deploymentScopedStorage(localStorageOrNull(), PUBLIC_CHANNEL_STORAGE_KEYS);
}

function rememberLocalStoragePersistenceStatus(status) {
  try {
    localStorageOrNull()?.setItem(PLATHO_STORAGE_PERSISTENCE_KEY, String(status));
  } catch {
    // Storage persistence status is advisory; wallet writes are checked separately.
  }
}

async function requestPersistentLocalStorage() {
  const storageManager = navigator.storage;
  if (!storageManager?.persist) {
    rememberLocalStoragePersistenceStatus('unsupported');
    return 'unsupported';
  }
  try {
    const alreadyPersisted = typeof storageManager.persisted === 'function'
      ? await storageManager.persisted()
      : false;
    if (alreadyPersisted) {
      rememberLocalStoragePersistenceStatus('granted');
      return 'granted';
    }
    const granted = await storageManager.persist();
    rememberLocalStoragePersistenceStatus(granted ? 'granted' : 'denied');
    return granted ? 'granted' : 'denied';
  } catch (error) {
    console.error(error);
    rememberLocalStoragePersistenceStatus('error');
    return 'error';
  }
}

function isStandaloneApp() {
  return window.matchMedia?.('(display-mode: standalone)')?.matches || window.navigator?.standalone === true;
}

function isIosDevice() {
  const ua = navigator.userAgent || '';
  return /iPad|iPhone|iPod/.test(ua) || (navigator.platform === 'MacIntel' && Number(navigator.maxTouchPoints || 0) > 1);
}

function installActionState() {
  if (isStandaloneApp()) return 'installed';
  if (installedRelatedPwaDetected) return 'open-in-app';
  if (deferredInstallPrompt) return 'prompt';
  return isIosDevice() ? 'ios-instructions' : 'instructions';
}

function setInstallSteps(steps = []) {
  if (!installSteps) return;
  installSteps.replaceChildren();
  if (!steps.length) {
    installSteps.hidden = true;
    return;
  }
  steps.forEach((text) => {
    const item = document.createElement('li');
    item.textContent = text;
    installSteps.append(item);
  });
  installSteps.hidden = false;
}

function refreshInstallButtons() {
  if (isTelegramEnv()) {
    // PWA install is meaningless inside Telegram; keep every install affordance hidden.
    installButtons.forEach((button) => button.toggleAttribute('hidden', true));
    return;
  }
  const state = installActionState();
  const canInstall = state !== 'installed';
  installButtons.forEach((button) => {
    button.toggleAttribute('hidden', !canInstall);
    const label = state === 'prompt'
      ? t('install.installPlatho')
      : state === 'open-in-app'
      ? t('install.openPlathoApp')
      : state === 'ios-instructions'
      ? t('install.howToInstallIphone')
      : t('install.openOrInstall');
    button.setAttribute('aria-label', label);
    button.title = label;
    const icon = button.querySelector('.icon');
    icon?.classList.toggle('icon-install', state === 'prompt');
    icon?.classList.toggle('icon-open-app', state !== 'prompt');
  });
  if (installTitle) {
    installTitle.textContent = state === 'prompt'
      ? t('install.installPlatho')
      : state === 'open-in-app'
      ? t('install.openPlathoApp')
      : state === 'ios-instructions'
      ? t('install.installOnIphone')
      : t('install.openOrInstall');
  }
  if (installConfirmButton) {
    installConfirmButton.textContent = state === 'prompt' ? t('install.install') : t('install.gotIt');
  }
  if (installDismissButton) {
    installDismissButton.textContent = t('install.notNow');
    installDismissButton.hidden = state !== 'prompt';
  }
  if (installLead) {
    installLead.textContent = state === 'open-in-app'
      ? t('install.leadOpenInApp')
      : state === 'ios-instructions'
      ? t('install.leadIos')
      : state === 'instructions'
      ? t('install.leadInstructions')
      : t('install.leadPrompt');
  }
  if (installBody) {
    installBody.textContent = state === 'open-in-app'
      ? t('install.bodyOpenInApp')
      : state === 'ios-instructions'
      ? t('install.bodyIos')
      : state === 'instructions'
      ? t('install.bodyInstructions')
      : t('install.bodyPrompt');
  }
  setInstallSteps(state === 'ios-instructions'
    ? [
      t('install.iosStep1'),
      t('install.iosStep2'),
      t('install.iosStep3'),
      t('install.iosStep4'),
    ]
    : []);
  if (installHelp) {
    installHelp.textContent = state === 'installed'
      ? t('install.helpInstalled')
      : state === 'open-in-app'
      ? t('install.helpOpenInApp')
      : state === 'ios-instructions'
      ? t('install.helpIos')
      : state === 'prompt'
      ? t('install.helpPrompt')
      : installHelpText();
  }
}

function installPromptDismissed() {
  return localStorageOrNull()?.getItem(INSTALL_PROMPT_DISMISSED_STORAGE_KEY) === '1';
}

function markInstallPromptDismissed() {
  localStorageOrNull()?.setItem(INSTALL_PROMPT_DISMISSED_STORAGE_KEY, '1');
}

function openInstallDialogIfUseful() {
  if (isTelegramEnv()) return;
  if (!installDialog || installPromptDismissed() || isStandaloneApp()) return;
  installDialog.hidden = false;
  refreshInstallButtons();
}

function closeInstallDialog({ dismissed = true } = {}) {
  if (dismissed) markInstallPromptDismissed();
  if (installDialog) installDialog.hidden = true;
}

let composerViewportMaxHeight = 0; // largest visible viewport height seen AT THE CURRENT WIDTH = the no-soft-keyboard baseline
let composerViewportBaselineWidth = 0; // width the baseline was captured at; a width change (orientation/resize) re-baselines
let composerKeyboardWasOpen = false; // last-seen soft-keyboard state, to detect the up->down (dismissed) transition
// The soft keyboard shrinks the visual viewport; "open" = the current visible height is meaningfully below the baseline.
// ~150px filters browser-chrome (address bar) changes (~50-120px) from a real keyboard (~250px+). Used to (a) re-focus
// on maximize only while the keyboard is UP (typing), and (b) detect when it is DISMISSED (see the hide-blur below).
function composerKeyboardLikelyOpen() {
  const viewport = window.visualViewport;
  if (!viewport || composerViewportMaxHeight <= 0) return false;
  return (composerViewportMaxHeight - viewport.height) > 150;
}

// Blur the focused composer editor the moment the soft keyboard is DISMISSED. Root cause of the mobile keyboard re-pop:
// hiding the keyboard with its own button leaves the field FOCUSED (caret visible) but the keyboard down, and then ANY
// geometry change (maximize / restore, and other reflows) makes a touch browser re-show the keyboard for that still-
// focused editable. Blurring on dismissal eliminates that "focused-but-keyboard-hidden" state at the source, so nothing
// can re-pop it. Only on a coarse-pointer (touch) device with a real soft keyboard; desktop/mouse never blurs (no soft
// keyboard, and a fine-pointer window resize must not drop the caret). Scoped to .composer-input so other fields are
// untouched. keyboardWasOpen tracks the last state so this fires exactly on the up->down edge, not on every VV tick.
function composerHandleKeyboardVisibility() {
  const nowOpen = composerKeyboardLikelyOpen();
  if (composerKeyboardWasOpen && !nowOpen) {
    const active = document.activeElement;
    const coarse = !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches);
    if (coarse && active && active.classList && active.classList.contains('composer-input')) active.blur();
  }
  composerKeyboardWasOpen = nowOpen;
}

function syncViewportCssVars() {
  // Inside Telegram the WebView height is governed by the client (viewportStableHeight),
  // not window.visualViewport — using the latter alone clips content under Telegram's header.
  const telegramHeight = telegramViewportHeight();
  const viewport = window.visualViewport;
  const visual = Math.round(viewport?.height ?? window.innerHeight ?? document.documentElement.clientHeight ?? 0);
  let height;
  if (telegramHeight > 0) {
    // Prefer Telegram's stable height, but let an on-screen keyboard (which shrinks
    // visualViewport on Android/Desktop) reduce it so the composer stays above the keyboard.
    height = visual > 0 ? Math.min(telegramHeight, visual) : telegramHeight;
  } else {
    height = visual;
  }
  // Key the no-keyboard baseline to the viewport WIDTH: a soft keyboard changes only the HEIGHT, but an orientation flip
  // (or a desktop window resize) changes the WIDTH and brings a whole new baseline height. Without this the monotonic max
  // keeps the taller PORTRAIT height as the baseline in LANDSCAPE, so composerKeyboardLikelyOpen() reads "open" forever
  // there and the keyboard-hide blur never fires (the fix would be dead in landscape). On a width change, re-baseline to
  // the current height and reset the keyboard edge so the flip itself doesn't read as a dismiss.
  const visualWidth = Math.round(viewport?.width ?? window.innerWidth ?? 0);
  if (visual > 0) {
    if (visualWidth !== composerViewportBaselineWidth) {
      composerViewportMaxHeight = visual; composerViewportBaselineWidth = visualWidth; composerKeyboardWasOpen = false;
    } else {
      composerViewportMaxHeight = Math.max(composerViewportMaxHeight, visual); // tallest at THIS width = no-soft-keyboard baseline
    }
  }
  composerHandleKeyboardVisibility(); // blur the composer if the soft keyboard was just dismissed (kills the re-pop at its source)
  const rounded = Math.max(0, Math.round(height));
  document.documentElement.style.setProperty('--app-viewport-height', `${Math.max(320, rounded)}px`);
  // Unclamped variant (no 320px floor) for the full-screen maximized composer only: on a short viewport (landscape or
  // a small/old device with the keyboard up) the floored value is taller than the visible area, so the overlay's
  // bottom-pinned send button (and a docked-below restore button) would hide behind the keyboard. The floor is kept
  // for --app-viewport-height because other layouts rely on it.
  if (rounded > 0) document.documentElement.style.setProperty('--app-viewport-height-exact', `${rounded}px`);
}

// ---- Telegram Mini App adapter --------------------------------------------
// Single codebase: when Platho runs inside a Telegram Mini App we load the
// self-hosted Telegram WebApp SDK (index.html) and turn on a thin adapter —
// native theme chrome, viewport + safe-area from Telegram, BackButton, closing
// confirmation, hidden PWA-install UI, and a softer background auto-lock. In an
// ordinary browser the SDK reports platform 'unknown', isTelegramEnv() is false,
// and every branch below is inert, so the standalone PWA is unchanged. Every SDK
// call is version-gated (isVersionAtLeast) and wrapped so an old client can never
// throw the app down.

function telegramWebApp() {
  const tg = window.Telegram && window.Telegram.WebApp;
  return tg && typeof tg === 'object' ? tg : null;
}

let telegramEnvCache;
function isTelegramEnv() {
  if (telegramEnvCache !== undefined) return telegramEnvCache;
  const tg = telegramWebApp();
  telegramEnvCache = Boolean(
    tg && (
      (typeof tg.initData === 'string' && tg.initData.length > 0)
      || (typeof tg.platform === 'string' && tg.platform && tg.platform !== 'unknown')
    ),
  );
  return telegramEnvCache;
}

function telegramSupports(version) {
  const tg = telegramWebApp();
  if (!tg || typeof tg.isVersionAtLeast !== 'function') return false;
  try {
    return Boolean(tg.isVersionAtLeast(version));
  } catch {
    return false;
  }
}

function telegramPlatform() {
  const tg = telegramWebApp();
  return tg && typeof tg.platform === 'string' ? tg.platform : '';
}

function isTelegramSuspendingPlatform() {
  // iOS WKWebView freezes a backgrounded Mini App (timers stop), so a deferred
  // background-lock timer would never fire there — keep lock-on-suspend on iOS.
  return telegramPlatform() === 'ios';
}

function telegramViewportHeight() {
  if (!isTelegramEnv()) return 0;
  const tg = telegramWebApp();
  const stable = Number(tg && tg.viewportStableHeight);
  if (Number.isFinite(stable) && stable > 0) return stable;
  const current = Number(tg && tg.viewportHeight);
  return Number.isFinite(current) && current > 0 ? current : 0;
}

function applyTelegramSafeArea() {
  // Telegram exposes safe areas via the SDK (>=8.0); env(safe-area-inset-*) is
  // unreliable inside the embed. We only override the CSS vars when the SDK can
  // report them, so older clients keep the env()-based fallback in styles.css.
  if (!isTelegramEnv() || !telegramSupports('8.0')) return;
  const tg = telegramWebApp();
  const root = document.documentElement.style;
  for (const side of ['top', 'right', 'bottom', 'left']) {
    const content = Number(tg && tg.contentSafeAreaInset && tg.contentSafeAreaInset[side]) || 0;
    const device = Number(tg && tg.safeAreaInset && tg.safeAreaInset[side]) || 0;
    const px = Math.max(0, Math.round(content + device));
    // Only override when we have a real inset. Setting 0 before the async
    // safe-area events arrive would clobber the env() fallback and let content
    // slide under the notch/home-indicator; leave it unset until the SDK reports one.
    if (px > 0) root.setProperty(`--app-safe-area-${side}`, `${px}px`);
    else root.removeProperty(`--app-safe-area-${side}`);
  }
}

// Back-navigation. The hardware/gesture Back (Android) — and the Telegram in-app BackButton — should return
// to the LIST when an overlay is open (a private conversation OR a public channel branch), and only exit the
// app from the list. Telegram env: drive the native BackButton (its click maps to Android Back). Non-Telegram
// (PWA/browser): keep exactly ONE history sentinel while an overlay is open, so a popstate (Android Back)
// closes the overlay instead of unloading the app.
function navOverlayIsOpen() {
  return appShell?.dataset?.chatOpen === 'true'
    || publicPane?.dataset?.postOpen === 'true'
    || publicPane?.dataset?.channelOpen === 'true';
}

let navHistorySentinel = false;
function syncNavBackAffordance() {
  const open = navOverlayIsOpen();
  if (isTelegramEnv()) {
    const tg = telegramWebApp();
    if (tg && tg.BackButton) { try { open ? tg.BackButton.show() : tg.BackButton.hide(); } catch {} }
    return;
  }
  if (open && !navHistorySentinel) {
    try { history.pushState({ plathoOverlay: 1 }, ''); navHistorySentinel = true; } catch {}
  }
}

function closeNavOverlay() {
  // A maximized composer is a full-screen overlay above the post detail / conversation; ANY back-navigation
  // (native/TG BackButton, hardware/swipe Back — these sit OUTSIDE the web viewport, so the overlay can't intercept
  // them) collapses it FIRST and consumes this Back, or the overlay strands the user over whatever they backed into.
  // A second Back then closes the underlying overlay.
  if (exitComposerMaximize()) {
    syncNavBackAffordance();
    return true;
  }
  // Public post detail -> back to the feed. Checked before the chat branch so Back closes whichever overlay is on.
  // closePublicPostDetail() also exits the composer's comment mode (setPublicCommentTarget(null)) — without it the
  // shared composer would stay pinned to the closed post and a feed "post" would publish as a comment.
  if (publicPane?.dataset?.postOpen === 'true') {
    closePublicPostDetail();
    syncNavBackAffordance();
    return true;
  }
  // Channel view -> back (to discovery when it launched the view, else the feed). Sits UNDER the post detail in
  // the stack: a post opened from the channel screen closes first (branch above), landing back on the channel.
  if (publicPane?.dataset?.channelOpen === 'true') {
    closePublicChannelView();
    syncNavBackAffordance();
    return true;
  }
  // Private conversation -> back to the dialog list. Clear activeThreadId so a later tab-return restores the
  // LIST, not this dialog: setView restores chatOpen from activeThreadId, and leaving it set re-opened the
  // dialog even when the user had backed out to the list.
  if (appShell?.dataset?.chatOpen === 'true') {
    appShell.dataset.chatOpen = 'false';
    activeThreadId = null;
    renderThreads();
    hideIdentityPopover();
    syncNavBackAffordance();
    return true;
  }
  return false;
}

function requestNavBack() {
  // Non-Telegram: pop the history sentinel so the stack stays consistent; popstate runs closeNavOverlay.
  if (!isTelegramEnv() && navHistorySentinel) {
    navHistorySentinel = false;
    try { history.back(); return; } catch { /* fall through to a direct close */ }
  }
  closeNavOverlay();
}

function installNavBackHandling() {
  if (!appShell) return;
  if (typeof MutationObserver === 'function') {
    const observer = new MutationObserver(syncNavBackAffordance);
    observer.observe(appShell, { attributes: true, attributeFilter: ['data-chat-open'] });
    if (publicPane) observer.observe(publicPane, { attributes: true, attributeFilter: ['data-post-open'] });
  }
  if (typeof window !== 'undefined' && !isTelegramEnv()) {
    window.addEventListener('popstate', () => {
      navHistorySentinel = false;
      closeNavOverlay();
    });
  }
  syncNavBackAffordance();
}

function openExternalLinkInTelegram(href) {
  const tg = telegramWebApp();
  if (!tg || typeof tg.openLink !== 'function') return false;
  try {
    tg.openLink(href);
    return true;
  } catch {
    return false;
  }
}

function openTelegramDeepLink(href) {
  const tg = telegramWebApp();
  if (tg && typeof tg.openTelegramLink === 'function') {
    try {
      tg.openTelegramLink(href);
      return true;
    } catch { /* fall through to openLink */ }
  }
  return openExternalLinkInTelegram(href);
}

// ── Safe auto-linking of URLs in user text (v749) ──────────────────────────────────────────
// User message / public-post text is rendered with appendLinkifiedText (below) instead of a raw textContent
// assignment: literal http(s) URLs become clickable, EVERYTHING ELSE stays a plain text node. Three layers keep
// this from re-opening the XSS-clean posture:
//   1. Scheme allowlist (safeExternalUrl): only http:/https: ever become an <a href>. javascript:/data:/blob:/
//      vbscript:/file:/tg:/intent: never match the autolink regex AND would be rejected here anyway, so a linkified
//      token can never execute. (The strict live CSP with no 'unsafe-inline' is a second backstop against href JS.)
//   2. No innerHTML anywhere — the anchor is built with createElement + textContent for the VISIBLE text.
//   3. We autolink the LITERAL url only (visible text === destination), so there is no [label](url) mismatch a
//      phisher could exploit — that markdown form stays limited to the owner's own Docs.
// Clicking does NOT navigate directly: it routes through an interstitial that shows the real destination and warns
// the external site will see the reader's IP (a real deanonymization vector for a privacy messenger — a unique
// per-recipient link is a read-receipt + IP beacon). A per-domain "don't ask again" suppresses the prompt.
// Matches EITHER a labeled link `[text](url)` (groups 1=label, 2=url) OR a bare http(s) URL (group 3). The labeled
// form is tried first at each position, so a bare-URL match never eats the url inside `(...)`. Only the composer's
// Link button produces `[text](url)`; a hand-typed one is fine too. Safety is identical for both: the url is
// scheme-checked (safeExternalUrl) and the visible text is textContent — a mismatched label is surfaced by the
// interstitial (which shows the REAL destination), never silently followed.
const LINKIFY_RE = /\[([^\]\n]{1,200})\]\(([^\s()]{1,2000})\)|(https?:\/\/[^\s<>"']+)/gi;

function safeExternalUrl(raw) {
  if (typeof raw !== 'string' || raw.length === 0) return null;
  let url;
  try { url = new URL(raw); } catch { return null; }
  if (url.protocol !== 'https:' && url.protocol !== 'http:') return null;
  return url.href;
}

function trimTrailingUrlPunctuation(url) {
  let out = url;
  while (out.length > 0 && '.,;:!?…\'")]}»'.includes(out[out.length - 1])) {
    // Keep a ')' that closes a '(' inside the URL (e.g. a Wikipedia link), otherwise strip trailing punctuation.
    if (out[out.length - 1] === ')' && out.includes('(')) break;
    out = out.slice(0, -1);
  }
  return out;
}

function appendLinkifiedText(parent, text) {
  const str = String(text ?? '');
  if (!str) return;
  LINKIFY_RE.lastIndex = 0;
  let lastIndex = 0;
  let match;
  while ((match = LINKIFY_RE.exec(str)) !== null) {
    if (match.index > lastIndex) parent.append(document.createTextNode(str.slice(lastIndex, match.index)));
    if (match[1] !== undefined) {
      // [label](url) — link ONLY if the url passes the scheme allowlist; otherwise emit the literal typed text.
      const safe = safeExternalUrl(match[2]);
      parent.append(safe ? buildExternalLinkAnchor(match[1], safe) : document.createTextNode(match[0]));
      lastIndex = match.index + match[0].length;
    } else {
      // bare url
      const trimmed = trimTrailingUrlPunctuation(match[3]);
      const safe = safeExternalUrl(trimmed);
      parent.append(safe ? buildExternalLinkAnchor(trimmed, safe) : document.createTextNode(trimmed));
      lastIndex = match.index + trimmed.length; // leave any trailing punctuation for the next text node
    }
    if (LINKIFY_RE.lastIndex <= match.index) LINKIFY_RE.lastIndex = match.index + match[0].length; // no zero-advance loop
  }
  if (lastIndex < str.length) parent.append(document.createTextNode(str.slice(lastIndex)));
}

// --- Safe message formatting renderer (v769) ---------------------------------------------------------------
// A lightweight, XSS-SAFE markdown subset for message/post/comment bodies. Built ENTIRELY via createElement +
// textContent (never innerHTML) — the same posture as appendLinkifiedText. Links go ONLY through
// buildExternalLinkAnchor (interstitial, NO live href): the Docs renderer's appendInlineMarkdown uses a LIVE
// href and MUST NOT be reused for messages (a live href leaks the reader's IP via middle-click / open-in-new-tab
// — the deanonymization vector buildExternalLinkAnchor exists to close). The composer's formatting toolbar
// inserts this markup; it rides inside the existing TEXT document block as raw UTF-8 (no wire change), so old
// clients that haven't updated simply show the literal markup (graceful degradation), never a broken message.
//
// Inline: **bold** -> <strong>, *italic* -> <em>, `code` -> <code>, [label](url) + bare urls -> safe anchor.
// Block (line-level): '# ' heading (1-3 -> small/smaller), '> ' blockquote, '- '/'* ' ul, '1. ' ol,
// and a '::center '/'::justify ' paragraph-leading alignment prefix (alignment is not standard markdown and is
// block-level, so it rides as a paragraph prefix parsed here; old clients show the literal prefix).
const INLINE_FORMAT_RE = /\*\*\*([^*\n]+)\*\*\*|\*\*([^*\n]+)\*\*|\*([^*\n]+)\*|`([^`\n]+)`|\[([^\]\n]{1,200})\]\(([^\s()]{1,2000})\)|(https?:\/\/[^\s<>"']+)/g;
const MSG_HEADING_RE = /^(#{1,3})\s+(.+)$/;
const MSG_QUOTE_RE = /^>\s?(.*)$/;
const MSG_ULIST_RE = /^[-*]\s+(.+)$/;
const MSG_OLIST_RE = /^\d+\.\s+(.+)$/;
const MSG_ALIGN_RE = /^::(center|justify)\s+([\s\S]*)$/;

function appendInlineFormatted(parent, text) {
  const str = String(text ?? '');
  if (!str) return;
  INLINE_FORMAT_RE.lastIndex = 0;
  let last = 0;
  let match;
  while ((match = INLINE_FORMAT_RE.exec(str)) !== null) {
    if (match.index > last) parent.append(document.createTextNode(str.slice(last, match.index)));
    let consumedEnd = match.index + match[0].length;
    if (match[1] !== undefined) {
      // ***bold+italic*** -> <strong><em>
      const strong = document.createElement('strong');
      const em = document.createElement('em');
      em.textContent = match[1];
      strong.append(em);
      parent.append(strong);
    } else if (match[2] !== undefined) {
      const el = document.createElement('strong');
      el.textContent = match[2];
      parent.append(el);
    } else if (match[3] !== undefined) {
      const el = document.createElement('em');
      el.textContent = match[3];
      parent.append(el);
    } else if (match[4] !== undefined) {
      const el = document.createElement('code');
      el.className = 'msg-code';
      el.textContent = match[4];
      parent.append(el);
    } else if (match[5] !== undefined) {
      // [label](url) — link ONLY if the url passes the scheme allowlist; else emit the literal typed text.
      const safe = safeExternalUrl(match[6]);
      parent.append(safe ? buildExternalLinkAnchor(match[5], safe) : document.createTextNode(match[0]));
    } else {
      // bare url (match[7]) — trim trailing punctuation like appendLinkifiedText does.
      const trimmed = trimTrailingUrlPunctuation(match[7]);
      const safe = safeExternalUrl(trimmed);
      parent.append(safe ? buildExternalLinkAnchor(trimmed, safe) : document.createTextNode(trimmed));
      consumedEnd = match.index + trimmed.length; // leave trailing punctuation for the next text node
    }
    last = consumedEnd;
    if (INLINE_FORMAT_RE.lastIndex <= match.index) INLINE_FORMAT_RE.lastIndex = match.index + match[0].length;
  }
  if (last < str.length) parent.append(document.createTextNode(str.slice(last)));
}

function messageTextHasBlockFormatting(text) {
  const str = String(text ?? '');
  if (!str.includes('\n') && !/^\s*(#{1,3}\s|>|[-*]\s|\d+\.\s|::(center|justify)\s)/.test(str)) {
    // Fast path: a single line with no leading block marker cannot carry block formatting.
    return false;
  }
  return str.split('\n').some((line) => (
    MSG_HEADING_RE.test(line) || MSG_QUOTE_RE.test(line) || MSG_ULIST_RE.test(line)
    || MSG_OLIST_RE.test(line) || MSG_ALIGN_RE.test(line)
  ));
}

// Render message body text with the safe formatting subset. Appends block/inline children to `container`.
// options.inlineOnly: skip block parsing (used for the shared-post embed snippet, which is a truncated excerpt
// and must stay a single inline run inside its <p>). When no block markers are present, the inline fast path
// keeps the common (unformatted) message structurally identical to the old appendLinkifiedText output.
function appendFormattedMessageText(container, text, options = {}) {
  const str = String(text ?? '');
  if (options.inlineOnly === true || !messageTextHasBlockFormatting(str)) {
    appendInlineFormatted(container, str);
    return;
  }
  const lines = str.split('\n');
  let index = 0;
  while (index < lines.length) {
    const line = lines[index];
    if (line.trim() === '') { index += 1; continue; }
    const headingMatch = MSG_HEADING_RE.exec(line);
    if (headingMatch) {
      const level = Math.min(headingMatch[1].length, 3);
      const heading = document.createElement('div');
      heading.className = `msg-block msg-heading msg-heading-${level}`;
      appendInlineFormatted(heading, headingMatch[2]);
      container.append(heading);
      index += 1;
      continue;
    }
    if (MSG_QUOTE_RE.test(line)) {
      const quoteLines = [];
      while (index < lines.length && MSG_QUOTE_RE.test(lines[index])) {
        quoteLines.push(lines[index].replace(MSG_QUOTE_RE, '$1'));
        index += 1;
      }
      const quote = document.createElement('blockquote');
      quote.className = 'msg-block msg-quote';
      appendInlineFormatted(quote, quoteLines.join('\n'));
      container.append(quote);
      continue;
    }
    if (MSG_ULIST_RE.test(line) || MSG_OLIST_RE.test(line)) {
      const ordered = MSG_OLIST_RE.test(line);
      const itemRe = ordered ? MSG_OLIST_RE : MSG_ULIST_RE;
      const list = document.createElement(ordered ? 'ol' : 'ul');
      list.className = 'msg-block msg-list';
      while (index < lines.length && itemRe.test(lines[index])) {
        const item = document.createElement('li');
        appendInlineFormatted(item, lines[index].replace(itemRe, '$1'));
        list.append(item);
        index += 1;
      }
      container.append(list);
      continue;
    }
    // Plain paragraph — its FIRST line may carry an alignment prefix (::center / ::justify) applied to the whole
    // paragraph. Collect consecutive non-block, non-blank lines.
    const paragraphLines = [];
    let align = null;
    while (index < lines.length) {
      const current = lines[index];
      if (current.trim() === '' || MSG_HEADING_RE.test(current) || MSG_QUOTE_RE.test(current)
        || MSG_ULIST_RE.test(current) || MSG_OLIST_RE.test(current)) break;
      let value = current;
      if (paragraphLines.length === 0) {
        const alignMatch = MSG_ALIGN_RE.exec(current);
        if (alignMatch) { align = alignMatch[1]; value = alignMatch[2]; }
      }
      paragraphLines.push(value);
      index += 1;
    }
    const paragraph = document.createElement('div');
    paragraph.className = `msg-block msg-p${align ? ` msg-align-${align}` : ''}`;
    appendInlineFormatted(paragraph, paragraphLines.join('\n'));
    container.append(paragraph);
  }
}

function buildExternalLinkAnchor(displayText, safeHref) {
  const anchor = document.createElement('a');
  anchor.className = 'msg-link';
  anchor.textContent = displayText; // the visible text (the literal URL, or a [text](url) label) — set via textContent
  // DELIBERATELY NO live href / target=_blank. A real href would let a MIDDLE-click (which fires 'auxclick', not
  // 'click') and the right-click "Open link in new tab" context item navigate DIRECTLY — bypassing the interstitial
  // and leaking the reader's IP to a per-recipient beacon URL (a deanonymization / read-receipt vector, the exact
  // thing this feature exists to prevent, and worse than a plain non-clickable URL). So the destination lives in a
  // dataset and EVERY activation path (left/middle click, Enter/Space) is forced through activateExternalLink →
  // the confirm. role=link + tabIndex keep it a real, keyboard-reachable link; the URL is the visible text, so it
  // is still selectable/copyable.
  anchor.dataset.externalUrl = safeHref;
  anchor.setAttribute('role', 'link');
  anchor.tabIndex = 0;
  const activate = (event) => {
    event.preventDefault();
    event.stopPropagation();
    activateExternalLink(safeHref, displayText);
  };
  anchor.addEventListener('click', activate);
  anchor.addEventListener('auxclick', activate); // middle-click (belt-and-suspenders; no href already means no nav)
  anchor.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' || event.key === ' ') activate(event);
  });
  return anchor;
}

function openExternalUrl(safeHref) {
  // Telegram embed: target=_blank is unreliable, route through the SDK. Plain web: a fresh noopener window.
  if (isTelegramEnv() && openExternalLinkInTelegram(safeHref)) return;
  window.open(safeHref, '_blank', 'noopener,noreferrer');
}

const EXTERNAL_LINK_TRUSTED_DOMAINS_KEY = 'platho.externalLink.trustedDomains.v1';
function readTrustedExternalDomains() {
  try {
    const parsed = JSON.parse(localStorageOrNull()?.getItem(scopedStorageKey(EXTERNAL_LINK_TRUSTED_DOMAINS_KEY)) ?? '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch { return []; }
}
function externalLinkDomainTrusted(host) {
  return Boolean(host) && readTrustedExternalDomains().includes(String(host).toLowerCase());
}
function trustExternalDomain(host) {
  if (!host) return;
  const set = new Set(readTrustedExternalDomains());
  set.add(String(host).toLowerCase());
  try {
    localStorageOrNull()?.setItem(scopedStorageKey(EXTERNAL_LINK_TRUSTED_DOMAINS_KEY), JSON.stringify([...set].slice(-300)));
  } catch { /* quota/unavailable: just re-prompt next time */ }
}

function activateExternalLink(safeHref, displayText) {
  let host = '';
  try { host = new URL(safeHref).hostname; } catch { host = ''; }
  if (externalLinkDomainTrusted(host)) { openExternalUrl(safeHref); return; }
  showExternalLinkConfirm(safeHref, host, displayText);
}

let activeExternalLinkModal = null;
function closeExternalLinkModal() {
  if (!activeExternalLinkModal) return;
  const { backdrop, onKeydown, previousFocus } = activeExternalLinkModal;
  document.removeEventListener('keydown', onKeydown, true);
  backdrop.remove();
  activeExternalLinkModal = null;
  try { previousFocus?.focus?.(); } catch { /* focus target detached */ }
}
function showExternalLinkConfirm(safeHref, host, displayText) {
  closeExternalLinkModal();
  const previousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const domainLabel = host || safeHref;
  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop external-link-backdrop';
  const card = document.createElement('section');
  card.className = 'action-dialog external-link-dialog';
  card.setAttribute('role', 'dialog');
  card.setAttribute('aria-modal', 'true');

  const title = document.createElement('h2');
  title.textContent = t('link.confirmTitle');
  const body = document.createElement('p');
  body.textContent = t('link.confirmBody', { domain: domainLabel });
  // ANTI-PHISHING: when the visible text is a LABEL that differs from the destination (a [text](url) link), show
  // "shown as: <label>" so a mismatch between what the reader clicked and where it actually goes is obvious.
  const isLabeled = typeof displayText === 'string' && displayText.length > 0 && displayText !== safeHref;
  let shownAs = null;
  if (isLabeled) {
    shownAs = document.createElement('p');
    shownAs.className = 'external-link-shownas';
    shownAs.textContent = t('link.shownAs', { text: displayText });
  }
  const urlPreview = document.createElement('p');
  urlPreview.className = 'external-link-url';
  urlPreview.textContent = safeHref; // the exact destination, textContent-only
  const ipWarn = document.createElement('p');
  ipWarn.className = 'external-link-ip-warning';
  ipWarn.textContent = t('link.ipWarning');

  const dontAskRow = document.createElement('label');
  dontAskRow.className = 'external-link-dontask';
  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  const dontAskText = document.createElement('span');
  dontAskText.textContent = t('link.dontAskAgain', { domain: domainLabel });
  dontAskRow.append(checkbox, dontAskText);

  const actions = document.createElement('div');
  actions.className = 'external-link-actions';
  const cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'secondary-button';
  cancelBtn.textContent = t('common.cancel');
  const openBtn = document.createElement('button');
  openBtn.type = 'button';
  openBtn.className = 'external-link-open';
  openBtn.textContent = t('link.open');
  actions.append(cancelBtn, openBtn);

  card.append(title, body, ...(shownAs ? [shownAs] : []), urlPreview, ipWarn, dontAskRow, actions);
  backdrop.append(card);
  document.body.append(backdrop);

  const confirmOpen = () => {
    if (checkbox.checked && host) trustExternalDomain(host);
    closeExternalLinkModal();
    openExternalUrl(safeHref);
  };
  cancelBtn.addEventListener('click', closeExternalLinkModal);
  openBtn.addEventListener('click', confirmOpen);
  // v794: X-only — no outside/backdrop tap and no Escape dismiss; the user must choose Cancel or Open.
  const onKeydown = (event) => {
    if (event.key === 'Enter' && document.activeElement === openBtn) { event.preventDefault(); confirmOpen(); }
  };
  document.addEventListener('keydown', onKeydown, true);
  activeExternalLinkModal = { backdrop, onKeydown, previousFocus };
  cancelBtn.focus();
}

// ── Composer "Insert link" dialog (v750) ───────────────────────────────────────────────────
// So people don't hand-craft [text](url) markup: a small dialog takes an optional link text + a URL and inserts
// the correctly-formatted markup at the composer caret. The URL is scheme-checked (safeExternalUrl) exactly like
// a rendered link, and any '(' / ')' in the URL is percent-encoded so it can't break the [text](url) parse.
let activeLinkComposerModal = null;
function closeLinkComposerModal() {
  if (!activeLinkComposerModal) return;
  const { backdrop, onKeydown, previousFocus } = activeLinkComposerModal;
  if (onKeydown) document.removeEventListener('keydown', onKeydown, true);
  backdrop.remove();
  activeLinkComposerModal = null;
  try { previousFocus?.focus?.(); } catch { /* detached */ }
}
function openLinkComposerDialog(targetInput, editChip = null) {
  if (!targetInput || targetInput.disabled) return;
  closeLinkComposerModal();
  // Capture the editor caret BEFORE the dialog steals focus, so the link lands where the user was typing (not at
  // the start). The editor DOM does not change while the dialog is open, so the cloned range stays valid.
  const savedRange = (() => {
    const sel = window.getSelection();
    if (sel && sel.rangeCount) { const r = sel.getRangeAt(0); if (targetInput.contains(r.commonAncestorContainer)) return r.cloneRange(); }
    return null;
  })();
  const previousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop link-composer-backdrop';
  const card = document.createElement('section');
  card.className = 'action-dialog link-composer-dialog';
  card.setAttribute('role', 'dialog');
  card.setAttribute('aria-modal', 'true');

  const title = document.createElement('h2');
  title.textContent = t(editChip ? 'composer.editLink' : 'composer.insertLink');
  const textInput = document.createElement('input');
  textInput.type = 'text';
  textInput.className = 'link-composer-input';
  textInput.placeholder = t('composer.linkText');
  textInput.setAttribute('aria-label', t('composer.linkText'));
  textInput.maxLength = 200;
  // Pre-fill: editing an existing chip fills BOTH fields from its [label](url) marker (decoding the %28/%29 we
  // encode on insert); otherwise a SELECTED word pre-fills the link text (and the link replaces the selection).
  let editUrl = '';
  let prefilledText = false;
  if (editChip) {
    const m = String(editChip.dataset.marker || '').match(/^\[([\s\S]*)\]\(([\s\S]*)\)$/);
    if (m) { textInput.value = m[1]; editUrl = m[2].replace(/%28/g, '(').replace(/%29/g, ')'); prefilledText = true; }
  } else {
    const selectedText = savedRange && !savedRange.collapsed ? savedRange.toString().replace(/[[\]\n]/g, ' ').trim().slice(0, 200) : '';
    if (selectedText) { textInput.value = selectedText; prefilledText = true; }
  }
  const urlInput = document.createElement('input');
  urlInput.type = 'url';
  urlInput.className = 'link-composer-input';
  urlInput.placeholder = t('composer.linkUrl');
  urlInput.setAttribute('aria-label', t('composer.linkUrl'));
  urlInput.inputMode = 'url';
  if (editUrl) urlInput.value = editUrl;
  const errorLine = document.createElement('p');
  errorLine.className = 'link-composer-error';
  errorLine.hidden = true;

  const actions = document.createElement('div');
  actions.className = 'external-link-actions';
  const cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'secondary-button';
  cancelBtn.textContent = t('common.cancel');
  const insertBtn = document.createElement('button');
  insertBtn.type = 'button';
  insertBtn.className = 'external-link-open';
  insertBtn.textContent = t('composer.insert');
  actions.append(cancelBtn, insertBtn);

  card.append(title, textInput, urlInput, errorLine, actions);
  backdrop.append(card);
  document.body.append(backdrop);

  const doInsert = () => {
    let raw = String(urlInput.value ?? '').trim();
    if (!raw) { errorLine.textContent = t('composer.linkUrlInvalid'); errorLine.hidden = false; urlInput.focus(); return; }
    if (!/^[a-z][a-z0-9+.-]*:/i.test(raw)) raw = `https://${raw}`; // a bare domain typed without a scheme -> assume https
    const safe = safeExternalUrl(raw);
    if (!safe) { errorLine.textContent = t('composer.linkUrlInvalid'); errorLine.hidden = false; urlInput.focus(); return; }
    const label = String(textInput.value ?? '').replace(/[[\]\n]/g, ' ').trim();
    const encodedUrl = safe.replace(/\(/g, '%28').replace(/\)/g, '%29'); // keep parens out of the [text](url) parse
    const display = label || safe;
    const markup = `[${display}](${encodedUrl})`; // always a labeled link so the editor can render it as a link chip
    closeLinkComposerModal();
    if (editChip) {
      // Editing an existing chip: replace it in place (do nothing if it was removed while the dialog was open).
      if (editChip.isConnected) {
        const newBlock = buildComposerLinkBlock(markup, display);
        editChip.replaceWith(newBlock);
        composerEditorPlaceCaretAfter(newBlock);
        composerEditorAfterEdit(targetInput);
      }
    } else {
      composerEditorInsertLinkBlock(targetInput, markup, display, savedRange); // renders as a link chip at the caret
    }
  };
  cancelBtn.addEventListener('click', closeLinkComposerModal);
  insertBtn.addEventListener('click', doInsert);
  urlInput.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); doInsert(); } });
  textInput.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); urlInput.focus(); } });
  // v794: X-only — no outside/backdrop tap and no Escape dismiss; the user must choose Cancel or Insert.
  activeLinkComposerModal = { backdrop, onKeydown: null, previousFocus };
  // If the link text is already filled (a selected word, or the chip being edited), jump straight to the URL field.
  (prefilledText ? urlInput : textInput).focus();
}

// A bare window.open of a t.me/ link is a no-op inside the Telegram in-app WebView,
// so route the @toncenter bot link through the SDK first and fall back to a new tab
// (normal browser / SDK missing).
function openToncenterBotLink() {
  if (openTelegramDeepLink('https://t.me/toncenter')) return;
  try { globalThis.open?.('https://t.me/toncenter', '_blank', 'noopener'); } catch { /* ignore */ }
}

// "Get" no longer dumps the user straight into the @toncenter bot. It opens an explanatory modal first
// (what an RPC key is for + the exact steps), and the bot link is the modal's primary action. Dismissing
// the modal (✕ / outside-click) does nothing; only the CTA opens the bot.
async function openRpcKeyHelpDialog() {
  const proceed = await openActionDialog({
    title: t('wallet.rpcKeyHelpTitle'),
    hint: t('wallet.rpcKeyHelpHint'),
    fields: [{
      type: 'note',
      steps: [
        t('wallet.rpcKeyHelpStep1'),
        t('wallet.rpcKeyHelpStep2'),
        t('wallet.rpcKeyHelpStep3'),
        t('wallet.rpcKeyHelpStep4'),
      ],
    }],
    submitLabel: t('wallet.rpcKeyHelpOpenBot'),
  });
  if (proceed) openToncenterBotLink();
}

function markTelegramRootAttribute() {
  try {
    if (isTelegramEnv()) document.documentElement.dataset.plathoTelegram = 'true';
  } catch {}
}

function initTelegramMiniApp() {
  const tg = telegramWebApp();
  if (!tg) return;
  try {
    tg.ready();
  } catch {}
  if (!isTelegramEnv()) return; // SDK present but launched in a normal browser
  markTelegramRootAttribute();
  try {
    tg.expand();
  } catch {}
  // Keep the app's own fixed dark brand theme; only match Telegram's chrome to it.
  const APP_BG = '#0b0d0f';
  try {
    if (telegramSupports('6.9')) tg.setHeaderColor(APP_BG);
    else tg.setHeaderColor('bg_color');
  } catch {}
  try {
    tg.setBackgroundColor(APP_BG);
  } catch {}
  try {
    if (telegramSupports('7.10') && typeof tg.setBottomBarColor === 'function') tg.setBottomBarColor(APP_BG);
  } catch {}
  try {
    if (telegramSupports('6.2')) tg.enableClosingConfirmation();
  } catch {}
  try {
    if (telegramSupports('7.7') && typeof tg.disableVerticalSwipes === 'function') tg.disableVerticalSwipes();
  } catch {}
  applyTelegramSafeArea();
  try {
    tg.onEvent('safeAreaChanged', applyTelegramSafeArea);
    tg.onEvent('contentSafeAreaChanged', applyTelegramSafeArea);
  } catch {}
  syncViewportCssVars();
  try {
    tg.onEvent('viewportChanged', syncViewportCssVars);
  } catch {}
  try {
    if (tg.BackButton && typeof tg.BackButton.onClick === 'function') {
      tg.BackButton.onClick(() => {
        try {
          requestNavBack();
        } catch {}
      });
    }
  } catch {}
}

// ---- Telegram durability: storage eviction is real on iOS WKWebView ---------
// localStorage (the only place the encrypted wallet key lives) can be evicted by
// the Telegram WebView between sessions. Two defenses: (1) force a confirmed
// 24-word backup right after generation, and (2) mirror the password-encrypted
// wallet record into Telegram CloudStorage (server-side, per-user) as a recovery
// channel. CloudStorage holds only ciphertext; without the user password it is
// useless, so this does not weaken the wallet.

const TELEGRAM_CLOUD_WALLET_KEY = 'platho_wallet_encrypted_v1';
const TELEGRAM_CLOUD_VALUE_MAX_BYTES = 4096;
const TELEGRAM_SEED_BACKUP_STORAGE_KEY = 'platho.wallet.telegram.seedbackup.v1';

function telegramCloudStorage() {
  const tg = telegramWebApp();
  return isTelegramEnv() && telegramSupports('6.9') && tg && tg.CloudStorage ? tg.CloudStorage : null;
}

function telegramCloudSet(key, value) {
  return new Promise((resolve) => {
    const cs = telegramCloudStorage();
    if (!cs || typeof cs.setItem !== 'function') {
      resolve(false);
      return;
    }
    try {
      cs.setItem(key, value, (error, ok) => resolve(!error && ok !== false));
    } catch {
      resolve(false);
    }
  });
}

function telegramCloudGet(key) {
  return new Promise((resolve) => {
    const cs = telegramCloudStorage();
    if (!cs || typeof cs.getItem !== 'function') {
      resolve(null);
      return;
    }
    try {
      cs.getItem(key, (error, value) => resolve(error ? null : (value || null)));
    } catch {
      resolve(null);
    }
  });
}

function telegramCloudGetKeys() {
  return new Promise((resolve) => {
    const cs = telegramCloudStorage();
    if (!cs || typeof cs.getKeys !== 'function') {
      resolve([]);
      return;
    }
    try {
      cs.getKeys((error, keys) => resolve(error || !Array.isArray(keys) ? [] : keys.map(String)));
    } catch {
      resolve([]);
    }
  });
}

function telegramCloudRemoveItems(keys) {
  return new Promise((resolve) => {
    const cs = telegramCloudStorage();
    if (keys.length === 0) {
      resolve(true);
      return;
    }
    if (!cs || typeof cs.removeItems !== 'function') {
      resolve(false);
      return;
    }
    try {
      cs.removeItems(keys, (error, ok) => resolve(!error && ok !== false));
    } catch {
      resolve(false);
    }
  });
}

// Wipe EVERY CloudStorage key this app ever wrote — ENUMERATED live (getKeys), not a hardcoded list, so a
// future cloud mirror cannot silently escape "Clear local data". Without this the Telegram Mini App
// resurrected the encrypted wallet from the cloud mirror on the very next boot (the owner's
// unlock-screen-right-after-clear report). Bounded by a timeout race: CloudStorage callbacks can hang on
// mobile Telegram (see the boot-restore race note), and the clear button must not wedge forever.
async function clearTelegramCloudAppData() {
  if (!telegramCloudStorage()) return true;
  const run = (async () => {
    const keys = await telegramCloudGetKeys();
    return telegramCloudRemoveItems(keys);
  })();
  const result = await Promise.race([run, delay(8_000).then(() => 'timeout')]);
  return result === true;
}

function mirrorWalletRecordToTelegramCloud(record) {
  if (!telegramCloudStorage() || !record || record.kind !== PLATHO_WALLET_STORAGE_KIND) return;
  let json = '';
  try {
    json = JSON.stringify(record);
  } catch {
    return;
  }
  // Telegram CloudStorage caps each value at 4096 bytes; the encrypted wallet
  // record (no message history) is well under that. Skip silently if it ever isn't.
  if (!json || json.length > TELEGRAM_CLOUD_VALUE_MAX_BYTES) return;
  telegramCloudSet(TELEGRAM_CLOUD_WALLET_KEY, json).catch(() => {});
}

async function restoreWalletRecordFromTelegramCloud() {
  if (!telegramCloudStorage()) return false;
  if (hasStoredPlathoWalletRecord()) return false; // a local copy always wins
  try {
    const json = await telegramCloudGet(TELEGRAM_CLOUD_WALLET_KEY);
    if (!json) return false;
    const record = JSON.parse(json);
    if (!record || record.kind !== PLATHO_WALLET_STORAGE_KIND) return false;
    const storage = localStorageOrNull();
    if (!storage) return false;
    storage.setItem(PLATHO_WALLET_STORAGE_KEY, JSON.stringify(record));
    return true;
  } catch {
    return false;
  }
}

function readTelegramSeedBackupSet() {
  try {
    const raw = localStorageOrNull()?.getItem(TELEGRAM_SEED_BACKUP_STORAGE_KEY);
    const list = raw ? JSON.parse(raw) : [];
    return Array.isArray(list) ? list.map(String) : [];
  } catch {
    return [];
  }
}

function isTelegramSeedBackupConfirmed(address) {
  if (!address) return false;
  return readTelegramSeedBackupSet().some((entry) => sameWalletAddress(entry, address));
}

function markTelegramSeedBackupConfirmed(address) {
  // Guard isTelegramEnv() so an ordinary-browser import never writes this key
  // (keeps non-Telegram localStorage byte-for-byte identical to before).
  if (!isTelegramEnv() || !address) return;
  try {
    const set = readTelegramSeedBackupSet();
    if (set.some((entry) => sameWalletAddress(entry, address))) return;
    set.push(String(address));
    localStorageOrNull()?.setItem(TELEGRAM_SEED_BACKUP_STORAGE_KEY, JSON.stringify(set.slice(-8)));
  } catch {}
}

// ---- Wallet-key backup safety net ------------------------------------------
// A newly-created wallet is stored on-device immediately, but exporting the encrypted KEY-FILE backup is a
// separate step. If the user is interrupted (screen off, reload, accidental close) before exporting it, the
// wallet can sit on the device with NO backup, and the quick-start would not re-appear (a wallet already
// exists). So we durably flag "this wallet's key was never exported" — mirrored to Telegram CloudStorage to
// survive iOS localStorage eviction — and keep re-surfacing the backup step until it is done. The flag is
// cleared on export; a wallet created by IMPORT is never flagged (the user already holds the seed / file).
const WALLET_KEY_BACKUP_PENDING_KEY = 'platho.wallet.keybackup.pending.v1';
const WALLET_KEY_BACKUP_PENDING_CLOUD_KEY = 'platho_wallet_keybackup_pending_v1';

function readWalletKeyBackupPendingSet() {
  try {
    const raw = localStorageOrNull()?.getItem(WALLET_KEY_BACKUP_PENDING_KEY);
    const list = raw ? JSON.parse(raw) : [];
    return Array.isArray(list) ? list.map(String) : [];
  } catch {
    return [];
  }
}

function writeWalletKeyBackupPendingSet(list) {
  const trimmed = Array.from(new Set(list.map(String))).slice(-8);
  try { localStorageOrNull()?.setItem(WALLET_KEY_BACKUP_PENDING_KEY, JSON.stringify(trimmed)); } catch { /* ignore */ }
  try { telegramCloudSet(WALLET_KEY_BACKUP_PENDING_CLOUD_KEY, JSON.stringify(trimmed)).catch(() => {}); } catch { /* ignore */ }
}

function isWalletKeyBackupPending(address) {
  if (!address) return false;
  return readWalletKeyBackupPendingSet().some((entry) => sameWalletAddress(entry, address));
}

function markWalletKeyBackupPending(address) {
  if (!address) return;
  const set = readWalletKeyBackupPendingSet();
  if (set.some((entry) => sameWalletAddress(entry, address))) return;
  set.push(String(address));
  writeWalletKeyBackupPendingSet(set);
  try { refreshWalletBackupWarning(); } catch { /* UI not ready */ }
}

function markWalletKeyBackupDone(address) {
  if (!address) return;
  const set = readWalletKeyBackupPendingSet();
  const next = set.filter((entry) => !sameWalletAddress(entry, address));
  if (next.length !== set.length) writeWalletKeyBackupPendingSet(next);
  try { refreshWalletBackupWarning(); } catch { /* UI not ready */ }
}

function walletKeyBackupPendingForStoredWallet() {
  if (!hasStoredPlathoWalletRecord()) return false;
  const record = readEncryptedPlathoWalletRecord();
  const address = record ? (storedWalletAddressForCopy(record) || record.address) : null;
  return Boolean(address && isWalletKeyBackupPending(address));
}

async function restoreWalletKeyBackupPendingFromTelegramCloud() {
  if (!telegramCloudStorage()) return;
  try {
    const json = await telegramCloudGet(WALLET_KEY_BACKUP_PENDING_CLOUD_KEY);
    if (!json) return;
    const cloud = JSON.parse(json);
    if (!Array.isArray(cloud)) return;
    // Union with local, erring toward "still pending": after iOS localStorage eviction the local set is
    // empty, so the cloud copy is what keeps the backup nudge alive until the key is actually exported.
    const merged = Array.from(new Set([...readWalletKeyBackupPendingSet(), ...cloud.map(String)]));
    writeWalletKeyBackupPendingSet(merged);
  } catch { /* ignore */ }
}

async function enforceTelegramSeedBackupGate(wallet, { force = false } = {}) {
  if (!isTelegramEnv() || !wallet) return;
  if (!force && isTelegramSeedBackupConfirmed(wallet.address)) return;
  let phrase = '';
  try {
    phrase = exportPlathoWalletRecoveryPhrase(wallet);
  } catch {
    return;
  }
  if (!phrase) return;
  // Hard gate: no ✕, no outside-click dismiss. The user must read the words and
  // type SAVED. If they keep declining we stop after a few tries and re-gate on the
  // next unlock (the flag is only set once they confirm). The fallback depends on
  // neither clipboard nor file download — the words are shown for manual transcription.
  for (let attempt = 0; attempt < 4; attempt += 1) {
    // eslint-disable-next-line no-await-in-loop
    const result = await openActionDialog({
      title: t('wallet.seedBackupTitle'),
      hint: t('wallet.seedBackupHint'),
      tone: 'error',
      cancellable: false,
      dismissOnBackdrop: false,
      submitLabel: t('wallet.seedBackupSubmit'),
      fields: [
        {
          id: 'recoveryPhrase',
          label: t('wallet.seedBackupPhraseLabel'),
          type: 'textarea',
          value: phrase,
          readOnly: true,
          required: false,
        },
        {
          id: 'seedBackupConfirm',
          name: 'confirmText',
          label: 'Type SAVED to confirm',
          type: 'text',
          placeholder: 'SAVED',
          autocomplete: 'off',
          autocapitalize: 'characters',
          spellcheck: false,
        },
      ],
      summary: [t('wallet.seedBackupSummary')],
    });
    if (String(result?.confirmText ?? '').trim().toUpperCase() === 'SAVED') {
      markTelegramSeedBackupConfirmed(wallet.address);
      return;
    }
  }
}

function showTelegramManualExportDialog(filename, content) {
  return openActionDialog({
    title: t('wallet.exportBackupTitle'),
    hint: t('wallet.exportBackupHint'),
    submitLabel: t('common.done'),
    fields: [{
      id: 'walletKeyBackup',
      label: filename,
      type: 'textarea',
      value: content,
      readOnly: true,
      required: false,
    }],
    summary: [t('wallet.exportBackupSummary')],
  }).catch(() => {});
}

// Mark the root as early as the module runs so the install-UI is hidden by CSS
// before first paint (the full bootstrap runs later, after handlers are wired).
markTelegramRootAttribute();

async function promptInstallApp() {
  const state = installActionState();
  if (state === 'installed') {
    closeInstallDialog({ dismissed: false });
    refreshInstallButtons();
    return;
  }
  if (state === 'instructions' || state === 'open-in-app' || state === 'ios-instructions') {
    if (installDialog?.hidden === false) {
      closeInstallDialog({ dismissed: false });
    } else if (installDialog) {
      installDialog.hidden = false;
    }
    refreshInstallButtons();
    return;
  }
  const promptEvent = deferredInstallPrompt;
  deferredInstallPrompt = null;
  closeInstallDialog({ dismissed: true });
  refreshInstallButtons();
  try {
    await promptEvent.prompt();
    await promptEvent.userChoice.catch(() => null);
  } finally {
    refreshInstallButtons();
  }
}

function installHelpText() {
  const ua = navigator.userAgent || '';
  if (/iPad|iPhone|iPod/.test(ua)) {
    return t('install.helpTextIos');
  }
  if (/Android/i.test(ua)) {
    return t('install.helpTextAndroid');
  }
  return t('install.helpTextDesktop');
}

async function refreshInstalledRelatedPwaState() {
  if (isStandaloneApp() || typeof navigator.getInstalledRelatedApps !== 'function') return;
  try {
    const installedApps = await navigator.getInstalledRelatedApps();
    installedRelatedPwaDetected = installedApps.some((app) => app?.platform === 'webapp');
    refreshInstallButtons();
  } catch {
    installedRelatedPwaDetected = false;
  }
}

function profileAvatarStorageKey(owner = plathoWallet?.address) {
  return owner ? `${PROFILE_AVATAR_POINTER_STORAGE_PREFIX}:${deploymentStorageSuffix()}:${owner}` : null;
}

function profileAvatarPublishRecoveryStorageKey(owner, avatarHash) {
  try {
    const normalizedOwner = requireBasechainAddress(owner, 'Avatar owner');
    return `${PROFILE_AVATAR_PUBLISH_RECOVERY_STORAGE_PREFIX}:${deploymentStorageSuffix()}:${normalizedOwner}:${normalizeAvatarHashHex(avatarHash).toLowerCase()}`;
  } catch {
    return null;
  }
}

function zeroAvatarHashHex() {
  return `0x${'00'.repeat(32)}`;
}

function normalizeAvatarHashHex(value) {
  const text = String(value ?? '').trim().toLowerCase();
  const hex = text.startsWith('0x') ? text.slice(2) : text;
  if (!/^[0-9a-f]{64}$/.test(hex)) throw new Error('Avatar hash must be uint256 hex');
  return `0x${hex}`;
}

function readStoredProfileAvatarPointer(owner = plathoWallet?.address) {
  const key = profileAvatarStorageKey(owner);
  if (!key) return null;
  try {
    const parsed = JSON.parse(localStorageOrNull()?.getItem(key) ?? 'null');
    if (!parsed || typeof parsed !== 'object') return null;
    const profileVersion = Number(parsed.profileVersion ?? parsed.profile_version ?? 0);
    const avatarHash = normalizeAvatarHashHex(parsed.avatarHash ?? parsed.avatar_hash ?? zeroAvatarHashHex());
    if (!Number.isSafeInteger(profileVersion) || profileVersion <= 0) return null;
    if (avatarHash === zeroAvatarHashHex()) return null;
    return { profileVersion, profile_version: profileVersion, avatarHash, avatar_hash: avatarHash };
  } catch {
    return null;
  }
}

function writeStoredProfileAvatarPointer(pointer, owner = plathoWallet?.address) {
  const key = profileAvatarStorageKey(owner);
  if (!key) return;
  const normalized = pointer ? {
    profileVersion: Number(pointer.profileVersion ?? pointer.profile_version ?? 0),
    avatarHash: normalizeAvatarHashHex(pointer.avatarHash ?? pointer.avatar_hash),
  } : null;
  if (!normalized || normalized.profileVersion <= 0) {
    localStorageOrNull()?.removeItem(key);
    localProfileAvatarPointer = null;
    return;
  }
  localStorageOrNull()?.setItem(key, JSON.stringify(normalized));
  localProfileAvatarPointer = {
    profileVersion: normalized.profileVersion,
    profile_version: normalized.profileVersion,
    avatarHash: normalized.avatarHash,
    avatar_hash: normalized.avatarHash,
  };
}

function currentProfileAvatarPointer() {
  localProfileAvatarPointer = localProfileAvatarPointer ?? readStoredProfileAvatarPointer();
  return localProfileAvatarPointer ?? {
    profileVersion: 0,
    profile_version: 0,
    avatarHash: zeroAvatarHashHex(),
    avatar_hash: zeroAvatarHashHex(),
  };
}

function currentProfilePointerFields() {
  const pointer = currentProfileAvatarPointer();
  return {
    profileVersion: pointer.profileVersion ?? 0,
    avatarHash: pointer.avatarHash ?? zeroAvatarHashHex(),
  };
}

function profileAvatarMediaHashKey(avatarHash) {
  try {
    const normalized = normalizeAvatarHashHex(avatarHash);
    if (normalized === zeroAvatarHashHex()) return null;
    return normalized;
  } catch {
    return null;
  }
}

function webpDataUrlToBytes(dataUrl) {
  const prefix = 'data:image/webp;base64,';
  if (typeof dataUrl !== 'string' || !dataUrl.startsWith(prefix)) return null;
  try {
    const binary = atob(dataUrl.slice(prefix.length));
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
    return bytes;
  } catch {
    return null;
  }
}

async function readProfileAvatarMediaCache(avatarHash) {
  const hash = profileAvatarMediaHashKey(avatarHash);
  if (!hash) return null;
  try {
    const store = await profileAvatarMediaStore();
    const url = (await store?.get(hash))?.url;
    if (typeof url !== 'string') return null;
    const bytes = webpDataUrlToBytes(url);
    if (!bytes) return null;
    const computedHash = await sha256Hex(bytes);
    if (computedHash.toLowerCase() !== hash.toLowerCase()) {
      await store?.delete(hash);
      return null;
    }
    return url;
  } catch {
    return null;
  }
}

async function writeProfileAvatarMediaCache(avatarHash, dataUrl) {
  const hash = profileAvatarMediaHashKey(avatarHash);
  if (!hash || typeof dataUrl !== 'string') return;
  try {
    const store = await profileAvatarMediaStore();
    await store?.put(hash, dataUrl);
  } catch {
    // Avatar media is reconstructable from chain; the local cache is best effort.
  }
}

// Warm the in-memory per-wallet public-avatar map from the IndexedDB media store BEFORE the first render, so a
// reloaded public feed shows faces immediately (no letter-tile placeholder + chain-refetch flash). The v504
// feed-cache media strip drops avatarImageUrl from the persisted feed, but avatarHash survives and the avatar
// bytes live in the media store. One batch read; no sha256 re-verify (the bytes were verified on write).
function collectCachedAvatarPointers(post, byWallet) {
  if (!post) return;
  const raw = rawWalletAddress(post.authorWallet ?? post.author_wallet);
  const hash = profileAvatarMediaHashKey(post.avatarHash ?? post.avatar_hash);
  if (raw && hash && !publicChannelAvatarUrlByWallet.has(raw) && !byWallet.has(raw)) byWallet.set(raw, hash);
  for (const comment of Array.isArray(post.comments) ? post.comments : []) collectCachedAvatarPointers(comment, byWallet);
}
// Synchronous read of a legacy localStorage avatar entry (pre-v512 format {hash,url,cachedAt}). Used as a
// first-boot fallback while the one-time IndexedDB migration has not yet run. Reads do NOT trigger the iOS
// whole-store re-serialization (only writes do), so this is safe.
function legacyAvatarMediaUrlFromLocalStorage(avatarHash) {
  const hash = profileAvatarMediaHashKey(avatarHash);
  if (!hash) return null;
  try {
    const parsed = JSON.parse(localStorageOrNull()?.getItem(`${PROFILE_AVATAR_MEDIA_CACHE_PREFIX}:${hash}`) ?? 'null');
    return parsed?.hash === hash && typeof parsed.url === 'string' ? parsed.url : null;
  } catch {
    return null;
  }
}
async function warmPublicChannelAvatarsFromCache() {
  try {
    const byWallet = new Map(); // raw wallet -> avatarHash, for authors not already in the in-memory map
    for (const record of Object.values(publicChannelFeedCache ?? {})) {
      // A cached channel record is { feed: { posts: [...] } } (sometimes the feed object directly, or just an
      // array). Extract the posts array robustly — iterating the wrong shape silently warmed NOTHING.
      const feed = record?.feed ?? record;
      const posts = Array.isArray(feed?.posts) ? feed.posts : (Array.isArray(feed) ? feed : []);
      for (const post of posts) collectCachedAvatarPointers(post, byWallet);
    }
    if (byWallet.size === 0) return;
    // 1) Legacy localStorage (pre-v512) — synchronous + instant, so the FIRST boot after the upgrade is clean
    //    before the deferred IndexedDB migration runs.
    const pending = new Map();
    for (const [raw, hash] of byWallet) {
      const url = legacyAvatarMediaUrlFromLocalStorage(hash);
      if (url) publicChannelAvatarUrlByWallet.set(raw, url);
      else pending.set(raw, hash);
    }
    // 2) IndexedDB — migrated + freshly-cached avatars.
    if (pending.size === 0) return;
    const store = await profileAvatarMediaStore();
    if (!store) return;
    const urls = await store.getMany([...pending.values()]);
    for (const [raw, hash] of pending) {
      const url = urls.get(hash);
      if (url && !publicChannelAvatarUrlByWallet.has(raw)) publicChannelAvatarUrlByWallet.set(raw, url);
    }
  } catch {
    // Best effort: a wallet whose avatar is not cached just hydrates from chain as before.
  }
}

// One-time migration of any avatars left in the OLD localStorage cache (platho.profile.avatar.media.v1:*) into
// IndexedDB, then delete them from localStorage — freeing the localStorage bloat the iOS freeze came from.
async function migrateLegacyAvatarMediaCacheToIndexedDb() {
  const ls = localStorageOrNull();
  if (!ls) return;
  let keys = [];
  try { keys = Object.keys(ls).filter((key) => key.startsWith(`${PROFILE_AVATAR_MEDIA_CACHE_PREFIX}:`)); } catch { return; }
  if (keys.length === 0) return;
  const store = await profileAvatarMediaStore().catch(() => null);
  for (const key of keys) {
    try {
      const parsed = JSON.parse(ls.getItem(key) ?? 'null');
      if (store && parsed?.hash && typeof parsed.url === 'string') await store.put(parsed.hash, parsed.url);
      ls.removeItem(key);
    } catch {
      // Skip a corrupt entry; it is reconstructable from chain.
    }
  }
}

function avatarPointerFromFields(profileVersion, avatarHash) {
  try {
    const version = Number(profileVersion ?? 0);
    const hash = normalizeAvatarHashHex(avatarHash ?? zeroAvatarHashHex());
    if (!Number.isSafeInteger(version) || version <= 0 || hash === zeroAvatarHashHex()) return null;
    return { profileVersion: version, profile_version: version, avatarHash: hash, avatar_hash: hash };
  } catch {
    return null;
  }
}

function avatarPointerFromPublicPayload(payload) {
  return avatarPointerFromFields(payload?.profileVersion ?? payload?.profile_version, payload?.avatarHash ?? payload?.avatar_hash);
}

function avatarHashHexFromBigInt(value) {
  return normalizeAvatarHashHex(`0x${BigInt(value ?? 0n).toString(16).padStart(64, '0')}`);
}

function streamIdHexFromBigInt(value) {
  return `0x${BigInt(value ?? 0n).toString(16).padStart(32, '0')}`;
}

function setAvatarNode(node, fallback, imageUrl = null) {
  if (!node) return;
  // Reused nodes may have been the Saved-thread icon on the previous render.
  node.classList.remove('avatar-saved');
  if (imageUrl) {
    node.textContent = '';
    node.classList.add('has-image');
    node.style.backgroundImage = `url("${imageUrl}")`;
    // Tap-to-view (v651): the delegated document click opens any image-bearing avatar in the fullscreen
    // lightbox — the url rides in the dataset so the handler needs no re-resolution. Avatars inside BUTTONS
    // (thread list rows etc.) are excluded there: their click keeps its own meaning.
    node.dataset.avatarUrl = imageUrl;
    return;
  }
  node.classList.remove('has-image');
  node.style.backgroundImage = '';
  delete node.dataset.avatarUrl;
  node.textContent = String(fallback ?? 'P').slice(0, 2).toUpperCase();
}

// Static markup only — never interpolate user data into this.
const SAVED_MESSAGES_AVATAR_SVG =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
  + '<path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg>';

// Thread avatars route through here so the Saved (My notes) thread gets its pencil icon instead of the
// wallet-letter fallback. The nodes are REUSED across threads (activeAvatar in the conversation header), so both
// branches fully undo the other's state.
function setThreadAvatarNode(node, thread) {
  if (!node) return;
  if (isSavedMessagesThread(thread)) {
    node.classList.remove('has-image');
    node.classList.add('avatar-saved');
    node.style.backgroundImage = '';
    delete node.dataset.avatarUrl;
    node.innerHTML = SAVED_MESSAGES_AVATAR_SVG;
    return;
  }
  node.classList.remove('avatar-saved');
  setAvatarNode(node, thread?.avatar, thread?.avatarImageUrl);
}

// Thread-list side label: today -> clock time, this week -> weekday, else a date (year only when it differs).
function formatThreadListTimestamp(ms) {
  if (!Number.isFinite(ms) || ms <= 0) return '';
  const date = new Date(ms);
  const now = new Date();
  const dayStart = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
  const dayDiff = Math.round((dayStart(now) - dayStart(date)) / 86_400_000);
  // The APP locale, not the browser one — otherwise weekday/month names contradict the chosen UI language.
  if (dayDiff <= 0) return date.toLocaleTimeString(currentLocale(), { hour: '2-digit', minute: '2-digit' });
  if (dayDiff < 7) return date.toLocaleDateString(currentLocale(), { weekday: 'short' });
  if (date.getFullYear() === now.getFullYear()) return date.toLocaleDateString(currentLocale(), { month: 'short', day: 'numeric' });
  return date.toLocaleDateString(currentLocale(), { year: 'numeric', month: 'short', day: 'numeric' });
}

function setText(node, value) {
  if (node) node.textContent = value ?? '';
}

function walletAddressForCopy(wallet = plathoWallet) {
  return wallet?.friendlyAddress ?? wallet?.address ?? '';
}

function currentWalletReceiveAddress() {
  return walletAddressForCopy(plathoWallet) || storedWalletAddressForCopy();
}

function walletTonTransferUri(address) {
  return `ton://transfer/${encodeURIComponent(address)}`;
}

function createWalletReceiveQrNode(address) {
  const wrapper = document.createElement('div');
  wrapper.className = 'wallet-receive-card';
  const image = document.createElement('img');
  image.className = 'wallet-receive-qr';
  image.alt = t('wallet.qrAlt');
  image.src = createQrSvgDataUrl(walletTonTransferUri(address), { title: t('wallet.qrTitle') });
  const addressBox = document.createElement('div');
  addressBox.className = 'wallet-receive-address';
  addressBox.textContent = address;
  wrapper.append(image, addressBox);
  return wrapper;
}

function storedPlathoWalletRecord() {
  return readEncryptedPlathoWalletRecord() ?? readLegacyPlaintextPlathoWalletRecord();
}

function storedWalletAddressForCopy(record = storedPlathoWalletRecord()) {
  if (!record?.address) return '';
  try {
    return formatTonUserFriendlyAddress(record.address, {
      testOnly: Number(record.networkGlobalId) === PLATHO_WALLET_NETWORK_GLOBAL_IDS.TESTNET,
    });
  } catch {
    return String(record.address);
  }
}

function walletDisplayIdentityStorageKey(owner = plathoWallet?.address) {
  return owner ? `${WALLET_DISPLAY_IDENTITY_STORAGE_PREFIX}:${owner}` : null;
}

// --- Per-counterparty display preference (shared by Private dialogs and Public wallet channels) ---
// The stored shape is { displayIdentity: <recipient identity or null>, localLabel: <string or null> },
// mirroring exactly the two fields a Private thread carries (thread.displayIdentity / thread.localLabel)
// so the "Display as" choice is identical in both tabs for the same wallet.
function contactDisplayPreferenceStorageKey(counterpartyWallet) {
  const raw = rawWalletAddress(counterpartyWallet);
  return raw ? `${CONTACT_DISPLAY_PREFERENCE_STORAGE_PREFIX}:${raw}` : null;
}

function normalizeContactDisplayPreference(value) {
  if (!value || typeof value !== 'object') return null;
  const displayIdentity = normalizeRecipientIdentity(value.displayIdentity) ?? null;
  const rawLabel = typeof value.localLabel === 'string' ? value.localLabel.trim() : '';
  const localLabel = rawLabel.length > 0 ? rawLabel : null;
  if (!displayIdentity && !localLabel) return null;
  return { displayIdentity, localLabel };
}

function readContactDisplayPreference(counterpartyWallet) {
  const key = contactDisplayPreferenceStorageKey(counterpartyWallet);
  if (!key) return null;
  try {
    return normalizeContactDisplayPreference(JSON.parse(localStorageOrNull()?.getItem(key) ?? 'null'));
  } catch {
    return null;
  }
}

function writeContactDisplayPreference(counterpartyWallet, preference) {
  const key = contactDisplayPreferenceStorageKey(counterpartyWallet);
  if (!key) return;
  // NEVER store a "Display as" preference for your OWN wallet. The own channel / self ("My notes") thread derives
  // its name from your own linked .ath, not a per-counterparty entry (resolveWalletChannelDisplay returns early for
  // the own wallet). A stray own-wallet entry — e.g. leaked by a cross-wallet thread merge — would bleed a peer's
  // name/avatar onto your own "You" channel. Refuse it at this single chokepoint AND clear any that already leaked in
  // (self-heal for devices already poisoned before this fix).
  const own = plathoWallet?.address ?? storedPlathoWalletRecord()?.address ?? null;
  if (own && sameWalletAddress(counterpartyWallet, own)) {
    try { localStorageOrNull()?.removeItem(key); } catch { /* cosmetic self-heal; ignore */ }
    return;
  }
  const normalized = normalizeContactDisplayPreference(preference);
  try {
    if (!normalized) {
      localStorageOrNull()?.removeItem(key);
    } else {
      localStorageOrNull()?.setItem(key, JSON.stringify({
        displayIdentity: normalized.displayIdentity,
        localLabel: normalized.localLabel,
      }));
    }
  } catch {
    // The cross-tab display preference is cosmetic; a failed write just means no sync this time.
  }
}

// Resolve how a counterparty wallet should be shown (name + identity tone) from the shared store.
// Returns null when the user has not chosen anything for this wallet (callers then keep the default
// short-address presentation).
function resolveContactDisplay(counterpartyWallet) {
  const stored = readContactDisplayPreference(counterpartyWallet);
  if (!stored) return null;
  if (stored.displayIdentity) {
    return {
      name: displayIdentityLabel(stored.displayIdentity),
      tone: identityTone(stored.displayIdentity),
      identity: stored.displayIdentity,
      localLabel: stored.localLabel ?? null,
    };
  }
  if (stored.localLabel) {
    return { name: stored.localLabel, tone: null, identity: null, localLabel: stored.localLabel };
  }
  return null;
}

// How a Public wallet channel should be shown: an explicit shared-store choice wins; otherwise mirror
// the matching Private dialog's CURRENT display (so a chat started via an .ath name shows that name in
// Public too, even with no explicit choice). Returns null to keep the default short-address name.
function resolveWalletChannelDisplay(counterpartyWallet) {
  // Own wallet FIRST: the user's own public channel (feed author name + channels list + their own posts) shows
  // their OWN .ath / profile NFT choice — parity with the Profile header. Known locally (readLinkedPlathoUsername,
  // verified at mint) so no chain read. Resolved via the address persisted in storage so it works before the full
  // wallet finishes loading, and BEFORE the per-counterparty store so a stray self-entry (only writable via the
  // old pre-wallet-load flash, now fixed) can't pin your own channel to the bare wallet address.
  const ownAddress = plathoWallet?.address ?? storedPlathoWalletRecord()?.address ?? null;
  if (ownAddress && sameWalletAddress(counterpartyWallet, ownAddress)) {
    const ownLabel = readLinkedPlathoUsername(ownAddress)?.label;
    const ownIdentity = ownLabel ? plathoUsernameIdentity(ownLabel) : null;
    // Your OWN channel shows YOUR OWN .ath (or the bare address when you have none) — and NOTHING else. RETURN here
    // unconditionally: never fall through to the per-counterparty store or the private-thread fallback below for your
    // own wallet, or a stray entry / a mis-merged thread could pin a peer's name+avatar onto your "You" channel. This
    // matters most on a brand-new wallet, which has no linked .ath to short-circuit on.
    return ownIdentity
      ? { name: displayIdentityLabel(ownIdentity), tone: identityTone(ownIdentity), identity: ownIdentity, localLabel: null }
      : null;
  }
  const explicit = resolveContactDisplay(counterpartyWallet);
  if (explicit) return explicit;
  const thread = findThreadByIdentityVariants(threads, privateWalletIdentityVariants(counterpartyWallet));
  if (thread) {
    const threadIdentity = threadSelectedIdentity(thread);
    // A private thread that only knows the BARE wallet address (no username, no local name) must NOT pin the
    // channel to that address when a chain-VERIFIED .ath exists below — the username is primary everywhere the
    // user has not chosen otherwise (owner rule). A thread that DOES carry a username or a local name still wins
    // (it reflects how the user already sees that person in Private).
    const threadIsBareAddress = !thread.localLabel
      && (!threadIdentity || threadIdentity.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS);
    if (!threadIsBareAddress) {
      const name = threadDisplayLabel(thread);
      if (name) {
        return {
          name,
          tone: threadDisplayTone(thread),
          identity: threadIdentity,
          localLabel: thread.localLabel ?? null,
        };
      }
    }
  }
  // No explicit choice and no username-bearing private thread → the channel's chain-VERIFIED .ath (proven owner
  // of the linked NFT, never the raw ownerUsername claim) is the DEFAULT. This is the SAME source the "Display as"
  // chevron already offers (contactDisplayContextForWallet injects it), so the default name a subscribed channel
  // shows now MATCHES the menu instead of defaulting to the bare address the user then has to override by hand.
  const verifiedUsername = publicChannelProfileCache[channelProfileCacheKey(counterpartyWallet)]?.verifiedUsername;
  if (verifiedUsername) {
    let identity = null;
    try { identity = plathoUsernameIdentity(verifiedUsername); } catch { identity = null; }
    if (identity) {
      return { name: displayIdentityLabel(identity), tone: identityTone(identity), identity, localLabel: null };
    }
  }
  return null;
}

function linkedPlathoUsernameStorageKey(owner = plathoWallet?.address) {
  return owner ? `${LINKED_PLATHO_USERNAME_STORAGE_PREFIX}:${deploymentStorageSuffix()}:${owner}` : null;
}

function privateSenderModeStorageKey(owner = plathoWallet?.address) {
  return owner ? `${PRIVATE_SENDER_MODE_STORAGE_PREFIX}:${owner}` : null;
}

function normalizeWalletDisplayMode(value) {
  return Object.values(WALLET_DISPLAY_MODES).includes(value) ? value : WALLET_DISPLAY_MODES.ADDRESS;
}

function normalizePrivateSenderMode(value) {
  return Object.values(PRIVATE_SENDER_MODES).includes(value) ? value : PRIVATE_SENDER_MODES.SHARE;
}

function privateSenderModeLabel(value) {
  return normalizePrivateSenderMode(value) === PRIVATE_SENDER_MODES.ANONYMOUS ? t('chat.senderModeAnonymous') : t('chat.senderModeShare');
}

function normalizeWalletDisplayIdentity(input) {
  const mode = normalizeWalletDisplayMode(input?.mode);
  if (mode === WALLET_DISPLAY_MODES.ADDRESS) {
    return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
  }
  if (mode === WALLET_DISPLAY_MODES.PLATHO_NFT) {
    try {
      return {
        mode,
        label: `${normalizeUsernameInput(input?.label ?? input?.value ?? '')}.ath`,
        verified_at: Number.isSafeInteger(Number(input?.verified_at)) ? Number(input.verified_at) : 0,
      };
    } catch {
      return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
    }
  }
  return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
}

function sameWalletAddress(left, right) {
  try {
    return parseTonAddress(left).raw === parseTonAddress(right).raw;
  } catch {
    return false;
  }
}

function rawWalletAddress(address) {
  try {
    return parseTonAddress(address).raw;
  } catch {
    return null;
  }
}

function walletAddressChanged(previousWallet, nextWallet) {
  if (!previousWallet?.address || !nextWallet?.address) return false;
  return !sameWalletAddress(previousWallet.address, nextWallet.address);
}

function activeWalletRuntimeAddress() {
  return activeRuntimeWalletAddress ?? plathoWallet?.address ?? null;
}

function walletScopedRuntimeChanged(nextWallet) {
  const currentAddress = activeWalletRuntimeAddress();
  if (!currentAddress || !nextWallet?.address) return false;
  return !sameWalletAddress(currentAddress, nextWallet.address);
}

function prepareWalletScopedRuntimeForWallet(wallet, reason = 'wallet replaced') {
  if (walletScopedRuntimeChanged(wallet)) {
    clearWalletScopedRuntimeState(reason);
  }
  if (wallet?.address) activeRuntimeWalletAddress = wallet.address;
}

function clearWalletScopedRuntimeState(reason = 'wallet changed') {
  for (const job of privateSendRetryJobs.values()) {
    if (job?.timer) window.clearTimeout(job.timer);
  }
  privateSendRetryJobs.clear();
  privateSendRetrySeq = 0;
  for (const job of privatePublishConfirmJobs.values()) {
    if (job?.timer) window.clearTimeout(job.timer);
  }
  privatePublishConfirmJobs.clear();
  privatePublishConfirmSeq = 0;
  for (const job of publicPublishConfirmJobs.values()) {
    if (job?.timer) window.clearTimeout(job.timer);
  }
  publicPublishConfirmJobs.clear();
  publicPostCommentsCache.clear();
  // Public-feed sync cursors are per-account context (the walk reads THIS account's subscriptions + window). Reset
  // the in-memory heads / truncation / comment cursors + the last-synced gate so the next account re-walks fresh
  // instead of inheriting this account's cursors (which would skip the re-walk and could show a stale feed/hint).
  publicAuthorIndexHeads.clear();
  publicAuthorIndexTruncated.clear();
  publicParentIndexHeads.clear();
  publicAuthorRoundCursor = 0;
  publicAuthorRoundCovered.clear();
  publicAuthorRoundStartHead = null;
  publicFeedShownCap = PUBLIC_FEED_RENDER_CAP;
  invalidatePublicSyncFastPath(); // epoch bump: an in-flight walk of the OLD account must not re-commit the cursor
  lastSyncedPublicSyncWindow = null;
  activeRuntimeWalletAddress = null;
  clearMessageAutoSyncTimer();
  clearMessageAutoSyncCountdownTimer();
  // Also cancel any pending rail Vault-balance retry so a teardown (lock / account switch) doesn't leave a get_user
  // firing later and racing the next boot's reads (one of the concurrent-connection sources on iOS WebKit).
  clearNavVaultBalanceRetryTimer();
  privateChainSyncPromise = null;
  messageAutoSyncAt = 0;
  messageAutoSyncPhase = 'idle';
  messageAutoSyncLastResult = null;
  messageAutoSyncLastErrorLabel = null;
  threads = [];
  activeThreadId = null;
  if (appShell) appShell.dataset.chatOpen = 'false';
  localIdentity = null;
  localVaultAuthKeyPair = null;
  localRecipientKeyPair = null;
  localSignedPublicBundle = null;
  localVaultDraft = null;
  // Stop the INTRO scan and drop its per-wallet K_root state — a different wallet must never inherit these (bleed).
  stopIntroReceiveLane();
  cancelAllConvDeliveryConfirms();   // drop pending delivery-confirm timers so none fires against a torn-down transport
  convKeyStore = null;
  introReplayGuard = null;
  convRecoveryRestoreAttempted = false;   // a new wallet must restore its OWN conversations from recovery
  convRecoveryBackupAllowed = false;      // block backups until the new wallet's restore proves the local map is complete
  if (recoveryBackupTimer) { clearTimeout(recoveryBackupTimer); recoveryBackupTimer = null; }
  // NOTE: convRecoveryDirtySlots deliberately survives — backups deferred by a background-lock are re-armed on unlock
  // (a stale slot from a switched-away wallet self-clears: the new wallet's partition for it is empty, so it is skipped).
  localReplayStore = createMemoryReplayStore();
  encryptedMessageStore = null;
  knownVaultKeyOwnerBySignPubkey.clear();
  knownVaultKeyRecordByWallet.clear();
  // The own-raw fallback cache is wallet-scoped: it exists to survive a TRANSIENT background lock (same account),
  // and must die with the account on a switch so the previous owner's address can never leak into the next
  // account's routing guards (clearWalletScopedRuntimeState runs ONLY on a wallet change, never on a mere lock).
  lastKnownOwnWalletRaw = null;
  // A vault-move button lock is scoped to the wallet that started the move — drop it on a wallet change so the NEW
  // wallet's deposit/withdraw button never inherits a spinner for a move it never made (else it stays locked until
  // the old 30s timeout). Sibling to plathoAccountActivationPending, which queueVaultRefreshAfterWalletChange clears.
  vaultMoveProcessing.TON = null;
  vaultMoveProcessing.ATH = null;
  // Supersede any in-flight prefs background confirm so it can't stamp "saved"/"not saved" onto the NEW wallet's
  // subscription state (prefs are per-wallet). The bump makes the stranded confirm bail on its generation guard, but
  // that same guard means it will NOT release the in-flight UI it was holding — so release it HERE, or a wallet switch
  // mid-confirm would leave the Save button disabled and the global sync spinner stuck forever.
  prefsConfirmGeneration += 1;
  prefsSyncInFlight = false;
  // The monotonic-activation guard is per-wallet: forget the previous wallet's activated state so the NEW wallet's
  // first not-activated read is honoured (never masked by the old wallet's cache). Drop the external-balance retry
  // for the same reason (it was chasing the old wallet's balance).
  lastKnownActivatedVaultWalletRaw = null;
  clearWalletTonProfileBalanceRetry();
  // Drop the previous wallet's cached pocket balances so the NEW wallet never inherits them — neither the vault
  // pocket nor (with the v739 carry-forward) a failed external read may surface wallet A's funds under wallet B. The
  // new wallet's own reads repopulate this; until then the UI shows unknown ("-"/pending), which is correct.
  vaultPocketState = { wallet: { ton_balance: null, ath_balance: null }, vault: { ton_balance: null, ath_balance: null } };
  privateImageAttachments = [];
  privatePaymentCheckDraft = null;
  privateFileAttachments = [];
  setPrivateReplyDraft(null);
  setPublicCommentReplyTo(null);
  setPrivateShareDraft(null);
  setPublicShareDraft(null);
  localProfileAvatarPointer = null;
  profileAvatarLoadPromises.clear();
  delete globalThis.plathoVaultBinding;
  delete globalThis.plathoLastEncryptedHistoryRestore;
  globalThis.plathoLastWalletScopedRuntimeReset = {
    reason,
    at: new Date().toISOString(),
  };
  updateImageAttachmentUi('private');
  refreshComposerCostStatus();
  renderThreads();
  renderConversation();
}

function displayWalletAddress(address) {
  try {
    return formatTonUserFriendlyAddress(address, { bounceable: false, testOnly: false });
  } catch {
    return String(address ?? '');
  }
}

// Canonical display name for a username: the bare name, WITHOUT the ".ath" suffix (the suffix lives in the stored
// identity label for routing/matching, but is never shown).
function canonicalUsernameDisplay(label) {
  return String(label ?? '').replace(/\.ath$/i, '');
}

function displayIdentityLabel(identity) {
  if (!identity) return '';
  if (identity.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) {
    return shortAddress(identity.value ?? identity.label);
  }
  // PLATHO_NFT (and any future name type) is shown canonically — never with the ".ath" suffix.
  return canonicalUsernameDisplay(identity.label ?? identity.value ?? '');
}

async function verifyWalletDisplayIdentity(mode, label, wallet = plathoWallet) {
  const normalizedMode = normalizeWalletDisplayMode(mode);
  if (normalizedMode === WALLET_DISPLAY_MODES.ADDRESS) {
    return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
  }
  const owner = requireBasechainAddress(wallet?.address, 'Connected wallet');
  if (normalizedMode === WALLET_DISPLAY_MODES.PLATHO_NFT) {
    const identity = await resolvePlathoUsernameOwner(label);
    if (!sameWalletAddress(identity.ownerWallet, owner)) throw new Error(`${identity.label} belongs to another wallet`);
    return { mode: normalizedMode, label: identity.label, verified_at: Date.now() };
  }
  return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
}

function readWalletDisplayIdentity(owner = plathoWallet?.address) {
  const key = walletDisplayIdentityStorageKey(owner);
  if (!key) return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
  try {
    return normalizeWalletDisplayIdentity(JSON.parse(localStorageOrNull()?.getItem(key) ?? 'null'));
  } catch {
    return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
  }
}

function readPrivateSenderMode(owner = plathoWallet?.address) {
  const key = privateSenderModeStorageKey(owner);
  if (!key) return PRIVATE_SENDER_MODES.SHARE;
  try {
    return normalizePrivateSenderMode(localStorageOrNull()?.getItem(key));
  } catch {
    return PRIVATE_SENDER_MODES.SHARE;
  }
}

function writePrivateSenderMode(value, owner = plathoWallet?.address) {
  const key = privateSenderModeStorageKey(owner);
  if (!key) return PRIVATE_SENDER_MODES.SHARE;
  const normalized = normalizePrivateSenderMode(value);
  try {
    if (normalized === PRIVATE_SENDER_MODES.SHARE) {
      localStorageOrNull()?.removeItem(key);
    } else {
      localStorageOrNull()?.setItem(key, normalized);
    }
  } catch {
    // Privacy preference is local-only; failed persistence should not block send.
  }
  return normalized;
}

function currentPrivateSenderMode() {
  return readPrivateSenderMode(plathoWallet?.address);
}

function currentPrivateSenderOptions() {
  // Saved (v652): anonymity to YOURSELF is meaningless and would make a self note render as INCOMING — the
  // self detection reads payload.senderWallet, which the anonymous mode strips. Self sends always carry it.
  const savedThread = isSavedMessagesThread(activeThread());
  const includeSenderWalletMetadata = savedThread || currentPrivateSenderMode() !== PRIVATE_SENDER_MODES.ANONYMOUS;
  const linkedUsername = includeSenderWalletMetadata ? readLinkedPlathoUsername(plathoWallet?.address) : null;
  return {
    includeSenderWalletMetadata,
    senderUsername: linkedUsername?.label ?? undefined,
  };
}

// The eye follows the full send-block state (owner: an inactive composer must not show live-looking
// buttons) — wallet/thread/read-only/activation/update/reserve reasons all come from the ONE send predicate,
// so this button dims exactly when the Send button does — plus its own extra rule: notes to yourself are
// never anonymous (v652). `sendBlock` is passed in (the callers already computed it) so this adds no extra
// send-plan build on the hot refresh paths.
function privateSenderModeToggleBlockReason(sendBlock) {
  if (sendBlock) return sendBlock;
  if (isSavedMessagesThread(activeThread())) return t('chat.blockSavedAnonymous');
  return null;
}

function canTogglePrivateSenderMode() {
  return privateSenderModeToggleBlockReason(privateSendBlockReason()) === null;
}

function updatePrivateSenderModeUi(sendBlockReason = privateSendBlockReason()) {
  const mode = currentPrivateSenderMode();
  const anonymous = mode === PRIVATE_SENDER_MODES.ANONYMOUS;
  if (privateSenderModeSelect) {
    privateSenderModeSelect.value = mode;
    privateSenderModeSelect.disabled = !plathoWallet;
  }
  if (privateAnonymousButton) {
    const icon = privateAnonymousButton.querySelector('.icon');
    const blockReason = privateSenderModeToggleBlockReason(sendBlockReason);
    privateAnonymousButton.disabled = Boolean(blockReason);
    privateAnonymousButton.setAttribute('aria-pressed', anonymous ? 'true' : 'false');
    privateAnonymousButton.setAttribute(
      'aria-label',
      anonymous ? t('chat.shareWalletAddress') : t('chat.sendPseudonymously'),
    );
    privateAnonymousButton.title = blockReason ?? (anonymous
      ? t('chat.anonymousOnTooltip')
      : t('chat.anonymousOffTooltip'));
    if (icon) {
      icon.classList.toggle('icon-eye', !anonymous);
      icon.classList.toggle('icon-eye-off', anonymous);
    }
  }
}

function normalizeLinkedPlathoUsername(input) {
  try {
    return {
      mode: WALLET_DISPLAY_MODES.PLATHO_NFT,
      label: `${normalizeUsernameInput(input?.label ?? input?.value ?? input ?? '')}.ath`,
      verified_at: Number.isSafeInteger(Number(input?.verified_at)) ? Number(input.verified_at) : 0,
    };
  } catch {
    return null;
  }
}

function readLinkedPlathoUsername(owner = plathoWallet?.address) {
  const key = linkedPlathoUsernameStorageKey(owner);
  if (key) {
    try {
      const linked = normalizeLinkedPlathoUsername(JSON.parse(localStorageOrNull()?.getItem(key) ?? 'null'));
      if (linked) return linked;
    } catch {
      // A malformed local display alias should not break wallet rendering.
    }
  }
  const legacy = readWalletDisplayIdentity(owner);
  return legacy.mode === WALLET_DISPLAY_MODES.PLATHO_NFT ? normalizeLinkedPlathoUsername(legacy) : null;
}

function writeLinkedPlathoUsername(identity, owner = plathoWallet?.address) {
  const key = linkedPlathoUsernameStorageKey(owner);
  const normalized = normalizeLinkedPlathoUsername(identity);
  if (!key || !normalized) return;
  try {
    localStorageOrNull()?.setItem(key, JSON.stringify(normalized));
  } catch {
    // Local display attachment is cosmetic and can be re-linked.
  }
}

// Drop the local linked-.ath alias entirely so outgoing messages carry NO username (used when the reconcile below
// finds the name was transferred away and there is no other owned name to fall back to). Clears BOTH the linked key
// AND the legacy wallet-display fallback (readLinkedPlathoUsername reads the linked key, then falls back to the
// display identity) — ADDRESS mode removes that key too.
function clearLinkedPlathoUsername(owner = plathoWallet?.address) {
  const key = linkedPlathoUsernameStorageKey(owner);
  try { if (key) localStorageOrNull()?.removeItem(key); } catch { /* cosmetic; still works without it */ }
  writeWalletDisplayIdentity({ mode: WALLET_DISPLAY_MODES.ADDRESS }, owner);
}

function knownPlathoUsernamesStorageKey(owner = plathoWallet?.address) {
  return owner ? `${KNOWN_PLATHO_USERNAMES_STORAGE_PREFIX}:${deploymentStorageSuffix()}:${owner}` : null;
}

// The .ath names this profile is already known to own — the ones the user has successfully linked or minted on
// this device. Offered as quick-picks in the "Link Platho name" dialog so a multi-username owner doesn't retype.
// Always unions the currently-linked name. A picked name is still re-verified on submit (it could have been
// transferred away since it was last seen).
function readKnownPlathoUsernames(owner = plathoWallet?.address) {
  const names = new Set();
  const linked = readLinkedPlathoUsername(owner)?.label;
  if (linked) names.add(linked);
  const key = knownPlathoUsernamesStorageKey(owner);
  if (key) {
    try {
      const stored = JSON.parse(localStorageOrNull()?.getItem(key) ?? '[]');
      if (Array.isArray(stored)) {
        for (const label of stored) if (typeof label === 'string' && label.trim()) names.add(label.trim());
      }
    } catch {
      // A malformed local quick-pick list must not break the link dialog.
    }
  }
  return [...names];
}

function addKnownPlathoUsername(label, owner = plathoWallet?.address) {
  const normalized = typeof label === 'string' ? label.trim() : '';
  const key = knownPlathoUsernamesStorageKey(owner);
  if (!normalized || !key) return;
  const next = [normalized, ...readKnownPlathoUsernames(owner).filter((entry) => entry !== normalized)].slice(0, 24);
  try {
    localStorageOrNull()?.setItem(key, JSON.stringify(next));
  } catch {
    // Cosmetic quick-pick list; safe to drop on a storage failure.
  }
}

function writeWalletDisplayIdentity(identity, owner = plathoWallet?.address) {
  const key = walletDisplayIdentityStorageKey(owner);
  if (!key) return;
  const normalized = normalizeWalletDisplayIdentity(identity);
  try {
    if (normalized.mode === WALLET_DISPLAY_MODES.ADDRESS) {
      localStorageOrNull()?.removeItem(key);
    } else {
      localStorageOrNull()?.setItem(key, JSON.stringify(normalized));
    }
  } catch {
    // Display preference is cosmetic; the wallet itself still works.
  }
}

function walletDisplayName(wallet = plathoWallet) {
  const identity = readWalletDisplayIdentity(wallet?.address);
  if (identity.mode === WALLET_DISPLAY_MODES.PLATHO_NFT) {
    return canonicalUsernameDisplay(readLinkedPlathoUsername(wallet?.address)?.label) || shortAddress(walletAddressForCopy(wallet));
  }
  return shortAddress(walletAddressForCopy(wallet));
}

function walletDisplaySubtitle(wallet = plathoWallet) {
  const identity = readWalletDisplayIdentity(wallet?.address);
  if (identity.mode === WALLET_DISPLAY_MODES.PLATHO_NFT && readLinkedPlathoUsername(wallet?.address)) return t('wallet.plathoName');
  return t('wallet.ready');
}

function renderWalletIdentity(status = null) {
  try { refreshWalletBackupWarning(); } catch { /* UI not ready */ }
  if (!plathoWallet) {
    const storedRecord = storedPlathoWalletRecord();
    const hasStored = Boolean(storedRecord);
    const storedAddress = storedWalletAddressForCopy(storedRecord);
    const storedLabel = storedAddress ? shortAddress(storedAddress) : storedWalletShortLabel();
    setText(identityName, hasStored ? storedLabel : t('wallet.noWallet'));
    setText(identitySubtitle, status ?? (hasStored ? t('wallet.unlockLocal') : t('wallet.createOrImport')));
    setText(walletAddressStatus, hasStored ? storedLabel : t('wallet.notCreated'));
    setText(walletDisplayModeStatus, t('wallet.addressMode'));
    setText(linkedUsernameStatus, t('wallet.verify'));
    if (walletDisplayModeSelect) walletDisplayModeSelect.value = WALLET_DISPLAY_MODES.ADDRESS;
    if (copyWalletAddressButton) copyWalletAddressButton.disabled = !storedAddress;
    return;
  }
  const identity = readWalletDisplayIdentity(plathoWallet.address);
  const linkedUsername = readLinkedPlathoUsername(plathoWallet.address);
  setText(identityName, walletDisplayName(plathoWallet));
  setText(identitySubtitle, status ?? walletDisplaySubtitle(plathoWallet));
  setText(walletAddressStatus, shortAddress(walletAddressForCopy(plathoWallet)));
  setText(walletDisplayModeStatus, identity.mode === WALLET_DISPLAY_MODES.PLATHO_NFT
    ? canonicalUsernameDisplay(linkedUsername?.label) || t('wallet.optional')
    : t('wallet.addressMode'));
  setText(linkedUsernameStatus, canonicalUsernameDisplay(linkedUsername?.label) || t('wallet.optional'));
  if (walletDisplayModeSelect) walletDisplayModeSelect.value = identity.mode;
  if (copyWalletAddressButton) copyWalletAddressButton.disabled = false;
}

function setProfileActionStatus(node, text, state = '') {
  if (!node) return;
  setText(node, text);
  if (state) {
    node.dataset.state = state;
  } else {
    delete node.dataset.state;
  }
}

function setProfileAvatarPending(pending) {
  const next = Boolean(pending);
  if (plathoProfileAvatarPending === next) return;
  plathoProfileAvatarPending = next;
  refreshMessagingControls();
}

function setProfileAvatarStatus(text, state = 'busy') {
  // Any terminal outcome releases the in-flight lock so the "Set avatar" button becomes clickable
  // again: an error tone, the success tone (''), or an "avatar active"/"active, ..." status. All
  // in-flight statuses (busy/default tone) keep the lock held.
  if (state === 'error' || state === '' || /^(avatar active|active,)/.test(String(text ?? ''))) {
    setProfileAvatarPending(false);
  }
  setProfileActionStatus(setAvatarStatus, text, state);
}

// Greppable, stable-English console marker that brackets an avatar set. An avatar rides the SHARED VPB2
// '[platho] send timeline' for its image capsules (Stage 1) and adds a SECOND Vault->ProfileRegistry
// pointer-registration message (Stage 2) that a normal image send never has — which is why the console reads
// differently. These phase markers let avatar activity be told apart from a plain image send without touching
// the shared publish path. phase is a fixed English token; the localized UI status stays on setProfileAvatarStatus.
function logAvatarTimeline(phase, detail = {}) {
  console.info('[platho] avatar timeline', { phase, ...detail, at: new Date().toISOString() });
}

function setUsernameMintStatus(text, state = 'busy') {
  setProfileActionStatus(mintUsernameStatus, text, state);
}

function flashWalletIdentityStatus(status, durationMs = 1400) {
  if (walletIdentityFlashTimer) {
    clearTimeout(walletIdentityFlashTimer);
    walletIdentityFlashTimer = null;
  }
  renderWalletIdentity(status);
  walletIdentityFlashTimer = setTimeout(() => {
    walletIdentityFlashTimer = null;
    if (identitySubtitle?.textContent === status) renderWalletIdentity();
  }, durationMs);
}

function clearWalletAutoLockTimer() {
  if (walletAutoLockTimer) {
    clearTimeout(walletAutoLockTimer);
    walletAutoLockTimer = null;
  }
}

function clearWalletUnlockPromptTimer() {
  if (walletUnlockPromptTimer) {
    clearTimeout(walletUnlockPromptTimer);
    walletUnlockPromptTimer = null;
  }
}

function scheduleWalletAutoLock() {
  clearWalletAutoLockTimer();
  if (!plathoWallet) return;
  walletAutoLockTimer = setTimeout(() => {
    lockPlathoWallet(t('wallet.locked'));
  }, WALLET_AUTO_LOCK_MS);
}

function noteWalletActivity() {
  if (plathoWallet) scheduleWalletAutoLock();
}

function markWalletUnlocked() {
  lastWalletUnlockAt = Date.now();
  walletUnlockPromptPending = false;
  clearWalletUnlockPromptTimer();
  clearTelegramBackgroundLockTimer();
}

function shouldIgnoreTransientWalletLock() {
  return Boolean(activeActionDialog)
    || (Date.now() - lastWalletUnlockAt) < 8000
    // Don't tear down an in-flight send on a brief background: defer the lock while signing/broadcasting
    // actively holds the key (bounded by SEND_LOCK_MAX_GRACE_MS). Confirmation is keyless and not counted.
    || shouldDeferLockForActiveSend();
}

function shouldDeferServiceWorkerReload() {
  return Boolean(plathoWallet) || Boolean(walletUnlockPromise) || shouldIgnoreTransientWalletLock();
}

function serviceWorkerUpdateReloadError() {
  return new Error('App update ready. Reload before sending.');
}

function requireNoPendingServiceWorkerAppShellReload() {
  if (!pendingServiceWorkerAppShellReload) return;
  flashWalletIdentityStatus(t('wallet.updateReadyReload'));
  throw serviceWorkerUpdateReloadError();
}

function reloadForPendingServiceWorkerAppShellUpdate() {
  if (!pendingServiceWorkerAppShellReload) return false;
  window.location.reload();
  return true;
}

function schedulePendingServiceWorkerAppShellReload(delayMs = 250) {
  if (!pendingServiceWorkerAppShellReload) return false;
  setTimeout(() => reloadForPendingServiceWorkerAppShellUpdate(), delayMs);
  return true;
}

async function liveAppRuntimeVersion() {
  try {
    const response = await fetch(`./?platho_version_check=${Date.now()}`, {
      cache: 'no-store',
      credentials: 'same-origin',
    });
    if (!response.ok) return null;
    const html = await response.text();
    const match = html.match(/id="appVersionLabel">v(\d+)<\/span>/);
    return match ? `v${match[1]}` : null;
  } catch {
    return null;
  }
}

async function handleServiceWorkerControllerChange() {
  const liveVersion = await liveAppRuntimeVersion();
  if (!liveVersion || liveVersion === PLATHO_APP_RUNTIME_VERSION) {
    pendingServiceWorkerAppShellReload = false;
    refreshMessagingControls();
    return;
  }
  if (shouldDeferServiceWorkerReload()) {
    pendingServiceWorkerAppShellReload = true;
    flashWalletIdentityStatus(t('wallet.updateReadyReload'));
    refreshMessagingControls();
    return;
  }
  window.location.reload();
}

function lockPlathoWallet(status = t('wallet.locked'), options = {}) {
  if (!plathoWallet) {
    reloadForPendingServiceWorkerAppShellUpdate();
    return;
  }
  if (options.transient === true && shouldIgnoreTransientWalletLock()) {
    scheduleWalletAutoLock();
    return;
  }
  clearWalletAutoLockTimer();
  clearTelegramBackgroundLockTimer();
  clearVaultAutoRefreshTimer();
  pauseProfileAvatarPublishRecoveryTimers();
  plathoWallet = null;
  localIdentity = null;
  localVaultAuthKeyPair = null;
  localRecipientKeyPair = null;
  localSignedPublicBundle = null;
  localVaultDraft = null;
  localProfileAvatarPointer = null;
  stopIntroReceiveLane();
  cancelAllConvDeliveryConfirms();   // drop pending delivery-confirm timers so none fires against a torn-down transport
  convKeyStore = null;
  introReplayGuard = null;
  convRecoveryRestoreAttempted = false;   // a new wallet must restore its OWN conversations from recovery
  convRecoveryBackupAllowed = false;      // block backups until the new wallet's restore proves the local map is complete
  if (recoveryBackupTimer) { clearTimeout(recoveryBackupTimer); recoveryBackupTimer = null; }
  // NOTE: convRecoveryDirtySlots deliberately survives — backups deferred by a background-lock are re-armed on unlock
  // (a stale slot from a switched-away wallet self-clears: the new wallet's partition for it is empty, so it is skipped).
  delete globalThis.plathoVaultBinding;
  resetVaultPocketState();
  renderWalletIdentity();
  flashWalletIdentityStatus(status);
  setText(encryptionStatus, t('wallet.unlockRequired'));
  setText(keyAuthStatus, t('common.locked'));
  setText(vaultDraftStatus, t('common.locked'));
  setText(vaultRecordStatus, t('common.locked'));
  setMessageSyncStatus(t('common.locked'), 'locked');
  setText(vaultRotateStatus, t('common.locked'));
  refreshMessagingControls();
  refreshComposerPublishPolicy();
  armWalletUnlockPrompt();
  reloadForPendingServiceWorkerAppShellUpdate();
}

const TELEGRAM_BACKGROUND_LOCK_GRACE_MS = 300_000;
let telegramBackgroundLockTimer = null;

function clearTelegramBackgroundLockTimer() {
  if (telegramBackgroundLockTimer) {
    clearTimeout(telegramBackgroundLockTimer);
    telegramBackgroundLockTimer = null;
  }
}

function scheduleTelegramBackgroundLock() {
  clearTelegramBackgroundLockTimer();
  telegramBackgroundLockTimer = setTimeout(() => {
    telegramBackgroundLockTimer = null;
    // Lock only if still backgrounded; the hard idle auto-lock still applies.
    if (!document.hidden || !plathoWallet) return;
    if (shouldDeferLockForActiveSend()) {
      // A send still holds the key — don't drop the background lock, re-arm and recheck.
      // Bounded by SEND_LOCK_MAX_GRACE_MS on the send side, so this cannot loop forever.
      scheduleTelegramBackgroundLock();
      return;
    }
    lockPlathoWallet(t('wallet.locked'));
  }, TELEGRAM_BACKGROUND_LOCK_GRACE_MS);
}

function lockPlathoWalletForBackground() {
  // Telegram (Desktop/Android) backgrounds the WebView on the smallest interaction
  // (opening its own UI, the attachment sheet, switching chats). Hard-locking on every
  // such transition makes the wallet unusable, so defer to a short background-grace
  // timer there — the page keeps running, so the timer fires and locks if still hidden.
  // iOS suspends the WebView (timers freeze), so it keeps the immediate lock-on-suspend
  // below; resume after suspend is keyless by design. closing-confirmation guards true close.
  if (isTelegramEnv() && !isTelegramSuspendingPlatform() && plathoWallet && !shouldIgnoreTransientWalletLock()) {
    scheduleTelegramBackgroundLock();
    return;
  }
  lockPlathoWallet(t('wallet.locked'), { transient: true });
}

function shouldOpenWalletUnlockPrompt() {
  return Boolean(walletUnlockPromptPending)
    && !document.hidden
    && !plathoWallet
    && !walletUnlockPromise
    && !activeActionDialog
    && hasStoredPlathoWalletRecord();
}

function scheduleWalletUnlockPrompt(delayMs = 180) {
  clearWalletUnlockPromptTimer();
  if (!shouldOpenWalletUnlockPrompt()) return;
  // Re-unlock on resume (after a background auto-lock): re-show the branded overlay NOW (synchronously, before
  // paint) so the unlock dialog opens on it — not on the bare, locked-but-visible app. No-op on cold boot
  // (overlay already up) — see showBootScreenForRelock. The core-ready lift hides it after unlock.
  showBootScreenForRelock();
  walletUnlockPromptTimer = setTimeout(async () => {
    walletUnlockPromptTimer = null;
    if (!shouldOpenWalletUnlockPrompt()) return;
    walletUnlockPromptPending = false;
    try {
      const wallet = await loadPlathoWallet();
      if (!wallet) {
        // Unlock declined/cancelled — reveal the app in its locked state (public feed still works).
        markBootAppReady();
        renderWalletIdentity();
        refreshMessagingControls();
        return;
      }
      await bootCrypto();
      // Re-gate the seed backup on the AUTO unlock path too (resume / foreground /
      // startup), not just the explicit unlock button — otherwise a user who once
      // declined the gate could keep using funds with no durable backup.
      await enforceTelegramSeedBackupGate(wallet);
      flashWalletIdentityStatus(t('wallet.unlocked'));
    } catch (error) {
      // Never strand the re-unlock behind the overlay on an error.
      markBootAppReady();
      console.error(error);
      renderWalletIdentity();
      refreshMessagingControls();
    }
  }, delayMs);
}

function armWalletUnlockPrompt() {
  if (plathoWallet || !hasStoredPlathoWalletRecord()) return;
  walletUnlockPromptPending = true;
  scheduleWalletUnlockPrompt();
}

function suppressProfileAvatarPicker(durationMs = 1000) {
  profileAvatarPickerSuppressedUntil = Math.max(profileAvatarPickerSuppressedUntil, Date.now() + durationMs);
}

function isProfileAvatarPickerSuppressed() {
  return Date.now() < profileAvatarPickerSuppressedUntil;
}

async function copyTextToClipboard(text) {
  const value = String(text ?? '');
  if (!value) throw new Error('Nothing to copy');
  if (navigator.clipboard?.writeText && window.isSecureContext) {
    await navigator.clipboard.writeText(value);
    return;
  }
  const area = document.createElement('textarea');
  area.value = value;
  area.setAttribute('readonly', '');
  area.style.position = 'fixed';
  area.style.left = '-9999px';
  area.style.top = '0';
  document.body.append(area);
  area.select();
  try {
    if (!document.execCommand('copy')) throw new Error('Clipboard copy blocked');
  } finally {
    area.remove();
  }
}

function renderPaneHeaders() {
  setText(chatCountLabel, t('nav.privateChats'));
  setText(publicSubtitle, t('nav.publicChannels'));
  setText(vaultSubtitle, t('nav.vault'));
  setText(profileHandle, t('nav.profile'));
}

// Pane status lines are logged only when they CHANGE: renderPublicSurface re-runs several times per background
// tick (feed sync + post-avatar + channel-avatar hydration each trigger a re-render), so logging every call
// spammed the console with identical '[public] feed' packs and buried the [platho] diagnostics that matter.
let lastLoggedPublicStatus = null;
function setPublicStatus(value) {
  if (!value || value === lastLoggedPublicStatus) return;
  lastLoggedPublicStatus = value;
  console.debug('[public]', value);
}

let lastLoggedVaultStatus = null;
function setVaultStatus(value) {
  if (!value || value === lastLoggedVaultStatus) return;
  lastLoggedVaultStatus = value;
  console.debug('[vault]', value);
}

function appendIcon(parent, icon) {
  const span = document.createElement('span');
  span.className = `icon icon-${icon}`;
  parent.append(span);
}

function threadSelectedIdentity(thread) {
  const displayIdentity = primaryThreadIdentity({ displayIdentity: thread?.displayIdentity });
  if (displayIdentity) return displayIdentity;
  if (thread?.localLabel) return null;
  return primaryThreadIdentity(thread);
}

function threadDisplayLabel(thread) {
  const identity = threadSelectedIdentity(thread);
  if (identity) return displayIdentityLabel(identity);
  if (thread?.localLabel) return thread.localLabel;
  // Fallback to a stored name — strip a stray ".ath" so a thread.name that was persisted with the suffix still
  // shows canonically.
  return canonicalUsernameDisplay(thread?.name ?? '');
}

function threadDisplayTone(thread) {
  const identity = threadSelectedIdentity(thread);
  return identity ? identityTone(identity) : null;
}

function routeIdentitySubtitle(thread) {
  const identity = primaryThreadIdentity(thread);
  if (!identity) return thread?.subtitle ?? '';
  const label = displayIdentityLabel(identity);
  return label ? t('chat.identityTypeWithLabel', { type: identityTypeLabel(identity), label }) : identityTypeLabel(identity);
}

function applyThreadDisplayFields(thread) {
  if (!thread) return thread;
  const label = threadDisplayLabel(thread);
  const identity = threadSelectedIdentity(thread);
  if (label) {
    thread.name = label;
    thread.avatar = String(label || 'P').slice(0, 1).toUpperCase() || thread.avatar || 'P';
  }
  thread.subtitle = identity ? identityTypeLabel(identity) : routeIdentitySubtitle(thread);
  return thread;
}

function persistThreadDisplayPreference(thread) {
  if (!thread?.messages?.length) return;
  Promise.all((thread.messages ?? [])
    .filter((message) => message?.localHistoryId)
    .map((message) => updateMessageInEncryptedHistory(thread, message)))
    .catch((error) => console.error(error));
}

// Mirror a Private thread's "Display as" choice into the shared per-counterparty store so the same
// person's Public wallet channel shows the same name. Cheap: writes localStorage and re-overlays the
// public registry names (no render — the Public surface re-resolves names from the registry on its
// next paint / sync).
function syncThreadDisplayToContactStore(thread) {
  const wallet = ownerWalletFromThread(thread);
  if (!wallet) return;
  writeContactDisplayPreference(wallet, {
    displayIdentity: thread.displayIdentity ?? null,
    localLabel: thread.localLabel ?? null,
  });
  rebuildPublicChannelRegistry();
}

// Apply a display choice that originated in the Public tab back to the shared store AND to any live
// Private thread for the same wallet, then refresh both surfaces. This is the Public -> Private half
// of the sync (the Private -> Public half is syncThreadDisplayToContactStore above).
function applyContactDisplaySelection(counterpartyWallet, { displayIdentity = null, localLabel = null } = {}) {
  writeContactDisplayPreference(counterpartyWallet, { displayIdentity, localLabel });
  const thread = findThreadByIdentityVariants(threads, privateWalletIdentityVariants(counterpartyWallet));
  if (thread) {
    thread.displayIdentity = displayIdentity ?? null;
    if (localLabel) thread.localLabel = localLabel;
    else delete thread.localLabel;
    applyThreadDisplayFields(thread);
    persistThreadDisplayPreference(thread);
  }
  // rebuildThreadsFromPublicSubscriptions re-overlays the registry itself, so no separate rebuild here.
  rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
  renderThreads();
  renderConversation();
  renderPublicSurface({ anchorUnread: false });
  // A choice made from a Discovery card's chevron (an unsubscribed channel not in the feed) must relabel that
  // card too. renderPublicSurface only rebuilds the feed; this debounced+guarded refresh re-renders the discovery
  // sample (no-op when discovery isn't on screen), so buildDiscoveryCard re-reads resolveWalletChannelDisplay.
  scheduleDiscoveryLabelRefresh();
}

// Build a thread-shaped object for a wallet that has NO open Private dialog, so the Public "Display as"
// menu can reuse the exact same option-builder (identityDisplayOptions) the Private menu uses. When a
// real Private thread exists, callers pass that instead and full parity (incl. a known .ath username)
// is automatic.
function contactDisplayContextForWallet(counterpartyWallet) {
  const base = baseContactDisplayContextForWallet(counterpartyWallet);
  const extraIdentities = [];
  // The user's OWN wallet channel must offer their OWN linked username (.ath) as a "Display as" option, the
  // same way a counterparty's channel offers theirs. A counterparty's username arrives via their received
  // posts (senderUsername); your own never does (you don't receive your own posts), so without this the own
  // channel only ever shows the wallet address while everyone else sees your username. Add it explicitly.
  if (plathoWallet?.address && sameWalletAddress(counterpartyWallet, plathoWallet.address)) {
    const ownUsername = readLinkedPlathoUsername(plathoWallet.address);
    const ownIdentity = ownUsername?.label ? plathoUsernameIdentity(ownUsername.label) : null;
    if (ownIdentity) extraIdentities.push(ownIdentity);
  }
  // A public channel's VERIFIED .ath username (chain-proven owner of the LINKED NFT — never the raw ownerUsername
  // claim) is offered as a "Display as" option too. This is what surfaces e.g. "glasnost" in the Discovery card's
  // chevron for a wallet you have no Private dialog with: contactDisplayContextForWallet only ever knew the raw
  // address there, so the menu would otherwise list address + local name only.
  const verifiedUsername = publicChannelProfileCache[channelProfileCacheKey(counterpartyWallet)]?.verifiedUsername;
  if (verifiedUsername) {
    let channelIdentity = null;
    try { channelIdentity = plathoUsernameIdentity(verifiedUsername); } catch { channelIdentity = null; }
    if (channelIdentity) extraIdentities.push(channelIdentity);
  }
  if (extraIdentities.length) {
    // Non-mutating: return a shallow context whose variants include the extra identities (base may be a live
    // thread object; don't graft the variant onto it as a side effect of opening a popover). uniqueDisplayIdentityVariants
    // de-dupes downstream, so an own username that also matches the channel's verified name collapses to one row.
    return { ...base, identityVariants: normalizeIdentityVariants([...extraIdentities, ...threadIdentityVariants(base)]) };
  }
  return base;
}

function baseContactDisplayContextForWallet(counterpartyWallet) {
  const existing = findThreadByIdentityVariants(threads, privateWalletIdentityVariants(counterpartyWallet));
  if (existing) return existing;
  const created = createRecipientThread(counterpartyWallet);
  const base = created.ok
    ? created.thread
    : { id: `wallet:${rawWalletAddress(counterpartyWallet) ?? counterpartyWallet}`, identityVariants: privateWalletIdentityVariants(counterpartyWallet) };
  const stored = readContactDisplayPreference(counterpartyWallet);
  if (stored?.displayIdentity) {
    base.identityVariants = normalizeIdentityVariants([stored.displayIdentity, ...threadIdentityVariants(base)]);
    base.displayIdentity = stored.displayIdentity;
  }
  if (stored?.localLabel) base.localLabel = stored.localLabel;
  return base;
}

// Pull a Private thread's display fields into line with the shared per-counterparty store. This is the
// load-time half of the Public <-> Private sync: a choice made in Public for a wallet whose dialog was
// not loaded at the time lands on the thread when it next materializes. If the store has nothing yet
// but the thread already carries a preference (a user who chose a name before this feature shipped), the
// thread seeds the store so the choice propagates to Public. Returns true when the thread changed.
//
// Runs ONCE per thread object (thread.contactDisplaySynced, a runtime-only flag not persisted in the
// thread snapshot). One-time is correct AND necessary: after the first sync every live edit updates the
// thread directly (Private via the popover callback, Public via applyContactDisplaySelection), so the
// store never gets ahead of a loaded thread. Re-running it on every renderThreads would (a) revert a
// just-made choice when the render happens before the store write, and (b) hammer localStorage on every
// keystroke-triggered render (slow-device path).
function hydrateThreadDisplayFromContactStore(thread) {
  if (!thread || thread.contactDisplaySynced) return false;
  const wallet = ownerWalletFromThread(thread);
  if (!wallet) return false; // no wallet yet (unresolved peer): retry once it resolves
  // The self/Saved ("My notes") thread must NEVER pull a display from the per-counterparty store: its label is always
  // "My notes" and its name derives from your own linked .ath. Reading a (possibly leaked) own-wallet entry here
  // would re-latch a peer's identity onto the Saved thread every session — so short-circuit for the own wallet.
  const own = plathoWallet?.address ?? storedPlathoWalletRecord()?.address ?? null;
  if (own && sameWalletAddress(wallet, own)) { thread.contactDisplaySynced = true; return false; }
  thread.contactDisplaySynced = true;
  const stored = readContactDisplayPreference(wallet);
  if (!stored) {
    if (thread.displayIdentity || thread.localLabel) {
      writeContactDisplayPreference(wallet, {
        displayIdentity: thread.displayIdentity ?? null,
        localLabel: thread.localLabel ?? null,
      });
    }
    return false;
  }
  const sameIdentity = identityKey(stored.displayIdentity) === identityKey(thread.displayIdentity ?? null);
  const sameLabel = (stored.localLabel ?? null) === (thread.localLabel ?? null);
  if (sameIdentity && sameLabel) return false;
  thread.displayIdentity = stored.displayIdentity ?? null;
  if (stored.localLabel) thread.localLabel = stored.localLabel;
  else delete thread.localLabel;
  applyThreadDisplayFields(thread);
  return true;
}

function setIdentityLabel(node, thread, baseClass = 'identity-label') {
  const tone = threadDisplayTone(thread);
  // Saved display name is RENDER-ONLY (threadDisplayLabel feeds the contact store + the own public channel name).
  node.textContent = isSavedMessagesThread(thread) ? t('chat.myNotes') : threadDisplayLabel(thread);
  node.className = `${baseClass}${tone ? ` identity-label-${tone}` : ''}`;
}

function identityVariantRow(option, selected, onSelect) {
  const row = document.createElement('button');
  row.type = 'button';
  row.className = `identity-variant${option.identity ? ` identity-label-${identityTone(option.identity)}` : ''}`;
  row.setAttribute('role', 'menuitemradio');
  row.setAttribute('aria-checked', selected ? 'true' : 'false');
  const label = document.createElement('strong');
  label.textContent = option.label;
  const type = document.createElement('span');
  type.textContent = selected ? t('chat.subtitleSelected', { subtitle: option.subtitle }) : option.subtitle;
  row.append(label, type);
  row.addEventListener('click', () => onSelect(option));
  return row;
}

function identityDisplayKey(identity) {
  if (!identity) return null;
  if (identity.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) {
    const raw = rawWalletAddress(identity.value);
    if (raw) return `${identity.type}:${raw}`;
  }
  return identityKey(identity);
}

function uniqueDisplayIdentityVariants(thread) {
  const out = [];
  const seen = new Set();
  for (const identity of threadIdentityVariants(thread)) {
    const key = identityDisplayKey(identity);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(identity);
  }
  return out;
}

function identityDisplayOptions(thread) {
  const options = [];
  if (thread?.localLabel) {
    options.push({
      key: 'local-label',
      label: thread.localLabel,
      subtitle: t('chat.localName'),
      identity: null,
    });
  }
  const variantOptions = [];
  for (const identity of uniqueDisplayIdentityVariants(thread)) {
    const key = identityDisplayKey(identity);
    if (!key) continue;
    variantOptions.push({
      key,
      label: displayIdentityLabel(identity),
      subtitle: identityTypeLabel(identity),
      identity,
    });
  }
  // Order: name identities (Platho NFT / TON DNS) first, alphabetically, then the raw wallet address last — so the
  // human-readable handles group together above the address. (The local name, if any, stays first; the "Set local
  // name" action is placed at the top of the popover separately.)
  variantOptions.sort((a, b) => {
    const aWallet = a.identity?.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS ? 1 : 0;
    const bWallet = b.identity?.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS ? 1 : 0;
    if (aWallet !== bWallet) return aWallet - bWallet;
    return String(a.label ?? '').localeCompare(String(b.label ?? ''));
  });
  options.push(...variantOptions);
  return options;
}

function selectedIdentityDisplayOptionKey(thread) {
  const selected = threadSelectedIdentity(thread);
  if (selected) return identityDisplayKey(selected);
  return thread?.localLabel ? 'local-label' : null;
}

function ensureIdentityPopover() {
  if (identityPopover) return identityPopover;
  identityPopover = document.createElement('div');
  identityPopover.className = 'identity-popover';
  identityPopover.hidden = true;
  document.body.append(identityPopover);
  return identityPopover;
}

// Place a (visible) identity popover next to its anchor using its REAL measured size, not a hardcoded guess. The old
// code clamped top against a magic 220px height, so a taller box still overflowed the bottom (description cut off) and
// low anchors snapped to a fixed line ("appears haphazardly"). The popover height is bounded by the CSS max-height, so
// this always lands the WHOLE box on-screen: below the anchor when it fits, else above it, else clamped to the top.
function positionIdentityPopover(popover, anchor) {
  if (!popover || popover.hidden || !anchor) return;
  const rect = anchor.getBoundingClientRect();
  const margin = 8;
  const w = popover.offsetWidth;
  const h = popover.offsetHeight;
  const left = Math.max(margin, Math.min(rect.left, window.innerWidth - w - margin));
  let top = rect.bottom + margin;
  if (top + h > window.innerHeight - margin) {
    const above = rect.top - margin - h;
    top = above >= margin ? above : Math.max(margin, window.innerHeight - h - margin);
  }
  popover.style.left = `${left}px`;
  popover.style.top = `${top}px`;
}

function hideIdentityPopover() {
  if (identityPopover) identityPopover.hidden = true;
  // Reset whichever button opened the popover (Private header or a Public channel detail button).
  if (identityPopoverAnchor) {
    identityPopoverAnchor.setAttribute('aria-expanded', 'false');
    identityPopoverAnchor = null;
  }
  identityMenuButton?.setAttribute('aria-expanded', 'false');
}

// Set or edit the thread's private local label from the "Display as" menu. A thread created via New Chat
// can be given a local label up front, but a thread auto-created from an INCOMING message could not — the
// menu only ever offered an existing local-label as a display choice, never a way to add one. This closes
// that gap: any thread can now be (re)named locally. The label never leaves the device (it is not sent to
// the other side); it is persisted in the thread snapshot exactly like the displayIdentity preference.
async function promptThreadLocalLabel(thread) {
  if (!thread) return;
  const current = typeof thread.localLabel === 'string' ? thread.localLabel : '';
  const result = await openActionDialog({
    title: current ? t('chat.editLocalName') : t('chat.setLocalName'),
    hint: t('chat.localNameHint'),
    submitLabel: t('common.save'),
    fields: [
      {
        id: 'localLabel',
        label: t('chat.localName'),
        placeholder: t('chat.localNamePlaceholder'),
        value: current,
        required: false,
        autocomplete: 'off',
      },
    ],
  });
  if (!result) return;
  const next = (result.localLabel ?? '').trim();
  if (next) {
    thread.localLabel = next;
    thread.displayIdentity = null; // show the just-set local name
  } else if (thread.localLabel) {
    delete thread.localLabel;
    // The cleared label may have been the shown name; applyThreadDisplayFields falls back to the identity.
  }
  applyThreadDisplayFields(thread);
  syncThreadDisplayToContactStore(thread); // write the store BEFORE rendering (hydrate reads it)
  renderThreads();
  renderConversation();
  persistThreadDisplayPreference(thread);
}

// Public-side twin of promptThreadLocalLabel: set/edit the local name for a wallet channel that may
// have no open Private dialog. Writes the shared store (and the matching live thread, if any).
async function promptContactLocalLabel(counterpartyWallet) {
  const stored = readContactDisplayPreference(counterpartyWallet);
  const current = stored?.localLabel ?? '';
  const result = await openActionDialog({
    title: current ? t('chat.editLocalName') : t('chat.setLocalName'),
    hint: t('chat.localNameHint'),
    submitLabel: t('common.save'),
    fields: [
      {
        id: 'localLabel',
        label: t('chat.localName'),
        placeholder: t('chat.localNamePlaceholder'),
        value: current,
        required: false,
        autocomplete: 'off',
      },
    ],
  });
  if (!result) return;
  const next = (result.localLabel ?? '').trim();
  // Setting a local name clears the identity choice (mirrors promptThreadLocalLabel); clearing it falls
  // back to the wallet/identity default.
  applyContactDisplaySelection(counterpartyWallet, { displayIdentity: null, localLabel: next || null });
}

// Small inline pencil glyph for the local-name edit affordance. Kept inline (createElementNS) so it
// needs no new asset file / SW-precache entry / bundle-allowlist entry.
function createPencilIcon() {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  const path = document.createElementNS(ns, 'path');
  path.setAttribute('d', 'M12 20h9M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z');
  svg.append(path);
  return svg;
}

// Small inline "channel about" glyph — an outline speech bubble with two short text lines ("what this channel says
// about itself"). Deliberately distinct from the (i) Docs header icon AND the document-lines "edit description"
// header icon (owner: the same icon must not sit on two different buttons), and from the filled double-bubble chat
// nav icon. Inline like createPencilIcon so it needs no new asset / SW-precache entry.
function createChannelAboutIcon() {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  const bubble = document.createElementNS(ns, 'path');
  bubble.setAttribute('d', 'M20 14a2 2 0 0 1-2 2H8l-4 4V6a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2z');
  const line1 = document.createElementNS(ns, 'path');
  line1.setAttribute('d', 'M8 8h8');
  const line2 = document.createElementNS(ns, 'path');
  line2.setAttribute('d', 'M8 11.5h5');
  svg.append(bubble, line1, line2);
  return svg;
}

// Small inline copy glyph (two overlapping cards) for the "copy wallet address" affordance on the address row of
// the "Display as" popover. Inline like createPencilIcon/createChannelAboutIcon so it needs no new asset / SW-precache entry.
function createCopyIcon() {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  const rect = document.createElementNS(ns, 'rect');
  rect.setAttribute('x', '9');
  rect.setAttribute('y', '9');
  rect.setAttribute('width', '12');
  rect.setAttribute('height', '12');
  rect.setAttribute('rx', '2');
  const back = document.createElementNS(ns, 'path');
  back.setAttribute('d', 'M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1');
  svg.append(rect, back);
  return svg;
}

// Anchored popover showing a channel's PROFILE (description + tags), reusing the shared identity-popover element
// (position + outside-click-close for free). Cache-first: a warm profile renders instantly; a cold miss shows a
// loading line and resolves via resolveChannelProfile (bounded per-author walk). For the user's OWN channel the
// empty/filled states offer an add/edit affordance.
async function showChannelDescriptionPopover(authorWallet, anchor, options = {}) {
  if (!authorWallet || !anchor) return;
  const isOwn = options.isOwn === true;
  const popover = ensureIdentityPopover();
  popover.setAttribute('role', 'dialog');
  popover.replaceChildren();
  const title = document.createElement('div');
  title.className = 'identity-popover-title';
  title.textContent = t('public.channelAbout');
  const body = document.createElement('div');
  body.className = 'channel-about-popover';
  popover.append(title, body);
  const renderBody = (profile) => {
    body.replaceChildren();
    const description = typeof profile?.description === 'string' ? profile.description.trim() : '';
    const tags = (profile?.tags ?? []).filter(Boolean);
    if (description) {
      const paragraph = document.createElement('p');
      paragraph.className = 'channel-about-description';
      paragraph.textContent = description;
      body.append(paragraph);
    }
    if (tags.length > 0) {
      const tagRow = document.createElement('div');
      tagRow.className = 'channel-about-tags';
      for (const tag of tags) {
        const chip = document.createElement('span');
        chip.className = 'channel-about-tag';
        chip.textContent = `#${tag}`;
        tagRow.append(chip);
      }
      body.append(tagRow);
    }
    if (!description && tags.length === 0) {
      const empty = document.createElement('p');
      empty.className = 'channel-about-empty';
      empty.textContent = t('public.noDescriptionYet');
      body.append(empty);
    }
    // Jump from the about card straight to the channel screen (this channel's posts only).
    const openChannelButton = document.createElement('button');
    openChannelButton.type = 'button';
    openChannelButton.className = 'discovery-cta-action channel-about-open';
    openChannelButton.textContent = t('public.openChannel');
    openChannelButton.addEventListener('click', () => {
      hideIdentityPopover();
      openPublicChannelView({ authorWallet });
    });
    body.append(openChannelButton);
    if (isOwn) {
      const editButton = document.createElement('button');
      editButton.type = 'button';
      editButton.className = 'discovery-cta-action channel-about-edit';
      editButton.textContent = (description || tags.length > 0) ? t('public.editDescription') : t('public.addDescription');
      editButton.addEventListener('click', () => {
        hideIdentityPopover();
        openEditChannelProfileDialog().catch((error) => console.error(error));
      });
      body.append(editButton);
    }
  };
  const cached = cachedChannelProfile(authorWallet);
  if (cached && cached.fetchedAt) {
    renderBody(cached);
  } else {
    const loading = document.createElement('p');
    loading.className = 'channel-about-empty';
    loading.textContent = t('public.loadingDescription');
    body.append(loading);
  }
  popover.hidden = false; // unhide FIRST so positionIdentityPopover can measure the real height (bounded by the CSS max-height)
  positionIdentityPopover(popover, anchor);
  if (identityPopoverAnchor && identityPopoverAnchor !== anchor) identityPopoverAnchor.setAttribute('aria-expanded', 'false');
  identityPopoverAnchor = anchor;
  anchor.setAttribute('aria-expanded', 'true');
  if (!cached || !cached.fetchedAt) {
    let resolved = null;
    try {
      resolved = await resolveChannelProfile(authorWallet);
    } catch (error) {
      resolved = cachedChannelProfile(authorWallet);
    }
    // Only repaint if THIS popover is still the one open for THIS anchor (the user may have moved on). The loaded
    // description changes the height, so re-position against the real measured size.
    if (!popover.hidden && identityPopoverAnchor === anchor) {
      renderBody(resolved);
      positionIdentityPopover(popover, anchor);
    }
  }
}

// Own-channel "add / edit description" dialog: pre-fills from the cached (or freshly resolved) current profile,
// publishes on submit via publishChannelProfile (errors surface inline, the dialog stays open), and updates the
// local cache so the owner sees their new description immediately. Tags are entered comma/newline-separated and
// normalized (lowercase/trim/dedupe/cap) by the wire codec.
async function openEditChannelProfileDialog() {
  const wallet = rawWalletAddress(plathoWallet?.address);
  if (!wallet) { setPublicStatus('channel description needs a wallet'); return; }
  if (!hasActivePlathoAccount()) { setPublicStatus('channel description needs an active account'); return; }
  let current = cachedChannelProfile(wallet);
  if (!current || !current.fetchedAt) {
    try { current = await resolveChannelProfile(wallet); } catch { current = cachedChannelProfile(wallet); }
  }
  const result = await openActionDialog({
    title: t('public.channelDescriptionTitle'),
    hint: t('public.channelDescriptionHint'),
    submitLabel: t('common.save'),
    checkingHint: t('public.descriptionSaving'),
    summary: (values) => {
      // Show the publish cost, same as the mint / avatar modals — a channel profile is a public post, so saving it
      // holds GRAM from the Vault (the bulk is a refundable over-reserve, hence "up to"). Reuses the generic GRAM-hold
      // strings for wording parity with the mint dialog. Best-effort: a pricing hiccup must never blank the dialog.
      try {
        const hold = estimatedChannelProfileHoldNanotons(values.description, values.tags);
        return [{ label: t('username.gramHold'), value: t('username.gramHoldValue', { amount: formatTonNanotons(hold) }) }];
      } catch {
        return [];
      }
    },
    fields: [
      {
        id: 'description',
        label: t('public.descriptionLabel'),
        type: 'textarea',
        placeholder: t('public.descriptionPlaceholder'),
        value: current?.description ?? '',
        required: false,
        // Live UTF-8 BYTE budget (the on-chain field is byte-capped; cyrillic is 2 bytes/char) so nothing truncates
        // silently on save. Red once over PROFILE_DESCRIPTION_MAX_BYTES.
        counter: (value) => {
          const used = utf8ByteLength(value);
          return { text: t('public.profileDescriptionBudget', { used, max: PROFILE_DESCRIPTION_MAX_BYTES }), over: used > PROFILE_DESCRIPTION_MAX_BYTES };
        },
      },
      {
        id: 'tags',
        label: t('public.tagsLabel'),
        placeholder: t('public.tagsPlaceholder'),
        value: (current?.tags ?? []).join(', '),
        required: false,
        autocomplete: 'off',
        // Count (≤PROFILE_MAX_TAGS) + per-tag byte cap; red if too many tags OR any tag exceeds PROFILE_TAG_MAX_BYTES.
        counter: (value) => {
          const raw = String(value).split(/[,\n]+/).map((s) => s.trim().toLowerCase()).filter(Boolean);
          const over = raw.length > PROFILE_MAX_TAGS || raw.some((tag) => utf8ByteLength(tag) > PROFILE_TAG_MAX_BYTES);
          return { text: t('public.profileTagsBudget', { count: raw.length, max: PROFILE_MAX_TAGS, bytes: PROFILE_TAG_MAX_BYTES }), over };
        },
      },
    ],
    validateSubmit: async (values) => {
      if (tonRpcLimited()) return { ok: false, error: t('sync.rpcBusy') };
      try {
        const description = String(values.description ?? '').trim();
        const tags = String(values.tags ?? '').split(/[,\n]+/);
        const published = await publishChannelProfile(description, tags);
        const status = published?.result?.status;
        const meta = { description: published.description, tags: published.tags, ownerUsername: published.ownerUsername };
        const createdAtSec = published.createdAtSec;
        const publishState = published?.result?.publishState ?? null;
        if (status === CAPSULEHUB_PUBLISH_STATUS_CONFIRMED) {
          // Landed already — commit to the durable cache with the real entry id.
          finalizeChannelProfile(wallet, meta, publishStateEntryId(publishState), createdAtSec);
          return { ok: true, result: { status } };
        }
        if (status === VAULT_PUBLISH_STATUS_SUBMITTED || status === VAULT_PUBLISH_STATUS_PARTIAL) {
          // Broadcast but not yet confirmed: show it immediately (overlay, not persisted) and let the heal driver
          // re-broadcast + confirm until it lands (→ durable cache) or terminals (→ overlay dropped, no masked failure).
          setChannelProfileOptimistic(wallet, meta, createdAtSec);
          if (publishState) healChannelProfilePublish(wallet, publishState, meta, createdAtSec);
          return { ok: true, result: { status } };
        }
        return { ok: false, error: t('public.descriptionSaveFailed') };
      } catch (error) {
        if (noteTonRpcRateLimit(error)) return { ok: false, error: t('sync.rpcBusy') };
        console.error(error);
        return { ok: false, error: t('public.descriptionSaveFailed') };
      }
    },
  });
  if (result) {
    setPublicStatus('channel description saved');
    if (isPublicViewActive()) renderPublicSurface({ anchorUnread: false });
  }
}

// Generic "Display as" popover used by BOTH the Private conversation header and the Public channel
// detail header. The caller supplies the option list, the current selection, and what to do when an
// option / the local-name action is picked.
function renderDisplayAsPopover({ options, selectedKey, localLabelExists, anchor, onSelect, onSetLocalName }) {
  if (!anchor) return;
  const popover = ensureIdentityPopover();
  popover.setAttribute('role', 'menu');
  popover.replaceChildren();
  const title = document.createElement('div');
  title.className = 'identity-popover-title';
  title.textContent = t('chat.displayAs');
  popover.append(title);
  const openEdit = () => {
    hideIdentityPopover();
    onSetLocalName();
  };
  // Local name at the very top: when none is set yet, the "Set local name" action sits above the identities. (When
  // one IS set it's the first option in the loop below, carrying an edit pencil — already at the top.)
  if (!localLabelExists) {
    const localNameRow = document.createElement('button');
    localNameRow.type = 'button';
    localNameRow.className = 'identity-variant identity-variant-action';
    localNameRow.setAttribute('role', 'menuitem');
    const localNameLabel = document.createElement('strong');
    localNameLabel.textContent = t('chat.setLocalName');
    const localNameType = document.createElement('span');
    localNameType.textContent = t('chat.onlyShownThisDevice');
    localNameRow.append(localNameLabel, localNameType);
    localNameRow.addEventListener('click', openEdit);
    popover.append(localNameRow);
  }
  for (const option of options ?? []) {
    if (option.key === 'local-label') {
      // The local name stays a selectable display option; its edit affordance is now a pencil button
      // on the row itself instead of a separate "Edit local name" menu item.
      const row = document.createElement('div');
      row.className = 'identity-variant-localname';
      row.setAttribute('role', 'none');
      const selectRow = identityVariantRow(option, option.key === selectedKey, (selected) => {
        hideIdentityPopover();
        onSelect(selected);
      });
      const editButton = document.createElement('button');
      editButton.type = 'button';
      editButton.className = 'identity-variant-edit';
      editButton.setAttribute('role', 'menuitem');
      editButton.setAttribute('aria-label', t('chat.editLocalName'));
      editButton.title = t('chat.editLocalName');
      editButton.append(createPencilIcon());
      editButton.addEventListener('click', openEdit);
      row.append(selectRow, editButton);
      popover.append(row);
      continue;
    }
    if (option.identity?.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS && option.identity.value) {
      // The raw-wallet-address option carries a copy affordance (owner request) so the full address is one tap
      // away wherever this menu appears — Private header, public post chevron, discovery card. Mirrors the
      // local-name row's select-row + trailing-icon-button layout. Copying is separate from selecting the
      // display identity, so the click is stopped from bubbling and the popover stays open for a follow-up pick.
      const row = document.createElement('div');
      row.className = 'identity-variant-localname';
      row.setAttribute('role', 'none');
      const selectRow = identityVariantRow(option, option.key === selectedKey, (selected) => {
        hideIdentityPopover();
        onSelect(selected);
      });
      const copyButton = document.createElement('button');
      copyButton.type = 'button';
      copyButton.className = 'identity-variant-edit';
      copyButton.setAttribute('role', 'menuitem');
      copyButton.setAttribute('aria-label', t('profile.copyWalletAddress'));
      copyButton.title = t('profile.copyWalletAddress');
      copyButton.append(createCopyIcon());
      const addressToCopy = option.identity.value;
      copyButton.addEventListener('click', async (event) => {
        event.stopPropagation();
        try {
          await copyTextToClipboard(addressToCopy);
          // In-place confirmation: no global toast exists, and flashWalletIdentityStatus targets the wallet
          // screen (off-screen here). Briefly tint + relabel the button, then restore. If the popover closes
          // first the node is detached and the restore is a harmless no-op.
          copyButton.classList.add('identity-variant-copied');
          copyButton.title = t('wallet.addressCopied');
          copyButton.setAttribute('aria-label', t('wallet.addressCopied'));
          window.setTimeout(() => {
            copyButton.classList.remove('identity-variant-copied');
            copyButton.title = t('profile.copyWalletAddress');
            copyButton.setAttribute('aria-label', t('profile.copyWalletAddress'));
          }, 1200);
        } catch (error) {
          console.error(error);
        }
      });
      row.append(selectRow, copyButton);
      popover.append(row);
      continue;
    }
    popover.append(identityVariantRow(option, option.key === selectedKey, (selected) => {
      hideIdentityPopover();
      onSelect(selected);
    }));
  }
  popover.hidden = false; // unhide FIRST so positionIdentityPopover can measure the real height (bounded by the CSS max-height)
  positionIdentityPopover(popover, anchor);
  // Track the opening button so its aria-expanded reflects the open state and is reset on close
  // (works for both the Private header button and a Public channel detail button).
  if (identityPopoverAnchor && identityPopoverAnchor !== anchor) {
    identityPopoverAnchor.setAttribute('aria-expanded', 'false');
  }
  identityPopoverAnchor = anchor;
  anchor.setAttribute('aria-expanded', 'true');
}

function showIdentityPopover(thread, anchor) {
  if (!thread || !anchor) return;
  renderDisplayAsPopover({
    options: identityDisplayOptions(thread),
    selectedKey: selectedIdentityDisplayOptionKey(thread),
    localLabelExists: Boolean(thread.localLabel),
    anchor,
    onSelect: (selected) => {
      thread.displayIdentity = selected.identity ?? null;
      applyThreadDisplayFields(thread);
      syncThreadDisplayToContactStore(thread); // write the store BEFORE rendering (hydrate reads it)
      renderThreads();
      renderConversation();
      persistThreadDisplayPreference(thread);
    },
    onSetLocalName: () => {
      promptThreadLocalLabel(thread).catch((error) => console.error(error));
    },
  });
}

// "Display as" for a Public wallet channel — the menu, options, and selection semantics mirror the
// Private conversation header exactly, and every change flows through the shared store so the matching
// Private dialog stays in sync.
function showPublicChannelDisplayPopover(channel, anchor) {
  const wallet = channel?.authorWallet;
  if (!wallet || !anchor) return;
  const context = contactDisplayContextForWallet(wallet);
  renderDisplayAsPopover({
    options: identityDisplayOptions(context),
    selectedKey: selectedIdentityDisplayOptionKey(context),
    localLabelExists: Boolean(context.localLabel),
    anchor,
    onSelect: (selected) => {
      // Re-read the local label from the store at click time (not the captured context): the user may
      // have set one via "Set local name" since this popover was built. Selecting an identity must not
      // wipe it (mirrors Private, where choosing an identity leaves thread.localLabel intact).
      const currentLocalLabel = readContactDisplayPreference(wallet)?.localLabel ?? null;
      applyContactDisplaySelection(wallet, {
        displayIdentity: selected.identity ?? null,
        localLabel: currentLocalLabel,
      });
    },
    onSetLocalName: () => {
      promptContactLocalLabel(wallet).catch((error) => console.error(error));
    },
  });
}

function renderConversationIdentity(thread) {
  const identity = threadSelectedIdentity(thread);
  const labelText = isSavedMessagesThread(thread) ? t('chat.myNotes') : threadDisplayLabel(thread);
  if (!identity) {
    activeTitle.textContent = labelText;
    if (identityMenuButton) {
      identityMenuButton.hidden = identityDisplayOptions(thread).length < 1;
      identityMenuButton.setAttribute('aria-label', t('chat.chooseDisplayNameFor', { name: labelText }));
      identityMenuButton.setAttribute('title', t('chat.chooseDisplayName'));
    }
    return;
  }
  const label = document.createElement('span');
  label.className = `identity-title-label identity-label-${identityTone(identity)}`;
  label.textContent = labelText;
  activeTitle.replaceChildren(label);
  if (identityMenuButton) {
    identityMenuButton.hidden = identityDisplayOptions(thread).length <= 1;
    identityMenuButton.setAttribute('aria-label', t('chat.chooseDisplayNameFor', { name: labelText }));
    identityMenuButton.setAttribute('title', t('chat.chooseDisplayName'));
  }
}

const MESSAGE_SYNC_LOADING_FRAMES = Object.freeze(['Syncing', 'Syncing.', 'Syncing..', 'Syncing...']);

function messageAutoSyncCountdownText() {
  if (!isChatsViewActive() || !plathoWallet || !localRecipientKeyPair) return null;
  // State-only sync status — auto-sync runs in the background, so there is no "next sync in Ns" countdown.
  if (messageAutoSyncPhase === 'syncing') {
    return MESSAGE_SYNC_LOADING_FRAMES[messageAutoSyncLoadingFrame % MESSAGE_SYNC_LOADING_FRAMES.length];
  }
  if (messageAutoSyncPhase === 'synced') return t('sync.syncedCheck');
  if (messageAutoSyncPhase === 'delayed') return messageAutoSyncLastErrorLabel ?? t('sync.delayed');
  return null;
}

function conversationSubtitleText() {
  // The sync status moved to the GLOBAL header sync indicator (spinner/check, visible on every tab), so the dialog
  // subtitle no longer carries it. Kept empty — the name above already identifies the conversation.
  return '';
}

function isGlobalSyncActive() {
  return messageAutoSyncPhase === 'syncing' || publicSyncPhase === 'syncing' || prefsSyncInFlight === true;
}

// Drive the green header sync indicator (spinner while any sync runs, check when synced) — shown in the corner on
// every tab. Toggled at every sync phase transition: private via refreshConversationSubtitle (which all private
// transitions call), public via setPublicSyncPhase, prefs via publishPrefsSnapshot.
function refreshGlobalSyncIndicator() {
  const active = isGlobalSyncActive();
  for (const el of globalSyncIndicators) {
    el.dataset.syncing = active ? 'true' : 'false';
    // Idle = a tappable "sync now" button (see syncNowForCurrentScreen); the tooltip says so.
    el.setAttribute('aria-label', active ? t('sync.syncing') : t('sync.syncNow'));
    el.title = active ? t('sync.syncingEllipsis') : t('sync.syncNow');
  }
}

// The idle sync indicator (check mode) doubles as a "sync NOW" button (owner request), and the tap is
// CONTEXT-AWARE — it means different things on different screens: the discovery overlay wants fresh active
// channels, the Private tab wants the full manual message walk, Vault/Profile want their balances, and the
// public feed / post detail want the unified sync cycle. A tap while any sync is already running (spinner
// mode) is a no-op — the work the user wants is already happening.
function syncNowForCurrentScreen() {
  if (isGlobalSyncActive() || messageSyncManualInFlight) return;
  const view = appShell?.dataset.view;
  if (view === 'public' && publicPane?.dataset?.discoverOpen === 'true') {
    refreshPublicDiscovery().catch((error) => console.error(error));
    return;
  }
  if (view === 'chats') {
    runManualPrivateMessageSync();
    return;
  }
  if (view === 'vault') {
    refreshVaultNow({ includeActivation: true, includeStats: true }).catch((error) => {
      const rateLimited = noteTonRpcRateLimit(error);
      setVaultStatus(rateLimited ? 'RPC busy, retrying' : 'sync blocked');
      if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
    });
    return;
  }
  if (view === 'profile') {
    refreshProfilePaneReads();
    return;
  }
  // Public feed / post detail (and any future view): run the unified private+public sync cycle now
  // (1s is the scheduler's floor delay).
  scheduleMessageAutoSync(1_000);
}
for (const indicator of globalSyncIndicators) {
  indicator.addEventListener('click', () => syncNowForCurrentScreen());
}

// Advance the public sync phase and, ONLY when it actually changes, repaint the public Feed so the live sync
// status updates. Gated to the active Public view + change-only so a quiet background sync does not repaint
// every cycle.
function setPublicSyncPhase(phase) {
  if (publicSyncPhase === phase) return;
  publicSyncPhase = phase;
  refreshGlobalSyncIndicator();
  if (isPublicViewActive()) renderPublicSurface({ anchorUnread: false });
}

function debugTiny(value, fallback = '-') {
  const text = String(value ?? '').trim();
  if (!text) return fallback;
  return text.length > 18 ? `${text.slice(0, 8)}...${text.slice(-6)}` : text;
}

function debugCountdown(isoValue) {
  const parsed = Date.parse(isoValue ?? '');
  if (!Number.isFinite(parsed)) return '-';
  const delta = parsed - Date.now();
  return delta > 0 ? `${Math.ceil(delta / 1000)}s` : 'due';
}

function debugDurationMs(value) {
  const ms = Number(value);
  if (!Number.isFinite(ms) || ms < 0) return '-';
  if (ms < 60_000) return `${Math.ceil(ms / 1000)}s`;
  return `${Math.ceil(ms / 60_000)}m`;
}

function privateDebugPublishMessages(thread) {
  const withPublish = (thread?.messages ?? []).filter((message) => message?.publishState);
  const pending = withPublish.filter((message) => (
    message.publishState?.status !== CAPSULEHUB_PUBLISH_STATUS_CONFIRMED
  ));
  const source = pending.length > 0 ? pending : withPublish;
  return source.slice(-5);
}

function privateDebugMessageLabel(thread, message) {
  const index = Math.max(0, (thread?.messages ?? []).indexOf(message));
  const text = String(message?.text ?? '').trim();
  const shortText = text ? debugTiny(text.replace(/\s+/g, ' '), '') : (message?.attachment ? 'image' : 'msg');
  return `m${index}${shortText ? `:${shortText}` : ''}`;
}

function privateDebugPartStatus(part) {
  const status = String(part?.status ?? '-');
  if (status === PUBLISH_PART_STATUS_CAPSULEHUB_CONFIRMED) return 'ok';
  if (status === PUBLISH_PART_STATUS_VAULT_SUBMITTED) return 'vault';
  if (status === PUBLISH_PART_STATUS_SENDING) return 'send';
  if (status === PUBLISH_PART_STATUS_SENT) return 'sent';
  if (status === PUBLISH_PART_STATUS_UNKNOWN) return 'unk';
  if (status === PUBLISH_PART_STATUS_FAILED) return 'fail';
  if (status === PUBLISH_PART_STATUS_BUILT) return 'built';
  return debugTiny(status, '-');
}

function privateDebugPartLine(part) {
  const index = Number(part?.index ?? 0);
  const nonce = part?.clientNonce !== undefined && part?.clientNonce !== null ? ` n=${part.clientNonce}` : '';
  const boc = typeof part?.externalBoc === 'string' && part.externalBoc.length > 0 ? ' boc=y' : '';
  const pid = publishIdForPart(part) ? ` pid=${debugTiny(publishIdForPart(part), '-')}` : '';
  const previous = part?.retryPreviousStatus ? ` prev=${privateDebugPartStatus({ status: part.retryPreviousStatus })}` : '';
  const retry = Number(part?.broadcastRetryCount ?? 0) || 0;
  const retryText = retry > 0 ? ` br=${retry}` : '';
  const error = part?.error ?? part?.lastBroadcastRetryError ?? part?.retryReason;
  const err = error ? ` err=${debugTiny(error, '-')}` : '';
  return `p${index}:${privateDebugPartStatus(part)}${previous}${nonce}${boc}${pid}${retryText}${err}`;
}

function privateDebugStoredCapsuleCount(message) {
  if (Array.isArray(message?.capsules)) return message.capsules.filter(Boolean).length;
  return message?.capsule ? 1 : 0;
}

function privateDebugPublishDetailLines(thread) {
  return privateDebugPublishMessages(thread).map((message) => {
    const sendKey = message.privateSendRetryKey;
    const confirmKey = message.privatePublishConfirmRetryKey;
    const sendJob = sendKey && privateSendRetryJobs.has(sendKey) ? 'job' : 'idle';
    const confirmJob = confirmKey && privatePublishConfirmJobs.has(confirmKey) ? 'job' : 'idle';
    const sendNext = debugCountdown(message.privateSendRetryNextAt);
    const confirmNext = debugCountdown(message.privatePublishConfirmNextAt);
    const expectedCapsules = Number(message.publishState?.partCount ?? message.publishState?.parts?.length ?? 0) || 0;
    const storedCapsules = privateDebugStoredCapsuleCount(message);
    const sendAttempt = Number(message.privateSendRetryAttempt ?? 0) || 0;
    const confirmAttempt = Number(message.privatePublishConfirmAttempt ?? 0) || 0;
    const stopped = `${message.privateSendRetryStopped === true ? ' sendStop=1' : ''}${message.privatePublishConfirmStopped === true ? ' confStop=1' : ''}`;
    const parts = (message.publishState?.parts ?? []).map((part) => privateDebugPartLine(part)).join(' ');
    const retryable = publishStateHasRetryableSendParts(message.publishState) ? ' retryable=1' : '';
    const partialAge = privateMessageHasPartialRetryablePublish(message)
      ? ` pAge=${debugDurationMs(privatePartialSendRetryAgeMs(message))}`
      : '';
    const partialExpired = privatePartialSendRetryExpired(message) ? ' pExpired=1' : '';
    const stateError = message.publishState?.lastBroadcastRetryError
      ? ` stateErr=${debugTiny(message.publishState.lastBroadcastRetryError, '-')}`
      : '';
    return `${privateDebugMessageLabel(thread, message)} caps=${storedCapsules}/${expectedCapsules || '-'} send=${sendJob}/${sendNext} sA=${sendAttempt} conf=${confirmJob}/${confirmNext} cA=${confirmAttempt}${stopped}${retryable}${partialAge}${partialExpired}${stateError} ${parts || 'parts=-'}`;
  });
}

function privateDebugPublishLine(thread) {
  const items = privateDebugPublishMessages(thread)
    .map((message) => {
      const state = message.publishState ?? {};
      const status = publishStateMeta(state);
      const total = Math.max(1, Number(state.partCount) || 1);
      const counts = total > 1
        ? ` c${Number(state.confirmedCount ?? 0)}/${total} s${Number(state.submittedCount ?? 0)}/${total}`
        : '';
      const updated = state.updatedAt ? new Date(state.updatedAt).toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
      }) : '-';
      const attempt = Number(message.privatePublishConfirmAttempt ?? 0) || 0;
      const nextAt = Date.parse(message.privatePublishConfirmNextAt ?? '');
      const next = Number.isFinite(nextAt) && nextAt > Date.now()
        ? `${Math.ceil((nextAt - Date.now()) / 1000)}s`
        : '-';
      const last = debugTiny(message.privatePublishConfirmLastResult ?? message.privatePublishConfirmLastError, '-');
      const retry = Number((state.parts ?? []).reduce((sum, part) => sum + (Number(part?.broadcastRetryCount ?? 0) || 0), 0));
      const confirm = attempt > 0 || next !== '-' || last !== '-' || retry > 0
        ? ` a${attempt} next=${next} last=${last} br=${retry}`
        : '';
      return `${privateDebugMessageLabel(thread, message)} ${status}${counts}@${updated}${confirm}`;
    });
  return items.length > 0 ? items.join(' | ') : '-';
}

function privateDebugLines(thread = activeThread()) {
  if (!thread) return [];
  const sync = globalThis.plathoLastPrivateSync ?? {};
  const reason = sync.reason ?? (sync.unchanged ? 'unchanged' : 'ok');
  const phase = messageAutoSyncPhase || 'idle';
  const error = messageAutoSyncLastErrorLabel ? ` err=${debugTiny(messageAutoSyncLastErrorLabel, '-')}` : '';
  const scanLog = Array.isArray(sync.scanLog) && sync.scanLog.length > 0
    ? sync.scanLog.join(' ')
    : '-';
  const recipientCursor = sync.recipientCursor ?? {};
  const senderCursor = sync.senderCursor ?? {};
  const indexError = sync.indexReadError ? ` idxErr=${debugTiny(sync.indexReadError, '-')}` : '';
  const indexFallback = sync.indexReadFallback ? ` idxFallback=${debugTiny(sync.indexReadFallback, '-')}` : '';
  return [
    `${PLATHO_APP_RUNTIME_VERSION} key=${shortKeyId(localRecipientKeyPair?.keyId)} phase=${phase}${error}`,
    `idx=${sync.indexKeyId ?? '-'} rh=${sync.recipientHead ?? '-'} sh=${sync.senderHead ?? '-'} mode=${sync.mode ?? '-'}`,
    `rc=${recipientCursor.processedHeadLink ?? '-'}:${recipientCursor.resumeLink ?? '-'} sc=${senderCursor.processedHeadLink ?? '-'}:${senderCursor.resumeLink ?? '-'}`,
    `imp=${sync.imported ?? 0} skip=${sync.skipped ?? 0} inc=${sync.incompletePrivateStreamCount ?? 0} catch=${sync.catchUpRemaining ?? 0}`,
    `reason=${reason}${indexError}${indexFallback} block=${sync.blockedEntryId ?? '-'} body=${sync.historyUnavailableCount ?? 0} scanned=${sync.indexEntriesScanned ?? 0} repair=${sync.headRepairScanned ?? 0} retry=${sync.historyRetryScanned ?? 0}`,
    `entries ${scanLog}`,
    `publish ${privateDebugPublishLine(thread)}`,
    ...privateDebugPublishDetailLines(thread),
  ];
}

function refreshConversationSubtitle() {
  // The global sync indicator updates on every private-sync transition (all of which call this), regardless of
  // whether a conversation is open — so refresh it first, before the no-active-thread early return.
  refreshGlobalSyncIndicator();
  const thread = activeThread();
  if (!thread || !activeSubtitle) return;
  activeSubtitle.textContent = conversationSubtitleText(thread);
}

function clearMessageAutoSyncCountdownTimer() {
  if (!messageAutoSyncCountdownTimer) return;
  window.clearTimeout(messageAutoSyncCountdownTimer);
  messageAutoSyncCountdownTimer = null;
}

function scheduleMessageAutoSyncCountdownUi() {
  clearMessageAutoSyncCountdownTimer();
  refreshConversationSubtitle();
  if (!isChatsViewActive() || document.hidden) return;
  // Only re-tick to animate the "Syncing…" frames; there is no longer a "next sync in Ns" countdown to update.
  if (messageAutoSyncPhase === 'syncing') {
    messageAutoSyncCountdownTimer = window.setTimeout(() => {
      messageAutoSyncLoadingFrame = (messageAutoSyncLoadingFrame + 1) % MESSAGE_SYNC_LOADING_FRAMES.length;
      scheduleMessageAutoSyncCountdownUi();
    }, 420);
  }
}

function beginMessageSyncUi() {
  messageAutoSyncPhase = 'syncing';
  messageAutoSyncAt = 0;
  messageAutoSyncLastErrorLabel = null;
  messageAutoSyncLoadingFrame = 0;
  setMessageSyncStatus(t('sync.statusSyncing'), 'syncing');
  scheduleMessageAutoSyncCountdownUi();
}

function completeMessageSyncUi(result) {
  messageAutoSyncLastResult = result ?? null;
  const status = privateSyncStatusText(result);
  const complete = result
    && result.ok !== false
    && result.scanComplete === true
    && result.rateLimited !== true
    && Number(result.historyUnavailableCount ?? 0) === 0
    && Number(result.skipped ?? 0) === 0
    && Number(result.incompletePrivateStreamCount ?? 0) === 0
    && Number(result.undeliveredCount ?? 0) === 0
    && !['body_history_unavailable', 'catch_up_pending', 'private_key_open_failed', 'partial_stream_pending', 'index_limit_without_cursor', 'private_entry_undelivered'].includes(String(result.reason ?? ''));
  messageAutoSyncPhase = complete ? 'synced' : 'delayed';
  messageAutoSyncLastErrorLabel = complete ? null : status;
  refreshConversationSubtitle();
}

function failMessageSyncUi(label) {
  messageAutoSyncPhase = 'delayed';
  messageAutoSyncLastErrorLabel = label || t('sync.delayed');
  refreshConversationSubtitle();
}

function openNewChatDialog() {
  if (!newChatDialog || !recipientInput || !recipientHint) return;
  recipientInput.value = '';
  if (recipientLocalLabel) recipientLocalLabel.value = '';
  recipientHint.textContent = t('chat.newChatRecipientHint');
  recipientHint.dataset.tone = 'muted';
  newChatDialog.hidden = false;
  requestAnimationFrame(() => recipientInput.focus());
}

function closeNewChatDialog() {
  if (newChatDialog) newChatDialog.hidden = true;
}

function collectActionDialogValues() {
  const values = {};
  for (const field of actionFields?.querySelectorAll('[name]') ?? []) {
    values[field.name] = field.type === 'checkbox' ? field.checked : field.value;
  }
  return values;
}

function renderActionSummary(summary, values = {}) {
  if (!actionSummary) return;
  const lines = typeof summary === 'function' ? summary(values) : summary;
  actionSummary.replaceChildren();
  if (!Array.isArray(lines) || lines.length === 0) {
    actionSummary.hidden = true;
    return;
  }
  actionSummary.hidden = false;
  for (const line of lines) {
    const row = document.createElement('div');
    if (typeof line === 'string') {
      row.textContent = line;
    } else {
      const label = document.createElement('strong');
      label.textContent = t('dialog.labelPrefix', { label: line.label });
      row.append(label, document.createTextNode(String(line.value ?? '')));
    }
    actionSummary.append(row);
  }
}

function createActionField(field) {
  if (field.type === 'custom') {
    const wrapper = document.createElement('div');
    wrapper.className = field.className ?? 'action-custom-field';
    const rendered = typeof field.render === 'function' ? field.render() : field.node;
    if (rendered instanceof Node) wrapper.append(rendered);
    return wrapper;
  }
  if (field.type === 'credential-username') {
    const input = document.createElement('input');
    input.type = 'text';
    input.id = field.id;
    input.name = field.name ?? 'username';
    input.value = field.value ?? '';
    input.autocomplete = field.autocomplete ?? 'username';
    input.className = 'password-manager-username';
    input.tabIndex = -1;
    input.setAttribute('aria-hidden', 'true');
    input.style.position = 'fixed';
    input.style.left = '-10000px';
    input.style.top = '0';
    input.style.width = '1px';
    input.style.height = '1px';
    input.style.opacity = '0.01';
    input.style.pointerEvents = 'none';
    input.required = false;
    return input;
  }
  if (field.type === 'hidden') {
    const input = document.createElement('input');
    input.type = 'hidden';
    input.id = field.id;
    input.name = field.name ?? field.id;
    input.value = field.value ?? '';
    if (field.autocomplete) input.autocomplete = field.autocomplete;
    return input;
  }
  const wrapper = document.createElement('div');
  wrapper.className = field.type === 'checkbox' ? 'action-field action-checkbox-field' : 'action-field';
  const label = document.createElement('label');
  label.htmlFor = field.id;
  label.textContent = field.label;
  if (field.type === 'checkbox') {
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.id = field.id;
    input.name = field.name ?? field.id;
    input.checked = field.checked === true;
    input.required = field.required !== false;
    const text = document.createElement('span');
    text.textContent = field.label;
    label.textContent = '';
    label.append(input, text);
    wrapper.append(label);
    return wrapper;
  }
  if (field.type === 'image-preview') {
    const card = document.createElement('div');
    card.className = 'image-preview-card';
    const image = document.createElement('img');
    image.id = field.id;
    image.alt = field.alt ?? t('dialog.imagePreviewAlt');
    image.loading = 'eager';
    image.tabIndex = 0;
    image.setAttribute('role', 'button');
    image.title = t('dialog.openFullSizePreview');
    const meta = document.createElement('div');
    meta.id = field.metaId ?? `${field.id}Meta`;
    meta.className = 'image-preview-meta';
    meta.textContent = field.meta ?? t('dialog.preparingPreview');
    card.append(image, meta);
    wrapper.append(label, card);
    return wrapper;
  }
  if (field.type === 'note') {
    // Purely informational block (no label, no [name] — not collected as a value): an intro line and/or a
    // numbered steps list, used by explanatory dialogs like the "Get an RPC key" help modal.
    const note = document.createElement('div');
    note.className = 'action-note';
    if (field.text) {
      const para = document.createElement('p');
      para.textContent = field.text;
      note.append(para);
    }
    if (Array.isArray(field.steps) && field.steps.length > 0) {
      const list = document.createElement('ol');
      list.className = 'action-note-steps';
      for (const step of field.steps) {
        const item = document.createElement('li');
        item.textContent = step;
        list.append(item);
      }
      note.append(list);
    }
    return note;
  }
  let input;
  if (field.type === 'textarea') {
    input = document.createElement('textarea');
  } else if (field.type === 'select') {
    input = document.createElement('select');
    for (const option of field.options ?? []) {
      const item = document.createElement('option');
      item.value = option.value;
      item.textContent = option.label;
      input.append(item);
    }
  } else {
    input = document.createElement('input');
    input.type = field.type ?? 'text';
  }
  input.id = field.id;
  input.name = field.name ?? field.id;
  if (field.placeholder) input.placeholder = field.placeholder;
  if (field.inputMode) input.inputMode = field.inputMode;
  if (field.autocomplete) input.autocomplete = field.autocomplete;
  if (field.autocapitalize) input.autocapitalize = field.autocapitalize;
  if (field.spellcheck !== undefined) input.spellcheck = Boolean(field.spellcheck);
  if (field.minLength) input.minLength = field.minLength;
  if (field.maxLength) input.maxLength = field.maxLength;
  if (field.readOnly) input.readOnly = true;
  if (field.required !== false) input.required = true;
  input.value = field.value ?? '';
  wrapper.append(label, input);
  // Optional live counter (e.g. UTF-8 byte budget for an on-chain field): field.counter(value) -> { text, over }.
  // Recomputed on every input so nothing silently truncates on save; `is-over` flags an exceeded budget in red.
  if (typeof field.counter === 'function') {
    const counter = document.createElement('span');
    counter.className = 'action-dialog-field-counter';
    const updateCounter = () => {
      const info = field.counter(input.value);
      counter.textContent = info?.text ?? '';
      counter.classList.toggle('is-over', Boolean(info?.over));
    };
    input.addEventListener('input', updateCounter);
    updateCounter();
    wrapper.append(counter);
  }
  return wrapper;
}

// v794: modals dismiss ONLY via their explicit ✕ / Cancel — an outside/backdrop tap no longer closes them (a
// stray tap outside used to discard in-progress input). Default-deny: a plain backdrop never closes on tap.
// Two deliberate exceptions keep the outside-tap gesture: the action dialog can opt in per-open via
// dismissOnBackdrop:true (default false), and the image lightbox opts in via allowOutsideTap (a fullscreen
// viewer, not a data dialog — tap-to-dismiss is the expected gesture there).
function closeOnBackdropClick(backdrop, close, { allowOutsideTap = false } = {}) {
  if (!backdrop) return;
  let pointerStartedOnBackdrop = false;
  backdrop.addEventListener('pointerdown', (event) => {
    pointerStartedOnBackdrop = event.target === backdrop;
  });
  backdrop.addEventListener('click', (event) => {
    if (event.target !== backdrop || !pointerStartedOnBackdrop) return;
    pointerStartedOnBackdrop = false;
    if (backdrop === actionDialog) {
      // Action dialogs are X-only unless a caller explicitly opted back into outside-dismiss.
      if (activeActionDialog?.dismissOnBackdrop === false) return;
      close(event);
      return;
    }
    if (!allowOutsideTap) return; // every other modal: closes ONLY via its ✕ / Cancel control
    close(event);
  });
}

function openImageLightbox(src, meta = '') {
  if (!imageLightboxDialog || !imageLightboxImage) return;
  if (!src) return;
  imageLightboxPreviousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  resetImageLightboxZoom();
  imageLightboxImage.src = src;
  if (imageLightboxMeta) imageLightboxMeta.textContent = meta || t('common.finalCompressedImage');
  if (imageLightboxDownloadButton) imageLightboxDownloadButton.disabled = false;
  imageLightboxDialog.hidden = false;
  imageLightboxCloseButton?.focus();
}

function closeImageLightbox() {
  if (!imageLightboxDialog || imageLightboxDialog.hidden) return;
  imageLightboxDialog.hidden = true;
  imageLightboxImage?.removeAttribute('src');
  resetImageLightboxZoom();
  if (imageLightboxDownloadButton) imageLightboxDownloadButton.disabled = true;
  const focusTarget = imageLightboxPreviousFocus;
  imageLightboxPreviousFocus = null;
  focusTarget?.focus?.();
}

// --- Lightbox zoom/pan engine: pinch (touch), drag-pan when zoomed, double-tap / double-click toggle, wheel ---
// Transforms are applied via CSSOM property assignment (allowed under the prod CSP style-src 'self' — what CSP
// blocks is setAttribute('style'); the avatar backgroundImage path proves CSSOM works live). Geometry: the img's
// untransformed layout box is grid-centered in the viewport; with transform-origin 0 0 and
// transform = translate(tx,ty) scale(s), keeping a screen point fixed across a scale change is
//   t' = t + (point - imgRect.topLeft) * (1 - s'/s)
const IMAGE_LIGHTBOX_MAX_SCALE = 8;
const imageLightboxZoom = { scale: 1, tx: 0, ty: 0 };
const imageLightboxPointers = new Map();
let imageLightboxPinchDistance = 0;
let imageLightboxLastTap = { time: 0, x: 0, y: 0 };

function applyImageLightboxZoom(animated = false) {
  if (!imageLightboxImage) return;
  const zoomed = imageLightboxZoom.scale > 1.001;
  imageLightboxImage.classList.toggle('is-zoom-animated', animated === true);
  imageLightboxImage.classList.toggle('is-zoomed', zoomed);
  // Explicit identity at rest (not '') so an animated zoom-OUT interpolates instead of snapping to `none`.
  imageLightboxImage.style.transform = zoomed || animated === true
    ? `translate(${imageLightboxZoom.tx}px, ${imageLightboxZoom.ty}px) scale(${imageLightboxZoom.scale})`
    : '';
}

function resetImageLightboxZoom() {
  imageLightboxZoom.scale = 1;
  imageLightboxZoom.tx = 0;
  imageLightboxZoom.ty = 0;
  imageLightboxPointers.clear();
  imageLightboxPinchDistance = 0;
  applyImageLightboxZoom(false);
}

// Keep the image anchored: centered on an axis it fits, covering the viewport on an axis it overflows (a pan can
// never fling it away and leave an empty box). Derivation: rest top-left is centered, scaling grows from 0 0, so
// the centered translation is (base - scaled)/2 and the cover band is that ± (scaled - viewport)/2.
function clampImageLightboxPan() {
  if (!imageLightboxViewport || !imageLightboxImage) return;
  const scale = imageLightboxZoom.scale;
  const viewportW = imageLightboxViewport.clientWidth;
  const viewportH = imageLightboxViewport.clientHeight;
  const baseW = imageLightboxImage.offsetWidth;
  const baseH = imageLightboxImage.offsetHeight;
  const scaledW = baseW * scale;
  const scaledH = baseH * scale;
  const centerX = (baseW - scaledW) / 2;
  if (scaledW <= viewportW) {
    imageLightboxZoom.tx = centerX;
  } else {
    const band = (scaledW - viewportW) / 2;
    imageLightboxZoom.tx = Math.min(centerX + band, Math.max(centerX - band, imageLightboxZoom.tx));
  }
  const centerY = (baseH - scaledH) / 2;
  if (scaledH <= viewportH) {
    imageLightboxZoom.ty = centerY;
  } else {
    const band = (scaledH - viewportH) / 2;
    imageLightboxZoom.ty = Math.min(centerY + band, Math.max(centerY - band, imageLightboxZoom.ty));
  }
}

function zoomImageLightboxAt(clientX, clientY, nextScale, animated = false) {
  if (!imageLightboxImage) return;
  const target = Math.min(IMAGE_LIGHTBOX_MAX_SCALE, Math.max(1, nextScale));
  const rect = imageLightboxImage.getBoundingClientRect();
  const factor = target / imageLightboxZoom.scale;
  imageLightboxZoom.tx += (clientX - rect.left) * (1 - factor);
  imageLightboxZoom.ty += (clientY - rect.top) * (1 - factor);
  imageLightboxZoom.scale = target;
  clampImageLightboxPan();
  applyImageLightboxZoom(animated);
}

function imageLightboxPointerSpread() {
  const [a, b] = [...imageLightboxPointers.values()];
  return Math.hypot(a.x - b.x, a.y - b.y);
}

function toggleImageLightboxZoomAt(clientX, clientY) {
  zoomImageLightboxAt(clientX, clientY, imageLightboxZoom.scale > 1.001 ? 1 : 2.5, true);
}

imageLightboxViewport?.addEventListener('pointerdown', (event) => {
  if (!imageLightboxImage?.src) return;
  try { imageLightboxViewport.setPointerCapture(event.pointerId); } catch { /* unsupported */ }
  imageLightboxPointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
  if (imageLightboxPointers.size === 2) imageLightboxPinchDistance = imageLightboxPointerSpread();
  // Double-tap (touch): dblclick does not fire for touch in all engines, so detect it from pointerdown pairs.
  if (event.pointerType === 'touch' && imageLightboxPointers.size === 1) {
    const now = Date.now();
    const isDoubleTap = now - imageLightboxLastTap.time < 350
      && Math.hypot(event.clientX - imageLightboxLastTap.x, event.clientY - imageLightboxLastTap.y) < 40;
    imageLightboxLastTap = { time: now, x: event.clientX, y: event.clientY };
    if (isDoubleTap) {
      toggleImageLightboxZoomAt(event.clientX, event.clientY);
      imageLightboxLastTap = { time: 0, x: 0, y: 0 };
    }
  }
});

imageLightboxViewport?.addEventListener('pointermove', (event) => {
  const pointer = imageLightboxPointers.get(event.pointerId);
  if (!pointer) return;
  const previousX = pointer.x;
  const previousY = pointer.y;
  pointer.x = event.clientX;
  pointer.y = event.clientY;
  if (imageLightboxPointers.size === 2) {
    // Pinch: each finger contributes half the midpoint drift (pan), and the spread ratio scales toward the
    // midpoint. touch-action: none on the viewport keeps the browser's own gestures out of the way.
    imageLightboxZoom.tx += (pointer.x - previousX) / 2;
    imageLightboxZoom.ty += (pointer.y - previousY) / 2;
    const spread = imageLightboxPointerSpread();
    if (imageLightboxPinchDistance > 0 && spread > 0) {
      const [a, b] = [...imageLightboxPointers.values()];
      zoomImageLightboxAt((a.x + b.x) / 2, (a.y + b.y) / 2, imageLightboxZoom.scale * (spread / imageLightboxPinchDistance));
    }
    imageLightboxPinchDistance = spread;
    event.preventDefault();
  } else if (imageLightboxPointers.size === 1 && imageLightboxZoom.scale > 1.001) {
    imageLightboxZoom.tx += pointer.x - previousX;
    imageLightboxZoom.ty += pointer.y - previousY;
    clampImageLightboxPan();
    applyImageLightboxZoom(false);
    event.preventDefault();
  }
});

function releaseImageLightboxPointer(event) {
  imageLightboxPointers.delete(event.pointerId);
  if (imageLightboxPointers.size < 2) imageLightboxPinchDistance = 0;
}
imageLightboxViewport?.addEventListener('pointerup', releaseImageLightboxPointer);
imageLightboxViewport?.addEventListener('pointercancel', releaseImageLightboxPointer);

imageLightboxViewport?.addEventListener('wheel', (event) => {
  if (!imageLightboxImage?.src) return;
  event.preventDefault();
  const factor = Math.exp(-event.deltaY * 0.0022);
  zoomImageLightboxAt(event.clientX, event.clientY, imageLightboxZoom.scale * factor, false);
}, { passive: false });

imageLightboxViewport?.addEventListener('dblclick', (event) => {
  if (!imageLightboxImage?.src) return;
  event.preventDefault();
  toggleImageLightboxZoomAt(event.clientX, event.clientY);
});

// No NATIVE page zoom anywhere (owner request): iOS Safari ignores user-scalable=no, but its WebKit-only
// gesture* events are cancelable — killing them kills the pinch page zoom. Unconditional on purpose: the
// lightbox zooms via its OWN pointer/transform machinery (touch-action:none viewport), so the native page
// zoom is unwanted even there. No-op on non-WebKit (the events never fire).
for (const gestureEventType of ['gesturestart', 'gesturechange', 'gestureend']) {
  document.addEventListener(gestureEventType, (event) => event.preventDefault(), { passive: false });
}

function imageDownloadExtension(src) {
  const match = String(src ?? '').match(/^data:image\/([a-z0-9.+-]+)[;,]/i);
  const type = (match?.[1] ?? 'webp').toLowerCase();
  if (type === 'jpeg') return 'jpg';
  if (/^[a-z0-9]+$/.test(type)) return type;
  return 'webp';
}

function imageLightboxDownloadFilename(src) {
  const stamp = new Date().toISOString().replace(/[-:]/g, '').replace(/\..+$/, '').replace('T', '-');
  return `platho-image-${stamp}.${imageDownloadExtension(src)}`;
}

function downloadImageLightboxImage() {
  const src = imageLightboxImage?.currentSrc || imageLightboxImage?.src;
  if (!src) return;
  const link = document.createElement('a');
  link.href = src;
  link.download = imageLightboxDownloadFilename(src);
  link.rel = 'noreferrer';
  document.body.append(link);
  link.click();
  link.remove();
}

function closeActionDialog(result = null) {
  if (!activeActionDialog) return;
  const { resolve } = activeActionDialog;
  activeActionDialog = null;
  closeImageLightbox();
  if (actionDialog) actionDialog.hidden = true;
  actionFields?.replaceChildren();
  if (actionCancelButton) {
    actionCancelButton.hidden = false;
    actionCancelButton.disabled = false;
  }
  if (actionSubmitButton) actionSubmitButton.disabled = false;
  resolve(result);
  scheduleWalletUnlockPrompt();
}

async function openActionDialog(config = {}) {
  if (!actionDialog || !actionForm || !actionFields || !actionTitle || !actionHint || !actionSubmitButton) {
    throw new Error('Action dialog is unavailable');
  }
  if (activeActionDialog) closeActionDialog(null);
  return new Promise((resolve) => {
    // v794: X-only by default — outside-click / Escape no longer dismiss an action dialog unless the caller
    // explicitly opts back in with dismissOnBackdrop:true. (Was: default true, so every dialog closed on an
    // outside tap.)
    const dismissible = config.dismissOnBackdrop === true;
    // `cancellable` (the explicit ✕ close button) is DECOUPLED from `dismissOnBackdrop` (click-outside /
    // Escape dismiss) and now defaults to ON so every dialog is closable via the ✕ — a caller can still force
    // a decision (no ✕) with cancellable:false (e.g. the seed-backup hard gate). Decoupling matters: since
    // dismissible now defaults false, tying the ✕ to it would have silently removed the ✕ from every dialog.
    const cancellable = config.cancellable ?? true;
    activeActionDialog = {
      resolve,
      summary: config.summary,
      dismissOnBackdrop: dismissible,
      cancellable,
      // Optional async gate: run on submit BEFORE the dialog closes. Resolves { ok, result?, error? }. When it
      // returns ok:false the dialog STAYS OPEN and shows the error inline (no close+reopen flicker).
      validateSubmit: config.validateSubmit ?? null,
      checkingHint: config.checkingHint ?? t('dialog.checking'),
    };
    actionTitle.textContent = config.title ?? t('dialog.defaultTitle');
    actionHint.textContent = config.hint ?? t('dialog.reviewBeforeSigning');
    actionHint.dataset.tone = config.tone ?? 'muted';
    actionForm.autocomplete = config.formAutocomplete ?? 'off';
    actionForm.method = config.formMethod ?? 'post';
    actionForm.action = config.formAction ?? window.location.href;
    if (actionCancelButton) {
      actionCancelButton.hidden = !cancellable;
      actionCancelButton.disabled = !cancellable;
    }
    actionSubmitButton.textContent = config.submitLabel ?? t('common.continue');
    actionSubmitButton.disabled = false;
    actionFields.replaceChildren(...(config.fields ?? []).map(createActionField));
    renderActionSummary(config.summary, collectActionDialogValues());
    actionDialog.hidden = false;
    requestAnimationFrame(() => actionFields.querySelector('textarea, input:not([readonly]):not([type="hidden"]):not(.password-manager-username), select')?.focus());
  });
}

function updateActiveActionSummary() {
  if (!activeActionDialog) return;
  renderActionSummary(activeActionDialog.summary, collectActionDialogValues());
}

function appDocById(id) {
  return APP_DOCS.find((doc) => doc.id === id) ?? APP_DOCS[0] ?? null;
}

function renderDocsNav() {
  if (!docsNav) return;
  docsNav.replaceChildren();
  for (const doc of APP_DOCS) {
    const button = document.createElement('button');
    button.type = 'button';
    button.dataset.docId = doc.id;
    button.className = doc.id === activeDocId ? 'is-active' : '';
    button.setAttribute('aria-pressed', doc.id === activeDocId ? 'true' : 'false');
    button.textContent = doc.label;
    docsNav.append(button);
  }
}

function setDocsStatus(message, tone = 'muted') {
  if (!docsContent) return;
  const status = document.createElement('div');
  status.className = `docs-status docs-status-${tone}`;
  status.textContent = message;
  docsContent.replaceChildren(status);
}

function closeDocsDialog() {
  if (docsDialog) docsDialog.hidden = true;
}

async function openDocsDialog(docId = activeDocId) {
  if (!docsDialog) return;
  docsDialog.hidden = false;
  await selectDoc(docId);
  requestAnimationFrame(() => docsContent?.focus());
}

async function selectDoc(docId) {
  const doc = appDocById(docId);
  if (!doc || !docsContent) return;
  activeDocId = doc.id;
  renderDocsNav();
  if (docsTitle) docsTitle.textContent = doc.title;
  if (docsLead) docsLead.textContent = t('docs.lead');
  setDocsStatus(t('docs.loading'));
  try {
    // Docs are localized: cache per (doc, locale) so switching language serves the right translation. The main-app
    // language switch reloads the whole page (appLanguageSelect), so an open doc reopens in the new locale for free.
    const locale = currentLocale();
    const cacheKey = `${doc.id}:${locale}`;
    let markdown = docsCache.get(cacheKey);
    if (!markdown) {
      markdown = await fetchLocalizedDocMarkdown(doc.path, locale);
      docsCache.set(cacheKey, markdown);
    }
    renderMarkdownToNode(markdown, docsContent);
    docsContent.scrollTop = 0;
  } catch (error) {
    console.error(error);
    setDocsStatus(t('docs.unavailable'), 'error');
  }
}

// Docs ship an English base (<name>.md) plus per-locale siblings (<name>.<locale>.md). English uses the base path.
function localizedDocPath(basePath, locale) {
  if (!locale || locale === 'en') return basePath;
  return basePath.replace(/\.md$/, `.${locale}.md`);
}

// Load the current locale's doc, falling back to the English base when the locale IS English or its localized file
// is missing/unfetchable (a language without a translated doc yet degrades to English instead of erroring). The
// English base is SW-precached, so this fallback also keeps docs available offline in any language.
async function fetchLocalizedDocMarkdown(basePath, locale) {
  const localizedPath = localizedDocPath(basePath, locale);
  if (localizedPath !== basePath) {
    try {
      const localized = await fetch(localizedPath, { cache: 'no-store' });
      if (localized.ok) return await localized.text();
    } catch { /* network/missing → fall through to the English base */ }
  }
  const response = await fetch(basePath, { cache: 'no-store' });
  if (!response.ok) throw new Error(`Document fetch failed: ${response.status}`);
  return await response.text();
}

function appendInlineMarkdown(parent, text) {
  const pattern = /(`[^`]+`|\*\*[^*]+\*\*|\[[^\]]+\]\(([^)]+)\))/g;
  let cursor = 0;
  for (const match of text.matchAll(pattern)) {
    if (match.index > cursor) {
      parent.append(document.createTextNode(text.slice(cursor, match.index)));
    }
    const token = match[0];
    if (token.startsWith('`')) {
      const code = document.createElement('code');
      code.textContent = token.slice(1, -1);
      parent.append(code);
    } else if (token.startsWith('**')) {
      const strong = document.createElement('strong');
      strong.textContent = token.slice(2, -2);
      parent.append(strong);
    } else {
      const labelEnd = token.indexOf(']');
      const href = token.slice(labelEnd + 2, -1);
      const anchor = document.createElement('a');
      anchor.textContent = token.slice(1, labelEnd);
      if (/^(https?:|mailto:)/i.test(href)) {
        anchor.href = href;
        anchor.target = '_blank';
        anchor.rel = 'noreferrer';
        if (/^https?:/i.test(href) && isTelegramEnv()) {
          // target=_blank is unreliable inside the Telegram embed; route through the SDK.
          anchor.addEventListener('click', (event) => {
            if (openExternalLinkInTelegram(href)) event.preventDefault();
          });
        }
      }
      parent.append(anchor);
    }
    cursor = match.index + token.length;
  }
  if (cursor < text.length) {
    parent.append(document.createTextNode(text.slice(cursor)));
  }
}

function isMarkdownTableLine(line) {
  const trimmed = line.trim();
  return trimmed.startsWith('|') && trimmed.endsWith('|') && trimmed.includes('|');
}

function isMarkdownTableSeparator(line) {
  if (!isMarkdownTableLine(line)) return false;
  return line
    .trim()
    .replace(/^\||\|$/g, '')
    .split('|')
    .every((cell) => /^:?-{3,}:?$/.test(cell.trim()));
}

function markdownTableCells(line) {
  return line
    .trim()
    .replace(/^\||\|$/g, '')
    .split('|')
    .map((cell) => cell.trim());
}

function markdownStartsBlock(line, nextLine = '') {
  const trimmed = line.trim();
  return !trimmed
    || trimmed.startsWith('```')
    || /^#{1,4}\s+/.test(trimmed)
    || /^[-*]\s+/.test(trimmed)
    || /^\d+\.\s+/.test(trimmed)
    || (isMarkdownTableLine(line) && isMarkdownTableSeparator(nextLine));
}

function renderMarkdownTable(rows) {
  const wrapper = document.createElement('div');
  wrapper.className = 'docs-table-wrap';
  const table = document.createElement('table');
  const thead = document.createElement('thead');
  const headRow = document.createElement('tr');
  for (const cellText of rows[0] ?? []) {
    const cell = document.createElement('th');
    appendInlineMarkdown(cell, cellText);
    headRow.append(cell);
  }
  thead.append(headRow);
  table.append(thead);
  const tbody = document.createElement('tbody');
  for (const row of rows.slice(1)) {
    const tr = document.createElement('tr');
    for (const cellText of row) {
      const cell = document.createElement('td');
      appendInlineMarkdown(cell, cellText);
      tr.append(cell);
    }
    tbody.append(tr);
  }
  table.append(tbody);
  wrapper.append(table);
  return wrapper;
}

function renderMarkdownToNode(markdown, target) {
  const root = document.createElement('div');
  root.className = 'docs-rendered';
  const lines = String(markdown ?? '').replace(/\r\n/g, '\n').split('\n');
  let index = 0;
  while (index < lines.length) {
    const line = lines[index];
    const trimmed = line.trim();
    if (!trimmed) {
      index += 1;
      continue;
    }
    if (trimmed.startsWith('```')) {
      const codeLines = [];
      index += 1;
      while (index < lines.length && !lines[index].trim().startsWith('```')) {
        codeLines.push(lines[index]);
        index += 1;
      }
      index += 1;
      const pre = document.createElement('pre');
      const code = document.createElement('code');
      code.textContent = codeLines.join('\n');
      pre.append(code);
      root.append(pre);
      continue;
    }
    const heading = trimmed.match(/^(#{1,4})\s+(.+)$/);
    if (heading) {
      const level = Math.min(heading[1].length + 1, 5);
      const node = document.createElement(`h${level}`);
      appendInlineMarkdown(node, heading[2]);
      root.append(node);
      index += 1;
      continue;
    }
    if (isMarkdownTableLine(line) && isMarkdownTableSeparator(lines[index + 1] ?? '')) {
      const rows = [markdownTableCells(line)];
      index += 2;
      while (index < lines.length && isMarkdownTableLine(lines[index])) {
        rows.push(markdownTableCells(lines[index]));
        index += 1;
      }
      root.append(renderMarkdownTable(rows));
      continue;
    }
    if (/^[-*]\s+/.test(trimmed) || /^\d+\.\s+/.test(trimmed)) {
      const ordered = /^\d+\.\s+/.test(trimmed);
      const list = document.createElement(ordered ? 'ol' : 'ul');
      const itemPattern = ordered ? /^\d+\.\s+/ : /^[-*]\s+/;
      while (index < lines.length && itemPattern.test(lines[index].trim())) {
        const item = document.createElement('li');
        appendInlineMarkdown(item, lines[index].trim().replace(itemPattern, ''));
        list.append(item);
        index += 1;
      }
      root.append(list);
      continue;
    }
    const paragraphLines = [trimmed];
    index += 1;
    while (index < lines.length && !markdownStartsBlock(lines[index], lines[index + 1] ?? '')) {
      paragraphLines.push(lines[index].trim());
      index += 1;
    }
    const paragraph = document.createElement('p');
    appendInlineMarkdown(paragraph, paragraphLines.join(' '));
    root.append(paragraph);
  }
  target.replaceChildren(root);
}

function activeThread() {
  // NO threads[0] fallback: threads[0] is ALWAYS the Saved "My notes" thread, so falling back to it made an
  // unresolved activeThreadId silently render/enable the composer on "My notes" — a message the user meant for a
  // peer could then be echoed into My notes, and the render disagreed with the send (which never targets threads[0]).
  // Null here = no chat selected → renderConversation shows the empty state and the composer is disabled, matching
  // the design intent (a null activeThreadId means the user is on the dialog LIST, not silently on My notes).
  return threads.find((item) => item.id === activeThreadId) ?? null;
}

// Find an already-open dialog for the same person as `newThread`, even when they were reached by a
// different identity (e.g. an existing chat started via an .ath name vs. opening "Private chat" from a
// Public wallet channel) or the same wallet in a different address format. Order: exact thread id ->
// any shared identity variant -> same counterparty wallet (compared as raw, so friendly/raw forms
// match). Prevents the duplicate empty dialog reported from the Public tab.
function findExistingRecipientThread(newThread) {
  const newWallet = ownerWalletFromThread(newThread);
  const peerRaw = newWallet ? rawWalletAddress(newWallet) : null;
  // Heal-on-touch: a PEER lookup must never hand back the Saved self-thread (and a peer dialog wearing a grafted
  // own-wallet variant is stripped the moment it is touched) — see healThreadWalletVariantConflict.
  const healed = (thread) => (thread ? healThreadWalletVariantConflict(thread, peerRaw) : null);
  const byId = healed(threads.find((thread) => thread.id === newThread.id));
  if (byId) return byId;
  const byVariant = healed(findThreadByIdentityVariants(threads, threadIdentityVariants(newThread)));
  if (byVariant) return byVariant;
  if (newWallet) {
    const byWallet = healed(threads.find((thread) => {
      const wallet = ownerWalletFromThread(thread);
      return wallet && sameWalletAddress(wallet, newWallet);
    }));
    if (byWallet) return byWallet;
  }
  return null;
}

function selectOrCreateRecipientThread(input, options = {}) {
  const result = createRecipientThread(input, options);
  if (!result.ok) return result;
  const existing = findExistingRecipientThread(result.thread);
  if (existing) {
    if (result.thread.localLabel) {
      existing.localLabel = result.thread.localLabel;
      existing.displayIdentity = null;
      existing.name = result.thread.name;
      existing.avatar = result.thread.avatar;
      existing.subtitle = result.thread.subtitle;
      persistThreadDisplayPreference(existing);
    } else {
      // Addressed by a specific identity (e.g. "admin") that resolved to an existing contact's wallet. Record that
      // username among the contact's known identities (the "Display as" list) even though we've never received from
      // it — and, for a username (not a raw wallet address), switch the dialog's display to it, so addressing
      // "admin" doesn't drop you into a dialog still labelled "plato".
      const addressedVariants = threadIdentityVariants(result.thread);
      if (addressedVariants.length > 0) refreshThreadIdentityFromVariants(existing, addressedVariants);
      const addressedIdentity = primaryThreadIdentity(result.thread);
      if (addressedIdentity && addressedIdentity.type !== RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) {
        existing.displayIdentity = addressedIdentity;
        applyThreadDisplayFields(existing);
        syncThreadDisplayToContactStore(existing);
        persistThreadDisplayPreference(existing);
      }
    }
    activeThreadId = existing.id;
  } else {
    // Stamp creation time: a just-added (still message-less) dialog sorts to the TOP of the recency-ordered list
    // (threadLastActivityMs falls back to this) instead of sinking below every old chat.
    result.thread.createdAtMs = Date.now();
    threads.push(result.thread);
    activeThreadId = result.thread.id;
  }
  appShell.dataset.chatOpen = 'true';
  closeNewChatDialog();
  hydrateThreadAvatarFromPointer(
    threads.find((thread) => thread.id === activeThreadId),
    ownerWalletFromThread(threads.find((thread) => thread.id === activeThreadId)),
    null,
  ).catch((error) => console.error(error));
  renderThreads();
  renderConversation();
  return { ok: true };
}

function readCustomPublicChannels() {
  try {
    const parsed = JSON.parse(localStorageOrNull()?.getItem(PUBLIC_CUSTOM_CHANNELS_STORAGE_KEY) ?? '[]');
    if (!Array.isArray(parsed) || parsed.length === 0) return [];
    const candidates = parsed.filter((item) => (
      item
      && typeof item === 'object'
      && item.id
      && (item.sourceUrl || item.authorWallet || item.author_wallet)
    ));
    return candidates.length > 0 ? normalizePublicChannelRegistry(candidates) : [];
  } catch {
    return [];
  }
}

function writeCustomPublicChannels() {
  try {
    localStorageOrNull()?.setItem(PUBLIC_CUSTOM_CHANNELS_STORAGE_KEY, JSON.stringify(customPublicChannels));
  } catch {
    // Non-persistent mode still keeps custom channels in memory for this tab.
  }
}

function publicChannelMatchesAuthorWallet(channel, authorWallet) {
  const channelWallet = channel?.authorWallet ?? channel?.author_wallet;
  if (!channelWallet || !authorWallet) return false;
  return sameWalletAddress(channelWallet, authorWallet)
    || String(channelWallet) === String(authorWallet);
}

function rebuildPublicChannelRegistry() {
  const baseChannels = normalizePublicChannelRegistry(basePublicChannelRegistry);
  const customChannels = normalizePublicChannelRegistry(customPublicChannels)
    .filter((channel) => !baseChannels.some((base) => publicChannelMatchesAuthorWallet(base, channel.authorWallet)));
  publicChannelRegistry = normalizePublicChannelRegistry([...baseChannels, ...customChannels])
    .map(applyContactDisplayToRegistryChannel);
  return publicChannelRegistry;
}

// Overlay the user's chosen display name (from the shared per-counterparty store) onto a wallet
// channel so the Public channels list, channel detail header, and feed all show the SAME name the
// Private dialog shows. name/avatar survive the registry re-normalization in
// subscribedPublicChannels(); identity tone is re-resolved at render time. The official platho.app
// channel keeps its brand name.
function applyContactDisplayToRegistryChannel(channel) {
  if (!channel?.authorWallet || channel.id === DEFAULT_PUBLIC_CHANNEL_ID) return channel;
  const display = resolveWalletChannelDisplay(channel.authorWallet);
  // An explicit display choice wins; otherwise fall back to the channel's own name made canonical (no ".ath"),
  // so even a registry name persisted/added with the suffix is shown bare everywhere it propagates (feed author,
  // channels list, channel-detail header, and the thread.name the public-feed module derives from it).
  const name = display?.name || canonicalUsernameDisplay(channel.name);
  if (!name || name === channel.name) return channel;
  return {
    ...channel,
    name,
    avatar: publicChannelAvatar(name),
  };
}

function publicChannelAvatar(label) {
  return String(label ?? 'P').trim().slice(0, 1).toUpperCase() || 'P';
}

function publicChannelSubtitleForIdentity(identity) {
  if (identity?.type === RECIPIENT_IDENTITY_TYPES.PLATHO_NFT) return 'Platho NFT public channel';
  if (identity?.type === RECIPIENT_IDENTITY_TYPES.TON_DNS) return 'TON DNS public channel';
  return 'wallet public channel';
}

function publicChannelRouteLabel(identity, authorWallet) {
  if (identity?.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) return shortAddress(authorWallet ?? identity.value);
  return canonicalUsernameDisplay(identity?.label) || shortAddress(authorWallet);
}

async function resolvePublicChannelIdentity(input) {
  const parsed = parseRecipientIdentity(input);
  if (!parsed.ok) throw new Error(parsed.error);
  const { identity } = parsed;

  if (identity.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) {
    return {
      identity,
      authorWallet: requireBasechainAddress(identity.value, 'Public channel author'),
    };
  }

  if (identity.type === RECIPIENT_IDENTITY_TYPES.PLATHO_NFT) {
    const resolved = await resolvePlathoUsernameOwner(identity.value);
    return {
      identity,
      authorWallet: requireBasechainAddress(resolved.ownerWallet, 'Public channel author'),
    };
  }

  if (identity.type === RECIPIENT_IDENTITY_TYPES.TON_DNS) {
    const provider = await resolveTonDnsProvider();
    if (!provider?.resolveWallet) throw new Error('TON DNS provider is not configured');
    const walletAddress = await provider.resolveWallet(identity.value, {
      rootAddress: appConfig.tonDns?.rootAddress ?? null,
      ...criticalChainReadOptions(),
    });
    return {
      identity,
      authorWallet: requireBasechainAddress(walletAddress, 'Public channel author'),
    };
  }

  throw new Error('Unsupported public channel identity');
}

function openPrivateThreadForWallet(walletAddress) {
  const result = selectOrCreateRecipientThread(walletAddress);
  if (!result.ok) {
    setPublicStatus(result.error ?? 'private chat unavailable');
    return false;
  }
  setView('chats');
  appShell.dataset.chatOpen = 'true';
  renderThreads();
  renderConversation();
  return true;
}

function addCustomPublicChannel(channel) {
  const normalized = normalizePublicChannelRegistry([channel]).find((item) => item.id === channel.id);
  if (!normalized) throw new Error('Channel needs an author wallet or feed URL');
  customPublicChannels = normalizePublicChannelRegistry([
    ...customPublicChannels.filter((item) => item.id !== normalized.id),
    normalized,
  ]);
  writeCustomPublicChannels();
  rebuildPublicChannelRegistry();
  const subscribedById = new Map((publicChannelSubscriptions?.channels ?? []).map((item) => [item.id, item]));
  subscribedById.set(normalized.id, { id: normalized.id, subscribed: true });
  publicChannelSubscriptions = {
    version: publicChannelSubscriptions?.version ?? 1,
    activeChannelId: normalized.id,
    channels: publicChannelRegistry.map((item) => ({
      id: item.id,
      subscribed: subscribedById.get(item.id)?.subscribed === true,
    })),
  };
  writePublicChannelSubscriptions(publicChannelStorage(), publicChannelSubscriptions);
  rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
  renderPublicSurface();
  resyncPublicForNewSubscription();
  markPrefsDirty();
}

// A newly-followed channel does NOT change the GLOBAL public latest id, so the sync fast-path (latestId unchanged ->
// skip the whole walk) would leave the channel on "Waiting for public feed" until a page reload reset the in-memory
// cursor. Invalidate the fast-path and kick a sync now so the new channel's posts load immediately.
function resyncPublicForNewSubscription() {
  invalidatePublicSyncFastPath();
  syncPublicChannels().catch((error) => { noteTonRpcRateLimit(error); });
}

function isPublicChannelSubscribed(channelId) {
  const id = String(channelId ?? '').trim();
  if (!id) return false;
  return (publicChannelSubscriptions?.channels ?? []).some((item) => item.id === id && item.subscribed === true);
}

function setPublicChannelSubscribed(channelId, subscribed) {
  const id = String(channelId ?? '').trim();
  if (!id) return false;
  const subscribedById = new Map((publicChannelSubscriptions?.channels ?? []).map((item) => [item.id, item]));
  subscribedById.set(id, { id, subscribed: subscribed === true });
  const channels = publicChannelRegistry.map((item) => ({
    id: item.id,
    subscribed: subscribedById.get(item.id)?.subscribed === true,
  }));
  const nextActive = subscribed === false && publicChannelSubscriptions?.activeChannelId === id
    ? channels.find((item) => item.subscribed)?.id ?? null
    : publicChannelSubscriptions?.activeChannelId ?? channels.find((item) => item.subscribed)?.id ?? null;
  publicChannelSubscriptions = {
    version: publicChannelSubscriptions?.version ?? 1,
    activeChannelId: nextActive,
    channels,
  };
  writePublicChannelSubscriptions(publicChannelStorage(), publicChannelSubscriptions);
  // preserveActive: TRUE. Following/unfollowing a public channel must NOT hijack the active PRIVATE dialog. With
  // preserveActive:false this reset activeThreadId to threads[0] (always the Saved "My notes" thread), and the
  // add-contact flow (selectOrCreateRecipientThread(peer) -> followContactPublicChannel(peer) -> here) then grafted
  // the peer's identity onto Saved and sent the first message into "My notes" — the root of "I write to glasnost but
  // it lands in my notes". preserveActive:true keeps the peer dialog selected (or, if the selection genuinely
  // vanished, drops to the LIST — never silently to Saved).
  rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
  renderPublicSurface({ anchorUnread: false });
  setPublicStatus(subscribed ? 'channel followed' : 'channel hidden');
  // Following a channel must pull its posts NOW (the fast-path would otherwise skip the walk until a reload).
  if (subscribed) resyncPublicForNewSubscription();
  markPrefsDirty();
  return true;
}

function readPublicReadCursors() {
  try {
    const parsed = JSON.parse(localStorageOrNull()?.getItem(scopedStorageKey(PUBLIC_READ_CURSORS_STORAGE_KEY)) ?? '{}');
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function writePublicReadCursors() {
  try {
    localStorageOrNull()?.setItem(scopedStorageKey(PUBLIC_READ_CURSORS_STORAGE_KEY), JSON.stringify(publicReadCursors));
  } catch {
    // Non-persistent mode still keeps read state for the current tab.
  }
}

function publicEntryIdBigInt(value) {
  if (value === undefined || value === null || value === '') return null;
  try {
    const bigint = BigInt(value);
    return bigint >= 0n ? bigint : null;
  } catch {
    return null;
  }
}

function publicChannelCursor(channelId) {
  return publicEntryIdBigInt(publicReadCursors?.[channelId]) ?? -1n;
}

function isUnreadPublicItem(item) {
  const entryId = publicEntryIdBigInt(item?.readEntryId ?? item?.entryId);
  if (entryId === null) return false;
  return entryId > publicChannelCursor(item.channelId ?? 'platho.app');
}

function publicFeedItemsChronological() {
  return publicChannelThreadsToFeedItems(publicChannelThreads).slice().reverse();
}

function publicUnreadCount(channelId) {
  let count = 0;
  for (const item of publicFeedItemsChronological()) {
    if (item.channelId !== channelId) continue;
    if (isUnreadPublicItem(item)) count += 1;
  }
  return count;
}

function markVisiblePublicFeedRead(items = publicFeedItemsChronological()) {
  let changed = false;
  for (const item of items) {
    const entryId = publicEntryIdBigInt(item.readEntryId ?? item.entryId);
    if (entryId === null) continue;
    const channelId = item.channelId ?? 'platho.app';
    if (entryId > publicChannelCursor(channelId)) {
      publicReadCursors = {
        ...publicReadCursors,
        [channelId]: entryId.toString(),
      };
      changed = true;
    }
  }
  if (changed) writePublicReadCursors();
  return changed;
}

function publicFeedCacheForCurrentWindow() {
  const cutoffMs = publicSyncCutoffMs();
  if (cutoffMs === null) return publicChannelFeedCache;
  const out = {};
  for (const [channelId, record] of Object.entries(publicChannelFeedCache ?? {})) {
    const feed = record?.feed ?? record;
    if (!feed?.posts) {
      out[channelId] = record;
      continue;
    }
    const filteredFeed = {
      ...feed,
      posts: feed.posts
        .filter((post) => isFreshPublicTimestamp(post.createdAt, cutoffMs))
        .map((post) => ({
          ...post,
          comments: (post.comments ?? []).filter((comment) => isFreshPublicTimestamp(comment.createdAt, cutoffMs)),
        })),
    };
    out[channelId] = record?.feed ? { ...record, feed: filteredFeed } : filteredFeed;
  }
  return out;
}

function isPendingPublicFeedItem(item) {
  return Boolean(item?.publishStatus && (item.entryId === undefined || item.entryId === null || item.entryId === ''));
}

function samePublicBodyHash(left, right) {
  const a = String(left?.bodyHash ?? '').toLowerCase();
  const b = String(right?.bodyHash ?? '').toLowerCase();
  return Boolean(a && b && a === b);
}

function mergeLocalPendingPublicFeed(channelId, chainPosts = []) {
  const cached = publicChannelFeedCache?.[channelId]?.feed ?? publicChannelFeedCache?.[channelId] ?? null;
  const localPosts = Array.isArray(cached?.posts) ? cached.posts : [];
  const merged = chainPosts.map((post) => {
    const matchingLocal = localPosts.filter((local) => (
      samePublicBodyHash(local, post)
      || (local.entryId && post.entryId && String(local.entryId) === String(post.entryId))
    ));
    const chainComments = post.comments ?? [];
    const pendingComments = matchingLocal
      .flatMap((local) => local.comments ?? [])
      .filter((comment) => isPendingPublicFeedItem(comment))
      .filter((comment) => !chainComments.some((chainComment) => samePublicBodyHash(comment, chainComment)));
    return pendingComments.length > 0
      ? { ...post, comments: [...chainComments, ...pendingComments] }
      : post;
  });
  const pendingPosts = localPosts
    .filter((post) => isPendingPublicFeedItem(post))
    .filter((post) => !chainPosts.some((chainPost) => samePublicBodyHash(post, chainPost)));
  return [...merged, ...pendingPosts]
    .sort((a, b) => new Date(a.createdAt ?? 0).getTime() - new Date(b.createdAt ?? 0).getTime());
}

function updatePublicJumpDownVisibility() {
  if (!publicJumpDownButton || !publicFeed) return;
  const maxScroll = Math.max(0, publicFeed.scrollHeight - publicFeed.clientHeight);
  // Newest is at the TOP now (v752): the jump-to-newest affordance shows once the user has scrolled DOWN
  // (away from the top) into older posts.
  const awayFromNewest = publicFeed.scrollTop > 80;
  publicJumpDownButton.hidden = !(maxScroll > 24 && awayFromNewest);
}

function updatePublicModeButtons() {
  // Public has a single view now (the Feed). Keep the dataset.publicMode='feed' marker so the feed-only CSS
  // ([data-public-mode="feed"]) keeps matching.
  if (publicPane) publicPane.dataset.publicMode = 'feed';
  if (publicChannelSearch) publicChannelSearch.placeholder = t('public.searchPlaceholder');
  updatePublicJumpDownVisibility();
  if (publicComposer) publicComposer.hidden = false;
}

function publicFeedItemMatchesSearch(item, query) {
  const needle = String(query ?? '').trim().toLowerCase();
  if (!needle) return true;
  const channel = publicChannelRegistry.find((entry) => entry.id === item.channelId) ?? null;
  const blockText = (blocks = []) => (blocks ?? [])
    .filter((block) => block?.type === 'text')
    .map((block) => block.text ?? '');
  const haystack = [
    item.title,
    item.text,
    ...blockText(item.blocks),
    item.author,
    item.authorWallet,
    item.bodyHash,
    item.channelId,
    channel?.name,
    channel?.subtitle,
    channel?.authorWallet,
    ...(item.meta ?? []),
    ...((item.comments ?? []).flatMap((comment) => [
      comment.author,
      comment.authorWallet,
      comment.text,
      ...blockText(comment.blocks),
    ])),
  ].filter(Boolean).join(' ').toLowerCase();
  return haystack.includes(needle);
}

function renderPublicEmpty(titleText, bodyText) {
  if (!publicFeed) return;
  const empty = document.createElement('article');
  empty.className = 'feed-item compact';
  const title = document.createElement('h2');
  title.textContent = titleText;
  const text = document.createElement('p');
  text.textContent = bodyText;
  empty.append(title, text);
  publicFeed.append(empty);
}

// Parity with the private .message-image affordance: a public feed/comment image is keyboard-focusable and opens
// the SAME full-size lightbox (delegated click/keydown on publicPane). Meta (dimensions + approx on-chain byte
// size, derivable from the data URL's base64 length) fills in once the image decodes.
function wirePublicImageLightbox(image, src) {
  image.alt = t('public.openImage');
  image.tabIndex = 0;
  image.role = 'button';
  image.title = t('public.openFullSizeImage');
  image.dataset.fullImageSrc = src;
  image.dataset.fullImageMeta = t('public.publicImage');
  image.addEventListener('load', () => {
    const base64 = String(src).split(',')[1] ?? '';
    const bytes = Math.floor(base64.length * 3 / 4);
    const dimensions = image.naturalWidth > 0 ? `${image.naturalWidth}x${image.naturalHeight}` : '';
    image.dataset.fullImageMeta = [dimensions, bytes > 0 ? imageByteCountLabel(bytes) : '']
      .filter(Boolean).join(' - ') || t('public.publicImage');
  }, { once: true });
}

function appendPublicItemContent(container, item) {
  const blocks = Array.isArray(item?.blocks) ? item.blocks : [];
  if (blocks.length > 0) {
    for (const block of blocks) {
      if (block?.type === 'reply') {
        // Reply quote strip (tappable — scrolls to the quoted comment within the open post detail).
        container.append(buildReplyQuoteNode(block, publicPostDetailBody));
      } else if (block?.type === 'text' && block.text) {
        // v769: a DIV (not <p>) so the formatting renderer can emit block children (heading/list/quote) validly.
        const text = document.createElement('div');
        text.className = 'feed-block-text';
        appendFormattedMessageText(text, block.text);
        container.append(text);
      } else if (block?.type === 'image' && block.url) {
        const image = document.createElement('img');
        image.className = 'feed-image feed-block-image';
        image.src = block.url;
        image.loading = 'lazy';
        wirePublicImageLightbox(image, block.url);
        container.append(image);
      } else if (block?.type === 'file' && block.url) {
        // Receive-side forward-compat (v652): the public composer has no file attach UI yet, but a FILE block
        // arriving on the public surface renders the same download chip as private bubbles.
        container.append(buildFileBlockChip(block));
      } else if (block?.type === 'share' && block.entryId) {
        // Shared public post (v766): the embed card with the source channel's header.
        container.append(buildSharedPostEmbed(block));
      }
    }
    return;
  }
  if (item?.text) {
    const text = document.createElement('div');
    text.className = 'feed-block-text';
    appendFormattedMessageText(text, item.text);
    container.append(text);
  }
  if (item?.imageUrl) {
    const image = document.createElement('img');
    image.className = 'feed-image';
    image.src = item.imageUrl;
    image.loading = 'lazy';
    wirePublicImageLightbox(image, item.imageUrl);
    container.append(image);
  }
}

function appendPublicItemComments(article, item) {
  const comments = Array.isArray(item?.comments) ? item.comments : [];
  if (comments.length === 0) return;
  const commentList = document.createElement('div');
  commentList.className = 'comment-list';
  for (const comment of comments) {
    const row = document.createElement('article');
    row.className = 'comment-item';
    // Chain anchor (parity with private .message rows): the swipe-to-reply gesture reads it as the reply ref and
    // reply quotes scroll to it. A local-pending comment has none — replying to it waits for the entry id.
    if (comment.entryId !== undefined && comment.entryId !== null && comment.entryId !== '') row.dataset.entryId = String(comment.entryId);
    const commentAuthorRow = document.createElement('div');
    commentAuthorRow.className = 'feed-author-row';
    const commentAvatar = document.createElement('div');
    commentAvatar.className = 'avatar feed-avatar';
    commentAvatar.setAttribute('aria-hidden', 'true');
    setAvatarNode(commentAvatar, String(comment.author ?? 'P').slice(0, 1), comment.avatarImageUrl ?? publicAvatarUrlForWallet(comment.authorWallet));
    const commentMeta = document.createElement('div');
    commentMeta.className = 'feed-meta';
    commentMeta.textContent = [comment.author, comment.createdAt?.slice?.(0, 10)].filter(Boolean).join(' - ');
    // Own pending comments show the SAME live private-style status badge as feed posts (publishStateMeta off
    // the streaming publishState; durable red on a failed terminal). CSS classes only (prod CSP).
    if (isPendingPublicFeedItem(comment) && comment.publishStatus) {
      const statusBadge = document.createElement('span');
      statusBadge.className = `public-publish-status${String(comment.publishStatus).endsWith('failed') ? ' public-publish-status--failed' : ''}`;
      statusBadge.textContent = (comment.publishState ? publishStateMeta(comment.publishState) : null) || comment.publishStatus;
      // Patch anchor for the status-only fast path (a publish tick updates this text in place, no rebuild).
      if (comment.id) statusBadge.dataset.publishLocalId = String(comment.id);
      wirePublicPublishRetryBadge(statusBadge, comment, 'comment');
      commentMeta.append(statusBadge);
    }
    commentAuthorRow.append(commentAvatar, commentMeta);
    row.append(commentAuthorRow);
    appendPublicItemContent(row, comment);
    appendRowReplyButton(row, beginPublicCommentReplyForRow);
    appendRowCopyButton(row, copyTextFromContent(comment));
    commentList.append(row);
  }
  article.append(commentList);
}

// Whether a public item is the logged-in user's OWN post. Falls back to the wallet address persisted in
// storage (record.address is plaintext — no decryption needed) so ownership is known from the FIRST public
// render, before the full wallet finishes loading. Without the fallback plathoWallet is briefly null at boot,
// so a user's own posts flash the author-only actions (the ▼ "Display as" chevron, "Private chat", "Unfollow")
// that only make sense for OTHER authors, until a later sync re-render corrects them.
function isOwnPublicAuthor(authorWallet) {
  if (!authorWallet) return false;
  const ownAddress = plathoWallet?.address ?? storedPlathoWalletRecord()?.address ?? null;
  return Boolean(ownAddress && sameWalletAddress(authorWallet, ownAddress));
}

// The "Display as" chevron for a public post — relabel another author (.ath / local name), shared
// per-counterparty and in sync with their Private dialog. Returns null for your own post, the official
// platho.app channel, or an item with no author wallet. Lives top-right in the post's author row in BOTH Feed
// and Channels modes (the channel-detail header no longer carries it).
function publicItemIdentityButton(item) {
  const authorWallet = item.authorWallet ?? item.author_wallet ?? null;
  const isOwnPost = isOwnPublicAuthor(authorWallet);
  if (!authorWallet || isOwnPost || item.channelId === DEFAULT_PUBLIC_CHANNEL_ID) return null;
  const identityButton = document.createElement('button');
  identityButton.type = 'button';
  identityButton.className = 'icon-button feed-author-identity';
  identityButton.setAttribute('aria-haspopup', 'menu');
  identityButton.setAttribute('aria-expanded', 'false');
  identityButton.title = t('public.chooseDisplayName');
  const identityIcon = document.createElement('span');
  identityIcon.className = 'icon icon-chevron-down';
  identityButton.append(identityIcon);
  identityButton.addEventListener('click', (event) => {
    event.stopPropagation();
    if (identityPopover && !identityPopover.hidden) {
      hideIdentityPopover();
    } else {
      showPublicChannelDisplayPopover({ authorWallet }, identityButton);
    }
  });
  return identityButton;
}

// The channel-description ("about") button for the post plate: an info glyph that opens the channel's PROFILE
// (description + tags) popover. Shown for any post with an author wallet — including the user's OWN channel and
// the official channel — since every channel can carry a description (the popover offers edit for own channels).
function publicItemDescriptionButton(item) {
  const authorWallet = item.authorWallet ?? item.author_wallet ?? null;
  if (!authorWallet) return null;
  const isOwn = isOwnPublicAuthor(authorWallet);
  const aboutButton = document.createElement('button');
  aboutButton.type = 'button';
  aboutButton.className = 'icon-button feed-author-about';
  aboutButton.setAttribute('aria-haspopup', 'dialog');
  aboutButton.setAttribute('aria-expanded', 'false');
  aboutButton.title = t('public.channelAbout');
  aboutButton.append(createChannelAboutIcon());
  aboutButton.addEventListener('click', (event) => {
    event.stopPropagation();
    if (identityPopover && !identityPopover.hidden && identityPopoverAnchor === aboutButton) {
      hideIdentityPopover();
    } else {
      showChannelDescriptionPopover(authorWallet, aboutButton, { isOwn }).catch((error) => console.error(error));
    }
  });
  return aboutButton;
}

function appendPublicItemActions(article, item) {
  const actions = document.createElement('div');
  actions.className = 'feed-actions';
  // A followed channel with no posts yet has nothing to comment on — skip the disabled "Preview only" button so
  // its card shows just Private chat + Unfollow (the Unfollow being the clear action for an empty channel).
  if (!item.emptyChannel) {
    const commentButton = document.createElement('button');
    commentButton.type = 'button';
    const commentsAllowed = item.commentsAllowed !== false;
    const hasChainCommentTarget = item.entryId !== undefined
      && item.entryId !== null
      && /^0x[0-9a-fA-F]{64}$/.test(String(item.bodyHash ?? ''));
    // Viewing comments needs no wallet — only an on-chain post to load them from. Posting a comment still
    // requires a wallet (enforced by the post detail composer). "Comments off" / "Preview only" stay disabled.
    const canViewComments = Boolean(commentsAllowed && hasChainCommentTarget);
    if (!commentsAllowed) {
      commentButton.textContent = t('public.commentsOff');
    } else if (!hasChainCommentTarget) {
      commentButton.textContent = t('public.previewOnly');
    } else {
      commentButton.textContent = t('public.comments');
    }
    commentButton.disabled = !canViewComments;
    commentButton.title = !commentsAllowed
      ? t('public.commentsClosedByAuthor')
      : (!hasChainCommentTarget
          ? t('public.previewNotOnChain')
          : t('public.openCommentsForPost'));
    commentButton.addEventListener('click', () => {
      if (!canViewComments) return;
      openPublicPostDetail(item);
    });
    // Pre-warm this post's durable comments (with images) into memory so opening it is instant + flash-free —
    // the private-message model (messages restored to memory before a thread opens). Only for openable posts.
    if (canViewComments) warmPublicPostCommentsCache(item);
    actions.append(commentButton);
  }

  const authorWallet = item.authorWallet ?? item.author_wallet ?? null;
  const isOwnPost = isOwnPublicAuthor(authorWallet);

  // "Share" (v766) — forward this post into My notes / a private contact / the own channel. Needs the post's
  // chain coordinates (same gate the share payload builder enforces): a local-pending post can't be shared yet.
  if (sharePayloadFromPublicItem(item)) {
    const shareButton = document.createElement('button');
    shareButton.type = 'button';
    shareButton.textContent = t('public.share');
    shareButton.title = t('public.sharePostTitle');
    shareButton.addEventListener('click', () => openSharePostDialog(item));
    actions.append(shareButton);
  }

  // "Private chat" — open the author in Private. HIDDEN on your own post: a dialog with yourself is meaningless.
  if (!isOwnPost) {
    const privateButton = document.createElement('button');
    privateButton.type = 'button';
    privateButton.textContent = t('public.privateChat');
    privateButton.disabled = !authorWallet;
    privateButton.title = authorWallet
      ? t('public.openAuthorInPrivate')
      : t('public.authorWalletUnavailable');
    privateButton.addEventListener('click', () => {
      if (!authorWallet) return;
      openPrivateThreadForWallet(authorWallet);
    });
    actions.append(privateButton);
  }

  // "Unfollow" — moved here from the channel-detail header so it sits with the post actions in BOTH Feed and
  // Channels modes. Shown only when the post's channel is currently subscribed (so it is actionable) AND it is not
  // the user's own post: publishing in Channels mode auto-subscribes the OWN channel (ensurePublicChannelForAuthorWallet
  // activate:true), so without the !isOwnPost guard Unfollow would wrongly appear on the user's own posts.
  if (!isOwnPost && isPublicChannelSubscribed(item.channelId)) {
    const unfollowButton = document.createElement('button');
    unfollowButton.type = 'button';
    unfollowButton.textContent = t('public.unfollow');
    unfollowButton.title = t('public.stopFollowingChannel');
    unfollowButton.addEventListener('click', () => {
      // Unfollowing from a card INSIDE the open channel view keeps the view's posts visible (the channel becomes
      // a transient preview source) — the same protocol as the header unfollow; without it the open screen
      // flips to a false "No posts yet".
      if (publicChannelViewOpen && publicChannelViewChannelId === item.channelId) {
        publicChannelPreviewChannelId = item.channelId;
      }
      setPublicChannelSubscribed(item.channelId, false);
    });
    actions.append(unfollowButton);
  }
  article.append(actions);
}

// ---- Share a public post (v766): into My notes / a private contact / the own channel ----
// The modal picks the TARGET; choosing navigates to that composer surface with the share draft attached (a
// cancellable chip + a positional [post] marker). The draft is a SNAPSHOT (entryId + bodyHash + author wallet +
// title/text excerpt) — the send encodes it as a SHARE document block.
let pendingSharePayload = null;

function sharePayloadFromPublicItem(item) {
  // Chain coordinates are REQUIRED (same gate as commenting): a local-pending post has no entryId yet.
  if (item?.entryId === undefined || item?.entryId === null) return null;
  if (!/^0x[0-9a-fA-F]{64}$/.test(String(item?.bodyHash ?? ''))) return null;
  const authorWallet = rawWalletAddress(item.authorWallet);
  if (!authorWallet) return null;
  const blocks = Array.isArray(item.blocks) ? item.blocks : [];
  const fullText = (blocks
    .filter((block) => block?.type === 'text' && String(block.text ?? '').trim())
    .map((block) => String(block.text).trim())
    .join('\n\n') || String(item.text ?? '')).trim();
  // Truncate at DRAFT time (not just at encode) so the optimistic echo shows exactly what the wire carries.
  const snippet = truncateUtf8ToShareSnippet(fullText);
  return {
    entryId: String(item.entryId),
    bodyHash: String(item.bodyHash),
    authorWallet,
    author: String(item.author ?? '').trim() || publicAuthorLabel(authorWallet) || shortAddress(authorWallet),
    title: String(item.title ?? ''),
    snippet,
    fullText, // untruncated — used by the "copy to clipboard" share target (the wire SHARE block still uses snippet)
    hasImage: blocks.some((block) => block?.type === 'image' && block.url) || Boolean(item.imageUrl),
    textTruncated: snippet.length < fullText.length,
  };
}

// UTF-8-safe byte-bounded cut for the share snippet (matches the codec's truncateUtf8ToBytes semantics).
function truncateUtf8ToShareSnippet(text) {
  const value = String(text ?? '');
  const encoder = new TextEncoder();
  if (encoder.encode(value).length <= SHARE_SNIPPET_MAX_BYTES) return value;
  // Byte length >= char count, so a char-cut to the byte budget lands close; then trim to the exact bound.
  let out = value.slice(0, SHARE_SNIPPET_MAX_BYTES);
  while (out.length > 0 && encoder.encode(out).length > SHARE_SNIPPET_MAX_BYTES) out = out.slice(0, -1);
  return out;
}

function openSharePostDialog(item) {
  const share = sharePayloadFromPublicItem(item);
  if (!share) return;
  pendingSharePayload = share;
  renderSharePostList();
  if (sharePostDialog) sharePostDialog.hidden = false;
}

function closeSharePostDialog() {
  pendingSharePayload = null;
  if (sharePostDialog) sharePostDialog.hidden = true;
}

// Clipboard-copy glyph for the "copy to clipboard" share target (same inline-SVG style as the Saved pencil).
const SHARE_COPY_ICON_SVG =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
  + '<rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>';

function buildShareTargetRow({ label, sublabel, avatarUrl, thread, icon, onChoose }) {
  const row = document.createElement('button');
  row.type = 'button';
  row.className = 'share-target-row';
  const avatar = document.createElement('div');
  avatar.className = 'avatar share-target-avatar';
  avatar.setAttribute('aria-hidden', 'true');
  if (thread) {
    setThreadAvatarNode(avatar, thread); // Saved (My notes) -> its pencil icon, not the wallet-letter avatar
  } else if (icon === 'copy') {
    avatar.classList.add('avatar-saved'); // reuse the icon-tinted avatar look
    avatar.innerHTML = SHARE_COPY_ICON_SVG;
  } else {
    setAvatarNode(avatar, String(label ?? 'P').slice(0, 1), avatarUrl);
  }
  const text = document.createElement('span');
  text.className = 'share-target-text';
  const name = document.createElement('span');
  name.className = 'share-target-name';
  name.textContent = label;
  text.append(name);
  if (sublabel) {
    const sub = document.createElement('span');
    sub.className = 'share-target-sublabel';
    sub.textContent = sublabel;
    text.append(sub);
  }
  row.append(avatar, text);
  row.addEventListener('click', onChoose);
  return row;
}

function renderSharePostList() {
  if (!sharePostList) return;
  sharePostList.replaceChildren();
  // Order (owner v793): Copy to clipboard, then My notes, then the own public channel, then private contacts by recency.
  sharePostList.append(buildShareTargetRow({
    label: t('dialog.shareCopyToClipboard'),
    icon: 'copy',
    onChoose: () => chooseShareCopyToClipboard(),
  }));
  const ownWallet = rawWalletAddress(plathoWallet?.address ?? storedPlathoWalletRecord()?.address);
  const own = ownPublicChannel();
  const visible = threads.filter((thread) => !thread.readOnly && !isTransientPendingResolutionThread(thread));
  // My notes (Saved) first — with its pencil icon, not the wallet-letter avatar.
  for (const thread of visible.filter((thread) => isSavedMessagesThread(thread))) {
    const wallet = threadPrimaryWalletRaw(thread);
    if (!wallet) continue;
    sharePostList.append(buildShareTargetRow({
      label: t('chat.myNotes'),
      thread,
      onChoose: () => chooseShareTargetThread(thread),
    }));
  }
  // Then the own public channel (a repost).
  if (own && ownWallet) {
    sharePostList.append(buildShareTargetRow({
      label: t('dialog.shareToOwnChannel'),
      sublabel: t('public.you'),
      avatarUrl: publicAvatarUrlForWallet(ownWallet),
      onChoose: () => chooseShareTargetOwnChannel(),
    }));
  }
  // Then private contacts by recency.
  const contacts = visible
    .filter((thread) => !isSavedMessagesThread(thread))
    .sort((a, b) => threadLastActivityMs(b) - threadLastActivityMs(a));
  for (const thread of contacts) {
    const wallet = threadPrimaryWalletRaw(thread);
    if (!wallet) continue;
    sharePostList.append(buildShareTargetRow({
      label: thread.name || shortAddress(wallet),
      sublabel: shortAddress(wallet),
      avatarUrl: publicAvatarUrlForWallet(wallet),
      onChoose: () => chooseShareTargetThread(thread),
    }));
  }
}

function insertShareMarker(textarea) {
  if (!textarea) return;
  COMPOSER_SHARE_MARKER_RE.lastIndex = 0;
  if (COMPOSER_SHARE_MARKER_RE.test(String(textarea.value ?? ''))) return;
  insertComposerMarker(textarea, '[post]');
}

function chooseShareTargetThread(thread) {
  const share = pendingSharePayload;
  closeSharePostDialog();
  const wallet = threadPrimaryWalletRaw(thread);
  if (!share || !wallet) return;
  // The canonical open path (selectOrCreateRecipientThread) — matches by identity variants, so Saved and every
  // existing dialog resolve to their real thread; view + chatOpen handled inside.
  if (!openPrivateThreadForWallet(wallet)) return;
  setPrivateShareDraft(share);
  insertShareMarker(messageInput);
  if (messageInput && !messageInput.disabled) messageInput.focus();
}

function chooseShareTargetOwnChannel() {
  const share = pendingSharePayload;
  closeSharePostDialog();
  const own = ownPublicChannel();
  if (!share || !own) return;
  setView('public');
  openPublicChannelView({ channelId: own.id, authorWallet: rawWalletAddress(plathoWallet?.address ?? storedPlathoWalletRecord()?.address) });
  setPublicShareDraft(share);
  insertShareMarker(publicMessageInput);
  if (publicMessageInput && !publicMessageInput.disabled) publicMessageInput.focus();
}

// Copy the shared post's text to the clipboard (title + the UNTRUNCATED body) — a plain "take it elsewhere" affordance.
function chooseShareCopyToClipboard() {
  const share = pendingSharePayload;
  closeSharePostDialog();
  if (!share) return;
  const text = [String(share.title ?? '').trim(), String(share.fullText ?? '').trim()].filter(Boolean).join('\n\n');
  copyTextToClipboard(text)
    .then(() => setPublicStatus(t('dialog.shareCopied')))
    .catch((error) => { console.error(error); setPublicStatus(t('dialog.shareCopyFailed')); });
}

sharePostCloseButton?.addEventListener('click', () => closeSharePostDialog());
// v794: X-only — the share dialog closes ONLY via its ✕ (an outside/backdrop tap no longer dismisses it).

function renderPublicFeed(items, options = {}) {
  if (!publicFeed) return;
  publicFeed.dataset.publicMode = 'feed';
  const allItems = items ?? [];
  if (allItems.length === 0) {
    publicFeed.replaceChildren();
    // The discovery CTA sits at the very top for a newcomer (no channels followed) — shown ABOVE the posts, and also
    // above the empty-state so a newcomer with a truly empty feed still gets a way in.
    if (shouldShowDiscoveryCta()) publicFeed.append(buildDiscoveryCtaCard());
    renderPublicEmpty(publicChannelSearchQuery ? t('public.noPostsFound') : t('public.noPosts'), publicChannelSearchQuery ? t('public.tryAnotherSearch') : t('public.followOrPublishFirst'));
    requestAnimationFrame(updatePublicJumpDownVisibility);
    return;
  }
  // F2 cap (newest-first feed: newest at the TOP): render only the newest publicFeedShownCap items; the rest sit
  // behind a "show older" button at the BOTTOM. We do NOT grow the cap toward an old unread anymore: the feed lands on
  // the newest (top), so an old unread stays behind "show older" (still unread until actually revealed) instead of
  // forcing a full-history render on every open and marking an off-screen post read.
  const hiddenOlderCount = Math.max(0, allItems.length - publicFeedShownCap);
  const windowItems = hiddenOlderCount > 0 ? allItems.slice(hiddenOlderCount) : allItems;
  // Preserve the reader's position across a background (non-anchor) re-render: newest-first prepends new posts at the
  // TOP, which would shove a scrolled-down reader's content down (iOS/WebKit has no overflow-anchor). Snapshot the
  // topmost visible article + its viewport offset now, restore it after the DOM is rebuilt below. Skipped at the top
  // (scrollTop 0 -> new posts simply appear) and on an anchorUnread render (we jump to the newest instead).
  let scrollAnchor = null;
  if (!options.anchorUnread && publicFeed.scrollTop > 0) {
    const feedTop = publicFeed.getBoundingClientRect().top;
    for (const node of publicFeed.children) {
      if (!node.dataset?.itemId) continue;
      const nodeTop = node.getBoundingClientRect().top - feedTop;
      if (nodeTop + node.offsetHeight > 0) { scrollAnchor = { id: node.dataset.itemId, offset: nodeTop }; break; }
    }
  }
  // F2 keyed reconciliation (mirrors renderThreads): reuse each <article> whose render signature is unchanged since
  // the last render (the common case on a background sync — post content is immutable), building only new/changed
  // ones and removing/reordering the delta. This also keeps the scroll position stable (no replaceChildren flicker)
  // while the user is scrolled up reading, across the frequent background re-renders.
  const existing = new Map();
  for (const node of Array.from(publicFeed.children)) {
    const id = node.dataset?.itemId;
    // Keep the FIRST node per item id; drop non-item nodes (discovery CTA / show-older / empty-state, rebuilt below)
    // AND any DUPLICATE id — so a DOM a prior render left with duplicates self-heals to one node per item here.
    if (id && !existing.has(id)) existing.set(id, node);
    else node.remove();
  }
  const avatarUrlMemo = new Map();
  const seen = new Set();
  let prev = null;
  // The discovery CTA stays at the very top (a newcomer sees it first).
  if (shouldShowDiscoveryCta()) {
    const cta = buildDiscoveryCtaCard();
    if (cta !== publicFeed.firstChild) publicFeed.insertBefore(cta, publicFeed.firstChild);
    prev = cta;
  }
  // Newest-FIRST (v752, owner ask: newer posts on TOP): render the window REVERSED so newer posts sit at the top;
  // the "show older" button then goes at the BOTTOM (below the oldest rendered post). windowItems is oldest→newest.
  for (const item of windowItems.slice().reverse()) {
    const key = String(item.id);
    seen.add(key);
    const sig = publicFeedItemRenderSignature(item, avatarUrlMemo);
    let article = existing.get(key);
    if (article && article.dataset.sig !== sig) {
      // Signature changed -> the cached article is stale. REMOVE it before rebuilding, else the old node lingers as a
      // duplicate (the final cleanup only removes ids NOT in `seen`, and this id IS in seen for the rebuilt node).
      article.remove();
      existing.delete(key);
      article = null;
    }
    if (!article) {
      article = buildPublicFeedArticle(item, avatarUrlMemo);
      article.dataset.itemId = key;
      article.dataset.sig = sig;
      existing.set(key, article);
    }
    const anchor = prev ? prev.nextSibling : publicFeed.firstChild;
    if (article !== anchor) publicFeed.insertBefore(article, anchor);
    prev = article;
  }
  if (hiddenOlderCount > 0) {
    const older = buildShowOlderButton(hiddenOlderCount);
    const anchor = prev ? prev.nextSibling : publicFeed.firstChild;
    if (older !== anchor) publicFeed.insertBefore(older, anchor);
    prev = older;
  }
  for (const [id, node] of existing) if (!seen.has(id)) node.remove();
  if (options.anchorUnread && publicFeed) {
    // Fresh view: land on the newest, now at the TOP (the old chat-style feed anchored to the oldest unread instead).
    requestAnimationFrame(() => { publicFeed.scrollTop = 0; updatePublicJumpDownVisibility(); });
  } else if (scrollAnchor && publicFeed) {
    // Restore the anchored article to the same viewport offset so a new post added ABOVE doesn't shove the reader;
    // content added BELOW (via "show older") leaves the anchor put, so this is a no-op there.
    const feedTop = publicFeed.getBoundingClientRect().top;
    for (const node of publicFeed.children) {
      if (node.dataset?.itemId !== scrollAnchor.id) continue;
      const nodeTop = node.getBoundingClientRect().top - feedTop;
      publicFeed.scrollTop = Math.max(0, publicFeed.scrollTop + (nodeTop - scrollAnchor.offset));
      break;
    }
  }
  requestAnimationFrame(updatePublicJumpDownVisibility);
  // Viewing the feed marks its (rendered) posts read (only when the Public tab is actually on screen, so a
  // background sync does not pre-clear unread). NOT while an overlay (post detail / discovery / channel view)
  // covers the feed — it is display:none then and the user cannot see the posts being marked. Re-render once to
  // drop the unread badges.
  if (isPublicViewActive() && !publicPostDetailOpen && !publicDiscoveryOpen && !publicChannelViewOpen
    && markVisiblePublicFeedRead(windowItems)) {
    requestAnimationFrame(() => renderPublicSurface({ anchorUnread: false }));
  }
}

// --- Long-post collapse (feed + channel view, v765) ---
// A long post renders clamped to --feed-post-collapsed-max-height with a "Show full post" button; expanding
// releases the clamp IN PLACE (no re-render — content grows downward under the reader). Session-scoped by item
// id, so the signature-driven article rebuilds (unread -> read, identity changes, background syncs) re-render an
// expanded post EXPANDED instead of snapping it shut. Never persisted — a fresh session starts collapsed again.
const publicFeedExpandedPosts = new Set();
// A clamp that hides less than this many pixels is released silently instead of showing the button: a
// "Show full post" that reveals a two-line sliver is worse than just showing the two lines.
const FEED_POST_CLAMP_SLACK_PX = 120;
// One shared observer for every rendered post body. It watches the UNCLAMPED inner wrapper — once the clamp
// bites, the outer clamped box stays at max-height forever, so an observer bound to it would never fire when a
// lazy image decodes later and grows the content. scrollHeight (full content) vs clientHeight (clamped box) on
// the OUTER box then says whether the clamp actually cuts anything. Pre-ResizeObserver engines get null: the
// collapsible class is then never added, so nothing is ever clamped (fail-open to the full-height feed — a
// clamp with no way to ever show the expand button would silently cut content).
const feedPostClampObserver = typeof ResizeObserver === 'function' ? new ResizeObserver((entries) => {
  for (const entry of entries) {
    const body = entry.target.parentElement;
    // The collapsible ROOT is always the clamped body's parent — a feed <article> or a shared-post embed
    // (v766); the CSS clamp rules are direct-child (`.feed-post-collapsible > .feed-post-body`) so a nested
    // embed clamp never leaks into (or inherits from) the post clamp around it.
    const root = body ? body.parentElement : null;
    if (!body || !root || !root.classList.contains('feed-post-collapsible')) continue;
    const clippedHeight = body.scrollHeight - body.clientHeight;
    if (clippedHeight > FEED_POST_CLAMP_SLACK_PX) {
      root.classList.add('feed-post-overflowing');
    } else if (clippedHeight > 0) {
      // Near-miss: the clamp bites but hides less than the slack — release it with no button, so content is
      // never silently cut. Not added to publicFeedExpandedPosts (that set records USER intent); a rebuilt
      // article simply re-measures and re-releases.
      root.classList.remove('feed-post-collapsible', 'feed-post-overflowing');
    } else {
      root.classList.remove('feed-post-overflowing');
    }
  }
}) : null;

// Animated clamp release (owner ask: expanding should feel alive): transition max-height from the clamped
// height to the measured full height, then drop the clamp entirely (max-height:none — later image growth stays
// unclamped). CSSOM per-property assignment only (prod CSP kills setAttribute('style'), allows .style.prop).
// prefers-reduced-motion turns the transition off in CSS — transitionend then never fires, so the timer
// backstop (also covering a mid-flight display:none) guarantees the release either way. The expanded class
// keeps the toggle button visible (relabeled "Collapse" by the caller).
function expandClampedBody(root, body) {
  const fullHeight = body.scrollHeight;
  body.style.maxHeight = `${body.clientHeight}px`;
  root.classList.add('feed-post-expanding', 'feed-post-expanded');
  root.classList.remove('feed-post-collapsible', 'feed-post-overflowing');
  requestAnimationFrame(() => { body.style.maxHeight = `${fullHeight}px`; });
  const release = () => {
    body.style.removeProperty('max-height');
    root.classList.remove('feed-post-expanding');
  };
  body.addEventListener('transitionend', release, { once: true });
  window.setTimeout(release, 450);
}

// Reverse toggle (owner ask v767): re-clamp an expanded post/embed, animated from the current full height down
// to the CSS clamp — the exact MIRROR of expandClampedBody. The clamp target is read from the :root var that
// applies to this root (posts vs shared-post embeds); an unparseable value degrades to an instant un-animated
// re-clamp. The clamp classes (feed-post-collapsible/-overflowing) are re-applied ONLY in settle(), never up
// front: adding feed-post-collapsible before the transition sets max-height to the clamp instantly, and reading
// scrollHeight while it is applied would commit that clamped height as the transition baseline — so the
// 850->480 change nets to zero and the browser skips the animation (the "collapses instantly" bug). settle()
// also pulls the card back into view: collapsing removes the content the reader was level with, which would
// otherwise strand them past the card's new bottom.
function collapseClampedBody(root, body) {
  const varName = root.classList.contains('shared-post-embed') ? '--shared-post-embed-max-height' : '--feed-post-collapsed-max-height';
  const target = Number.parseFloat(getComputedStyle(root).getPropertyValue(varName));
  root.classList.remove('feed-post-expanded');
  let released = false;
  const settle = () => {
    if (released) return;
    released = true;
    body.style.removeProperty('max-height');
    root.classList.remove('feed-post-expanding');
    root.classList.add('feed-post-collapsible', 'feed-post-overflowing');
    root.scrollIntoView({ block: 'nearest' });
  };
  if (!Number.isFinite(target)) { settle(); return; }
  // Pin the CURRENT full height inline (the body still renders unclamped here — no visual change), turn on the
  // transition, then animate down to the clamp value. The 850px baseline is the last rendered height, so the
  // rAF change to the clamp target animates. overflow:hidden comes from feed-post-expanding during the run.
  body.style.maxHeight = `${body.scrollHeight}px`;
  root.classList.add('feed-post-expanding');
  requestAnimationFrame(() => { body.style.maxHeight = `${target}px`; });
  body.addEventListener('transitionend', settle, { once: true });
  window.setTimeout(settle, 450);
}

// The shared expand/collapse toggle button for a clamped root (feed article or shared-post embed): one button,
// relabeled per state, session state carried by `expandedSet[key]` so rebuilds re-render the current state.
function wireClampToggleButton(root, body, inner, expandedSet, key) {
  const expanded = expandedSet.has(key);
  root.classList.add(expanded ? 'feed-post-expanded' : 'feed-post-collapsible');
  const toggleButton = document.createElement('button');
  toggleButton.type = 'button';
  toggleButton.className = 'feed-expand-button';
  toggleButton.textContent = expanded ? t('public.collapsePost') : t('public.showFullPost');
  toggleButton.addEventListener('click', (event) => {
    event.stopPropagation();
    if (expandedSet.has(key)) {
      expandedSet.delete(key);
      toggleButton.textContent = t('public.showFullPost');
      feedPostClampObserver.observe(inner);
      collapseClampedBody(root, body);
    } else {
      expandedSet.add(key);
      toggleButton.textContent = t('public.collapsePost');
      feedPostClampObserver.unobserve(inner);
      expandClampedBody(root, body);
    }
  });
  root.append(toggleButton);
  if (!expanded) feedPostClampObserver.observe(inner);
}

// Session-expanded shared-post embeds, by the SHARED post's entry id: private bubbles and feed articles rebuild
// on every render pass, so a DOM-only expand would snap shut — the builder re-applies from here (the
// publicFeedExpandedPosts pattern one level down).
const expandedSharedEmbeds = new Set();

// The image of a resolved public post (the top-level imageUrl of an image-only post, or the first image block of
// a text+image post), or null when it carries none / hasn't warmed its media yet.
function sharedPostImageUrlFromPost(post) {
  const media = publicPostRenderableImageMedia(post);
  if (!media) return null;
  if (media.imageUrl) return media.imageUrl;
  const imageBlock = (media.blocks ?? []).find((b) => b?.type === 'image' && typeof b.url === 'string' && b.url.length > 0);
  return imageBlock?.url ?? null;
}

// The original public post a SHARE embed references, found in the subscribed/viewed feed cache by entryId (posts
// carry both id and entryId). null when the channel isn't cached locally.
function findCachedPublicPostByEntryId(entryId) {
  const target = String(entryId ?? '');
  if (!target) return null;
  let found = null;
  eachCachedPublicPost((post) => {
    if (found || !post) return;
    if (String(post.entryId ?? '') === target || String(post.readEntryId ?? '') === target) found = post;
  });
  return found;
}

// Canonical 32-byte body hash (lowercase, no 0x), or null when malformed — for comparing a SHARE block's bodyHash
// to a resolved post's, so both forms (with/without 0x, any case) match.
function normalizeBodyHashHex(value) {
  const hex = String(value ?? '').replace(/^0x/i, '').toLowerCase();
  return /^[0-9a-f]{64}$/.test(hex) ? hex : null;
}

// v797: a SHARE is an internal REFERENCE (entryId), not a copy — the original post's image already lives on-chain
// (retained >=1 year by CapsuleHub) and never rides the wire again. Resolve that image by entryId from LOCAL caches
// only: the feed cache (subscribed/viewed channels), warming a stripped light item from the durable post-media
// store. Returns the image data-url, or null when the post isn't cached (a cold recipient who never opened the
// channel — the embed header still taps through to the live original). Best-effort + non-throwing (render backstop).
// REFERENCE INTEGRITY: the whole SHARE block is sender-authored, so the resolved post's bodyHash must match the
// block's expectedBodyHash (content-addressed) — else a crafted entryId could show an UNRELATED cached post's image
// under the sender's claimed channel/label. No match -> null (keep the hint). Only the recipient's OWN decoded media
// is ever shown; sender bytes never cross.
async function resolveSharedPostImageUrl(entryId, expectedBodyHash) {
  try {
    const post = findCachedPublicPostByEntryId(entryId);
    if (!post) return null;
    const want = normalizeBodyHashHex(expectedBodyHash);
    if (!want || want !== normalizeBodyHashHex(post.bodyHash)) return null; // reference must be content-authentic
    const direct = sharedPostImageUrlFromPost(post);
    if (direct) return direct;
    // The localStorage feed cache STRIPS image data-urls on persist — warm the image back from the durable
    // per-post media store (keyed by post.id) exactly like the feed's own load-time image warm.
    const key = publicPostCacheKey(post);
    if (!key) return null;
    const store = await publicPostMediaStore();
    const raw = await store?.get(key);
    if (!raw) return null;
    let media = null;
    try { media = JSON.parse(raw); } catch { return null; }
    applyPublicPostMediaRecord(post, media);
    return sharedPostImageUrlFromPost(post);
  } catch {
    return null;
  }
}

// The shared-post embed card (v766): source-channel header (recipient-resolved identity; the sender's snapshot
// label only as fallback) + title/text snapshot, clamped with its own smaller max height and the same expand
// machinery as long posts. Snippet renders as PLAIN TEXT (textContent, no linkify): the snapshot is
// sender-authored/unverified — the tappable header leads to the REAL channel (chain truth) instead. v797: when the
// referenced post's image is cached locally, the media hint is swapped for the real image (resolved by entryId, no
// wire copy).
function buildSharedPostEmbed(block) {
  const embed = document.createElement('div');
  embed.className = 'shared-post-embed';
  const wallet = rawWalletAddress(block.authorWallet);
  const label = (wallet ? resolveWalletChannelDisplay(wallet)?.name : null)
    || (wallet ? publicAuthorLabel(wallet) : null)
    || String(block.author ?? '').trim()
    || (wallet ? shortAddress(wallet) : t('public.channel'));
  const header = document.createElement('button');
  header.type = 'button';
  header.className = 'shared-post-embed-header';
  header.title = t('public.openSharedChannel');
  const avatar = document.createElement('div');
  avatar.className = 'avatar shared-post-embed-avatar';
  avatar.setAttribute('aria-hidden', 'true');
  setAvatarNode(avatar, String(label).slice(0, 1), wallet ? publicAvatarUrlForWallet(wallet) : null);
  const headText = document.createElement('span');
  headText.className = 'shared-post-embed-channel';
  const kind = document.createElement('span');
  kind.className = 'shared-post-embed-kind';
  kind.textContent = t('public.sharedPost');
  const name = document.createElement('span');
  name.className = 'shared-post-embed-name';
  name.textContent = label;
  headText.append(kind, name);
  header.append(avatar, headText);
  header.addEventListener('click', (event) => {
    event.stopPropagation();
    if (!wallet) return;
    // Works from the PRIVATE surface too: the channel view lives on the Public pane.
    setView('public');
    openPublicChannelView({ authorWallet: wallet });
  });
  embed.append(header);
  const body = document.createElement('div');
  body.className = 'feed-post-body';
  const inner = document.createElement('div');
  inner.className = 'feed-post-body-inner';
  if (block.title) {
    const title = document.createElement('div');
    title.className = 'shared-post-embed-title';
    title.textContent = block.title;
    inner.append(title);
  }
  if (block.snippet) {
    const text = document.createElement('p');
    text.className = 'feed-block-text shared-post-embed-text';
    // Inline formatting + links only (inlineOnly): the snippet is a TRUNCATED excerpt inside a <p>, so block
    // elements would be invalid and a half-cut heading/list would look odd. Bold/italic/links render; block
    // markers (heading/list/quote) show as literal text in the preview excerpt. Links are safe for the
    // UNVERIFIED sender snapshot — appendInlineFormatted routes every link through the activateExternalLink
    // interstitial (no live href), like the original post.
    appendFormattedMessageText(text, block.snippet, { inlineOnly: true });
    if (block.textTruncated) text.append(document.createTextNode('…'));
    inner.append(text);
  }
  if (block.hasImage) {
    const mediaHint = document.createElement('span');
    mediaHint.className = 'shared-post-embed-media-hint';
    mediaHint.textContent = t('public.sharedPostImageHint');
    inner.append(mediaHint);
    // v797: resolve the ORIGINAL post's image by entryId from the local cache (no re-upload, no wire copy) and
    // swap the hint for the real image. A cold recipient (channel not cached) keeps the hint; the header still
    // taps through to the live original. .src is a decoded data-url from our own store (never user HTML) — XSS-safe.
    if (block.entryId) {
      resolveSharedPostImageUrl(block.entryId, block.bodyHash).then((url) => {
        if (!url || !mediaHint.isConnected) return;
        const img = document.createElement('img');
        img.className = 'shared-post-embed-image';
        img.loading = 'lazy';
        img.decoding = 'async';
        img.alt = '';
        img.src = url;
        mediaHint.replaceWith(img);
      }).catch(() => {});
    }
  }
  body.append(inner);
  embed.append(body);
  if (feedPostClampObserver) {
    wireClampToggleButton(embed, body, inner, expandedSharedEmbeds, String(block.entryId));
  }
  return embed;
}

// Build one feed <article> (chrome + content) for an item. Extracted so renderPublicFeed can REUSE an article whose
// publicFeedItemRenderSignature is unchanged instead of rebuilding it every render.
function buildPublicFeedArticle(item, avatarUrlMemo) {
  const unread = isUnreadPublicItem(item);
  const article = document.createElement('article');
  article.className = `feed-item${item.compact ? ' compact' : ''}${unread ? ' is-unread' : ''}`;
  if (unread) article.dataset.unread = 'true';
  if (item.entryId !== undefined && item.entryId !== null) article.dataset.entryId = String(item.entryId);
  if (item.channelId) article.dataset.channelId = item.channelId;
  const authorRow = document.createElement('div');
  authorRow.className = 'feed-author-row';
  const authorAvatar = document.createElement('div');
  authorAvatar.className = 'avatar feed-avatar';
  authorAvatar.setAttribute('aria-hidden', 'true');
  setAvatarNode(authorAvatar, String(item.author ?? item.title ?? 'P').slice(0, 1), item.avatarImageUrl ?? publicAvatarUrlForWallet(item.authorWallet, avatarUrlMemo));
  const meta = document.createElement('div');
  meta.className = 'feed-meta';
  for (const label of [...(item.meta ?? []), unread ? t('public.unread') : null].filter(Boolean)) {
    const span = document.createElement('span');
    span.textContent = label;
    meta.append(span);
  }
  authorRow.append(authorAvatar, meta);
  // Tapping the author NAME/meta block opens the channel screen — this channel's posts only. The AVATAR is NOT
  // wired here: it keeps its v651 tap-to-view meaning (the delegated document click opens an image-bearing avatar
  // in the fullscreen lightbox) — owner: avatar tap = see the avatar, name tap = open the channel.
  // Plain click affordance, NO role/aria-label: an aria-label would wipe the author/date/unread text from the
  // accessibility tree, and the meta block can host interactive children (the publish-status retry chip) — a
  // nested-button-in-button violation. The keyboard path to the channel is the about "i" button's "Open channel"
  // action (a real button). The about "i" + "Display as" chevron stopPropagation, staying independent targets.
  if (item.channelId) {
    const openChannel = (event) => {
      // A click landing on an interactive child (the publish-status/retry chip) is not a channel-open intent.
      if (event.target instanceof Element && event.target !== event.currentTarget
        && event.target.closest('button, .public-publish-status')) return;
      event.stopPropagation();
      openPublicChannelView({ channelId: item.channelId, authorWallet: item.authorWallet });
    };
    meta.classList.add('feed-author-link');
    meta.addEventListener('click', openChannel);
  }
  // Own pending publishes carry a status badge ('public publish submitted…' / 'public publish failed') —
  // CSS classes only (prod CSP style-src 'self' silently kills inline styles).
  if (isPendingPublicFeedItem(item) && item.publishStatus) {
    const statusBadge = document.createElement('span');
    statusBadge.className = `public-publish-status${String(item.publishStatus).endsWith('failed') ? ' public-publish-status--failed' : ''}`;
    // Private-style live status ('sending 2 parts' / 'submitted 1/2, confirming' / …) when a publishState is
    // streaming; the machine-readable publishStatus marker is the fallback.
    statusBadge.textContent = (item.publishState ? publishStateMeta(item.publishState) : null) || item.publishStatus;
    // Patch anchor for the status-only fast path (a publish tick updates this text in place, no rebuild).
    if (item.id) statusBadge.dataset.publishLocalId = String(item.id);
    wirePublicPublishRetryBadge(statusBadge, item, 'post');
    meta.append(statusBadge);
  }
  // The channel "about" (description + tags) button and the "Display as" chevron live top-right in the author
  // row. Both carry margin-left:auto: the first absorbs the free space (pushing the group right), the second
  // then sits flush beside it — so they render as an adjacent [about][chevron] cluster on the right edge.
  const feedDescriptionButton = publicItemDescriptionButton(item);
  if (feedDescriptionButton) authorRow.append(feedDescriptionButton);
  const feedIdentityButton = publicItemIdentityButton(item);
  if (feedIdentityButton) authorRow.append(feedIdentityButton);
  article.append(authorRow);
  // Long-post collapse: title + content live in a clamped body wrapper (feed + channel view only — the post
  // detail screen and comments call appendPublicItemContent directly and never clamp). The inner wrapper is the
  // observer target; the outer .feed-post-body is what the CSS max-height clamps.
  const body = document.createElement('div');
  body.className = 'feed-post-body';
  const bodyContent = document.createElement('div');
  bodyContent.className = 'feed-post-body-inner';
  if (item.title) {
    const title = document.createElement('h2');
    title.textContent = item.title;
    bodyContent.append(title);
  }
  appendPublicItemContent(bodyContent, item);
  body.append(bodyContent);
  article.append(body);
  // Compact cards (channel plates / empty states) carry a line or two — no clamp machinery for them.
  if (feedPostClampObserver && !item.compact) {
    wireClampToggleButton(article, body, bodyContent, publicFeedExpandedPosts, String(item.id));
  }
  // Comments are no longer rendered inline in the feed — they load on demand on the post detail screen
  // (openPublicPostDetail). appendPublicItemComments is reused there.
  appendPublicItemActions(article, item);
  return article;
}

// A compact string of every MUTABLE input to buildPublicFeedArticle, so a reused article rebuilds when (and only
// when) its appearance would change. Post CONTENT (text/image) is immutable for a chain post, so it is not part of
// the signature. Conservative by design: including more here only costs the occasional needless rebuild (cheap under
// the render cap); a MISSING input would instead leave a stale article. `item.author` carries the resolved
// display-name so an identity / "display as" change reflows; rare channel-profile-only changes self-heal on the next
// signature-changing event.
function publicFeedItemRenderSignature(item, avatarUrlMemo) {
  return [
    isUnreadPublicItem(item) ? 'u' : '',
    item.compact ? 'c' : '',
    // Expanded long posts rebuild expanded on EVERY surface: the click mutates only the tapped article's DOM,
    // so the OTHER surface's reused article (feed vs channel view render the same item independently) would
    // otherwise stay collapsed until an unrelated rebuild.
    publicFeedExpandedPosts.has(String(item.id)) ? 'x' : '',
    (item.meta ?? []).join(''),
    item.author ?? '',
    item.title ?? '',
    item.publishStatus ?? '',
    item.publishState ? publishStateMeta(item.publishState) : '',
    (item.avatarImageUrl ?? publicAvatarUrlForWallet(item.authorWallet, avatarUrlMemo)) ?? '',
    item.commentsAllowed === false ? 'nc' : '',
    isPublicChannelSubscribed(item.channelId) ? 's' : '',
    // Renderable-image presence IS mutable across the persist-strip round-trip: the localStorage feed cache strips
    // image data urls (omitHeavyFeedMediaForPersist), so a reloaded post loses its image, then the post-reload sync
    // re-hydrates it from the durable body cache. Without this term the reused article stayed image-less (the sync
    // repaired the DATA but the signature/DOM never changed -> "the image showed once then vanished"). Count blocks
    // that actually render an image + the legacy image-only imageUrl; stripped (0) vs re-hydrated (1) differ.
    `img${(item.blocks ?? []).filter((block) => block?.type === 'image' && block.url).length}${item.imageUrl ? 'i' : ''}`,
  ].join('');
}

// The "show older" affordance at the BOTTOM of the newest-first feed: reveals another PUBLIC_FEED_RENDER_PAGE of
// older posts. One button, rebuilt each render (cheap), with a fresh listener.
function buildShowOlderButton(hiddenOlderCount) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'feed-show-older';
  button.textContent = t('public.showOlder');
  button.dataset.hiddenOlder = String(hiddenOlderCount);
  button.addEventListener('click', () => {
    publicFeedShownCap += PUBLIC_FEED_RENDER_PAGE;
    renderPublicSurface({ anchorUnread: false });
  });
  return button;
}

// Show the "edit channel description" header button only when the user has an activatable own channel — i.e. a
// connected wallet with an active Platho account (publishing a profile needs both). Toggled on every public render.
function refreshEditChannelProfileButton() {
  if (!editChannelProfileButton) return;
  editChannelProfileButton.hidden = !(ownPublicChannel() && hasActivePlathoAccount());
}

function renderPublicSurface(options = {}) {
  updatePublicModeButtons();
  refreshEditChannelProfileButton();
  if (publicChannelSearchRow) publicChannelSearchRow.hidden = false;
  const allItems = publicFeedItemsChronological();
  // A transient preview channel (open in the channel view, not followed) is excluded from the MAIN feed and its
  // unread/status counts — its posts show only inside the channel view until the user follows.
  const surfaceItems = publicChannelPreviewChannelId
    ? allItems.filter((item) => item.channelId !== publicChannelPreviewChannelId)
    : allItems;
  const items = surfaceItems.filter((item) => publicFeedItemMatchesSearch(item, publicChannelSearchQuery));
  renderPublicFeed(items, options);
  // Keep the open post detail (per-post comments) in sync with the cache too — a just-published local-pending
  // comment lands in the cache and must show on the detail screen, which is rendered separately from the feed.
  if (publicPostDetailOpen) renderPublicPostDetail();
  // Same for the open channel view — a background sync (or a preview fetch) re-renders its post list.
  if (publicChannelViewOpen) renderPublicChannelView();
  const unread = surfaceItems.filter(isUnreadPublicItem).length;
  setPublicStatus(publicChannelSearchQuery ? `${items.length} found` : (unread > 0 ? `${unread} unread` : 'feed'));
}

function setPublicCommentTarget(item = null, { focus = true, showContext = true } = {}) {
  publicCommentTarget = item;
  const active = Boolean(item);
  // A comment target change (or clear) always drops any pending reply-to-comment quote — it referenced a comment
  // of the PREVIOUS target post.
  publicCommentReplyTo = null;
  if (publicComposer) publicComposer.dataset.mode = active ? 'comment' : 'post';
  // The post detail screen drives comment mode implicitly (the whole screen IS the post), so it suppresses the
  // inline "Comment to X / Cancel" context bar — there a Cancel would silently drop the composer back to post mode
  // while still on the post screen, so a "comment" would publish as a new public post. (Reply mode re-shows the
  // bar on the detail screen — see refreshPublicCommentReplyUi — with a Cancel that clears ONLY the reply.)
  publicCommentContextSuppressed = !active || !showContext;
  if (publicCommentContext) publicCommentContext.hidden = publicCommentContextSuppressed;
  if (publicPostCommentsToggle) publicPostCommentsToggle.hidden = active;
  if (active) {
    setText(publicCommentContextText, t('public.commentTo', { target: item.title ?? item.id ?? t('public.postFallback') }));
    if (publicMessageInput) {
      publicMessageInput.placeholder = publicComposerPlaceholder();
      if (focus) publicMessageInput.focus();
    }
  } else {
    if (publicMessageInput) {
      publicMessageInput.placeholder = publicComposerPlaceholder();
    }
    if (publicComposerCommentsCheckbox) publicComposerCommentsCheckbox.checked = readPublicCommentsDefault() !== 'disabled';
  }
  updatePublicCommentsToggleUi();
  refreshComposerPublishPolicy();
  refreshComposerCostStatus();
}

// ---- Swipe-to-reply (v646): composer quote strips ---------------------------------------------------------------
// Both strips show "author: snippet" with a Cancel that clears ONLY the reply draft. The reply becomes a REPLY
// document block at send time (composerBlocksFromDraft / publicDocumentBlocksFromDraft read the drafts directly).

function replyStripContent(node, reply, cancelLabelNode) {
  if (!node) return;
  const author = document.createElement('span');
  author.className = 'composer-reply-author';
  author.textContent = reply.author || t('chat.reply');
  const snippet = document.createElement('span');
  snippet.textContent = reply.snippet || '';
  const wrap = document.createElement('span');
  wrap.className = 'composer-reply-text';
  wrap.append(author, snippet);
  node.replaceChildren(wrap);
  if (cancelLabelNode) node.append(cancelLabelNode);
}

function setPrivateReplyDraft(reply) {
  privateReplyDraft = reply ?? null;
  if (privateReplyContext) privateReplyContext.hidden = !privateReplyDraft;
  // The mobile composer grid re-rows around the quote strip via this class — a JS-set class, not :has():
  // :has() silently no-ops on the iOS floor (Safari 14), which left the strip stranded under the buttons.
  // Share (v766) uses the same row, so the class stays while EITHER strip is up.
  composer?.classList.toggle('is-replying', Boolean(privateReplyDraft || privateShareDraft));
  if (privateReplyDraft && privateReplyContextText) {
    replyStripContent(privateReplyContextText, privateReplyDraft);
  }
  if (privateReplyDraft && messageInput && !messageInput.disabled) messageInput.focus();
  refreshComposerCostStatus();
}

// Strip content for the share chip (v766): "Sharing post" label + the source channel/title as the snippet.
function shareStripContent(node, share) {
  if (!node) return;
  const label = document.createElement('span');
  label.className = 'composer-reply-author';
  label.textContent = t('composer.sharingPost');
  const snippet = document.createElement('span');
  snippet.textContent = [share.author, share.title || share.snippet].filter(Boolean).join(' - ');
  const wrap = document.createElement('span');
  wrap.className = 'composer-reply-text';
  wrap.append(label, snippet);
  node.replaceChildren(wrap);
}

// Cancel path: the [post] marker leaves the text with the draft (mirrors removeImageMarkerForComposer).
function removeShareMarkerForComposer(textarea) {
  if (!textarea) return;
  COMPOSER_SHARE_MARKER_RE.lastIndex = 0;
  let value = String(textarea.value ?? '').replace(COMPOSER_SHARE_MARKER_RE, '');
  value = value.replace(/\n{3,}/g, '\n\n');
  if (!value.trim()) value = '';
  textarea.value = value;
}

function setPrivateShareDraft(share) {
  privateShareDraft = share ?? null;
  if (privateShareContext) privateShareContext.hidden = !privateShareDraft;
  composer?.classList.toggle('is-replying', Boolean(privateReplyDraft || privateShareDraft));
  if (privateShareDraft && privateShareContextText) {
    shareStripContent(privateShareContextText, privateShareDraft);
  }
  refreshComposerCostStatus();
  // A share-only draft (no typed text) IS sendable — the button must open the moment the draft attaches.
  refreshPrivateSendButtonState();
}

function setPublicShareDraft(share) {
  publicShareDraft = share ?? null;
  if (publicShareContext) publicShareContext.hidden = !publicShareDraft;
  if (publicShareDraft && publicShareContextText) {
    shareStripContent(publicShareContextText, publicShareDraft);
  }
  refreshComposerCostStatus();
  refreshPublicSendButtonState();
}

// Suppression state mirrors setPublicCommentTarget's showContext decision so reply mode can temporarily re-show
// the context bar on the post-detail screen and hide it back when the reply is cancelled/sent.
let publicCommentContextSuppressed = true;

function refreshPublicCommentReplyUi() {
  if (!publicCommentContext) return;
  if (publicCommentReplyTo) {
    replyStripContent(publicCommentContextText, publicCommentReplyTo);
    publicCommentContext.hidden = false;
  } else {
    if (publicCommentTarget) setText(publicCommentContextText, t('public.commentTo', { target: publicCommentTarget.title ?? publicCommentTarget.id ?? t('public.postFallback') }));
    publicCommentContext.hidden = publicCommentContextSuppressed;
  }
}

function setPublicCommentReplyTo(reply) {
  publicCommentReplyTo = reply ?? null;
  refreshPublicCommentReplyUi();
  if (publicCommentReplyTo && publicMessageInput && !publicMessageInput.disabled) publicMessageInput.focus();
  refreshComposerCostStatus();
}

// Rendered quote strip inside a bubble/comment (the received REPLY block). Tapping it scrolls to the original
// row (matched by data-entry-id inside `scroller`) with a brief highlight; a missing original (evicted/unloaded)
// keeps the strip inert — the denormalized author+snippet already tell the story, Telegram-style.
function buildReplyQuoteNode(reply, scroller) {
  const quote = document.createElement('div');
  quote.className = 'message-reply-quote';
  const author = document.createElement('span');
  author.className = 'message-reply-quote-author';
  author.textContent = reply.author || t('chat.reply');
  const snippet = document.createElement('span');
  snippet.className = 'message-reply-quote-snippet';
  snippet.textContent = reply.snippet || '';
  quote.append(author, snippet);
  const refEntryId = reply.refEntryId === undefined || reply.refEntryId === null ? '' : String(reply.refEntryId);
  if (refEntryId && scroller) {
    quote.dataset.refEntryId = refEntryId;
    quote.addEventListener('click', (event) => {
      event.stopPropagation();
      const target = scroller.querySelector(`[data-entry-id="${refEntryId}"]`);
      if (!target) return;
      target.scrollIntoView({ behavior: 'smooth', block: 'center' });
      target.classList.remove('reply-target-flash');
      requestAnimationFrame(() => target.classList.add('reply-target-flash'));
    });
  }
  return quote;
}

// Snippet for a quote strip + the wire block: first text, else a media word (denormalized, like Telegram).
function replySnippetFromContent(item) {
  const blocks = Array.isArray(item?.blocks) ? item.blocks : [];
  const text = String(item?.text ?? '').trim() || String(blocks.find((block) => block?.type === 'text' && String(block.text ?? '').trim())?.text ?? '').trim();
  if (text) return text;
  if (blocks.some((block) => block?.type === 'image') || item?.imageUrl || item?.attachment?.type === 'image') return 'Image';
  if (blocks.some((block) => block?.type === 'payment') || item?.payment) return 'Payment check';
  if (blocks.some((block) => block?.type === 'file')) return 'File';
  if (blocks.some((block) => block?.type === 'share')) return 'Shared post';
  return 'Message';
}

// ---- Public post detail screen (per-post comments, opened from the "Comments" action) -------------------------
// The feed no longer loads comments (scalability). Opening a post slides a detail screen over the feed (mirrors the
// private chatOpen pattern via publicPane.dataset.postOpen), shows the post at the top, loads ITS comments on demand
// from chain, and puts the shared composer into comment mode for that post.

// Cached comments for a post (read from the feed cache where rememberLocalPublicComment stores them, and where a
// prior version's comment-walk persisted confirmed ones). Includes BOTH confirmed (entryId) and local-pending
// comments so the detail can fall back to local data when a fresh chain read returns fewer (or none), and so an
// own just-published comment shows instantly. Note the cache is per-account, so a comment seen under another
// account is not here.
function cachedCommentsForPost(item) {
  if (!item) return [];
  const channelId = item.channelId ?? 'platho.app';
  const cached = publicChannelFeedCache?.[channelId]?.feed ?? publicChannelFeedCache?.[channelId] ?? null;
  const post = (cached?.posts ?? []).find((entry) => (
    String(entry.entryId ?? entry.id) === String(item.entryId ?? item.id)
    && (!item.bodyHash || !entry.bodyHash || String(entry.bodyHash).toLowerCase() === String(item.bodyHash).toLowerCase())
  ));
  return post?.comments ?? [];
}

function publicPostDetailMergedComments() {
  const item = publicPostDetailItem;
  if (!item) return [];
  const chain = publicPostDetailChainComments;
  // UNION of both real comment sources. Chain-forensics fact (probe 2026-07-02): every comment published before
  // the publishItemToBatchPart parent_entry_id fix went on-chain with parent_link=0 — AUTHOR-indexed, invisible
  // to get_public_parent_index forever. For those, the FEED SYNC (author-index walk) is the ONLY source, surfaced
  // here via cachedCommentsForPost; the parent-index walk (`chain`) covers comments published after the fix.
  // mergePublicComments favors its SECOND argument on entryId collision, so the chain/durable copy (which carries
  // the image data URL) wins over a feed-cache copy (images stripped on persist). A local-pending copy (no
  // entryId) is dropped once its body hash appears in the chain list.
  const cached = cachedCommentsForPost(item).filter((local) => {
    if (local.entryId !== undefined && local.entryId !== null && local.entryId !== '') return true;
    return !chain.some((chainComment) => samePublicBodyHash(local, chainComment));
  });
  return mergePublicComments(cached, chain);
}

function publicDetailStatusNode(text, { retry = false } = {}) {
  const node = document.createElement('p');
  node.className = 'public-detail-status';
  node.textContent = text;
  if (retry) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'public-detail-retry';
    button.textContent = t('common.retry');
    button.addEventListener('click', () => { refreshPublicPostDetailComments(); });
    node.append(' ', button);
  }
  return node;
}

function renderPublicPostDetail() {
  if (!publicPostDetailBody || !publicPostDetailItem) return;
  // Re-find the current feed item by entryId so a display change (e.g. relabelling the author via the chevron)
  // reflects here without re-opening; fall back to the captured item. Identity for comment loading stays the
  // captured item.entryId (stable).
  const fresh = publicFeedItemsChronological().find((it) => (
    it.entryId !== undefined && String(it.entryId) === String(publicPostDetailItem.entryId)
  ));
  const item = fresh ?? publicPostDetailItem;
  // Feed items carry the author NAME in meta[0] (= the channel/thread name) and the date as the last meta entry —
  // there is no item.author / item.createdAt. The header mirrors the private chat conversation header (avatar +
  // name + a short subtitle), so the body below can show just the post content + comments without repeating the
  // author on every row.
  const flatMeta = (item.meta ?? []).flat().filter(Boolean);
  const authorName = item.author || flatMeta[0] || item.title || t('public.postTitleFallback');
  const dateLabel = flatMeta.length > 1 ? String(flatMeta[flatMeta.length - 1]) : '';
  // Title carries the author's identity tone (e.g. the teal ".ath" colour) — parity with the private chat header
  // (renderConversationIdentity). The date is NOT shown here; it moves into the post card below (like the feed),
  // and the subtitle is left empty so this header matches the private one (just the name).
  const authorTone = item.authorWallet ? resolveWalletChannelDisplay(item.authorWallet)?.tone : null;
  if (authorTone) {
    const toneLabel = document.createElement('span');
    toneLabel.className = `identity-title-label identity-label-${authorTone}`;
    toneLabel.textContent = authorName;
    publicPostDetailTitle.replaceChildren(toneLabel);
  } else {
    setText(publicPostDetailTitle, authorName);
  }
  setText(publicPostDetailSubtitle, '');
  if (publicPostDetailAvatar) {
    setAvatarNode(publicPostDetailAvatar, String(authorName).slice(0, 1), item.avatarImageUrl ?? publicAvatarUrlForWallet(item.authorWallet));
  }
  // The "Display as" chevron — relabel another author (same as the feed's per-post chevron). Hidden for your own
  // post, the official channel, or an item with no author wallet (matches publicItemIdentityButton's gate).
  if (publicPostAuthorIdentityButton) {
    const authorWallet = item.authorWallet ?? null;
    publicPostAuthorIdentityButton.hidden = !authorWallet
      || isOwnPublicAuthor(authorWallet)
      || item.channelId === DEFAULT_PUBLIC_CHANNEL_ID;
  }
  publicPostDetailBody.replaceChildren();

  // The post content, pinned at the top (no author row — the header already carries the author identity).
  const post = document.createElement('article');
  post.className = 'feed-item public-detail-post';
  // Post date lives on the card (mirrors the feed), not in the header — keeps the header to just the author.
  if (dateLabel) {
    const meta = document.createElement('div');
    meta.className = 'feed-meta public-detail-post-meta';
    const dateSpan = document.createElement('span');
    dateSpan.textContent = dateLabel;
    meta.append(dateSpan);
    post.append(meta);
  }
  if (item.title) {
    const title = document.createElement('h2');
    title.textContent = item.title;
    post.append(title);
  }
  appendPublicItemContent(post, item);
  publicPostDetailBody.append(post);

  // Comments section.
  const section = document.createElement('section');
  section.className = 'public-detail-comments';
  const comments = publicPostDetailMergedComments();
  const heading = document.createElement('h3');
  heading.className = 'public-detail-comments-heading';
  heading.textContent = comments.length > 0 ? t('public.commentsWithCount', { count: comments.length }) : t('public.comments');
  section.append(heading);
  if (comments.length > 0) appendPublicItemComments(section, { comments });
  if (publicPostDetailLoadState === 'loading') {
    section.append(publicDetailStatusNode(comments.length > 0 ? t('public.loadingMoreComments') : t('public.loadingComments')));
  } else if (publicPostDetailLoadState === 'error' && comments.length === 0) {
    // The read failed (rate-limited / unreachable) after retries — we do NOT know if there are comments.
    section.append(publicDetailStatusNode(t('public.commentsNotLoadedRetry'), { retry: true }));
  } else if (publicPostDetailLoadState === 'ready' && comments.length === 0) {
    // A clean read distinguishes the two honestly: parentExists === false means the post's comment index was
    // genuinely never created (no one has commented). parentExists === true with nothing shown is anomalous (index
    // present but no comment resolved) — treat as not-yet-loaded with a retry, not as "no comments".
    section.append(publicPostDetailParentExists === false
      ? publicDetailStatusNode(t('public.noCommentsYet'))
      : publicDetailStatusNode(t('public.commentsNotLoadedYet'), { retry: true }));
  }
  publicPostDetailBody.append(section);
}

// Warm the durable comment cache (IndexedDB — WITH image data URLs) into the in-memory Map BEFORE the user opens
// the post: the public analogue of restoreEncryptedMessageHistory pre-loading private messages into memory at
// boot, so openPublicPostDetail paints comments-with-images on its FIRST synchronous frame (no text-first flash,
// no chain read). Called when a post's "Comments" button is rendered (the exact set of posts that can be opened).
// Idempotent + cheap-guarded: skips a post already in the Map or already warming; a single IndexedDB get per post.
const warmingPublicPostComments = new Set();
async function warmPublicPostCommentsCache(item) {
  const cacheKey = publicPostCommentsCacheKey(item);
  if (!cacheKey || publicPostCommentsCache.has(cacheKey) || warmingPublicPostComments.has(cacheKey)) return;
  warmingPublicPostComments.add(cacheKey);
  try {
    const durable = await readCachedPublicComments(cacheKey);
    if (!durable || !Array.isArray(durable.comments) || durable.comments.length === 0) return;
    if (publicPostCommentsCache.has(cacheKey)) return; // an authoritative load beat us to it
    publicPostCommentsCache.set(cacheKey, {
      comments: durable.comments,
      parentExists: durable.parentExists === true,
      latestLink: durable.latestLink ?? null,
    });
    while (publicPostCommentsCache.size > 24) {
      publicPostCommentsCache.delete(publicPostCommentsCache.keys().next().value);
    }
    // If the user already has THIS post open and still empty (opened before the warm resolved), paint now.
    if (publicPostDetailOpen && publicPostDetailItem
      && String(publicPostDetailItem.entryId) === String(item.entryId)
      && publicPostDetailChainComments.length === 0) {
      publicPostDetailChainComments = durable.comments;
      publicPostDetailParentExists = durable.parentExists === true;
      publicPostDetailLoadState = 'ready';
      renderPublicPostDetail();
    }
  } catch {
    /* ignore (unavailable / quota) */
  } finally {
    warmingPublicPostComments.delete(cacheKey);
  }
}

function openPublicPostDetail(item) {
  if (!item || item.entryId === undefined || item.entryId === null) return;
  closePublicDiscovery();
  publicPostDetailItem = item;
  publicPostDetailOpen = true;
  // Stale-while-revalidate: paint the cached comments immediately (no re-download flash) if we have them, then
  // let refreshPublicPostDetailComments silently reload in the background.
  const cacheKey = publicPostCommentsCacheKey(item);
  const cached = publicPostCommentsCache.get(cacheKey);
  publicPostDetailChainComments = Array.isArray(cached?.comments) ? cached.comments : [];
  publicPostDetailParentExists = cached ? cached.parentExists === true : null;
  publicPostDetailLoadState = publicPostDetailChainComments.length > 0 ? 'ready' : 'loading';
  if (publicPane) publicPane.dataset.postOpen = 'true';
  // Shared composer -> comment mode for this post; no auto-focus (the user opens to read first) and no inline
  // context bar (the screen itself is the context).
  setPublicCommentTarget(item, { focus: false, showContext: false });
  renderPublicPostDetail();
  if (publicPostDetailBody) publicPostDetailBody.scrollTop = 0;
  // DURABLE seed: after a full reload the in-memory Map is empty — pull the last-loaded comments (with images)
  // from IndexedDB and paint them instantly, before the background chain re-walk. Guarded so a fast chain result
  // or a post close/reopen is never clobbered.
  if (publicPostDetailChainComments.length === 0) {
    readCachedPublicComments(cacheKey).then((durable) => {
      if (!durable || publicPostDetailItem !== item || publicPostDetailChainComments.length > 0) return;
      publicPostDetailChainComments = durable.comments;
      publicPostDetailParentExists = durable.parentExists === true;
      publicPostDetailLoadState = 'ready';
      publicPostCommentsCache.set(cacheKey, { comments: durable.comments, parentExists: durable.parentExists === true, latestLink: durable.latestLink ?? null });
      renderPublicPostDetail();
    }).catch(() => {});
  }
  refreshPublicPostDetailComments();
}

function closePublicPostDetail() {
  if (!publicPostDetailOpen && publicPane?.dataset?.postOpen !== 'true') return;
  publicPostDetailOpen = false;
  publicPostDetailItem = null;
  publicPostDetailChainComments = [];
  publicPostDetailLoadState = 'idle';
  publicPostDetailLoadToken += 1; // invalidate any in-flight comment load so a stale result can't render
  if (publicPane) publicPane.dataset.postOpen = 'false';
  setPublicCommentTarget(null);
  renderPublicSurface({ anchorUnread: false });
}

// --- Newcomer discovery panel (Part B) ---
async function openPublicDiscovery() {
  closePublicPostDetail();
  // reopenReturnTo:false — discovery is being opened EXPLICITLY here; the close must not re-open it (loop).
  closePublicChannelView({ reopenReturnTo: false });
  publicDiscoveryOpen = true;
  publicDiscoveryTagFilter = null;
  if (publicPane) publicPane.dataset.discoverOpen = 'true';
  const token = ++publicDiscoveryLoadToken;
  // Paint cached results immediately (fresh cache) or a loading line, then resolve.
  renderPublicDiscovery({ loading: !publicDiscoveryCache });
  try {
    const results = await discoverChannels();
    if (token !== publicDiscoveryLoadToken || !publicDiscoveryOpen) return;
    publicDiscoveryResults = results;
    renderPublicDiscovery({ loading: false });
  } catch (error) {
    if (token !== publicDiscoveryLoadToken || !publicDiscoveryOpen) return;
    noteTonRpcRateLimit(error);
    publicDiscoveryResults = publicDiscoveryCache?.results ?? [];
    renderPublicDiscovery({ loading: false, error: true });
  }
}

function closePublicDiscovery() {
  if (!publicDiscoveryOpen && publicPane?.dataset?.discoverOpen !== 'true') return;
  publicDiscoveryOpen = false;
  publicDiscoveryLoadToken += 1; // invalidate any in-flight scan so a stale result can't render
  if (publicPane) publicPane.dataset.discoverOpen = 'false';
}

// --- Channel view (v753): one channel's posts on their own screen ---
// Opens over the feed like the post detail / discovery (data-channel-open). A FOLLOWED channel renders instantly
// from the local cache; a NOT-followed one becomes a transient feed source (feedSourcePublicChannels) and the
// standard sync walk pulls its posts as a preview — nothing leaks into the main feed until the user follows.
// The post detail stacks ON TOP (open a post from the channel screen; Back returns to it).
function publicChannelViewChannel() {
  return publicChannelRegistry.find((channel) => channel.id === publicChannelViewChannelId) ?? null;
}

function publicChannelViewItems() {
  if (!publicChannelViewChannelId) return [];
  return publicFeedItemsChronological().filter((item) => (
    item.channelId === publicChannelViewChannelId && item.emptyChannel !== true
  ));
}

function openPublicChannelView(source = {}) {
  const wallet = rawWalletAddress(source.authorWallet) ?? null;
  let channelId = source.channelId ?? null;
  // A wallet with no registry entry yet (e.g. straight from discovery) gets registered UNSUBSCRIBED — the
  // existing "discovered while syncing" semantics, not a follow.
  if (!channelId && wallet) channelId = ensurePublicChannelForAuthorWallet(wallet, { activate: false });
  if (!channelId) return;
  // A floating "Display as" popover (body-appended singleton) must not survive the tap — the entry points
  // stopPropagation, so the document-level click closer never sees it. ABOVE the same-channel early return:
  // an author-row tap INSIDE the open view takes that return, and the popover would otherwise float on.
  hideIdentityPopover();
  if (publicChannelViewOpen && publicChannelViewChannelId === channelId) { renderPublicChannelView(); return; }
  closePublicPostDetail();
  closePublicDiscovery();
  publicChannelViewOpen = true;
  publicChannelViewChannelId = channelId;
  publicChannelViewWallet = wallet
    ?? rawWalletAddress(publicChannelRegistry.find((channel) => channel.id === channelId)?.authorWallet)
    ?? null;
  publicChannelViewReturnTo = source.returnTo ?? null;
  publicChannelViewShownCap = PUBLIC_FEED_RENDER_CAP;
  publicChannelViewRenderSig = '';
  const own = publicChannelViewWallet ? isOwnPublicAuthor(publicChannelViewWallet) : false;
  const followed = own || isPublicChannelSubscribed(channelId);
  publicChannelPreviewChannelId = followed ? null : channelId;
  if (publicPane) {
    publicPane.dataset.channelOpen = 'true';
    // Foreign channel: the post composer is hidden by CSS (you publish to YOUR channel from the feed; comments
    // live in the post detail, which re-shows the composer in comment mode when stacked on top).
    publicPane.dataset.channelOwn = own ? 'true' : 'false';
  }
  syncNavBackAffordance();
  const syncToken = ++publicChannelViewOpenToken;
  // Raised BEFORE the first paint: a cold preview channel must open on "Loading posts…", not flash a false
  // "No posts yet" until an incidental later render happens to repaint it.
  publicChannelViewSyncPending = !followed;
  renderPublicChannelView();
  if (publicChannelViewBody) publicChannelViewBody.scrollTop = 0;
  if (!followed) {
    // The preview source just joined feedSourcePublicChannels — rebuild the threads around it and pull its posts
    // now (the fast-path would otherwise skip the walk until the next global post; same invalidation the follow
    // flow uses in resyncPublicForNewSubscription, epoch-guarded against a concurrent walk's commit).
    rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
    invalidatePublicSyncFastPath();
    syncPublicChannels()
      .catch((error) => { noteTonRpcRateLimit(error); })
      .finally(() => {
        // Token guard: this finally may belong to a PREVIOUS channel's preview (the user moved on) — clearing the
        // pending flag then would flip the CURRENT channel's "Loading posts…" to a false "No posts yet".
        if (syncToken !== publicChannelViewOpenToken) return;
        publicChannelViewSyncPending = false;
        if (publicChannelViewOpen) renderPublicChannelView();
      });
  }
  // Header description card (and the freshest verified name) — cache-first, repaint when the cold read lands.
  if (publicChannelViewWallet) {
    const openedChannelId = channelId;
    resolveChannelProfile(publicChannelViewWallet)
      .then(() => { if (publicChannelViewOpen && publicChannelViewChannelId === openedChannelId) renderPublicChannelView(); })
      .catch(() => {});
  }
}

function closePublicChannelView(options = {}) {
  if (!publicChannelViewOpen && publicPane?.dataset?.channelOpen !== 'true') return;
  publicChannelViewOpen = false;
  publicChannelViewOpenToken += 1; // invalidate any in-flight preview sync's finally
  publicChannelViewSyncPending = false;
  const hadPreview = publicChannelPreviewChannelId !== null;
  publicChannelPreviewChannelId = null;
  publicChannelViewChannelId = null;
  publicChannelViewWallet = null;
  publicChannelViewRenderSig = '';
  const returnTo = publicChannelViewReturnTo;
  publicChannelViewReturnTo = null;
  if (publicPane) {
    publicPane.dataset.channelOpen = 'false';
    delete publicPane.dataset.channelOwn;
  }
  // Closing the view drops the transient preview source (its posts leave the threads; the cache entry stays for an
  // instant re-open, bounded by the per-channel cache caps).
  if (hadPreview) rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
  else renderPublicSurface({ anchorUnread: false });
  if (options.reopenReturnTo !== false && returnTo === 'discovery') openPublicDiscovery().catch(() => {});
}

function renderPublicChannelView() {
  if (!publicChannelViewOpen || !publicChannelViewBody) return;
  const channel = publicChannelViewChannel();
  const wallet = publicChannelViewWallet;
  const own = wallet ? isOwnPublicAuthor(wallet) : false;
  // Header identity: the same precedence the feed/discovery use (explicit "Display as" choice > verified
  // username > registry name) — see applyContactDisplayToRegistryChannel.
  const label = (wallet ? resolveWalletChannelDisplay(wallet)?.name : null)
    || (wallet ? publicAuthorLabel(wallet) : null)
    || channel?.name
    || t('public.channel');
  if (publicChannelViewTitle) publicChannelViewTitle.textContent = label;
  if (publicChannelViewSubtitle) {
    publicChannelViewSubtitle.textContent = wallet ? shortAddress(wallet) : (channel?.subtitle ?? t('public.channelPosts'));
  }
  if (publicChannelViewAvatar) {
    setAvatarNode(publicChannelViewAvatar, String(label ?? 'P').slice(0, 1), wallet ? publicAvatarUrlForWallet(wallet) : null);
  }
  const followed = isPublicChannelSubscribed(publicChannelViewChannelId);
  if (publicChannelViewFollowButton) {
    publicChannelViewFollowButton.hidden = own;
    publicChannelViewFollowButton.textContent = followed ? t('public.unfollow') : t('public.follow');
    publicChannelViewFollowButton.dataset.followed = followed ? 'true' : 'false';
  }
  const items = publicChannelViewItems();
  const profile = wallet ? cachedChannelProfile(wallet) : null;
  const description = typeof profile?.description === 'string' ? profile.description.trim() : '';
  const tags = (profile?.tags ?? []).filter(Boolean);
  // Rebuild guard: a background sync re-renders this view every cycle; when nothing visible changed, keep the
  // existing DOM (and the reader's scroll position). Signature mirrors the feed's per-item reconciliation.
  const avatarUrlMemo = new Map();
  const capped = items.length > publicChannelViewShownCap ? items.slice(items.length - publicChannelViewShownCap) : items;
  const sig = [
    publicChannelViewChannelId, label, followed ? 'f' : '', own ? 'o' : '',
    publicChannelViewSyncPending ? 'p' : '', description, tags.join(','), String(items.length),
    ...capped.map((item) => `${item.id}:${publicFeedItemRenderSignature(item, avatarUrlMemo)}`),
  ].join('|');
  if (sig !== publicChannelViewRenderSig) {
    publicChannelViewRenderSig = sig;
    // Reading-position anchor (the v752 feed lesson): a raw scrollTop restore shifts the reader when a NEW post
    // prepends at the top of the rebuilt list — snapshot the topmost visible article + its viewport offset and
    // re-align it after the rebuild. Skipped at the top (scrollTop 0 → new posts simply appear).
    const previousScrollTop = publicChannelViewBody.scrollTop;
    let scrollAnchor = null;
    if (previousScrollTop > 0) {
      const bodyTop = publicChannelViewBody.getBoundingClientRect().top;
      for (const node of publicChannelViewBody.children) {
        if (!node.dataset?.itemId) continue;
        const nodeTop = node.getBoundingClientRect().top - bodyTop;
        if (nodeTop + node.offsetHeight > 0) { scrollAnchor = { id: node.dataset.itemId, offset: nodeTop }; break; }
      }
    }
    publicChannelViewBody.replaceChildren();
    if (description || tags.length > 0) {
      const about = document.createElement('article');
      about.className = 'discovery-card channel-view-about';
      if (description) {
        const paragraph = document.createElement('p');
        paragraph.className = 'channel-about-description';
        paragraph.textContent = description;
        about.append(paragraph);
      }
      if (tags.length > 0) {
        const tagRow = document.createElement('div');
        tagRow.className = 'channel-about-tags';
        for (const tag of tags) {
          const chip = document.createElement('span');
          chip.className = 'channel-about-tag';
          chip.textContent = `#${tag}`;
          tagRow.append(chip);
        }
        about.append(tagRow);
      }
      publicChannelViewBody.append(about);
    }
    if (capped.length === 0) {
      const status = document.createElement('p');
      status.className = 'discovery-status';
      status.textContent = publicChannelViewSyncPending ? t('public.channelLoading') : t('public.channelEmpty');
      publicChannelViewBody.append(status);
    } else {
      // Newest-first (the v752 feed model) with a local cap + "show older" at the bottom.
      for (const item of capped.slice().reverse()) {
        const node = buildPublicFeedArticle(item, avatarUrlMemo);
        node.dataset.itemId = String(item.id); // scroll-anchor key across rebuilds
        publicChannelViewBody.append(node);
      }
      const hiddenOlder = items.length - capped.length;
      if (hiddenOlder > 0) {
        const older = document.createElement('button');
        older.type = 'button';
        older.className = 'feed-show-older';
        older.textContent = t('public.showOlder');
        older.dataset.hiddenOlder = String(hiddenOlder);
        older.addEventListener('click', () => {
          publicChannelViewShownCap += PUBLIC_FEED_RENDER_PAGE;
          renderPublicChannelView();
        });
        publicChannelViewBody.append(older);
      }
    }
    publicChannelViewBody.scrollTop = previousScrollTop;
    if (scrollAnchor) {
      // Re-align the anchored article to its pre-rebuild viewport offset (content added ABOVE otherwise shoves
      // the reader down; WebKit has no overflow-anchor). No-op when the anchor aged out of the window.
      const bodyTop = publicChannelViewBody.getBoundingClientRect().top;
      for (const node of publicChannelViewBody.children) {
        if (node.dataset?.itemId !== scrollAnchor.id) continue;
        const nodeTop = node.getBoundingClientRect().top - bodyTop;
        publicChannelViewBody.scrollTop = Math.max(0, publicChannelViewBody.scrollTop + (nodeTop - scrollAnchor.offset));
        break;
      }
    }
  }
  // Reading the channel marks its rendered posts read — the same rule the feed applies to its window. NOT while
  // the post detail / discovery is stacked on top (the view is display:none then; the user never saw the posts).
  if (isPublicViewActive() && !publicPostDetailOpen && !publicDiscoveryOpen && markVisiblePublicFeedRead(capped)) {
    requestAnimationFrame(() => renderPublicSurface({ anchorUnread: false }));
  }
}

async function refreshPublicDiscovery() {
  if (!publicDiscoveryOpen) return;
  const token = ++publicDiscoveryLoadToken;
  renderPublicDiscovery({ loading: true });
  try {
    const results = await discoverChannels({ force: true });
    if (token !== publicDiscoveryLoadToken || !publicDiscoveryOpen) return;
    publicDiscoveryResults = results;
    renderPublicDiscovery({ loading: false });
  } catch (error) {
    if (token !== publicDiscoveryLoadToken || !publicDiscoveryOpen) return;
    noteTonRpcRateLimit(error);
    renderPublicDiscovery({ loading: false, error: true });
  }
}

function renderPublicDiscovery(options = {}) {
  if (!publicDiscoveryBody) return;
  publicDiscoveryBody.replaceChildren();
  if (options.loading === true) {
    const status = document.createElement('p');
    status.className = 'discovery-status';
    status.textContent = t('public.discoverLoading');
    publicDiscoveryBody.append(status);
    return;
  }
  const results = publicDiscoveryResults ?? [];
  if (results.length === 0) {
    const status = document.createElement('p');
    status.className = 'discovery-status';
    status.textContent = options.error === true ? t('public.discoverError') : t('public.discoverEmpty');
    publicDiscoveryBody.append(status);
    return;
  }
  // Tag filter chips (tags present in the sampled set) — filtering narrows within the recent sample, not globally.
  const allTags = [...new Set(results.flatMap((channel) => channel.tags))].slice(0, 24);
  if (allTags.length > 0) {
    const filterRow = document.createElement('div');
    filterRow.className = 'discovery-tag-filter';
    for (const tag of allTags) {
      const chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'channel-about-tag';
      chip.textContent = `#${tag}`;
      chip.setAttribute('aria-pressed', publicDiscoveryTagFilter === tag ? 'true' : 'false');
      chip.addEventListener('click', () => {
        publicDiscoveryTagFilter = publicDiscoveryTagFilter === tag ? null : tag;
        renderPublicDiscovery({ loading: false });
      });
      filterRow.append(chip);
    }
    publicDiscoveryBody.append(filterRow);
  }
  const shown = publicDiscoveryTagFilter
    ? results.filter((channel) => channel.tags.includes(publicDiscoveryTagFilter))
    : results;
  if (shown.length === 0) {
    const status = document.createElement('p');
    status.className = 'discovery-status';
    status.textContent = t('public.discoverEmpty');
    publicDiscoveryBody.append(status);
    return;
  }
  for (const channel of shown) publicDiscoveryBody.append(buildDiscoveryCard(channel));
}

// The discovery card's "Display as" chevron — same menu + selection semantics as a public post's chevron
// (publicItemIdentityButton), keyed by the channel's author wallet directly. Returns null for your own channel
// or a wallet-less entry (nothing to relabel). Toggles the shared identity popover open/closed on repeat clicks.
function discoveryCardIdentityButton(authorWallet) {
  if (!authorWallet || isOwnPublicAuthor(authorWallet)) return null;
  const identityButton = document.createElement('button');
  identityButton.type = 'button';
  identityButton.className = 'icon-button discovery-card-identity';
  identityButton.setAttribute('aria-haspopup', 'menu');
  identityButton.setAttribute('aria-expanded', 'false');
  identityButton.title = t('public.chooseDisplayName');
  const identityIcon = document.createElement('span');
  identityIcon.className = 'icon icon-chevron-down';
  identityButton.append(identityIcon);
  identityButton.addEventListener('click', (event) => {
    event.stopPropagation();
    if (identityPopover && !identityPopover.hidden && identityPopoverAnchor === identityButton) {
      hideIdentityPopover();
    } else {
      showPublicChannelDisplayPopover({ authorWallet }, identityButton);
    }
  });
  return identityButton;
}

function buildDiscoveryCard(channel) {
  const card = document.createElement('article');
  card.className = 'discovery-card';
  const head = document.createElement('div');
  head.className = 'discovery-card-head';
  const avatar = document.createElement('div');
  avatar.className = 'avatar feed-avatar';
  avatar.setAttribute('aria-hidden', 'true');
  // Resolve the label at RENDER time so a username verified after the results were built shows on the next
  // re-render (scheduleDiscoveryLabelRefresh) without rebuilding the discovery sample. An explicit "Display as"
  // choice for this wallet (made via the chevron below, shared with the Private dialog + feed) wins over the
  // verified channel username — same precedence as a subscribed channel (applyContactDisplayToRegistryChannel).
  const label = resolveWalletChannelDisplay(channel.authorWallet)?.name
    || publicAuthorLabel(channel.authorWallet)
    || channel.name;
  setAvatarNode(avatar, String(label ?? 'P').slice(0, 1), publicAvatarUrlForWallet(channel.authorWallet));
  const name = document.createElement('span');
  name.className = 'discovery-card-name';
  name.textContent = label;
  head.append(avatar, name);
  // The card NAME opens the channel screen (read the posts BEFORE deciding to follow); the AVATAR keeps its
  // tap-to-view lightbox meaning (owner: avatar tap = see the avatar, name tap = open the channel). Plain click
  // affordance, no role/aria-label — the keyboard path is the explicit "Open channel" action button below. The
  // chevron stopPropagations, so relabeling stays an independent target.
  name.classList.add('feed-author-link');
  const openDiscoveredChannel = (event) => {
    if (event && event.target instanceof Element && event.target !== event.currentTarget
      && event.target.closest('button')) return;
    // stopPropagation: one tap, one meaning — the document-level closers see nothing (openPublicChannelView
    // hides a floating popover itself).
    event?.stopPropagation?.();
    openPublicChannelView({ authorWallet: channel.authorWallet, returnTo: 'discovery' });
  };
  name.addEventListener('click', openDiscoveredChannel);
  // "Display as" chevron — same affordance as a public post's author row: relabel this channel by its verified
  // .ath username, wallet address (with copy), or a local name, shared per-counterparty with any Private dialog.
  // Skipped for your own channel (nothing to relabel) or an entry with no author wallet.
  const identityButton = discoveryCardIdentityButton(channel.authorWallet);
  if (identityButton) head.append(identityButton);
  card.append(head);
  if (channel.description) {
    const desc = document.createElement('p');
    desc.className = 'discovery-card-desc';
    desc.textContent = channel.description;
    card.append(desc);
  }
  if (channel.tags.length > 0) {
    const tagRow = document.createElement('div');
    tagRow.className = 'channel-about-tags';
    for (const tag of channel.tags) {
      const chip = document.createElement('span');
      chip.className = 'channel-about-tag';
      chip.textContent = `#${tag}`;
      tagRow.append(chip);
    }
    card.append(tagRow);
  }
  const actions = document.createElement('div');
  actions.className = 'discovery-card-actions';
  // Browse-then-commit order: open (preview) first, follow second.
  const openButton = document.createElement('button');
  openButton.type = 'button';
  openButton.className = 'discovery-cta-action';
  openButton.textContent = t('public.openChannel');
  openButton.addEventListener('click', openDiscoveredChannel);
  const followButton = document.createElement('button');
  followButton.type = 'button';
  // Shared plate-CTA look (same as "Add contact"/"Add channel") — owner-requested single source of truth.
  followButton.className = 'discovery-cta-action';
  followButton.textContent = t('public.follow');
  followButton.addEventListener('click', () => {
    followButton.disabled = true;
    followButton.textContent = t('public.following');
    followDiscoveredChannel(channel.authorWallet);
  });
  actions.append(openButton, followButton);
  card.append(actions);
  return card;
}

// Adding a contact implies interest in the person, so the add-contact dialog also follows their public
// channel (owner request). Deliberately called ONLY from that dialog — NOT inside selectOrCreateRecipientThread,
// which also serves the "Private chat" button on public posts (auto-(re)following there would fight a
// deliberate unfollow). Re-adding an existing contact re-follows on purpose: addressing the person again IS
// a fresh expression of interest. Skipped for the Saved self-thread (publishing already handles own-channel).
function followContactPublicChannel(recipientWallet) {
  try {
    // rawWalletAddress (NOT the strict Vault-action address gate): the dialog hands over user-friendly
    // UQ/EQ forms, and the channel registry keys by the parsed raw form anyway.
    const wallet = rawWalletAddress(recipientWallet);
    if (!wallet) return;
    if (plathoWallet?.address && sameWalletAddress(wallet, plathoWallet.address)) return;
    const channelId = ensurePublicChannelForAuthorWallet(wallet, { activate: false });
    setPublicChannelSubscribed(channelId, true);
  } catch (error) {
    // Best effort: a follow must never block the contact add itself.
    console.warn('[platho] contact channel follow skipped', error?.message ?? error);
  }
}

function followDiscoveredChannel(authorWallet) {
  const channelId = ensurePublicChannelForAuthorWallet(authorWallet, { activate: false });
  setPublicChannelSubscribed(channelId, true);
  // Drop the now-followed channel from the discovery list + cache so it isn't suggested again, then re-render.
  const wallet = rawWalletAddress(authorWallet);
  const drop = (list) => (list ?? []).filter((channel) => rawWalletAddress(channel.authorWallet) !== wallet);
  publicDiscoveryResults = drop(publicDiscoveryResults);
  if (publicDiscoveryCache) publicDiscoveryCache = { ...publicDiscoveryCache, results: drop(publicDiscoveryCache.results) };
  renderPublicDiscovery({ loading: false });
}

// The channels plate at the top of the feed. Since the search-row "+" was removed (owner: a bare plus is
// unreadable), this plate is the ONLY entry point for discovery-by-activity AND add-channel-by-address, so it
// shows for EVERYONE — hidden only while a channel search is filtering the feed (results must not be pushed down).
function shouldShowDiscoveryCta() {
  return !publicChannelSearchQuery;
}

function buildDiscoveryCtaCard() {
  const card = document.createElement('article');
  card.className = 'feed-item discovery-cta';

  const head = document.createElement('div');
  head.className = 'discovery-cta-head';
  const badge = document.createElement('span');
  badge.className = 'discovery-cta-icon';
  const badgeIcon = document.createElement('span');
  badgeIcon.className = 'icon icon-compass';
  badge.append(badgeIcon);
  const textWrap = document.createElement('div');
  textWrap.className = 'discovery-cta-text';
  const title = document.createElement('h2');
  title.setAttribute('data-i18n', 'public.discoverCtaTitle');
  title.textContent = t('public.discoverCtaTitle');
  const body = document.createElement('p');
  body.setAttribute('data-i18n', 'public.discoverCtaBody');
  body.textContent = t('public.discoverCtaBody');
  textWrap.append(title, body);
  head.append(badge, textWrap);

  // Two labeled actions (real <button>s — the card itself is no longer a click target): discover channels by
  // recent activity, or add a known channel by name/address. data-i18n keeps the card retranslatable in place
  // by applyStaticTranslations (the quick-start language switch applies without a reload).
  const actions = document.createElement('div');
  actions.className = 'discovery-cta-actions';
  const discover = document.createElement('button');
  discover.type = 'button';
  discover.className = 'discovery-cta-action';
  discover.setAttribute('data-i18n', 'public.discoverCtaAction');
  discover.textContent = t('public.discoverCtaAction');
  discover.addEventListener('click', () => { openPublicDiscovery().catch((error) => console.error(error)); });
  const add = document.createElement('button');
  add.type = 'button';
  add.className = 'discovery-cta-action';
  add.setAttribute('data-i18n', 'public.discoverCtaAddAction');
  add.textContent = t('public.discoverCtaAddAction');
  add.addEventListener('click', () => { openAddPublicChannelDialog(); });
  actions.append(discover, add);

  card.append(head, actions);
  return card;
}

// On-demand comment loader for ONE post: walk the post's parent (comment) index, resolve each comment body, and
// reassemble multipart comments with the SAME assembler the feed sync uses. Returns { comments, degraded }: a
// rate-limited / partial walk reports degraded:true so the caller keeps "Loading..." and retries instead of
// showing a partial list as complete (the "comments disappear on flaky RPC" failure mode).
// INCREMENTAL comment loader (modelled on the private message sync: persisted bodies + fetch only what's NEW).
// options.snapshot = { comments, latestLink } from the last CLEAN load: if the parent index's latest_entry_link
// is unchanged, NOTHING is re-downloaded (1 cheap index read, zero ~32KB body reads — the owner-flagged
// re-download); otherwise the walk STOPS at the snapshot boundary and only the new entries' bodies are fetched
// (comment entries are immutable on-chain). A multipart group straddling the boundary (half-landed at snapshot
// time) extends the walk until the group completes.
// clean-17 comment read (gated): a post's comments live in its THREAD shard (address = f(post_uid), and post_uid
// folds the parent's channel_pk + channel epoch_tag + entry_id). The opened post carries channelEpochTag/authorWallet
// from the shard feed, so the thread is O(1) derivable — no parent index, no chain walk.
// NOTE (era window): readThreadComments reads the CURRENT thread era only; comments written in a later era land in a
// different thread shard. Within a 30-day thread era this is complete; a cross-era window is a public-lane refinement.
async function loadPublicPostCommentsFromShards(item) {
  const lane = directPublicLaneReader();
  if (!lane) return { comments: [], degraded: true };
  if (item?.channelEpochTag == null || item?.entryId == null || !item?.authorWallet) {
    return { comments: [], degraded: false, parentExists: false, latestLink: '0' };
  }
  let threadPosts;
  try {
    // shardEntryId is the RAW per-shard entry_id post_uid folds; item.entryId is the collision-safe composite.
    threadPosts = await lane.readThreadComments(item.authorWallet, BigInt(item.channelEpochTag), BigInt(item.shardEntryId ?? item.entryId), { channelShardSeq: item.channelShardSeq ?? 0 });
  } catch (error) {
    console.warn('[public] thread comments read failed', item.entryId, error);
    return { comments: [], degraded: true };
  }
  const commentParts = [];
  for (const tp of threadPosts) {
    let payload;
    try { payload = readPublicPostPayloadV2({ header: tp.header, body: tp.body }); } catch { continue; }
    if (payload.type !== 'comment' && payload.type !== 'image_comment' && payload.type !== 'document_comment') continue;
    const authorWallet = tp.publisher ? (rawWalletAddress(publicAddrKey(tp.publisher)) ?? publicAddrKey(tp.publisher)) : item.authorWallet;
    const createdAtSec = Number(tp.created_at ?? 0n);
    const bodyHashHex = await publicShardBodyHashHex(tp.body);
    // A thread's comments now come from MULTIPLE era shards (the era-window fix), whose entry_ids collide (0-based
    // per shard). A comment is a leaf (nothing derives from its id), so its feed identity is its unique body hash —
    // which also dedups the same comment on re-read. Multipart comments still group by streamId, not this id.
    commentParts.push({
      id: `pshard-c-${bodyHashHex.slice(2, 18)}`,
      entryId: `c-${bodyHashHex.slice(2)}`,
      channelId: item.channelId ?? publicChannelIdForAuthorWallet(authorWallet),
      type: payload.type,
      text: payload.text ?? '',
      imageBytes: payload.imageBytes ?? payload.image_bytes,
      documentBytes: payload.documentBytes ?? payload.document_bytes,
      createdAt: createdAtSec > 0 ? new Date(createdAtSec * 1000).toISOString() : new Date().toISOString(),
      author: publicAuthorLabel(authorWallet),
      authorWallet,
      bodyHash: bodyHashHex,
      entryUid: bodyHashHex.slice(2),
      streamId: payload.stream_id,
      partIndex: payload.partIndex ?? 0,
      partCount: payload.partCount ?? 1,
      chainVerified: true,
      // All comments in the thread share the parent; carry the post's id/hash so assemble/attach group them under it.
      parentEntryId: String(item.entryId),
      parentHash: item.bodyHash,
    });
  }
  const comments = assemblePublicParts(commentParts);
  comments.sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
  globalThis.plathoLastPublicCommentLoad = { mode: 'shard', entryId: String(item.entryId), comments: comments.length, degraded: false };
  return { comments, degraded: false, parentExists: comments.length > 0, latestLink: String(comments.length) };
}

async function loadPublicPostComments(item, options = {}) {
  if (publicLaneDirectPayEnabled()) return loadPublicPostCommentsFromShards(item);
  const snapshot = options.snapshot && Array.isArray(options.snapshot.comments) ? options.snapshot : null;
  const snapshotBoundary = (() => {
    try { return BigInt(snapshot?.latestLink ?? 0n); } catch { return 0n; }
  })();
  const resolved = await resolveCapsuleHubProvider();
  if (!resolved) return { comments: [], degraded: true };
  const { provider, address } = resolved;
  // 'critical' priority (same as the public sync, ABOVE the private message sync at 'messages') — already the
  // highest practical tier without a wide module-version cascade. The user-waited comment read thus jumps ahead of
  // the private sync (the bulk of any burst); a dedicated above-critical tier wasn't worth re-versioning 8 modules.
  const readOptions = criticalCapsuleHubReadOptions(address);
  let degraded = false;
  let parentIndex;
  try {
    parentIndex = await provider.getPublicParentIndex(BigInt(item.entryId), readOptions);
  } catch (error) {
    if (noteTonRpcRateLimit(error)) return { comments: [], degraded: true };
    throw error;
  }
  // No comment index for this post yet -> genuinely zero comments (a clean, non-degraded result).
  if (!parentIndex || parentIndex.exists !== true) {
    globalThis.plathoLastPublicCommentLoad = {
      entryId: String(item.entryId), bodyHash: item.bodyHash ?? null,
      parentExists: parentIndex?.exists ?? null,
      latestLink: String(parentIndex?.latest_entry_link ?? ''), entryCount: String(parentIndex?.entry_count ?? ''),
      walked: 0, resolved: 0, comments: 0, degraded: false,
    };
    // Clean read, no parent index → the post genuinely has no comments (the index is created on the first comment).
    return { comments: [], degraded: false, parentExists: false, latestLink: '0' };
  }
  const latestLink = String(parentIndex.latest_entry_link ?? '0');
  // UNCHANGED shortcut: the comment chain grows append-only, so an identical latest_entry_link means the
  // snapshot already holds everything — return it with ZERO body reads (this is the whole point).
  if (snapshot && snapshotBoundary > 0n && String(snapshotBoundary) === latestLink) {
    globalThis.plathoLastPublicCommentLoad = {
      entryId: String(item.entryId), bodyHash: item.bodyHash ?? null,
      parentExists: true, latestLink, entryCount: String(parentIndex.entry_count ?? ''),
      walked: 0, resolved: 0, comments: snapshot.comments.length, degraded: false, incremental: 'unchanged',
    };
    return { comments: snapshot.comments, degraded: false, parentExists: true, latestLink };
  }

  const ids = [];
  const walkedEntries = new Map();
  let link = BigInt(parentIndex.latest_entry_link ?? 0n);
  try {
    for (let n = 0; link > 0n; n += 1) {
      if (n >= PUBLIC_CHAIN_LONG_READ_LIMIT) { degraded = true; break; }
      // Snapshot boundary: everything at/below the last clean load's latest_entry_link is already assembled in
      // the snapshot — stop fetching (only NEW entries above it are read).
      if (snapshotBoundary > 0n && link <= snapshotBoundary) break;
      const entryId = link - 1n;
      const entry = await provider.getPublicEntry(entryId, readOptions);
      walkedEntries.set(entryId.toString(), entry);
      if (entry.exists !== true) break;
      ids.push(entryId);
      const prev = BigInt(entry.prev_link ?? 0n);
      if (prev === link) break; // defensive: never spin on a self-referential link
      link = prev;
    }
  } catch (error) {
    if (noteTonRpcRateLimit(error)) return { comments: [], degraded: true };
    throw error;
  }

  const commentParts = [];
  const resolveEntryToCommentPart = async (entry) => {
    // Body durability lives INSIDE resolvePublicEntryPayload (the per-entry BoC cache): a comment body that
    // resolved once is served locally on every later walk, so this resolver stays a thin assembler.
    let payload = null;
    try {
      payload = await resolvePublicEntryPayload(provider, entry, address, { maxBytes: PUBLIC_POST_BODY_MAX_BYTES });
    } catch (error) {
      // An unreadable / history-unavailable comment must NOT be presented as "no such comment": mark degraded so
      // the caller retries instead of caching a short list.
      if (noteTonRpcRateLimit(error)) { degraded = true; return; }
      degraded = true;
      return;
    }
    if (!payload) { degraded = true; return; }
    if (payload.type !== 'comment' && payload.type !== 'image_comment' && payload.type !== 'document_comment') return;
    const createdAtSec = Number(payload.createdAtSec ?? payload.created_at_sec ?? 0);
    const createdAt = createdAtSec > 0 ? new Date(createdAtSec * 1000).toISOString() : new Date().toISOString();
    const authorWallet = rawWalletAddress(payload.authorWallet ?? entry.author_wallet) ?? String(payload.authorWallet ?? entry.author_wallet ?? '');
    const part = {
      id: `chain-${entry.entry_id.toString()}`,
      entryId: entry.entry_id.toString(),
      channelId: item.channelId ?? publicChannelIdForAuthorWallet(authorWallet),
      type: payload.type,
      text: payload.text ?? '',
      imageBytes: payload.imageBytes ?? payload.image_bytes,
      documentBytes: payload.documentBytes ?? payload.document_bytes,
      createdAt,
      author: publicAuthorLabel(authorWallet),
      authorWallet,
      bodyHash: payload.bodyHash ?? uint256Hex(entry.body_hash),
      entryUid: payload.entryUid ?? entry.entry_uid.toString(16),
      streamId: payload.stream_id,
      partIndex: payload.partIndex ?? 0,
      partCount: payload.partCount ?? 1,
      profileVersion: payload.profileVersion ?? payload.profile_version ?? 0,
      avatarHash: payload.avatarHash ?? payload.avatar_hash ?? zeroAvatarHashHex(),
      chainVerified: true,
      parentEntryId: payload.parentEntryId.toString(),
      parentHash: payload.parentHash,
    };
    commentParts.push(part);
  };
  for (const entryId of ids) {
    const entry = walkedEntries.get(entryId.toString());
    if (!entry || entry.exists !== true) continue;
    await resolveEntryToCommentPart(entry);
  }

  // Boundary-straddle extension: a multipart comment half-landed at snapshot time has parts BELOW the boundary
  // that were never assembled (incomplete groups are dropped) — walk deeper until every multipart group among
  // the fresh parts is complete (bounded by the same read limit).
  try {
    let walked = ids.length;
    while (snapshotBoundary > 0n && link > 0n && walked < PUBLIC_CHAIN_LONG_READ_LIMIT
      && publicCommentPartsHaveIncompleteGroup(commentParts)) {
      const entryId = link - 1n;
      const entry = await provider.getPublicEntry(entryId, readOptions);
      walked += 1;
      if (entry.exists !== true) break;
      await resolveEntryToCommentPart(entry);
      const prev = BigInt(entry.prev_link ?? 0n);
      if (prev === link) break;
      link = prev;
    }
    // LIMIT exit with a still-incomplete group MUST degrade (symmetric with the main walk): otherwise the
    // result caches with the NEW cursor and the half-fetched comment falls below the boundary FOREVER. The
    // evicted (exists!==true) and chain-start (link=0) exits stay clean — an evicted half-group would loop
    // a retry forever if degraded here.
    if (walked >= PUBLIC_CHAIN_LONG_READ_LIMIT && publicCommentPartsHaveIncompleteGroup(commentParts)) {
      degraded = true;
    }
  } catch (error) {
    noteTonRpcRateLimit(error);
    degraded = true;
  }

  const assembled = assemblePublicParts(commentParts)
    .sort((a, b) => new Date(a.createdAt ?? 0).getTime() - new Date(b.createdAt ?? 0).getTime());
  // Bind exactly to THIS post: same filter the feed sync uses (drop only when both hashes present AND mismatch).
  const fresh = assembled.filter((comment) => (
    String(comment.parentEntryId) === String(item.entryId)
    && (!item.bodyHash || !comment.parentHash || String(item.bodyHash).toLowerCase() === String(comment.parentHash).toLowerCase())
  ));
  // Incremental merge: fresh (new) entries win by entryId (mergePublicComments favors its SECOND argument);
  // the snapshot supplies everything below the boundary.
  const comments = snapshot
    ? mergePublicComments(snapshot.comments, fresh)
      .sort((a, b) => new Date(a.createdAt ?? 0).getTime() - new Date(b.createdAt ?? 0).getTime())
    : fresh;
  // Diagnostic snapshot (read via globalThis.plathoLastPublicCommentLoad) so an empty result is debuggable: it
  // pinpoints whether the parent index was missing, the walk returned nothing, bodies failed to resolve, or the
  // parent-binding filter dropped them.
  globalThis.plathoLastPublicCommentLoad = {
    entryId: String(item.entryId), bodyHash: item.bodyHash ?? null,
    parentExists: true, latestLink: String(parentIndex.latest_entry_link ?? ''), entryCount: String(parentIndex.entry_count ?? ''),
    walked: ids.length, resolved: commentParts.length, assembled: assembled.length, comments: comments.length, degraded,
    incremental: snapshot ? `boundary=${String(snapshotBoundary)}` : 'full',
    sampleParents: assembled.slice(0, 5).map((c) => ({ parentEntryId: String(c.parentEntryId ?? ''), parentHash: c.parentHash ?? null, type: c.type })),
  };
  return { comments, degraded, parentExists: true, latestLink };
}

// TRUE when a multipart comment group among the freshly-fetched parts is still missing parts (used to extend
// the incremental walk past the snapshot boundary for a group that straddles it).
function publicCommentPartsHaveIncompleteGroup(parts) {
  const groups = new Map();
  for (const part of parts) {
    const expected = Number(part.partCount ?? 1);
    if (expected <= 1) continue;
    const key = `${part.channelId}:${part.streamId}:${part.parentEntryId ?? ''}:${part.parentHash ?? ''}`;
    const group = groups.get(key) ?? { expected, seen: new Set() };
    group.expected = Math.max(group.expected, expected);
    group.seen.add(Number(part.partIndex ?? 0));
    groups.set(key, group);
  }
  for (const group of groups.values()) {
    if (group.seen.size < group.expected) return true;
  }
  return false;
}

// Orchestrate the on-demand load with a generation token (so a close/reopen abandons stale results) and bounded
// retries on a degraded (rate-limited) walk — keeping the partial result OUT of the authoritative list.
async function refreshPublicPostDetailComments() {
  const item = publicPostDetailItem;
  if (!item) return;
  const token = (publicPostDetailLoadToken += 1);
  publicPostDetailLoadState = publicPostDetailChainComments.length > 0 ? 'ready' : 'loading';
  renderPublicPostDetail();
  // INCREMENTAL cursor: the last clean load's snapshot ({comments, latestLink}) — from the in-memory Map, or
  // (after a reload) from IndexedDB. With it the loader re-reads NOTHING unless new comments actually landed.
  const cacheKey = publicPostCommentsCacheKey(item);
  let snapshot = publicPostCommentsCache.get(cacheKey) ?? null;
  if (!snapshot?.latestLink) {
    const durable = await readCachedPublicComments(cacheKey);
    if (durable?.latestLink) snapshot = durable;
  }
  if (token !== publicPostDetailLoadToken) return;
  const maxAttempts = 6;
  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    let result;
    try {
      result = await loadPublicPostComments(item, { snapshot: snapshot?.latestLink ? snapshot : null });
    } catch (error) {
      console.error(error);
      result = { comments: [], degraded: true };
    }
    if (token !== publicPostDetailLoadToken) return; // closed or reopened — drop this result
    if (!result.degraded) {
      publicPostDetailChainComments = result.comments;
      publicPostDetailParentExists = result.parentExists === true;
      publicPostDetailLoadState = 'ready';
      // Cache the fresh authoritative result so the next open of this post is instant (SWR). Bounded LRU (data
      // URLs can be large): drop the oldest once past the cap.
      if (cacheKey) {
        publicPostCommentsCache.delete(cacheKey);
        publicPostCommentsCache.set(cacheKey, { comments: result.comments, parentExists: result.parentExists === true, latestLink: result.latestLink ?? null });
        while (publicPostCommentsCache.size > 24) {
          publicPostCommentsCache.delete(publicPostCommentsCache.keys().next().value);
        }
        // Durable layer (survives a full reload; localStorage can't hold the image data URLs): IndexedDB.
        writeCachedPublicComments(cacheKey, result.comments, result.parentExists, result.latestLink);
      }
      renderPublicPostDetail();
      return;
    }
    // Degraded: keep the previous authoritative list on screen (don't overwrite with a partial), show "loading",
    // retry. BUT still persist whatever assembled so far into the durable snapshot (accumulate-never-wipe, like
    // the private per-message history) with latestLink=null — so the images that DID resolve paint instantly on
    // the next open, while the null cursor keeps the unchanged-shortcut disarmed (an incomplete feed must be
    // re-walked, not trusted as complete). The per-entry part cache already made those bodies durable; this makes
    // the post snapshot durable too, so a post whose walk never lands fully clean still restores its images.
    if (cacheKey && Array.isArray(result.comments) && result.comments.length > 0) {
      const durablePartial = mergePublicComments(snapshot?.comments ?? [], result.comments);
      if (durablePartial.length > 0) {
        writeCachedPublicComments(cacheKey, durablePartial, publicPostDetailParentExists === true, null);
      }
    }
    publicPostDetailLoadState = publicPostDetailChainComments.length > 0 ? 'ready' : 'loading';
    renderPublicPostDetail();
    await new Promise((resolve) => setTimeout(resolve, 2500));
    if (token !== publicPostDetailLoadToken) return;
  }
  if (token !== publicPostDetailLoadToken) return;
  publicPostDetailLoadState = 'error';
  renderPublicPostDetail();
}

async function confirmPublicCommentsRisk() {
  const result = await openActionDialog({
    title: t('public.openCommentsRiskTitle'),
    hint: t('public.openCommentsRiskHint'),
    tone: 'error',
    submitLabel: t('public.publishWithComments'),
    fields: [],
    summary: [
      t('public.openCommentsRiskAnyone'),
      t('public.openCommentsRiskModeration'),
      t('public.openCommentsRiskPrune'),
      t('public.openCommentsRiskClose'),
    ],
  });
  return result !== null;
}

function renderVaultCards(cards) {
  if (!balanceGrid) return;
  balanceGrid.replaceChildren();
  const visibleCards = cards ?? [];
  balanceGrid.hidden = visibleCards.length === 0;
  for (const card of visibleCards) {
    const article = document.createElement('article');
    article.className = `balance-card${card.tone ? ` ${card.tone}` : ''}`;
    const label = document.createElement('span');
    label.textContent = card.label ?? '';
    const value = document.createElement('strong');
    value.textContent = card.value ?? '';
    const caption = document.createElement('small');
    caption.textContent = card.caption ?? '';
    article.append(label, value, caption);
    balanceGrid.append(article);
  }
}

function renderVaultActions(actions) {
  if (!actionGrid) return;
  actionGrid.replaceChildren();
  const visibleActions = actions ?? [];
  actionGrid.hidden = visibleActions.length === 0;
  for (const action of visibleActions) {
    const button = document.createElement('button');
    button.type = 'button';
    if (action.id) button.dataset.action = action.id;
    appendIcon(button, action.icon ?? 'bolt');
    button.append(document.createTextNode(action.label ?? ''));
    actionGrid.append(button);
  }
}

function renderLedgerRows(rows) {
  if (!ledgerRows) return;
  ledgerRows.replaceChildren();
  const visibleRows = rows ?? [];
  ledgerRows.hidden = visibleRows.length === 0;
  for (const row of visibleRows) {
    const item = document.createElement('div');
    item.className = 'ledger-row';
    const icon = document.createElement('span');
    icon.className = `ledger-icon ${row.tone ?? 'cyan'}`;
    const body = document.createElement('div');
    const title = document.createElement('strong');
    title.textContent = row.title ?? '';
    const detail = document.createElement('small');
    detail.textContent = row.detail ?? '';
    const value = document.createElement('span');
    value.textContent = row.value ?? '';
    body.append(title, detail);
    item.append(icon, body, value);
    ledgerRows.append(item);
  }
}

function renderConfiguredShell() {
  const ui = appConfig.ui ?? {};
  setText(brandNetworkLabel, ui.brandNetworkLabel ?? appConfig.network?.label ?? appConfig.mode);
  setText(appVersionLabel, PLATHO_APP_RUNTIME_VERSION);
  // Mirror on the Profile pane: the rail (and its badge) is hidden on the narrow mobile / TG Mini App layout,
  // and TMA webviews cache hard — the Profile badge is the on-device way to verify which build is running.
  setText(profileVersionLabel, PLATHO_APP_RUNTIME_VERSION);
  renderPaneHeaders();
  setText(identityName, ui.identityName);
  setText(identitySubtitle, ui.identitySubtitle);
  setText(walletRuntimeLabel, ui.walletLabel);
  setText(localStateLabel, ui.localStateLabel);
  setText(networkRuntimeLabel, ui.networkLabel ?? appConfig.network?.label);
  renderVaultCards(ui.vaultCards);
  renderVaultActions(ui.vaultActions);
  renderLedgerRows(ui.ledgerRows);
}

function clonePreviewThreads() {
  return previewThreads.map((thread) => ({
    ...thread,
    messages: (thread.messages ?? []).map((message) => ({ ...message })),
  }));
}

function rebuildThreadsFromPublicSubscriptions(options = {}) {
  const preserveActive = options.preserveActive ?? true;
  const previousActive = activeThreadId;
  const nonPublicThreads = threads.length > 0
    ? threads.filter((thread) => !thread.publicChannelId)
    : clonePreviewThreads();

  threads = nonPublicThreads;
  // Re-resolve wallet-channel names against the current private threads + shared store so feed-mode
  // (which bakes channel.name into its items) stays in sync with the Private dialog display.
  rebuildPublicChannelRegistry();
  // Feed source = subscribed channels UNIONED with the user's own wallet channel (so own posts always show
  // without auto-subscribing). The channels LIST stays subscription-driven (see the channels render).
  publicChannelThreads = publicChannelsToThreads(
    feedSourcePublicChannels(),
    publicFeedCacheForCurrentWindow(),
  );

  if (!preserveActive) {
    // Explicit boot / wallet-reset: default to the first thread (the boot-tail view logic reads this).
    activeThreadId = threads[0]?.id ?? null;
  } else if (previousActive && threads.some((thread) => thread.id === previousActive)) {
    // Keep the user's current selection.
    activeThreadId = previousActive;
  } else if (previousActive) {
    // The selected thread vanished — drop the selection (show the LIST). NEVER default to threads[0] (the Saved
    // "My notes" thread): that would silently drop the user into My notes and let a peer-intended send land there.
    activeThreadId = null;
  } else {
    // No selection: the user was on the dialog LIST (they never opened a chat, or backed out to the list).
    // A preserving rebuild — e.g. a background sync or the resume-after-unlock sync — must NOT silently revive
    // threads[0] here, or a later tab-switch to Private (setView reads activeThreadId) would open that dialog
    // instead of the list the user was on.
    activeThreadId = null;
  }

  renderPublicSurface({ anchorUnread: false });
  renderPaneHeaders();
}

function configuredCapsuleHubAddress() {
  return appConfig.capsuleHub?.address
    ?? globalThis.plathoCapsuleHubAddress
    ?? globalThis.PLATHO_CAPSULEHUB_ADDRESS
    ?? null;
}

function configuredFeeAccumulatorAddress() {
  return appConfig.feeAccumulator?.address
    ?? globalThis.plathoFeeAccumulatorAddress
    ?? globalThis.PLATHO_FEE_ACCUMULATOR_ADDRESS
    ?? null;
}

function configuredProfileRegistryAddress() {
  return appConfig.profileRegistry?.address
    ?? globalThis.plathoProfileRegistryAddress
    ?? globalThis.PLATHO_PROFILE_REGISTRY_ADDRESS
    ?? null;
}

async function resolveCapsuleHubProvider() {
  const address = configuredCapsuleHubAddress();
  if (!address) return null;
  const provider = globalThis.plathoCapsuleHubProvider
    ?? createCapsuleHubTonRpcProvider({ capsuleHubAddress: address });
  if (!provider?.getState || !provider?.getPublicEntry || !provider?.getPrivateEntry) {
    throw new Error('CapsuleHub provider cannot read entries');
  }
  return { provider, address };
}

function tryReadPublicEntryPayload(entry, options = {}) {
  try {
    return readPublicPostPayload({
      header_boc: entry.header_boc,
      body_boc: entry.body_boc,
    }, options);
  } catch (error) {
    console.warn('Skipping malformed public CapsuleHub entry', entry?.entry_id?.toString?.() ?? 'unknown', error);
    return null;
  }
}

async function resolvePublicEntryPayload(provider, entry, address, options = {}) {
  let hydrated = entry;
  if (!entry?.body_boc && provider?.resolvePublicEntryBody) {
    // Durable per-entry body cache FIRST (the private model: local body before the chain). The hit is accepted
    // ONLY when the stored hash matches the entry's on-chain body_hash — bodies are immutable, so a match is
    // authoritative; a mismatch/corrupt record silently falls through to the live read (which then re-writes it).
    const entryBodyHashHex = entry?.body_hash !== undefined && entry?.body_hash !== null ? uint256Hex(entry.body_hash) : null;
    const cachedBody = await readCachedPublicEntryBody(entry?.entry_id);
    if (cachedBody && entryBodyHashHex && cachedBody.body_hash === entryBodyHashHex) {
      hydrated = { ...entry, body_boc: cachedBody.body_boc };
    } else {
      hydrated = await provider.resolvePublicEntryBody(entry, {
        capsuleHubAddress: address,
        vaultAddress: appConfig.vault?.address ?? null,
        messageCacheTtlMs: 0,
        priority: 'critical',
      });
      // Persist the resolved body UNCONDITIONALLY (fire-and-forget) — per-entry, never gated on the caller's
      // overall walk succeeding. A body that resolved once never re-downloads; every reader (feed sync, post
      // detail, avatars-via-payload) shares the hit.
      if (typeof hydrated?.body_boc === 'string' && hydrated.body_boc.length > 0 && entryBodyHashHex) {
        writeCachedPublicEntryBody(entry.entry_id, hydrated.body_boc, entryBodyHashHex);
      }
    }
  }
  const payload = tryReadPublicEntryPayload(hydrated, options);
  if (!payload) return null;
  const authorWallet = hydrated?.author_wallet ?? hydrated?.authorWallet;
  if (authorWallet) payload.authorWallet = String(authorWallet);
  if (hydrated?.body_hash !== undefined && hydrated?.body_hash !== null) payload.bodyHash = uint256Hex(hydrated.body_hash);
  if (hydrated?.entry_uid !== undefined && hydrated?.entry_uid !== null) payload.entryUid = BigInt(hydrated.entry_uid).toString(16);
  const entryCreatedAt = hydrated?.created_at ?? hydrated?.createdAt;
  if (entryCreatedAt !== undefined && entryCreatedAt !== null) {
    try {
      const sec = Number(BigInt(entryCreatedAt));
      if (Number.isFinite(sec) && sec > 0) {
        payload.createdAtSec = sec;
        payload.created_at_sec = sec;
      }
    } catch {
      // Keep the parsed header timestamp when chain metadata is malformed.
    }
  }
  return payload;
}

async function resolvePrivateEntryBody(provider, entry, address, options = {}) {
  if (entry?.body_boc || !provider?.resolvePrivateEntryBody) return entry;
  return provider.resolvePrivateEntryBody(entry, {
    capsuleHubAddress: address,
    vaultAddress: appConfig.vault?.address ?? null,
    messageCacheTtlMs: options.messageCacheTtlMs ?? 0,
    priority: options.priority ?? 'critical',
    verify: options.verify,
    allowUnverifiedCriticalRead: options.allowUnverifiedCriticalRead,
  });
}

async function resolveProfileRegistryProvider() {
  const address = configuredProfileRegistryAddress();
  if (!address) return null;
  const provider = globalThis.plathoProfileRegistryProvider
    ?? createProfileRegistryTonRpcProvider({ profileRegistryAddress: address });
  if (!provider?.getGlobal || !provider?.getAthWalletAddress) {
    throw new Error('ProfileRegistry provider cannot read the registry');
  }
  return { provider, address };
}

// The avatar pointer moved out of ProfileRegistry into the buyer's own KeyShard on 2026-07-21 (the registry's map
// cost 5.0000 cells per profile and capped the product at 13,076 profiles, silently). The registry is still what
// PRICES and settles a purchase, so it keeps its own provider above; reads of the pointer come from here.
//
// The KeyShard address is derived from (wallet, registry), so this provider is handed the SAME registry address
// the registry provider uses. A mismatch would not error — it would derive a live, empty address and report every
// user as having no avatar.
async function resolveProfileAvatarProvider() {
  const address = configuredProfileRegistryAddress();
  if (!address) return null;
  const provider = globalThis.plathoKeyShardProvider
    ?? createKeyShardTonRpcProvider({ profileRegistryAddress: address, decodeAddressSliceBoc: decodeTonAddressSliceBoc });
  if (!provider?.getAvatar || !provider?.getAvatarVersion) {
    throw new Error('KeyShard provider cannot read avatars');
  }
  return { provider, address };
}

function uint256Hex(value) {
  return `0x${BigInt(value).toString(16).padStart(64, '0')}`;
}

function profileAvatarPointerFromRecord(record) {
  if (!record?.exists) return null;
  const pointer = avatarPointerFromFields(Number(record.version ?? 0n), avatarHashHexFromBigInt(record.avatar_hash ?? 0n));
  if (!pointer) return null;
  return {
    ...pointer,
    ownerWallet: record.owner_wallet,
    owner_wallet: record.owner_wallet,
    avatarEntryId: BigInt(record.avatar_entry_id ?? 0n),
    avatar_entry_id: BigInt(record.avatar_entry_id ?? 0n),
    avatarStreamId: streamIdHexFromBigInt(record.avatar_stream_id ?? 0n),
    avatar_stream_id: streamIdHexFromBigInt(record.avatar_stream_id ?? 0n),
    avatarPartCount: Number(record.avatar_part_count ?? 0n),
    avatar_part_count: Number(record.avatar_part_count ?? 0n),
    mediaFormat: Number(record.media_format ?? 0n),
    media_format: Number(record.media_format ?? 0n),
  };
}

function diagnosticBigIntString(value) {
  if (value === undefined || value === null) return null;
  try {
    return BigInt(value).toString();
  } catch {
    return String(value);
  }
}

function diagnosticBigIntOrNull(value) {
  if (value === undefined || value === null) return null;
  try {
    return BigInt(value);
  } catch {
    return null;
  }
}

function profileAvatarPublishDiagnosticParts(publishState) {
  return (publishState?.parts ?? []).map((part) => ({
    index: Number(part?.index ?? 0),
    status: part?.status ?? null,
    publishKind: part?.publishKind ?? part?.publish_kind ?? null,
    clientNonce: part?.clientNonce !== undefined && part?.clientNonce !== null ? String(part.clientNonce) : null,
    publishId: part?.publishId !== undefined && part?.publishId !== null ? String(part.publishId) : null,
    entryId: part?.entryId !== undefined && part?.entryId !== null ? String(part.entryId) : null,
    bodyHash: part?.bodyHash ?? part?.body_hash ?? null,
    headerHash: part?.header0Hash ?? part?.headerHash ?? part?.header_hash ?? null,
    error: part?.error ?? null,
    externalBocLength: typeof part?.externalBoc === 'string' ? part.externalBoc.length : null,
    broadcastRetryCount: Number(part?.broadcastRetryCount ?? 0) || 0,
    lastBroadcastAt: part?.lastBroadcastAt ?? null,
  }));
}

function profileAvatarPublishPayloadDiagnostics(payloads) {
  return (payloads ?? []).map((payload, index) => ({
    index,
    kind: payload?.kind ?? null,
    type: payload?.type ?? null,
    sizeClass: payload?.sizeClass ?? payload?.size_class ?? null,
    usefulBytes: payload?.usefulBytes ?? null,
    headerBytes: payload?.headerBytes ?? null,
    bodyBytes: payload?.bodyBytes ?? payload?.bytes ?? null,
    headerBocLength: typeof payload?.headerBoc === 'string' ? payload.headerBoc.length : null,
    bodyBocLength: typeof payload?.bodyBoc === 'string' ? payload.bodyBoc.length : null,
    headerHash: payload?.headerHash ?? payload?.header_hash ?? null,
    bodyHash: payload?.bodyHash ?? payload?.body_hash ?? null,
  }));
}

function profileAvatarPublishBroadcastErrorStatus(diagnostics) {
  const snapshots = [...(diagnostics?.snapshots ?? [])].reverse();
  for (const snapshot of snapshots) {
    const part = (snapshot?.parts ?? []).find((item) => item?.error);
    if (part?.error) return shortUiErrorText({ message: part.error }, 'TON RPC broadcast failed');
  }
  if (diagnostics?.initialPublishError) {
    return shortUiErrorText({ message: diagnostics.initialPublishError }, 'TON RPC broadcast failed');
  }
  return null;
}

async function readProfileAvatarPublishChainSnapshot(ownerWallet, publishState, label) {
  const snapshot = {
    label,
    at: new Date().toISOString(),
    ownerWallet,
    vaultAddress: null,
    capsuleHubAddress: null,
    userPublishNonce: null,
    userTonBalance: null,
    vaultPendingPublishCount: null,
    capsulePublicLatestId: null,
    capsulePrivateLatestId: null,
    publishStateStatus: publishState?.status ?? null,
    publishStateConfirmedCount: Number(publishState?.confirmedCount ?? 0) || 0,
    publishStateSubmittedCount: Number(publishState?.submittedCount ?? 0) || 0,
    parts: profileAvatarPublishDiagnosticParts(publishState),
    vaultError: null,
    capsuleHubError: null,
  };
  try {
    snapshot.vaultAddress = requireVaultAddress();
    const provider = await resolveVaultChainProvider();
    if (provider?.getUser) {
      const user = await provider.getUser(ownerWallet, {
        vaultAddress: snapshot.vaultAddress,
        verify: true,
        priority: 'critical',
        cacheTtlMs: 0,
      });
      snapshot.userPublishNonce = diagnosticBigIntString(user?.publish_nonce ?? user?.publishNonce);
      snapshot.userTonBalance = diagnosticBigIntString(user?.ton_balance ?? user?.tonBalance);
    }
    if (provider?.getGlobal) {
      const global = await provider.getGlobal({
        vaultAddress: snapshot.vaultAddress,
        verify: true,
        priority: 'critical',
        cacheTtlMs: 0,
      });
      snapshot.vaultPendingPublishCount = diagnosticBigIntString(global?.pending_publish_count ?? global?.pendingPublishCount);
    }
  } catch (error) {
    snapshot.vaultError = String(error?.message ?? error);
  }
  try {
    const resolved = await resolveCapsuleHubProvider();
    snapshot.capsuleHubAddress = resolved?.address ?? null;
    if (resolved?.provider?.getState) {
      const state = await resolved.provider.getState(criticalCapsuleHubReadOptions(resolved.address));
      snapshot.capsulePublicLatestId = diagnosticBigIntString(state?.public_latest_id ?? state?.publicLatestId);
      snapshot.capsulePrivateLatestId = diagnosticBigIntString(state?.private_latest_id ?? state?.privateLatestId);
    }
  } catch (error) {
    snapshot.capsuleHubError = String(error?.message ?? error);
  }
  return snapshot;
}

function profileAvatarPublishDiagnosticStatus(diagnostics) {
  const snapshots = diagnostics?.snapshots ?? [];
  const before = snapshots.find((item) => item.label === 'before-public-publish');
  const after = snapshots.findLast?.((item) => item.label === 'after-avatar-not-visible')
    ?? [...snapshots].reverse().find((item) => item.label === 'after-avatar-not-visible');
  if (!before || !after) return null;
  const beforeNonce = diagnosticBigIntOrNull(before.userPublishNonce);
  const afterNonce = diagnosticBigIntOrNull(after.userPublishNonce);
  const beforePublic = diagnosticBigIntOrNull(before.capsulePublicLatestId);
  const afterPublic = diagnosticBigIntOrNull(after.capsulePublicLatestId);
  const beforePending = diagnosticBigIntOrNull(before.vaultPendingPublishCount);
  const afterPending = diagnosticBigIntOrNull(after.vaultPendingPublishCount);
  if (afterPublic !== null && beforePublic !== null && afterPublic > beforePublic) {
    return 'CapsuleHub entry appeared; avatar search failed';
  }
  if (afterPending !== null && beforePending !== null && afterPending > beforePending) {
    return 'Vault publish pending; CapsuleHub ACK not seen yet';
  }
  if (afterNonce !== null && beforeNonce !== null && afterNonce > beforeNonce) {
    return 'Vault accepted publish, but CapsuleHub entry was not created';
  }
  const broadcastError = profileAvatarPublishBroadcastErrorStatus(diagnostics);
  if (broadcastError) return `TON RPC broadcast failed: ${broadcastError}`;
  return null;
}

function publicAvatarPartMatches(payload, ownerWallet, pointer) {
  if (payload?.type !== 'avatar') return false;
  if (String(payload.avatarHash ?? payload.avatar_hash ?? '').toLowerCase() !== pointer.avatarHash.toLowerCase()) return false;
  const pointerStreamId = pointer.avatarStreamId ?? pointer.avatar_stream_id ?? null;
  if (pointerStreamId && String(payload.stream_id ?? '').toLowerCase() !== String(pointerStreamId).toLowerCase()) return false;
  if (pointer.profileVersion && Number(payload.profileVersion ?? payload.profile_version ?? 0) !== Number(pointer.profileVersion)) return false;
  if (pointer.avatarPartCount && Number(payload.partCount ?? payload.part_count ?? 0) !== Number(pointer.avatarPartCount)) return false;
  if (ownerWallet && payload.authorWallet && !sameWalletAddress(payload.authorWallet, ownerWallet)) return false;
  return true;
}

// clean-17 avatar-part match: PPH2 dropped the per-part avatar_hash/profile_version from the header (they were the
// free avatar-from-header bypass, mandatory fix #4), so a shard avatar part is matched by streamId + partCount +
// owner, and the AUTHORITATIVE check is the whole-image sha256 against the PAID KeyShard pointer.avatarHash, done in
// cacheAssembledAvatarParts. The pointer's avatar_stream_id/avatar_part_count come from the paid KeyShard pointer.
function publicAvatarPartMatchesShard(payload, ownerWallet, pointer) {
  if (payload?.type !== 'avatar') return false;
  const pointerStreamId = pointer.avatarStreamId ?? pointer.avatar_stream_id ?? null;
  if (pointerStreamId && String(payload.stream_id ?? '').toLowerCase() !== String(pointerStreamId).toLowerCase()) return false;
  if (pointer.avatarPartCount && Number(payload.partCount ?? payload.part_count ?? 0) !== Number(pointer.avatarPartCount)) return false;
  if (ownerWallet && payload.authorWallet && !sameWalletAddress(payload.authorWallet, ownerWallet)) return false;
  return true;
}

// Read the avatar image bytes from the owner's AVATAR PublicShard (kind 3) and verify them against the paid pointer.
// The pointer (from KeyShard) is authoritative; the shard only stores bytes, authenticated by sha256 == avatarHash.
async function readAvatarPartsFromShard(ownerWallet, pointer) {
  const cached = await readProfileAvatarMediaCache(pointer?.avatarHash);
  if (cached) return cached;
  if (!pointer) return null;
  const lane = directPublicLaneReader();
  if (!lane) return null;
  let messages;
  try { ({ messages } = await lane.readAvatarParts(ownerWallet)); }
  catch (error) { console.warn('[public] avatar shard read failed', error); return null; }
  const parts = [];
  for (const message of messages ?? []) {
    const parsed = parsePublicPublish(message.bodyCell);
    if (!parsed) continue;
    let payload;
    try { payload = readPublicPostPayloadV2({ header: parsed.header, body: parsed.body }); } catch { continue; }
    payload.authorWallet = message.source ? (rawWalletAddress(publicAddrKey(message.source)) ?? publicAddrKey(message.source)) : ownerWallet;
    if (!publicAvatarPartMatchesShard(payload, ownerWallet, pointer)) continue;
    parts.push({ ...payload, imageBytes: payload.imageBytes ?? payload.image_bytes });
  }
  const assembled = await assembledAvatarPartGroup(parts, pointer);
  return assembled?.imageUrl ?? null;
}

function avatarPartStreamId(part) {
  return String(part?.stream_id ?? part?.streamId ?? '').toLowerCase();
}

function avatarPartsCompleteForPointer(parts, pointer) {
  const expected = Number(pointer.avatarPartCount ?? pointer.partCount ?? 0);
  if (!Number.isSafeInteger(expected) || expected <= 0) return false;
  const groups = new Map();
  for (const part of parts ?? []) {
    const index = Number(part.partIndex ?? part.part_index ?? -1);
    if (!Number.isSafeInteger(index) || index < 0 || index >= expected) continue;
    const streamId = avatarPartStreamId(part);
    const group = groups.get(streamId) ?? new Set();
    group.add(index);
    groups.set(streamId, group);
    if (group.size >= expected) return true;
  }
  return false;
}

function assembleAvatarParts(parts, pointer) {
  const expected = Number(pointer.avatarPartCount ?? pointer.partCount ?? 0);
  if (!Number.isSafeInteger(expected) || expected <= 0 || expected > 16) return null;
  const unique = new Map();
  for (const part of parts ?? []) {
    const index = Number(part.partIndex ?? part.part_index ?? -1);
    if (!Number.isSafeInteger(index) || index < 0 || index >= expected) continue;
    unique.set(index, part);
  }
  if (unique.size !== expected) return null;
  const ordered = [...unique.values()].sort((a, b) => Number(a.partIndex ?? 0) - Number(b.partIndex ?? 0));
  const bytes = new Uint8Array(ordered.reduce((sum, item) => sum + (item.imageBytes?.length ?? item.image_bytes?.length ?? 0), 0));
  let offset = 0;
  for (const item of ordered) {
    const chunk = item.imageBytes ?? item.image_bytes;
    if (!chunk?.length) return null;
    bytes.set(chunk, offset);
    offset += chunk.length;
  }
  return bytes;
}

async function assembledAvatarPartGroup(parts, pointer) {
  const groups = new Map();
  for (const part of parts ?? []) {
    const streamId = avatarPartStreamId(part);
    const group = groups.get(streamId) ?? [];
    group.push(part);
    groups.set(streamId, group);
  }
  for (const groupParts of groups.values()) {
    const imageUrl = await cacheAssembledAvatarParts(groupParts, pointer);
    if (!imageUrl) continue;
    return {
      imageUrl,
      parts: groupParts,
      streamId: groupParts[0]?.stream_id ?? groupParts[0]?.streamId ?? null,
    };
  }
  return null;
}

async function cacheAssembledAvatarParts(parts, pointer) {
  const bytes = assembleAvatarParts(parts, pointer);
  if (!bytes) return null;
  const hash = await sha256Hex(bytes);
  if (hash.toLowerCase() !== pointer.avatarHash.toLowerCase()) return null;
  const url = bytesToImageDataUrl(bytes, 'image/webp');
  await writeProfileAvatarMediaCache(pointer.avatarHash, url);
  return url;
}

async function readAvatarPartsFromCapsuleHub(ownerWallet, pointer, options = {}) {
  const cached = await readProfileAvatarMediaCache(pointer?.avatarHash);
  if (cached) return cached;
  const resolved = await resolveCapsuleHubProvider();
  if (!resolved || !pointer) return null;
  const { provider, address } = resolved;
  const readOptions = criticalCapsuleHubReadOptions(address);
  const parts = [];
  const start = publicEntryIdBigInt(pointer.avatarEntryId ?? pointer.avatar_entry_id);
  if (start !== null && start >= 0n) {
    const maxExtra = BigInt(Math.max(PROFILE_AVATAR_ENTRY_SCAN_PADDING, Number(pointer.avatarPartCount ?? 0) + PROFILE_AVATAR_ENTRY_SCAN_PADDING));
    for (let entryId = start; entryId <= start + maxExtra; entryId += 1n) {
      try {
        const entry = await provider.getPublicEntry(entryId, readOptions);
        if (entry.exists !== true) continue;
        const payload = await resolvePublicEntryPayload(provider, entry, address, { maxBytes: PUBLIC_POST_BODY_MAX_BYTES });
        if (!payload) continue;
        payload.authorWallet = String(entry.author_wallet ?? '');
        if (!publicAvatarPartMatches(payload, ownerWallet, pointer)) continue;
        parts.push({
          ...payload,
          entryId: entry.entry_id?.toString?.() ?? entryId.toString(),
          imageBytes: payload.imageBytes ?? payload.image_bytes,
        });
        if (avatarPartsCompleteForPointer(parts, pointer)) break;
      } catch (error) {
        if (!/not found|missing|does not exist/i.test(String(error?.message ?? error))) console.error(error);
      }
    }
    const assembled = await assembledAvatarPartGroup(parts, pointer);
    if (assembled?.imageUrl) return assembled.imageUrl;
  }

  const state = await provider.getState(readOptions);
  const latest = BigInt(state.public_latest_id ?? 0n);
  const configuredLimit = Number(options.scanLimit ?? appConfig.capsuleHub?.publicAvatarReadLimit ?? 0);
  const limit = BigInt(Math.max(
    PROFILE_AVATAR_FALLBACK_SCAN_LIMIT,
    Number.isFinite(configuredLimit) ? Math.max(0, Math.floor(configuredLimit)) : 0,
  ));
  const floor = latest > limit ? latest - limit : 0n;
  for (let entryId = latest - 1n; entryId >= floor; entryId -= 1n) {
    const entry = await provider.getPublicEntry(entryId, readOptions);
    if (entry.exists !== true) {
      if (entryId === 0n) break;
      continue;
    }
    const payload = await resolvePublicEntryPayload(provider, entry, address, { maxBytes: PUBLIC_POST_BODY_MAX_BYTES });
    if (!payload) {
      if (entryId === 0n) break;
      continue;
    }
    payload.authorWallet = String(entry.author_wallet ?? '');
    if (publicAvatarPartMatches(payload, ownerWallet, pointer)) {
      parts.push({
        ...payload,
        entryId: entry.entry_id?.toString?.() ?? entryId.toString(),
        imageBytes: payload.imageBytes ?? payload.image_bytes,
      });
      if (avatarPartsCompleteForPointer(parts, pointer)) break;
    }
    if (entryId === 0n) break;
  }
  return (await assembledAvatarPartGroup(parts, pointer))?.imageUrl ?? null;
}

function minPublicEntryIdFromPublishState(publishState) {
  let min = null;
  for (const part of publishState?.parts ?? []) {
    if (publishPartKind(part) !== 'public') continue;
    const value = publicEntryIdBigInt(part?.entryId);
    if (value === null || value < 0n) continue;
    if (min === null || value < min) min = value;
  }
  return min;
}

async function findPublishedAvatarEntries(ownerWallet, pointer, options = {}) {
  const resolved = await resolveCapsuleHubProvider();
  if (!resolved) throw new Error('CapsuleHub provider is required to confirm avatar capsules');
  const { provider, address } = resolved;
  const readOptions = criticalCapsuleHubReadOptions(address);
  const expectedParts = Number(pointer.avatarPartCount ?? 0);
  if (!Number.isSafeInteger(expectedParts) || expectedParts <= 0) throw new Error('Avatar part count is invalid');
  const parts = [];
  // Fast path: when the publish already assigned a first entry id, the batch parts are contiguous
  // from there, so read a SMALL window (parts + a little slack) instead of scanning thousands of
  // entries from the chain tip. This keeps a 2-part confirm to a handful of reads — decisive under a
  // throttled ~1rps verifier where the wide latest-down scan is what makes it stall for minutes.
  const targetedStart = publicEntryIdBigInt(pointer.avatarEntryId ?? pointer.avatar_entry_id);
  if (targetedStart !== null && targetedStart >= 0n) {
    const targetedEnd = targetedStart + BigInt(expectedParts + 8);
    for (let entryId = targetedStart; entryId <= targetedEnd; entryId += 1n) {
      const entry = await provider.getPublicEntry(entryId, readOptions);
      if (entry.exists !== true) continue;
      const payload = await resolvePublicEntryPayload(provider, entry, address, { maxBytes: PUBLIC_POST_BODY_MAX_BYTES });
      if (!payload) continue;
      payload.authorWallet = String(entry.author_wallet ?? '');
      if (!publicAvatarPartMatches(payload, ownerWallet, pointer)) continue;
      parts.push({
        ...payload,
        entryId: entry.entry_id?.toString?.() ?? entryId.toString(),
        imageBytes: payload.imageBytes ?? payload.image_bytes,
      });
      if (avatarPartsCompleteForPointer(parts, pointer)) break;
    }
  }
  if (!avatarPartsCompleteForPointer(parts, pointer)) {
    const state = await provider.getState(readOptions);
    const latest = BigInt(state.public_latest_id ?? 0n);
    // options.fallbackScanLimit caps the wide latest-down sweep for callers that only care about a RECENT
    // republish (the pre-publish "already published?" check) — the default stays the deep recovery scan.
    const requestedFallbackLimit = Number(options.fallbackScanLimit ?? 0);
    const limit = BigInt(requestedFallbackLimit > 0
      ? Math.max(requestedFallbackLimit, expectedParts)
      : Math.max(PROFILE_AVATAR_FALLBACK_SCAN_LIMIT, expectedParts + PROFILE_AVATAR_ENTRY_SCAN_PADDING));
    const floor = latest > limit ? latest - limit : 0n;
    for (let entryId = latest - 1n; entryId >= floor; entryId -= 1n) {
      const entry = await provider.getPublicEntry(entryId, readOptions);
      if (entry.exists === true) {
        const payload = await resolvePublicEntryPayload(provider, entry, address, { maxBytes: PUBLIC_POST_BODY_MAX_BYTES });
        if (!payload) {
          if (entryId === 0n) break;
          continue;
        }
        payload.authorWallet = String(entry.author_wallet ?? '');
        if (publicAvatarPartMatches(payload, ownerWallet, pointer)) {
          parts.push({
            ...payload,
            entryId: entry.entry_id?.toString?.() ?? entryId.toString(),
            imageBytes: payload.imageBytes ?? payload.image_bytes,
          });
          if (avatarPartsCompleteForPointer(parts, pointer)) break;
        }
      }
      if (entryId === 0n) break;
    }
  }
  const assembled = await assembledAvatarPartGroup(parts, pointer);
  if (!assembled?.imageUrl) return null;
  const firstEntryId = assembled.parts.reduce((min, part) => {
    const value = publicEntryIdBigInt(part.entryId) ?? min;
    return value < min ? value : min;
  }, publicEntryIdBigInt(assembled.parts[0]?.entryId) ?? 0n);
  return {
    imageUrl: assembled.imageUrl,
    firstEntryId,
    parts: assembled.parts,
    streamId: assembled.streamId,
    confirmedBy: 'recovered_from_existing_identical_payload',
  };
}

async function findConfirmedAvatarEntriesFromPublishState(ownerWallet, pointer, publishState) {
  const expectedParts = Number(pointer?.avatarPartCount ?? pointer?.partCount ?? 0);
  if (!Number.isSafeInteger(expectedParts) || expectedParts <= 0) return null;
  const confirmedParts = (publishState?.parts ?? []).filter((part) => (
    publishPartKind(part) === 'public'
    && part.status === PUBLISH_PART_STATUS_CAPSULEHUB_CONFIRMED
    && part.entryId !== undefined
    && part.entryId !== null
  )).sort((left, right) => Number(left?.index ?? 0) - Number(right?.index ?? 0));
  // With FEWER confirmed parts than the pointer expects the group can never assemble (the hash of a partial
  // set cannot match) — return without chain reads. The mobilized loop calls this every ~1.5s pass, and in
  // the window between batch confirmations the read fallback below would burn verified entry+payload reads
  // per pass just to fail the assembly.
  if (confirmedParts.length < expectedParts) return null;
  if (confirmedParts.length >= expectedParts) {
    const byIndex = new Map();
    for (const part of confirmedParts) {
      const index = Number(part.index ?? -1);
      if (!Number.isSafeInteger(index) || index < 0 || index >= expectedParts) continue;
      byIndex.set(index, part);
    }
    if (byIndex.size >= expectedParts) {
      const ordered = [...byIndex.values()].sort((left, right) => Number(left.index ?? 0) - Number(right.index ?? 0));
      const firstEntryId = ordered.reduce((min, part) => {
        const value = publicEntryIdBigInt(part.entryId) ?? min;
        return value < min ? value : min;
      }, publicEntryIdBigInt(ordered[0]?.entryId) ?? 0n);
      return {
        imageUrl: await readProfileAvatarMediaCache(pointer.avatarHash),
        firstEntryId,
        parts: ordered.map((part) => ({
          entryId: String(part.entryId),
          partIndex: Number(part.index ?? 0),
          part_count: expectedParts,
          partCount: expectedParts,
          bodyHash: part.bodyHash ?? null,
          headerHash: part.header0Hash ?? null,
          stream_id: pointer.avatarStreamId ?? pointer.avatar_stream_id ?? null,
          streamId: pointer.avatarStreamId ?? pointer.avatar_stream_id ?? null,
          avatarHash: pointer.avatarHash,
          avatar_hash: pointer.avatarHash,
        })),
        streamId: pointer.avatarStreamId ?? pointer.avatar_stream_id ?? null,
        confirmedBy: 'publish_state_hashes',
      };
    }
  }
  const resolved = await resolveCapsuleHubProvider();
  if (!resolved) return null;
  const { provider, address } = resolved;
  const readOptions = criticalCapsuleHubReadOptions(address);
  const parts = [];
  for (const part of confirmedParts) {
    const entryId = publicEntryIdBigInt(part.entryId);
    if (entryId === null || entryId < 0n) continue;
    const entry = await provider.getPublicEntry(entryId, readOptions);
    if (entry.exists !== true) continue;
    const payload = await resolvePublicEntryPayload(provider, entry, address, { maxBytes: PUBLIC_POST_BODY_MAX_BYTES });
    if (!payload) continue;
    payload.authorWallet = String(entry.author_wallet ?? '');
    if (!publicAvatarPartMatches(payload, ownerWallet, pointer)) continue;
    parts.push({
      ...payload,
      entryId: entry.entry_id?.toString?.() ?? entryId.toString(),
      imageBytes: payload.imageBytes ?? payload.image_bytes,
    });
  }
  const assembled = await assembledAvatarPartGroup(parts, pointer);
  if (!assembled?.imageUrl) return null;
  const firstEntryId = assembled.parts.reduce((min, part) => {
    const value = publicEntryIdBigInt(part.entryId) ?? min;
    return value < min ? value : min;
  }, publicEntryIdBigInt(assembled.parts[0]?.entryId) ?? 0n);
  return {
    imageUrl: assembled.imageUrl,
    firstEntryId,
    parts: assembled.parts,
    streamId: assembled.streamId,
  };
}

async function waitForProfileAvatarRegistryUpdate(ownerWallet, avatarHash) {
  const expectedHash = normalizeAvatarHashHex(avatarHash);
  let lastTransientError = null;
  for (let attempt = 0; attempt < PROFILE_AVATAR_PUBLISH_CONFIRM_ATTEMPTS; attempt += 1) {
    try {
      const pointer = await readCurrentProfileAvatarPointerFromChain(ownerWallet, { required: true });
      if (pointer?.avatarHash?.toLowerCase() === expectedHash.toLowerCase()) return pointer;
      lastTransientError = null;
    } catch (error) {
      if (!isTonRpcRecoverableReadError(error) && !noteTonRpcRateLimit(error)) throw error;
      lastTransientError = error;
    }
    await delay(PROFILE_AVATAR_PUBLISH_CONFIRM_DELAY_MS);
  }
  if (lastTransientError) throw lastTransientError;
  throw new Error('Avatar registry update is not visible on-chain yet');
}

async function loadProfileAvatarImage(ownerWallet, pointer = null) {
  if (!ownerWallet) return null;
  // Callers hand over BOTH raw and user-friendly (UQ/EQ) forms — e.g. a thread keyed by a pasted UQ address
  // hydrating its avatar — and the profile-registry provider requires raw: normalize ONCE here (this also
  // unifies the load-promise / media-cache key across the two spellings of the same wallet).
  ownerWallet = rawWalletAddress(ownerWallet) ?? ownerWallet;
  const requestedPointer = pointer ? avatarPointerFromFields(pointer.profileVersion ?? pointer.profile_version, pointer.avatarHash ?? pointer.avatar_hash) : null;
  const cached = requestedPointer ? await readProfileAvatarMediaCache(requestedPointer.avatarHash) : null;
  if (cached) return cached;
  const key = `${ownerWallet}:${requestedPointer?.profileVersion ?? 'current'}:${requestedPointer?.avatarHash ?? 'current'}`;
  if (profileAvatarLoadPromises.has(key)) return profileAvatarLoadPromises.get(key);
  const promise = enqueueAvatarChainRead(async () => {
    const resolved = await resolveProfileAvatarProvider();
    if (!resolved) return null;
    const readOptions = { profileRegistryAddress: resolved.address, ...criticalChainReadOptions() };
    const record = requestedPointer
      ? await resolved.provider.getAvatarVersion(ownerWallet, requestedPointer.profileVersion, readOptions)
      : await resolved.provider.getAvatar(ownerWallet, readOptions);
    const recordPointer = profileAvatarPointerFromRecord(record);
    if (!recordPointer) return null;
    if (requestedPointer && recordPointer.avatarHash.toLowerCase() !== requestedPointer.avatarHash.toLowerCase()) return null;
    return publicLaneDirectPayEnabled()
      ? readAvatarPartsFromShard(ownerWallet, recordPointer)
      : readAvatarPartsFromCapsuleHub(ownerWallet, recordPointer);
  }).catch((error) => {
    if (!noteTonRpcRateLimit(error)) console.error(error);
    return null;
  }).finally(() => {
    profileAvatarLoadPromises.delete(key);
  });
  profileAvatarLoadPromises.set(key, promise);
  return promise;
}

function attachAvatarUrlToPublicFeedCache(ownerWallet, pointer, imageUrl) {
  if (!ownerWallet || !imageUrl) return false;
  const expected = avatarPointerFromFields(pointer?.profileVersion ?? pointer?.profile_version, pointer?.avatarHash ?? pointer?.avatar_hash);
  let changed = false;
  const updateItem = (item) => {
    if (!item || !sameWalletAddress(item.authorWallet ?? item.author_wallet ?? '', ownerWallet)) return item;
    const itemPointer = avatarPointerFromFields(item.profileVersion ?? item.profile_version, item.avatarHash ?? item.avatar_hash);
    if (expected && (!itemPointer || itemPointer.avatarHash.toLowerCase() !== expected.avatarHash.toLowerCase())) return item;
    if (!expected && itemPointer) return item;
    if (item.avatarImageUrl === imageUrl) return item;
    changed = true;
    return { ...item, avatarImageUrl: imageUrl };
  };
  const next = {};
  for (const [channelId, record] of Object.entries(publicChannelFeedCache ?? {})) {
    const feed = record?.feed ?? record;
    if (!feed?.posts) {
      next[channelId] = record;
      continue;
    }
    const posts = feed.posts.map((post) => {
      const updatedPost = updateItem(post);
      const comments = (updatedPost.comments ?? []).map(updateItem);
      return comments === updatedPost.comments ? updatedPost : { ...updatedPost, comments };
    });
    const updatedFeed = { ...feed, posts };
    next[channelId] = record?.feed ? { ...record, feed: updatedFeed } : updatedFeed;
  }
  if (changed) publicChannelFeedCache = next;
  return changed;
}

function publicChannelIdForAuthorWallet(authorWallet) {
  const wallet = rawWalletAddress(authorWallet) ?? String(authorWallet ?? '').trim();
  return publicChannelRegistry.find((channel) => publicChannelMatchesAuthorWallet(channel, wallet))?.id
    ?? ensurePublicChannelForAuthorWallet(wallet);
}

// The user's OWN wallet channel. FIND-only (no side effects: does NOT register/subscribe), so it is safe to call
// on every render/sync. Smart default: if the channel is not yet in the registry — a fresh import or a local-data
// wipe leaves the registry without it until the first publish re-registers it — SYNTHESIZE it from the wallet so
// the own channel is ALWAYS a feed source and the user's own posts load + show even before they post this session.
// The synthesized object uses the same id (`wallet:<addr>`) and shape as ensurePublicChannelForAuthorWallet, so the
// first publish's registration is idempotent (same id) and nothing duplicates.
function ownPublicChannel() {
  // Fall back to the plaintext address persisted in storage (storedPlathoWalletRecord().address — no decryption) so
  // the own channel is a feed source even when the wallet is LOCKED (auto-lock) or still loading at boot. Without it,
  // plathoWallet is null while locked, so ownPublicChannel returned null, feedSourcePublicChannels dropped the own
  // channel, and the user could not find their OWN channel in the public list (had to manually subscribe to self).
  // Mirrors isOwnPublicAuthor's fallback.
  const wallet = rawWalletAddress(plathoWallet?.address ?? storedPlathoWalletRecord()?.address);
  if (!wallet) return null;
  const existing = publicChannelRegistry.find((channel) => publicChannelMatchesAuthorWallet(channel, wallet));
  if (existing) return existing;
  return {
    id: `wallet:${wallet}`,
    name: t('public.you'),
    avatar: publicChannelAvatar(t('public.you')),
    subtitle: t('public.ownChannelSubtitle', { address: shortAddress(wallet) }),
    authorWallet: wallet,
  };
}

// The set of channels that feed the Public FEED: everything the user is subscribed to, PLUS their own wallet
// channel — so a user always sees their OWN posts without auto-subscribing (auto-subscribe was killed in
// clean-10). The own channel is included as an implicit feed source only; the persisted subscription store is
// never mutated, so the channels LIST stays driven by real subscriptions and the per-author scalability bound
// is preserved (cost adds at most ONE author index — the user's own).
function feedSourcePublicChannels() {
  const subscribed = subscribedPublicChannels(publicChannelSubscriptions, publicChannelRegistry);
  const own = ownPublicChannel();
  const channels = (!own || subscribed.some((channel) => channel.id === own.id)) ? subscribed : [...subscribed, own];
  // A channel open in the CHANNEL VIEW but not followed rides along as a TRANSIENT source, so the standard sync
  // walk (multipart, comments, eviction — one battle-tested code path) fetches its posts for the preview. The main
  // feed render filters it out until followed (renderPublicSurface); closing the view drops it again.
  if (publicChannelPreviewChannelId && !channels.some((channel) => channel.id === publicChannelPreviewChannelId)) {
    const preview = publicChannelRegistry.find((channel) => channel.id === publicChannelPreviewChannelId);
    if (preview) return [...channels, preview];
  }
  return channels;
}

// ---- Subscription persistence (Phase 2 v1): full snapshot stored as a private capsule to SELF -----------------
// Public-channel subscriptions live only in localStorage and are lost on a data wipe / new device. v1 persists them
// on-chain (recoverable from the key like everything else): the user taps "Save subscriptions" to publish a FULL
// snapshot as a private capsule addressed to themselves; a fresh device restores it from the recipient-index walk.
// No silent/background write — only the explicit button (piggyback is Phase 2.1). Latest snapshot wins (per-channel
// LWW is a 2.1 refinement). The own + official channels are implicit (never stored).
const PREFS_SNAPSHOT_VERSION = 1;
const PREFS_DIRTY_STORAGE_KEY = 'platho.prefs.dirty.v1';
const PREFS_LAST_SYNCED_STORAGE_KEY = 'platho.prefs.lastSyncedAt.v1';
let prefsDirty = false;
let prefsLastSyncedAt = null; // unix sec of the last snapshot written or restored, or null if never
let pendingRestoredPrefsSnapshots = [];
// Monotonic edit counter: bumped on EVERY follow/unfollow (even while already dirty). A save captures this at
// snapshot time; a CONFIRMED publish clears dirty ONLY if the counter is unchanged. If the user edited during the
// (possibly ~75s) confirm window, the on-chain snapshot is stale — clearing dirty would silently discard that edit.
let prefsEditEpoch = 0;

function loadPrefsSyncMeta() {
  const storage = publicChannelStorage();
  try {
    prefsDirty = storage?.getItem(PREFS_DIRTY_STORAGE_KEY) === '1';
    const at = Number(storage?.getItem(PREFS_LAST_SYNCED_STORAGE_KEY) ?? '');
    prefsLastSyncedAt = Number.isFinite(at) && at > 0 ? at : null;
  } catch {
    prefsDirty = false;
    prefsLastSyncedAt = null;
  }
}

function writePrefsDirty(value) {
  prefsDirty = Boolean(value);
  try { publicChannelStorage()?.setItem(PREFS_DIRTY_STORAGE_KEY, prefsDirty ? '1' : '0'); } catch { /* advisory */ }
  refreshPrefsSyncUi();
}

function markPrefsDirty() {
  prefsEditEpoch += 1; // bump on every edit, even when already dirty, so a background confirm can detect its snapshot went stale
  if (!prefsDirty) writePrefsDirty(true);
}

function setPrefsLastSyncedAt(sec) {
  prefsLastSyncedAt = Number.isFinite(sec) && sec > 0 ? Math.floor(sec) : null;
  try {
    if (prefsLastSyncedAt) publicChannelStorage()?.setItem(PREFS_LAST_SYNCED_STORAGE_KEY, String(prefsLastSyncedAt));
  } catch { /* advisory */ }
}

// Full snapshot of the user's FOLLOWED wallet channels (+ explicit unfollows). Official + own channels are implicit.
function buildPrefsSnapshot() {
  const nowSec = Math.floor(Date.now() / 1000);
  const ownWallet = rawWalletAddress(plathoWallet?.address);
  const subById = new Map((publicChannelSubscriptions?.channels ?? []).map((c) => [c.id, c.subscribed === true]));
  const customById = new Map((customPublicChannels ?? []).map((c) => [c.id, c]));
  const channels = [];
  for (const id of new Set([...subById.keys(), ...customById.keys()])) {
    if (id === DEFAULT_PUBLIC_CHANNEL_ID) continue;
    const authorWallet = customById.get(id)?.authorWallet ?? null;
    if (authorWallet && ownWallet && sameWalletAddress(authorWallet, ownWallet)) continue; // own channel is implicit
    channels.push({ id, w: authorWallet, sub: subById.get(id) === true, name: customById.get(id)?.name ?? null, ts: nowSec });
  }
  // Also remember this wallet's .ath names so a cleared/re-imported device gets its "linked names" back. The
  // quick-pick list (readKnownPlathoUsernames unions the currently-linked name) + which one is the active display.
  // These are this wallet's own NFTs and re-verified on use, so restoring them is safe.
  const usernames = ownWallet ? readKnownPlathoUsernames(plathoWallet?.address) : [];
  const linked = ownWallet ? (readLinkedPlathoUsername(plathoWallet?.address)?.label ?? null) : null;
  return { v: PREFS_SNAPSHOT_VERSION, writtenAt: nowSec, channels, usernames, linked };
}

function serializePrefsSnapshotBytes(snapshot) {
  return new TextEncoder().encode(JSON.stringify(snapshot));
}

function parsePrefsSnapshotBytes(bytes) {
  try {
    const obj = JSON.parse(new TextDecoder().decode(bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes ?? [])));
    if (!obj || obj.v !== PREFS_SNAPSHOT_VERSION || !Array.isArray(obj.channels)) return null;
    return obj;
  } catch {
    return null;
  }
}

// Restore the wallet's known .ath names from a snapshot — additive (a union of quick-picks, re-verified on use), so
// safe to run regardless of the subscription auto-apply gate. This is what makes the profile remember its linked
// names after a local clear + re-import.
function restoreKnownUsernamesFromSnapshot(snapshot) {
  if (!Array.isArray(snapshot?.usernames)) return;
  for (const label of snapshot.usernames) {
    if (typeof label === 'string' && label.trim()) addKnownPlathoUsername(label.trim());
  }
}

// Apply a restored snapshot to local subscriptions (v1: the snapshot wins). Registers its wallet channels, sets the
// subscribed flags, pulls posts. NOT a user change → does not mark dirty; records the snapshot as last-synced.
function applyPrefsSnapshot(snapshot) {
  if (!snapshot || !Array.isArray(snapshot.channels)) return false;
  for (const ch of snapshot.channels) {
    if (!ch?.id || ch.id === DEFAULT_PUBLIC_CHANNEL_ID || !ch.w) continue;
    if (customPublicChannels.some((c) => c.id === ch.id)) continue;
    const normalized = normalizePublicChannelRegistry([{ id: ch.id, authorWallet: ch.w, name: ch.name ?? undefined }]).find((c) => c.id === ch.id);
    if (normalized) customPublicChannels = normalizePublicChannelRegistry([...customPublicChannels, normalized]);
  }
  writeCustomPublicChannels();
  rebuildPublicChannelRegistry();
  const subById = new Map((publicChannelSubscriptions?.channels ?? []).map((c) => [c.id, c.subscribed === true]));
  for (const ch of snapshot.channels) {
    if (ch?.id && ch.id !== DEFAULT_PUBLIC_CHANNEL_ID) subById.set(ch.id, ch.sub === true);
  }
  publicChannelSubscriptions = {
    version: publicChannelSubscriptions?.version ?? 1,
    activeChannelId: publicChannelSubscriptions?.activeChannelId ?? null,
    channels: publicChannelRegistry.map((item) => ({ id: item.id, subscribed: subById.get(item.id) === true })),
  };
  writePublicChannelSubscriptions(publicChannelStorage(), publicChannelSubscriptions);
  setPrefsLastSyncedAt(snapshot.writtenAt);
  writePrefsDirty(false);
  // Restore the wallet's .ath names (the "linked names" quick-picks) and, when this device has no display name yet,
  // re-link the one the snapshot remembered so the profile shows it again (re-verified on next interaction).
  restoreKnownUsernamesFromSnapshot(snapshot);
  if (typeof snapshot.linked === 'string' && snapshot.linked.trim() && !readLinkedPlathoUsername()) {
    const identity = normalizeLinkedPlathoUsername(snapshot.linked.trim());
    if (identity) {
      writeLinkedPlathoUsername(identity);
      writeWalletDisplayIdentity(identity);
      try { renderWalletIdentity(); } catch { /* profile UI not ready yet; next render picks it up */ }
    }
  }
  rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
  resyncPublicForNewSubscription();
  return true;
}

// A diverted prefs capsule (from the recipient-index walk) parks its snapshot here; drained after the sync pass.
function collectRestoredPrefsSnapshot(bytes) {
  const snapshot = parsePrefsSnapshotBytes(bytes);
  if (snapshot) pendingRestoredPrefsSnapshots.push(snapshot);
}

// v1 restore: auto-apply the newest collected snapshot ONLY on a truly fresh device (never synced here, no local
// follows, no unsaved changes) — so a restore never clobbers in-session local edits. Otherwise just note the time;
// the user reconciles via the Save button. (Cross-device merge / per-channel LWW is Phase 2.1.)
function drainRestoredPrefsSnapshots() {
  if (pendingRestoredPrefsSnapshots.length === 0) return false;
  const snapshots = pendingRestoredPrefsSnapshots;
  pendingRestoredPrefsSnapshots = [];
  const newest = snapshots.reduce((best, s) => (Number(s.writtenAt ?? 0) >= Number(best.writtenAt ?? 0) ? s : best));
  const hasLocalFollows = (publicChannelSubscriptions?.channels ?? [])
    .some((c) => c.subscribed && c.id !== DEFAULT_PUBLIC_CHANNEL_ID);
  if (prefsLastSyncedAt === null && !prefsDirty && !hasLocalFollows) {
    return applyPrefsSnapshot(newest);
  }
  // Not a fresh device (so we don't auto-apply subscriptions), but the known .ath names are additive — restore them
  // anyway so the profile's linked-names list stays complete across devices.
  restoreKnownUsernamesFromSnapshot(newest);
  const seen = Math.max(prefsLastSyncedAt ?? 0, Number(newest.writtenAt ?? 0));
  if (seen > 0) setPrefsLastSyncedAt(seen);
  return false;
}

function publicAuthorLabel(authorWallet) {
  const wallet = rawWalletAddress(authorWallet) ?? String(authorWallet ?? '').trim();
  // Registry-VERIFIED channel username wins over everything: it is the author's own linked .ath, proven on-chain to
  // be owned by this wallet (owner == author). Read-only, synchronous — the verification ran async at profile-resolve
  // time (verifyChannelUsernameClaim) and only a proven name is ever written here, so this can never surface a
  // spoofed claim. Falls back to a locally-known channel name, then the short address.
  const verified = publicChannelProfileCache[channelProfileCacheKey(wallet)]?.verifiedUsername;
  if (verified) return canonicalUsernameDisplay(verified);
  const channelName = publicChannelRegistry.find((channel) => publicChannelMatchesAuthorWallet(channel, wallet))?.name;
  // Author is shown canonically — never with the ".ath" suffix (the registry name may still carry it for matching).
  return channelName ? canonicalUsernameDisplay(channelName) : shortAddress(wallet);
}

function ensurePublicChannelForAuthorWallet(authorWallet, options = {}) {
  const wallet = rawWalletAddress(authorWallet) ?? String(authorWallet ?? '').trim();
  if (!wallet) return publicChannelRegistry[0]?.id ?? 'platho.app';
  const existing = publicChannelRegistry.find((channel) => (
    publicChannelMatchesAuthorWallet(channel, wallet)
  ));
  if (existing) {
    if (options.activate && publicChannelSubscriptions?.activeChannelId !== existing.id) {
      publicChannelSubscriptions = {
        ...publicChannelSubscriptions,
        activeChannelId: existing.id,
      };
      writePublicChannelSubscriptions(publicChannelStorage(), publicChannelSubscriptions);
    }
    return existing.id;
  }

  const id = `wallet:${wallet}`;
  const isOwnChannel = plathoWallet?.address && sameWalletAddress(wallet, plathoWallet.address);
  const name = isOwnChannel ? 'you' : shortAddress(wallet);
  const channel = {
    id,
    name,
    avatar: publicChannelAvatar(name),
    subtitle: `${isOwnChannel ? 'your' : 'wallet'} public channel - ${shortAddress(wallet)}`,
    authorWallet: wallet,
  };
  customPublicChannels = normalizePublicChannelRegistry([
    ...customPublicChannels.filter((item) => item.id !== id),
    channel,
  ]);
  writeCustomPublicChannels();
  rebuildPublicChannelRegistry();

  const subscribedById = new Map((publicChannelSubscriptions?.channels ?? []).map((item) => [item.id, item]));
  // Only an EXPLICIT user action (options.activate) subscribes. A channel merely DISCOVERED while syncing
  // (a post author, or the author of a comment on a subscribed post) is registered for display but left
  // unsubscribed — otherwise a fresh user's feed fills with everyone, the original public-feed bug.
  subscribedById.set(id, { id, subscribed: subscribedById.get(id)?.subscribed === true || options.activate === true });
  publicChannelSubscriptions = {
    version: publicChannelSubscriptions?.version ?? 1,
    activeChannelId: options.activate ? id : (publicChannelSubscriptions?.activeChannelId ?? id),
    channels: publicChannelRegistry.map((item) => ({
      id: item.id,
      subscribed: subscribedById.get(item.id)?.subscribed === true,
    })),
  };
  writePublicChannelSubscriptions(publicChannelStorage(), publicChannelSubscriptions);
  rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
  return id;
}

// Assemble walked public entry parts (posts OR comments) into display items: groups multipart streams, joins
// image/document bytes in part order, decodes document blocks (forward-compat tolerant), and drops incomplete
// multipart groups. Hoisted to module scope so both the feed sync and the on-demand comment loader use the
// exact same assembly (multipart comments must reassemble identically in both paths).
function assemblePublicParts(items) {
  const groups = new Map();
  for (const item of items) {
    const count = Number(item.partCount ?? 1);
    const index = Number(item.partIndex ?? 0);
    const key = count <= 1
      ? `single:${item.channelId}:${item.entryId}`
      : `${item.channelId}:${item.streamId}:${item.parentEntryId ?? ''}:${item.parentHash ?? ''}`;
    const group = groups.get(key) ?? { expected: count, parts: [] };
    group.expected = Math.max(group.expected, count);
    group.parts.push({ ...item, partIndex: index, partCount: count });
    groups.set(key, group);
  }
  const out = [];
  for (const group of groups.values()) {
    const ordered = group.parts
      .slice()
      .sort((a, b) => Number(a.partIndex ?? 0) - Number(b.partIndex ?? 0));
    const unique = new Set(ordered.map((item) => Number(item.partIndex ?? 0)));
    if (group.expected > 1 && unique.size !== group.expected) continue;
    const first = ordered[0];
    const imageParts = ordered.filter((item) => item.imageBytes?.length);
    const imageBytes = imageParts.length > 0
      ? new Uint8Array(imageParts.reduce((sum, item) => sum + item.imageBytes.length, 0))
      : null;
    if (imageBytes) {
      let offset = 0;
      for (const item of imageParts) {
        imageBytes.set(item.imageBytes, offset);
        offset += item.imageBytes.length;
      }
    }
    const documentParts = ordered.filter((item) => item.documentBytes?.length);
    const documentBytes = documentParts.length > 0
      ? new Uint8Array(documentParts.reduce((sum, item) => sum + item.documentBytes.length, 0))
      : null;
    if (documentBytes) {
      let offset = 0;
      for (const item of documentParts) {
        documentBytes.set(item.documentBytes, offset);
        offset += item.documentBytes.length;
      }
    }
    const documentBlocks = documentBytes
      // Public decode is forward-compat tolerant: a post carrying a new block type (e.g. the author-.ath
      // tag added in a later phase) still decodes here instead of throwing. Private decode stays strict.
      ? displayBlocksFromDocumentBlocks(decodeMessageDocumentBlocks(documentBytes, { tolerateUnknownBlocks: true }))
      : [];
    const readEntryId = ordered.reduce((max, item) => {
      const value = publicEntryIdBigInt(item.entryId) ?? -1n;
      return value > max ? value : max;
    }, -1n);
    const item = {
      ...first,
      text: documentBlocks.length > 0
        ? messagePreviewFromBlocks(documentBlocks)
        : ordered.filter((part) => !part.imageBytes?.length && !part.documentBytes?.length).map((part) => part.text ?? '').join(''),
      blocks: documentBlocks.length > 0 ? documentBlocks : undefined,
      readEntryId: readEntryId >= 0n ? readEntryId.toString() : first.entryId,
      partCount: group.expected,
      avatarImageUrl: null,
    };
    if (imageBytes && documentBlocks.length === 0) {
      item.imageUrl = bytesToImageDataUrl(imageBytes, 'image/webp');
      item.imageBytes = undefined;
    }
    out.push(item);
  }
  return out;
}

// --- Channel profile cache (description + tags), keyed by the raw author wallet ---
// Cold reads walk this many of an author's newest posts looking for a PROFILE block. Bounded on purpose (the owner
// wants "recent, no deep scans"): a channel that publishes more than this many posts AFTER editing its description
// sinks the profile out of the cold-read window until re-published (subscribed readers still get it warm from the
// wider feed walk). A deeper structural fix (a profile pointer on the on-chain author index) needs a contract change.
const PUBLIC_CHANNEL_PROFILE_WALK_LIMIT = 24;
// A cached "no profile found" (absent) result is re-checked after this long, so a channel that ADDS a description
// later resurfaces (in the popover and in discovery) instead of being permanently cached as description-less. A
// cached profile WITH content stays cache-first (descriptions change rarely; the feed walk refreshes subscribed ones).
const PUBLIC_CHANNEL_PROFILE_ABSENT_TTL_SEC = 15 * 60;

function channelProfileCacheKey(authorWallet) {
  return rawWalletAddress(authorWallet) ?? (authorWallet ? String(authorWallet) : '');
}

function cachedChannelProfile(authorWallet) {
  const key = channelProfileCacheKey(authorWallet);
  if (!key) return null;
  // A not-yet-confirmed optimistic edit (overlay) wins over the durable copy for immediate display.
  return pendingChannelProfileOverlay.get(key) ?? publicChannelProfileCache[key] ?? null;
}

function persistChannelProfileCache() {
  try { writePublicChannelProfileCache(publicChannelStorage(), publicChannelProfileCache); } catch { /* advisory */ }
}

// Latest-wins ordering: newer createdAt beats older, ties broken by the higher entryId.
function compareProfileRecency(a, b) {
  const ac = Number(a?.createdAtSec ?? 0) || 0;
  const bc = Number(b?.createdAtSec ?? 0) || 0;
  if (ac !== bc) return ac - bc;
  let ae = 0n; let be = 0n;
  try { ae = BigInt(a?.entryId ?? 0); } catch { ae = 0n; }
  try { be = BigInt(b?.entryId ?? 0); } catch { be = 0n; }
  return ae > be ? 1 : (ae < be ? -1 : 0);
}

function nowSec() { return Math.floor(Date.now() / 1000); }

// Record a profile found on-chain, keeping only the newest (latest-wins). A cold fetch that finds nothing records
// an empty profile (fetchedAt set, entryId '') so the button/discovery stop re-walking on every open.
function setChannelProfileFromWalk(authorWallet, profileBlock, entryId, createdAtSec) {
  const key = channelProfileCacheKey(authorWallet);
  if (!key) return;
  const incoming = normalizeChannelProfile({
    description: profileBlock?.description ?? '',
    tags: profileBlock?.tags ?? [],
    ownerUsername: profileBlock?.ownerUsername ?? '',
    entryId: entryId === null || entryId === undefined ? '' : String(entryId),
    createdAtSec: Number(createdAtSec) || 0,
    fetchedAt: nowSec(),
  });
  const prev = publicChannelProfileCache[key] ?? null;
  // Latest-wins by created_at (ties by entryId). Guard on recency ALONE (not entryId) so a just-published
  // optimistic edit (entryId '', createdAt now) can't be clobbered by a STALE older profile the walk surfaces
  // during indexer lag; a genuinely-newer edit (higher created_at, e.g. from another device) still wins.
  if (prev && compareProfileRecency(prev, incoming) > 0) return;
  // Carry the last-known VERIFIED name across the profile update so a re-walk doesn't blank the label until the
  // async re-verification below lands; if the claim changed (user re-linked a different .ath), re-verification
  // corrects it. Only ever set from a registry proof — never from the raw claim.
  if (prev?.verifiedUsername && prev.ownerUsername === incoming.ownerUsername) {
    incoming.verifiedUsername = prev.verifiedUsername;
  }
  publicChannelProfileCache = { ...publicChannelProfileCache, [key]: incoming };
  persistChannelProfileCache();
  verifyChannelUsernameClaim(authorWallet, incoming.ownerUsername);
}

// Verify a channel's self-declared owner-username CLAIM against the on-chain registry and cache the VERIFIED display
// name (never the raw claim). Reuses the exact pipeline private chats use for peer usernames
// (verifiedPlathoUsernameIdentityForWallet → verifiedPlathoUsernameOwnerCache), so a wallet that owns several .ath
// names only ever wears the one it LINKED and actually owns. Serialized via queueUsernameHygiene so a discovery
// walk over many authors never fires parallel chain reads (the iOS single-serial-read rule).
function verifyChannelUsernameClaim(authorWallet, claimedName) {
  const key = channelProfileCacheKey(authorWallet);
  if (!key) return;
  // plathoUsernameIdentity is TOLERANT — returns null for an empty/malformed claim (unlike normalizeUsernameInput,
  // which THROWS). The claim is attacker-controlled on-chain data ('xx', 'a!b', emoji), so parse it defensively:
  // a throw here (from any candidate) must NOT unwind the discovery walk / feed sync that called us.
  let identity = null;
  try { identity = plathoUsernameIdentity(claimedName); } catch { identity = null; }
  const rawWallet = rawWalletAddress(authorWallet);
  if (!identity || !rawWallet) { applyVerifiedChannelUsername(key, ''); return; }
  queueUsernameHygiene(async () => {
    let verified = null;
    try { verified = await verifiedPlathoUsernameIdentityForWallet(identity.value, rawWallet); } catch { verified = null; }
    if (verified) {
      applyVerifiedChannelUsername(key, canonicalUsernameDisplay(verified.label ?? verified.value));
      return;
    }
    // The helper returns null for BOTH a DEFINITIVE mismatch (it CACHES null) and a TRANSIENT RPC error (no cache).
    // Only strip a name we can PROVE is not owned — a cached-null entry. On a transient/uncached miss keep the
    // last-known-good verified name (the anti-strip rule the private path enforces by branching on the thrown error).
    const cached = verifiedPlathoUsernameOwnerCache.get(`${identity.value}:${rawWallet}`);
    if (cached && cached.value === null) applyVerifiedChannelUsername(key, '');
  });
}

function applyVerifiedChannelUsername(profileKey, verifiedUsername) {
  const prev = publicChannelProfileCache[profileKey];
  if (!prev) return;
  const next = verifiedUsername ?? '';
  if ((prev.verifiedUsername ?? '') === next) return;
  publicChannelProfileCache = { ...publicChannelProfileCache, [profileKey]: { ...prev, verifiedUsername: next } };
  persistChannelProfileCache();
  scheduleDiscoveryLabelRefresh();
}

// Coalesce the discovery re-render across a burst of per-author verifications (one walk verifies N channels).
let discoveryLabelRefreshScheduled = false;
function scheduleDiscoveryLabelRefresh() {
  if (discoveryLabelRefreshScheduled) return;
  discoveryLabelRefreshScheduled = true;
  queueMicrotask(() => {
    discoveryLabelRefreshScheduled = false;
    // buildDiscoveryCard reads publicAuthorLabel at render, so re-rendering picks up the now-warm verified name.
    // Feed post labels are baked at resolve time and refresh on the next sync (publicAuthorLabel reads the same cache).
    try { if (publicDiscoveryBody && publicDiscoveryBody.childElementCount > 0) renderPublicDiscovery({ loading: false }); } catch { /* cosmetic */ }
  });
}

function channelProfileHasContent(profile) {
  return Boolean(profile && (profile.description || (profile.tags && profile.tags.length > 0) || profile.entryId));
}

function markChannelProfileAbsent(authorWallet) {
  const key = channelProfileCacheKey(authorWallet);
  if (!key) return;
  if (pendingChannelProfileOverlay.has(key)) return; // an edit is publishing — don't record "absent" over it
  const prev = publicChannelProfileCache[key] ?? null;
  if (channelProfileHasContent(prev)) return; // real content is cached — never overwrite with "absent"
  publicChannelProfileCache = {
    ...publicChannelProfileCache,
    [key]: normalizeChannelProfile({ description: '', tags: [], entryId: '', createdAtSec: 0, fetchedAt: nowSec() }),
  };
  persistChannelProfileCache();
}

// Show a just-edited profile IMMEDIATELY (in-memory overlay), without persisting — a publish that never lands must
// not survive a reload as if it saved. The heal driver moves it to the durable cache on confirmation, or drops it.
function setChannelProfileOptimistic(authorWallet, profile, createdAtSec) {
  const key = channelProfileCacheKey(authorWallet);
  if (!key) return;
  pendingChannelProfileOverlay.set(key, normalizeChannelProfile({
    description: profile?.description ?? '',
    tags: normalizeProfileTags(profile?.tags),
    ownerUsername: profile?.ownerUsername ?? '',
    entryId: '',
    createdAtSec: Number(createdAtSec) || nowSec(),
    fetchedAt: nowSec(),
  }));
  // Verify your OWN just-published username so your own channel shows it immediately (the overlay isn't walked).
  verifyChannelUsernameClaim(authorWallet, profile?.ownerUsername);
}

// Commit a CONFIRMED profile to the durable cache (unconditional — we KNOW it just landed, so it wins over any prior
// entry regardless of the recency guard) and clear the optimistic overlay. Recording the real entryId here is what
// completes the latest-wins reconciliation the walk path can't (its recency guard keeps the fresher optimistic copy).
function finalizeChannelProfile(authorWallet, profile, entryId, createdAtSec) {
  const key = channelProfileCacheKey(authorWallet);
  if (!key) return;
  pendingChannelProfileOverlay.delete(key);
  const prevVerified = publicChannelProfileCache[key]?.verifiedUsername ?? '';
  const committed = normalizeChannelProfile({
    description: profile?.description ?? '',
    tags: normalizeProfileTags(profile?.tags),
    ownerUsername: profile?.ownerUsername ?? '',
    entryId: entryId === null || entryId === undefined ? '' : String(entryId),
    createdAtSec: Number(createdAtSec) || nowSec(),
    fetchedAt: nowSec(),
  });
  // Carry a matching prior verification forward so the label doesn't blink; re-verify to catch a re-linked name.
  if (prevVerified && (publicChannelProfileCache[key]?.ownerUsername ?? '') === committed.ownerUsername) {
    committed.verifiedUsername = prevVerified;
  }
  publicChannelProfileCache = { ...publicChannelProfileCache, [key]: committed };
  persistChannelProfileCache();
  verifyChannelUsernameClaim(authorWallet, profile?.ownerUsername);
}

function publishStateEntryId(publishState) {
  return publishState?.parts?.find((part) => part?.entryId !== undefined && part?.entryId !== null)?.entryId ?? null;
}

// Background heal for a profile publish (the send-path parity fix): a profile is channel metadata with no feed
// record, so the feed confirm/resume driver never touches it. Without this, a SUBMITTED/PARTIAL profile whose
// external was dropped (toncenter ACKs 200 without delivering — the documented non-delivery hazard) would silently
// never land while the UI reported "saved". This re-broadcasts + confirms on the same cadence as the post driver,
// until CONFIRMED (→ commit to the durable cache) or the no-progress deadline (→ drop the optimistic overlay).
// Heal jobs keyed by author wallet. A newer edit REPLACES the in-flight job (its post has a higher entry id, so it
// wins the on-chain walk anyway) instead of being dropped — this closes the rapid-double-edit race where the first
// job would otherwise finalize the durable cache with the OLDER edit and discard the newer overlay.
const channelProfileHealJobs = new Map();

function scheduleChannelProfileHeal(key, delayMs) {
  const job = channelProfileHealJobs.get(key);
  if (!job || job.inFlight) return; // a running pass reschedules itself when it finishes — never stack timers
  if (job.timer) clearTimeout(job.timer);
  job.timer = setTimeout(() => {
    runChannelProfileHealPass(key).catch((error) => { channelProfileHealJobs.delete(key); console.error(error); });
  }, delayMs);
}

async function runChannelProfileHealPass(key) {
  const job = channelProfileHealJobs.get(key);
  if (!job || job.inFlight) return; // single-flight: never two concurrent passes for one key
  job.timer = null;
  job.inFlight = true;
  if (job.publishState.status === CAPSULEHUB_PUBLISH_STATUS_CONFIRMED) {
    channelProfileHealJobs.delete(key);
    finalizeChannelProfile(key, job.profile, publishStateEntryId(job.publishState), job.createdAtSec);
    return;
  }
  if (Date.now() - job.startedAt >= publishConfirmNoProgressDeadlineMs(job.publishState)) {
    channelProfileHealJobs.delete(key);
    console.warn('[platho] channel profile publish: no-progress terminal', { key });
    pendingChannelProfileOverlay.delete(key); // drop the optimistic overlay — a never-landed publish is not masked
    return;
  }
  // Don't fight the serial pump while a chain sync pass is in flight (same rule as the post driver).
  if (privateChainSyncPromise) { job.inFlight = false; scheduleChannelProfileHeal(key, 2_500); return; }
  let passError = null;
  try {
    await retryUnconfirmedVaultPublishBroadcasts(job.publishState, {
      deadlineMs: PRIVATE_PUBLISH_BROADCAST_RETRY_DEADLINE_MS,
      readTimeoutMs: PRIVATE_PUBLISH_BROADCAST_RETRY_READ_TIMEOUT_MS,
      sendTimeoutMs: PRIVATE_PUBLISH_BROADCAST_RETRY_SEND_TIMEOUT_MS,
      queueTimeoutMs: PRIVATE_PUBLISH_BROADCAST_RETRY_QUEUE_TIMEOUT_MS,
    });
    await confirmCapsuleHubPublishEntries(job.publishState, {
      deadlineMs: PRIVATE_PUBLISH_CONFIRM_RECOVERY_DEADLINE_MS,
      requestTimeoutMs: PRIVATE_PUBLISH_CONFIRM_RECOVERY_REQUEST_TIMEOUT_MS,
      queueTimeoutMs: PRIVATE_PUBLISH_CONFIRM_RECOVERY_QUEUE_TIMEOUT_MS,
      owner: resolvePublishOwner(job.publishState),
    });
  } catch (error) {
    passError = error;
    noteTonRpcRateLimit(error);
  }
  // Re-read: a newer edit may have replaced the job while we awaited an RPC.
  const current = channelProfileHealJobs.get(key);
  if (!current) return;
  if (current.publishState.status === CAPSULEHUB_PUBLISH_STATUS_CONFIRMED) {
    channelProfileHealJobs.delete(key);
    finalizeChannelProfile(key, current.profile, publishStateEntryId(current.publishState), current.createdAtSec);
    return;
  }
  current.inFlight = false;
  scheduleChannelProfileHeal(key, privatePublishConfirmDelayMs({ publishState: current.publishState, createdAtMs: current.startedAt }, passError));
}

function healChannelProfilePublish(authorWallet, publishState, profile, createdAtSec) {
  const key = channelProfileCacheKey(authorWallet);
  if (!key || !publishState) return;
  const existing = channelProfileHealJobs.get(key);
  if (existing) {
    // Supersede the in-flight/pending job IN PLACE (same object) so a running pass picks up the newer edit on its
    // next check; scheduleChannelProfileHeal is a no-op while a pass is in flight (it reschedules itself).
    existing.publishState = publishState;
    existing.profile = profile;
    existing.createdAtSec = Number(createdAtSec) || nowSec();
    existing.startedAt = Date.now();
    scheduleChannelProfileHeal(key, PRIVATE_PUBLISH_CONFIRM_SETTLE_MS);
    return;
  }
  channelProfileHealJobs.set(key, { publishState, profile, createdAtSec: Number(createdAtSec) || nowSec(), startedAt: Date.now(), timer: null, inFlight: false });
  scheduleChannelProfileHeal(key, PRIVATE_PUBLISH_CONFIRM_SETTLE_MS);
}

// Decode a resolved single-part document body and, if it carries a PROFILE block, return it plus whether the
// document is profile-ONLY (no text/image) — that's the signal to divert it from the visible feed.
function readProfileDocument(documentBytes) {
  if (!documentBytes) return null;
  let blocks;
  try { blocks = decodeMessageDocumentBlocks(documentBytes, { tolerateUnknownBlocks: true }); } catch { return null; }
  const profile = blocks.find((block) => block?.type === 'profile');
  if (!profile) return null;
  return {
    // Carry the self-declared owner-username CLAIM through — it is the SOLE funnel for every on-chain read path
    // (author-walk, discovery-chain, feed divert), so dropping it here would make the verified-username feature dead
    // for every channel a reader resolves from chain. It is still only DISPLAYED after registry verification.
    profileBlock: {
      description: String(profile.description ?? ''),
      tags: Array.isArray(profile.tags) ? profile.tags : [],
      ownerUsername: typeof profile.ownerUsername === 'string' ? profile.ownerUsername : '',
    },
    isProfileOnly: blocks.length > 0 && blocks.every((block) => block?.type === 'profile'),
  };
}

// clean-11 capability gate: true only when the deployed genesis exposes the on-chain profile-pointer (config flag,
// flipped at the clean-11 cutover in lockstep with the new addresses). Gates the is_profile publish bit (clean-10
// Vault/Hub reject reserved != 0) and the global-profile-chain discovery/resolve fast-paths. false on clean-10.
function profilePointerEnabled() {
  return appConfig.capsuleHub?.profilePointer === true;
}

// Cold read of a channel's current profile: walk ONLY this author's on-chain post chain newest-first (no global
// scan), bounded by maxScan, and return the first (newest) PROFILE block. Cache-first: a warm cache (populated by
// the feed walk for subscribed channels) returns instantly with zero reads. Bounded body reads on a cold miss.
async function resolveChannelProfile(authorWallet, options = {}) {
  const maxScan = Number.isFinite(options.maxScan) ? Math.max(1, Math.floor(options.maxScan)) : PUBLIC_CHANNEL_PROFILE_WALK_LIMIT;
  const key = channelProfileCacheKey(authorWallet);
  if (!key) return null;
  if (options.force !== true) {
    const cached = cachedChannelProfile(key);
    if (cached && cached.fetchedAt) {
      // Cache-first for a profile WITH content; an ABSENT result is only trusted until its TTL, then re-walked so a
      // newly-added description can surface.
      if (channelProfileHasContent(cached)) return cached;
      if ((Date.now() / 1000 - cached.fetchedAt) < PUBLIC_CHANNEL_PROFILE_ABSENT_TTL_SEC) return cached;
    }
  }
  const resolved = await resolveCapsuleHubProvider();
  if (!resolved) return cachedChannelProfile(key);
  const { provider, address } = resolved;
  const readOptions = criticalCapsuleHubReadOptions(address);
  let authorIndex;
  try {
    const authorKeyId = await computePublicAuthorKeyId(authorWallet);
    // clean-11 fast-path: the per-author profile index points DIRECTLY at this channel's latest profile post (O(1),
    // no chain walk). Dangling-tolerant — if the pointer's entry was evicted or carries no profile block, fall
    // through to the clean-10 author-walk. Its own try so a fast-path miss/error never aborts the fallback.
    if (profilePointerEnabled()) {
      try {
        const profileIndex = await provider.getPublicProfileIndex(authorKeyId, readOptions);
        const profileLink = BigInt(profileIndex?.latest_entry_link ?? 0n);
        if (profileIndex?.exists === true && profileLink > 0n) {
          const profileEntry = await provider.getPublicEntry(profileLink - 1n, readOptions);
          if (profileEntry.exists === true) {
            let payload = null;
            try { payload = await resolvePublicEntryPayload(provider, profileEntry, address, { maxBytes: PUBLIC_POST_BODY_MAX_BYTES }); } catch { payload = null; }
            const profileDoc = payload ? readProfileDocument(payload.documentBytes ?? payload.document_bytes) : null;
            if (profileDoc?.profileBlock) {
              const createdAtSec = Number(payload?.createdAtSec ?? payload?.created_at_sec ?? 0) || 0;
              setChannelProfileFromWalk(authorWallet, profileDoc.profileBlock, profileLink - 1n, createdAtSec);
              return cachedChannelProfile(key);
            }
          }
        }
      } catch (fastPathError) { noteTonRpcRateLimit(fastPathError); }
    }
    authorIndex = await provider.getPublicAuthorIndex(authorKeyId, readOptions);
  } catch (error) {
    noteTonRpcRateLimit(error);
    return cachedChannelProfile(key);
  }
  if (authorIndex.exists !== true) { markChannelProfileAbsent(key); return cachedChannelProfile(key); }
  let link = BigInt(authorIndex.latest_entry_link ?? 0n);
  for (let scanned = 0; link > 0n && scanned < maxScan; scanned += 1) {
    const entryId = link - 1n;
    let entry;
    try { entry = await provider.getPublicEntry(entryId, readOptions); } catch (error) { noteTonRpcRateLimit(error); break; }
    if (entry.exists !== true) break;
    const prev = BigInt(entry.prev_link ?? 0n);
    // A profile is always single-part; skip multipart entries WITHOUT a body read (header-only check).
    const headerInfo = readPublicPartHeaderInfo(entry?.header_boc ?? entry?.headerBoc);
    if (!headerInfo || headerInfo.partCount <= 1) {
      let payload = null;
      try { payload = await resolvePublicEntryPayload(provider, entry, address, { maxBytes: PUBLIC_POST_BODY_MAX_BYTES }); } catch { payload = null; }
      const profileDoc = payload ? readProfileDocument(payload.documentBytes ?? payload.document_bytes) : null;
      if (profileDoc?.profileBlock) {
        const createdAtSec = Number(payload?.createdAtSec ?? payload?.created_at_sec ?? 0) || 0;
        setChannelProfileFromWalk(authorWallet, profileDoc.profileBlock, entryId, createdAtSec);
        return cachedChannelProfile(key);
      }
    }
    if (prev === link) break; // defensive: never spin on a self-referential link
    link = prev;
  }
  markChannelProfileAbsent(key);
  return cachedChannelProfile(key);
}

// --- Newcomer discovery (Part B): suggest channels WITH a description, sampled from the head of the global log ---
// Scale-safe by construction: cost = O(WINDOW + CANDIDATES·MAXSCAN), all FIXED constants — independent of the total
// channel count (100 or 100k cost the same). It never enumerates the corpus; it samples the newest WINDOW entries
// for distinct recent authors (entry views only, NO body reads), then resolves at most CANDIDATES profiles with a
// shallow per-author walk. Recency-scoped by design (the owner's "show what's found, no deep scans"): a channel
// that has been silent longer than the window, or whose profile sits deeper than MAXSCAN posts, won't surface.
const PUBLIC_DISCOVERY_WINDOW = 64;
const PUBLIC_DISCOVERY_MAX_CANDIDATES = 16;
const PUBLIC_DISCOVERY_PROFILE_MAXSCAN = 6;
const PUBLIC_DISCOVERY_CACHE_TTL_MS = 5 * 60 * 1000;

let publicDiscoveryCache = null; // { at, results: [{ authorWallet, description, tags, name }] }

// clean-11 COMPLETE discovery: walk the GLOBAL profile chain newest-first (get_public_profile_head -> follow each
// entry's profile_prev_link), surfacing EVERY described channel — not recency-scoped like the clean-10 window sample.
// Bounded by a distinct-author cap + a scan cap (edit-churn safety: repeated profile edits by a few authors inflate
// the chain, so we dedupe by author, latest wins). Strict-FIFO eviction means the first evicted node ends the live
// prefix (stop). Returns null on a head-read failure so the caller falls back to the clean-10 window scan.
async function discoverChannelsViaProfileChain(provider, address, readOptions, ownWallet, subscribedAuthors) {
  let head;
  try { head = BigInt((await provider.getPublicProfileHead(readOptions)) ?? 0n); }
  catch (error) { noteTonRpcRateLimit(error); return null; }
  if (head <= 0n) return [];
  const results = [];
  const seen = new Set();
  let link = head;
  for (let scanned = 0; link > 0n && scanned < PUBLIC_DISCOVERY_WINDOW && results.length < PUBLIC_DISCOVERY_MAX_CANDIDATES; scanned += 1) {
    const entryId = link - 1n;
    let entry;
    try { entry = await provider.getPublicEntry(entryId, readOptions); } catch (error) { noteTonRpcRateLimit(error); break; }
    if (entry.exists !== true) break; // strict-FIFO: first evicted node ends the live prefix
    const nextLink = BigInt(entry.profile_prev_link ?? 0n);
    const wallet = rawWalletAddress(entry.author_wallet);
    if (wallet && !seen.has(wallet)) {
      seen.add(wallet); // dedupe: a channel's older profile-edit nodes are ignored (latest wins, newest-first)
      const skip = (ownWallet && sameWalletAddress(wallet, ownWallet)) || subscribedAuthors.has(wallet);
      if (!skip) {
        let payload = null;
        try { payload = await resolvePublicEntryPayload(provider, entry, address, { maxBytes: PUBLIC_POST_BODY_MAX_BYTES }); } catch { payload = null; }
        const profileDoc = payload ? readProfileDocument(payload.documentBytes ?? payload.document_bytes) : null;
        if (profileDoc?.profileBlock) {
          const description = typeof profileDoc.profileBlock.description === 'string' ? profileDoc.profileBlock.description.trim() : '';
          const tags = (profileDoc.profileBlock.tags ?? []).filter(Boolean);
          if (description || tags.length > 0) {
            const createdAtSec = Number(payload?.createdAtSec ?? payload?.created_at_sec ?? 0) || 0;
            setChannelProfileFromWalk(wallet, profileDoc.profileBlock, entryId, createdAtSec); // warm the per-author cache
            results.push({ authorWallet: wallet, description, tags, name: publicAuthorLabel(wallet) });
          }
        }
      }
    }
    if (nextLink === link) break; // defensive: never spin on a self-referential link
    link = nextLink;
  }
  return results;
}

// clean-17 Discover: sweep the BEACON directory (public-lane ranks live buckets by entry_count, NOT lt) and adapt
// each announcement to the 4-field shape renderPublicDiscovery consumes. The beacon card body is the raw profile
// document (a single-part 'document' body), so it decodes header-free via readProfileDocument.
async function discoverChannelsFromBeacon() {
  const lane = directPublicLaneReader();
  if (!lane) return publicDiscoveryCache?.results ?? [];
  let catalog;
  try { catalog = await lane.sweepChannelCatalog({ topBuckets: 32 }); }
  catch (error) { console.warn('[public] beacon sweep failed', error); return publicDiscoveryCache?.results ?? []; }
  const ownWallet = rawWalletAddress(plathoWallet?.address);
  const subscribedAuthors = new Set(
    subscribedPublicChannels(publicChannelSubscriptions, publicChannelRegistry)
      .map((channel) => rawWalletAddress(channel.authorWallet))
      .filter(Boolean),
  );
  const results = [];
  const seen = new Set();
  for (const item of catalog) {
    const wallet = rawWalletAddress(item.channelWallet);
    if (!wallet || seen.has(wallet)) continue;
    if (ownWallet && sameWalletAddress(wallet, ownWallet)) continue;   // discovery is for finding NEW channels
    if (subscribedAuthors.has(wallet)) continue;
    let profileDoc = null;
    try { profileDoc = readProfileDocument(tonCell.readSnakeCellBytes(item.card, { maxBytes: PUBLIC_POST_BODY_MAX_BYTES })); }
    catch { continue; }                                               // a card that is not a profile document is skipped
    if (!profileDoc?.profileBlock) continue;
    const description = String(profileDoc.profileBlock.description ?? '').trim();
    const tags = (profileDoc.profileBlock.tags ?? []).filter(Boolean);
    if (!description && tags.length === 0) continue;                  // discovery suggests DESCRIBED channels
    seen.add(wallet);
    // Warm the profile cache (also queues .ath verification) so render-time publicAuthorLabel resolves the name.
    setChannelProfileFromWalk(wallet, profileDoc.profileBlock, null, Number(item.announcedAt ?? 0n));
    results.push({ authorWallet: wallet, description, tags, name: publicAuthorLabel(wallet) });
  }
  publicDiscoveryCache = { at: Date.now(), results };
  return results;
}

async function discoverChannels(options = {}) {
  if (options.force !== true && publicDiscoveryCache && (Date.now() - publicDiscoveryCache.at) < PUBLIC_DISCOVERY_CACHE_TTL_MS) {
    return publicDiscoveryCache.results;
  }
  if (publicLaneDirectPayEnabled()) return discoverChannelsFromBeacon();
  const resolved = await resolveCapsuleHubProvider();
  if (!resolved) return publicDiscoveryCache?.results ?? [];
  const { provider, address } = resolved;
  const readOptions = criticalCapsuleHubReadOptions(address);
  const ownWalletEarly = rawWalletAddress(plathoWallet?.address);
  const subscribedAuthorsEarly = new Set(
    subscribedPublicChannels(publicChannelSubscriptions, publicChannelRegistry)
      .map((channel) => rawWalletAddress(channel.authorWallet))
      .filter(Boolean),
  );
  // clean-11: prefer the COMPLETE global-profile-chain walk; fall through to the clean-10 recency window on failure.
  if (profilePointerEnabled()) {
    const chainResults = await discoverChannelsViaProfileChain(provider, address, readOptions, ownWalletEarly, subscribedAuthorsEarly);
    if (chainResults) { publicDiscoveryCache = { at: Date.now(), results: chainResults }; return chainResults; }
  }
  const state = await provider.getState(readOptions);
  const latestId = BigInt(state.public_latest_id ?? 0n);
  if (latestId <= 0n) { publicDiscoveryCache = { at: Date.now(), results: [] }; return []; }
  // Phase 1 — distinct recent authors from the head window (entry views only, no body reads). Skip own wallet and
  // channels already subscribed (discovery is for finding NEW channels).
  const ownWallet = rawWalletAddress(plathoWallet?.address);
  const subscribedAuthors = new Set(
    subscribedPublicChannels(publicChannelSubscriptions, publicChannelRegistry)
      .map((channel) => rawWalletAddress(channel.authorWallet))
      .filter(Boolean),
  );
  const seen = new Set();
  const candidates = [];
  for (let i = 0; i < PUBLIC_DISCOVERY_WINDOW && candidates.length < PUBLIC_DISCOVERY_MAX_CANDIDATES; i += 1) {
    const entryId = latestId - 1n - BigInt(i);
    if (entryId < 0n) break;
    let entry;
    try { entry = await provider.getPublicEntry(entryId, readOptions); } catch (error) { noteTonRpcRateLimit(error); break; }
    if (entry.exists !== true) continue;
    const wallet = rawWalletAddress(entry.author_wallet);
    if (!wallet || seen.has(wallet)) continue;
    seen.add(wallet);
    if (ownWallet && sameWalletAddress(wallet, ownWallet)) continue;
    if (subscribedAuthors.has(wallet)) continue;
    candidates.push(wallet);
  }
  // Phase 2 — resolve each candidate's profile (cache-first, shallow walk). Keep only channels that HAVE a
  // description or tags — discovery suggests DESCRIBED channels.
  const results = [];
  for (const wallet of candidates) {
    let profile = null;
    try { profile = await resolveChannelProfile(wallet, { maxScan: PUBLIC_DISCOVERY_PROFILE_MAXSCAN }); } catch { profile = cachedChannelProfile(wallet); }
    const description = typeof profile?.description === 'string' ? profile.description.trim() : '';
    const tags = (profile?.tags ?? []).filter(Boolean);
    if (!description && tags.length === 0) continue;
    // Verify the channel's declared username (queued/deduped) — a cache-first profile resolve skips the walk (and
    // thus setChannelProfileFromWalk's verify kick), so trigger it here too. The label refreshes on the next render.
    verifyChannelUsernameClaim(wallet, profile?.ownerUsername);
    results.push({ authorWallet: wallet, description, tags, name: publicAuthorLabel(wallet) });
  }
  publicDiscoveryCache = { at: Date.now(), results };
  return results;
}

// clean-17 read lane: a public-lane reader over the app's shared RPC pump. endpoint/apiKey are OMITTED on purpose —
// web/shard-rpc.resolveEndpoint derives the /accountStates and /messages leaves from globalThis.plathoTonRpcEndpoint
// (+ plathoToncenterApiKey), exactly as intro-transport does in production; passing a final URL here is what once
// made the messages reader query /accountStates and silently return null bodies. Built per sync (cheap) so it always
// picks up the current transport after a wallet/endpoint switch.
function directPublicLaneReader() {
  const transport = globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) return null;
  return createPublicLane({
    runGetMethod: (call) => transport.runGetMethod(call),
    now: () => Math.floor(Date.now() / 1000),
  });
}

// ── clean-17 INTRO receive lane (gated behind privateLane.directPay) ──────────────────────────────────────────
// Scans IntroShard for stealth first contacts addressed to this wallet, opens each through the reviewed handshake
// crypto (keyId binding + K_root confirm — NO chain resolver), and adopts the pairwise K_root into the conv key store.
// Lifecycle mirrors the app's other polling: armed on unlock + tab-visible, stopped on lock/teardown + tab-hidden
// (the scan-runner's own timer must not tick in a backgrounded tab — RUN-08).
// FIRST-PASS LIMITATION: the conv key store is IN-MEMORY, so a device reload loses K_roots (re-derived on the next
// INTRO from that peer). An encrypted persistent store is the fast-follow. [clean17-private-lane-plan]

// A messaging keyId as its canonical base64url string. openIntroHandshake surfaces senderKeyId as RAW 32 bytes;
// the conv key store and thread ids key on the base64url form, so convert once here.
function introKeyIdString(keyId) {
  if (typeof keyId === 'string') return keyId;
  return bytesToBase64(keyId).replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/, '');
}

// Decode the intro's first message (a composer document payload) into display blocks, tolerating unknown block kinds
// and never throwing — a first contact must still establish the conversation even if its first message will not parse.
function introFirstMessageBlocks(bytes) {
  try {
    const blocks = displayBlocksFromDocumentBlocks(decodeMessageDocumentBlocks(bytes, { tolerateUnknownBlocks: true }));
    return Array.isArray(blocks) && blocks.length > 0 ? blocks : null;
  } catch {
    return null;
  }
}

// onFirstContact: the K_root is already adopted by the handler; here we surface the conversation. A first contact is
// ANONYMOUS by design — INTRO carries no sender wallet, only the sender keyId + profile — so the thread is keyed on
// the sender keyId and labelled as such until a later CONV message (which does carry a wallet) can name it.
function handleIntroFirstContact(opened) {
  const senderKeyId = introKeyIdString(opened.senderKeyId);
  const created = createInboundPeerThread({ senderKeyId, keyId: senderKeyId, label: null });
  let thread = threads.find((item) => item.id === created.id);
  if (!thread) { thread = created; threads.push(thread); }
  // The clean bridge from INTRO-receive to CONV-send: stash the peer's messaging keyId (base64url) on the thread so a
  // CONV reply can look up this conversation's adopted K_root in convKeyStore by (selfKeyId, peerKeyId). The thread id
  // is a normalised/anonymised peer id (a lossy round-trip), so the raw keyId is kept here explicitly. [CONV-send]
  thread.convPeerKeyId = senderKeyId;
  scheduleRecoveryBackup(conversationId(localRecipientKeyPair.keyId, senderKeyId));   // adopted a new K_root — back its slot up
  const bytes = opened.firstMessageBytes;
  if (bytes && bytes.length > 0) {
    const blocks = introFirstMessageBlocks(bytes);
    const message = { type: 'in', text: blocks ? messagePreviewFromBlocks(blocks) : '', meta: 'received', blocks: blocks ?? undefined };
    insertThreadMessage(thread, message);
    refreshThreadAfterMessageChange(thread);
    markIncomingThreadMessage(thread);
  }
  renderThreads();
}

// Build + start the scan (idempotent). Safe to call on unlock and on every return-to-visible.
async function armIntroReceiveLane() {
  if (!privateLaneDirectPayEnabled()) return;
  if (introReceiveLane || !localIdentity || !localRecipientKeyPair) return;
  const transport = globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) return;
  if (!convKeyStore) convKeyStore = createMemoryConvKeyStore();
  if (!introReplayGuard) introReplayGuard = createMemoryReplayStore();
  const onIntro = createIntroReceiveHandler({
    recipientKeyPair: localRecipientKeyPair,
    convKeyStore,
    introReplayGuard,
    onFirstContact: handleIntroFirstContact,
  });
  try {
    introReceiveLane = await createIntroLane({
      scanSecretKey: localIdentity.scanSecretKey,
      runGetMethod: (call) => transport.runGetMethod(call),
      onIntro,
      onError: (error) => { if (!noteTonRpcRateLimit(error)) console.warn('[intro] scan error', error); },
    });
    introReceiveLane.start();
  } catch (error) {
    introReceiveLane = null;
    console.warn('[intro] lane arm failed', error);
  }
}

// Stop the scan (idempotent). Called on lock/teardown and on tab-hidden.
function stopIntroReceiveLane() {
  if (!introReceiveLane) return;
  try { introReceiveLane.stop(); } catch { /* stop is best-effort/idempotent */ }
  introReceiveLane = null;
}

// 0x + 64-hex representation hash of a body cell — the shard model's stand-in for CapsuleHub's stored body_hash, so a
// shard post satisfies publicFeedPostHasChainAnchor (which the feed cache/merge/render all gate on). Unique per body.
async function publicShardBodyHashHex(cell) {
  const { hash } = await tonCell.computeCellHashAndDepth(cell);
  return `0x${tonCell.bytesToHex(hash)}`;
}

// clean-17 feed sync (gated): for each feed-source channel, read its posts from the author's CHANNEL PublicShard and
// merge into publicChannelFeedCache through the SAME assemble/upsert/local-pending seam the CapsuleHub sync uses.
// Comments are NOT walked here — they load on demand (loadPublicPostComments), same as the CapsuleHub path since the
// scalability fix. A channel whose read fails keeps its cached posts (append-merge, never wipe to placeholder).
async function syncPublicChannelFromShards() {
  const lane = directPublicLaneReader();
  if (!lane) return false;
  const feedChannels = feedSourcePublicChannels();
  const updatedAt = new Date().toISOString();
  const nextFeedCache = { ...publicChannelFeedCache };
  const touched = [];
  for (const channel of feedChannels) {
    if (!channel.authorWallet) continue;
    let shardPosts;
    try {
      shardPosts = await lane.readChannelPosts(channel.authorWallet);
    } catch (error) {
      console.warn('[public] shard channel read failed', channel.id, error);
      continue;
    }
    const postParts = [];
    for (const sp of shardPosts) {
      let payload;
      try { payload = readPublicPostPayloadV2({ header: sp.header, body: sp.body }); } catch { continue; }
      const authorWallet = channel.authorWallet;
      const createdAtSec = Number(sp.created_at ?? 0n);
      // Channel PROFILE divert: a single-part document carrying only a profile block is channel metadata, not a
      // visible post — capture it and drop it, exactly like the CapsuleHub walk.
      if (payload.type === 'document' && Number(payload.partCount ?? 1) <= 1) {
        const profileDoc = readProfileDocument(payload.documentBytes ?? payload.document_bytes);
        if (profileDoc?.isProfileOnly) {
          setChannelProfileFromWalk(authorWallet, profileDoc.profileBlock, sp.entry_id, createdAtSec);
          continue;
        }
      }
      const bodyHashHex = await publicShardBodyHashHex(sp.body);
      // entry_id is 0-based PER shard account, so a channel's posts across its era/overflow shards COLLIDE on it
      // (both shards have entry 0, 1, …). assemblePublicParts groups single-part posts by `single:channelId:entryId`
      // and upsertPublicChainPosts dedups by entryId — a raw entry_id would merge two distinct posts into one
      // corrupted record. So the FEED identity (entryId) is made globally unique with the shard's coordinates, while
      // the RAW per-shard entry_id is kept as shardEntryId for the comment thread derivation (post_uid needs it).
      const shardEntryId = sp.entry_id.toString();
      const globalEntryId = `${sp.channelEpochTag}.${sp.channelShardSeq ?? 0}.${shardEntryId}`;
      postParts.push({
        id: `pshard-${channel.id}-${globalEntryId}`,
        entryId: globalEntryId,
        shardEntryId,
        channelId: channel.id,
        type: payload.type,
        text: payload.text ?? '',
        imageBytes: payload.imageBytes ?? payload.image_bytes,
        documentBytes: payload.documentBytes ?? payload.document_bytes,
        createdAt: createdAtSec > 0 ? new Date(createdAtSec * 1000).toISOString() : new Date().toISOString(),
        author: publicAuthorLabel(authorWallet),
        authorWallet,
        bodyHash: bodyHashHex,
        entryUid: bodyHashHex.slice(2),   // synthesized: unique per body, satisfies the chain anchor
        streamId: payload.stream_id,
        partIndex: payload.partIndex ?? 0,
        partCount: payload.partCount ?? 1,
        commentsAllowed: payload.commentsAllowed !== false,
        chainVerified: true,
        // The shard's channel epoch_tag + overflow seq — the comment reader/writer folds these into post_uid to
        // find the THREAD shard for this post's comments.
        channelEpochTag: sp.channelEpochTag != null ? String(sp.channelEpochTag) : undefined,
        channelShardSeq: sp.channelShardSeq ?? 0,
      });
    }
    const posts = assemblePublicParts(postParts);
    posts.reverse();
    const cachedFeed = publicChannelFeedCache?.[channel.id]?.feed ?? publicChannelFeedCache?.[channel.id];
    const existing = (cachedFeed?.posts ?? []).filter(publicFeedPostHasChainAnchor);
    const merged = upsertPublicChainPosts(existing, posts);
    const withPending = mergeLocalPendingPublicFeed(channel.id, merged);
    nextFeedCache[channel.id] = { feed: { version: 1, channelId: channel.id, updatedAt, posts: withPending }, syncedAt: updatedAt };
    touched.push(channel.id);
  }
  publicChannelFeedCache = nextFeedCache;
  globalThis.plathoLastPublicSync = { mode: 'shard', channels: touched, at: updatedAt };
  return true;
}

async function syncPublicChannelFromChain() {
  if (publicLaneDirectPayEnabled()) return syncPublicChannelFromShards();
  const resolved = await resolveCapsuleHubProvider();
  if (!resolved) return false;
  const { provider, address } = resolved;
  const readOptions = criticalCapsuleHubReadOptions(address);
  const state = await provider.getState(readOptions);
  const latestId = BigInt(state.public_latest_id ?? 0n);
  const latest = Number(latestId);
  // Eviction floor (Phase 3), derived FOR FREE from get_state (already read): clean-10 public eviction is strictly
  // bottom-FIFO and gapless (PruneCapsuleEntry was removed → no mid-chain deletes), and entryIds are 0-INDEXED with
  // public_latest_id the NEXT id (highest live id = latest - 1; total ever = latest). So the live id range is
  // [latest - live_count, latest - 1] and the oldest-live id is EXACTLY latest - live_count (= the contract's
  // public_oldest_live_id). Cached posts/comments with entryId STRICTLY BELOW this floor are evicted on-chain —
  // pruned from the cache in the merge below (no rotating re-walk, zero extra reads, scales to any subscription
  // count). live_count 0 → nothing live (floor = latest → every id 0..latest-1 pruned).
  const publicLiveCount = BigInt(state.public_live_count ?? 0n);
  const publicOldestLiveId = publicEvictionFloor(latestId, publicLiveCount);
  const configuredLimit = Number(appConfig.capsuleHub?.publicReadLimit ?? PUBLIC_CHAIN_READ_LIMIT);
  const readLimit = Number.isFinite(configuredLimit)
    ? Math.max(1, Math.floor(configuredLimit))
    : PUBLIC_CHAIN_READ_LIMIT;
  const syncWindow = readPublicSyncWindow();
  const minEntryId = syncWindow === 'long' ? 0 : Math.max(0, latest - readLimit);
  const retryEntryIds = publicBodyHistoryRetryEntryIds(address, latestId, BigInt(minEntryId));
  const retryEntryIdSet = new Set(retryEntryIds.map((id) => id.toString()));
  // Incremental fast-path (mirrors the private cursor's "head unchanged -> zero reads"): if no new public entry
  // has appeared globally since the last CLEAN walk in the SAME history window, and no body-gap retries are
  // pending, the cached feed is already current — skip the entire author/parent index walk + body re-resolution.
  // This is what stops re-reading every post and every comment every ~30s. lastSyncedPublicLatestId only advances
  // after a non-degraded walk (the commit-gate below), so a rate-limited cycle re-walks next time and never
  // strands a post that a rate limit made it miss behind a skipped head.
  if (lastSyncedPublicLatestId !== null
    && latestId === lastSyncedPublicLatestId
    && syncWindow === lastSyncedPublicSyncWindow
    && retryEntryIds.length === 0) {
    return true;
  }
  // Set when a transient read failure (rate limit) was swallowed mid-walk, so the walk produced a PARTIAL result.
  // A degraded walk must not advance the cursor (commit-gate) and must not be trusted to prune the cache.
  let walkDegraded = false;
  // Captured AFTER the fast-path: if an invalidation (follow / channel-view preview) lands while THIS walk is in
  // flight, its source list may predate the newly-interesting channel — the commit-gate below must then leave the
  // cursor null so the invalidation's own walk actually runs instead of fast-pathing out.
  const invalidationEpochAtStart = publicSyncInvalidationEpoch;
  // Per-subscribed-author walk (replaces the old global scan): fetch only posts by channels the user is
  // subscribed to, plus the comments on those posts, via the on-chain author/parent indexes. Cost scales with
  // the user's subscriptions, NOT the global feed size — the scalability fix. The walk caches each fetched
  // entry so the body-resolution loop below does not re-fetch it.
  const entryIdsToScan = [];
  const scanSet = new Set();
  const walkedEntries = new Map();
  const pushScanId = (id) => { const k = id.toString(); if (!scanSet.has(k)) { scanSet.add(k); entryIdsToScan.push(id); } };
  // Walk a backward-linked index chain (an author's posts, or a post's comments). Returns the walked entry ids
  // plus whether the cap truncated the walk (the chain still had older entries) — the honest-incomplete signal,
  // symmetric to the private walk's catch-up. The chain ends naturally at link==0 (entryLink == id+1, 0 = none);
  // a missing/evicted entry (exists!==true) terminates gracefully without counting it.
  const walkPublicChainIds = async (latestLink, max) => {
    const ids = [];
    let link = BigInt(latestLink ?? 0n);
    let truncated = false;
    // Header-only multipart tracking (v650): streamId/partIndex/partCount live at fixed header offsets, so the
    // walker can tell a window-split multipart POST apart without any ~32KB body read.
    const partStreams = new Map(); // streamId -> { partCount, seen:Set<partIndex> }
    const noteWalkedHeader = (entry) => {
      const info = readPublicPartHeaderInfo(entry?.header_boc ?? entry?.headerBoc);
      if (!info || info.partCount <= 1) return;
      const group = partStreams.get(info.streamId) ?? { partCount: info.partCount, seen: new Set() };
      group.partCount = Math.max(group.partCount, info.partCount);
      group.seen.add(info.partIndex);
      partStreams.set(info.streamId, group);
    };
    const hasSplitPartStream = () => {
      for (const group of partStreams.values()) {
        if (group.seen.size < group.partCount) return true;
      }
      return false;
    };
    const walkOne = async () => {
      const entryId = link - 1n;
      const entry = await provider.getPublicEntry(entryId, readOptions);
      walkedEntries.set(entryId.toString(), entry);
      if (entry.exists !== true) return false;
      noteWalkedHeader(entry);
      ids.push(entryId);
      pushScanId(entryId);
      const prev = BigInt(entry.prev_link ?? 0n);
      if (prev === link) return false; // defensive: never spin on a self-referential link
      link = prev;
      return true;
    };
    for (let n = 0; link > 0n; n += 1) {
      if (n >= max) { truncated = true; break; }
      if (!(await walkOne())) return { ids, truncated };
    }
    // Boundary-straddle extension (v650, the v649 private-walk rule applied to the feed's per-author walk): a
    // window cap landing in the MIDDLE of a multipart post left the group incomplete forever — assemblePublicParts
    // drops half groups, the ids never enter the cached set, and an unchanged author head never re-walks them.
    // Keep walking (bounded) until every split stream seen by THIS walk closes; the ids then resolve+assemble
    // normally in this same cycle.
    if (truncated && hasSplitPartStream()) {
      let extendedScans = 0;
      while (link > 0n && extendedScans < PUBLIC_CHAIN_STRADDLE_EXTENSION_SCAN_LIMIT && hasSplitPartStream()) {
        extendedScans += 1;
        if (!(await walkOne())) return { ids, truncated };
      }
    }
    return { ids, truncated };
  };
  // 'short' = newest readLimit per author (cheap default). 'long' = the full retained per-author history the UI
  // promises ("up to 1 year"), bounded by a generous safety cap. entry_count (kept exact by the contract's
  // tail-first FIFO eviction) is the false-positive-free truncation detector.
  const allTime = syncWindow === 'long';
  const authorWalkMax = allTime ? PUBLIC_CHAIN_LONG_READ_LIMIT : readLimit;
  const incompleteChannels = [];
  // Walk the FEED source (subscribed + own) so the user's own confirmed posts are fetched from chain, not just
  // the subscribed authors. Adds at most one author index (the user's own).
  const pendingAuthorHeadWrites = [];
  const pendingAuthorTruncatedWrites = [];
  // F1 (scale): pick this cycle's bounded read set. Author keys are a LOCAL cell-hash (computePublicAuthorKeyId, no
  // RPC), so compute them for every channel up front. ALWAYS read the own channel and any channel with no cached
  // head yet (a fresh subscription must be walked once); round-robin the rest at PUBLIC_AUTHOR_INDEX_BUDGET_PER_CYCLE
  // over a stable (id-sorted) order. A subscriber with <= budget readable channels reads them ALL every cycle
  // (behavior unchanged); only heavy subscribers get the rotation, so no small-account latency is added.
  const feedChannels = feedSourcePublicChannels();
  const ownChannelId = ownPublicChannel()?.id ?? null;
  const channelAuthorKeys = new Map();
  for (const channel of feedChannels) {
    if (!channel.authorWallet) continue;
    try { channelAuthorKeys.set(channel.id, await computePublicAuthorKeyId(channel.authorWallet)); } catch { /* unresolvable key -> treated as not-readable this cycle */ }
  }
  const readableChannels = feedChannels.filter((c) => channelAuthorKeys.has(c.id));
  // roundStartHead is captured at the START of a round (covered set empty). The commit-gate advances the global
  // fast-path cursor only TO this head, and only once every readable channel is covered -- so a channel skipped by
  // the budget can never let the gate advance past that channel's not-yet-re-read new posts.
  // Self-heal a wedged round: a wallet switch racing an in-flight walk can leave covered NON-empty while
  // roundStartHead is null (the switch cleared both, the stale walk then re-added covered keys). roundStartHead is
  // only ever set here (covered empty) and covered only cleared in the commit (roundStartHead non-null) — without
  // this reset the gate deadlocks and every cycle re-reads the full budget for the rest of the session.
  if (publicAuthorRoundStartHead === null && publicAuthorRoundCovered.size > 0) publicAuthorRoundCovered.clear();
  if (publicAuthorRoundCovered.size === 0) publicAuthorRoundStartHead = latestId;
  // Selection, HARD-capped at the per-cycle budget regardless of how many channels are headless -- so a cold-start /
  // account-switch / sustained-rate-limit cycle (where NO per-author head is cached yet) still cannot fan out to
  // O(subscriptions) reads and re-open the send/receive starvation F1 targets. Priority WITHIN the budget:
  //   (1) the own channel (own posts must confirm fast),
  //   (2) never-read (headless) channels, id-sorted -- so a fresh subscription / cold feed surfaces within a cycle
  //       or two instead of waiting a full rotation,
  //   (3) a stable round-robin over the already-headed channels for whatever budget remains.
  // The round gate guarantees no strand for a channel deferred to a later cycle (every channel is covered within
  // ceil(N/budget) cycles, and the global head advances only to roundStartHead on roundComplete).
  const idSorted = [...readableChannels].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  const isHeadless = (c) => !publicAuthorIndexHeads.has(channelAuthorKeys.get(c.id).toString());
  const readThisCycle = new Set();
  if (ownChannelId !== null && readableChannels.some((c) => c.id === ownChannelId)) readThisCycle.add(ownChannelId);
  // The channel-view preview channel is what the user is LOOKING AT right now — always read it this cycle. On a
  // cold head cache (reload/account switch) with more headless channels than the budget, the id-sort could
  // otherwise defer it for cycles and the open view would sit on a false "No posts yet".
  if (publicChannelPreviewChannelId !== null && readableChannels.some((c) => c.id === publicChannelPreviewChannelId)) {
    readThisCycle.add(publicChannelPreviewChannelId);
  }
  let budget = PUBLIC_AUTHOR_INDEX_BUDGET_PER_CYCLE - readThisCycle.size;
  for (const c of idSorted) {
    if (budget <= 0) break;
    // has() (not just own): the pre-seeded preview channel is ALREADY charged against the budget above — a no-op
    // re-add here would decrement the budget a second time and waste a read slot every cycle it is open.
    if (readThisCycle.has(c.id) || !isHeadless(c)) continue;
    readThisCycle.add(c.id);
    budget -= 1;
  }
  const withHeads = idSorted.filter((c) => !readThisCycle.has(c.id) && !isHeadless(c));
  if (withHeads.length > 0 && budget > 0) {
    if (publicAuthorRoundCursor >= withHeads.length) publicAuthorRoundCursor = 0;
    const take = Math.min(budget, withHeads.length);
    for (let i = 0; i < take; i += 1) readThisCycle.add(withHeads[(publicAuthorRoundCursor + i) % withHeads.length].id);
    publicAuthorRoundCursor = (publicAuthorRoundCursor + take) % withHeads.length;
  }
  for (const channel of feedChannels) {
    const channelAuthor = channel.authorWallet;
    if (!channelAuthor) continue;
    const authorKeyId = channelAuthorKeys.get(channel.id);
    if (authorKeyId === undefined) continue;
    const authorHeadKey = authorKeyId.toString();
    if (!readThisCycle.has(channel.id)) {
      // Skipped by the per-cycle budget: reuse this channel's cached posts (the append-merge below preserves them)
      // + its remembered truncation. No RPC. NOT added to publicAuthorRoundCovered, so the gate stays at
      // roundStartHead until a later cycle re-reads this channel (strand-safe).
      if (publicAuthorIndexTruncated.get(authorHeadKey) === true) incompleteChannels.push(channel.id);
      continue;
    }
    let authorIndex;
    try {
      authorIndex = await provider.getPublicAuthorIndex(authorKeyId, readOptions);
    } catch (error) {
      // A transient rate-limit degrades the whole cycle (gate held, retried next cycle). A NON-transient read error
      // for one channel marks it covered so a permanent single-channel failure cannot wedge the round gate forever
      // -- it degrades to the pre-F1 behavior (that channel is skipped, the rest of the feed still advances).
      if (noteTonRpcRateLimit(error)) walkDegraded = true;
      else publicAuthorRoundCovered.add(authorHeadKey);
      console.warn('Skipping public author index read', channel.id, error);
      continue;
    }
    // A successful read (even an empty/no-posts index) marks this channel covered for the current round.
    publicAuthorRoundCovered.add(authorHeadKey);
    if (authorIndex.exists !== true) continue;
    const authorHead = String(authorIndex.latest_entry_link ?? 0n);
    const cachedPostIds = cachedChainPostEntryIds(channel.id);
    // Per-author POST cursor: an unchanged author-index head means no new posts — reuse the cached post ids
    // without re-reading every post body. A changed head re-walks the window and unions with the cached ids.
    let postIds;
    let postsTruncated = false;
    if (publicAuthorIndexHeads.get(authorHeadKey) === authorHead) {
      postIds = cachedPostIds;
      postsTruncated = publicAuthorIndexTruncated.get(authorHeadKey) === true; // remembered from the walk that built this head
    } else {
      const walked = await walkPublicChainIds(authorIndex.latest_entry_link, authorWalkMax);
      postsTruncated = walked.truncated;
      const postIdSet = new Map();
      for (const id of walked.ids) postIdSet.set(id.toString(), id);
      for (const id of cachedPostIds) if (!postIdSet.has(id.toString())) postIdSet.set(id.toString(), id);
      postIds = [...postIdSet.values()];
      pendingAuthorHeadWrites.push([authorHeadKey, authorHead]);
      pendingAuthorTruncatedWrites.push([authorHeadKey, walked.truncated]);
    }
    // Comments are no longer walked during the feed sync — they load on demand on the post detail screen
    // (loadPublicPostComments). The feed resolves posts only now: no per-post parent-index reads and no comment
    // body resolution for every subscribed channel on every cycle (the scalability fix the owner asked for).
    // Honest incomplete = the author's chain was TRUNCATED by the read window (more retained than we could walk).
    // Do NOT compare postIds.length against entry_count: entry_count counts EVERY author entry — INCLUDING the
    // profile-pointer entry (walked, then dropped as a profile not a post) and comment entries — so `posts <
    // entry_count` was true forever for any channel that ever set a profile or got a comment (the '[public] older
    // posts available' console spam). Truncation is the false-positive-free signal, remembered across cached cycles.
    if (postsTruncated) {
      incompleteChannels.push(channel.id);
    }
  }
  for (const id of retryEntryIds) pushScanId(id);
  const cutoffMs = publicSyncCutoffMs();
  const postParts = [];
  const commentParts = [];
  const avatarParts = [];
  const unavailableEntries = [];
  let scanned = 0;
  for (const entryIdValue of entryIdsToScan) {
    const retryOnly = retryEntryIdSet.has(entryIdValue.toString());
    scanned += 1;
    const entry = walkedEntries.get(entryIdValue.toString()) ?? await provider.getPublicEntry(entryIdValue, readOptions);
    if (entry.exists !== true) {
      if (retryOnly) clearPublicBodyHistoryUnavailable(address, entryIdValue);
      continue;
    }
    let payload = null;
    try {
      payload = await resolvePublicEntryPayload(provider, entry, address, { maxBytes: PUBLIC_POST_BODY_MAX_BYTES });
    } catch (error) {
      if (isBodyHistoryUnavailableError(error)) {
        rememberPublicBodyHistoryUnavailable(address, entry, entryIdValue);
        unavailableEntries.push({
          entryId: String(entry.entry_id ?? entryIdValue),
          bodyHash: entryBodyHashHex(entry),
        });
        // An in-window post/comment that failed to materialize must NOT let the commit-gate advance this author's
        // cursor: Phase 2 would then skip re-walking it (postIds = cached, and the body-gap retry set excludes
        // in-window ids), so the gap would never self-heal. Marking the walk degraded keeps the cursor put so the
        // next cycle re-attempts — restoring the pre-Phase-2 unconditional-re-walk self-heal. (Out-of-window
        // retryOnly ids are < minEntryId, so they keep self-healing via the retry set without degrading the walk.)
        if (entryIdValue >= BigInt(minEntryId)) walkDegraded = true;
        continue;
      }
      if (retryOnly) clearPublicBodyHistoryUnavailable(address, entryIdValue);
      if (noteTonRpcRateLimit(error) || entryIdValue >= BigInt(minEntryId)) walkDegraded = true;
      console.warn('Skipping unreadable public CapsuleHub entry', entry.entry_id?.toString?.() ?? entryIdValue.toString(), error);
      continue;
    }
    if (!payload) {
      if (retryOnly) clearPublicBodyHistoryUnavailable(address, entryIdValue);
      if (entryIdValue >= BigInt(minEntryId)) walkDegraded = true;
      continue;
    }
    clearPublicBodyHistoryUnavailable(address, entryIdValue);
    const createdAtSec = Number(payload.createdAtSec ?? payload.created_at_sec ?? 0);
    const createdAt = createdAtSec > 0
      ? new Date(createdAtSec * 1000).toISOString()
      : new Date().toISOString();
    const createdMs = new Date(createdAt).getTime();
    if (!retryOnly && cutoffMs !== null && createdAtSec > 0 && !Number.isNaN(createdMs) && createdMs < cutoffMs) continue;
    const authorWallet = rawWalletAddress(payload.authorWallet ?? entry.author_wallet) ?? String(payload.authorWallet ?? entry.author_wallet ?? '');
    // Channel PROFILE divert (v-profile): a single-part document post carrying ONLY a profile block is channel
    // metadata, not a visible post — capture it into the per-author profile cache (free, the body was just read)
    // and DROP it from the feed so it never renders as a blank post. Latest-wins by created_at/entryId.
    if (payload.type === 'document' && Number(payload.partCount ?? 1) <= 1) {
      const profileDoc = readProfileDocument(payload.documentBytes ?? payload.document_bytes);
      if (profileDoc?.isProfileOnly) {
        setChannelProfileFromWalk(authorWallet, profileDoc.profileBlock, entry.entry_id, createdAtSec);
        continue;
      }
    }
    const base = {
      id: `chain-${entry.entry_id.toString()}`,
      entryId: entry.entry_id.toString(),
      channelId: publicChannelIdForAuthorWallet(authorWallet),
      type: payload.type,
      text: payload.text ?? '',
      imageBytes: payload.imageBytes ?? payload.image_bytes,
      documentBytes: payload.documentBytes ?? payload.document_bytes,
      createdAt,
      author: publicAuthorLabel(authorWallet),
      authorWallet,
      bodyHash: payload.bodyHash ?? uint256Hex(entry.body_hash),
      entryUid: payload.entryUid ?? entry.entry_uid.toString(16),
      streamId: payload.stream_id,
      partIndex: payload.partIndex ?? 0,
      partCount: payload.partCount ?? 1,
      profileVersion: payload.profileVersion ?? payload.profile_version ?? 0,
      avatarHash: payload.avatarHash ?? payload.avatar_hash ?? zeroAvatarHashHex(),
      chainVerified: true,
    };
    if (payload.type === 'avatar') {
      avatarParts.push({
        ...base,
        imageBytes: payload.imageBytes ?? payload.image_bytes,
      });
    } else if (payload.type === 'comment' || payload.type === 'image_comment' || payload.type === 'document_comment') {
      commentParts.push({
        ...base,
        parentEntryId: payload.parentEntryId.toString(),
        parentHash: payload.parentHash,
      });
    } else {
      postParts.push({
        ...base,
        commentsAllowed: payload.commentsAllowed !== false,
      });
    }
  }
  // assemblePublicParts is hoisted to module scope (reused by the on-demand comment loader, loadPublicPostComments).
  const avatarGroups = new Map();
  for (const part of avatarParts) {
    const pointer = avatarPointerFromFields(part.profileVersion, part.avatarHash);
    if (!pointer) continue;
    const key = `${part.authorWallet}:${pointer.profileVersion}:${pointer.avatarHash}:${part.streamId}`;
    const group = avatarGroups.get(key) ?? {
      ownerWallet: part.authorWallet,
      pointer: { ...pointer, avatarPartCount: Number(part.partCount ?? 1) },
      parts: [],
    };
    group.parts.push(part);
    avatarGroups.set(key, group);
  }
  for (const group of avatarGroups.values()) {
    await cacheAssembledAvatarParts(group.parts, group.pointer);
  }
  const posts = assemblePublicParts(postParts);
  const comments = assemblePublicParts(commentParts);
  posts.reverse();
  comments.reverse();
  const postsByEntry = new Map(posts.map((post) => [String(post.entryId), post]));
  for (const comment of comments) {
    const parent = postsByEntry.get(String(comment.parentEntryId));
    if (!parent) continue;
    if (parent.commentsAllowed === false) continue;
    if (parent.bodyHash && comment.parentHash && parent.bodyHash.toLowerCase() !== comment.parentHash.toLowerCase()) continue;
    parent.comments = [...(parent.comments ?? []), comment];
  }
  // Group this cycle's new comments by parent entryId so the merge can attach them to a parent that is a CACHED
  // post (Phase 2 skips re-resolving unchanged posts, so such a parent is absent from `posts`/postsByEntry above).
  const newCommentsByParent = new Map();
  for (const comment of comments) {
    const key = String(comment.parentEntryId);
    if (!newCommentsByParent.has(key)) newCommentsByParent.set(key, []);
    newCommentsByParent.get(key).push(comment);
  }
  const updatedAt = new Date().toISOString();
  const postsByChannel = new Map();
  for (const post of posts) {
    const channelId = post.channelId ?? publicChannelSubscriptions?.activeChannelId ?? publicChannelRegistry[0]?.id ?? 'platho.app';
    const list = postsByChannel.get(channelId) ?? [];
    list.push(post);
    postsByChannel.set(channelId, list);
  }
  const channelIdsToRefresh = new Set([
    ...publicChannelRegistry.map((channel) => channel.id),
    ...Object.keys(publicChannelFeedCache ?? {}),
    ...postsByChannel.keys(),
  ]);
  const nextFeedCache = { ...publicChannelFeedCache };
  for (const channelId of channelIdsToRefresh) {
    const newChainPosts = postsByChannel.get(channelId) ?? [];
    // Append-merge (NOT a wholesale rebuild from this one walk): upsert this cycle's chain posts into the
    // channel's EXISTING cached chain posts by entryId, unioning comments. A degraded/rate-limited cycle that
    // returned fewer (or zero) posts for a channel therefore LEAVES the already-cached posts in place instead of
    // wiping them to the "Waiting for public feed" placeholder — that wholesale swap was the flicker. (Genuinely
    // evicted posts persist until the history window hides them or a future rotating self-heal prunes them.)
    const cachedFeed = publicChannelFeedCache?.[channelId]?.feed ?? publicChannelFeedCache?.[channelId];
    const existingChainPosts = (cachedFeed?.posts ?? []).filter(publicFeedPostHasChainAnchor);
    // Upsert this cycle's walked posts into the cached posts, THEN attach this cycle's new comments — including
    // comments whose parent is a cached post that was not re-walked (the Phase 2 comment-on-old-post path).
    const mergedChainPosts = prunePublicPostsBelowFloor(
      attachNewPublicComments(
        upsertPublicChainPosts(existingChainPosts, newChainPosts),
        newCommentsByParent,
      ),
      publicOldestLiveId,
    );
    const postsWithLocalPending = mergeLocalPendingPublicFeed(channelId, mergedChainPosts);
    nextFeedCache[channelId] = {
      feed: {
        version: 1,
        channelId,
        updatedAt,
        posts: postsWithLocalPending,
      },
      syncedAt: updatedAt,
    };
  }
  publicChannelFeedCache = nextFeedCache;
  // Commit-gate (mirrors the private cursor advance at app.js ~8163): only remember this global head as
  // "fully synced" after a CLEAN walk. A degraded (rate-limited) cycle leaves lastSyncedPublicLatestId unchanged
  // so the next cycle re-walks and picks up whatever the rate limit made it miss, instead of the fast-path
  // skipping past it forever.
  if (!walkDegraded) {
    // Advance the per-index cursors only now — after the merge committed — so a head is never recorded as "seen"
    // before its (new) entries actually reached the cache. A degraded cycle skips this entirely and re-walks next.
    // These commit for the channels READ THIS CYCLE (pendingAuthorHeadWrites), independent of the global round gate.
    for (const [key, head] of pendingAuthorHeadWrites) publicAuthorIndexHeads.set(key, head);
    for (const [key, truncated] of pendingAuthorTruncatedWrites) publicAuthorIndexTruncated.set(key, truncated);
    // F1 round gate: the global fast-path cursor advances only to the head that was current when this round BEGAN,
    // and only once every readable channel has been covered (read) since then. So a channel the budget skipped this
    // cycle can never let the fast-path advance past its not-yet-re-read posts. If new posts appeared during the
    // round (latestId > roundStartHead) the fast-path will not fire next cycle and a fresh round re-reads everyone;
    // once the feed goes quiet and a round completes, roundStartHead == latestId and the fast-path returns to zero
    // reads. A subscriber with <= budget channels covers all every cycle, so this reduces to the old per-cycle gate.
    const roundComplete = readableChannels.every((c) => publicAuthorRoundCovered.has(channelAuthorKeys.get(c.id).toString()));
    // Epoch guard: an invalidation that landed mid-walk means a channel THIS walk never read is now interesting —
    // committing the cursor here would let the NEXT walk fast-path past it forever (false "No posts yet").
    if (roundComplete && publicAuthorRoundStartHead !== null && publicSyncInvalidationEpoch === invalidationEpochAtStart) {
      lastSyncedPublicLatestId = publicAuthorRoundStartHead;
      lastSyncedPublicSyncWindow = syncWindow;
      publicAuthorRoundCovered.clear();
    }
  }
  globalThis.plathoLastPublicSync = {
    capsuleHub: address,
    latest: String(latest),
    minEntryId: String(minEntryId),
    scanned,
    readLimit,
    allTime: syncWindow === 'long',
    retryEntryCount: retryEntryIds.length,
    historyUnavailableCount: unavailableEntries.length,
    unavailableEntries,
    incompleteChannelCount: incompleteChannels.length,
    incompleteChannels,
  };
  return true;
}

function publicFeedPostHasChainAnchor(post) {
  return Boolean(
    post?.chainVerified === true
    && post?.entryId
    && post?.bodyHash
    && post?.entryUid
    && /^0x[0-9a-fA-F]{64}$/.test(String(post.bodyHash)),
  );
}

// Union two comment lists by entryId (fallback bodyHash), keeping the fresh copy on collision, sorted oldest
// first. Lets a degraded walk that re-read only SOME of a post's comments keep the rest instead of dropping them.
function mergePublicComments(existing = [], fresh = []) {
  const byKey = new Map();
  const order = [];
  const add = (comment) => {
    const key = String(comment?.entryId ?? '') || `hash:${String(comment?.bodyHash ?? '')}`;
    if (key === '' || key === 'hash:') return;
    if (!byKey.has(key)) order.push(key);
    byKey.set(key, byKey.has(key) ? { ...byKey.get(key), ...comment } : comment);
  };
  for (const comment of existing) add(comment);
  for (const comment of fresh) add(comment);
  return order
    .map((key) => byKey.get(key))
    .sort((a, b) => new Date(a?.createdAt ?? 0).getTime() - new Date(b?.createdAt ?? 0).getTime());
}

// Upsert this walk's chain posts into the channel's existing cached chain posts by entryId (fallback bodyHash):
// matching posts are refreshed (newer fields win) with their comments UNIONED; posts the walk did not return
// this cycle are kept. Result is sorted oldest-first to match the feed order. This is the public analogue of the
// private sync's idempotent append (appendOpenedCapsuleMessage) — merge into existing, never rebuild from empty.
function upsertPublicChainPosts(existing = [], fresh = []) {
  const byKey = new Map();
  const order = [];
  const add = (post) => {
    const key = String(post?.entryId ?? '') || `hash:${String(post?.bodyHash ?? '')}`;
    if (key === '' || key === 'hash:') return;
    if (byKey.has(key)) {
      const prev = byKey.get(key);
      byKey.set(key, { ...prev, ...post, comments: mergePublicComments(prev.comments ?? [], post.comments ?? []) });
    } else {
      byKey.set(key, post);
      order.push(key);
    }
  };
  for (const post of existing) add(post);
  for (const post of fresh) add(post);
  return order
    .map((key) => byKey.get(key))
    .sort((a, b) => new Date(a?.createdAt ?? 0).getTime() - new Date(b?.createdAt ?? 0).getTime());
}

// Chain-anchored post entryIds (BigInt) already cached for a channel. Phase 2 reuses these to check a cached
// post's parent (comment) index for NEW comments even when the post itself was not re-walked this cycle.
function cachedChainPostEntryIds(channelId) {
  const cachedFeed = publicChannelFeedCache?.[channelId]?.feed ?? publicChannelFeedCache?.[channelId];
  const ids = [];
  for (const post of cachedFeed?.posts ?? []) {
    if (!publicFeedPostHasChainAnchor(post)) continue;
    try { ids.push(BigInt(post.entryId)); } catch { /* skip non-numeric entryId */ }
  }
  return ids;
}

// Attach this cycle's NEW comments to their parent post even when the parent is a CACHED post that Phase 2 did
// not re-resolve (the parent is absent from the freshly-walked `posts`, so the in-place attach above would drop
// it). Comments are validated (commentsAllowed + parentHash match, mirroring the in-place attach) and unioned
// idempotently, so a comment already present is not duplicated.
function attachNewPublicComments(posts, newCommentsByParent) {
  if (!newCommentsByParent || newCommentsByParent.size === 0) return posts;
  return posts.map((post) => {
    const fresh = newCommentsByParent.get(String(post.entryId));
    if (!fresh || fresh.length === 0) return post;
    const valid = fresh.filter((comment) => post.commentsAllowed !== false
      && (!post.bodyHash || !comment.parentHash || post.bodyHash.toLowerCase() === comment.parentHash.toLowerCase()));
    if (valid.length === 0) return post;
    return { ...post, comments: mergePublicComments(post.comments ?? [], valid) };
  });
}

function chainBackedPublicFeedOnly(feed) {
  return {
    ...feed,
    posts: (feed?.posts ?? [])
      .filter(publicFeedPostHasChainAnchor)
      .map((post) => ({
        ...post,
        comments: (post.comments ?? []).filter(publicFeedPostHasChainAnchor),
      })),
  };
}

async function syncPublicChannels() {
  return await syncPublicChannelsRun();
}
async function syncPublicChannelsRun() {
  let chainSyncError = null;
  try {
    // First cycle on a fresh load pays the verifier failure that parks a dead
    // verifier (e.g. region-blocked toncenter); retry unverified in the same
    // call so the public feed loads immediately instead of next tick.
    const syncedFromChain = await callWithDegradedTransportReadFallback(
      () => syncPublicChannelFromChain(),
      () => syncPublicChannelFromChain(),
    );
    if (syncedFromChain) {
      commitPublicChannelFeedCache();
      rebuildThreadsFromPublicSubscriptions();
      renderThreads();
      renderConversation();
      // Serialize the two avatar hydrators (feed-post authors, then channel authors): firing both
      // fire-and-forget let their chain reads overlap on iOS (the v509 run-loop freeze class). One
      // sequential worker keeps them off the sync critical path while never running two at once.
      void (async () => {
        await hydratePublicAvatars();
        await hydratePublicChannelAvatars();
      })().catch((error) => console.error(error));
      const unavailableCount = Number(globalThis.plathoLastPublicSync?.historyUnavailableCount ?? 0);
      const incompleteCount = Number(globalThis.plathoLastPublicSync?.incompleteChannelCount ?? 0);
      if (unavailableCount > 0) {
        setPublicStatus(`chain sync: ${unavailableCount} history gap${unavailableCount === 1 ? '' : 's'}`);
      } else if (incompleteCount > 0) {
        // Honest incomplete signal (symmetric to the private 'sync incomplete'): a subscribed channel has more
        // retained posts on-chain than were surfaced. 'short' shows only the newest 128 — point the user at the
        // Long window; 'long' already loads full retained history, so only a past-cap extreme reports here.
        setPublicStatus(globalThis.plathoLastPublicSync?.allTime
          ? `feed incomplete: ${incompleteCount} channel${incompleteCount === 1 ? '' : 's'}`
          : 'older posts available — set History sync to Long');
      }
      setPublicSyncPhase('synced');
      return;
    }
  } catch (error) {
    chainSyncError = error;
    if (noteTonRpcRateLimit(error)) {
      setPublicStatus('sync delayed');
    } else {
      console.error(error);
    }
  }

  if (appConfig.capsuleHub?.allowUnverifiedStaticPublicFeeds !== true) {
    setPublicSyncPhase('delayed');
    setPublicStatus(chainSyncError ? 'chain sync unavailable' : 'chain provider unavailable');
    return;
  }

  const channels = subscribedPublicChannels(publicChannelSubscriptions, publicChannelRegistry);
  let changed = false;
  for (const channel of channels) {
    if (!channel.sourceUrl) continue;
    try {
      const response = await fetch(channel.sourceUrl, { cache: 'no-cache' });
      if (!response.ok) throw new Error(`Public channel feed unavailable: ${channel.id}`);
      const feed = chainBackedPublicFeedOnly(normalizePublicChannelFeed(await response.json(), channel.id));
      if ((feed.posts ?? []).length === 0) {
        throw new Error(`Public channel feed has no verified CapsuleHub anchors: ${channel.id}`);
      }
      publicChannelFeedCache = {
        ...publicChannelFeedCache,
        [channel.id]: {
          feed,
          syncedAt: new Date().toISOString(),
        },
      };
      changed = true;
    } catch (error) {
      console.error(error);
    }
  }
  if (!changed) return;
  commitPublicChannelFeedCache();
  rebuildThreadsFromPublicSubscriptions();
  renderThreads();
  renderConversation();
  void (async () => {
    await hydratePublicAvatars();
    await hydratePublicChannelAvatars();
  })().catch((error) => console.error(error));
}

function collectPublicAvatarRequests() {
  const requests = [];
  const seen = new Set();
  const visit = (item, options = {}) => {
    const ownerWallet = item?.authorWallet ?? item?.author_wallet;
    const pointer = avatarPointerFromFields(item?.profileVersion ?? item?.profile_version, item?.avatarHash ?? item?.avatar_hash);
    if (!ownerWallet || item.avatarImageUrl) return;
    if (!pointer && !options.allowCurrent) return;
    const key = `${ownerWallet}:${pointer?.profileVersion ?? 'current'}:${pointer?.avatarHash ?? 'current'}`;
    if (seen.has(key)) return;
    seen.add(key);
    requests.push({ ownerWallet, pointer });
  };
  for (const record of Object.values(publicChannelFeedCache ?? {})) {
    const feed = record?.feed ?? record;
    for (const post of feed?.posts ?? []) {
      visit(post);
      for (const comment of post.comments ?? []) visit(comment, { allowCurrent: true });
    }
  }
  return requests;
}

async function hydratePublicAvatars() {
  const requests = collectPublicAvatarRequests();
  if (requests.length === 0) return false;
  let changed = false;
  for (const request of requests.slice(0, 24)) {
    const imageUrl = await loadProfileAvatarImage(request.ownerWallet, request.pointer);
    if (!imageUrl) continue;
    changed = attachAvatarUrlToPublicFeedCache(request.ownerWallet, request.pointer, imageUrl) || changed;
  }
  if (!changed) return false;
  commitPublicChannelFeedCache();
  rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
  renderPublicSurface({ anchorUnread: false });
  renderThreads();
  renderConversation();
  return true;
}

// Resolve the avatar image for a Public wallet channel: the per-wallet profile avatar (loaded by
// hydratePublicChannelAvatars), falling back to the avatar already loaded for that wallet's open
// Private dialog. Lets a channel show a face even when it has no cached public posts yet.
// `memo` (optional) is a per-render-pass Map<rawWallet, url|null> so a feed of N items across M private threads
// resolves the O(M) findThreadByIdentityVariants scan at most ONCE per distinct author, not once per item (a
// channel's posts all share one authorWallet). Callers on a hot render loop pass a shared memo; one-off callers omit it.
function publicAvatarUrlForWallet(walletAddress, memo = null) {
  const raw = rawWalletAddress(walletAddress);
  if (!raw) return null;
  if (memo && memo.has(raw)) return memo.get(raw);
  const cached = publicChannelAvatarUrlByWallet.get(raw);
  let url;
  if (cached) {
    url = cached;
  } else {
    const thread = findThreadByIdentityVariants(threads, privateWalletIdentityVariants(raw));
    url = thread?.avatarImageUrl ?? null;
  }
  if (memo) memo.set(raw, url);
  return url;
}

// Load profile avatars for subscribed wallet channels straight from the ProfileRegistry (no public
// post required), keyed by wallet. Only successful loads are cached; a faceless wallet OR a wallet
// whose provider was momentarily unavailable stays uncached so a later sync retries it (no stuck
// "no avatar" once the user sets one or the provider recovers).
async function hydratePublicChannelAvatars() {
  // Includes the official channel so its post-style placeholder can show the platho.ath profile
  // avatar (falls back to the letter tile if that wallet has none).
  const channels = subscribedPublicChannels(publicChannelSubscriptions, publicChannelRegistry)
    .filter((channel) => channel.authorWallet);
  let changed = false;
  for (const channel of channels.slice(0, 24)) {
    const raw = rawWalletAddress(channel.authorWallet);
    if (!raw || publicChannelAvatarUrlByWallet.get(raw)) continue;
    let imageUrl = null;
    try {
      imageUrl = await loadProfileAvatarImage(channel.authorWallet);
    } catch (error) {
      if (!noteTonRpcRateLimit(error)) console.error(error);
      continue; // transient: leave uncached so a later sync retries
    }
    if (!imageUrl) continue;
    publicChannelAvatarUrlByWallet.set(raw, imageUrl);
    changed = true;
  }
  if (changed) renderPublicSurface({ anchorUnread: false });
  return changed;
}

function privateKeyIdIndexValue(keyId) {
  const bytes = base64UrlToBytes(keyId);
  if (bytes.length !== 32) throw new Error('Private messaging key id must be 32 bytes');
  return bytesToBigIntValue(bytes);
}

function privateChainIndexStorageKey(address = configuredCapsuleHubAddress(), role = 'recipient') {
  const hub = address ?? 'no-capsulehub';
  const keyId = localRecipientKeyPair?.keyId ?? 'no-key';
  return `${PRIVATE_CHAIN_INDEX_STORAGE_PREFIX}:${hub}:${keyId}:${role}`;
}

function normalizePrivateChainIndexCursor(cursor) {
  const normalized = {
    processedHeadLink: 0n,
    targetHeadLink: 0n,
    resumeLink: 0n,
  };
  if (!cursor || typeof cursor !== 'object') return normalized;
  for (const field of Object.keys(normalized)) {
    const raw = cursor[field];
    try {
      if (raw !== null && raw !== undefined && /^[0-9]+$/.test(String(raw))) normalized[field] = BigInt(raw);
    } catch {
      normalized[field] = 0n;
    }
  }
  return normalized;
}

function readPrivateChainIndexCursor(address, role) {
  try {
    const raw = localStorageOrNull()?.getItem(privateChainIndexStorageKey(address, role));
    if (!raw) return normalizePrivateChainIndexCursor(null);
    return normalizePrivateChainIndexCursor(JSON.parse(raw));
  } catch {
    // Non-persistent mode starts from the current indexed head.
  }
  return normalizePrivateChainIndexCursor(null);
}

function writePrivateChainIndexCursor(address, role, cursor) {
  try {
    const normalized = normalizePrivateChainIndexCursor(cursor);
    localStorageOrNull()?.setItem(privateChainIndexStorageKey(address, role), JSON.stringify({
      processedHeadLink: normalized.processedHeadLink.toString(),
      targetHeadLink: normalized.targetHeadLink.toString(),
      resumeLink: normalized.resumeLink.toString(),
    }));
  } catch {
    // Encrypted history still dedupes by capsule id when local storage is unavailable.
  }
}

function privateChainHeadRepairStorageKey(address = configuredCapsuleHubAddress(), role = 'recipient') {
  const hub = address ?? 'no-capsulehub';
  const keyId = localRecipientKeyPair?.keyId ?? 'no-key';
  return `${PRIVATE_CHAIN_HEAD_REPAIR_STORAGE_PREFIX}:${hub}:${keyId}:${role}`;
}

function readPrivateChainHeadRepairLink(address, role) {
  try {
    const raw = localStorageOrNull()?.getItem(privateChainHeadRepairStorageKey(address, role));
    if (!/^[0-9]+$/.test(String(raw ?? ''))) return 0n;
    return BigInt(raw);
  } catch {
    return 0n;
  }
}

function writePrivateChainHeadRepairLink(address, role, link) {
  try {
    const normalized = privateIndexLinkValue(link);
    localStorageOrNull()?.setItem(privateChainHeadRepairStorageKey(address, role), normalized.toString());
  } catch {
    // Repair scans are opportunistic; normal chain cursors still gate steady-state sync.
  }
}

function privateChainHistoryUnavailableStorageKey(address = configuredCapsuleHubAddress()) {
  const hub = address ?? 'no-capsulehub';
  const keyId = localRecipientKeyPair?.keyId ?? 'no-key';
  return `${PRIVATE_CHAIN_HISTORY_UNAVAILABLE_STORAGE_PREFIX}:${hub}:${keyId}`;
}

function normalizePrivateBodyHistoryUnavailableRecord(record) {
  const entryId = record?.entryId ?? record?.entry_id ?? record;
  if (!/^[0-9]+$/.test(String(entryId ?? ''))) return null;
  return {
    entryId: String(entryId),
    bodyHash: /^0x[0-9a-fA-F]{64}$/.test(String(record?.bodyHash ?? '')) ? String(record.bodyHash).toLowerCase() : null,
    createdAt: record?.createdAt ? String(record.createdAt) : null,
    strikes: Math.max(0, Math.floor(Number(record?.strikes ?? 0)) || 0),
    firstSeenAt: record?.firstSeenAt ? String(record.firstSeenAt) : (record?.lastSeenAt ? String(record.lastSeenAt) : new Date().toISOString()),
    lastSeenAt: record?.lastSeenAt ? String(record.lastSeenAt) : new Date().toISOString(),
  };
}

function readPrivateBodyHistoryUnavailable(address) {
  try {
    const raw = localStorageOrNull()?.getItem(privateChainHistoryUnavailableStorageKey(address));
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .map(normalizePrivateBodyHistoryUnavailableRecord)
      .filter(Boolean)
      .slice(-PRIVATE_CHAIN_HISTORY_UNAVAILABLE_LIMIT);
  } catch {
    return [];
  }
}

function writePrivateBodyHistoryUnavailable(address, records) {
  try {
    const normalized = (records ?? [])
      .map(normalizePrivateBodyHistoryUnavailableRecord)
      .filter(Boolean)
      .slice(-PRIVATE_CHAIN_HISTORY_UNAVAILABLE_LIMIT);
    const storage = localStorageOrNull();
    if (!storage) return;
    if (normalized.length === 0) storage.removeItem(privateChainHistoryUnavailableStorageKey(address));
    else storage.setItem(privateChainHistoryUnavailableStorageKey(address), JSON.stringify(normalized));
  } catch {
    // Non-persistent mode retries unavailable entries only within the current session.
  }
}

function entryBodyHashHex(entry) {
  try {
    if (entry?.body_hash === undefined || entry?.body_hash === null) return null;
    return uint256Hex(entry.body_hash).toLowerCase();
  } catch {
    return null;
  }
}

function publicChainHistoryUnavailableStorageKey(address = configuredCapsuleHubAddress()) {
  const hub = address ?? 'no-capsulehub';
  return `${PUBLIC_CHAIN_HISTORY_UNAVAILABLE_STORAGE_PREFIX}:${hub}`;
}

function normalizePublicBodyHistoryUnavailableRecord(record) {
  const entryId = record?.entryId ?? record?.entry_id ?? record;
  if (!/^[0-9]+$/.test(String(entryId ?? ''))) return null;
  return {
    entryId: String(entryId),
    bodyHash: /^0x[0-9a-fA-F]{64}$/.test(String(record?.bodyHash ?? '')) ? String(record.bodyHash).toLowerCase() : null,
    createdAt: record?.createdAt ? String(record.createdAt) : null,
    lastSeenAt: record?.lastSeenAt ? String(record.lastSeenAt) : new Date().toISOString(),
  };
}

function readPublicBodyHistoryUnavailable(address) {
  try {
    const raw = localStorageOrNull()?.getItem(publicChainHistoryUnavailableStorageKey(address));
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .map(normalizePublicBodyHistoryUnavailableRecord)
      .filter(Boolean)
      .slice(-PUBLIC_CHAIN_HISTORY_UNAVAILABLE_LIMIT);
  } catch {
    return [];
  }
}

function writePublicBodyHistoryUnavailable(address, records) {
  try {
    const normalized = (records ?? [])
      .map(normalizePublicBodyHistoryUnavailableRecord)
      .filter(Boolean)
      .slice(-PUBLIC_CHAIN_HISTORY_UNAVAILABLE_LIMIT);
    const storage = localStorageOrNull();
    if (!storage) return;
    if (normalized.length === 0) storage.removeItem(publicChainHistoryUnavailableStorageKey(address));
    else storage.setItem(publicChainHistoryUnavailableStorageKey(address), JSON.stringify(normalized));
  } catch {
    // Non-persistent mode retries unavailable public entries only within the current session.
  }
}

function rememberPublicBodyHistoryUnavailable(address, entry, entryId) {
  const id = String(entryId ?? entry?.entry_id ?? entry?.entryId ?? '');
  if (!/^[0-9]+$/.test(id)) return [];
  const existing = readPublicBodyHistoryUnavailable(address)
    .filter((record) => record.entryId !== id);
  existing.push({
    entryId: id,
    bodyHash: entryBodyHashHex(entry),
    createdAt: entry?.created_at !== undefined && entry?.created_at !== null ? String(entry.created_at) : null,
    lastSeenAt: new Date().toISOString(),
  });
  writePublicBodyHistoryUnavailable(address, existing);
  return existing;
}

function clearPublicBodyHistoryUnavailable(address, entryId) {
  const id = String(entryId ?? '');
  if (!/^[0-9]+$/.test(id)) return;
  const remaining = readPublicBodyHistoryUnavailable(address)
    .filter((record) => record.entryId !== id);
  writePublicBodyHistoryUnavailable(address, remaining);
}

function publicBodyHistoryRetryEntryIds(address, latest, minEntryId) {
  const ids = [];
  const latestId = BigInt(latest);
  const windowStart = BigInt(minEntryId);
  for (const record of readPublicBodyHistoryUnavailable(address)) {
    try {
      const id = BigInt(record.entryId);
      if (id < 0n || id >= latestId) continue;
      if (id >= windowStart && id < latestId) continue;
      ids.push(id);
    } catch {
      // Ignore corrupt local retry records.
    }
  }
  return ids;
}

function rememberPrivateBodyHistoryUnavailable(address, entry, entryId) {
  const id = String(entryId ?? privateEntryIdText(entry) ?? '');
  if (!/^[0-9]+$/.test(id)) return 0;
  const records = readPrivateBodyHistoryUnavailable(address);
  const prior = records.find((record) => record.entryId === id);
  const strikes = (Number(prior?.strikes ?? 0) || 0) + 1;
  const existing = records.filter((record) => record.entryId !== id);
  existing.push({
    entryId: id,
    bodyHash: entryBodyHashHex(entry),
    createdAt: entry?.created_at !== undefined && entry?.created_at !== null ? String(entry.created_at) : null,
    strikes,
    firstSeenAt: prior?.firstSeenAt ?? new Date().toISOString(),
    lastSeenAt: new Date().toISOString(),
  });
  writePrivateBodyHistoryUnavailable(address, existing);
  return strikes;
}

function clearPrivateBodyHistoryUnavailable(address, entryId) {
  const id = String(entryId ?? '');
  if (!/^[0-9]+$/.test(id)) return;
  const remaining = readPrivateBodyHistoryUnavailable(address)
    .filter((record) => record.entryId !== id);
  writePrivateBodyHistoryUnavailable(address, remaining);
}

function privateBodyHistoryRetryEntryIds(address, options = {}) {
  const ids = [];
  const records = readPrivateBodyHistoryUnavailable(address);
  const force = options.forceHistoryRetry === true;
  const retryLimit = force ? PRIVATE_CHAIN_HISTORY_RETRY_MANUAL_LIMIT : PRIVATE_CHAIN_HISTORY_RETRY_AUTO_LIMIT;
  const now = Date.now();
  for (const record of records) {
    // Terminally-capped body gaps (surfaced 'undelivered') stop consuming the auto-retry budget —
    // filtered BEFORE the cooldown, exactly like the stuck-entry store. The manual "Sync messages"
    // (force) path still re-attempts them so a no-key owner can retry without losing the option.
    if (!force && (Number(record.strikes ?? 0) || 0) >= PRIVATE_CHAIN_BODY_HISTORY_CROSS_SESSION_CAP) continue;
    if (!force) {
      const lastSeenMs = Date.parse(record.lastSeenAt ?? '');
      if (Number.isFinite(lastSeenMs) && now - lastSeenMs < PRIVATE_CHAIN_HISTORY_RETRY_COOLDOWN_MS) continue;
    }
    try {
      const id = BigInt(record.entryId);
      if (id < 0n) continue;
      ids.push(id);
    } catch {
      // Ignore corrupt local retry records.
    }
    if (ids.length >= retryLimit) break;
  }
  return ids;
}

// Count body gaps promoted past the cross-session cap — a surfaced "undelivered" body, fed into the
// sync's undeliveredCount so "Synced" stays honest after the cursor/early-skip stops re-fetching them.
function privateBodyHistorySurfacedCount(address) {
  return readPrivateBodyHistoryUnavailable(address)
    .filter((record) => (Number(record.strikes ?? 0) || 0) >= PRIVATE_CHAIN_BODY_HISTORY_CROSS_SESSION_CAP)
    .length;
}

// Is this entry's body terminally unrecoverable (capped)? Used to SKIP the heavy/500-prone body tx-scan
// on the per-cycle index walk while still reading the cheap entry metadata the walk needs.
function privateBodyHistoryEntryCapped(address, entryId) {
  const id = String(entryId ?? '');
  if (!/^[0-9]+$/.test(id)) return false;
  return readPrivateBodyHistoryUnavailable(address)
    .some((record) => record.entryId === id && (Number(record.strikes ?? 0) || 0) >= PRIVATE_CHAIN_BODY_HISTORY_CROSS_SESSION_CAP);
}

// Cross-session "stuck entry" store (#9): a private index entry that the per-session
// 3-strikes unknown-error skip would otherwise bury forever (cursor advances past it,
// in-memory counter dies on reload). Persisted here so later sessions re-scan it via
// the retryEntryIds replay (NOT via cursor manipulation), bounded by a cooldown +
// auto-limit + a cross-session strike cap; once capped it becomes a surfaced
// "undelivered" gap and stops being re-fetched. Mirrors the body-history store above.
function privateChainStuckEntryStorageKey(address = configuredCapsuleHubAddress()) {
  const hub = address ?? 'no-capsulehub';
  const keyId = localRecipientKeyPair?.keyId ?? 'no-key';
  return `${PRIVATE_CHAIN_STUCK_ENTRY_STORAGE_PREFIX}:${hub}:${keyId}`;
}

function normalizePrivateStuckEntryRecord(record) {
  const entryId = record?.entryId ?? record?.entry_id ?? record;
  if (!/^[0-9]+$/.test(String(entryId ?? ''))) return null;
  const strikes = Math.max(1, Math.floor(Number(record?.strikes ?? 1)) || 1);
  return {
    entryId: String(entryId),
    strikes,
    lastError: record?.lastError ? String(record.lastError).slice(0, 200) : null,
    firstSeenAt: record?.firstSeenAt ? String(record.firstSeenAt) : new Date().toISOString(),
    lastSeenAt: record?.lastSeenAt ? String(record.lastSeenAt) : new Date().toISOString(),
  };
}

function readPrivateStuckEntries(address) {
  try {
    const raw = localStorageOrNull()?.getItem(privateChainStuckEntryStorageKey(address));
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .map(normalizePrivateStuckEntryRecord)
      .filter(Boolean)
      .slice(-PRIVATE_CHAIN_STUCK_ENTRY_LIMIT);
  } catch {
    return [];
  }
}

function writePrivateStuckEntries(address, records) {
  try {
    const normalized = (records ?? [])
      .map(normalizePrivateStuckEntryRecord)
      .filter(Boolean)
      .slice(-PRIVATE_CHAIN_STUCK_ENTRY_LIMIT);
    const storage = localStorageOrNull();
    if (!storage) return;
    if (normalized.length === 0) storage.removeItem(privateChainStuckEntryStorageKey(address));
    else storage.setItem(privateChainStuckEntryStorageKey(address), JSON.stringify(normalized));
  } catch {
    // Non-persistent mode retries stuck entries only within the current session.
  }
}

function hasPrivateStuckEntry(address, entryId) {
  const id = String(entryId ?? '');
  if (!/^[0-9]+$/.test(id)) return false;
  return readPrivateStuckEntries(address).some((record) => record.entryId === id);
}

function rememberPrivateStuckEntry(address, entryId, message) {
  const id = String(entryId ?? '');
  if (!/^[0-9]+$/.test(id)) return 0;
  const records = readPrivateStuckEntries(address);
  const prior = records.find((record) => record.entryId === id);
  const strikes = (Number(prior?.strikes ?? 0) || 0) + 1;
  const remaining = records.filter((record) => record.entryId !== id);
  remaining.push({
    entryId: id,
    strikes,
    lastError: message ? String(message).slice(0, 200) : (prior?.lastError ?? null),
    firstSeenAt: prior?.firstSeenAt ?? new Date().toISOString(),
    lastSeenAt: new Date().toISOString(),
  });
  writePrivateStuckEntries(address, remaining);
  return strikes;
}

function clearPrivateStuckEntry(address, entryId) {
  const id = String(entryId ?? '');
  if (!/^[0-9]+$/.test(id)) return;
  const remaining = readPrivateStuckEntries(address).filter((record) => record.entryId !== id);
  writePrivateStuckEntries(address, remaining);
}

function privateStuckEntryRetryEntryIds(address, options = {}) {
  const ids = [];
  const records = readPrivateStuckEntries(address);
  const force = options.forceStuckRetry === true;
  const retryLimit = force ? PRIVATE_CHAIN_STUCK_ENTRY_RETRY_MANUAL_LIMIT : PRIVATE_CHAIN_STUCK_ENTRY_RETRY_AUTO_LIMIT;
  const now = Date.now();
  for (const record of records) {
    // Promoted-undelivered entries (strikes at the cap) stop being re-fetched —
    // filtered BEFORE the cooldown so they never consume the auto-retry budget.
    if ((Number(record.strikes ?? 0) || 0) >= PRIVATE_SCAN_UNKNOWN_ERROR_CROSS_SESSION_CAP) continue;
    if (!force) {
      const lastSeenMs = Date.parse(record.lastSeenAt ?? '');
      if (Number.isFinite(lastSeenMs) && now - lastSeenMs < PRIVATE_CHAIN_HISTORY_RETRY_COOLDOWN_MS) continue;
    }
    try {
      const id = BigInt(record.entryId);
      if (id < 0n) continue;
      ids.push(id);
    } catch {
      // Ignore corrupt local retry records.
    }
    if (ids.length >= retryLimit) break;
  }
  return ids;
}

function privateStuckEntrySurfacedCount(address) {
  return readPrivateStuckEntries(address)
    .filter((record) => (Number(record.strikes ?? 0) || 0) >= PRIVATE_SCAN_UNKNOWN_ERROR_CROSS_SESSION_CAP)
    .length;
}

function base64UrlToBytes(value) {
  const text = String(value ?? '');
  if (!/^[A-Za-z0-9_-]*$/.test(text)) throw new Error('Invalid base64url value');
  const padded = `${text}${'='.repeat((4 - (text.length % 4)) % 4)}`;
  const binary = atob(padded.replace(/-/g, '+').replace(/_/g, '/'));
  return Uint8Array.from(binary, (char) => char.charCodeAt(0));
}

function senderSigningPublicKeyValue(opened) {
  try {
    const bytes = base64UrlToBytes(opened?.capsule?.header0?.senderSigningPublicKey);
    if (bytes.length !== 32) return null;
    return bytesToBigIntValue(bytes).toString();
  } catch {
    return null;
  }
}

// The OWN messaging signing public key (as the same bigint-string senderSigningPublicKeyValue produces). Used to
// prove a capsule was SIGNED BY US — the only cheap, RPC-free, sender-mode-independent self-authorship check
// (payload.senderWallet is omitted in anonymous mode, so isSelfOpenedCapsule can't confirm self on a 2nd device).
function ownMessagingSignPubkeyValue() {
  try {
    const key = localIdentity?.signingPublicKey;
    return key && key.length === 32 ? bytesToBigIntValue(key).toString() : null;
  } catch {
    return null;
  }
}

function rememberKnownVaultKeyOwner(walletAddress, keyRecord) {
  const raw = rawWalletAddress(walletAddress);
  if (!raw || !keyRecord?.sign_pubkey) return null;
  const signPubkey = BigInt(keyRecord.sign_pubkey).toString();
  knownVaultKeyOwnerBySignPubkey.set(signPubkey, raw);
  knownVaultKeyRecordByWallet.set(raw, keyRecord);
  return raw;
}

function privateEntryPublisherWallet(entry) {
  const wallet = entry?.author_wallet ?? null;
  if (!wallet) return null;
  const vault = appConfig.vault?.address ?? null;
  if (vault && sameWalletAddress(wallet, vault)) return null;
  // On the RECIPIENT index the entry publisher is the OWN wallet, which is NEVER the sender of a received message —
  // returning it made peer messages resolve sender==own and file into "My notes". The own wallet is only a valid
  // "publisher-as-sender" for the SENDER-side path, which does not use this function.
  const own = ownRuntimeWalletRaw();
  if (own && sameWalletAddress(wallet, own)) return null;
  return wallet;
}

function privateWalletIdentityVariants(walletAddress) {
  const raw = rawWalletAddress(walletAddress);
  if (!raw) return [];
  const friendly = displayWalletAddress(raw);
  return normalizeIdentityVariants([
    { type: RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS, value: friendly, label: friendly, entered: friendly },
    { type: RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS, value: raw, label: friendly, entered: raw },
  ]);
}

function plathoUsernameIdentity(label) {
  const parsed = parseRecipientIdentity(label);
  return parsed.ok && parsed.identity.type === RECIPIENT_IDENTITY_TYPES.PLATHO_NFT ? parsed.identity : null;
}

async function verifiedPlathoUsernameIdentityForWallet(label, walletAddress) {
  const rawWallet = rawWalletAddress(walletAddress);
  const identity = plathoUsernameIdentity(label);
  if (!rawWallet || !identity) return null;
  const key = `${identity.value}:${rawWallet}`;
  // Short TTL, not forever: a username can be TRANSFERRED to another wallet, so a once-verified (username,wallet)
  // pairing must expire. Without this the old owner keeps wearing the username's label for the whole session even
  // after losing the NFT. (Routing is fixed authoritatively in resolveRecipientWalletForThread; this is label
  // hygiene.) Key includes the wallet, so an old-owner entry never mislabels the new owner.
  const cached = verifiedPlathoUsernameOwnerCache.get(key);
  if (cached && (Date.now() - cached.at) < PLATHO_USERNAME_OWNER_CACHE_TTL_MS) return cached.value;
  try {
    const resolved = await resolvePlathoUsernameOwner(identity.value);
    const verified = sameWalletAddress(resolved.ownerWallet, rawWallet)
      ? plathoUsernameIdentity(resolved.label)
      : null;
    verifiedPlathoUsernameOwnerCache.set(key, { value: verified, at: Date.now() });
    return verified;
  } catch (error) {
    if (!noteTonRpcRateLimit(error)) {
      console.warn('Unable to verify private sender username', identity.value, error);
    }
    return null;
  }
}

async function privateWalletIdentityVariantsWithUsername(walletAddress, usernameLabel) {
  const base = privateWalletIdentityVariants(walletAddress);
  const username = await verifiedPlathoUsernameIdentityForWallet(usernameLabel, walletAddress);
  return normalizeIdentityVariants([username, ...base]);
}

function knownPrivateWalletCandidates() {
  const wallets = new Map();
  for (const thread of threads) {
    for (const identity of threadIdentityVariants(thread)) {
      if (identity.type !== RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) continue;
      const raw = rawWalletAddress(identity.value);
      if (!raw) continue;
      if (appConfig.vault?.address && sameWalletAddress(raw, appConfig.vault.address)) continue;
      wallets.set(raw, raw);
    }
  }
  return [...wallets.values()];
}

function knownPrivateWalletForSigningPubkey(signPubkey) {
  let key = null;
  try {
    key = signPubkey ? BigInt(signPubkey).toString() : null;
  } catch {
    return null;
  }
  if (!key) return null;
  const remembered = knownVaultKeyOwnerBySignPubkey.get(key);
  if (remembered) return remembered;
  const ownRaw = ownRuntimeWalletRaw();
  for (const thread of threads) {
    const wallet = rawWalletAddress(ownerWalletFromThread(thread));
    if (!wallet) continue;
    for (const message of thread.messages ?? []) {
      if (message?.type !== 'in') continue;
      const capsules = [
        message.capsule,
        ...(message.capsules ?? []),
      ].filter(Boolean);
      if (capsules.some((capsule) => senderSigningPublicKeyValue({ capsule }) === key)) {
        // A PEER's received message MISFILED into the Saved thread (its owner == own) must NOT teach us that the
        // peer's signing key belongs to own. This heuristic reads "which dialog does a message with this sign key
        // currently sit in" — but a poisoned Saved placement (stale-build era, or a transient mis-route) then caches
        // peerSignKey -> own PERMANENTLY (the map is only cleared on lock), so resolveKnownPrivateSenderWallet returns
        // own for every future peer message, the v723 own-guard nulls it, and it is diverted to an Anonymous thread
        // forever — the migration "runs but never heals". Accept own-ownership ONLY from a GENUINE self-note (its sign
        // key IS own's messaging key — e.g. a note received on a 2nd device); otherwise skip this misplaced message so
        // the cryptographic resolveClaimedPrivateSenderWallet can bind the key to the real peer wallet.
        if (ownRaw && sameWalletAddress(wallet, ownRaw) && key !== ownMessagingSignPubkeyValue()) continue;
        knownVaultKeyOwnerBySignPubkey.set(key, wallet);
        return wallet;
      }
    }
  }
  return null;
}

async function resolveCurrentKnownVaultKeyRecord(walletAddress, provider, options = {}) {
  const raw = rawWalletAddress(walletAddress);
  if (!raw) return null;
  const cached = knownVaultKeyRecordByWallet.get(raw);
  if (cached && options.allowCached !== false) return cached;
  // Key trust prefers dual-provider verification. When verification is
  // structurally impossible (no reachable verifier on this network), the
  // record is still bound to the on-chain key id by hash recomputation in
  // assertVaultKeyRecordMatchesOwner, and availability wins by policy.
  const readPair = async (chainReadOptions) => {
    const readOptions = { vaultAddress: requireVaultAddress(), ...chainReadOptions };
    const user = await provider.getUser(raw, readOptions);
    const currentKeyId = BigInt(user.current_key_id ?? 0n);
    if (user.exists !== true || currentKeyId === 0n) return null;
    const keyRecord = await provider.getKeyRecord(currentKeyId, {
      ownerWallet: raw,
      ...readOptions,
    });
    await assertVaultKeyRecordMatchesOwner(raw, keyRecord, currentKeyId);
    rememberKnownVaultKeyOwner(raw, keyRecord);
    return keyRecord;
  };
  return callWithDegradedTransportReadFallback(
    () => readPair(criticalChainReadOptions()),
    () => readPair(unverifiedCriticalChainReadOptions()),
  );
}

async function assertVaultKeyRecordMatchesOwner(walletAddress, keyRecord, expectedKeyId) {
  const expected = BigInt(expectedKeyId ?? 0n);
  if (expected === 0n) throw new Error('Vault key id is required');
  const computedKeyId = await computeVaultMessagingKeyId({
    owner_wallet: requireBasechainAddress(walletAddress, 'Vault key owner'),
    key_generation: keyRecord?.key_generation ?? keyRecord?.keyGeneration,
    enc_pubkey: keyRecord?.enc_pubkey ?? keyRecord?.encPubkey,
    sign_pubkey: keyRecord?.sign_pubkey ?? keyRecord?.signPubkey,
    pq_kem_pubkey_hash: keyRecord?.pq_kem_pubkey_hash ?? keyRecord?.pqKemPubkeyHash,
    pq_kem_pubkey_len: keyRecord?.pq_kem_pubkey_len ?? keyRecord?.pqKemPubkeyLen,
    crypto_suite_mask: keyRecord?.crypto_suite_mask ?? keyRecord?.cryptoSuiteMask,
  });
  if (computedKeyId !== expected) {
    throw new Error('Vault key record does not belong to this wallet');
  }
  return computedKeyId;
}

async function resolveVaultKeyRecordForSenderWallet(walletAddress, vaultKeyId, provider) {
  const raw = rawWalletAddress(walletAddress);
  if (!raw) return null;
  if (vaultKeyId !== null && vaultKeyId !== undefined && BigInt(vaultKeyId) > 0n) {
    const readRecord = async (chainReadOptions) => {
      const keyRecord = await provider.getKeyRecord(BigInt(vaultKeyId), {
        ownerWallet: raw,
        vaultAddress: requireVaultAddress(),
        ...chainReadOptions,
      });
      await assertVaultKeyRecordMatchesOwner(raw, keyRecord, BigInt(vaultKeyId));
      rememberKnownVaultKeyOwner(raw, keyRecord);
      return keyRecord;
    };
    return callWithDegradedTransportReadFallback(
      () => readRecord(criticalChainReadOptions()),
      () => readRecord(unverifiedCriticalChainReadOptions()),
    );
  }
  return resolveCurrentKnownVaultKeyRecord(raw, provider, { allowCached: false });
}

async function resolveClaimedPrivateSenderWallet(opened, provider, signPubkey) {
  const claimedWallet = rawWalletAddress(opened?.payload?.senderWallet ?? opened?.payload?.sender_wallet);
  if (!claimedWallet) return null;
  const senderVaultKeyId = opened?.payload?.senderVaultKeyId ?? opened?.payload?.sender_vault_key_id ?? null;
  try {
    const keyRecord = await resolveVaultKeyRecordForSenderWallet(claimedWallet, senderVaultKeyId, provider);
    if (keyRecord?.sign_pubkey && BigInt(keyRecord.sign_pubkey).toString() === signPubkey) {
      lastClaimedSenderResolveDebug = { claimed: claimedWallet, outcome: 'matched' };
      return rememberKnownVaultKeyOwner(claimedWallet, keyRecord);
    }
    lastClaimedSenderResolveDebug = { claimed: claimedWallet, outcome: 'mismatch', hadKeyRecord: Boolean(keyRecord?.sign_pubkey) };
    console.warn('Private sender wallet claim did not match Vault signing key', claimedWallet);
  } catch (error) {
    if (noteTonRpcRateLimit(error)) { lastClaimedSenderResolveDebug = { claimed: claimedWallet, outcome: 'ratelimited' }; return null; }
    lastClaimedSenderResolveDebug = { claimed: claimedWallet, outcome: 'error', message: String(error?.message ?? error).slice(0, 80) };
    console.warn('Unable to verify private sender wallet claim', claimedWallet, error);
  }
  return null;
}

async function resolveKnownPrivateSenderWallet(opened, options = {}) {
  const signPubkey = senderSigningPublicKeyValue(opened);
  if (!signPubkey) return null;
  const localMatch = knownPrivateWalletForSigningPubkey(signPubkey);
  if (localMatch) return localMatch;
  const remembered = knownVaultKeyOwnerBySignPubkey.get(signPubkey);
  const candidates = [...new Set([
    remembered,
    ...knownPrivateWalletCandidates(),
  ].filter(Boolean))];
  let resolved = null;
  try {
    resolved = await resolveVaultChainProvider();
  } catch {
    return null;
  }
  if (!resolved?.getUser || !resolved?.getKeyRecord) return null;
  if (options.allowClaimedSenderWallet !== false) {
    const claimed = await resolveClaimedPrivateSenderWallet(opened, resolved, signPubkey);
    if (claimed) return claimed;
  }
  for (const wallet of candidates) {
    try {
      const keyRecord = await resolveCurrentKnownVaultKeyRecord(wallet, resolved, { allowCached: false });
      if (keyRecord?.sign_pubkey && BigInt(keyRecord.sign_pubkey).toString() === signPubkey) {
        return rememberKnownVaultKeyOwner(wallet, keyRecord);
      }
    } catch (error) {
      if (noteTonRpcRateLimit(error)) return null;
      console.warn('Unable to match private sender wallet', wallet, error);
    }
  }
  return null;
}

async function resolvePrivateCapsuleSenderWallet(opened, entry) {
  return await resolveKnownPrivateSenderWallet(opened) ?? privateEntryPublisherWallet(entry);
}

async function threadForOpenedSenderCapsule(opened) {
  const recipientWallet = rawWalletAddress(opened?.payload?.recipientWallet ?? opened?.payload?.recipient_wallet);
  if (recipientWallet) {
    const variants = privateWalletIdentityVariants(recipientWallet);
    // Heal-on-touch: never route a peer-addressed sent capsule into the Saved self-thread (see
    // healThreadWalletVariantConflict); after a strip, re-find — the real peer dialog (if any) now matches.
    let identityThread = findThreadByIdentityVariants(threads, variants);
    if (identityThread) {
      identityThread = healThreadWalletVariantConflict(identityThread, recipientWallet)
        ?? findThreadByIdentityVariants(threads, variants);
    }
    // HARD INVARIANT (mirror of the receive path): a sent capsule addressed to a PEER may never target Saved —
    // purge whatever stale named variant matched it there and re-resolve among the OTHER dialogs. A self note
    // (recipient == own) still routes to Saved as always.
    {
      const own = ownRuntimeWalletRaw();
      if (identityThread && own && recipientWallet !== own && isRealSavedThread(identityThread)) {
        purgePeerVariantsFromSavedThread(identityThread);
        identityThread = findThreadByIdentityVariants(threads.filter((thread) => !isRealSavedThread(thread)), variants);
      }
    }
    if (identityThread) return refreshThreadIdentityFromVariants(identityThread, variants);
    const created = createRecipientThread(recipientWallet);
    if (created?.ok && created.thread) {
      const existingById = threads.find((thread) => thread.id === created.thread.id);
      if (existingById) return refreshThreadIdentityFromVariants(existingById, variants);
      threads.push(created.thread);
      return refreshThreadIdentityFromVariants(created.thread, variants);
    }
  }
  const recipientKeyId = opened?.capsule?.header0?.recipientKeyId ?? opened?.payload?.recipientKeyId ?? opened?.payload?.recipient_key_id;
  const fallback = createInboundPeerThread({
    senderKeyId: recipientKeyId,
    keyId: recipientKeyId,
    label: 'Recovered sent',
  });
  const existingById = threads.find((thread) => thread.id === fallback.id);
  if (existingById) return existingById;
  threads.push(fallback);
  return fallback;
}

function findMessageByCapsuleId(capsuleId) {
  if (!capsuleId) return null;
  for (const thread of threads) {
    const message = (thread.messages ?? []).find((item) => (
      item.capsule?.id === capsuleId
      || (item.capsules ?? []).some((capsule) => capsule?.id === capsuleId)
    ));
    if (message) return { thread, message };
  }
  return null;
}

function messageBlocksForHistory(message) {
  if (!Array.isArray(message?.blocks) || message.blocks.length <= 0) return null;
  return safeJsonClone(message.blocks) ?? null;
}

function valuesJsonEqual(a, b) {
  try {
    return JSON.stringify(a ?? null) === JSON.stringify(b ?? null);
  } catch {
    return false;
  }
}

function mergeOpenedPrivateMessage(existingMessage, incomingMessage) {
  if (!existingMessage || !incomingMessage) return false;
  let changed = false;
  const assignIfPresent = (field) => {
    const value = incomingMessage[field];
    if (value === undefined || value === null) return;
    if (valuesJsonEqual(existingMessage[field], value)) return;
    existingMessage[field] = safeJsonClone(value) ?? value;
    changed = true;
  };
  const incomingBlocks = Array.isArray(incomingMessage.blocks) && incomingMessage.blocks.length > 0
    ? incomingMessage.blocks
    : null;
  if (incomingBlocks && !valuesJsonEqual(existingMessage.blocks, incomingBlocks)) {
    existingMessage.blocks = safeJsonClone(incomingBlocks) ?? incomingBlocks;
    changed = true;
  }
  for (const field of [
    'text',
    'payment',
    'attachment',
    'capsule',
    'capsules',
    'chainEntryId',
    'chainLastEntryId',
    'createdAt',
    'createdAtMs',
    'meta',
    'profileVersion',
    'avatarHash',
  ]) {
    assignIfPresent(field);
  }
  if (/published/i.test(String(incomingMessage.meta ?? ''))) {
    if (existingMessage.privatePublishConfirmStopped === true) changed = true;
    if (existingMessage.privateSendRetryStopped === true) changed = true;
    if (existingMessage.privateManualRetryAvailable === true) changed = true;
    if (existingMessage.privateCancelAvailable === true) changed = true;
    if (existingMessage.privateSendLastError) changed = true;
    existingMessage.privateSendRetryStopped = false;
    existingMessage.privateSendRetryAttempt = 0;
    existingMessage.privatePublishConfirmStopped = false;
    existingMessage.privatePublishConfirmAttempt = 0;
    clearPrivateSendRetry(existingMessage);
    clearPrivatePublishConfirmRetry(existingMessage);
    clearPrivateMessageManualRecovery(existingMessage);
  }
  return changed;
}

async function upsertOpenedPrivateMessage(existing, targetThread, incomingMessage) {
  if (!existing?.message || !targetThread || !incomingMessage) return false;
  const relocated = relocateExistingCapsuleMessage(existing, targetThread);
  const changed = mergeOpenedPrivateMessage(existing.message, incomingMessage);
  if (relocated || changed) {
    refreshThreadAfterMessageChange(existing.thread);
    refreshThreadAfterMessageChange(targetThread);
    await updateMessageInEncryptedHistory(targetThread, existing.message);
  }
  return relocated || changed;
}

function refreshThreadIdentityFromVariants(thread, variants) {
  if (!thread || variants.length === 0) return thread;
  const normalizedVariants = normalizeIdentityVariants(variants);
  const preferred = preferredInboundIdentity(normalizedVariants);
  const existingIdentity = thread.identity ? primaryThreadIdentity({ identity: thread.identity }) : null;
  const nextIdentity = existingIdentity ?? preferred;
  thread.pendingIdentityResolution = false;
  thread.pendingIdentityResolutionAt = null;
  thread.identityVariants = normalizeIdentityVariants([
    nextIdentity,
    ...(thread.identityVariants ?? []),
    ...normalizedVariants,
  ]);
  if (!existingIdentity && nextIdentity) {
    thread.identity = nextIdentity;
  }
  if (!thread.localLabel && !thread.displayIdentity && nextIdentity) {
    const label = displayIdentityLabel(nextIdentity);
    thread.name = label;
    thread.subtitle = identityTypeLabel(nextIdentity);
    thread.avatar = String(label || 'P').slice(0, 1).toUpperCase() || thread.avatar || 'P';
  }
  return thread;
}

// Remove an identity variant (matched by its key) from a thread and RE-LABEL it. Used when a .ath username is
// transferred away from this thread's wallet: the username is just a movable display alias, so the dialog (keyed
// by wallet) keeps existing but must stop wearing a name it no longer owns. Defeats the sticky-identity trap in
// refreshThreadIdentityFromVariants (which never overwrites thread.identity once set) by clearing identity /
// displayIdentity FIRST, then re-deriving the display from the kept variants (another username -> wallet address),
// while preserving a user-set local label. Returns true if anything was dropped (callers skip persist/render on
// a no-op, which also prevents repaint storms in the on-open revalidation).
function dropThreadIdentityVariant(thread, targetKey) {
  if (!thread) return false;
  const variants = threadIdentityVariants(thread);
  const kept = variants.filter((variant) => identityKey(variant) !== targetKey);
  if (kept.length === variants.length) return false;
  thread.identityVariants = normalizeIdentityVariants(kept);
  if (thread.identity && identityKey(thread.identity) === targetKey) thread.identity = null;
  if (thread.displayIdentity && identityKey(thread.displayIdentity) === targetKey && !thread.localLabel) {
    thread.displayIdentity = null;
  }
  if (kept.length > 0) refreshThreadIdentityFromVariants(thread, kept);
  applyThreadDisplayFields(thread);
  return true;
}

// A username now belongs to ownerWallet. Strip it from every OTHER wallet's dialog (the previous owner) and
// relabel them. Skips dialogs with no wallet variant (username-only, nothing to fall back to — the new-chat
// addressing re-keys those by wallet) and the owner's own dialog. The wallet is canonical; the username moves.
function reconcileUsernameOwnership(usernameIdentity, ownerWallet) {
  if (!usernameIdentity || !ownerWallet) return;
  const targetKey = identityKey(usernameIdentity);
  let changed = false;
  for (const thread of threads) {
    const wallet = ownerWalletFromThread(thread);
    if (!wallet || sameWalletAddress(wallet, ownerWallet)) continue;
    if (dropThreadIdentityVariant(thread, targetKey)) {
      syncThreadDisplayToContactStore(thread);
      persistThreadDisplayPreference(thread);
      changed = true;
    }
  }
  if (changed) renderThreads();
}

// Lazily re-check, on dialog open, that each .ath variant a dialog wears still resolves to the dialog's wallet;
// drop+relabel any that have been transferred away. Throttled per-dialog (once per TTL) so opening chats does not
// hammer the chain, and fire-and-forget so it never blocks the open. Distinguishes "transferred/unregistered"
// (strip) from a transient RPC failure (leave it) — unlike verifiedPlathoUsernameIdentityForWallet, which returns
// null for both, so we resolve directly here.
async function revalidateThreadUsernameVariants(thread) {
  if (!thread) return;
  const wallet = ownerWalletFromThread(thread);
  if (!wallet) return;
  const usernameVariants = threadIdentityVariants(thread)
    .filter((variant) => variant.type === RECIPIENT_IDENTITY_TYPES.PLATHO_NFT);
  if (usernameVariants.length === 0) return;
  // Never strip a peer's .ath off an unverifiable read (single unverified provider / hostile RPC could report a
  // wrong owner). Cheap sync predicate — no chain read; retries once verification recovers.
  if (tonRpcVerificationStructurallyDegraded()) return;
  if (thread.usernameRevalidatedAt && (Date.now() - thread.usernameRevalidatedAt) < PLATHO_USERNAME_OWNER_CACHE_TTL_MS) return;
  thread.usernameRevalidatedAt = Date.now();
  let dropped = false;
  for (const variant of usernameVariants) {
    let ownerWallet = null;
    try {
      ownerWallet = (await resolvePlathoUsernameOwner(variant.value)).ownerWallet;
    } catch (error) {
      if (error instanceof UsernameNotRegisteredError) ownerWallet = '';
      else continue; // transient RPC — do not strip
    }
    // Verification degraded mid-loop (was healthy at the pre-loop gate): the answer just now may be a single
    // unverified / hostile-RPC report — do NOT strip a peer's .ath on it. Abort and retry once verification recovers.
    if (tonRpcVerificationStructurallyDegraded()) { thread.usernameRevalidatedAt = 0; return; }
    if (!ownerWallet || !sameWalletAddress(ownerWallet, wallet)) {
      if (dropThreadIdentityVariant(thread, identityKey(variant))) {
        syncThreadDisplayToContactStore(thread);
        persistThreadDisplayPreference(thread);
        dropped = true;
      }
    }
  }
  if (dropped) {
    renderThreads();
    if (thread.id === activeThreadId) renderConversation();
  }
}

// Serialize ALL fire-and-forget username-hygiene resolves (own-linked reconcile + peer-dialog revalidate) through
// one chain so a catch-up sync spanning many dialogs never fires N concurrent resolvePlathoUsernameOwner reads —
// concurrent app-level toncenter reads are the v509-class iOS run-loop freeze. One resolve at a time; each task is
// still throttled internally, so this only bounds the fan-out, it adds no latency to anything user-facing.
let usernameHygieneChain = Promise.resolve();
function queueUsernameHygiene(task) {
  usernameHygieneChain = usernameHygieneChain.catch(() => {}).then(() => task()).catch(() => {});
  return usernameHygieneChain;
}

// Sender-side mirror of revalidateThreadUsernameVariants: reconcile the wallet's OWN linked .ath against the chain.
// After the user transfers the username NFT away, the local cache (readLinkedPlathoUsername) goes stale and would
// keep stamping a name the wallet no longer owns onto every outgoing private message (senderUsername). Throttled via
// the stored verified_at (same 5-min TTL) and serialized via queueUsernameHygiene, so it NEVER adds a round-trip to
// the send hot path — the send reads the cache synchronously; this only keeps the cache honest for the NEXT send.
// It strips the name ONLY on a DEFINITIVE, VERIFIED loss (a verified read whose authoritative owner != mine, or the
// name is unregistered) and then falls back to another still-owned known name (each re-verified) else clears it
// (next send carries no username). It NEVER strips on a transient RPC failure OR a structurally degraded
// (single-unverified-provider / hostile-RPC) read: a wrong-owner answer there could destroy a name the wallet
// legitimately still owns, and clearing is non-self-healing (only a manual re-link / mint re-writes it).
let ownLinkedUsernameReconcileInFlight = false;
async function reconcileOwnLinkedUsername() {
  const owner = plathoWallet?.address;
  if (!owner || ownLinkedUsernameReconcileInFlight) return;
  const linked = readLinkedPlathoUsername(owner);
  if (!linked?.label) return;
  if (linked.verified_at && (Date.now() - linked.verified_at) < PLATHO_USERNAME_OWNER_CACHE_TTL_MS) return;
  // Cannot verify ownership right now — do NOT reconcile off an unverifiable read; back off ~1 min so a degraded
  // window doesn't re-resolve the own name on every dialog open (and can't repeatedly risk a wrong-owner strip).
  if (tonRpcVerificationStructurallyDegraded()) { backoffOwnLinkedUsernameReconcile(linked, owner); return; }
  ownLinkedUsernameReconcileInFlight = true;
  try {
    let ownerWallet = null;
    try {
      ownerWallet = (await resolvePlathoUsernameOwner(linked.label)).ownerWallet;
    } catch (error) {
      if (error instanceof UsernameNotRegisteredError) ownerWallet = '';
      else { backoffOwnLinkedUsernameReconcile(linked, owner); return; } // transient RPC — leave cache intact, back off
    }
    // A read that COMPLETED but under degraded verification is not authoritative enough to destroy the local name.
    if (tonRpcVerificationStructurallyDegraded()) { backoffOwnLinkedUsernameReconcile(linked, owner); return; }
    if (ownerWallet && sameWalletAddress(ownerWallet, owner)) {
      writeLinkedPlathoUsername({ ...linked, verified_at: Date.now() }, owner); // still owned — refresh throttle stamp
      return;
    }
    // Definitively (verified) lost: drop it, then fall back to another still-owned known name.
    const priorMode = readWalletDisplayIdentity(owner)?.mode;
    const lostValue = plathoUsernameIdentity(linked.label)?.value ?? null;
    clearLinkedPlathoUsername(owner);
    for (const candidate of readKnownPlathoUsernames(owner)) {
      if (lostValue && plathoUsernameIdentity(candidate)?.value === lostValue) continue; // skip the one we just lost
      const identity = await verifiedPlathoUsernameIdentityForWallet(candidate, owner); // authoritative, wallet-keyed
      if (identity) {
        writeLinkedPlathoUsername({ ...identity, verified_at: Date.now() }, owner);
        // clearLinkedPlathoUsername forced display=ADDRESS; if the user was showing their .ath, keep showing one.
        if (priorMode === WALLET_DISPLAY_MODES.PLATHO_NFT) writeWalletDisplayIdentity({ mode: WALLET_DISPLAY_MODES.PLATHO_NFT }, owner);
        break;
      }
    }
    renderThreads(); // repaint own-identity surfaces (e.g. the Saved-messages self label)
  } finally {
    ownLinkedUsernameReconcileInFlight = false;
  }
}

// Push the reconcile throttle ~1 min forward after an unverifiable/transient read, so an RPC-degraded window doesn't
// re-resolve the own linked name on every dialog open. Keeps the label intact (only the verified_at stamp moves).
function backoffOwnLinkedUsernameReconcile(linked, owner) {
  if (!linked?.label) return;
  writeLinkedPlathoUsername({ ...linked, verified_at: Date.now() - PLATHO_USERNAME_OWNER_CACHE_TTL_MS + 60_000 }, owner);
}

// ---- Saved messages (v652): a private dialog with your OWN wallet, like Telegram's Saved -----------------------
// Last own wallet we positively knew this session. The logged-in identity NEVER changes within a session, so this is
// a safe fallback for the window where a background lock (Telegram/iOS suspends the webview) has nulled BOTH the
// runtime wallet AND — on some webviews — the stored record. Without it ownRuntimeWalletRaw() briefly returns null,
// which SKIPS every own-guard (threadForChainCapsule + privateEntryPublisherWallet): a peer capsule then resolves
// sender==own and is filed into "My notes" as a plain 'in' message (never flagged pending, never re-routed). It is
// only ever CONSULTED when both live sources are null; any live source overwrites it, so a wallet switch (which sets
// a live wallet before any routing runs) can never bleed the previous account's address into the new one's routing.
let lastKnownOwnWalletRaw = null;
function ownRuntimeWalletRaw() {
  try {
    const address = plathoWallet?.address ?? storedPlathoWalletRecord()?.address ?? null;
    const raw = address ? rawWalletAddress(address) : null;
    if (raw) { lastKnownOwnWalletRaw = raw; return raw; }
    return lastKnownOwnWalletRaw;
  } catch {
    return lastKnownOwnWalletRaw;
  }
}

// TRUE when a capsule is a message to SELF (sender == recipient == own wallet). Prefs snapshots are ALSO
// self-addressed but never reach display (the kind-based divert runs earlier) — this only shapes chat messages.
function isSelfOpenedCapsule(opened) {
  const own = ownRuntimeWalletRaw();
  if (!own) return false;
  if (opened?.openedAs === 'recipient') {
    // A self-note received on a 2nd device. The claimed senderWallet is SPOOFABLE (any peer can put own's address
    // in the plaintext payload), so a bare `sender === own` would let a peer pin its message into "My notes" as if
    // WE wrote it. Require CRYPTOGRAPHIC self-authorship: the capsule's sender signing key must BE our own messaging
    // key. Fail closed if our key isn't loaded yet (→ treated as a peer message, never mis-pinned to Saved).
    const ownSig = ownMessagingSignPubkeyValue();
    if (!ownSig || senderSigningPublicKeyValue(opened) !== ownSig) return false;
    const sender = rawWalletAddress(opened?.payload?.senderWallet ?? opened?.payload?.sender_wallet);
    return sender === own;
  }
  if (opened?.openedAs === 'sender') {
    const recipient = rawWalletAddress(opened?.payload?.recipientWallet ?? opened?.payload?.recipient_wallet);
    return recipient === own;
  }
  return false;
}

function isSavedMessagesThread(thread) {
  const own = ownRuntimeWalletRaw();
  if (!own || !thread) return false;
  const variants = Array.isArray(thread.identityVariants) && thread.identityVariants.length > 0
    ? thread.identityVariants
    : (thread.identity ? [thread.identity] : []);
  return variants.some((variant) => {
    try { return variant?.value && rawWalletAddress(variant.value) === own; } catch { return false; }
  });
}

// Ensure the Saved thread exists (top of the list) once a wallet is available. Keyed by the STANDARD own-wallet
// dm identity so chain scans (threadForChainCapsule / threadForOpenedSenderCapsule) route self messages here
// with zero routing changes.
function ensureSavedMessagesThread() {
  const own = plathoWallet?.address;
  if (!own) return null;
  const variants = privateWalletIdentityVariants(own);
  const existing = findThreadByIdentityVariants(threads, variants);
  if (existing) return existing;
  const created = createRecipientThread(own);
  if (!created?.ok || !created.thread) return null;
  created.thread.preview = 'Notes to yourself';
  threads.unshift(created.thread);
  return created.thread;
}

// Heal-on-touch companion to healCrossWalletIdentityBleed (the restore-time sweep): the moment ROUTING would
// conflate a PEER dialog with the Saved self-thread, resolve the conflict right there. Covers the races the
// sweep cannot (a sync pass landing BEFORE the history restore has healed, or any residual re-poisoning path).
// Returns the thread to use, or null when the matched thread was the REAL Saved thread (its creation id is the
// own-wallet dm id) wrongly carrying the peer's wallet variant — the peer variant is stripped off Saved and the
// caller re-resolves to (or creates) the real peer dialog. A PEER dialog wrongly carrying the OWN wallet variant
// is stripped in place and returned (it IS the peer's dialog; it just must stop looking like "My notes").
// The wallet a dialog is REALLY about = its PRIMARY (creation) identity, parsed from the immutable thread id
// (dm:wallet_address:<value>). Compared raw-normalized so a stored EQ/UQ/raw form NEVER fools us — the earlier
// string-id / string-key comparison silently failed when the address was stored in a different friendly form than
// displayWalletAddress() produces, which is exactly why a poisoned Saved thread was mis-identified and never healed.
function threadPrimaryWalletRaw(thread) {
  const match = /^dm:wallet_address:(.+)$/.exec(String(thread?.id ?? ''));
  if (match) {
    try { return rawWalletAddress(decodeURIComponent(match[1])); } catch { /* fall through */ }
  }
  const identity = thread?.identity;
  if (identity?.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) {
    try { return rawWalletAddress(identity.value); } catch { /* fall through */ }
  }
  return null;
}

// Remove EVERY wallet_address variant of `thread` whose wallet == walletRaw, in ANY friendly form (raw-normalized
// match, not by identity-key string — a grafted variant can be UQ/EQ/raw). Never touches the id-derived PRIMARY
// (callers only ever strip a NON-primary grafted wallet). Returns true if anything was removed.
function stripWalletVariantFromThread(thread, walletRaw) {
  const matches = (variant) => {
    if (variant?.type !== RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS) return false;
    try { return rawWalletAddress(variant.value) === walletRaw; } catch { return false; }
  };
  const current = threadIdentityVariants(thread);
  if (!current.some(matches)) return false;
  thread.identityVariants = normalizeIdentityVariants(current.filter((variant) => !matches(variant)));
  if (thread.identity && matches(thread.identity)) thread.identity = null;
  if (thread.displayIdentity && matches(thread.displayIdentity) && !thread.localLabel) thread.displayIdentity = null;
  applyThreadDisplayFields(thread);
  return true;
}

function healThreadWalletVariantConflict(thread, peerWalletRaw) {
  const own = ownRuntimeWalletRaw();
  if (!thread || !own || !peerWalletRaw || peerWalletRaw === own) return thread;
  if (!isSavedMessagesThread(thread)) return thread; // no own-wallet variant present — nothing to reconcile
  if (threadPrimaryWalletRaw(thread) === own) {
    // Real Saved/self thread wrongly carrying the PEER wallet → strip the peer variant, re-route the caller.
    if (stripWalletVariantFromThread(thread, peerWalletRaw)) persistThreadDisplayPreference(thread);
    return null;
  }
  // A peer dialog wrongly carrying the OWN wallet → strip the own variant in place; it IS the peer's dialog.
  if (stripWalletVariantFromThread(thread, own)) persistThreadDisplayPreference(thread);
  return thread;
}

// The REAL Saved/self thread, identified STRICTLY by its immutable CREATION id (raw-normalized) — NEVER by
// variants (variants are exactly what gets poisoned) and NEVER by the identity fallback (a named identity grafted
// onto some other thread must not let it be mistaken for Saved). The real Saved is ALWAYS created by
// createRecipientThread(own), so its id is always `dm:wallet_address:<own>`.
function isRealSavedThread(thread) {
  const own = ownRuntimeWalletRaw();
  if (!own || !thread) return false;
  const match = /^dm:wallet_address:(.+)$/.exec(String(thread.id ?? ''));
  if (!match) return false;
  try { return rawWalletAddress(decodeURIComponent(match[1])) === own; } catch { return false; }
}

// Restore the REAL Saved thread to its canonical shape: it wears ONLY the own wallet identity — never a
// username/DNS variant, never a foreign wallet, never a named identity/displayIdentity. This is the single source
// of Saved hygiene (routing purge + restore/heal both call it). Named grafts on "My notes" came from the pre-v729
// add-contact bug (the owner literally saw peer usernames in Saved's "Display as" list); since
// findThreadByIdentityVariants matches ANY variant kind, one stale grafted username kept attracting that peer's
// messages into Saved forever, even after the sender resolved correctly.
// IDEMPOTENT + no-op-safe: returns true ONLY when it actually changed something, so callers (esp. the per-sync
// heal) never persist/re-encrypt Saved history on a tick when it is already clean. displayIdentity is cleared even
// when a localLabel is set — Saved renders hardcoded as "My notes" and the label falls back to localLabel, so a
// named displayIdentity on Saved has zero display value and is pure poison (the adversarial-review persist-storm).
function purgeNamedIdentityFromSavedThread(savedThread) {
  if (!savedThread) return false;
  const own = isRealSavedThread(savedThread) ? ownRuntimeWalletRaw() : null;
  if (!own) return false;
  const isNamed = (variant) => Boolean(variant) && variant.type !== RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS;
  const canonical = normalizeIdentityVariants(privateWalletIdentityVariants(own));
  const canonicalKeys = new Set(canonical.map(identityKey));
  const current = Array.isArray(savedThread.identityVariants) ? savedThread.identityVariants : [];
  const variantsClean = current.length === canonical.length
    && current.every((variant) => variant?.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS && canonicalKeys.has(identityKey(variant)));
  const changed = isNamed(savedThread.displayIdentity) || isNamed(savedThread.identity) || !variantsClean;
  if (!changed) return false;
  savedThread.displayIdentity = null;
  savedThread.identity = canonical[0] ?? null;
  savedThread.identityVariants = canonical;
  applyThreadDisplayFields(savedThread);
  return true;
}

// Routing-time entry point: a NON-self capsule matched the real Saved thread through a stale variant — restore
// Saved to canonical (drops ALL named + foreign variants, not only the incoming one, so a sibling graft can't be
// promoted to Saved's name) and persist only when it changed.
function purgePeerVariantsFromSavedThread(savedThread) {
  if (purgeNamedIdentityFromSavedThread(savedThread)) { persistThreadDisplayPreference(savedThread); return true; }
  return false;
}

async function threadForChainCapsule(opened, entry) {
  if (opened?.openedAs === 'sender') {
    const target = await threadForOpenedSenderCapsule(opened);
    if (target) return target;
  }
  const senderKeyId = opened?.capsule?.header0?.senderKeyId;
  let senderWallet = await resolvePrivateCapsuleSenderWallet(opened, entry);
  // Diagnostic: snapshot the cryptographically-resolved sender BEFORE the own-guard can null it (see badge diag).
  const resolvedSenderBeforeGuard = (() => { try { return senderWallet ? rawWalletAddress(senderWallet) : null; } catch { return null; } })();
  // Sender-wallet sanity for routing (the real, ongoing root of "peer messages land in My notes"):
  // resolvePrivateCapsuleSenderWallet falls back to the chain entry publisher when the CRYPTOGRAPHIC sender can't be
  // resolved — and on the RECIPIENT index that publisher is the OWN wallet, so a peer's message resolved sender==own
  // and matched the Saved thread by the own-wallet variant (no graft needed).
  {
    const ownRaw = ownRuntimeWalletRaw();
    if (ownRaw) {
      if (isSelfOpenedCapsule(opened)) {
        // A self note (own->own) ALWAYS belongs in Saved — pin the sender to the own wallet so it routes there even
        // when key resolution fails on a degraded chain (publisher no longer supplies own).
        senderWallet = plathoWallet?.address ?? ownRaw;
      } else {
        // A received PEER message can NEVER have the own wallet as its sender. The VERIFIED sender is already returned
        // inside resolveKnown (resolveClaimedPrivateSenderWallet cryptographically binds the claimed wallet to the
        // capsule signing key); so an own/unresolved result here is the FAILED-verification case — do NOT trust the
        // raw, spoofable payload.senderWallet. Leave it unresolved: the message lands in an inbound peer thread keyed
        // by the sender key id (pendingIdentityResolution, re-bound when resolution recovers), never Saved.
        let resolvedRaw = null; try { resolvedRaw = senderWallet ? rawWalletAddress(senderWallet) : null; } catch { resolvedRaw = null; }
        if (resolvedRaw === ownRaw) senderWallet = null;
      }
    }
  }
  // Diagnostic: one record per routed capsule — why it landed where it did (badge diag reads plathoSenderResolveDebug).
  let claimedRawForDbg = null; try { claimedRawForDbg = rawWalletAddress(opened?.payload?.senderWallet ?? opened?.payload?.sender_wallet); } catch { claimedRawForDbg = null; }
  const resolveDbg = {
    as: opened?.openedAs ?? null,
    self: isSelfOpenedCapsule(opened),
    claimed: claimedRawForDbg,
    resolvedPre: resolvedSenderBeforeGuard,
    own: ownRuntimeWalletRaw(),
    final: (() => { try { return senderWallet ? rawWalletAddress(senderWallet) : null; } catch { return null; } })(),
    claimVerify: lastClaimedSenderResolveDebug,
  };
  const finishSenderResolve = (thread) => {
    resolveDbg.target = thread?.id ?? null;
    resolveDbg.targetSaved = thread ? isSavedMessagesThread(thread) : null;
    resolveDbg.targetPending = thread?.pendingIdentityResolution === true;
    recordSenderResolveDebug(resolveDbg);
    return thread;
  };
  const senderUsername = opened?.payload?.senderUsername ?? opened?.payload?.sender_username;
  // A SELF note (own->own) resolves WALLET-ONLY, exactly like threadForOpenedSenderCapsule: a note-to-self carries
  // the owner's OWN .ath in senderUsername, and grafting that PLATHO_NFT variant onto the real Saved thread would
  // then be stripped by the (now strict) per-sync heal on every scan — re-encrypting the WHOLE Saved history once
  // per new self-note. Saved wears only the own wallet; the own username is never a variant on "My notes".
  const variants = isSelfOpenedCapsule(opened)
    ? privateWalletIdentityVariants(senderWallet)
    : await privateWalletIdentityVariantsWithUsername(senderWallet, senderUsername);
  // Heal-on-touch: an incoming peer message must never land in the Saved self-thread (see
  // healThreadWalletVariantConflict); after a strip, re-find — the real peer dialog (if any) now matches.
  let identityThread = findThreadByIdentityVariants(threads, variants);
  if (identityThread) {
    identityThread = healThreadWalletVariantConflict(identityThread, rawWalletAddress(senderWallet))
      ?? findThreadByIdentityVariants(threads, variants);
  }
  // HARD INVARIANT: a NON-self capsule may NEVER target the real Saved thread, no matter WHICH stale variant
  // matched it. Wallet grafts are stripped above, but a grafted peer USERNAME also matches (the v728 iPhone dump
  // showed correctly-resolved peer messages still routed to Saved through exactly that) — purge the offending
  // named variants off Saved and re-resolve among the OTHER dialogs. A self capsule still routes to Saved as always.
  if (identityThread && !isSelfOpenedCapsule(opened) && isRealSavedThread(identityThread)) {
    purgePeerVariantsFromSavedThread(identityThread);
    identityThread = findThreadByIdentityVariants(threads.filter((thread) => !isRealSavedThread(thread)), variants);
  }
  if (identityThread) {
    // The sender may have TRANSFERRED away a .ath this dialog still wears. The fresh `variants` already exclude an
    // unowned name (verifiedPlathoUsernameIdentityForWallet drops it), but refreshThreadIdentityFromVariants is
    // sticky and never strips a previously-latched one — so re-check + relabel here. Throttled per-dialog (5-min)
    // and routed through the shared username-hygiene queue so a catch-up sync across many dialogs never fires N
    // concurrent chain reads (v509 iOS freeze); the private-scan loop never awaits it.
    queueUsernameHygiene(() => revalidateThreadUsernameVariants(identityThread));
    return finishSenderResolve(refreshThreadIdentityFromVariants(identityThread, variants));
  }
  const created = createInboundPeerThread({
    senderKeyId,
    keyId: senderKeyId,
    label: senderWallet ? displayWalletAddress(senderWallet) : null,
    ownerWallet: senderWallet ?? null,
    identity: preferredInboundIdentity(variants),
    identityVariants: variants,
  });
  // A CLAIMED-but-unverified sender (share mode + transient verification failure) is a resolution we should retry
  // and keep hidden meanwhile; a genuinely anonymous sender (no claim) is shown as-is.
  const hadClaimedSender = Boolean(opened?.payload?.senderWallet ?? opened?.payload?.sender_wallet);
  if (!senderWallet) {
    created.pendingIdentityResolution = true;
    created.pendingIdentityResolutionAt = new Date().toISOString();
    created.pendingClaimedSenderResolution = hadClaimedSender;
    if (hadClaimedSender) queuePendingSenderRescan(entry, created);
  }
  const existingById = threads.find((thread) => thread.id === created.id);
  if (existingById) {
    if (!senderWallet && isAnonymousPeerThread(existingById)) {
      existingById.pendingIdentityResolution = true;
      existingById.pendingIdentityResolutionAt = existingById.pendingIdentityResolutionAt ?? new Date().toISOString();
      if (hadClaimedSender) {
        existingById.pendingClaimedSenderResolution = true;
        queuePendingSenderRescan(entry, existingById);
      }
    }
    return finishSenderResolve(refreshThreadIdentityFromVariants(existingById, variants));
  }
  threads.push(created);
  return finishSenderResolve(created);
}

function ownerWalletFromThread(thread) {
  const variants = threadIdentityVariants(thread);
  const walletIdentity = variants.find((identity) => identity.type === RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS);
  return walletIdentity?.value ?? null;
}

function avatarPointerFromPrivateHeader(header0) {
  return avatarPointerFromFields(header0?.profileVersion ?? header0?.profile_version, header0?.avatarHash ?? header0?.avatar_hash);
}

async function hydrateThreadAvatarFromPointer(thread, ownerWallet, pointer) {
  if (!thread || !ownerWallet) return false;
  const cached = pointer ? await readProfileAvatarMediaCache(pointer.avatarHash) : null;
  const imageUrl = cached ?? await loadProfileAvatarImage(ownerWallet, pointer);
  if (!imageUrl || thread.avatarImageUrl === imageUrl) return false;
  thread.avatarImageUrl = imageUrl;
  renderThreads();
  if (thread.id === activeThreadId) renderConversation();
  return true;
}

// Push the logged-in user's own avatar into the public-feed per-wallet map (publicChannelAvatarUrlByWallet) so
// the own face shows in the feed/channel header, and re-render if it changed. Unlike counterparties — whose
// avatars warm from the avatarHash embedded in their feed posts — the own wallet often has NO feed post carrying
// its CURRENT avatarHash (the official channel may be postless; a past comment embeds the avatar-at-publish-time),
// so the feed-warm path can't restore it. Driving the map from the own profile avatar fixes that.
function setOwnPublicFeedAvatar(owner, imageUrl) {
  const raw = rawWalletAddress(owner);
  if (!raw) return;
  if (imageUrl) {
    if (publicChannelAvatarUrlByWallet.get(raw) === imageUrl) return;
    publicChannelAvatarUrlByWallet.set(raw, imageUrl);
  } else if (publicChannelAvatarUrlByWallet.has(raw)) {
    publicChannelAvatarUrlByWallet.delete(raw);
  } else {
    return;
  }
  renderPublicSurface({ anchorUnread: false });
}

// Restore the own avatar from the local media store IMMEDIATELY (no chain wait) using the persisted current
// pointer, into both the profile node and the public-feed map. This is what stops the own face vanishing to the
// letter tile on reload while the chain refresh is still in flight. Returns the cached url, or null on a miss.
async function restoreOwnAvatarFromCacheFast(owner = plathoWallet?.address) {
  if (!owner) return null;
  const pointer = readStoredProfileAvatarPointer(owner);
  if (!pointer) return null;
  const cachedUrl = await readProfileAvatarMediaCache(pointer.avatarHash);
  if (!cachedUrl) return null;
  setAvatarNode(profileAvatar, 'P', cachedUrl);
  setOwnPublicFeedAvatar(owner, cachedUrl);
  return cachedUrl;
}

async function refreshOwnProfileAvatar() {
  return await refreshOwnProfileAvatarRun();
}
async function refreshOwnProfileAvatarRun() {
  const owner = plathoWallet?.address;
  if (!owner) {
    setAvatarNode(profileAvatar, 'P', null);
    return null;
  }
  // Cache-first: show the cached avatar at once so it never flashes the letter tile, then confirm from chain.
  await restoreOwnAvatarFromCacheFast(owner).catch(() => {});
  const onChain = await readCurrentProfileAvatarPointerResultFromChain(owner, { required: false });
  const pointer = onChain.ok ? onChain.pointer : readStoredProfileAvatarPointer(owner);
  if (!pointer) {
    setAvatarNode(profileAvatar, 'P', null);
    setOwnPublicFeedAvatar(owner, null);
    return null;
  }
  const imageUrl = await loadProfileAvatarImage(owner, pointer);
  setAvatarNode(profileAvatar, 'P', imageUrl);
  setOwnPublicFeedAvatar(owner, imageUrl);
  return imageUrl;
}

async function readCurrentProfileAvatarPointerResultFromChain(ownerWallet, options = {}) {
  try {
    const resolved = await resolveProfileAvatarProvider();
    if (!resolved) {
      const error = new Error('KeyShard provider is required to read current avatar version');
      if (options.required === false) return { ok: false, pointer: null, error };
      throw error;
    }
    const record = await resolved.provider.getAvatar(ownerWallet, {
      profileRegistryAddress: resolved.address,
      ...criticalChainReadOptions(),
    });
    const pointer = profileAvatarPointerFromRecord(record);
    if (pointer) writeStoredProfileAvatarPointer(pointer, ownerWallet);
    else writeStoredProfileAvatarPointer(null, ownerWallet);
    return { ok: true, pointer, record };
  } catch (error) {
    if (options.required === false) {
      if (!noteTonRpcRateLimit(error)) console.error(error);
      return { ok: false, pointer: null, error };
    }
    throw error;
  }
}

async function readCurrentProfileAvatarPointerFromChain(ownerWallet, options = {}) {
  const result = await readCurrentProfileAvatarPointerResultFromChain(ownerWallet, options);
  return result.pointer;
}

function privateEntryIdValue(entry) {
  const value = entry?.entry_id ?? entry?.entryId;
  if (value === null || value === undefined) return null;
  try {
    return BigInt(value);
  } catch {
    return null;
  }
}

function privateEntryIdText(entry) {
  const value = privateEntryIdValue(entry);
  return value === null ? null : value.toString();
}

function privateEntryCreatedAtMs(entry) {
  const value = entry?.created_at ?? entry?.createdAt;
  if (value === null || value === undefined) return null;
  try {
    const ms = Number(BigInt(value) * 1000n);
    return Number.isFinite(ms) && ms > 0 ? ms : null;
  } catch {
    return null;
  }
}

function messageCreatedAtMs(message) {
  const local = Number(message?.localCreatedAtMs ?? message?.localHistoryCreatedAt);
  if (Number.isFinite(local) && local > 0) return local;
  const direct = Number(message?.createdAtMs);
  if (Number.isFinite(direct) && direct > 0) return direct;
  const parsed = Date.parse(message?.createdAt ?? '');
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

function privateChainMessageOrderFields(entry) {
  const chainEntryId = privateEntryIdText(entry);
  const createdAtMs = privateEntryCreatedAtMs(entry);
  const fields = {};
  if (chainEntryId !== null) fields.chainEntryId = chainEntryId;
  if (createdAtMs !== null) {
    fields.createdAtMs = createdAtMs;
    fields.createdAt = new Date(createdAtMs).toISOString();
  }
  return fields;
}

function localMessageOrderFields(createdAtMs = Date.now()) {
  return {
    createdAtMs,
    createdAt: new Date(createdAtMs).toISOString(),
    localCreatedAtMs: createdAtMs,
  };
}

function ensureMessageOrderFields(message, fallbackMs = Date.now()) {
  if (!message) return;
  if (messageCreatedAtMs(message) !== null) return;
  Object.assign(message, localMessageOrderFields(fallbackMs));
}

function compareMessageOrder(a, b) {
  const timeA = messageCreatedAtMs(a.message);
  const timeB = messageCreatedAtMs(b.message);
  if (timeA !== null && timeB !== null && timeA !== timeB) return timeA - timeB;
  const entryA = privateEntryIdValue({ entry_id: a.message?.chainEntryId });
  const entryB = privateEntryIdValue({ entry_id: b.message?.chainEntryId });
  if (entryA !== null && entryB !== null && entryA !== entryB) return entryA < entryB ? -1 : 1;
  return a.index - b.index;
}

function sortThreadMessages(thread) {
  if (!Array.isArray(thread?.messages) || thread.messages.length < 2) return;
  thread.messages = thread.messages
    .map((message, index) => ({ message, index }))
    .sort(compareMessageOrder)
    .map((item) => item.message);
}

function insertThreadMessage(thread, message) {
  if (!thread) return;
  if (!Array.isArray(thread.messages)) thread.messages = [];
  thread.messages.push(message);
  sortThreadMessages(thread);
}

// When this dialog was last ACTIVE = the newest message's timestamp (messages are kept ascending, so scan from the
// end; skip entries without a resolvable time). A just-created empty dialog falls back to its creation stamp
// (createdAtMs, set when the user opens a new chat) so it starts at the TOP of the list; with no stamp (e.g. an
// empty dialog restored from history) it sinks — no activity is exactly what "inactive" means. Drives the
// recency sort of the private list (renderThreads): active dialogs on top, dormant ones drift down.
function threadLastActivityMs(thread) {
  const messages = Array.isArray(thread?.messages) ? thread.messages : [];
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const ms = messageCreatedAtMs(messages[index]);
    if (ms !== null) return ms;
  }
  return Number.isFinite(thread?.createdAtMs) ? thread.createdAtMs : 0;
}

// A self-addressed subscription snapshot (Phase 2) rides as a single PREFS document block. Detect it on an opened
// capsule so the scan can divert it (collect for restore) BEFORE it is routed to a thread — it is never a chat
// message. v1 prefs is single-part, so multipart documents are never prefs here.
function prefsBytesFromOpenedCapsule(opened) {
  if (opened?.payload?.type !== 'document') return null;
  if (Number(opened.payload.partCount ?? 1) > 1) return null;
  // SECURITY: a prefs snapshot is ALWAYS self-authored (you publish it to your OWN index). A document capsule from
  // SOMEONE ELSE that merely contains a 'prefs' block must NEVER be treated as YOUR subscription snapshot — otherwise
  // a peer could inject subscriptions / a linked username onto a fresh device (drainRestoredPrefsSnapshots
  // auto-applies on a never-synced wallet). Require the capsule to be SIGNED BY OUR messaging key (works cross-device
  // + in anonymous sender mode, unlike a payload.senderWallet check). Fail closed if our key isn't loaded yet.
  const ownSig = ownMessagingSignPubkeyValue();
  if (!ownSig || senderSigningPublicKeyValue(opened) !== ownSig) return null;
  try {
    const prefsBlock = decodeMessageDocumentBlocks(opened.payload.bytes).find((block) => block?.type === 'prefs');
    return prefsBlock ? prefsBlock.bytes : null;
  } catch {
    return null;
  }
}

function messageFromOpenedCapsule(opened, meta, entry) {
  // A self message (Saved) always renders own-side — device A's echo and device B's chain restore agree.
  const isOutgoing = opened?.openedAs === 'sender' || isSelfOpenedCapsule(opened);
  const isImage = opened.payload?.type === 'image';
  const isDocument = opened.payload?.type === 'document';
  // tolerateUnknownBlocks (v646): forward-compat for the private DISPLAY path — a future block kind degrades to
  // "block skipped" instead of throwing the WHOLE message into the sync's unknown-error strike machine (stuck
  // entry -> cross-session retries -> terminal undelivered). Funds/prefs parsing paths keep their own strictness.
  const documentBlocks = isDocument ? displayBlocksFromDocumentBlocks(decodeMessageDocumentBlocks(opened.payload.bytes, { tolerateUnknownBlocks: true })) : [];
  const text = isDocument
    ? messagePreviewFromBlocks(documentBlocks)
    : (isImage ? '' : opened.plaintext);
  const message = {
    type: isOutgoing ? 'out' : 'in',
    text,
    meta,
    ...privateChainMessageOrderFields(entry),
    blocks: documentBlocks.length > 0 ? documentBlocks : undefined,
    capsule: opened.capsule,
    profileVersion: opened.capsule?.header0?.profileVersion ?? 0,
    avatarHash: opened.capsule?.header0?.avatarHash ?? zeroAvatarHashHex(),
  };
  if (isImage) {
    message.attachment = {
      type: 'image',
      url: bytesToImageDataUrl(opened.payload.bytes, 'image/webp'),
      bytes: opened.payload.bytes.length,
    };
  }
  return message;
}

function privateChainMessageMeta(entry, parts = 1) {
  if (entry?.openedAs === 'self') return parts > 1 ? `saved (${parts} parts)` : 'saved';
  if (entry?.openedAs === 'sender') return parts > 1 ? `published (${parts} parts)` : 'published';
  return parts > 1 ? `received (${parts} parts)` : 'received';
}

function privatePartKey(opened, entry) {
  const streamId = opened?.payload?.stream_id ?? 'single';
  const peer = opened?.openedAs === 'sender'
    ? rawWalletAddress(opened?.payload?.recipientWallet ?? opened?.payload?.recipient_wallet)
    : rawWalletAddress(opened?.payload?.senderWallet ?? opened?.payload?.sender_wallet);
  const identity = peer
    ?? privateEntryPublisherWallet(entry)
    ?? opened?.capsule?.header0?.senderKeyId
    ?? 'unknown';
  return `${opened?.openedAs ?? 'unknown'}:${identity}:${streamId}`;
}

function messageFromOpenedPrivateParts(parts, meta) {
  const ordered = [...parts].sort((a, b) => (
    Number(a.opened?.payload?.partIndex ?? 0) - Number(b.opened?.payload?.partIndex ?? 0)
  ));
  const orderedByChain = [...parts].sort((a, b) => {
    const entryA = privateEntryIdValue(a.entry ?? { entry_id: a.entryId });
    const entryB = privateEntryIdValue(b.entry ?? { entry_id: b.entryId });
    if (entryA === null || entryB === null || entryA === entryB) return 0;
    return entryA < entryB ? -1 : 1;
  });
  const first = ordered[0]?.opened;
  const isOutgoing = first?.openedAs === 'sender' || isSelfOpenedCapsule(first);
  const firstEntry = orderedByChain[0]?.entry;
  const lastEntry = orderedByChain[orderedByChain.length - 1]?.entry;
  const chainLastEntryId = privateEntryIdText(lastEntry);
  const documentParts = ordered.filter((part) => part.opened?.payload?.type === 'document');
  const documentBytes = documentParts.length > 0
    ? new Uint8Array(documentParts.reduce((sum, part) => sum + (part.opened?.payload?.bytes?.length ?? 0), 0))
    : null;
  if (documentBytes) {
    let offset = 0;
    for (const part of documentParts) {
      documentBytes.set(part.opened.payload.bytes, offset);
      offset += part.opened.payload.bytes.length;
    }
  }
  // Same forward-compat tolerance as the single-part path above (multipart private display decode).
  const documentBlocks = documentBytes ? displayBlocksFromDocumentBlocks(decodeMessageDocumentBlocks(documentBytes, { tolerateUnknownBlocks: true })) : [];
  const text = ordered
    .filter((part) => part.opened?.payload?.type === 'text')
    .map((part) => part.opened?.payload?.text ?? part.opened?.plaintext ?? '')
    .join('');
  const imageParts = ordered.filter((part) => part.opened?.payload?.type === 'image');
  const imageBytes = imageParts.length > 0
    ? new Uint8Array(imageParts.reduce((sum, part) => sum + (part.opened?.payload?.bytes?.length ?? 0), 0))
    : null;
  if (imageBytes) {
    let offset = 0;
    for (const part of imageParts) {
      imageBytes.set(part.opened.payload.bytes, offset);
      offset += part.opened.payload.bytes.length;
    }
  }
  const message = {
    type: isOutgoing ? 'out' : 'in',
    text: documentBlocks.length > 0 ? messagePreviewFromBlocks(documentBlocks) : text,
    meta,
    ...privateChainMessageOrderFields(firstEntry),
    capsule: first?.capsule,
    capsules: ordered.map((part) => part.opened?.capsule).filter(Boolean),
    blocks: documentBlocks.length > 0 ? documentBlocks : undefined,
    profileVersion: first?.capsule?.header0?.profileVersion ?? 0,
    avatarHash: first?.capsule?.header0?.avatarHash ?? zeroAvatarHashHex(),
  };
  if (chainLastEntryId && chainLastEntryId !== message.chainEntryId) {
    message.chainLastEntryId = chainLastEntryId;
  }
  if (imageBytes && documentBlocks.length === 0) {
    message.attachment = {
      type: 'image',
      url: bytesToImageDataUrl(imageBytes, 'image/webp'),
      bytes: imageBytes.length,
    };
  }
  return message;
}

function refreshThreadAfterMessageChange(thread) {
  if (!thread) return;
  sortThreadMessages(thread);
  const last = thread.messages?.[thread.messages.length - 1] ?? null;
  const status = messageStatusKey(last);
  thread.preview = last
    ? (messagePreviewFromBlocks(last.blocks) || last.text || (last.attachment ? 'Image' : ''))
    : 'No messages yet';
  // No thread.time write: the list's side label is computed at render from the last message's real timestamp
  // (formatThreadListTimestamp) — the old constant 'now'/'new' words carried no information.
  thread.state = status === 'failed'
    ? 'blocked'
    : status === 'sending'
      ? 'sending'
      : last?.capsule
        ? 'sealed'
        : (last ? 'local' : 'route');
}

function threadUnreadCount(thread) {
  const count = Number(thread?.unreadCount ?? 0);
  return Number.isFinite(count) && count > 0 ? Math.floor(count) : 0;
}

function isThreadConversationVisible(thread) {
  return Boolean(
    thread
      && thread.id === activeThreadId
      && isChatsViewActive()
      && appShell?.dataset?.chatOpen === 'true'
      && !document.hidden,
  );
}

function markThreadRead(thread) {
  if (!thread || threadUnreadCount(thread) === 0) return false;
  thread.unreadCount = 0;
  return true;
}

function markIncomingThreadMessage(thread) {
  // Saved never self-badges unread: every message there is the user's own.
  if (!thread || isSavedMessagesThread(thread) || isThreadConversationVisible(thread)) return;
  thread.unreadCount = threadUnreadCount(thread) + 1;
}

function messageMetaText(message) {
  const text = String(message?.meta ?? '').trim();
  if (!text) return '';
  if (privateMessageHasAutoRecoveryPending(message)) {
    if (/not sent|failed|blocked|retrying send|checking rpc/i.test(text)) {
      return message?.publishState ? publishStateMeta(message.publishState) : 'sending';
    }
  } else if (
    message?.type === 'out'
    && message.publishState
    && message.publishState.status !== CAPSULEHUB_PUBLISH_STATUS_CONFIRMED
    && isStalePrivatePendingPublishConfirmation(message)
    && /submitted|confirming|sending|waiting for chain/i.test(text)
  ) {
    // A private OUTBOUND stuck in a "confirming/submitted/sending" meta past the stale-confirmation window (24h) with
    // no active recovery is de-facto UNDELIVERED — its publish never landed (e.g. an underpriced/rejected capsule) and
    // no confirm job will ever flip it to CONFIRMED. Surface a durable terminal at RENDER time (works on reload even if
    // no confirm job re-armed for it), instead of an ETERNAL "submitted N/N, confirming". messageStatusKey maps the
    // "not confirmed" text to the red 'failed' class. Gated on stale (24h) + no active recovery, so a legitimately
    // in-flight send (still auto-recovering, or under the window) is never falsely terminalized.
    return privatePublishConfirmStoppedStatusText({ code: 'STALE_PRIVATE_PUBLISH' });
  }
  if (/chain #\d+/i.test(text)) return text.includes('parts') ? 'received parts' : 'received';
  if (/local capsule/i.test(text)) return 'sending';
  return text;
}

function messageStatusKey(message) {
  const text = messageMetaText(message).toLowerCase();
  if (
    text.includes('sending')
    || text.includes('submitted')
    || text.includes('confirming')
    || text.includes('retrying')
    || text.includes('waiting for chain confirmation')
  ) return 'sending';
  if (
    text.includes('failed')
    || text.includes('blocked')
    || text.includes('not sent')
    || text.includes('not confirmed')
    || text.includes('cancel required')
  ) return 'failed';
  if (text.includes('published') || text.includes('sent')) return 'sent';
  if (text.includes('received')) return 'received';
  return 'info';
}

function isAnonymousPeerThread(thread) {
  return Boolean(
    thread
      && String(thread.id ?? '').startsWith('peer:')
      && !thread.localLabel
      && !primaryThreadIdentity(thread),
  );
}

function isPendingIdentityResolutionThread(thread) {
  return isAnonymousPeerThread(thread) && thread.pendingIdentityResolution === true;
}

// A received message whose sender is NOT YET identified opens an inbound peer thread. When the sender was CLAIMED
// (share mode) but its cryptographic verification transiently failed (cold key cache / flaky RPC), that thread is
// about to resolve into a real dialog — so keep it HIDDEN for a short grace window and re-scan its entry each sync
// (queuePendingSenderRescan) until it resolves and its messages relocate to the peer's real dialog. This removes the
// "Anonymous jJrUJ8t-" flicker the owner disliked. If the grace elapses without a resolve (or the sender was
// genuinely anonymous — no claim to retry), the thread is SHOWN so a real message is never permanently hidden.
const PENDING_SENDER_RESOLUTION_GRACE_MS = 45000;

function pendingResolutionWithinGrace(thread) {
  const at = Date.parse(thread?.pendingIdentityResolutionAt ?? '');
  return Number.isFinite(at) ? (Date.now() - at) < PENDING_SENDER_RESOLUTION_GRACE_MS : false;
}

// A pending dialog is hidden ONLY while it is a transient (claimed-sender) resolution within the grace window —
// a genuinely anonymous sender (no claim) is shown immediately, and a stuck one is shown after the grace.
function isTransientPendingResolutionThread(thread) {
  return isPendingIdentityResolutionThread(thread)
    && thread.pendingClaimedSenderResolution === true
    && pendingResolutionWithinGrace(thread);
}

function queuePendingSenderRescan(entry, thread) {
  if (!pendingResolutionWithinGrace(thread)) return;
  try {
    const id = privateEntryIdText(entry);
    if (id !== null && id !== undefined) queueSavedRelocateEntryId(id);
  } catch { /* best-effort re-scan queue */ }
}

function pruneEmptyAnonymousPeerThreads() {
  let changed = false;
  for (let index = threads.length - 1; index >= 0; index -= 1) {
    const thread = threads[index];
    if (!isAnonymousPeerThread(thread) || (thread.messages ?? []).length > 0) continue;
    threads.splice(index, 1);
    changed = true;
    if (activeThreadId === thread.id) activeThreadId = null; // show the LIST, never default to threads[0] (Saved)
  }
  return changed;
}

function relocateExistingCapsuleMessage(existing, targetThread) {
  if (!existing?.thread || !existing?.message || !targetThread || existing.thread === targetThread) return false;
  const hadUnread = threadUnreadCount(existing.thread) > 0 && existing.message.type !== 'out';
  existing.thread.messages = (existing.thread.messages ?? []).filter((message) => message !== existing.message);
  if (hadUnread) existing.thread.unreadCount = Math.max(0, threadUnreadCount(existing.thread) - 1);
  if (!(targetThread.messages ?? []).includes(existing.message)) {
    insertThreadMessage(targetThread, existing.message);
    if (hadUnread) targetThread.unreadCount = threadUnreadCount(targetThread) + 1;
  }
  refreshThreadAfterMessageChange(existing.thread);
  refreshThreadAfterMessageChange(targetThread);
  // The source just had its message moved to the target (the same counterparty wallet, recognised after the fact).
  // If that emptied it, it's a duplicate dialog (e.g. one opened for a username before we knew it's an existing
  // contact) — drop it and move the user onto the surviving thread, so they aren't stranded in an empty merged
  // dialog. (pruneEmptyAnonymousPeerThreads below only removes no-identity peers; this also handles named ones.)
  if (existing.thread !== targetThread && (existing.thread.messages ?? []).length === 0) {
    const sourceThread = existing.thread;
    // NEVER merge away the self/Saved ("My notes") thread or lend its identity. A capsule can end up wrongly
    // double-homed in Saved (e.g. an outgoing send while the active dialog was momentarily unresolved); its message
    // is still relocated to the real peer above, but Saved must keep existing and its OWN-wallet identity must not
    // graft onto the peer — that graft is what flipped the peer dialog to "My notes" (isSavedMessagesThread sees the
    // own wallet on it) and bled the peer's avatar onto the user's own "You" channel.
    if (!isSavedMessagesThread(sourceThread)) {
      const sourceIndex = threads.indexOf(sourceThread);
      if (sourceIndex >= 0) {
        // Carry ONLY the merged dialog's USERNAME(s) into the survivor (its "Display as" list + display) — NEVER a
        // wallet_address variant. Grafting one dialog's wallet onto another's would mis-key routing/self-detection
        // (e.g. a support dialog and a platho dialog are the same wallet, so the username is the only useful carry;
        // two DIFFERENT wallets must never share a wallet variant).
        const sourceVariants = threadIdentityVariants(sourceThread)
          .filter((variant) => variant && variant.type !== RECIPIENT_IDENTITY_TYPES.WALLET_ADDRESS);
        if (sourceVariants.length > 0) refreshThreadIdentityFromVariants(targetThread, sourceVariants);
        if (sourceThread.localLabel && !targetThread.localLabel) {
          targetThread.localLabel = sourceThread.localLabel;
        } else if (!targetThread.localLabel) {
          // Adopt the username the merged dialog actually represented (first named variant) so the survivor shows
          // e.g. "support" instead of reverting to "platho".
          const namedVariant = sourceVariants[0] ?? null;
          if (namedVariant) targetThread.displayIdentity = namedVariant;
        }
        applyThreadDisplayFields(targetThread);
        syncThreadDisplayToContactStore(targetThread);
        persistThreadDisplayPreference(targetThread);
        threads.splice(sourceIndex, 1);
        if (activeThreadId === sourceThread.id) activeThreadId = targetThread.id;
      }
    }
  }
  pruneEmptyAnonymousPeerThreads();
  return true;
}

async function appendOpenedCapsuleMessage(opened, targetThread, meta, entry) {
  // Defensive divert (the scan already diverts before thread resolution): a prefs snapshot is never a chat message.
  const prefsBytes = prefsBytesFromOpenedCapsule(opened);
  if (prefsBytes) { collectRestoredPrefsSnapshot(prefsBytes); return true; }
  if (!targetThread) throw new Error('Private chain message target thread could not be resolved');
  const message = messageFromOpenedCapsule(opened, meta, entry);
  const existing = findMessageByCapsuleId(opened.capsule?.id);
  if (existing) return upsertOpenedPrivateMessage(existing, targetThread, message);
  insertThreadMessage(targetThread, message);
  refreshThreadAfterMessageChange(targetThread);
  if (message.type !== 'out') markIncomingThreadMessage(targetThread);
  await persistMessageToEncryptedHistory(targetThread, message);
  // Only an INCOMING message's header carries the counterparty's avatar. An outgoing ('out') message carries the
  // OWN avatar pointer, and the avatar media cache is content-addressed by avatarHash (not wallet), so feeding it
  // here would briefly paint the dialog header with the user's own avatar until an inbound message corrects it.
  if (message.type !== 'out') {
    hydrateThreadAvatarFromPointer(
      targetThread,
      ownerWalletFromThread(targetThread),
      avatarPointerFromPrivateHeader(opened.capsule?.header0),
    ).catch((error) => console.error(error));
  }
  return true;
}

async function appendOpenedPrivatePartsMessage(parts, targetThread, meta) {
  if (!targetThread) throw new Error('Private chain multipart target thread could not be resolved');
  const message = messageFromOpenedPrivateParts(parts, meta);
  const existing = parts.map((part) => findMessageByCapsuleId(part.opened?.capsule?.id)).find(Boolean);
  if (existing) return upsertOpenedPrivateMessage(existing, targetThread, message);
  insertThreadMessage(targetThread, message);
  refreshThreadAfterMessageChange(targetThread);
  if (message.type !== 'out') markIncomingThreadMessage(targetThread);
  await persistMessageToEncryptedHistory(targetThread, message);
  const firstOpened = parts[0]?.opened;
  // Incoming only — see appendOpenedCapsuleMessage: an outgoing message's header carries the OWN avatar.
  if (message.type !== 'out') {
    hydrateThreadAvatarFromPointer(
      targetThread,
      ownerWalletFromThread(targetThread),
      avatarPointerFromPrivateHeader(firstOpened?.capsule?.header0),
    ).catch((error) => console.error(error));
  }
  return true;
}

function isBodyHistoryUnavailableError(error) {
  return isCapsuleHubBodyHistoryUnavailable(error)
    || String(error?.code ?? '') === 'BODY_HISTORY_UNAVAILABLE'
    || /body was not found in message history|cannot read CapsuleHub message history/i.test(String(error?.message ?? error ?? ''));
}

function isPrivateOpenKeyMismatchError(error) {
  // NOTE: keep ONLY deterministic key/decrypt-mismatch tokens here. A message
  // matching this regex is treated as a PERMANENTLY unreadable capsule (the cursor
  // advances past it). Transient RPC errors (verification/timeout/5xx) must
  // re-walk, NOT drop — they are caught by the transient guard in
  // scanPrivateEntryId before this classifier is ever consulted.
  return /recipient|decrypt|key mismatch|expired|operation-specific/i.test(String(error?.message ?? error ?? ''));
}

function isPrivateUnreadableCapsuleError(error) {
  if (isPrivateOpenKeyMismatchError(error)) return true;
  const message = String(error?.message ?? error ?? '');
  return /private capsule|platho private capsule|capsulehub private entry|compact body|header0|header1|sender signature|magic mismatch|body size mismatch|suite mismatch|hash mismatch|invalid platho private capsule/i.test(message);
}

function privateSyncResult(fields = {}) {
  return {
    ok: fields.ok !== false,
    imported: Number(fields.imported ?? 0),
    skipped: Number(fields.skipped ?? 0),
    scanComplete: fields.scanComplete === true,
    reason: fields.reason ?? null,
    blockedEntryId: fields.blockedEntryId ?? null,
    catchUpRemaining: fields.catchUpRemaining ?? 0,
    indexLimitReachedWithoutCursor: fields.indexLimitReachedWithoutCursor === true,
    indexReadFallback: fields.indexReadFallback ?? null,
    historyUnavailableCount: Number(fields.historyUnavailableCount ?? 0),
    historyUnavailableEntries: Array.isArray(fields.historyUnavailableEntries) ? fields.historyUnavailableEntries : [],
    incompletePrivateStreamCount: Number(fields.incompletePrivateStreamCount ?? 0),
    undeliveredCount: Number(fields.undeliveredCount ?? 0),
    rateLimited: fields.rateLimited === true,
    rpcDelayed: fields.rpcDelayed === true,
    unchanged: fields.unchanged === true,
  };
}

function privateIndexLinkValue(value) {
  try {
    const link = BigInt(value ?? 0n);
    return link > 0n ? link : 0n;
  } catch {
    return 0n;
  }
}

function privateIndexLatestLink(index) {
  return privateIndexLinkValue(index?.latest_entry_link ?? 0n);
}

function privateIndexPreviousLink(entry, role) {
  return privateIndexLinkValue(
    role === 'sender'
      ? entry?.sender_prev_link
      : entry?.recipient_prev_link,
  );
}

function privateIndexEntryIdFromLink(link) {
  const normalized = privateIndexLinkValue(link);
  return normalized > 0n ? normalized - 1n : null;
}

function privateIndexCursorDebug(cursor) {
  const normalized = normalizePrivateChainIndexCursor(cursor);
  return {
    processedHeadLink: normalized.processedHeadLink.toString(),
    targetHeadLink: normalized.targetHeadLink.toString(),
    resumeLink: normalized.resumeLink.toString(),
  };
}

function privateIndexSyncReadLimit(options = {}) {
  const configured = Number(
    options.readLimit
      ?? appConfig.capsuleHub?.privateIndexReadLimit
      ?? (options.mode === 'auto' || options.fast === true
        ? PRIVATE_CHAIN_AUTO_INDEX_READ_LIMIT
        : PRIVATE_CHAIN_INDEX_READ_LIMIT),
  );
  return Number.isFinite(configured)
    ? Math.max(1, Math.floor(configured))
    : PRIVATE_CHAIN_INDEX_READ_LIMIT;
}

function privateIndexCursorPersistenceMode(readOptions = {}) {
  if (readOptions.verify === true && readOptions.allowUnverifiedCriticalRead !== true) return 'verified';
  // Client-direct keyless model: verify:false single-source (toncenter) reads are the trusted norm
  // (verifyCriticalReads:false; the gateway the 'verified' mode required is decommissioned). The private
  // index is an APPEND-ONLY backward-linked list, so a node cannot fabricate a future head; the cursor
  // advances only AFTER a complete walk (every entry head->stopLink processed), a lagging head simply
  // self-corrects next cycle (the cursor stays below the real head, so the next walk catches up), and the
  // head-repair window re-scans the recent entries every cycle. So persisting the keyless cursor is safe,
  // and it stops the per-cycle full re-walk (head->frozen-cursor, ~15 getPrivateEntry reads) that burned
  // the keyless RPC budget. The conservative non-persist mode stays for any read that opts OUT of the
  // unverified path (no allowUnverifiedCriticalRead).
  if (readOptions.allowUnverifiedCriticalRead === true) return 'keyless_unverified';
  return 'disabled_unverified';
}

function privateSyncImported(result) {
  if (typeof result === 'boolean') return result;
  return Number(result?.imported ?? 0) > 0;
}

function privateSyncStatusText(result) {
  if (typeof result === 'boolean') return result ? t('sync.newMessages') : t('sync.upToDate');
  if (!result) return t('sync.upToDate');
  if (result.rateLimited || result.rpcDelayed) return t('sync.delayedShort');
  if (Number(result.historyUnavailableCount ?? 0) > 0) {
    return result.imported > 0 ? t('sync.newMessagesHistoryGaps') : t('sync.historyGaps', { count: result.historyUnavailableCount });
  }
  if (result.reason === 'body_history_unavailable') {
    return result.blockedEntryId ? t('sync.historyUnavailableEntry', { id: result.blockedEntryId }) : t('sync.historyUnavailable');
  }
  if (result.reason === 'private_key_open_failed') {
    return result.blockedEntryId ? t('sync.keyMismatchEntry', { id: result.blockedEntryId }) : t('sync.keyMismatch');
  }
  if (result.reason === 'private_index_unavailable') {
    return t('sync.indexUnavailable');
  }
  if (result.reason === 'private_index_read_failed') {
    return t('sync.delayedShort');
  }
  if (result.reason === 'partial_stream_pending') {
    return t('sync.partsPending');
  }
  if (result.reason === 'index_limit_without_cursor') {
    return result.imported > 0 ? t('sync.newMessagesScanLimited') : t('sync.scanLimited');
  }
  if (result.reason === 'catch_up_pending') {
    return result.imported > 0 ? t('sync.newMessagesCatchUp') : t('sync.catchUpLeft', { count: result.catchUpRemaining ?? 0 });
  }
  if (result.reason === 'private_entry_undelivered' || Number(result.undeliveredCount ?? 0) > 0) {
    const n = Number(result.undeliveredCount ?? 0) || 1;
    return result.imported > 0 ? t('sync.newMessagesUndelivered', { n }) : tPlural('sync.undelivered', n);
  }
  if (Number(result.incompletePrivateStreamCount ?? 0) > 0) {
    return result.imported > 0 ? t('sync.newMessagesPartsPending') : t('sync.partsPending');
  }
  if (Number(result.skipped ?? 0) > 0) {
    return result.imported > 0 ? t('sync.newMessagesSomeDelayed') : t('sync.someDelayed');
  }
  if (result.ok === false || result.scanComplete === false) return t('sync.incomplete');
  return result.imported > 0 ? t('sync.newMessages') : t('sync.upToDate');
}

// The thread a decrypted CONV message belongs to, keyed on the peer's messaging keyId (the same convPeerKeyId
// handleIntroFirstContact stamped on the INTRO-receive thread). Created if a message somehow arrives before the INTRO
// thread does (defensive — the K_root is adopted from that INTRO, so normally the thread already exists).
function resolveConvReceiveThread(peerKeyIdB64) {
  let thread = threads.find((item) => item.convPeerKeyId === peerKeyIdB64);
  if (thread) return thread;
  const created = createInboundPeerThread({ senderKeyId: peerKeyIdB64, keyId: peerKeyIdB64, label: null });
  thread = threads.find((item) => item.id === created.id) ?? created;
  if (!threads.includes(thread)) threads.push(thread);
  thread.convPeerKeyId = peerKeyIdB64;
  return thread;
}

// Merge a conversation's freshly-decrypted capsules into a thread. Groups by streamId so a multipart message is
// reassembled (appendOpenedPrivatePartsMessage); a single-part message is its own group. Both appends dedup by
// capsule id, so re-reading the acceptance window on the next tick adds nothing. An incomplete multipart (some parts
// not yet on chain / not yet in the window) is held for a later tick rather than rendered as fragments.
async function appendConvOpenedCapsules(collected, targetThread) {
  if (collected.length === 0) return 0;
  const groups = new Map();
  for (const item of collected) {
    const payload = item.opened?.payload;
    const key = String(payload?.streamId ?? payload?.stream_id ?? item.opened?.capsule?.id ?? '');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(item);
  }
  let appended = 0;
  for (const parts of groups.values()) {
    const partCount = Number(parts[0]?.opened?.payload?.partCount ?? 1);
    try {
      if (partCount > 1) {
        if (parts.length < partCount) continue; // incomplete — wait for the remaining parts on a later tick
        if (await appendOpenedPrivatePartsMessage(parts, targetThread, 'received')) appended += 1;
      } else if (await appendOpenedCapsuleMessage(parts[0].opened, targetThread, 'received', parts[0].entry)) {
        appended += 1;
      }
    } catch (error) {
      console.warn('[conv] append failed', error);
    }
  }
  return appended;
}

// clean-17 CONV receive (gated). For every conversation whose K_root is in the store, read its incoming RecordShards
// (K_root → bucketKey → addresses, zero index), decrypt each published capsule to the recipient's keys, and merge into
// the SAME thread seam the CapsuleHub sync uses. Replaces getPrivateRecipientIndex/SenderIndex (a clean-15 concept)
// with the bucketKey batch read. Idempotent: appendConvOpenedCapsules dedups by capsule id.
// The furthest back the receive lane will ever catch up in one pass, in epochs. RecordShard retention is ~1 year
// (RS_RETENTION), after which a record is retired on-chain, so scanning older buys nothing. This bounds a cold-start /
// long-offline catch-up to a finite read fan while still covering the whole live retention window. [conv-receive review]
const CONV_SCAN_CATCHUP_CAP_EPOCHS = 366;

async function syncConvCapsulesFromShards() {
  if (!localRecipientKeyPair || !convKeyStore) return privateSyncResult({ ok: false, reason: 'not_ready', scanComplete: false });
  const transport = globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) return privateSyncResult({ ok: false, reason: 'provider_unavailable', scanComplete: false });
  const selfKeyId = localRecipientKeyPair.keyId;
  const lane = createConvReadLane({ readMessagesWithSource: createShardMessagesWithSourceReader() });
  const epochNow = epochFromCreatedAtSeconds(Math.floor(Date.now() / 1000));
  let imported = 0;
  let skipped = 0;
  let conversations = 0;
  let rateLimited = false;
  let allClean = true;
  for (const record of convKeyStore.snapshot().values()) {
    if (!record?.kRootCurrent || !record?.peerKeyId) continue;
    conversations += 1;
    const peerKeyId = record.peerKeyId;
    const targetThread = resolveConvReceiveThread(introKeyIdString(peerKeyId));
    // OFFLINE CATCH-UP. Always scan at least the last CONV_RECV_WINDOW_W epochs (the ±1 publish-slack window), and
    // extend BACK to this conversation's scan cursor if it is older — so a message whose epoch scrolled past the
    // steady window while the client was offline is still read. Capped at CONV_SCAN_CATCHUP_CAP_EPOCHS (retention).
    // NOTE: the cursor lives on the in-memory conv key store today, so full cross-reload offline resilience also needs
    // the persistent K_root store (a message is only lost if BOTH the store and the cursor are dropped on reload).
    const steadyFrom = epochNow - CONV_RECV_WINDOW_W;
    const cursorFrom = record.lastScannedEpoch == null ? steadyFrom : Math.min(steadyFrom, Number(record.lastScannedEpoch));
    const scanFrom = Math.max(0, epochNow - CONV_SCAN_CATCHUP_CAP_EPOCHS, cursorFrom);
    const windowW = Math.max(CONV_RECV_WINDOW_W, epochNow - scanFrom);
    // The current root plus any retired roots (a re-INTRO minted a new K_root; old messages still in the window
    // decrypt under the retired one). kRootsForRead holds { kRoot, adoptedAt }.
    const roots = [record.kRootCurrent, ...(record.kRootsForRead ?? []).map((entry) => entry.kRoot)];
    const collected = [];
    let convClean = true; // every shard read for this conversation succeeded — only then may the cursor advance
    for (const kRoot of roots) {
      let entries;
      try {
        entries = await lane.readIncoming({ kRoot, selfKeyId, peerKeyId, epochNow, windowW });
      } catch (error) {
        convClean = false; allClean = false;
        if (noteTonRpcRateLimit(error)) rateLimited = true;
        else console.warn('[conv] incoming shard read failed', error);
        continue;
      }
      for (const found of entries) {
        let opened;
        try {
          opened = await openPrivateCapsuleChainEntry(found.entry, localRecipientKeyPair, { enforceExpiry: false });
        } catch (error) {
          if (isPrivateUnreadableCapsuleError(error)) { skipped += 1; continue; }
          convClean = false; allClean = false;
          if (noteTonRpcRateLimit(error)) rateLimited = true;
          else console.warn('[conv] capsule open failed', error);
          continue;
        }
        collected.push({ opened, entry: { entry_id: found.seq } });
      }
    }
    imported += await appendConvOpenedCapsules(collected, targetThread);
    // Advance the cursor ONLY on a fully clean scan — a failed read must leave the cursor so those epochs are retried,
    // never silently skipped past.
    if (convClean) await convKeyStore.advanceConvScanCursor(selfKeyId, peerKeyId, epochNow);
  }
  if (imported > 0) { renderThreads(); renderConversation(); }
  globalThis.plathoLastConvSync = { at: new Date().toISOString(), conversations, imported, skipped, epochNow, rateLimited };
  // scanComplete reflects the truth: false if any read failed (so the UI does not claim 'up to date' over a gap).
  return privateSyncResult({ ok: true, imported, skipped, scanComplete: allClean, rateLimited });
}

async function syncPrivateCapsulesFromChain(options = {}) {
  // clean-17 direct-pay: the CapsuleHub recipient/sender index walk below is a clean-15 concept. Private receive now
  // reads the conversation's RecordShards by bucketKey (K_root → addresses, no index) and decrypts into the same
  // thread seam. Mirrors syncPublicChannelFromChain's top branch.
  if (privateLaneDirectPayEnabled()) return syncConvCapsulesFromShards(options);
  if (!localRecipientKeyPair) return privateSyncResult({ ok: false, reason: 'not_ready', scanComplete: false });
  const resolved = await resolveCapsuleHubProvider();
  if (!resolved) return privateSyncResult({ ok: false, reason: 'provider_unavailable', scanComplete: false });
  const { provider, address } = resolved;
  if (!provider?.getPrivateRecipientIndex || !provider?.getPrivateSenderIndex || !provider?.getPrivateEntry) {
    const result = privateSyncResult({ ok: false, reason: 'private_index_unavailable', scanComplete: false });
    globalThis.plathoLastPrivateSync = {
      capsuleHub: address,
      keyId: localRecipientKeyPair?.keyId ?? null,
      imported: 0,
      skipped: 0,
      scanComplete: false,
      reason: result.reason,
      mode: options.mode === 'auto' || options.fast === true ? 'auto' : 'recovery',
      scanLog: ['index-unavailable'],
    };
    return result;
  }
  const quickSync = options.mode === 'auto' || options.fast === true;
  let allowUnverifiedPrivateIndexRead = options.allowUnverifiedPrivateIndexRead === true;
  const allowUnverifiedPrivateIndexFallback = quickSync && options.allowUnverifiedPrivateIndexRead !== false;
  let readOptions = allowUnverifiedPrivateIndexRead
    ? capsuleHubMessageSyncReadOptions(address)
    : criticalCapsuleHubReadOptions(address);
  const forceIndexRescan = options.forceIndexRescan === true;
  const keyIdIndex = privateKeyIdIndexValue(localRecipientKeyPair.keyId);
  let recipientIndex = null;
  let senderIndex = null;
  let indexReadFallback = null;
  // Sequential, not Promise.all: the recipient + sender index reads are 2 concurrent toncenter reads that stall
  // the iOS run loop (v509 class) — and this runs on every sync tick, boot and unlock. Two independent read-only
  // index reads; sequential returns the same [recipient, sender] heads (the walk is eventually-consistent, so a
  // one-block skew between the two heads just resolves on the next cycle — no entry is lost).
  const readPrivateIndexes = async () => {
    const recipient = await provider.getPrivateRecipientIndex(keyIdIndex, readOptions);
    const sender = await provider.getPrivateSenderIndex(keyIdIndex, readOptions);
    return [recipient, sender];
  };
  const privateIndexReadFailure = (error) => {
    const rateLimited = noteTonRpcRateLimit(error);
    const rpcDelayed = !rateLimited && isTonRpcTransientError(error);
    const result = privateSyncResult({
      ok: false,
      reason: 'private_index_read_failed',
      scanComplete: false,
      rateLimited,
      rpcDelayed,
    });
    const indexReadError = shortUiErrorText(error, 'private index read failed');
    globalThis.plathoLastPrivateSync = {
      capsuleHub: address,
      keyId: localRecipientKeyPair?.keyId ?? null,
      indexKeyId: keyIdIndex.toString(),
      imported: 0,
      skipped: 0,
      scanComplete: false,
      pageComplete: false,
      reason: result.reason,
      mode: quickSync ? 'auto' : 'recovery',
      indexReadError,
      indexReadFallback,
      rateLimited,
      rpcDelayed,
      scanLog: ['index-read-error'],
    };
    if (rpcDelayed) return result;
    throw error;
  };
  try {
    [recipientIndex, senderIndex] = await readPrivateIndexes();
  } catch (error) {
    if (!allowUnverifiedPrivateIndexRead && allowUnverifiedPrivateIndexFallback && isTonRpcVerificationSoftReadError(error)) {
      indexReadFallback = shortUiErrorText(error, 'verified private index unavailable');
      allowUnverifiedPrivateIndexRead = true;
      readOptions = capsuleHubMessageSyncReadOptions(address);
      try {
        [recipientIndex, senderIndex] = await readPrivateIndexes();
      } catch (fallbackError) {
        return privateIndexReadFailure(fallbackError);
      }
    } else {
      return privateIndexReadFailure(error);
    }
  }
  // Cursor persistence is a local performance cache, but advancing it can hide
  // older index entries. It only moves after a verified indexed walk; unverified
  // fallback may import self-authenticated entries but leaves the active cursor
  // untouched.
  const cursorPersistence = privateIndexCursorPersistenceMode(readOptions);
  const canPersistPrivateIndexCursor = cursorPersistence !== 'disabled_unverified';
  const recipientHead = privateIndexLatestLink(recipientIndex);
  const senderHead = privateIndexLatestLink(senderIndex);
  // Re-heal on EVERY sync, not just boot: a session poisoned mid-flight (a peer capsule filed into "My notes" while
  // the wallet was transiently locked, or a variant grafted onto Saved) must self-correct WITHOUT waiting for a full
  // re-unlock. This is the cheap Saved-only pass (strip foreign variants + queue Saved-stuck messages for relocation);
  // the anonymous re-queue + own-contact-display write stay boot-only. Runs BEFORE the retry snapshot below so the
  // queued ids are consumed in THIS pass.
  healCrossWalletIdentityBleed();
  // Replay set: body-history gaps + cross-session stuck entries (#9), re-scanned
  // regardless of the advanced cursor. De-duped by value (an id can sit in both
  // stores). Manual "Sync messages" (forceHistoryRetry) uses the manual limits for
  // both. The stuck ids are made safe for the {ok:false}-break replay loop by the
  // fast-path in scanPrivateEntryId (a persisted stuck entry returns {ok:true}).
  const retryEntryIds = [...new Set([
    ...privateBodyHistoryRetryEntryIds(address, { forceHistoryRetry: options.forceHistoryRetry === true }),
    ...privateStuckEntryRetryEntryIds(address, { forceStuckRetry: options.forceHistoryRetry === true }),
    // One-time relocation of messages the identity-bleed heal found stuck inside "My notes" (re-open -> route to
    // the true sender -> relocate out of Saved). Snapshot + clear now so the loop below consumes them once.
    ...(() => { const ids = [...pendingSavedRelocateEntryIds]; pendingSavedRelocateEntryIds = new Set(); return ids; })(),
  ].map((id) => id.toString()))].map((id) => BigInt(id));
  const baseLimit = privateIndexSyncReadLimit(options);
  const limit = !canPersistPrivateIndexCursor && quickSync
    ? Math.max(baseLimit, PRIVATE_CHAIN_INDEX_READ_LIMIT)
    : baseLimit;
  let imported = 0;
  let skipped = 0;
  let scanComplete = true;
  let rateLimitError = null;
  let bodyHistoryError = null;
  let privateKeyOpenError = null;
  let blockedEntryId = null;
  const historyUnavailableEntries = [];
  let incompletePrivateStreamCount = 0;
  const privatePartGroups = new Map();
  const scannedPrivateEntryIds = new Set();
  const privateEntryCache = new Map();
  const cursorWrites = [];
  const headRepairWrites = [];
  const scanLog = [];
  const rememberPrivateScanLog = (entryId, status) => {
    const item = `${entryId.toString()}:${String(status ?? 'seen')}`;
    scanLog.push(item);
    if (scanLog.length > 14) scanLog.shift();
  };
  const readPrivateEntryCached = async (entryId) => {
    const entryIdKey = entryId.toString();
    if (privateEntryCache.has(entryIdKey)) return privateEntryCache.get(entryIdKey);
    const entry = await provider.getPrivateEntry(entryId, readOptions);
    privateEntryCache.set(entryIdKey, entry);
    return entry;
  };
  const scanPrivateEntryId = async (entryId, { source = 'index' } = {}) => {
    const entryIdKey = entryId.toString();
    if (scannedPrivateEntryIds.has(entryIdKey)) return { ok: true, entry: privateEntryCache.get(entryIdKey) ?? null };
    let entry = null;
    try {
      entry = await readPrivateEntryCached(entryId);
      // Terminally-capped body gap (surfaced 'undelivered'): the body is unrecoverable keyless, so SKIP
      // the heavy, 500-prone open+body tx-scan and keep only the cheap entry-metadata read the walk needs
      // for the previousLink. The manual "Sync messages" (source 'history-retry') path still re-attempts.
      if (source !== 'history-retry' && privateBodyHistoryEntryCapped(address, entryId)) {
        scannedPrivateEntryIds.add(entryIdKey);
        rememberPrivateScanLog(entryId, 'body-undelivered');
        skipped += 1;
        return { ok: true, entry };
      }
      if (entry.exists !== true) {
        scannedPrivateEntryIds.add(entryIdKey);
        rememberPrivateScanLog(entryId, 'empty');
        clearPrivateBodyHistoryUnavailable(address, entryId);
        clearPrivateStuckEntry(address, entryId);
        return { ok: true, entry };
      }
      entry = await resolvePrivateEntryBody(provider, entry, address, readOptions);
      privateEntryCache.set(entryIdKey, entry);
      scannedPrivateEntryIds.add(entryIdKey);
      privateScanUnknownErrorCounts.delete(`${address}:${entryIdKey}`);
      clearPrivateBodyHistoryUnavailable(address, entryId);
      const opened = await openPrivateCapsuleChainEntry(entry, localRecipientKeyPair, {
        now: Date.now(),
      });
      // Divert a self-addressed subscription snapshot BEFORE thread resolution, so it never spawns a "chat with
      // yourself" thread. Collected here; applied (restore) when the sync pass drains them.
      const prefsBytes = prefsBytesFromOpenedCapsule(opened);
      if (prefsBytes) {
        collectRestoredPrefsSnapshot(prefsBytes);
        rememberPrivateScanLog(entryId, 'prefs');
        clearPrivateStuckEntry(address, entryId);
        return { ok: true, entry };
      }
      const targetThread = await threadForChainCapsule(opened, entry);
      const partCount = Number(opened.payload?.partCount ?? 1);
      if (partCount > 1) {
        const key = privatePartKey(opened, entry);
        const existing = privatePartGroups.get(key) ?? {
          targetThread,
          parts: [],
          partCount,
          maxCreatedAtMs: 0,
          hasIndexedPart: false,
        };
        if (isPendingIdentityResolutionThread(existing.targetThread) && !isPendingIdentityResolutionThread(targetThread)) {
          existing.targetThread = targetThread;
        }
        existing.parts.push({ opened, entry, entryId, targetThread });
        existing.partCount = Math.max(existing.partCount, partCount);
        existing.hasIndexedPart = existing.hasIndexedPart || source !== 'history-retry';
        existing.maxCreatedAtMs = Math.max(existing.maxCreatedAtMs, privateEntryCreatedAtMs(entry) ?? 0);
        privatePartGroups.set(key, existing);
      } else {
        const added = await appendOpenedCapsuleMessage(
          opened,
          targetThread,
          privateChainMessageMeta({ ...entry, openedAs: isSelfOpenedCapsule(opened) ? 'self' : opened.openedAs }),
          entry,
        );
        if (added) imported += 1;
      }
      rememberPrivateScanLog(entryId, `open-${opened.openedAs ?? 'ok'}`);
      // Genuine success (the entry opened): it is no longer a stuck/undelivered
      // candidate. (Clear here, NOT before the open at the body-history clear, so a
      // resolve-ok-but-open-fails entry keeps accumulating its cross-session strike.)
      clearPrivateStuckEntry(address, entryId);
      return { ok: true, entry };
    } catch (error) {
      const message = String(error?.message ?? error);
      if (noteTonRpcRateLimit(error)) {
        rateLimitError = error;
        scanComplete = false;
        return { ok: false, entry };
      } else if (isBodyHistoryUnavailableError(error)) {
        scannedPrivateEntryIds.add(entryIdKey);
        const bodyStrikes = rememberPrivateBodyHistoryUnavailable(address, entry, entryId);
        if (bodyStrikes < PRIVATE_CHAIN_BODY_HISTORY_CROSS_SESSION_CAP) {
          // Still retrying: pin the cursor (the gap may be transient/recoverable) so it re-walks next cycle.
          rememberPrivateScanLog(entryId, 'body-gap');
          bodyHistoryError = error;
          blockedEntryId = entryId;
          historyUnavailableEntries.push({
            entryId: entryId.toString(),
            bodyHash: entryBodyHashHex(entry),
          });
        } else {
          // Terminal: surfaced 'undelivered' (folded into undeliveredCount). Do NOT set bodyHistoryError,
          // so it stops vetoing cursor/head-repair persistence; the next cycle the entry is early-skipped
          // (no heavy body tx-scan, the 500 source).
          rememberPrivateScanLog(entryId, 'body-undelivered');
        }
        skipped += 1;
        return { ok: true, entry };
      } else if (isTonRpcVerificationSoftReadError(error) || isTonRpcTransientError(error)) {
        // A transient RPC failure (verification-unavailable, 5xx, timeout, network,
        // disagreement) is NOT a permanently-unreadable capsule. Pin the cursor like
        // the rate-limit branch so this entry is re-walked on the next cycle once the
        // RPC recovers, instead of being dropped forever while the header still says
        // "Synced" (the historical /unavailable/i landmine). Genuine deterministic
        // crypto/structural mismatches still fall through to the unreadable branch.
        rememberPrivateScanLog(entryId, 'transient');
        scanComplete = false;
        return { ok: false, entry };
      } else if (isPrivateUnreadableCapsuleError(error)) {
        scannedPrivateEntryIds.add(entryIdKey);
        clearPrivateBodyHistoryUnavailable(address, entryId);
        privateKeyOpenError = error;
        blockedEntryId = entryId;
        rememberPrivateScanLog(entryId, 'unreadable');
        skipped += 1;
        globalThis.plathoLastPrivateSyncKeyOpenError = {
          entryId: entryId.toString(),
          localKeyId: localRecipientKeyPair?.keyId ?? null,
          type: 'unreadable_capsule',
          message,
          at: new Date().toISOString(),
        };
        return { ok: true, entry };
      } else {
        const failureKey = `${address}:${entryIdKey}`;
        const failures = (privateScanUnknownErrorCounts.get(failureKey) ?? 0) + 1;
        privateScanUnknownErrorCounts.set(failureKey, failures);
        // A persisted stuck entry (or ANY replay of one — source 'history-retry')
        // must NEVER return {ok:false}: the retryEntryIds replay loop breaks on the
        // first !ok, which would stall the whole pass + the cursor every session
        // (a worse loop than v419-v421). Mirror body-history's non-blocking
        // {ok:true} contract — bump the CROSS-session strike and session-skip at
        // once (one read, never scanComplete=false). A FRESH unknown error reached
        // by the index walk keeps the per-session 3-strikes ramp so a one-off blip
        // does not pin the page before the entry is persisted.
        const alreadyStuck = source === 'history-retry' || hasPrivateStuckEntry(address, entryId);
        if (alreadyStuck || failures >= PRIVATE_SCAN_UNKNOWN_ERROR_SKIP_AFTER) {
          const crossStrikes = rememberPrivateStuckEntry(address, entryId, message);
          scannedPrivateEntryIds.add(entryIdKey);
          rememberPrivateScanLog(entryId, crossStrikes >= PRIVATE_SCAN_UNKNOWN_ERROR_CROSS_SESSION_CAP ? 'undelivered' : 'error-skip');
          globalThis.plathoLastPrivateSyncBlockedEntry = {
            entryId: entryIdKey,
            message,
            failures,
            crossStrikes,
            at: new Date().toISOString(),
          };
          skipped += 1;
          return { ok: true, entry };
        }
        rememberPrivateScanLog(entryId, 'error');
        console.error(error);
        scanComplete = false;
        return { ok: false, entry };
      }
    }
  };

  let indexEntriesScanned = 0;
  let headRepairScanned = 0;
  let historyRetryScanned = 0;
  let catchUpRemaining = 0;
  let indexLimitReachedWithoutCursor = false;
  // Each scanned private entry runs a SYNCHRONOUS ML-KEM-768 decapsulate (the dominant CPU cost). On a
  // slow single-thread device (e.g. iPhone SE2) dozens of these back-to-back in this await chain starve
  // the main thread — tab clicks and renders queue behind the burst and the UI "freezes" for ~10s. Yield
  // to the event loop after EVERY entry so at most ONE decapsulate ever runs between event-loop turns:
  // input/paint get processed between decapsulations and the UI stays responsive. The sync is single-
  // flight (privateChainSyncPromise guards syncPrivateCapsulesFromChainOnce), so yielding mid-walk cannot
  // let a second pass interleave. Background sync takes marginally longer wall-clock; the UI never blocks.
  const cooperativeYield = () => new Promise((resolve) => setTimeout(resolve, 0));
  // TRUE while this role's walk has collected a multipart group that is still missing parts (unique partIndex
  // count below partCount). Group keys start with the openedAs role (privatePartKey), which matches the walked
  // index: the recipient index only yields recipient-opened parts and vice versa — so extending THIS role's walk
  // is exactly what can close them. history-retry-only groups (hasIndexedPart false) never trigger an extension.
  const rolePartGroupsIncomplete = (role) => {
    const ownRaw = ownRuntimeWalletRaw();
    for (const [key, group] of privatePartGroups) {
      // Self (Saved) groups live in BOTH index chains — either role's walk can close them, so the role filter
      // admits any group whose peer identity is the own wallet (v652; without this a straddled multipart self
      // message only closed on the recipient walk's later pass).
      const selfGroup = ownRaw ? key.includes(`:${ownRaw}:`) : false;
      if (!key.startsWith(`${role}:`) && !selfGroup) continue;
      if (group.hasIndexedPart !== true) continue;
      const unique = new Set();
      for (const part of group.parts) unique.add(Number(part.opened?.payload?.partIndex ?? 0));
      if (unique.size < group.partCount) return true;
    }
    return false;
  };

  const walkIndexedRole = async (role, latestHeadLink) => {
    const cursor = forceIndexRescan
      ? normalizePrivateChainIndexCursor(null)
      : readPrivateChainIndexCursor(address, role);
    const hasResume = cursor.resumeLink > 0n;
    const targetHeadLink = hasResume ? cursor.targetHeadLink : latestHeadLink;
    const stopLink = cursor.processedHeadLink;
    let currentLink = hasResume ? cursor.resumeLink : latestHeadLink;
    if (latestHeadLink === 0n) {
      if (cursor.processedHeadLink !== 0n || cursor.targetHeadLink !== 0n || cursor.resumeLink !== 0n) {
        cursorWrites.push({ role, cursor: normalizePrivateChainIndexCursor(null) });
      }
      return;
    }
    if (!hasResume && latestHeadLink === stopLink) return;
    let scannedForRole = 0;
    let nextLink = currentLink;
    while (currentLink > 0n && currentLink !== stopLink && scannedForRole < limit) {
      const entryId = privateIndexEntryIdFromLink(currentLink);
      if (entryId === null) {
        nextLink = 0n;
        break;
      }
      const result = await scanPrivateEntryId(entryId, { source: role });
      if (!result.ok) {
        scanComplete = false;
        return;
      }
      indexEntriesScanned += 1;
      scannedForRole += 1;
      await cooperativeYield();
      const previousLink = privateIndexPreviousLink(result.entry, role);
      nextLink = previousLink;
      if (previousLink === currentLink) {
        scanComplete = false;
        return;
      }
      currentLink = previousLink;
    }
    // Boundary-straddle extension (v649, the public comment loader's rule applied here): a window-limit exit in
    // the MIDDLE of a multipart group would either veto the cursor while fresh (head-restart livelock) or —
    // once stale — advance the cursor past the group's head-side parts forever. Keep walking (bounded) until
    // every group this role collected is closed; the exit branches below then see the EXTENDED position, so a
    // completed group flows into normal assembly and the catch-up cursor resumes below it.
    if (currentLink > 0n && currentLink !== stopLink && rolePartGroupsIncomplete(role)) {
      let extendedScans = 0;
      while (currentLink > 0n && currentLink !== stopLink
        && extendedScans < PRIVATE_CHAIN_STRADDLE_EXTENSION_SCAN_LIMIT
        && rolePartGroupsIncomplete(role)) {
        const entryId = privateIndexEntryIdFromLink(currentLink);
        if (entryId === null) {
          nextLink = 0n;
          break;
        }
        const result = await scanPrivateEntryId(entryId, { source: role });
        if (!result.ok) {
          scanComplete = false;
          return;
        }
        indexEntriesScanned += 1;
        extendedScans += 1;
        await cooperativeYield();
        const previousLink = privateIndexPreviousLink(result.entry, role);
        nextLink = previousLink;
        if (previousLink === currentLink) {
          scanComplete = false;
          return;
        }
        currentLink = previousLink;
      }
    }
    if (currentLink > 0n && currentLink !== stopLink) {
      if (canPersistPrivateIndexCursor) {
        catchUpRemaining += 1;
        cursorWrites.push({
          role,
          cursor: {
            processedHeadLink: stopLink,
            targetHeadLink,
            resumeLink: nextLink,
          },
        });
      } else {
        indexLimitReachedWithoutCursor = true;
      }
      return;
    }
    cursorWrites.push({
      role,
      cursor: {
        processedHeadLink: targetHeadLink,
        targetHeadLink: 0n,
        resumeLink: 0n,
      },
    });
  };

  const walkRecentIndexedRoleForRepair = async (role, latestHeadLink) => {
    const latestLink = privateIndexLinkValue(latestHeadLink);
    if (latestLink === 0n) return;
    if (readPrivateChainHeadRepairLink(address, role) === latestLink) return;
    let currentLink = latestLink;
    let scannedForRole = 0;
    while (currentLink > 0n && scannedForRole < PRIVATE_CHAIN_HEAD_REPAIR_SCAN_LIMIT) {
      const entryId = privateIndexEntryIdFromLink(currentLink);
      if (entryId === null) break;
      const result = await scanPrivateEntryId(entryId, { source: `${role}-head-repair` });
      if (!result.ok) {
        scanComplete = false;
        return;
      }
      headRepairScanned += 1;
      scannedForRole += 1;
      await cooperativeYield();
      const previousLink = privateIndexPreviousLink(result.entry, role);
      if (previousLink === currentLink) {
        scanComplete = false;
        return;
      }
      currentLink = previousLink;
    }
    headRepairWrites.push({ role, link: latestLink });
  };

  for (const entryId of retryEntryIds) {
    const result = await scanPrivateEntryId(entryId, { source: 'history-retry' });
    historyRetryScanned += 1;
    if (!result.ok) break;
    await cooperativeYield();
  }
  if (!rateLimitError && scanComplete) {
    await walkIndexedRole('recipient', recipientHead);
  }
  if (!rateLimitError && scanComplete) {
    await walkIndexedRole('sender', senderHead);
  }
  if (!rateLimitError && scanComplete) {
    await walkRecentIndexedRoleForRepair('recipient', recipientHead);
  }
  if (!rateLimitError && scanComplete) {
    await walkRecentIndexedRoleForRepair('sender', senderHead);
  }

  const incompletePrivatePartGroups = [...privatePartGroups.values()].filter((group) => {
    const uniqueParts = new Set();
    for (const part of group.parts) {
      uniqueParts.add(Number(part.opened?.payload?.partIndex ?? 0));
    }
    if (uniqueParts.size === group.partCount) return false;
    return group.hasIndexedPart === true;
  });

  for (const group of privatePartGroups.values()) {
    const uniqueParts = new Map();
    for (const part of group.parts) {
      uniqueParts.set(Number(part.opened?.payload?.partIndex ?? 0), part);
    }
    if (uniqueParts.size !== group.partCount) {
      if (bodyHistoryError) {
        for (const part of uniqueParts.values()) {
          rememberPrivateBodyHistoryUnavailable(address, part.entry, part.entryId);
        }
        continue;
      }
      const ageMs = group.maxCreatedAtMs > 0 ? Date.now() - group.maxCreatedAtMs : Number.POSITIVE_INFINITY;
      if (ageMs <= PRIVATE_PENDING_PUBLISH_STALE_AFTER_MS) {
        scanComplete = false;
      }
      incompletePrivateStreamCount += 1;
      skipped += uniqueParts.size;
      continue;
    }
    const ordered = [...uniqueParts.values()].sort((a, b) => {
      const entryA = privateEntryIdValue({ entry_id: a.entryId });
      const entryB = privateEntryIdValue({ entry_id: b.entryId });
      if (entryA === null || entryB === null || entryA === entryB) return 0;
      return entryA < entryB ? -1 : 1;
    });
    const firstEntry = ordered[0]?.entry;
    const firstOpened = ordered[0]?.opened;
    try {
      const added = await appendOpenedPrivatePartsMessage(
        ordered,
        group.targetThread,
        privateChainMessageMeta({ ...firstEntry, openedAs: isSelfOpenedCapsule(firstOpened) ? 'self' : firstOpened?.openedAs }, ordered.length),
      );
      pruneEmptyAnonymousPeerThreads();
      if (added) imported += 1;
    } catch (error) {
      skipped += ordered.length;
      globalThis.plathoLastPrivateSyncGroupError = {
        message: String(error?.message ?? error ?? 'private multipart blocked'),
        entryId: privateEntryIdText(firstEntry),
        partCount: ordered.length,
        at: new Date().toISOString(),
      };
      console.error(error);
    }
  }
  const publishConfirmations = await confirmPendingPrivatePublishMessagesFromEntries(
    [...privateEntryCache.values()],
    'private_sync_index',
  );
  const hasFreshPartial = incompletePrivatePartGroups.some((group) => {
    const ageMs = group.maxCreatedAtMs > 0 ? Date.now() - group.maxCreatedAtMs : Number.POSITIVE_INFINITY;
    return ageMs <= PRIVATE_PENDING_PUBLISH_STALE_AFTER_MS;
  });
  if (canPersistPrivateIndexCursor && !rateLimitError && scanComplete && !hasFreshPartial && bodyHistoryError === null) {
    for (const write of cursorWrites) writePrivateChainIndexCursor(address, write.role, write.cursor);
    for (const write of headRepairWrites) writePrivateChainHeadRepairLink(address, write.role, write.link);
  } else if (canPersistPrivateIndexCursor && !rateLimitError && !hasFreshPartial && catchUpRemaining > 0 && bodyHistoryError === null) {
    for (const write of cursorWrites) writePrivateChainIndexCursor(address, write.role, write.cursor);
    for (const write of headRepairWrites) writePrivateChainHeadRepairLink(address, write.role, write.link);
  }
  // Entries promoted past the cross-session strike cap (#9): a permanently surfaced
  // "undelivered" gap. Read from the STORE (not the per-run skipped counter) so it
  // survives reload, when skipped resets to 0 while the cursor sits past the entry —
  // exactly the false "Synced" this guards against.
  const undeliveredCount = privateStuckEntrySurfacedCount(address) + privateBodyHistorySurfacedCount(address);
  const reason = bodyHistoryError
    ? 'body_history_unavailable'
    : privateKeyOpenError
      ? 'private_key_open_failed'
      : hasFreshPartial
        ? 'partial_stream_pending'
        : indexLimitReachedWithoutCursor
          ? 'index_limit_without_cursor'
          : undeliveredCount > 0
            ? 'private_entry_undelivered'
            : (catchUpRemaining > 0 ? 'catch_up_pending' : null);
  const fullScanComplete = scanComplete
    && catchUpRemaining === 0
    && !hasFreshPartial
    && !indexLimitReachedWithoutCursor;
  const recipientCursor = readPrivateChainIndexCursor(address, 'recipient');
  const senderCursor = readPrivateChainIndexCursor(address, 'sender');
  globalThis.plathoLastPrivateSync = {
    capsuleHub: address,
    keyId: localRecipientKeyPair?.keyId ?? null,
    indexKeyId: keyIdIndex.toString(),
    recipientHead: recipientHead.toString(),
    senderHead: senderHead.toString(),
    recipientCursor: privateIndexCursorDebug(recipientCursor),
    senderCursor: privateIndexCursorDebug(senderCursor),
    cursorPersistence,
    imported,
    skipped,
    scanComplete: fullScanComplete,
    pageComplete: scanComplete,
    indexEntriesScanned,
    headRepairScanned,
    historyRetryScanned,
    publishConfirmations,
    readLimit: limit,
    forceIndexRescan,
    indexReadFallback,
    rateLimited: rateLimitError !== null,
    bodyHistoryUnavailable: bodyHistoryError !== null,
    privateKeyOpenFailed: privateKeyOpenError !== null,
    blockedEntryId: blockedEntryId?.toString?.() ?? null,
    historyUnavailableCount: historyUnavailableEntries.length,
    historyUnavailableEntries,
    incompletePrivateStreamCount,
    undeliveredCount,
    catchUpRemaining,
    indexLimitReachedWithoutCursor,
    reason,
    mode: quickSync ? 'auto' : 'recovery',
    scanLog,
  };
  const result = privateSyncResult({
    imported,
    skipped,
    scanComplete: fullScanComplete,
    reason,
    blockedEntryId: blockedEntryId?.toString?.() ?? null,
    historyUnavailableCount: historyUnavailableEntries.length,
    historyUnavailableEntries,
    incompletePrivateStreamCount,
    undeliveredCount,
    catchUpRemaining,
    indexLimitReachedWithoutCursor,
    indexReadFallback,
    rateLimited: rateLimitError !== null,
    ok: rateLimitError === null,
  });
  if (imported > 0) {
    refreshMessagingControls();
    renderThreads();
    renderConversation();
    resumePendingPrivatePublishConfirmations();
  resumePendingPublicPublishConfirmations();
    resumePendingPrivateSendRetries();
    return result;
  }
  if (!scanComplete) {
    refreshMessagingControls();
    resumePendingPrivateSendRetries();
    if (rateLimitError) throw rateLimitError;
    return result;
  }
  refreshMessagingControls();
  resumePendingPrivatePublishConfirmations();
  resumePendingPublicPublishConfirmations();
  resumePendingPrivateSendRetries();
  return result;
}

async function syncPrivateCapsulesFromChainOnce(options = {}) {
  if (privateChainSyncPromise) return privateChainSyncPromise;
  privateChainSyncPromise = syncPrivateCapsulesFromChain(options);
  try {
    const result = await privateChainSyncPromise;
    // Apply any subscription snapshot diverted from this pass (restore on a fresh device / cleared data).
    try { drainRestoredPrefsSnapshots(); } catch (error) { console.error(error); }
    return result;
  } finally {
    privateChainSyncPromise = null;
  }
}

function isChatsViewActive() {
  return appShell?.dataset?.view === 'chats';
}

function isPublicViewActive() {
  return appShell?.dataset?.view === 'public';
}

function clearMessageAutoSyncTimer() {
  if (messageAutoSyncTimer) {
    window.clearTimeout(messageAutoSyncTimer);
    messageAutoSyncTimer = null;
  }
  messageAutoSyncAt = 0;
  messageAutoSyncPhase = 'idle';
  clearMessageAutoSyncCountdownTimer();
  refreshConversationSubtitle();
}

function privateOutboundWorkActive() {
  return privateOutboundWorkDepth > 0;
}

// True while a send is actively holding the auth key (the vault send-lock is held for the sign+broadcast
// loop of BOTH private and public sends, or a private re-sign/recovery job is mid-flight). Confirmation is
// keyless and intentionally NOT counted here, so the wallet may lock once broadcasting is done.
function vaultSendNeedsKeyNow() {
  const needsKey = vaultPublishSendWaiters > 0 || privateOutboundWorkActive();
  if (!needsKey) vaultSendInFlightUntil = 0;
  return needsKey;
}

// Whether a background auto-lock should be DEFERRED right now because a send still needs the key. The
// grace deadline is set ONCE at the first defer and is never refreshed by later background events, so a
// wedged send can defer the lock by at most SEND_LOCK_MAX_GRACE_MS; after that it locks normally and the
// existing fail-closed re-sign path governs resumption.
function shouldDeferLockForActiveSend() {
  if (!vaultSendNeedsKeyNow()) return false;
  const now = Date.now();
  if (vaultSendInFlightUntil === 0) vaultSendInFlightUntil = now + SEND_LOCK_MAX_GRACE_MS;
  return now < vaultSendInFlightUntil;
}

function beginPrivateOutboundWork() {
  privateOutboundWorkDepth += 1;
  return () => {
    privateOutboundWorkDepth = Math.max(0, privateOutboundWorkDepth - 1);
    if (privateOutboundWorkDepth === 0 && !messageAutoSyncTimer) {
      scheduleMessageAutoSync(PRIVATE_OUTBOUND_SYNC_PAUSE_MS);
    }
  };
}

async function enterVaultPublishSendLock() {
  vaultPublishSendWaiters += 1;
  const previous = vaultPublishSendLock;
  let releaseLock = () => {};
  vaultPublishSendLock = new Promise((resolve) => {
    releaseLock = resolve;
  });
  await previous.catch(() => {});
  vaultPublishSendWaiters = Math.max(0, vaultPublishSendWaiters - 1);
  let released = false;
  return {
    hasWaiters: () => vaultPublishSendWaiters > 0,
    release() {
      if (released) return;
      released = true;
      releaseLock();
    },
  };
}

async function awaitVaultPublishNonceBarrier() {
  while (pendingVaultPublishNonceBarrier) {
    const barrier = pendingVaultPublishNonceBarrier;
    await barrier.catch(() => {});
    if (pendingVaultPublishNonceBarrier === barrier) pendingVaultPublishNonceBarrier = null;
  }
}

function installVaultPublishNonceBarrier(task) {
  const barrier = Promise.resolve(task).catch(() => {});
  pendingVaultPublishNonceBarrier = barrier;
  barrier.then(() => {
    if (pendingVaultPublishNonceBarrier === barrier) pendingVaultPublishNonceBarrier = null;
  });
  return barrier;
}

function vaultPublishNonceFloor(owner) {
  const key = rawWalletAddress(owner) ?? String(owner ?? '');
  return vaultPublishNonceFloorByOwner.get(key) ?? 0n;
}

function raiseVaultPublishNonceFloor(owner, nonce) {
  if (nonce === null || nonce === undefined) return;
  const key = rawWalletAddress(owner) ?? String(owner ?? '');
  const current = vaultPublishNonceFloorByOwner.get(key) ?? 0n;
  if (nonce > current) vaultPublishNonceFloorByOwner.set(key, nonce);
}

// The public feed shares the unified background sync loop but at a gentler cadence than the private fast-idle
// tier (it is less time-sensitive, and keyless reads share one toncenter budget).
const PUBLIC_BACKGROUND_SYNC_MS = 30_000;
let lastPublicBackgroundSyncAt = 0;
// Unified background sync loop. Runs on EVERY in-app tab — only document.hidden (the whole app backgrounded)
// suspends it — ticking the public feed + (with a wallet) private messages, so switching tabs is instant:
// the data is already fresh, setView no longer re-triggers a sync. The loop yields the toncenter budget to an
// in-flight send/confirm. The funds-critical send/confirm/nonce loops are SEPARATE and untouched.
function scheduleMessageAutoSync(delayMs = MESSAGE_AUTO_SYNC_MS) {
  clearMessageAutoSyncTimer();
  if (document.hidden) return;
  const transport = globalThis.plathoTonRpcTransport;
  const degradedTransport = typeof transport?.isDegraded === 'function' && transport.isDegraded();
  const requestedDelayMs = Math.max(1_000, Number(delayMs) || MESSAGE_AUTO_SYNC_MS);
  const effectiveDelayMs = degradedTransport ? Math.max(requestedDelayMs, MESSAGE_AUTO_SYNC_DEGRADED_MS) : requestedDelayMs;
  messageAutoSyncPhase = messageAutoSyncLastErrorLabel ? 'delayed' : (messageAutoSyncLastResult ? 'synced' : 'scheduled');
  messageAutoSyncAt = Date.now() + effectiveDelayMs;
  scheduleMessageAutoSyncCountdownUi();
  messageAutoSyncTimer = window.setTimeout(async () => {
    messageAutoSyncTimer = null;
    messageAutoSyncAt = 0;
    let nextSyncDelayMs = MESSAGE_AUTO_SYNC_MS;
    // Pause background sync while an outbound send OR its publish-confirmation is in flight. The broadcast
    // is covered by privateOutboundWorkActive(), but the CONFIRM phase (runPrivatePublishConfirmationRetry:
    // nonce poll + CapsuleHub receipt read + the retry ladder, tens of seconds) is intentionally keyless and
    // NOT counted there — so without this the index-walk sync resumes ~5s after broadcast and competes with
    // the confirm reads for the keyless ~1 rps budget, tipping over the toncenter per-IP limit -> 429 storm
    // and a stalled image (the owner's "image sent during sync" case). Yielding the budget to the in-flight
    // confirm lets it settle fast; sync resumes once privatePublishConfirmJobs drains. (Wallet-lock logic is
    // untouched: confirmation stays keyless / not key-holding — this only gates the background read pump.)
    // Also pause while ACCOUNT ACTIVATION is in flight: activation fires its own vault read burst (the poll +
    // status/key-record reads), and on iOS WebKit the background sync reads running concurrently with it is
    // the run-loop-stall pattern (v509) that froze the activation page. plathoAccountActivationPending clears
    // the moment the account is active, so this only yields for the activation window.
    if (privateOutboundWorkActive() || privatePublishConfirmJobs.size > 0 || plathoAccountActivationPending) {
      scheduleMessageAutoSync(PRIVATE_OUTBOUND_SYNC_PAUSE_MS);
      return;
    }
    // PUBLIC feed — synced in the background (every ~30s) regardless of the active tab AND regardless of
    // wallet, so switching to Public is instant. Cheap cursor read; best effort.
    if (Date.now() - lastPublicBackgroundSyncAt >= PUBLIC_BACKGROUND_SYNC_MS) {
      lastPublicBackgroundSyncAt = Date.now();
      try { await syncPublicChannels(); } catch (error) { noteTonRpcRateLimit(error); }
    }
    // PRIVATE — only with a wallet + messaging keys; otherwise keep the loop alive for the public sync above.
    if (!plathoWallet || !localRecipientKeyPair) {
      scheduleMessageAutoSync(nextSyncDelayMs);
      return;
    }
    beginMessageSyncUi();
    try {
      const result = await syncPrivateCapsulesFromChainOnce({ mode: 'auto' });
      completeMessageSyncUi(result);
      if ((result?.scanComplete === false && result?.reason !== 'index_limit_without_cursor') || result?.reason === 'catch_up_pending') {
        // Fast follow-up only while the catch-up actually makes progress;
        // a stalled walk (same state every pass) backs off exponentially so
        // it cannot melt the RPC budget with a 2-second resync loop.
        // A cycle whose ONLY delta is body-gap skips (keyless cannot fetch those bodies) is NOT real
        // progress: counting it as progress pins the fast 8s cadence and re-walks the same unfetchable
        // bodies every cycle, keeping the RPC limiter perpetually hot (and starving sends). Treat a
        // body-gap-only cycle as a stall so the backoff ramps toward 60s; genuine imports or any
        // non-body-gap skip still fast-follow.
        const onlyBodyGapSkips = !privateSyncImported(result)
          && result?.reason === 'body_history_unavailable';
        const progressed = privateSyncImported(result)
          || (Number(result?.skipped ?? 0) > 0 && !onlyBodyGapSkips);
        messageAutoSyncStallStreak = progressed ? 0 : messageAutoSyncStallStreak + 1;
        // Floor the fast follow-up at 8s. The old 2s minimum re-fired a fresh sync pass (dozens of
        // synchronous ML-KEM decapsulates) every 2 seconds while a catch-up progressed — fine on a fast
        // CPU, but on a slow single-thread device it kept the main thread perpetually churning and never
        // let it settle. 8s lets each (now-cooperative) pass finish and the device breathe between them;
        // catch-up still drains, just paced.
        nextSyncDelayMs = Math.max(8_000, Math.min(2_000 * 2 ** Math.min(messageAutoSyncStallStreak, 5), MESSAGE_AUTO_SYNC_MS));
      } else {
        // Fully synced ("nothing new"): poll again on the fast foreground-idle tier instead of the 60s cap,
        // so a freshly-arrived message is picked up in ~12s. The pass is cheap (2 cursor-at-head reads) and
        // the degraded floor + send-pause + 429-backoff below still override this when they apply.
        messageAutoSyncStallStreak = 0;
        nextSyncDelayMs = MESSAGE_AUTO_SYNC_IDLE_MS;
      }
      if (privateSyncImported(result)) {
        setMessageSyncStatus(t('sync.newMessages'), 'result');
      } else if (messageSyncStatusState() === 'syncing') {
        setMessageSyncStatus(privateSyncStatusText(result), privateSyncStatusState(result));
      }
    } catch (error) {
      const rateLimited = noteTonRpcRateLimit(error);
      const label = rateLimited ? t('sync.syncDelayed') : t('sync.syncFailed');
      failMessageSyncUi(label);
      setMessageSyncStatus(rateLimited ? t('sync.delayedShort') : t('sync.failedShort'), rateLimited ? 'delayed' : 'failed');
      if (!rateLimited) console.error(error);
      if (rateLimited) nextSyncDelayMs = tonRpcLimitBackoffMs(error);
    } finally {
      scheduleMessageAutoSync(nextSyncDelayMs);
    }
  }, effectiveDelayMs);
}

async function bootReplayStore() {
  if (!plathoWallet?.address) {
    localReplayStore = createMemoryReplayStore();
    setText(replayStoreStatus, hasStoredPlathoWalletRecord() ? t('common.unlockRequired') : t('vault.storeMemory'));
    return;
  }
  try {
    localReplayStore = await createIndexedDbReplayStore({ dbName: currentReplayDbName() });
    setText(replayStoreStatus, t('vault.storeDeviceDb'));
  } catch {
    localReplayStore = createMemoryReplayStore();
    setText(replayStoreStatus, t('vault.storeMemory'));
  }
}

function historyStatusLabel() {
  if (!encryptedMessageStore) return t('vault.historyOff');
  const limit = encryptedMessageStore.maxRecords ? t('vault.historyLimitLast', { count: encryptedMessageStore.maxRecords }) : t('vault.historyLimitLocal');
  return encryptedMessageStore.persistent === false
    ? t('vault.historyMemoryCache', { limit })
    : t('vault.historyLocalCache', { limit });
}

// Drop the pre-signed variant BoCs (~16 × ~47KB per part) before persisting: they are in-memory retry material
// for THIS session's re-broadcast rotation, not needed to restore a message (a cross-reload resume falls back
// to the single externalBoc). Persisting them would re-encrypt+write ~1.5MB on EVERY status notify during a
// send — a latency regression that would defeat the whole point of the variants.
function publishStateForHistory(publishState) {
  if (!publishState || typeof publishState !== 'object' || !Array.isArray(publishState.parts)) {
    return publishState ?? null;
  }
  return {
    ...publishState,
    parts: publishState.parts.map((part) => {
      if (part && part.externalBocVariants) {
        const { externalBocVariants, ...rest } = part;
        return rest;
      }
      return part;
    }),
  };
}

function serializeMessageForHistory(message) {
  return {
    type: message.type,
    text: message.text,
    meta: message.meta,
    createdAt: message.createdAt ?? null,
    createdAtMs: messageCreatedAtMs(message),
    chainEntryId: message.chainEntryId ?? null,
    chainLastEntryId: message.chainLastEntryId ?? null,
    localCreatedAtMs: message.localCreatedAtMs ?? null,
    localHistoryCreatedAt: message.localHistoryCreatedAt ?? null,
    blocks: messageBlocksForHistory(message),
    capsule: message.capsule ?? null,
    capsules: message.capsules ?? null,
    publishState: publishStateForHistory(message.publishState),
    recipientWallet: message.recipientWallet ?? null,
    vaultCreateIntent: safeJsonClone(message.vaultCreateIntent) ?? null,
    vaultPublish: safeJsonClone(message.vaultPublish) ?? null,
    vaultCancelIntent: safeJsonClone(message.vaultCancelIntent) ?? null,
    // Minimal privateDraft persistence (v646, +share v766): ONLY the reply quote + share snapshot. A post-reload
    // capsule REBUILD (the rare capsule-less failure path) must reproduce the same reply/share blocks;
    // text/attachments intentionally stay unpersisted (bytes) — the rebuild falls back to message.text as before.
    privateDraft: (message.privateDraft?.replyDraft || message.privateDraft?.shareDraft)
      ? {
        replyDraft: safeJsonClone(message.privateDraft.replyDraft) ?? null,
        shareDraft: safeJsonClone(message.privateDraft.shareDraft) ?? null,
      }
      : null,
    privateSendRetryAttempt: Number(message.privateSendRetryAttempt ?? 0) || 0,
    privateSendRetryStopped: message.privateSendRetryStopped === true,
    privateSendRetryStoppedAt: message.privateSendRetryStoppedAt ?? null,
    privatePublishConfirmAttempt: Number(message.privatePublishConfirmAttempt ?? 0) || 0,
    privatePublishConfirmStopped: message.privatePublishConfirmStopped === true,
    privatePublishConfirmStoppedAt: message.privatePublishConfirmStoppedAt ?? null,
    // clean-17 CONV delivery confirm: the driver's setTimeout chain dies on reload, but these DO survive it, so
    // rearmConvDeliveryConfirms can resume verifying an optimistic-green send (and the persisted boc revives the
    // idempotent re-broadcast). Without persistence a bounced green reloaded before the 8-min terminal froze green
    // forever = silent loss. convDirectSend is JSON-safe (commits are hex strings). [confirm review: persistence]
    convDirectSend: safeJsonClone(message.convDirectSend) ?? null,
    convDelivery: message.convDelivery ?? null,
    attachment: message.attachment ?? null,
    profileVersion: message.profileVersion ?? 0,
    avatarHash: message.avatarHash ?? zeroAvatarHashHex(),
  };
}

function safeJsonClone(value) {
  try {
    return JSON.parse(JSON.stringify(value, (_key, item) => (
      typeof item === 'bigint' ? item.toString() : item
    )));
  } catch {
    return null;
  }
}

function safeDiagnosticsJson(value) {
  return JSON.stringify(value ?? null, (_key, item) => (
    typeof item === 'bigint' ? item.toString() : item
  ), 2);
}

globalThis.plathoProfileAvatarPublishDiagnosticsJson = () => safeDiagnosticsJson(
  globalThis.plathoLastProfileAvatarPublishDiagnostics,
);

function serializeThreadForHistory(thread) {
  if (!thread?.id) return null;
  return safeJsonClone({
    id: thread.id,
    name: thread.name ?? null,
    subtitle: thread.subtitle ?? null,
    avatar: thread.avatar ?? null,
    state: thread.state ?? null,
    preview: thread.preview ?? null,
    identity: thread.identity ?? null,
    displayIdentity: thread.displayIdentity ?? null,
    identityVariants: threadIdentityVariants(thread),
    localLabel: thread.localLabel ?? null,
    avatarImageUrl: thread.avatarImageUrl ?? null,
  });
}

function peerLabelFromThreadId(threadId, message = null) {
  const idText = String(threadId ?? '');
  if (idText.startsWith('peer:')) {
    try {
      const decoded = decodeURIComponent(idText.slice(5));
      return `Anonymous ${shortPeerId(decoded)}`;
    } catch {
      return 'Anonymous';
    }
  }
  const senderKeyId = message?.capsule?.header0?.senderKeyId;
  if (senderKeyId) return `Anonymous ${shortKeyId(senderKeyId)}`;
  return 'Anonymous';
}

function applyHistoryThreadSnapshot(thread, snapshot) {
  if (!thread || !snapshot || typeof snapshot !== 'object') return thread;
  const variants = normalizeIdentityVariants([
    snapshot.identity,
    snapshot.displayIdentity,
    ...(snapshot.identityVariants ?? []),
  ]);
  if (variants.length > 0) {
    thread.identityVariants = normalizeIdentityVariants([
      ...(thread.identityVariants ?? []),
      ...variants,
    ]);
    thread.identity = thread.identity ?? preferredInboundIdentity(thread.identityVariants);
  }
  if (!thread.localLabel && snapshot.name && snapshot.name !== 'Imported') thread.name = snapshot.name;
  if (snapshot.subtitle && snapshot.subtitle !== 'local encrypted history') thread.subtitle = snapshot.subtitle;
  if (snapshot.avatar) thread.avatar = snapshot.avatar;
  if (snapshot.avatarImageUrl) thread.avatarImageUrl = snapshot.avatarImageUrl;
  if (snapshot.displayIdentity) thread.displayIdentity = snapshot.displayIdentity;
  if (snapshot.localLabel) thread.localLabel = snapshot.localLabel;
  // A snapshot may carry a stale display preference (e.g. a Public-tab choice was made while this
  // dialog was not loaded, so it never reached this thread's persisted snapshot). Re-arm the one-time
  // contact-store hydration so the next render reconciles against the authoritative shared store.
  thread.contactDisplaySynced = false;
  return thread;
}

function ensureHistoryThread(threadId, snapshot = null, message = null) {
  let thread = threads.find((item) => item.id === threadId);
  if (thread) return applyHistoryThreadSnapshot(thread, snapshot);
  const restoredName = snapshot?.name && snapshot.name !== 'Imported'
    ? snapshot.name
    : peerLabelFromThreadId(threadId, message);
  thread = {
    id: threadId,
    name: restoredName,
    subtitle: snapshot?.subtitle && snapshot.subtitle !== 'local encrypted history' ? snapshot.subtitle : 'Encrypted history',
    avatar: snapshot?.avatar ?? 'P',
    preview: 'encrypted local history',
    state: 'sealed',
    time: 'local',
    messages: [],
  };
  applyHistoryThreadSnapshot(thread, snapshot);
  threads.push(thread);
  return thread;
}

async function persistMessageToEncryptedHistory(thread, message) {
  if (!encryptedMessageStore || message.localHistoryId) return null;
  return writeMessageToEncryptedHistory(thread, message);
}

async function writeMessageToEncryptedHistory(thread, message) {
  if (!encryptedMessageStore || !thread || !message) return null;
  ensureMessageOrderFields(message);
  try {
    const createdAt = messageCreatedAtMs(message) ?? Date.now();
    const stored = await encryptedMessageStore.putMessage({
      id: message.localHistoryId ?? undefined,
      threadId: thread.id,
      thread: serializeThreadForHistory(thread),
      message: serializeMessageForHistory(message),
      createdAt: message.localHistoryCreatedAt ?? createdAt,
    });
    message.localHistoryId = stored.id;
    message.localHistoryCreatedAt = stored.createdAt;
    setText(localStateLabel, historyStatusLabel());
    return stored;
  } catch (error) {
    setText(localStateLabel, t('sync.historyBlocked'));
    console.error(error);
    return null;
  }
}

// One-time self-heal for devices poisoned BEFORE the cross-wallet identity-bleed fix. The old thread-merge in
// relocateExistingCapsuleMessage grafted wallet variants ACROSS dialogs, so a peer dialog could carry the OWN
// wallet variant (isSavedMessagesThread flips true → it renders as "My notes", and its avatar bleeds onto the own
// "You" channel), and the Saved thread could symmetrically carry a PEER wallet/username variant (that peer's
// incoming messages then route INTO "My notes"). Those variants persist inside the encrypted-history thread
// snapshots and applyHistoryThreadSnapshot re-adds them ADDITIVELY on every load — so the live guards alone can
// never clean an already-poisoned device. Strip them after each history restore: the OWN wallet variant may live
// ONLY on the real Saved thread (identified by its CREATION id, dm:wallet_address:<own> — identity variants are
// exactly what got poisoned, so they cannot be trusted for this), and the Saved thread may carry NOTHING but the
// own wallet (a dropped own .ath re-latches on next use). Rewrite the affected snapshots + clear a leaked
// own-wallet "Display as" entry. Idempotent no-op on a clean device.
// Chain entry ids of messages found mis-filed inside "My notes" by healCrossWalletIdentityBleed — replayed through
// the next private scan (as a history-retry source) so they are re-opened, re-routed to the true sender's dialog,
// and relocated out of Saved. Consumed + cleared by the scan; survives only until then.
let pendingSavedRelocateEntryIds = new Set();
// Requeue bound: the heal now also runs on EVERY sync tick, so a stuck message whose entry can never be re-opened
// (unreadable body, sender permanently unresolvable) must not cost an RPC re-read on every tick forever. Cap the
// requeues per entry per SESSION; a successful relocation removes the message from Saved so it stops being queued
// naturally, and the next boot (new session) retries a capped-out entry afresh.
const savedRelocateRequeueCounts = new Map();
const SAVED_RELOCATE_MAX_REQUEUES_PER_SESSION = 3;
function queueSavedRelocateEntryId(entryId) {
  const key = String(entryId);
  const count = savedRelocateRequeueCounts.get(key) ?? 0;
  if (count >= SAVED_RELOCATE_MAX_REQUEUES_PER_SESSION) return;
  savedRelocateRequeueCounts.set(key, count + 1);
  pendingSavedRelocateEntryIds.add(key);
}

// options.requeueAnonymous: also re-queue messages stuck in an ANONYMOUS / pending peer thread (a received capsule
//   whose sender could not be resolved landed there — the flip side of the own-guard keeping it OUT of Saved). Once
//   the sender's signing key resolves on a healthy sync, the re-opened message routes to the real wallet dialog and
//   relocates. Bounded to the BOOT heal only (not every auto-sync) so a genuinely-anonymous sender is not re-scanned
//   on every tick. options.clearOwnContactDisplay: run the (persisting) own-wallet contact-display cleanup — also
//   boot-only; the per-tick auto-sync heal skips it to avoid a storage write every sync.
function healCrossWalletIdentityBleed({ requeueAnonymous = false, clearOwnContactDisplay = false } = {}) {
  const own = ownRuntimeWalletRaw();
  if (!own) return false;
  let healed = false;
  for (const thread of threads) {
    if (thread.publicChannelId) continue;
    if (requeueAnonymous && (isAnonymousPeerThread(thread) || thread.pendingIdentityResolution === true)) {
      // Peer message(s) stuck without a resolved sender — re-queue for a re-route once resolution recovers.
      for (const message of thread.messages ?? []) {
        if (message?.chainEntryId !== undefined && message?.chainEntryId !== null) {
          queueSavedRelocateEntryId(message.chainEntryId);
        }
      }
      continue;
    }
    if (isRealSavedThread(thread)) {
      // The REAL Saved/self dialog wears NOTHING but the own wallet — restore it to canonical (drops any foreign
      // wallet AND any username/DNS graft AND a named displayIdentity, in one IDEMPOTENT step). Any named variant on
      // "My notes" is a graft from the add-contact bug era (the owner literally saw peer usernames in Saved's
      // "Display as" list); since routing matches ANY variant kind, one stale grafted username kept attracting that
      // peer's messages into Saved forever — even after the sender resolved correctly (v728 iPhone dump). Idempotent:
      // no persist/re-encrypt on a tick when Saved is already clean (the adversarial-review per-tick persist-storm).
      // Addressing the OWN .ath still opens Saved fine: it resolves to the own WALLET first and matches by wallet.
      if (purgeNamedIdentityFromSavedThread(thread)) { persistThreadDisplayPreference(thread); healed = true; }
      // Queue every MISFILED message's chain entry for relocation — the next private scan re-opens each, routes it to
      // its true dialog, and relocates it out of Saved. Once moved they leave Saved, so this converges; the id set
      // self-dedups. Two misfiling shapes both land here (the earlier heal handled only the first, which is why an
      // iPhone whose stuck messages were the user's OWN sends never healed):
      //  - 'in'  message inside "My notes": ALWAYS misfiled (a genuine self-note is stored 'out', isSelfOpenedCapsule
      //    -> isOutgoing). Queue unconditionally.
      //  - 'out' message whose ORIGIN meta is 'published' (privateChainMessageMeta returns 'published' ONLY for an
      //    own capsule addressed to a PEER, openedAs 'sender'; a genuine self-note is 'saved'). An own->peer send has
      //    NO business in Saved -> it is a misfiled send (the "I write to glasnost but it lands in my notes" report).
      //    The re-open uses the sender-recovery lane -> threadForOpenedSenderCapsule routes it to the recipient's
      //    dialog. meta 'saved' self-notes are never matched, so this never perpetually re-scans genuine notes.
      for (const message of thread.messages ?? []) {
        if (message?.chainEntryId === undefined || message?.chainEntryId === null) continue;
        const misfiledIncoming = message.type === 'in';
        const misfiledOwnSend = message.type === 'out' && /publish/i.test(String(message.meta ?? ''));
        if (misfiledIncoming || misfiledOwnSend) {
          queueSavedRelocateEntryId(message.chainEntryId);
        }
      }
    } else if (stripWalletVariantFromThread(thread, own)) {
      // A peer dialog wrongly carrying the OWN wallet variant.
      persistThreadDisplayPreference(thread);
      healed = true;
    }
  }
  // Clear a leaked own-wallet contact-display entry (Fix D clears it on any own write, but a poisoned device may
  // never write again — clear it here explicitly). Boot-only: it is a storage write, skipped on the per-tick sync.
  if (clearOwnContactDisplay) writeContactDisplayPreference(own, null);
  return healed;
}

async function restoreEncryptedMessageHistory() {
  if (!encryptedMessageStore) return;
  try {
    const result = encryptedMessageStore.listMessagesDetailed
      ? await encryptedMessageStore.listMessagesDetailed()
      : { messages: await encryptedMessageStore.listMessages(), failed: [] };
    const restored = result.messages ?? [];
    const failed = result.failed ?? [];
    let changed = false;
    for (const item of restored) {
      const thread = ensureHistoryThread(item.threadId, item.thread, item.message);
      if (thread.messages.some((message) => message.localHistoryId === item.id)) continue;
      const message = {
        ...item.message,
        localHistoryId: item.id,
        localHistoryCreatedAt: item.createdAt,
      };
      ensureMessageOrderFields(message, item.createdAt);
      insertThreadMessage(thread, message);
      refreshThreadAfterMessageChange(thread);
      // Incoming only — an outgoing ('out') restored message carries the OWN avatar pointer, which the by-hash
      // avatar cache would resolve to the user's own avatar on the counterparty's dialog header.
      if (message.type !== 'out') {
        hydrateThreadAvatarFromPointer(
          thread,
          ownerWalletFromThread(thread),
          avatarPointerFromFields(message.profileVersion, message.avatarHash),
        ).catch((error) => console.error(error));
      }
        changed = true;
    }
    // Heal AFTER the snapshots have been applied (they are what re-adds the poisoned variants). Boot run: also
    // re-queue anonymous/pending-stuck peer messages and do the one-off own-contact-display cleanup.
    if (healCrossWalletIdentityBleed({ requeueAnonymous: true, clearOwnContactDisplay: true })) changed = true;
    globalThis.plathoLastEncryptedHistoryRestore = {
      restored: restored.length,
      failed: failed.length,
      failedRecords: failed,
      dbName: currentMessageHistoryDbName(),
      walletAddress: plathoWallet?.address ?? null,
    };
    const restoredLabel = restored.length > 0 ? t('sync.historyRestoredCount', { label: historyStatusLabel(), count: restored.length }) : historyStatusLabel();
    setText(localStateLabel, failed.length > 0 ? t('sync.historyRestoredBlocked', { restored: restoredLabel, count: failed.length }) : restoredLabel);
    if (changed) {
      renderThreads();
      renderConversation();
      resumePendingPrivatePublishConfirmations();
  resumePendingPublicPublishConfirmations();
      resumePendingPrivateSendRetries();
    }
    // Re-arm CONV delivery confirms for sends still unresolved when the page reloaded — the setTimeout chain does not
    // survive a reload, but the persisted convDirectSend (commits + shard address) does. Bounded by the max age inside.
    rearmConvDeliveryConfirms();
  } catch (error) {
    setText(localStateLabel, t('sync.historyBlocked'));
    console.error(error);
  }
}


async function bootEncryptedMessageHistory() {
  if (!plathoWallet?.address) {
    encryptedMessageStore = null;
    setText(localStateLabel, hasStoredPlathoWalletRecord() ? t('sync.historyLocked') : t('sync.historyOff'));
    return;
  }
  try {
    encryptedMessageStore = await createIndexedDbEncryptedMessageHistoryStore({ dbName: currentMessageHistoryDbName() });
  } catch (indexedDbError) {
    try {
      encryptedMessageStore = await createMemoryEncryptedMessageHistoryStore();
    } catch (memoryError) {
      encryptedMessageStore = null;
      setText(localStateLabel, t('sync.historyUnavailable'));
      console.error(indexedDbError);
      console.error(memoryError);
      return;
    }
  }
  await restoreEncryptedMessageHistory();
}

// Persistent, device-sealed K_root store for the direct-pay CONV lane. WITHOUT it a reload drops every conversation's
// K_root and scan cursor, so an offline recipient permanently loses messages that are still on chain — the persistence
// half of the receive silent-loss fix. Wallet-scoped + AES-GCM sealed (conv-key-persist); memory fallback if IndexedDB
// is unavailable. Gated behind privateLane.directPay: the clean-15 private path does not use convKeyStore at all. Runs
// BEFORE armIntroReceiveLane (unlock order) so the intro handler captures the persistent store, not a transient memory one.
async function bootConvKeyStore() {
  if (!privateLaneDirectPayEnabled() || !plathoWallet?.address) return;
  try {
    convKeyStore = await createIndexedDbConvKeyStore({ dbName: currentConvKeyDbName() });
  } catch (error) {
    console.warn('[conv] persistent key store unavailable, using memory (K_roots will not survive reload)', error);
    if (!convKeyStore) convKeyStore = createMemoryConvKeyStore();
  }
  await restoreConvKeysFromRecoveryIfEmpty();
  await restorePrefsFromRecoveryIfFresh();
}

// A fresh device / reinstall has an EMPTY conv key store — the IndexedDB is gone but the seed re-derives the recovery
// owner key. Read every recovery slot on chain, decrypt the blob with the seed, and import the K_roots so conversations
// survive a reinstall. Only while the store is empty (a populated store is authoritative), and only latched on a CLEAN
// scan — a transient RPC failure mid-scan returns a PARTIAL map, which must be retried, not treated as authoritative
// (and must never be backed up over the fuller on-chain blob). [RECOVERY restore; recovery-wiring review #1/#2]
let convRecoveryRestoreAttempted = false;   // a CLEAN restore (or clean-empty scan) completed — do not re-scan
let convRecoveryBackupAllowed = false;      // the local map is known ⊇ the on-chain blob → safe to overwrite it
async function restoreConvKeysFromRecoveryIfEmpty() {
  if (convRecoveryRestoreAttempted || !convKeyStore || !plathoWallet?.seed) return;
  if (convKeyStore.snapshot().size > 0) {
    // Already holds conversations (original device, or a prior clean restore) → authoritative; backups are safe.
    convRecoveryRestoreAttempted = true;
    convRecoveryBackupAllowed = true;
    return;
  }
  const transport = globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) return;   // no transport yet — do NOT latch; retry on the next unlock/visible
  try {
    const readView = createRecoveryViewReader((call) => transport.runGetMethod(call));
    const readBody = createRecoveryBodyReader((call) => transport.runGetMethod(call));
    const { map, found, clean } = await restoreConvKeysFromRecovery({ seed: plathoWallet.seed, readView, readBody });
    const imported = map.size > 0 ? await convKeyStore.importConversations(map) : 0;
    globalThis.plathoLastConvRecoveryRestore = { imported, slots: found.length, clean, at: new Date().toISOString() };
    if (clean) {
      // A clean scan is authoritative — the store now holds the whole on-chain backup, so a later backup can only grow it.
      convRecoveryRestoreAttempted = true;
      convRecoveryBackupAllowed = true;
    }  // unclean → leave both false: retry next unlock/visible, and BLOCK any backup from clobbering the fuller on-chain blob.
    if (imported > 0) renderThreads();
  } catch (error) {
    if (!noteTonRpcRateLimit(error)) console.warn('[recovery] restore failed', error);   // no latch — retry later
  }
}

// clean-17: restore the seed-durable prefs (subscriptions) from the NAMED recovery slot on a fresh device. Reads the slot
// by its fixed address (no scan), opens it under the seed, and hands the snapshot to the SAME fresh-device drain the
// clean-15 CapsuleHub path uses (drainRestoredPrefsSnapshots auto-applies ONLY on a truly fresh device, never clobbering
// in-session local follows). A wrong-seed/foreign/absent slot yields nothing and touches no local state.
async function restorePrefsFromRecoveryIfFresh() {
  if (!privateLaneDirectPayEnabled() || !plathoWallet?.seed) return;
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod) return;   // no transport yet — retry on the next unlock/visible
  try {
    const readView = createRecoveryViewReader((call) => transport.runGetMethod(call));
    const readBody = createRecoveryBodyReader((call) => transport.runGetMethod(call));
    const { prefsBytes } = await restorePrefsSnapshot({ seed: plathoWallet.seed, readView, readBody });
    if (prefsBytes) {
      collectRestoredPrefsSnapshot(prefsBytes);
      if (drainRestoredPrefsSnapshots()) { rebuildPublicChannelRegistry(); renderThreads(); }
    }
  } catch (error) {
    if (!noteTonRpcRateLimit(error)) console.warn('[prefs] recovery restore failed', error);
  }
}

// Back up the conversation K_root map on chain so a future reinstall can restore it. Debounced + triggered only when a
// K_root actually changes (a new conversation established via INTRO) — NOT on every CONV message, so the backup cost
// (RECOVERY_PUBLISH_VALUE per write) tracks new conversations, not traffic. MULTI-SLOT: a conversation maps to a stable
// slot (recoverySlotForConversation), so only the AFFECTED slot's partition is re-published — the load spreads across
// 256 slots (~256×the single-slot cap) and one busy slot cannot block the rest. `convRecoveryDirtySlots` survives a lock
// so backups deferred by a background-lock are re-armed on the next unlock. [recovery-wiring review #3/#5/#6; multi-slot]
const RECOVERY_BACKUP_DEBOUNCE_MS = 45_000;
let recoveryBackupTimer = null;
const convRecoveryDirtySlots = new Set();
function scheduleRecoveryBackup(convId, delayMs = RECOVERY_BACKUP_DEBOUNCE_MS) {
  if (!privateLaneDirectPayEnabled() || !convKeyStore || !plathoWallet?.seed) return;
  if (convId) convRecoveryDirtySlots.add(recoverySlotForConversation(convId));
  else for (const slot of partitionRecoveryMap(convKeyStore.snapshot()).keys()) convRecoveryDirtySlots.add(slot);
  if (recoveryBackupTimer) clearTimeout(recoveryBackupTimer);
  recoveryBackupTimer = setTimeout(() => {
    recoveryBackupTimer = null;
    runRecoveryBackup().catch((error) => { if (!noteTonRpcRateLimit(error)) console.warn('[recovery] backup failed', error); });
  }, delayMs);
}
// Re-arm backups a background-lock cancelled before they fired (called after unlock / on return-to-visible).
function rearmRecoveryBackupIfDirty() {
  if (convRecoveryDirtySlots.size > 0 && convRecoveryBackupAllowed && !recoveryBackupTimer) scheduleRecoveryBackup(null, 3_000);
}
async function runRecoveryBackup() {
  if (!convKeyStore || !plathoWallet?.seed) return;
  if (!convRecoveryBackupAllowed) return;   // a partial/unknown local map must NOT overwrite the on-chain blob [#1]
  const transport = globalThis.plathoWalletRpcTransport ?? globalThis.plathoTonRpcTransport;
  if (!transport?.runGetMethod || !transport?.sendBoc) return;   // no transport — keep the dirty slots, retry later
  const readView = createRecoveryViewReader((call) => transport.runGetMethod(call));
  const bySlot = partitionRecoveryMap(convKeyStore.snapshot());
  const slots = [...convRecoveryDirtySlots];
  let published = 0;
  for (const slot of slots) {
    const partition = bySlot.get(slot);
    if (!partition || partition.size === 0) { convRecoveryDirtySlots.delete(slot); continue; }   // slot emptied — nothing to write
    try {
      const built = await prepareRecoveryBackup({ seed: plathoWallet.seed, slotIndex: slot, map: partition, readView, value: RECOVERY_PUBLISH_VALUE });
      await sendPlathoWalletTransaction(plathoWallet, {
        messages: [{ address: built.to, amount: built.value, payload: tonCell.bytesToBase64(tonCell.serializeBoc(built.body)), stateInit: built.init, bounce: true }],
      }, { transport });
      convRecoveryDirtySlots.delete(slot);   // cleared per-slot ONLY on a successful publish — a throw leaves it dirty [#6]
      published += 1;
    } catch (error) {
      if (!noteTonRpcRateLimit(error)) console.warn('[recovery] backup slot', slot, 'failed', error);   // keep this slot dirty
    }
  }
  globalThis.plathoLastConvRecoveryBackup = { slotsPublished: published, slotsRemaining: convRecoveryDirtySlots.size, at: new Date().toISOString() };
}

async function bootWalletScopedLocalStores() {
  await bootReplayStore();
  await bootEncryptedMessageHistory();
  await bootConvKeyStore();
  rearmRecoveryBackupIfDirty();   // re-fire a backup a background-lock cancelled before it landed (now that restore ran)
  if (plathoWallet?.address) activeRuntimeWalletAddress = plathoWallet.address;
  // Saved messages (v652): the self-dialog exists from the first unlock (top of the list until real dialogs push it).
  if (ensureSavedMessagesThread()) renderThreads();
}

function shortKeyId(keyId) {
  const text = String(keyId ?? '');
  if (!text) return 'none';
  if (text.length <= 15) return text;
  return `${text.slice(0, 6)}...${text.slice(-6)}`;
}

function shortPeerId(value) {
  return String(value ?? '').replace(/[^a-z0-9_-]/gi, '').slice(0, 8) || 'unknown';
}

function normalizeCryptoSuite(value) {
  return CRYPTO_SUITES.HYBRID_V1;
}

function currentOutgoingPrivateSuite() {
  return CRYPTO_SUITES.HYBRID_V1;
}

function walletStorageCrypto() {
  const webCrypto = globalThis.crypto;
  if (!webCrypto?.subtle || typeof webCrypto.getRandomValues !== 'function') {
    throw new Error('Secure wallet storage requires WebCrypto');
  }
  return webCrypto;
}

function randomStorageBytes(length) {
  const bytes = new Uint8Array(length);
  walletStorageCrypto().getRandomValues(bytes);
  return bytes;
}

function walletBytesToBase64(bytes) {
  let binary = '';
  const chunkSize = 0x8000;
  for (let offset = 0; offset < bytes.length; offset += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + chunkSize));
  }
  return btoa(binary);
}

function walletBase64ToBytes(text) {
  const binary = atob(String(text ?? ''));
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

function normalizeWalletPasswordInput(value) {
  return String(value ?? '').trim();
}

async function deriveWalletStorageKey(password, saltBytes, iterations = PLATHO_WALLET_KDF_ITERATIONS) {
  const subtle = walletStorageCrypto().subtle;
  const material = await subtle.importKey(
    'raw',
    new TextEncoder().encode(String(password ?? '')),
    'PBKDF2',
    false,
    ['deriveKey'],
  );
  return subtle.deriveKey(
    {
      name: 'PBKDF2',
      hash: 'SHA-256',
      salt: saltBytes,
      iterations,
    },
    material,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  );
}

function readEncryptedPlathoWalletRecord() {
  try {
    const raw = localStorageOrNull()?.getItem(PLATHO_WALLET_STORAGE_KEY);
    if (!raw) return null;
    const record = JSON.parse(raw);
    return record?.kind === PLATHO_WALLET_STORAGE_KIND ? record : null;
  } catch {
    return null;
  }
}

async function updateMessageInEncryptedHistory(thread, message) {
  if (!encryptedMessageStore) return null;
  return writeMessageToEncryptedHistory(thread, message);
}

function readLegacyPlaintextPlathoWalletRecord() {
  try {
    const raw = localStorageOrNull()?.getItem(PLATHO_WALLET_LEGACY_STORAGE_KEY);
    if (!raw) return null;
    const record = JSON.parse(raw);
    return record?.kind === PLATHO_WALLET_LEGACY_STORAGE_KIND && typeof record.recoveryPhrase === 'string'
      ? record
      : null;
  } catch {
    return null;
  }
}

function hasStoredPlathoWalletRecord() {
  return Boolean(readEncryptedPlathoWalletRecord() || readLegacyPlaintextPlathoWalletRecord());
}

function storedWalletShortLabel() {
  const record = storedPlathoWalletRecord();
  const address = storedWalletAddressForCopy(record);
  return address ? shortAddress(address) : t('wallet.encrypted');
}

function storedWalletLockStatus() {
  if (plathoWallet) return t('wallet.unlockedStatus');
  if (readEncryptedPlathoWalletRecord()) return t('wallet.encrypted');
  if (readLegacyPlaintextPlathoWalletRecord()) return t('wallet.secureNow');
  return t('wallet.notStored');
}

function walletPasswordManagerUsername(address = '', networkGlobalId = plathoWalletNetworkOptions().networkGlobalId) {
  const value = String(address ?? '').trim();
  if (!value) return PLATHO_WALLET_PASSWORD_MANAGER_USERNAME;
  try {
    return formatTonUserFriendlyAddress(value, {
      bounceable: false,
      testOnly: Number(networkGlobalId) === PLATHO_WALLET_NETWORK_GLOBAL_IDS.TESTNET,
    });
  } catch {
    return value;
  }
}

async function encryptPlathoWalletRecord(wallet, password) {
  const normalizedPassword = normalizeWalletPasswordInput(password);
  if (!normalizedPassword) throw new Error('Local wallet password is required');
  const salt = randomStorageBytes(16);
  const iv = randomStorageBytes(12);
  const key = await deriveWalletStorageKey(normalizedPassword, salt);
  const payload = {
    kind: PLATHO_WALLET_ENCRYPTED_PAYLOAD_KIND,
    version: 1,
    recoveryPhrase: exportPlathoWalletRecoveryPhrase(wallet),
    address: wallet.address,
    walletKind: wallet.kind,
    networkGlobalId: wallet.networkGlobalId,
  };
  const plaintext = new TextEncoder().encode(JSON.stringify(payload));
  const ciphertext = new Uint8Array(await walletStorageCrypto().subtle.encrypt({ name: 'AES-GCM', iv }, key, plaintext));
  return {
    kind: PLATHO_WALLET_STORAGE_KIND,
    version: 1,
    kdf: PLATHO_WALLET_KDF_NAME,
    iterations: PLATHO_WALLET_KDF_ITERATIONS,
    salt: walletBytesToBase64(salt),
    cipher: PLATHO_WALLET_CIPHER_NAME,
    iv: walletBytesToBase64(iv),
    ciphertext: walletBytesToBase64(ciphertext),
    address: wallet.address,
    walletKind: wallet.kind,
    networkGlobalId: wallet.networkGlobalId,
    createdAt: Date.now(),
  };
}

async function decryptPlathoWalletRecord(record, password) {
  if (!record || record.kind !== PLATHO_WALLET_STORAGE_KIND) throw new Error('Encrypted wallet record is missing');
  const salt = walletBase64ToBytes(record.salt);
  const iv = walletBase64ToBytes(record.iv);
  const ciphertext = walletBase64ToBytes(record.ciphertext);
  const rawPassword = String(password ?? '');
  const normalizedPassword = normalizeWalletPasswordInput(rawPassword);
  let plaintextBytes;
  try {
    const key = await deriveWalletStorageKey(rawPassword, salt, Number(record.iterations ?? PLATHO_WALLET_KDF_ITERATIONS));
    plaintextBytes = await walletStorageCrypto().subtle.decrypt({ name: 'AES-GCM', iv }, key, ciphertext);
  } catch (error) {
    if (!normalizedPassword || normalizedPassword === rawPassword) throw error;
    const key = await deriveWalletStorageKey(normalizedPassword, salt, Number(record.iterations ?? PLATHO_WALLET_KDF_ITERATIONS));
    plaintextBytes = await walletStorageCrypto().subtle.decrypt({ name: 'AES-GCM', iv }, key, ciphertext);
  }
  const payload = JSON.parse(new TextDecoder().decode(plaintextBytes));
  if (payload?.kind !== PLATHO_WALLET_ENCRYPTED_PAYLOAD_KIND || typeof payload.recoveryPhrase !== 'string') {
    throw new Error('Encrypted wallet payload is invalid');
  }
  const storedNetworkGlobalId = Number.isInteger(Number(payload.networkGlobalId))
    ? Number(payload.networkGlobalId)
    : Number.isInteger(Number(record.networkGlobalId))
    ? Number(record.networkGlobalId)
    : plathoWalletNetworkOptions().networkGlobalId;
  const wallet = await importPlathoWallet(payload.recoveryPhrase, { networkGlobalId: storedNetworkGlobalId });
  if (record.address && !sameWalletAddress(wallet.address, record.address)) {
    const error = new Error('Encrypted wallet password is correct, but address metadata does not match');
    error.code = 'PLATHO_WALLET_ADDRESS_METADATA_MISMATCH';
    throw error;
  }
  return wallet;
}

async function requestWalletPasswordInput({
  title,
  hint,
  submitLabel,
  confirm = false,
  create = false,
  // v794: password dialogs are X-only (outside-tap / Escape must not discard a half-typed password). The ✕
  // stays (cancellable defaults true); the unlock flow already passes dismissOnBackdrop:false explicitly.
  dismissOnBackdrop = false,
  cancellable = true,
  passwordManagerUsername = PLATHO_WALLET_PASSWORD_MANAGER_USERNAME,
  passwordManagerNetworkGlobalId = plathoWalletNetworkOptions().networkGlobalId,
  summary = [],
  tone = 'muted',
}) {
  const fields = [{
    id: 'walletPasswordManagerUsername',
    name: 'username',
    type: 'credential-username',
    autocomplete: 'username',
    value: walletPasswordManagerUsername(passwordManagerUsername, passwordManagerNetworkGlobalId),
    required: false,
  }, {
    id: 'walletPassword',
    label: t('wallet.localPasswordLabel'),
    type: 'password',
    autocomplete: create ? 'new-password' : 'current-password',
    placeholder: t('wallet.localPasswordPlaceholder'),
    autocapitalize: 'none',
    spellcheck: false,
    minLength: create ? PLATHO_WALLET_PASSWORD_MIN_LENGTH : undefined,
  }];
  if (confirm) {
    fields.push({
      id: 'walletPasswordConfirm',
      label: t('wallet.repeatPasswordLabel'),
      type: 'password',
      autocomplete: 'new-password',
      placeholder: t('wallet.repeatPasswordPlaceholder'),
      autocapitalize: 'none',
      spellcheck: false,
      minLength: PLATHO_WALLET_PASSWORD_MIN_LENGTH,
    });
  }
  const result = await openActionDialog({
    title,
    hint,
    tone,
    submitLabel,
    dismissOnBackdrop,
    cancellable,
    formAutocomplete: 'on',
    fields,
    summary,
  });
  if (!result) return null;
  return {
    password: String(result.walletPassword ?? ''),
    confirmPassword: String(result.walletPasswordConfirm ?? ''),
  };
}

async function requestNewWalletStoragePassword(title = t('wallet.encryptLocalWalletTitle'), {
  passwordManagerUsername = PLATHO_WALLET_PASSWORD_MANAGER_USERNAME,
  passwordManagerNetworkGlobalId = plathoWalletNetworkOptions().networkGlobalId,
} = {}) {
  let hint = t('wallet.setLocalPasswordHint', { min: PLATHO_WALLET_PASSWORD_MIN_LENGTH, recommended: PLATHO_WALLET_PASSWORD_RECOMMENDED_LENGTH });
  let tone = 'muted';
  while (true) {
    const result = await requestWalletPasswordInput({
      title,
      hint,
      tone,
      submitLabel: t('wallet.encryptWalletSubmit'),
      confirm: true,
      create: true,
      passwordManagerUsername,
      passwordManagerNetworkGlobalId,
      summary: [
        t('wallet.passwordNotSentSummary'),
        t('wallet.passwordManagerSummary', { min: PLATHO_WALLET_PASSWORD_MIN_LENGTH, recommended: PLATHO_WALLET_PASSWORD_RECOMMENDED_LENGTH }),
        t('wallet.recoveryPhraseEncryptedSummary'),
      ],
    });
    if (!result) return null;
    const password = normalizeWalletPasswordInput(result.password);
    const confirmPassword = normalizeWalletPasswordInput(result.confirmPassword);
    if (password.length < PLATHO_WALLET_PASSWORD_MIN_LENGTH) {
      hint = t('wallet.passwordTooShort', { min: PLATHO_WALLET_PASSWORD_MIN_LENGTH });
      tone = 'error';
      continue;
    }
    if (password !== confirmPassword) {
      hint = t('wallet.passwordsDoNotMatch');
      tone = 'error';
      continue;
    }
    return password;
  }
}

async function requestAndDecryptEncryptedWallet(record, {
  title = t('wallet.unlockWallet'),
  hint = t('wallet.unlockWalletHint'),
  submitLabel = t('wallet.unlockWallet'),
} = {}) {
  let feedback = hint;
  let tone = 'muted';
  while (true) {
    const result = await requestWalletPasswordInput({
      title,
      hint: feedback,
      tone,
      submitLabel,
      // Unlock dialog closes ONLY via the explicit ✕ — no click-outside / Escape dismiss (owner request).
      dismissOnBackdrop: false,
      cancellable: true,
      passwordManagerUsername: record?.address,
      passwordManagerNetworkGlobalId: record?.networkGlobalId,
      summary: [
        { label: t('wallet.storedWalletLabel'), value: record?.address ? shortAddress(record.address) : t('wallet.encrypted') },
        { label: t('wallet.storageLabel'), value: `${record?.cipher ?? PLATHO_WALLET_CIPHER_NAME} + ${record?.kdf ?? PLATHO_WALLET_KDF_NAME}` },
      ],
    });
    if (!result) return null;
    try {
      return await decryptPlathoWalletRecord(record, result.password);
    } catch (error) {
      console.error(error);
      feedback = error?.code === 'PLATHO_WALLET_ADDRESS_METADATA_MISMATCH'
        ? t('wallet.metadataMismatch')
        : t('wallet.wrongPassword');
      tone = 'error';
    }
  }
}

async function readStoredPlathoWallet() {
  try {
    const encryptedRecord = readEncryptedPlathoWalletRecord();
    if (encryptedRecord) {
      return requestAndDecryptEncryptedWallet(encryptedRecord);
    }
    const legacyRecord = readLegacyPlaintextPlathoWalletRecord();
    if (!legacyRecord) return null;
    const wallet = await importPlathoWallet(legacyRecord.recoveryPhrase, plathoWalletNetworkOptions());
    const password = await requestNewWalletStoragePassword(t('wallet.secureExistingWalletTitle'), {
      passwordManagerUsername: wallet.address,
      passwordManagerNetworkGlobalId: wallet.networkGlobalId,
    });
    if (!password) return null;
    await writeStoredPlathoWallet(wallet, password);
    return wallet;
  } catch (error) {
    console.error(error);
    return null;
  }
}

async function promptStoredWalletUnlockOnStartup() {
  if (plathoWallet || walletUnlockPromise || !hasStoredPlathoWalletRecord()) return;
  armWalletUnlockPrompt();
}

async function writeStoredPlathoWallet(wallet, password) {
  if (!password) throw new Error('Local wallet password is required');
  const record = await encryptPlathoWalletRecord(wallet, password);
  const verificationWallet = await decryptPlathoWalletRecord(record, password);
  if (!sameWalletAddress(verificationWallet.address, wallet.address)) {
    throw new Error('Encrypted wallet self-check failed');
  }
  try {
    const storage = localStorageOrNull();
    storage?.setItem(PLATHO_WALLET_STORAGE_KEY, JSON.stringify(record));
    storage?.removeItem(PLATHO_WALLET_LEGACY_STORAGE_KEY);
    await requestPersistentLocalStorage();
  } catch {
    // Without persistent storage the current tab still has a working wallet.
  }
  mirrorWalletRecordToTelegramCloud(record);
}

async function writeEncryptedPlathoWalletRecord(record) {
  if (!record || record.kind !== PLATHO_WALLET_STORAGE_KIND) {
    throw new Error('Encrypted wallet record is invalid');
  }
  const storage = localStorageOrNull();
  if (!storage) throw new Error('Local storage is unavailable');
  storage.setItem(PLATHO_WALLET_STORAGE_KEY, JSON.stringify(record));
  storage.removeItem(PLATHO_WALLET_LEGACY_STORAGE_KEY);
  await requestPersistentLocalStorage();
  mirrorWalletRecordToTelegramCloud(record);
}

async function changeStoredPlathoWalletPassword() {
  const record = readEncryptedPlathoWalletRecord();
  if (!record) throw new Error('No encrypted wallet is stored on this device');
  const wallet = await requestAndDecryptEncryptedWallet(record, {
    title: t('wallet.changePasswordTitle'),
    hint: t('wallet.changePasswordHint'),
    submitLabel: t('common.continue'),
  });
  if (!wallet) return false;
  const newPassword = await requestNewWalletStoragePassword(t('wallet.setNewPasswordTitle'), {
    passwordManagerUsername: wallet.address,
    passwordManagerNetworkGlobalId: wallet.networkGlobalId,
  });
  if (!newPassword) return false;
  await writeStoredPlathoWallet(wallet, newPassword);
  plathoWallet = wallet;
  localProfileAvatarPointer = readStoredProfileAvatarPointer(wallet.address);
  markWalletUnlocked();
  scheduleWalletAutoLock();
  return true;
}

async function loadPlathoWallet() {
  if (plathoWallet) return plathoWallet;
  if (walletUnlockPromise) return walletUnlockPromise;
  walletUnlockPromptPending = false;
  clearWalletUnlockPromptTimer();
  walletUnlockPromise = (async () => {
    const wallet = await readStoredPlathoWallet();
    if (wallet) prepareWalletScopedRuntimeForWallet(wallet, 'wallet unlocked');
    plathoWallet = wallet;
    localProfileAvatarPointer = readStoredProfileAvatarPointer(wallet?.address);
    if (wallet) {
      // Password accepted: swap the boot screen from the unlock dialog to the spinner (no-op if it is not up,
      // e.g. a mid-session unlock). bootCrypto lifts it once the core is ready.
      setBootScreenPhase('loading');
      markWalletUnlocked();
      scheduleWalletAutoLock();
      markNavVaultBalancePending('wallet loaded', {
        resetRetry: true,
        retry: true,
        retryDelayMs: 0,
      });
      // The profile-avatar read is NOT fired here: every loadPlathoWallet caller (unlock button, auto-unlock,
      // boot) runs bootCrypto right after, and bootCrypto refreshes the avatar at its tail — serialized AFTER
      // the activation/sync reads. Firing it here overlapped those reads and stalled the iOS run loop (v509).
      resumeProfileAvatarPublishRecoveryForOwner(wallet.address);
    }
    return wallet;
  })();
  try {
    return await walletUnlockPromise;
  } finally {
    walletUnlockPromise = null;
  }
}

async function setPlathoWallet(wallet, { password } = {}) {
  prepareWalletScopedRuntimeForWallet(wallet, 'wallet replaced');
  plathoWallet = wallet;
  markWalletUnlocked();
  localProfileAvatarPointer = readStoredProfileAvatarPointer(wallet.address);
  await writeStoredPlathoWallet(wallet, password);
  scheduleWalletAutoLock();
  await bootCrypto();
  // bootCrypto already refreshed the profile avatar at its tail (serialized after sync). Fire the vault
  // refresh only AFTER bootCrypto fully settles so its single vault read does not overlap that avatar read.
  queueVaultRefreshAfterWalletChange();
  return wallet;
}

async function loadMessagingIdentityFromWallet(suite) {
  const wallet = await loadPlathoWallet();
  if (!wallet) return null;
  return deriveMessagingIdentityFromWallet(wallet, suite);
}

function currentNetworkFeeEstimateNanotons() {
  return resolveNetworkFeeEstimateNanotons(
    globalThis.plathoNetworkFeeEstimate
      ?? appConfig.messaging?.pricing
      ?? appConfig.messaging?.networkFeeEstimateNanotons,
    INCLUDED_NETWORK_FEE_NANOTONS,
  );
}

function currentVaultUserSource() {
  return globalThis.plathoVaultBinding?.user
    ?? null;
}

// Activation is MONOTONIC on-chain: once a wallet's Vault user exists with current_key_id>0 it never reverts. So a
// read that comes back NOT-activated for a wallet we have ALREADY observed activated is a transient bad read (a
// lagging RPC replica / a pre-registration block height / a reorg), never a real downgrade. Accepting one tore the
// whole UI down to "activate your account" (Vault tab locked, profile "Activate" row, nav vault balance gone) for a
// few seconds until the next good read healed it. Remember the last wallet seen activated; reject a not-activated
// read for that same wallet. Cleared on a wallet change (clearWalletScopedRuntimeState). Sibling to
// lastKnownOwnWalletRaw (the v728 messaging-identity guard) — same "never infer state from one bad read" rule.
let lastKnownActivatedVaultWalletRaw = null;
// A get_user read is STAMPED (in loadConnectedVaultUser) with the wallet it was ISSUED for. A read that resolves
// AFTER an in-app wallet switch carries the OLD wallet's stamp, so it must never be attributed to the NEW wallet.
// Without this, a stale activated read for wallet A, landing after a switch to a fresh wallet B, marked B activated
// and the guard then masked B's genuine not-activated reads all session (the v739 review's cross-wallet poison).
const VAULT_USER_READ_WALLET = Symbol('vaultUserReadWallet');

function vaultUserReadWalletRaw(user) {
  return (user && typeof user === 'object' && user[VAULT_USER_READ_WALLET]) || null;
}

// True when `user` came from a read ISSUED for a wallet OTHER than the one connected now (the wallet switched while
// the read was in flight). Display callers discard such a read; note/guard never attribute it to the current wallet.
function vaultUserReadIsStale(user) {
  const readWallet = vaultUserReadWalletRaw(user);
  if (!readWallet) return false; // unstamped (in-context caller) -> treated as current
  const current = rawWalletAddress(plathoWallet?.address);
  return Boolean(current && !sameWalletAddress(readWallet, current));
}

function vaultUserIsActivated(user) {
  if (user?.exists !== true) return false;
  try { return BigInt(user.current_key_id ?? 0n) > 0n; } catch { return false; }
}

function noteVaultUserActivationObserved(user) {
  if (!vaultUserIsActivated(user)) return;
  const current = rawWalletAddress(plathoWallet?.address);
  // Only trust the observation if the read was issued for the CURRENTLY connected wallet — a stale cross-wallet read
  // must never stamp the new wallet as activated (an unstamped in-context read is attributed to the current wallet).
  if (!current || vaultUserReadIsStale(user)) return;
  lastKnownActivatedVaultWalletRaw = current;
}

// True when `user` reports NOT-activated but we have already seen THIS wallet activated -> a transient bad read the
// caller must not act on (don't clobber the binding / flip the UI; a display caller keeps last-known + retries, a
// pre-sign caller still fails closed on the raw read it holds). A read issued for a DIFFERENT wallet is never
// classified against this wallet's guard.
function isTransientVaultActivationDowngrade(user) {
  if (!user || typeof user !== 'object' || vaultUserIsActivated(user) || vaultUserReadIsStale(user)) return false;
  const raw = rawWalletAddress(plathoWallet?.address);
  return Boolean(raw && lastKnownActivatedVaultWalletRaw && sameWalletAddress(raw, lastKnownActivatedVaultWalletRaw));
}

function rememberConnectedVaultUser(user) {
  if (!user || typeof user !== 'object') return user;
  // Suspect not-activated read for a wallet we know is activated: keep the good binding + nav balance untouched.
  // Return the RAW read so a PRE-SIGN caller (readFreshConnectedVaultUserForOwnVaultAction) still fails closed on it
  // instead of signing against a bad read — while the display never flips to "not activated".
  if (isTransientVaultActivationDowngrade(user)) return user;
  noteVaultUserActivationObserved(user);
  globalThis.plathoVaultBinding = {
    ...(globalThis.plathoVaultBinding ?? {}),
    walletAddress: plathoWallet?.address ?? globalThis.plathoVaultBinding?.walletAddress ?? null,
    user,
  };
  vaultPocketState = {
    wallet: vaultPocketState.wallet ?? { ton_balance: null, ath_balance: null },
    vault: {
      ton_balance: user.exists === true ? nonNegativeBigInt(user.ton_balance) : 0n,
      ath_balance: user.exists === true ? nonNegativeBigInt(user.ath_balance) : 0n,
    },
  };
  markNavVaultBalanceReady();
  return user;
}

function hasActiveVaultMessagingKeys() {
  const user = currentVaultUserSource();
  if (user?.exists !== true) return false;
  try {
    return BigInt(user.current_key_id ?? 0n) > 0n;
  } catch {
    return false;
  }
}

function hasActivePlathoAccount() {
  return hasActiveVaultMessagingKeys();
}

function hasCurrentWalletVaultBinding() {
  const binding = globalThis.plathoVaultBinding;
  if (!binding || !plathoWallet?.address) return false;
  if (binding.walletAddress && !sameWalletAddress(binding.walletAddress, plathoWallet.address)) return false;
  return hasActiveVaultMessagingKeys();
}

function currentVaultMessagingKeyId() {
  try {
    const keyId = BigInt(currentVaultUserSource()?.current_key_id ?? 0n);
    return keyId > 0n ? keyId : null;
  } catch {
    return null;
  }
}

function plathoAccountActivationFeeNanotons(user = currentVaultUserSource()) {
  // clean-17 direct-pay: a KeyShard register is a fixed wallet send of KEYSHARD_REGISTER_VALUE (the shard reserves its
  // rent and refunds the surplus), NOT a Vault-estimated external. Gate so every fee-display site is correct at cutover.
  if (privateLaneDirectPayEnabled()) return KEYSHARD_REGISTER_VALUE;
  return estimateVaultAttachedValueNanotons('RegisterMessagingKeys', localVaultDraft?.message ?? { crypto_suite_mask: VAULT_CRYPTO_SUITE.HYBRID }, {
    userExists: user?.exists === true,
  });
}

function plathoAccountActivationFeeLabel(user = currentVaultUserSource()) {
  return t('common.gramAmount', { amount: formatTonNanotons(plathoAccountActivationFeeNanotons(user)) });
}

function clearNavVaultBalanceRetryTimer() {
  if (!navVaultBalanceRetryTimer) return;
  clearTimeout(navVaultBalanceRetryTimer);
  navVaultBalanceRetryTimer = null;
}

function markNavVaultBalanceIdle() {
  clearNavVaultBalanceRetryTimer();
  navVaultBalanceState = { status: 'idle', retryAttempt: 0, reason: null };
  refreshNavVaultBalance();
}

function markNavVaultBalanceReady() {
  clearNavVaultBalanceRetryTimer();
  navVaultBalanceState = { status: 'ready', retryAttempt: 0, reason: null };
  refreshNavVaultBalance();
}

function markNavVaultBalancePending(reason = 'refreshing', options = {}) {
  if (!plathoWallet?.address) {
    markNavVaultBalanceIdle();
    return;
  }
  if (options.resetRetry === true) {
    navVaultBalanceState.retryAttempt = 0;
  }
  navVaultBalanceState = {
    status: 'pending',
    retryAttempt: navVaultBalanceState.retryAttempt,
    reason,
  };
  refreshNavVaultBalance();
  if (options.retry === true) scheduleNavVaultBalanceRetry(options.retryDelayMs);
}

function scheduleNavVaultBalanceRetry(delayMs = null) {
  if (!plathoWallet?.address || document.hidden) return;
  if (navVaultBalanceRetryTimer) return;
  const attempt = Math.min(
    navVaultBalanceState.retryAttempt,
    VAULT_NAV_BALANCE_RETRY_DELAYS_MS.length - 1,
  );
  const effectiveDelayMs = delayMs ?? VAULT_NAV_BALANCE_RETRY_DELAYS_MS[attempt];
  navVaultBalanceRetryTimer = setTimeout(() => {
    navVaultBalanceRetryTimer = null;
    refreshVaultNavBalanceInBackground({ fromRetry: true }).catch((error) => {
      const rateLimited = noteTonRpcRateLimit(error);
      if (!rateLimited && !isExpectedVaultProviderUnavailable(error)) console.error(error);
    });
  }, Math.max(0, Number(effectiveDelayMs) || 0));
}

function markNavVaultBalanceRetryNeeded(reason = 'retrying') {
  navVaultBalanceState.retryAttempt = Math.min(
    navVaultBalanceState.retryAttempt + 1,
    VAULT_NAV_BALANCE_RETRY_DELAYS_MS.length - 1,
  );
  markNavVaultBalancePending(reason, { retry: true });
}

function walletTonBalanceLabel() {
  const balance = vaultPocketState.wallet?.ton_balance;
  return balance === null || balance === undefined ? '-' : t('common.gramAmount', { amount: formatTonNanotons(balance) });
}

function refreshWalletTonProfileStatus() {
  setText(walletTonBalanceStatus, walletTonBalanceLabel());
}

function refreshMessageActionStatuses(options = {}) {
  if (!plathoWallet) {
    if (!options.keepSyncStatus) setMessageSyncStatus(t('common.walletRequiredStatus'), 'wallet-required');
    setText(vaultRotateStatus, t('common.walletRequiredStatus'));
    return;
  }
  if (!options.keepSyncStatus) {
    const state = messageSyncStatusState();
    if (!state || state === 'wallet-required' || state === 'chain') {
      setMessageSyncStatus(t('sync.statusTapToSync'), 'idle');
    }
  }
  setText(vaultRotateStatus, hasActivePlathoAccount() ? t('vault.rotateReady') : t('vault.rotateActivateFirst'));
}

function plathoWalletNetworkOptions() {
  const chain = String(appConfig.network?.chain ?? '').toLowerCase();
  return {
    networkGlobalId: chain === 'testnet'
      ? PLATHO_WALLET_NETWORK_GLOBAL_IDS.TESTNET
      : PLATHO_WALLET_NETWORK_GLOBAL_IDS.MAINNET,
  };
}

function nonNegativeBigInt(value, fallback = 0n) {
  try {
    if (typeof value === 'bigint') return value >= 0n ? value : fallback;
    if (typeof value === 'number' && Number.isFinite(value)) {
      return value > 0 ? BigInt(Math.trunc(value)) : fallback;
    }
    if (typeof value === 'string' && /^[0-9]+$/.test(value.trim())) return BigInt(value.trim());
    if (value && typeof value.toString === 'function') {
      const text = value.toString();
      if (/^[0-9]+$/.test(text)) return BigInt(text);
    }
  } catch {
    return fallback;
  }
  return fallback;
}

function currentAthBalanceAtomic() {
  const source = currentVaultUserSource();
  if (!source || typeof source !== 'object') return 0n;
  return nonNegativeBigInt(source.ath_balance ?? source.athBalance ?? source.ath);
}

function vaultTonBalanceNanotons(user = currentVaultUserSource()) {
  if (!user || typeof user !== 'object') return 0n;
  return nonNegativeBigInt(user.ton_balance ?? user.tonBalance ?? user.ton);
}

function currentMessagingPricingOptions() {
  return appConfig.messaging?.pricing ?? {};
}

function currentNetworkFeeSurchargeNanotons() {
  return networkFeeSurchargeNanotons(currentNetworkFeeEstimateNanotons(), currentMessagingPricingOptions());
}

function currentRawNetworkFeeSurchargeNanotons() {
  return rawNetworkFeeSurchargeNanotons(currentNetworkFeeEstimateNanotons(), currentMessagingPricingOptions());
}

function assertNetworkFeeSurchargeWithinCap() {
  const pricingOptions = currentMessagingPricingOptions();
  const estimate = currentNetworkFeeEstimateNanotons();
  if (!networkFeeSurchargeExceedsMax(estimate, pricingOptions)) return;
  const rawSurcharge = currentRawNetworkFeeSurchargeNanotons();
  const maxSurcharge = maxNetworkFeeSurchargeNanotons(pricingOptions);
  throw new Error(`Network surcharge ${formatTonNanotons(rawSurcharge)} GRAM exceeds the production cap ${formatTonNanotons(maxSurcharge)} GRAM. Try another RPC/network estimate before sending.`);
}

function shortUiErrorText(error, fallback = t('common.blockedCap')) {
  const text = String(error?.message ?? error ?? '').replace(/\s+/g, ' ').trim();
  if (!text) return fallback;
  return text.length > 180 ? `${text.slice(0, 177)}...` : text;
}

function privateSendPreflightStatusText(error) {
  const message = shortUiErrorText(error, 'Send blocked');
  if (/not enough vault ton/i.test(message)) return message;
  if (/persistent encrypted local history/i.test(message)) return 'Local encrypted history unavailable; reload Platho before creating a check';
  if (/payment check recovery record could not be saved|payment check pending ledger could not be saved/i.test(message)) {
    return 'Payment check recovery could not be saved; reload Platho and try again';
  }
  if (/activate platho account before publishing/i.test(message)) return 'Activate Platho account before sending';
  // Insufficient Vault balance is DETERMINISTIC — retrying never helps (the balance won't appear). Surface a
  // clear, actionable terminal status (the message is stopped + manual-retry-available via isFatalPrivateSendError);
  // the user tops up the Vault, then retries.
  if (/ath balance is too low/i.test(message)) return 'Insufficient Vault ATH — top up in Vault, then retry';
  if (/gram balance is too low/i.test(message)) return 'Insufficient Vault GRAM — top up in Vault, then retry';
  if (/network surcharge .* exceeds the production cap/i.test(message)) return message;
  if (isTonRpcVerificationSoftReadError(error)) return 'RPC verification pending';
  if (/Vault chain provider|TON RPC|sendBoc transport|provider is not configured/i.test(message)) return message;
  return message;
}

function privateSendBlockedStatusText(error) {
  return `not sent: ${privateSendPreflightStatusText(error)}`;
}

function vaultActionBlockedStatusText(error, fallback = t('vault.moveBlocked')) {
  const message = shortUiErrorText(error, fallback);
  if (/unlock and activate your platho account before moving ton from vault/i.test(message)) {
    return t('vault.activateBeforeMove');
  }
  if (/local vault auth key is not ready/i.test(message)) {
    return t('vault.unlockActivateBeforeActions');
  }
  return message;
}

function canEditPrivateComposerDraft(thread = activeThread()) {
  return Boolean(thread)
    && thread.readOnly !== true
    && Boolean(plathoWallet);
}

function privateSendBlockReason(thread = activeThread(), options = {}) {
  if (!thread) return t('chat.choosePrivateChat');
  if (thread.readOnly === true) return t('chat.readOnlyChannel');
  if (!plathoWallet) return t('common.walletRequired');
  if (pendingServiceWorkerAppShellReload === true) return t('common.updateReadyReload');
  if (!localIdentity || !localRecipientKeyPair || !localSignedPublicBundle) {
    return t('send.unlockActivateBeforeSending');
  }
  // Activation gate, mirroring the public send button (refreshPublicSendButtonState): an unlocked-but-not-
  // activated sender has the local keys but NO Vault user record, so publishing would be rejected downstream
  // by assertVaultHasPrivatePublishHold. Disable the button + show this reason in the cost status up front
  // instead of letting the user send into an optimistic bubble that flips to "not sent". (The draft INPUT,
  // canEditPrivateComposerDraft, deliberately stays independent of this flickering state — PWA-ACTIVATION-02.)
  if (!hasActivePlathoAccount()) {
    return t('send.activateBeforeSending');
  }
  // Part-cap first (v648): an over-limit draft previously fell through to the shortfall branch and the button
  // tooltip misattributed the block to balance ("Vault GRAM hold required") while the cost line said "split it".
  {
    const plan = privateComposerSendPlan(messageInput?.value ?? '', privateImageAttachments, currentPrivateSenderOptions(), {
      paymentCheck: privatePaymentCheckDraft,
    });
    const limitMessage = privateComposerPartLimitMessage(plan.length);
    if (limitMessage) return limitMessage;
  }
  if (options.includeVaultShortfall !== false && privateComposerKnownVaultTonShortfall()) {
    return t('send.vaultHoldRequired');
  }
  return null;
}

function canAttemptPrivateSend(thread = activeThread()) {
  return canEditPrivateComposerDraft(thread)
    && Boolean(localIdentity && localRecipientKeyPair && localSignedPublicBundle)
    && hasActivePlathoAccount()
    && pendingServiceWorkerAppShellReload !== true
    && !privateComposerKnownVaultTonShortfall();
}

function isTonRpcTransientError(error) {
  const message = String(error?.message ?? error ?? '');
  return isTonRpcRateLimitError(error)
    || Number(error?.status ?? error?.response?.status ?? 0) >= 500
    || error?.code === 'TIMEOUT'
    // Local queue congestion — the request never left the device; retrying next pass is safe and the
    // provider is fine (isTonRpcHardTransportError excludes it from transport-health parking too).
    || error?.code === 'QUEUE_TIMEOUT'
    || error?.code === 'NETWORK_ERROR'
    || error?.code === 'RPC_VERIFICATION_UNAVAILABLE'
    || error?.code === 'RPC_DISAGREEMENT'
    || /HTTP 5\d\d|timeout|network|failed to fetch|fetch failed|backoff|temporar(?:y|ily)|verification unavailable|rpc disagreement|provider unavailable|rpc busy|request aborted|bad gateway|service unavailable|gateway timeout|upstream request failed/i.test(message);
}

function isTonRpcVerificationUnavailableError(error) {
  const message = String(error?.message ?? error ?? '');
  return error?.code === 'RPC_VERIFICATION_UNAVAILABLE'
    || error?.code === 'RPC_DISAGREEMENT'
    || /RPC_VERIFICATION_UNAVAILABLE|verification unavailable|TON RPC disagreement|RPC_DISAGREEMENT/i.test(message);
}

function isFatalPrivateSendError(error) {
  const message = String(error?.message ?? error ?? '');
  return isPublishPriceChangeCancelled(error)
    || isVaultPublishPartialError(error)
    || /not enough vault ton|vault (?:ton|gram|ath) balance is too low|activate platho account|recipient .*not activated|is not registered|ownership is not authoritative|network surcharge .*exceeds the production cap|local platho signing key is not ready|wallet required|provider is not configured|cannot price publish|deployment manifest/i.test(message);
}

function isRecoverablePrivateSendError(error) {
  return isTonRpcTransientError(error) && !isFatalPrivateSendError(error);
}

function isAmbiguousTonRpcBroadcastError(error) {
  const message = String(error?.message ?? error ?? '');
  // App-level definitive rejections (bad BOC / bad nonce / underfunded) only ever
  // arrive as client-side <500 responses. A 5xx is a server/upstream failure whose
  // delivery is UNKNOWN even if its body happens to contain one of these words, so
  // gate the keyword hard-fail to <500 and let 5xx fall through to ambiguous →
  // confirm-via-read (never falsely mark a possibly-delivered external as rejected).
  if (Number(error?.status ?? error?.response?.status ?? 0) < 500
    && /rejected|bad request|invalid boc|invalid message|exit code|not enough vault ton|nonce/i.test(message)) return false;
  if (isTonRpcRateLimitError(error)) return false;
  if (Number(error?.status ?? error?.response?.status ?? 0) >= 500) return true;
  return error?.code === 'TIMEOUT'
    || error?.code === 'NETWORK_ERROR'
    || /HTTP 5\d\d|timeout|network|failed to fetch|fetch failed|backoff|request aborted|bad gateway|service unavailable|gateway timeout|upstream request failed/i.test(message);
}

// Vault exit code 16453 = the publish path's throwUnless(clientNonce == publish_nonce) (contracts/Vault.tact).
// AMBIGUOUS even on a re-broadcast sent right after reading currentNonce === clientNonce: toncenter is a
// FLEET — POST /message is emulated against the SEND node's own state, which can lag the read pool by a
// block, so its 16453 can mean "too early" (publish_nonce still below clientNonce there) just as well as
// "the nonce advanced past this external". NEVER treat this error alone as proof the external landed; the
// only sound landing evidence is a fresh nonce READ showing currentNonce > clientNonce (monotonic counter —
// replicas lag, never run ahead). Callers use this match only to route to the quiet short-cooldown retry.
function isVaultPublishNonceConsumedError(error) {
  return /\b16453\b/.test(String(error?.responseBody ?? error?.message ?? ''));
}

// Per-receiver Vault pre-accept nonce-reject exit codes (throwUnless(code, clientNonce == user.publish_nonce)
// in contracts/Vault.tact) for every SINGLE-EXTERNAL action the no-retained-boc submit helpers send:
// WithdrawTon 16808 (:1402), WithdrawAth 16037 (:1471), ReplaceMessagingKeys 16135 (:1755),
// CreateReceiveIntent 16233 (:1871), ClaimReceiveIntent 16249 (:1998), CancelReceiveIntent 16262 (:2050),
// SetProfileAvatar 16611 (:2345), MintUsername 16711 (:2457). 16453 is the BATCH-publish receiver's code
// and can never genuinely appear on these paths.
const VAULT_SINGLE_EXTERNAL_NONCE_REJECT_CODES = Object.freeze([16037, 16135, 16233, 16249, 16262, 16611, 16711, 16808]);
const VAULT_SINGLE_EXTERNAL_NONCE_REJECT_RE = new RegExp(`\\b(?:${VAULT_SINGLE_EXTERNAL_NONCE_REJECT_CODES.join('|')})\\b`);

// A DEFINITIVE not-relayed verdict for a single-external broadcast 5xx: toncenter's emulation rejected
// the external pre-accept on the receiver's nonce gate, so it was never queued/relayed by that node and
// its nonce was NOT consumed. Deliberately STRICT, failing safe toward AMBIGUOUS (= the caller's old
// raise-floor-and-wait behavior): (1) the exit-code CONTEXT is required, never a bare number anywhere in
// a proxy error page — a false "definitely rejected" on a funds-moving external invites a user retry of
// a possibly-delivered action (double execution), while a false "ambiguous" costs at most the old floor
// overshoot; (2) it never fires when an EARLIER transport attempt's delivery is unknown
// (tonRpcPriorDeliveryAmbiguous, stamped by callSend): a TIMEOUT'd primary upload can still be delivered
// later, so a lagging fallback node's nonce reject does not prove that no copy is in flight.
function isDefinitiveVaultSingleExternalNonceReject(error) {
  if (error?.tonRpcPriorDeliveryAmbiguous === true) return false;
  const text = String(error?.responseBody ?? error?.message ?? '');
  if (!/exit\s*_?code/i.test(text)) return false;
  return VAULT_SINGLE_EXTERNAL_NONCE_REJECT_RE.test(text);
}

// toncenter "cannot send external message : duplicate message" = the SAME BoC is already queued in its
// mempool (an earlier broadcast of this exact external is still being processed). The external IS in flight,
// so a re-broadcast attempt that hits this is effectively a SUCCESSFUL relay, not a failure: without treating
// it as such, the tight (~1s) confirm cadence + the zero first-heal cooldown re-POST the same BoC every pass
// and toncenter answers 500 "duplicate" each time — the red-500-spam loop the owner saw.
function isTonBroadcastDuplicateMessageError(error) {
  return /duplicate message/i.test(String(error?.responseBody ?? error?.message ?? ''));
}

function privateSendRetryDelayMs(error = null, attempt = 0) {
  if (isTonRpcRateLimitError(error)) return tonRpcLimitBackoffMs(error);
  const index = Math.min(Math.max(0, Number(attempt) || 0), PRIVATE_SEND_RETRY_DELAYS_MS.length - 1);
  return PRIVATE_SEND_RETRY_DELAYS_MS[index];
}

function privateSendRetryMeta(error = null) {
  if (isTonRpcVerificationSoftReadError(error)) return 'checking RPC, retrying';
  return isTonRpcRateLimitError(error) ? 'retrying after RPC busy' : 'retrying send';
}

function privateSendRetryExhaustedStatusText(error = null) {
  if (error?.code === 'RECIPIENT_OWNER_CHANGED') return 'not sent: username moved to a new wallet — resend';
  if (error?.code === 'STALE_PRIVATE_PUBLISH') return 'not sent: retry window expired';
  if (error?.code === 'PARTIAL_PRIVATE_PUBLISH_RETRY_EXPIRED') {
    return /limit/i.test(String(error?.message ?? ''))
      ? 'not sent: partial publish retry limit reached'
      : 'not sent: partial publish retry window expired';
  }
  if (isTonRpcVerificationSoftReadError(error)) return 'not sent: RPC verification stayed unavailable';
  if (isTonRpcRateLimitError(error)) return 'not sent: RPC stayed busy';
  return 'not sent: retry limit reached';
}

function privateSendRetryMaxAttempts(error = null, message = null) {
  if (privateMessageHasPartialRetryablePublish(message)) return PRIVATE_SEND_PARTIAL_RETRY_MAX_ATTEMPTS;
  if (isTonRpcVerificationSoftReadError(error) || isTonRpcRateLimitError(error)) return PRIVATE_SEND_RPC_RETRY_MAX_ATTEMPTS;
  return PRIVATE_SEND_RETRY_MAX_ATTEMPTS;
}

function messageDiscountUnlocked() {
  const remaining = vaultProtocolState?.airdrop_remaining_ath;
  if (remaining === null || remaining === undefined) return false;
  return nonNegativeBigInt(remaining) <= VAULT_ACTIVITY_AIRDROP_DISCOUNT_UNLOCK_REMAINING_ATH_ATOMIC;
}

function athDiscountBps() {
  if (!messageDiscountUnlocked()) return 0n;
  const athBalance = currentAthBalanceAtomic();
  if (athBalance >= ATH_FULL_DISCOUNT_AMOUNT_ATOMIC) return 10_000n;
  return (athBalance * 10_000n) / ATH_FULL_DISCOUNT_AMOUNT_ATOMIC;
}

function formatDiscountPercent(bps = athDiscountBps()) {
  const basis = nonNegativeBigInt(bps);
  return basis >= 10_000n ? '100%' : formatBasisPointsPercent(basis);
}

function formatAthDiscountLabel() {
  if (!messageDiscountUnlocked()) {
    return t('composer.athDiscountLocked');
  }
  const bps = athDiscountBps();
  if (bps >= 10_000n) {
    return t('composer.athDiscountFull');
  }
  return t('composer.athDiscountPartial', { percent: formatDiscountPercent(bps) });
}

function discountedProtocolFeeNanotons(fullFee) {
  const fee = nonNegativeBigInt(fullFee);
  if (!messageDiscountUnlocked()) return fee;
  const minFee = fee < PLATO_MIN_PROTOCOL_FEE_NANOTONS ? fee : PLATO_MIN_PROTOCOL_FEE_NANOTONS;
  const athBalance = currentAthBalanceAtomic();
  if (athBalance >= ATH_FULL_DISCOUNT_AMOUNT_ATOMIC) return minFee;
  const remaining = ATH_FULL_DISCOUNT_AMOUNT_ATOMIC - athBalance;
  const discounted = ((fee * remaining) + ATH_FULL_DISCOUNT_AMOUNT_ATOMIC - 1n) / ATH_FULL_DISCOUNT_AMOUNT_ATOMIC;
  return discounted < minFee ? minFee : discounted;
}

function normalizePrivateSizeClass(sizeClass = 1) {
  const normalized = Number(sizeClass);
  return [1, 2, 4, 8, 16, 32].includes(normalized) ? normalized : 1;
}

function privateLocalExecReserveNanotons(suite, sizeClass = 1) {
  const normalizedSizeClass = normalizePrivateSizeClass(sizeClass);
  const table = VAULT_PUBLISH_PRIVATE_HYBRID_LOCAL_EXEC_RESERVE_NANOTONS;
  return table[normalizedSizeClass] ?? table[1];
}

function privateCapsulehubChargeNanotons(sizeClass = 1) {
  const normalizedSizeClass = normalizePrivateSizeClass(sizeClass);
  const execReserve = CAPSULEHUB_PRIVATE_HYBRID_EXEC_RESERVE_NANOTONS[normalizedSizeClass]
    ?? CAPSULEHUB_PRIVATE_HYBRID_EXEC_RESERVE_NANOTONS[1];
  return execReserve + CAPSULEHUB_PRIVATE_STORAGE_CHARGE_NANOTONS;
}

function publicLocalExecReserveNanotons(sizeClass = 1) {
  const normalizedSizeClass = normalizePrivateSizeClass(sizeClass);
  const table = VAULT_PUBLISH_PUBLIC_LOCAL_EXEC_RESERVE_NANOTONS;
  return table[normalizedSizeClass] ?? table[1];
}

function publicCapsulehubChargeNanotons(sizeClass = 1) {
  const normalizedSizeClass = normalizePrivateSizeClass(sizeClass);
  const execReserve = CAPSULEHUB_PUBLIC_EXEC_RESERVE_NANOTONS[normalizedSizeClass]
    ?? CAPSULEHUB_PUBLIC_EXEC_RESERVE_NANOTONS[1];
  return execReserve + CAPSULEHUB_PUBLIC_STORAGE_CHARGE_NANOTONS;
}

function privateComposerPublishProfile(suite = currentOutgoingPrivateSuite(), sizeClass = 1) {
  const normalizedSuite = normalizeCryptoSuite(suite);
  const normalizedSizeClass = normalizePrivateSizeClass(sizeClass);
  return {
    publishKind: VAULT_PUBLISH_KIND.PRIVATE,
    sizeClass: BigInt(normalizedSizeClass),
    cryptoSuite: VAULT_CRYPTO_SUITE.HYBRID,
    priceSuite: MESSAGE_PRICE_SUITES.HYBRID_V1,
    fixedCharge: privateLocalExecReserveNanotons(normalizedSuite, normalizedSizeClass) + privateCapsulehubChargeNanotons(normalizedSizeClass),
    protocolFee: PLATO_PRIVATE_LONG_TERM_FEE_NANOTONS,
  };
}

function publicComposerPublishProfile(sizeClass = 1) {
  const normalizedSizeClass = normalizePrivateSizeClass(sizeClass);
  return {
    publishKind: VAULT_PUBLISH_KIND.PUBLIC,
    sizeClass: BigInt(normalizedSizeClass),
    cryptoSuite: VAULT_CRYPTO_SUITE.PUBLIC_NONE,
    priceSuite: MESSAGE_PRICE_SUITES.PUBLIC_V1,
    fixedCharge: publicLocalExecReserveNanotons(normalizedSizeClass) + publicCapsulehubChargeNanotons(normalizedSizeClass),
    protocolFee: PLATO_PUBLIC_POST_FEE_NANOTONS,
  };
}

function publicComposerPublishProfilesForPlan(plan) {
  const parts = Array.isArray(plan) && plan.length > 0 ? plan : [{ sizeClass: 1 }];
  return parts.map((part) => publicComposerPublishProfile(part.sizeClass));
}

function composerPartCount(text, maxTextBytes = SINGLE_CAPSULE_USEFUL_BYTES) {
  return messagePartCount(text ?? '', maxTextBytes);
}

function imageCompressionMode(modeId) {
  return IMAGE_COMPRESSION_MODES[modeId] ?? IMAGE_COMPRESSION_MODES[DEFAULT_IMAGE_COMPRESSION_MODE_ID];
}

function imageAttachmentPartCount(attachment) {
  if (!attachment?.bytes?.length) return 0;
  return splitBytesToCapsuleParts(attachment.bytes, MAX_CAPSULE_USEFUL_BYTES).length;
}

function privateImageAttachmentPartCount(attachment, options = currentPrivateSenderOptions()) {
  if (!attachment?.bytes?.length) return 0;
  return privateImageCapsulePartsForSend(attachment, options).length;
}

function normalizePrivateImageAttachments(attachments = privateImageAttachments) {
  if (Array.isArray(attachments)) return attachments.filter((attachment) => attachment?.bytes?.length);
  return attachments?.bytes?.length ? [attachments] : [];
}

function normalizePublicImageAttachments(attachments = publicImageAttachments) {
  return normalizePrivateImageAttachments(attachments);
}

function normalizePrivateFileAttachments(attachments = privateFileAttachments) {
  if (!Array.isArray(attachments)) return [];
  return attachments.filter((file) => file?.bytes?.length);
}

function privateCompactPayloadOverhead(options = {}) {
  return PLATHO_COMPACT_SENDER_RECOVERY_BYTES
    + PLATHO_COMPACT_RECIPIENT_WALLET_METADATA_BYTES
    + (options.includeSenderWalletMetadata === false ? 0 : PLATHO_COMPACT_SENDER_WALLET_METADATA_BYTES)
    + privateSenderUsernameMetadataBytes(options);
}

function privateTextCapsulePartsForSend(text, options = {}) {
  return splitUtf8ToCapsuleParts(text, MAX_CAPSULE_USEFUL_BYTES, {
    perPartOverheadBytes: privateCompactPayloadOverhead(options),
  });
}

function privateImageCapsulePartsForSend(attachment, options = {}) {
  if (!attachment?.bytes?.length) return [];
  return splitBytesToCapsuleParts(attachment.bytes, MAX_CAPSULE_USEFUL_BYTES, {
    perPartOverheadBytes: privateCompactPayloadOverhead(options),
  });
}

function privateComposerRetrievalPartLimit() {
  const configuredLimit = Number(appConfig.capsuleHub?.privateIndexReadLimit ?? PRIVATE_CHAIN_INDEX_READ_LIMIT);
  return Number.isFinite(configuredLimit)
    ? Math.max(1, Math.floor(configuredLimit))
    : PRIVATE_CHAIN_INDEX_READ_LIMIT;
}

// v648 (owner): ONE message is capped at 8 capsules on BOTH surfaces. Before this the private cap was the
// RETRIEVAL bound (120 — the recipient index walk), which let a user compose a ~3.8MB monster whose serial
// nonce-chain send would run for HOURS (and the public composer had NO cap at all — the symmetric-case miss).
// 8 = MAX_BATCH_PARTS: matches the batch unit, bounds the worst-case send at the scaled ~21-minute terminal, and
// still fits 4 Maximum-quality images or ~256KB of text per message.
const COMPOSER_MAX_MESSAGE_PARTS = MAX_BATCH_PARTS;

function privateComposerPartLimitMessage(partCount) {
  const parts = Number(partCount ?? 0);
  const limit = Math.min(privateComposerRetrievalPartLimit(), COMPOSER_MAX_MESSAGE_PARTS);
  if (!Number.isFinite(parts) || parts <= limit) return null;
  return tPlural('composer.privatePartLimit', parts, { limit });
}

function publicComposerPartLimitMessage(partCount) {
  const parts = Number(partCount ?? 0);
  if (!Number.isFinite(parts) || parts <= COMPOSER_MAX_MESSAGE_PARTS) return null;
  return tPlural('composer.publicPartLimit', parts, { limit: COMPOSER_MAX_MESSAGE_PARTS });
}

function assertPublicComposerPartLimit(partCount) {
  const message = publicComposerPartLimitMessage(partCount);
  if (message) throw new Error(message);
}

function assertPrivateComposerPartLimit(partCount) {
  const message = privateComposerPartLimitMessage(partCount);
  if (message) throw new Error(message);
}

function privateSenderUsernameMetadataLabel(options = {}) {
  if (options.includeSenderWalletMetadata === false) return null;
  const explicit = normalizeLinkedPlathoUsername(options.senderUsername ?? options.sender_username);
  if (explicit) return explicit.label;
  return readLinkedPlathoUsername(plathoWallet?.address)?.label ?? null;
}

function privateSenderUsernameMetadataBytes(options = {}) {
  const label = privateSenderUsernameMetadataLabel(options);
  if (!label) return 0;
  return PLATHO_COMPACT_SENDER_USERNAME_METADATA_PREFIX_BYTES + new TextEncoder().encode(label).length;
}

function privateComposerSendPlan(text, attachments = privateImageAttachments, options = currentPrivateSenderOptions(), extras = {}) {
  const plan = [];
  // extras.replyDraft: undefined -> the LIVE composer draft (typing-time cost estimates); an explicit null/value
  // -> that exact state (retry contexts replay the CAPTURED draft — the live one is long cleared by then).
  const documentBytes = messageDocumentBytesFromDraft(text, attachments, extras.paymentCheck ?? privatePaymentCheckDraft, {
    allowMissingPaymentSecret: true,
  }, extras.replyDraft === undefined ? privateReplyDraft : extras.replyDraft,
  extras.fileAttachments === undefined ? privateFileAttachments : extras.fileAttachments,
  extras.shareDraft === undefined ? privateShareDraft : extras.shareDraft);
  if (!documentBytes) return plan;
  for (const part of splitBytesToCapsuleParts(documentBytes, MAX_CAPSULE_USEFUL_BYTES, {
    perPartOverheadBytes: privateCompactPayloadOverhead(options),
  })) {
    plan.push({ type: 'document', bytes: part.bytes, sizeClass: part.sizeClass, usefulBytes: part.usefulBytes });
  }
  return plan;
}

function privateComposerPublishProfilesForPlan(suite, plan) {
  const parts = Array.isArray(plan) && plan.length > 0 ? plan : [{ sizeClass: 1 }];
  return parts.map((part) => privateComposerPublishProfile(suite, part.sizeClass));
}

function imageAttachmentSizeLabel(attachment) {
  if (!attachment?.bytes?.length) return t('common.kibAmount', { amount: 0 });
  const kib = attachment.bytes.length / 1024;
  return kib < 10 ? t('common.kibAmount', { amount: kib.toFixed(1) }) : t('common.kibAmount', { amount: Math.ceil(kib) });
}

function imageByteCountLabel(value) {
  const bytes = typeof value === 'number'
    ? value
    : (value?.length ?? value?.byteLength ?? 0);
  const length = Number(bytes);
  if (!Number.isFinite(length) || length <= 0) return '';
  const kib = length / 1024;
  return kib < 10 ? t('common.kibAmount', { amount: kib.toFixed(1) }) : t('common.kibAmount', { amount: Math.ceil(kib) });
}

function messageImageLightboxMeta(attachment, image = null) {
  const width = Number(attachment?.width ?? image?.naturalWidth ?? 0);
  const height = Number(attachment?.height ?? image?.naturalHeight ?? 0);
  const dimensions = width > 0 && height > 0 ? t('common.dimensions', { width, height }) : '';
  const size = imageByteCountLabel(attachment?.bytes);
  const mode = attachment?.modeLabel
    ?? (attachment?.mode ? imageCompressionMode(attachment.mode).label : '');
  return [dimensions, size, mode].filter(Boolean).join(' - ') || t('chat.chatImage');
}

function imageAttachmentSummaryRows(attachment, options = {}) {
  const mode = attachment?.mode ?? imageCompressionMode(options.modeId);
  const partCounter = typeof options.partCounter === 'function' ? options.partCounter : imageAttachmentPartCount;
  const parts = partCounter(attachment);
  const rows = [
    { label: t('composer.qualityLabel'), value: mode.label },
  ];
  if (attachment) {
    rows.push(
      { label: t('composer.finalImageLabel'), value: t('composer.finalImageValue', { width: attachment.width, height: attachment.height }) },
      { label: t('composer.onChainSizeLabel'), value: tPlural('composer.onChainSizeValue', parts, { size: imageAttachmentSizeLabel(attachment) }) },
    );
  } else {
    rows.push({ label: t('composer.previewLabel'), value: t('composer.compressingSelectedQuality') });
  }
  const extraRows = typeof options.extraRows === 'function'
    ? options.extraRows(attachment)
    : (options.extraRows ?? []);
  for (const row of extraRows) rows.push(row);
  return rows;
}

function setImagePreviewNodes(previewId, attachment, status = '') {
  const preview = document.getElementById(previewId);
  const meta = document.getElementById(`${previewId}Meta`);
  if (preview instanceof HTMLImageElement && attachment?.dataUrl) {
    preview.src = attachment.dataUrl;
    preview.dataset.fullImageSrc = attachment.dataUrl;
    preview.dataset.fullImageMeta = t('composer.imageMetaLine', { width: attachment.width, height: attachment.height, size: imageAttachmentSizeLabel(attachment), mode: attachment.mode.label });
  } else if (preview instanceof HTMLImageElement) {
    delete preview.dataset.fullImageSrc;
    delete preview.dataset.fullImageMeta;
  }
  if (meta) {
    meta.textContent = attachment
      ? t('composer.imageMetaLine', { width: attachment.width, height: attachment.height, size: imageAttachmentSizeLabel(attachment), mode: attachment.mode.label })
      : status;
  }
}

async function requestCompressedImageFile(file, options = {}) {
  if (!file) return null;
  const initialMode = imageCompressionMode(options.modeId ?? DEFAULT_IMAGE_COMPRESSION_MODE_ID);
  const previewId = `imagePreview${Date.now()}${Math.floor(Math.random() * 10000)}`;
  let selectedAttachment = null;
  let selectedModeId = initialMode.id;
  let errorText = '';
  let sequence = 0;

  const dialogPromise = openActionDialog({
    title: options.title ?? t('composer.attachImageTitle'),
    hint: options.hint ?? t('composer.attachImageHint'),
    tone: options.tone ?? 'muted',
    submitLabel: options.submitLabel ?? t('composer.useImageSubmit'),
    fields: [
      {
        id: previewId,
        label: t('composer.previewFinalImageLabel'),
        type: 'image-preview',
        meta: t('composer.compressingPreview'),
      },
      {
        id: 'imageQuality',
        label: t('composer.qualityLabel'),
        type: 'select',
        options: avatarCompressionOptions(),
        value: initialMode.id,
      },
    ],
    summary: (values) => {
      const mode = imageCompressionMode(values.imageQuality ?? selectedModeId);
      if (errorText) {
        return [
          { label: t('composer.qualityLabel'), value: mode.label },
          { label: t('common.statusLabel'), value: errorText },
        ];
      }
      if (!selectedAttachment || selectedAttachment.mode.id !== mode.id) {
        return imageAttachmentSummaryRows(null, {
          modeId: mode.id,
          partCounter: options.partCounter,
          extraRows: options.extraRows,
        });
      }
      return imageAttachmentSummaryRows(selectedAttachment, {
        partCounter: options.partCounter,
        extraRows: options.extraRows,
      });
    },
  });

  const qualitySelect = actionFields?.querySelector('[name="imageQuality"]');
  const compressSelected = async () => {
    const run = ++sequence;
    const mode = imageCompressionMode(qualitySelect?.value ?? selectedModeId);
    selectedModeId = mode.id;
    selectedAttachment = null;
    errorText = '';
    if (actionSubmitButton) actionSubmitButton.disabled = true;
    setImagePreviewNodes(previewId, null, t('composer.compressingModePreview', { mode: mode.label.toLowerCase() }));
    renderActionSummary(activeActionDialog?.summary, collectActionDialogValues());
    try {
      const attachment = await compressImageFile(file, mode.id);
      if (run !== sequence) return;
      selectedAttachment = attachment;
      setImagePreviewNodes(previewId, attachment);
    } catch (error) {
      if (run !== sequence) return;
      errorText = error?.message ?? t('composer.imageCompressionBlocked');
      setImagePreviewNodes(previewId, null, errorText);
      console.error(error);
    } finally {
      if (run === sequence) {
        renderActionSummary(activeActionDialog?.summary, collectActionDialogValues());
        if (actionSubmitButton) actionSubmitButton.disabled = !selectedAttachment;
      }
    }
  };

  qualitySelect?.addEventListener('change', () => {
    compressSelected().catch((error) => {
      errorText = error?.message ?? t('composer.imageCompressionBlocked');
      renderActionSummary(activeActionDialog?.summary, collectActionDialogValues());
    });
  });
  compressSelected().catch((error) => {
    errorText = error?.message ?? t('composer.imageCompressionBlocked');
    renderActionSummary(activeActionDialog?.summary, collectActionDialogValues());
  });

  const result = await dialogPromise;
  if (!result) return null;
  const finalMode = imageCompressionMode(result.imageQuality ?? selectedModeId);
  if (!selectedAttachment || selectedAttachment.mode.id !== finalMode.id) {
    selectedAttachment = await compressImageFile(file, finalMode.id);
  }
  return selectedAttachment;
}

function composerTotalPartCount(text, attachment, maxTextBytes = SINGLE_CAPSULE_USEFUL_BYTES) {
  const hasText = String(text ?? '').trim().length > 0;
  const textParts = hasText ? composerPartCount(text, maxTextBytes) : 0;
  return Math.max(1, textParts + imageAttachmentPartCount(attachment));
}

// Map a composer publish profile to the kind label the batch hold model keys on.
function composerProfileKindLabel(profile) {
  return BigInt(profile?.publishKind ?? VAULT_PUBLISH_KIND.PRIVATE) === VAULT_PUBLISH_KIND.PUBLIC
    ? 'public'
    : 'private';
}

// VPB2 batch hold. The contract post-accept-rejects RJ_UNDERPRICED any batch whose signed max_charge is
// below canonical_total == SHARED_BASE + Σ perPartHold(kind,size). The protocol fee + per-part costs live
// INSIDE perPartHold (sandbox-measured), so we no longer add profile.fixedCharge/protocolFee here — those
// were the stale per-message model that under-quoted the batch and would strand a publish at RJ_UNDERPRICED.
// The network-fee surcharge rides on top, per part. Passing an ARRAY prices the whole batch (SHARED_BASE
// charged ONCE — amortized). Passing a single profile with `parts` prices `parts` independent SINGLE-capsule
// batches (SHARED_BASE per part): a deliberate, SAFE over-estimate for affordability, since the real grouped
// batch hold is never higher than the per-capsule sum.
function composerEstimatedMaxChargeNanotons(profile, parts = 1) {
  if (Array.isArray(profile)) {
    if (profile.length === 0) return 0n;
    const hold = batchHoldNanotons(profile.map((item) => ({
      kindLabel: composerProfileKindLabel(item),
      sizeClass: Number(item?.sizeClass ?? 1),
    })));
    return hold + currentNetworkFeeSurchargeNanotons() * BigInt(profile.length);
  }
  const count = BigInt(Math.max(1, Number(parts) || 1));
  const kindLabel = composerProfileKindLabel(profile);
  const sizeClass = Number(profile?.sizeClass ?? 1);
  const singleCapsuleHold = BATCH_SHARED_BASE_HOLD_NANOTONS + capsulePerPartHoldNanotons(kindLabel, sizeClass);
  return (singleCapsuleHold + currentNetworkFeeSurchargeNanotons()) * count;
}

// The OBSERVED SETTLED net price of one capsule (real user debit after the over-hold is refunded on ACK),
// from the sandbox-measured net-price tables, plus the retained network-fee surcharge (not refunded).
function composerProfileNetPriceNanotons(profile) {
  const sizeClass = Number(profile?.sizeClass ?? 1);
  const settled = composerProfileKindLabel(profile) === 'public'
    ? publicCapsuleBaseNetPriceNanotons(sizeClass)
    : privateCapsuleBaseNetPriceNanotons(sizeClass);
  return nonNegativeBigInt(settled) + currentNetworkFeeSurchargeNanotons();
}

function composerEstimatedNetCostNanotons(profile, parts = 1) {
  if (Array.isArray(profile)) {
    return profile.reduce((sum, item) => sum + composerProfileNetPriceNanotons(item), 0n);
  }
  return composerProfileNetPriceNanotons(profile) * BigInt(Math.max(1, Number(parts) || 1));
}

// Hold -> net fallback for paths that only have the final hold (no per-part profiles): the settled net cost
// is materially below the hold (the bulk of the hold is the refundable import over-hold + ACK float), so we
// estimate net from the observed-settled fraction of a 1-part hold. Used only for the price-change confirm
// dialog's "new cost" line; if profiles are available, composerEstimatedNetCostNanotons is exact.
function composerNetCostFromHoldNanotons(hold, parts = 1, profiles = null) {
  if (Array.isArray(profiles) && profiles.length > 0) {
    return composerEstimatedNetCostNanotons(profiles, profiles.length);
  }
  const value = nonNegativeBigInt(hold);
  // Conservative: report the hold itself as the cost ceiling when we lack profiles (never under-quote).
  return value * BigInt(Math.max(1, Number(parts) || 1)) / BigInt(Math.max(1, Number(parts) || 1));
}

function composerKnownVaultTonShortfall(profile, parts = 1) {
  // clean-17 direct-pay has NO Vault hold — a CONV/public send is funded from the wallet and the affordability check
  // runs at send time (attemptConvMessagePublishDirect / the public direct path do their own wallet-GRAM check). The
  // synthesized KeyShard activation user carries no ton_balance, so reading it here would be a permanent false shortfall
  // that disables every registered user's send button at cutover. Skip the Vault-balance gate; keep the part-cap gate
  // (checked in the wrappers before this call). [keyshard activation review: ton_balance false-shortfall]
  if (privateLaneDirectPayEnabled()) return false;
  const user = currentVaultUserSource();
  if (user?.exists !== true) return false;
  return vaultTonBalanceNanotons(user) < composerEstimatedMaxChargeNanotons(profile, parts);
}

function privateComposerKnownVaultTonShortfall() {
  const plan = privateComposerSendPlan(messageInput?.value ?? '', privateImageAttachments, currentPrivateSenderOptions(), {
    paymentCheck: privatePaymentCheckDraft,
  });
  if (privateComposerPartLimitMessage(plan.length)) return true;
  return composerKnownVaultTonShortfall(privateComposerPublishProfilesForPlan(currentOutgoingPrivateSuite(), plan), 1);
}

function publicComposerKnownVaultTonShortfall() {
  const plan = publicComposerSendPlan(publicMessageInput?.value ?? '', publicImageAttachments);
  // Part-cap disables the send button too (v648, mirrors the private branch); the cost status carries the
  // split-it message so the disabled state is explained right below the composer.
  if (publicComposerPartLimitMessage(plan.length)) return true;
  return composerKnownVaultTonShortfall(publicComposerPublishProfilesForPlan(plan), 1);
}

function composerPublishProfileForDraft(publish) {
  if (BigInt(publish?.publish_kind ?? 0n) === VAULT_PUBLISH_KIND.PUBLIC) return publicComposerPublishProfile(Number(publish?.size_class ?? 1));
  return privateComposerPublishProfile(currentOutgoingPrivateSuite(), Number(publish?.size_class ?? 1));
}

function composerPublishProfilesForCapsules(capsules) {
  return (capsules ?? [])
    .filter((capsule) => capsule?.publish)
    .map((capsule) => composerPublishProfileForDraft(capsule.publish));
}

const PUBLISH_PRICE_CHANGE_CANCELLED_CODE = 'PLATHO_PUBLISH_PRICE_CHANGE_CANCELLED';

function publishPriceChangeCancelledError() {
  const error = new Error('Publish cancelled');
  error.code = PUBLISH_PRICE_CHANGE_CANCELLED_CODE;
  return error;
}

function isPublishPriceChangeCancelled(error) {
  return error?.code === PUBLISH_PRICE_CHANGE_CANCELLED_CODE;
}

async function confirmPublishPriceIncrease({ previousHold, finalHold, previousNetCost, finalNetCost, parts }) {
  const oldHold = nonNegativeBigInt(previousHold);
  const newHold = nonNegativeBigInt(finalHold);
  const oldCost = nonNegativeBigInt(previousNetCost);
  const newCost = nonNegativeBigInt(finalNetCost);
  // Only a higher NET COST (a real, non-refundable debit increase) needs confirmation. A higher
  // hold alone is a fully-refundable over-reserve and must NOT alarm — otherwise every multi-capsule
  // batch (whose amortized batch hold and the per-part canonical sum legitimately differ by one
  // SHARED_BASE per extra part) would prompt spuriously even though the chain price is unchanged.
  if (newCost <= oldCost) return true;
  const result = await openActionDialog({
    title: t('dialog.priceChangedTitle'),
    hint: t('dialog.priceChangedHint'),
    tone: 'error',
    submitLabel: t('dialog.sendWithNewPrice'),
    dismissOnBackdrop: false,
    summary: [
      { label: t('composer.capsulesLabel'), value: String(Math.max(1, Number(parts) || 1)) },
      { label: t('dialog.previousCostLabel'), value: t('common.gramAmount', { amount: formatTonNanotons(oldCost) }) },
      { label: t('dialog.newCostLabel'), value: t('common.gramAmount', { amount: formatTonNanotons(newCost) }) },
      { label: t('dialog.previousHoldLabel'), value: t('common.gramAmount', { amount: formatTonNanotons(oldHold) }) },
      { label: t('dialog.newHoldLabel'), value: t('common.gramAmount', { amount: formatTonNanotons(newHold) }) },
    ],
  });
  return result !== null;
}

async function confirmHighNetworkFeeSurcharge({ surcharge, finalHold, finalNetCost, parts }) {
  const perCapsuleSurcharge = nonNegativeBigInt(surcharge);
  const pricingOptions = currentMessagingPricingOptions();
  if (!requiresHighNetworkFeeSurchargeConfirmation(perCapsuleSurcharge, pricingOptions)) return true;
  const capsuleCount = Math.max(1, Number(parts) || 1);
  const totalSurcharge = perCapsuleSurcharge * BigInt(capsuleCount);
  const netCost = nonNegativeBigInt(finalNetCost);
  const baseNetCost = netCost > totalSurcharge ? netCost - totalSurcharge : 0n;
  const manualOverride = requiresManualNetworkFeeSurchargeOverride(perCapsuleSurcharge, pricingOptions);
  const result = await openActionDialog({
    title: manualOverride ? t('dialog.manualNetworkFeeOverrideTitle') : t('dialog.highNetworkSurchargeTitle'),
    hint: t('dialog.highNetworkSurchargeHint'),
    tone: manualOverride ? 'error' : 'warning',
    submitLabel: manualOverride ? t('dialog.manualOverrideSend') : t('dialog.confirmSurcharge'),
    dismissOnBackdrop: false,
    summary: [
      { label: t('composer.capsulesLabel'), value: String(capsuleCount) },
      { label: t('dialog.baseCostLabel'), value: t('common.gramAmount', { amount: formatTonNanotons(baseNetCost) }) },
      { label: t('dialog.networkSurchargeLabel'), value: t('common.gramAmount', { amount: formatTonNanotons(totalSurcharge) }) },
      { label: t('dialog.expectedCostLabel'), value: t('common.gramAmount', { amount: formatTonNanotons(netCost) }) },
      { label: t('dialog.holdLabel'), value: t('common.gramAmount', { amount: formatTonNanotons(finalHold) }) },
    ],
  });
  return result !== null;
}

// Does the private composer resolve to at least one real block to send? composerBlocksFromDraft drops an orphaned
// "[image N]" marker (attachment removed) and trims empty text, so an "[image 1]"-only draft resolves to nothing — this
// gates ONLY the send button (below), never the whole composer, so the user can still attach to an empty field. Cheap:
// builds block objects by reference (no byte encoding, unlike the full send plan).
function privateComposerHasSendableContent() {
  return composerBlocksFromDraft(messageInput?.value ?? '', privateImageAttachments, privatePaymentCheckDraft, privateReplyDraft, privateFileAttachments).length > 0;
}

function refreshPrivateSendButtonState() {
  const thread = activeThread();
  const reason = privateSendBlockReason(thread);
  const blocked = Boolean(reason);
  // Nothing real to send (empty draft, or an orphaned "[image N]" marker whose attachment was removed): disable ONLY
  // the send button, not the composer — so a stray marker can never be published into "Capsule publish payload is missing".
  const nothingToSend = !blocked && !privateComposerHasSendableContent();
  if (sendButton) {
    sendButton.disabled = blocked || nothingToSend;
    sendButton.title = reason ?? (nothingToSend ? t('composer.nothingToSend') : t('send.sendPrivateMessage'));
  }
  // The composer's secondary controls follow the SAME send-block state (owner: an inactive composer must not
  // show live-looking buttons). Every enable/disable path funnels here (this runs at the end of
  // refreshComposerCostStatus, so refreshComposerPublishPolicy / refreshMessagingControls / renderConversation
  // all converge on it) — scattered per-site predicates were the "some buttons stay active" bug. The text
  // INPUT deliberately stays on canEditPrivateComposerDraft: drafting while funding/activating is allowed
  // (PWA-ACTIVATION-02).
  if (privateEmojiButton) privateEmojiButton.disabled = blocked;
  if (privateComposerAddButton) {
    privateComposerAddButton.disabled = blocked;
    privateComposerAddButton.title = reason ?? t('composer.addImageOrCheck');
  }
  if (blocked) hidePrivateComposerAddMenu();
  if (paymentCheckButton) paymentCheckButton.disabled = blocked;
  if (privateImageButton) privateImageButton.disabled = blocked;
  if (privateFileButton) privateFileButton.disabled = blocked;
  // The eye lives in the same funnel (else it goes stale in BOTH directions on cost-status-only refresh
  // paths — e.g. typing past the part cap, or a Vault top-up re-read — and a stuck-disabled button can never
  // self-heal from its own click). The already-computed reason is passed through: no extra plan build.
  updatePrivateSenderModeUi(reason);
}

// The ONE public composer availability predicate — Publish and every secondary control read the same answer.
function publicComposerSendBlocked() {
  return !plathoWallet || !hasActivePlathoAccount() || pendingServiceWorkerAppShellReload || tonRpcLimited() || publicComposerKnownVaultTonShortfall();
}

function publicComposerHasSendableContent() {
  // Same canonical builder the public send path uses (publicDocumentBlocksFromDraft), so the button-disable and the
  // send match exactly: an orphaned "[image N]" marker resolves to no block -> button disabled.
  return publicDocumentBlocksFromDraft(publicMessageInput?.value ?? '').length > 0;
}

function refreshPublicSendButtonState() {
  const blocked = publicComposerSendBlocked();
  const publicSendButton = publicComposer?.querySelector?.('.send-button');
  // Symmetric with private: disable ONLY the Publish button (not the composer) when nothing real resolves to send.
  const nothingToSend = !blocked && !publicComposerHasSendableContent();
  if (publicSendButton) {
    publicSendButton.disabled = blocked || nothingToSend;
    publicSendButton.title = nothingToSend ? t('composer.nothingToSend') : '';
  }
  // Secondary controls follow the send state (owner: an inactive composer must not show live-looking
  // buttons) — mirrors the private composer's refreshPrivateSendButtonState. The label class mirrors the
  // checkbox's :disabled because the dim rule via :has() silently no-ops on the iOS floor (Safari 14).
  if (publicEmojiButton) publicEmojiButton.disabled = blocked;
  if (publicImageButton) publicImageButton.disabled = blocked;
  if (publicComposerAddButton) publicComposerAddButton.disabled = blocked;
  if (publicFileButton) publicFileButton.disabled = blocked;
  if (blocked) hidePublicComposerAddMenu();
  if (publicComposerCommentsCheckbox) publicComposerCommentsCheckbox.disabled = blocked;
  publicPostCommentsToggle?.classList.toggle('is-disabled', blocked);
}

async function assertVaultHasPrivatePublishHold(suite, plan, options = {}) {
  const provider = await resolveVaultChainProvider();
  const user = rememberConnectedVaultUser(options.allowOwnVaultActionReadFallback === false
    ? await loadConnectedVaultUser({ provider, ...criticalChainReadOptions() })
    : await readFreshConnectedVaultUserForOwnVaultAction(provider));
  if (user.exists !== true || BigInt(user.current_key_id ?? 0n) === 0n) {
    throw new Error('Activate Platho account before publishing');
  }
  const hold = composerEstimatedMaxChargeNanotons(privateComposerPublishProfilesForPlan(suite, plan), 1);
  const balance = vaultTonBalanceNanotons(user);
  if (balance < hold) {
    throw new Error(`Not enough Vault GRAM: need ${formatTonNanotons(hold)} GRAM hold, have ${formatTonNanotons(balance)} GRAM`);
  }
  return { user, hold, balance };
}

function estimatedUsernameMintTonFeeNanotons() {
  return USERNAME_MINT_VAULT_TON_CHARGE_NANOTONS;
}

function estimatedProfileAvatarTonFeeNanotons(attachment) {
  const plan = imagePartsForSend(attachment, 'profile avatar');
  const pricedProfiles = publicComposerPublishProfilesForPlan(plan);
  return composerEstimatedMaxChargeNanotons(pricedProfiles, 1)
    + PROFILE_AVATAR_VAULT_TON_CHARGE_NANOTONS;
}

function profileAvatarTonFeeLabel(attachment) {
  if (!attachment) return t('avatar.estimatedAfterCompression');
  const parts = Math.max(1, imageAttachmentPartCount(attachment));
  const capsuleLabel = tPlural('avatar.publicCapsules', parts);
  return t('avatar.feeUpTo', { amount: formatTonNanotons(estimatedProfileAvatarTonFeeNanotons(attachment)), capsules: capsuleLabel });
}

// Estimate the GRAM hold to PUBLISH a channel profile (a single public post carrying the PROFILE document block) so the
// edit dialog can show the cost the same way the mint / avatar modals do. Mirrors estimatedProfileAvatarTonFeeNanotons
// but for a document instead of an image: encode the SAME bytes publishChannelProfile will (incl. the owner-username
// trailer, which affects the byte size), split into capsule parts, and price the public batch. No extra Vault charge —
// a profile is a plain public post (createPublicPayloadParts type:'post'), unlike the avatar's ProfileRegistry write.
function estimatedChannelProfileHoldNanotons(description, tags) {
  const desc = String(description ?? '').trim();
  const normalizedTags = normalizeProfileTags(tags);
  const linkedLabel = readLinkedPlathoUsername(plathoWallet?.address)?.label ?? '';
  const ownerUsername = linkedLabel ? canonicalUsernameDisplay(linkedLabel) : '';
  const documentBytes = encodeMessageDocumentBlocks([{ type: 'profile', description: desc, tags: normalizedTags, ownerUsername }]);
  const parts = splitBytesToCapsuleParts(documentBytes, MAX_CAPSULE_USEFUL_BYTES);
  return composerEstimatedMaxChargeNanotons(publicComposerPublishProfilesForPlan(parts), 1);
}

function composerCostStatusText(profile, text, maxTextBytes, attachment = null, options = {}) {
  const parts = options.parts ?? composerTotalPartCount(text, attachment, maxTextBytes);
  const pricedProfile = options.pricedProfile ?? profile;
  if (!plathoWallet) {
    return {
      text: t('common.walletRequired'),
      state: 'short',
      parts,
    };
  }
  if (options.ignoreTonRpcLimit !== true && tonRpcLimited()) {
    return {
      text: TON_RPC_CONNECTING_STATUS,
      state: 'short',
      parts,
    };
  }
  if (pendingServiceWorkerAppShellReload === true) {
    return {
      text: t('common.updateReadyReload'),
      state: 'short',
      parts,
    };
  }
  const price = composerEstimatedNetCostNanotons(pricedProfile, parts);
  const hold = composerEstimatedMaxChargeNanotons(pricedProfile, parts);
  const surchargeParts = Array.isArray(pricedProfile)
    ? pricedProfile.length
    : Math.max(1, Number(parts) || 1);
  const surcharge = currentNetworkFeeSurchargeNanotons() * BigInt(surchargeParts);
  const surchargeText = surcharge > 0n ? t('composer.networkSurchargeSuffix', { amount: formatTonNanotons(surcharge) }) : '';
  const user = currentVaultUserSource();
  // No Vault hold under direct-pay (see composerKnownVaultTonShortfall) — do not show the "need hold … vault 0" warning.
  if (!privateLaneDirectPayEnabled() && user?.exists === true && vaultTonBalanceNanotons(user) < hold) {
    return {
      text: t('composer.needHoldStatus', { hold: formatTonNanotons(hold), vault: formatTonNanotons(vaultTonBalanceNanotons(user)) }),
      state: 'short',
      parts,
    };
  }
  return {
    text: t('composer.costHoldStatus', { cost: formatTonNanotons(price), hold: formatTonNanotons(hold), surcharge: surchargeText, discount: formatAthDiscountLabel() }),
    state: 'ready',
    parts,
  };
}

function refreshComposerCostStatus() {
  if (privateComposerCostStatus) {
    const privatePlan = privateComposerSendPlan(messageInput?.value ?? '', privateImageAttachments, currentPrivateSenderOptions(), {
      paymentCheck: privatePaymentCheckDraft,
    });
    const limitMessage = privateComposerPartLimitMessage(privatePlan.length);
    const blockReason = privateSendBlockReason(activeThread(), { includeVaultShortfall: false });
    const status = blockReason
      ? { text: blockReason, state: 'short' }
      : limitMessage
      ? { text: limitMessage, state: 'short' }
      : composerCostStatusText(
        privateComposerPublishProfile(),
        messageInput?.value ?? '',
        SINGLE_CAPSULE_USEFUL_BYTES,
        privateImageAttachments[0] ?? null,
        {
          parts: Math.max(1, privatePlan.length),
          pricedProfile: privateComposerPublishProfilesForPlan(currentOutgoingPrivateSuite(), privatePlan),
          ignoreTonRpcLimit: true,
        },
      );
    privateComposerCostStatus.textContent = status.text;
    privateComposerCostStatus.dataset.state = status.state;
  }
  refreshPrivateSendButtonState();
  if (publicComposerCostStatus) {
    const publicPlan = publicComposerSendPlan(publicMessageInput?.value ?? '', publicImageAttachments);
    // Part-cap gate (v648, symmetric with the private branch above): an over-limit draft shows the split-it
    // message instead of a price, and the submit path re-checks before anything clears or signs.
    const publicLimitMessage = publicComposerPartLimitMessage(publicPlan.length);
    const status = publicLimitMessage
      ? { text: publicLimitMessage, state: 'short' }
      : composerCostStatusText(
        publicComposerPublishProfile(),
        publicMessageInput?.value ?? '',
        PUBLIC_POST_TEXT_MAX_BYTES,
        publicImageAttachments,
        {
          parts: Math.max(1, publicPlan.length),
          pricedProfile: publicComposerPublishProfilesForPlan(publicPlan),
        },
      );
    publicComposerCostStatus.textContent = status.text;
    publicComposerCostStatus.dataset.state = status.state;
  }
  refreshPublicSendButtonState();
}

function normalizePublicSyncWindow(value) {
  const text = String(value ?? 'short').toLowerCase();
  if (text === 'all' || text === 'long') return 'long';
  return 'short';
}

function readPublicSyncWindow() {
  try {
    return normalizePublicSyncWindow(localStorageOrNull()?.getItem(PUBLIC_SYNC_WINDOW_STORAGE_KEY));
  } catch {
    return 'short';
  }
}

function writePublicSyncWindow(value) {
  const normalized = normalizePublicSyncWindow(value);
  try {
    localStorageOrNull()?.setItem(PUBLIC_SYNC_WINDOW_STORAGE_KEY, normalized);
  } catch {
    // Non-persistent mode still applies the visible selection for this tab.
  }
  return normalized;
}

function normalizePublicCommentsDefault(value) {
  const text = String(value ?? 'disabled').toLowerCase();
  return ['enabled', 'disabled'].includes(text) ? text : 'disabled';
}

function readPublicCommentsDefault() {
  try {
    return normalizePublicCommentsDefault(localStorageOrNull()?.getItem(PUBLIC_COMMENTS_DEFAULT_STORAGE_KEY));
  } catch {
    return 'disabled';
  }
}

function writePublicCommentsDefault(value) {
  const normalized = normalizePublicCommentsDefault(value);
  try {
    localStorageOrNull()?.setItem(PUBLIC_COMMENTS_DEFAULT_STORAGE_KEY, normalized);
  } catch {
    // Non-persistent mode still applies the visible selection for this tab.
  }
  return normalized;
}

function publicCommentsDefaultLabel(value = readPublicCommentsDefault()) {
  return normalizePublicCommentsDefault(value) === 'disabled' ? t('public.commentsClosedStatus') : t('public.commentsAllowedStatus');
}

function updatePublicCommentsDefaultUi() {
  const value = readPublicCommentsDefault();
  if (publicCommentsDefaultSelect) publicCommentsDefaultSelect.value = value;
  if (!publicCommentTarget && publicComposerCommentsCheckbox) publicComposerCommentsCheckbox.checked = value !== 'disabled';
  updatePublicCommentsToggleUi();
}

// Keep the comments toggle's title/aria-label reflecting its state (the visual is the accent-vs-muted
// + slash styling; this makes the state explicit for hover and screen readers too).
function updatePublicCommentsToggleUi() {
  if (!publicPostCommentsToggle) return;
  const on = publicComposerCommentsCheckbox?.checked !== false;
  const label = on ? t('public.commentsOnTapOff') : t('public.commentsOffTapOn');
  publicPostCommentsToggle.setAttribute('aria-label', label);
  publicPostCommentsToggle.title = label;
}

function publicSyncWindowLabel(value = readPublicSyncWindow()) {
  const normalized = normalizePublicSyncWindow(value);
  return normalized === 'long' ? t('public.longHistory') : t('public.shortHistory');
}

function publicSyncCutoffMs(value = readPublicSyncWindow()) {
  normalizePublicSyncWindow(value);
  return null;
}

function updatePublicSyncWindowUi() {
  const windowValue = readPublicSyncWindow();
  if (publicSyncWindowSelect) publicSyncWindowSelect.value = windowValue;
}

function isFreshPublicTimestamp(value, cutoffMs = publicSyncCutoffMs()) {
  if (cutoffMs === null) return true;
  if (!value) return true;
  const timestamp = new Date(value).getTime();
  if (Number.isNaN(timestamp)) return true;
  return timestamp >= cutoffMs;
}

// --- WYSIWYG composer editor (v771) --------------------------------------------------------------------------
// Each composer is a contenteditable .composer-input div. It SERIALIZES to the exact same markdown+marker string
// the old <textarea>.value produced, so composerBlocksFromDraft / the size-cost plan / the submit capture / the
// receive renderer all keep working UNCHANGED. Rules that keep the DOM tractable + safe:
//  - Inline formatting = CLASS spans (.fmt-bold / .fmt-italic / .fmt-code) — never inline styles (prod CSP
//    style-src 'self') and never execCommand.
//  - Attachment markers = ATOMIC contenteditable=false chips carrying data-marker="[image N]" — the user can't
//    split "[image" / "N]" and orphan it (the v769 marker-corruption class of bug, closed by construction).
//  - Line breaks = <br>. Enter is intercepted so the browser never inserts <div>/<p> blocks; a stray block from
//    paste is still tolerated by the serializer (treated as a newline boundary).
//  - Paste/drop are sanitized to text/plain; IME composition is guarded (the isComposing keydown check).

// Serialize a composer editor's DOM back to the plain markdown+marker string that the send pipeline reads.
// keepTrailingBr: normally the editor's OWN trailing <br> is an invisible filler and is dropped. The copy/cut path
// serializes a cloned SELECTION where a trailing <br> is a REAL newline the user selected, so it passes true.
function serializeComposerEditor(el, keepTrailingBr = false) {
  if (!el) return '';
  // Serialize a node's children to markdown. `delim` is the emphasis delimiter that wraps the caller's
  // formattable text runs (''=root/none). A .fmt-* span emits `delim` around each maximal run of formattable
  // content, and a HARD boundary — a <br> (newline), an atom marker chip, or a DIV/P block — SPLITS that run
  // (flush closes the open delimiter, the boundary is emitted RAW, a new run reopens after). This guarantees a
  // delimiter never spans a newline or straddles a marker (both serialize to unbalanced `**` the recipient shows
  // as literal asterisks), and an EMPTY span (seg stays '') emits NOTHING (no stray `****`). Balanced by
  // construction — no editor DOM state, however it was produced (a caret-trapped <br>, a leftover empty span, a
  // marker pasted inside bold), can emit corrupt emphasis on the wire. Byte-identical to the old serializer for
  // any well-formed draft (a single-line, boundary-free span).
  const serChildren = (node, delim) => {
    let out = '';
    let seg = '';
    const flush = () => { if (seg !== '') { out += delim + seg + delim; seg = ''; } };
    for (const child of node.childNodes) {
      if (child.nodeType === 3) { // text
        seg += child.nodeValue;
      } else if (child.nodeType === 1) { // element
        const tag = child.tagName;
        const cls = child.classList;
        if (tag === 'BR') {
          // A trailing <br> that is the editor's own last child is the "filler" break browsers (and our Enter
          // handler) leave to make the final empty line visible — it is not real content, so drop it.
          if (!keepTrailingBr && node === el && !child.nextSibling) { /* filler trailing br */ }
          else { flush(); out += '\n'; }
        } else if (child.dataset && child.dataset.marker) {
          flush(); out += child.dataset.marker; // atomic attachment/link chip -> its [marker], never inside emphasis
        } else if (cls.contains('fmt-bold')) {
          seg += serChildren(child, '**');
        } else if (cls.contains('fmt-italic')) {
          seg += serChildren(child, '*');
        } else if (cls.contains('fmt-code')) {
          seg += serChildren(child, '`');
        } else if (tag === 'DIV' || tag === 'P') {
          // A block boundary (browser/paste inserted one despite the Enter intercept) -> newline before content.
          flush();
          if (out && !out.endsWith('\n')) out += '\n';
          out += serChildren(child, ''); // block content, no wrapping delimiter
        } else {
          seg += serChildren(child, ''); // unknown wrapper (e.g. a plain <span> from paste) -> just its content
        }
      }
    }
    flush();
    return out;
  };
  return serChildren(el, '');
}

// Build the EDITABLE DOM for a composer editor from a markdown+marker string (draft restore / share insertion).
// Inverse of serializeComposerEditor: **bold** -> <span class=fmt-bold>, [image N] -> chip, \n -> <br>. Uses the
// SAME inline tokenizer family as the renderer but emits editor spans/chips (not the receive-side anchors).
const EDITOR_INLINE_RE = /\*\*\*([^*\n]+)\*\*\*|\*\*([^*\n]+)\*\*|\*([^*\n]+)\*|`([^`\n]+)`|(\[(?:image|img)\s+\d+\]|\[file\s+\d+\]|\[post\]|\[(?:check|payment)\])(?!\()|\[([^\]\n]{1,200})\]\(([^\s()]{1,2000})\)/g;

function composerChipLabelForMarker(marker) {
  const m = String(marker);
  if (/^\[(?:image|img)\s+\d+\]$/i.test(m)) return t('composer.image');
  if (/^\[file\s+\d+\]$/i.test(m)) return t('composer.file');
  if (/^\[post\]$/i.test(m)) return t('public.sharedPost');
  if (/^\[(?:check|payment)\]$/i.test(m)) return t('payment.paymentCheck');
  return m;
}

// v773: resolve a composer editor to the attachment arrays / drafts its markers point at, so the editor can
// render each marker as its REAL content (image/file/payment/share) live — WYSIWYG, no separate preview.
function composerBlockContextForEditor(el) {
  if (el === publicMessageInput) {
    return { kind: 'public', images: publicImageAttachments, files: publicFileAttachments, payment: null, share: publicShareDraft };
  }
  return { kind: 'private', images: privateImageAttachments, files: privateFileAttachments, payment: privatePaymentCheckDraft, share: privateShareDraft };
}

// The rich inner node a marker renders as (real image / file chip / payment card / shared-post embed), or null
// when the attachment/draft can't be resolved (an orphan marker) so the caller falls back to a labeled pill.
function composerBlockInner(marker, ctx) {
  let m;
  if ((m = marker.match(/^\[(?:image|img)\s+(\d+)\]$/i))) {
    const att = ctx.images?.[Number(m[1]) - 1];
    if (!att?.bytes?.length) return null;
    const img = document.createElement('img');
    img.className = 'composer-block-image';
    img.src = bytesToImageDataUrl(att.bytes, 'image/webp');
    img.alt = String(att.name ?? '');
    img.draggable = false;
    return img;
  }
  if ((m = marker.match(/^\[file\s+(\d+)\]$/i))) {
    const att = ctx.files?.[Number(m[1]) - 1];
    if (!att) return null;
    const chip = document.createElement('span');
    chip.className = 'composer-block-file';
    const icon = document.createElement('span'); icon.className = 'icon icon-download';
    const name = document.createElement('span'); name.className = 'message-file-name'; name.textContent = String(att.name ?? t('chat.fileFallbackName'));
    const size = document.createElement('span'); size.className = 'message-file-size'; size.textContent = imageByteCountLabel(att.bytes?.length ?? 0);
    chip.append(icon, name, size);
    return chip;
  }
  if (/^\[post\]$/i.test(marker)) {
    if (!ctx.share?.entryId) return null;
    return buildSharedPostEmbed(ctx.share);
  }
  return null;
}

// An atomic (contenteditable=false) editor block carrying data-marker (so serializeComposerEditor round-trips it
// unchanged) whose visual is the REAL content, or a labeled pill fallback. Inner is display-only (CSS neutralizes
// its pointer events) so the block behaves as one selectable/deletable unit.
function buildComposerBlock(marker, el) {
  const block = document.createElement('div');
  block.className = 'composer-block';
  block.contentEditable = 'false';
  block.dataset.marker = String(marker);
  const inner = el ? composerBlockInner(String(marker), composerBlockContextForEditor(el)) : null;
  if (inner) {
    block.append(inner);
  } else {
    block.classList.add('composer-block-pill');
    block.textContent = composerChipLabelForMarker(marker);
  }
  return block;
}

// A link renders live in the editor as a styled, atomic (contenteditable=false) chip showing the LABEL, with
// data-marker = the `[label](url)` markdown so serializeComposerEditor round-trips it as plain text — the recipient
// side (appendInlineFormatted) turns that text into the interstitial link. No live href in the editor.
function buildComposerLinkBlock(markup, label) {
  const block = document.createElement('span');
  block.className = 'composer-block composer-block-link';
  block.contentEditable = 'false';
  block.dataset.marker = String(markup);
  block.textContent = String(label || markup);
  return block;
}

// A finished link chip is contenteditable=false (atomic), so it can't be edited by typing. Clicking it re-opens the
// link dialog pre-filled with its label + url and replaces the chip in place on save — the only way to fix a link.
function composerEditorLinkClick(el, event) {
  if (!el || el.disabled) return;
  const chip = event.target?.closest?.('.composer-block-link');
  if (!chip || !el.contains(chip)) return;
  event.preventDefault();
  openLinkComposerDialog(el, chip);
}

// Copy/cut: the native clipboard drops a contenteditable=false chip (so a copied link/image/etc. lost its marker and
// vanished on paste). Serialize the SELECTED fragment to the SAME markdown+marker string the editor uses, so EVERY
// atom the selection spans (link/image/file/payment/post) round-trips its marker. A LINK re-renders as a live chip on
// paste; attachment markers paste as LITERAL text (their bytes can't ride a text clipboard, and a live re-render would
// phantom-bind the editor's own attachment — see composerEditorInsertPlainMultiline). text/plain only — no clipboard HTML.
function composerEditorCopySelection(el, event, isCut) {
  if (!el || !event.clipboardData) return;
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0 || sel.isCollapsed) return; // nothing selected -> let the browser handle it
  const range = sel.getRangeAt(0);
  if (!el.contains(range.commonAncestorContainer)) return;
  const wrapper = document.createElement('div');
  wrapper.appendChild(range.cloneContents()); // includes any atom chip the selection spans (contenteditable=false = atomic)
  // Keep a real trailing newline the user selected, but NOT the editor's invisible filler <br> (only cloned when the
  // selection reaches the editor's very end).
  const fillerBr = el.lastChild && el.lastChild.nodeName === 'BR' && !el.lastChild.nextSibling ? el.lastChild : null;
  const keepTrailingBr = !(fillerBr && range.intersectsNode(fillerBr));
  event.clipboardData.setData('text/plain', serializeComposerEditor(wrapper, keepTrailingBr));
  event.preventDefault();
  if (isCut && !el.disabled) {
    // An ATTACHMENT chip's BYTES can't ride a text clipboard, so Cut-then-Paste would silently LOSE the image/file:
    // deleting the atom drops its marker, and reconcileComposerAttachments then prunes the marker-less attachment.
    // Treat a cut that spans an attachment atom ([image N]/[file N]/[post]/[check], NOT a `](`-link which DOES
    // round-trip) as a COPY — leave the original in place so nothing is lost. Text-only / link-only cuts still delete.
    const hasAttachmentAtom = [...wrapper.querySelectorAll('[data-marker]')].some((a) => !/\]\(/.test(a.dataset.marker || ''));
    if (!hasAttachmentAtom) {
      range.deleteContents();
      composerEditorPruneEmptyFmt(el); // a cut that emptied a fmt span would else serialize to a stray `****`
      composerEditorAfterEdit(el); // input -> reconcileComposerAttachments prunes any cut atom's attachment
    }
  }
}

// context (default: target) is the editor element a marker atom resolves its attachment against — pass the real
// editor when building into a detached fragment. renderAttachmentMarkers=false keeps a literal [image N]/[file N]/
// [post]/[check] as PLAIN TEXT (paste path): rendering it as a live atom would bind a pasted token to the editor's
// OWN attachment -> a phantom duplicate whose Backspace deletes the real attachment. Links still render.
function appendEditorInline(target, text, context = target, renderAttachmentMarkers = true) {
  const str = String(text ?? '');
  if (!str) return;
  EDITOR_INLINE_RE.lastIndex = 0;
  let last = 0;
  let match;
  while ((match = EDITOR_INLINE_RE.exec(str)) !== null) {
    if (match.index > last) target.append(document.createTextNode(str.slice(last, match.index)));
    if (match[1] !== undefined) { // ***bold+italic*** -> nested fmt-bold > fmt-italic
      const b = document.createElement('span'); b.className = 'fmt-bold';
      const i = document.createElement('span'); i.className = 'fmt-italic'; i.textContent = match[1];
      b.append(i); target.append(b);
    }
    else if (match[2] !== undefined) { const s = document.createElement('span'); s.className = 'fmt-bold'; s.textContent = match[2]; target.append(s); }
    else if (match[3] !== undefined) { const s = document.createElement('span'); s.className = 'fmt-italic'; s.textContent = match[3]; target.append(s); }
    else if (match[4] !== undefined) { const s = document.createElement('span'); s.className = 'fmt-code'; s.textContent = match[4]; target.append(s); }
    else if (match[5] !== undefined) { target.append(renderAttachmentMarkers ? buildComposerBlock(match[5], context) : document.createTextNode(match[5])); }
    else { target.append(buildComposerLinkBlock(`[${match[6]}](${match[7]})`, match[6])); } // [label](url) link chip
    last = match.index + match[0].length;
  }
  if (last < str.length) target.append(document.createTextNode(str.slice(last)));
}

function buildComposerEditorDom(el, text) {
  el.replaceChildren();
  const lines = String(text ?? '').split('\n');
  lines.forEach((line, index) => {
    if (index > 0) el.append(document.createElement('br'));
    appendEditorInline(el, line);
  });
}


// --- Editor caret ops (v771) ---------------------------------------------------------------------------------
// Range-based insert/format for the contenteditable composer. All of them end with composerEditorAfterEdit() so
// the size/cost/send-enable pipeline (an 'input' listener) stays in sync and the placeholder tracks correctly.

// The live Range if the caret sits inside the editor, else a collapsed caret at the very end of the editor.
function composerEditorRange(el) {
  const sel = window.getSelection();
  if (sel && sel.rangeCount) {
    const range = sel.getRangeAt(0);
    if (el.contains(range.commonAncestorContainer)) return range;
  }
  const range = document.createRange();
  range.selectNodeContents(el);
  range.collapse(false);
  return range;
}

function composerEditorPlaceCaretAfter(node) {
  const sel = window.getSelection();
  if (!sel) return;
  const range = document.createRange();
  range.setStartAfter(node);
  range.collapse(true);
  sel.removeAllRanges();
  sel.addRange(range);
}

function composerEditorAfterEdit(el) {
  el.classList.toggle('is-empty', serializeComposerEditor(el).trim() === '');
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function composerEditorInsertText(el, text) {
  if (!el || el.disabled) return;
  el.focus();
  const range = composerEditorRange(el);
  range.deleteContents();
  const node = document.createTextNode(String(text ?? ''));
  range.insertNode(node);
  composerEditorPlaceCaretAfter(node);
  composerEditorAfterEdit(el);
}

// If the collapsed caret is ANYWHERE inside a .fmt-* span, move it OUT of the OUTERMOST such span. A newline or an
// attachment marker inserted WHILE the caret is inside the span would otherwise be trapped in the formatting: a marker
// inside bold serializes to `**…[image N]…**` which composerBlocksFromDraft splits into UNBALANCED `**` blocks, and a
// `<br>` inside bold serializes to `**…\n…**` which the recipient can't match (bold cannot span a newline) — both show
// literal asterisks. So Enter/attachment always land OUTSIDE the word's formatting. (Since v779 the caret can rest
// MID-word after a toggle, so we escape the whole span, not just its trailing edge.) DIRECTION: at the span's LEADING
// edge (nothing before the caret inside it — e.g. Enter at the START of a bold heading) escape to BEFORE the span, so
// the new line/marker lands ABOVE/before the word; otherwise (mid/trailing) escape to AFTER it.
function composerEditorEscapeTrailingFmt(el) {
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return;
  const range = sel.getRangeAt(0);
  if (!range.collapsed) return;
  const isFmt = (n) => n && n.nodeType === 1 && /\bfmt-/.test(n.className || '');
  let n = range.startContainer;
  let span = null;
  while (n && n !== el) {
    if (isFmt(n)) span = n;    // the OUTERMOST .fmt-* ancestor of the caret (nested bold>italic escapes ALL the way)
    n = n.parentNode;
  }
  if (!span) return;
  const lead = document.createRange(); // is there any content BEFORE the caret inside the span?
  lead.setStart(span, 0);
  lead.setEnd(range.startContainer, range.startOffset);
  const before = lead.cloneContents();
  const atLeadingEdge = before.textContent === '' && !before.querySelector('br, [data-marker]');
  const r = document.createRange();
  if (atLeadingEdge) r.setStartBefore(span); else r.setStartAfter(span);
  r.collapse(true);
  sel.removeAllRanges();
  sel.addRange(r);
}

// Drop any .fmt-* span a deletion emptied (e.g. replacing the selected bold word with a link removes the span's text
// but leaves the span): an empty fmt span serializes to a stray `****` / `**` the recipient shows as literal asterisks.
// Skips spans still holding a <br> or a marker atom, and spans whose parent was already pruned (isConnected).
function composerEditorPruneEmptyFmt(el) {
  for (const span of [...el.querySelectorAll('[class*="fmt-"]')]) {
    if (!span.isConnected) continue;
    if (/\bfmt-/.test(span.className || '') && span.textContent === '' && !span.querySelector('br, [data-marker]')) span.remove();
  }
}

// Our composer expresses formatting ONLY as `.fmt-*` CLASS spans applied via the toolbar — it NEVER creates native
// <b>/<strong>/<i>/<em>/<u>/<font> elements or inline font-weight/font-style styles. So any of those in the DOM is a
// contentEditable "typing style" ARTIFACT: after Backspace-deleting a bold word the browser keeps queryCommandState
// ('bold')===true, so the NEXT native keystroke wraps the char in the browser's OWN bold element. That looks bold,
// serialized to `**` the user never asked for, AND the `.fmt-*` toggle can't SEE it (so pressing Bold ADDs a
// `.fmt-bold` layer -> `****` instead of removing) — the owner bug "delete all, type -> bold, Bold does nothing".
// Unwrap every native format element on `input`, keeping its text (moving the text nodes preserves the caret), so
// typed text is PLAIN unless the toolbar formatted it as a `.fmt-*` span. Never touches our `.fmt-*` spans or chips.
function composerEditorStripNativeFormatting(el) {
  if (!el) return;
  const natives = el.querySelectorAll('b, strong, i, em, u, s, font, [style*="font-weight"], [style*="font-style"], [style*="text-decoration"]');
  for (const node of natives) {
    if (!node.isConnected || node.nodeType !== 1) continue;
    if (/\bfmt-/.test(node.className || '')) continue; // our own toolbar span — keep
    if (node.closest && node.closest('[data-marker]')) continue; // inside an atom chip — leave it alone
    while (node.firstChild) node.parentNode.insertBefore(node.firstChild, node);
    node.remove();
  }
}

// After a NATIVE edit (Backspace/Delete emptying a formatted word, or a selection-replace) an emptied .fmt-* span
// can linger with the caret INSIDE it: subsequent typing then inherits the format, the word-toggle can't find a
// word to un-format (composerEditorWordRangeAtCaret needs a text-node caret), and the span serializes to a stray
// delimiter pair. Drop every empty fmt span and, when the caret was inside one, place the caret where the span
// was so the next keystroke is plain. Called from the editors' 'input' listener (after the native edit lands).
function composerEditorNormalizeEmptyFmt(el) {
  if (!el) return;
  // If the editor has NO text at all (everything was deleted), strip EVERY lingering fmt span — even one holding
  // just a <br>/whitespace — so the next keystroke types PLAIN. A native select-all+Delete on a bold message can
  // leave a `<span class="fmt-bold"><br></span>` behind that captures new typing (owner bug: "delete everything,
  // type again -> it types bold"). Then park the caret at the start of the now-clean empty editor.
  if ((el.textContent || '').trim() === '') {
    let strippedFmt = false;
    el.querySelectorAll('[class*="fmt-"]').forEach((span) => {
      if (!span.isConnected || !/\bfmt-/.test(span.className || '')) return;
      while (span.firstChild) span.parentNode.insertBefore(span.firstChild, span);
      span.remove();
      strippedFmt = true;
    });
    if (strippedFmt) {
      const sel = window.getSelection();
      if (sel) { const r = document.createRange(); r.setStart(el, 0); r.collapse(true); sel.removeAllRanges(); sel.addRange(r); }
    }
    return;
  }
  const empties = [...el.querySelectorAll('[class*="fmt-"]')].filter((s) =>
    s.isConnected && /\bfmt-/.test(s.className || '') && s.textContent === '' && !s.querySelector('br, [data-marker]'));
  if (!empties.length) return;
  const sel = window.getSelection();
  let caretSpan = null; // the empty span the caret currently sits inside (if any)
  if (sel && sel.rangeCount) {
    let n = sel.getRangeAt(0).startContainer;
    while (n && n !== el) { if (empties.includes(n)) { caretSpan = n; break; } n = n.parentNode; }
  }
  let anchorParent = null, anchorNext = null;
  if (caretSpan) {
    anchorParent = caretSpan.parentNode;
    anchorNext = caretSpan.nextSibling;
    while (anchorNext && empties.includes(anchorNext)) anchorNext = anchorNext.nextSibling; // skip siblings we also remove
  }
  empties.forEach((s) => s.remove());
  if (caretSpan && anchorParent && anchorParent.isConnected && sel) {
    const r = document.createRange();
    if (anchorNext && anchorNext.parentNode === anchorParent) r.setStartBefore(anchorNext);
    else r.setStart(anchorParent, anchorParent.childNodes.length);
    r.collapse(true);
    sel.removeAllRanges(); sel.addRange(r);
  }
}

// After a selection is deleted, the collapsed caret may sit inside a NON-empty fmt span (a partial selection of a
// multi-word bold/italic run). Split that span at the caret — the text AFTER the caret moves into a sibling clone
// with the same formatting — and leave the caret BETWEEN the two halves. So a link inserted here lands at the true
// selection point with the surrounding text kept in order, instead of after the whole span (which silently reversed
// word order for a non-trailing partial selection). No-op if the caret is not inside a fmt span.
function composerEditorSplitFmtAtCaret(el) {
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return;
  const caret = sel.getRangeAt(0);
  if (!caret.collapsed) return;
  const isFmt = (n) => n && n.nodeType === 1 && /\bfmt-/.test(n.className || '');
  let n = caret.startContainer, span = null;
  while (n && n !== el) { if (isFmt(n)) span = n; n = n.parentNode; } // outermost enclosing fmt span
  if (!span) return;
  const tail = document.createRange();
  tail.setStart(caret.startContainer, caret.startOffset);
  tail.setEnd(span, span.childNodes.length); // caret -> end of the span's content
  const afterFrag = tail.extractContents();
  if (afterFrag && afterFrag.textContent !== '') {
    const afterSpan = span.cloneNode(false); // same fmt-* class, no children
    afterSpan.appendChild(afterFrag);
    span.after(afterSpan);
  }
  const r = document.createRange();
  r.setStartAfter(span); // between the before-span and the after-span; an emptied before-span is pruned later
  r.collapse(true);
  sel.removeAllRanges();
  sel.addRange(r);
}

// Enter INSIDE a bold/italic word must SPLIT the fmt span so the second half wraps to the new line KEEPING its format
// (`**hel**\n**lo**` = two balanced spans), not jump the caret to the word end. Returns true if it split (caret was
// MID-word). A leading/trailing edge (or no fmt span) returns false so composerEditorInsertLineBreak falls back to
// composerEditorEscapeTrailingFmt (leading -> line ABOVE the word; trailing -> plain line below).
function composerEditorSplitFmtForNewlineIfMidWord(el) {
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return false;
  const range = sel.getRangeAt(0);
  if (!range.collapsed) return false;
  const isFmt = (n) => n && n.nodeType === 1 && /\bfmt-/.test(n.className || '');
  let n = range.startContainer, span = null;
  while (n && n !== el) { if (isFmt(n)) span = n; n = n.parentNode; } // outermost enclosing fmt span
  if (!span) return false;
  const emptyRun = (from, fromOff, to, toOff) => {
    const r = document.createRange(); r.setStart(from, fromOff); r.setEnd(to, toOff);
    const frag = r.cloneContents();
    return frag.textContent === '' && !frag.querySelector('br, [data-marker]');
  };
  const nothingBefore = emptyRun(span, 0, range.startContainer, range.startOffset);
  const nothingAfter = emptyRun(range.startContainer, range.startOffset, span, span.childNodes.length);
  if (nothingBefore || nothingAfter) return false; // leading / trailing edge -> let escapeTrailingFmt place it
  composerEditorSplitFmtAtCaret(el); // MID-word: split into two same-format halves, caret between them
  return true;
}

function composerEditorInsertLineBreak(el) {
  if (!el || el.disabled) return;
  el.focus();
  // A NON-COLLAPSED selection must be collapsed to its END first (mirrors composerEditorInsertChip). The common
  // case is the whole word staying selected right after a Bold/Italic toggle: without this the split/escape guards
  // both bail on !collapsed, then range.deleteContents() below STRIPS the word and drops the <br> INSIDE the now-
  // empty .fmt-* span (`**\n\n**` = unbalanced bold + lost text). Collapse (not delete) so the word is KEPT — a
  // post-toggle artifact selection is indistinguishable from a deliberate one, and losing text on Enter is worse.
  const sel = window.getSelection();
  if (sel && sel.rangeCount && !sel.isCollapsed && el.contains(sel.getRangeAt(0).commonAncestorContainer)) {
    const r = sel.getRangeAt(0); r.collapse(false); sel.removeAllRanges(); sel.addRange(r);
  }
  // MID-word Enter in a bold/italic word SPLITS it (second half wraps down, still formatted); a leading/trailing edge
  // (or plain text) falls back to escapeTrailingFmt (line ABOVE the word / plain line below) so a `<br>` never lands
  // INSIDE the formatting (which would serialize to unbalanced ** across the newline).
  if (!composerEditorSplitFmtForNewlineIfMidWord(el)) composerEditorEscapeTrailingFmt(el);
  composerEditorPruneEmptyFmt(el); // drop any span a prior edit emptied so Enter never emits a stray `****` line
  const range = composerEditorRange(el);
  range.deleteContents();
  const br = document.createElement('br');
  range.insertNode(br);
  // A prior split/extract/escape can leave an EMPTY text node right after the caret. It makes br.nextSibling
  // non-null, so the trailing filler <br> below is skipped and the new line never becomes VISIBLE (owner bug: the
  // FIRST Enter did nothing, a SECOND added the line). Drop those empties so the filler check sees the <br> as last.
  while (br.nextSibling && br.nextSibling.nodeType === 3 && br.nextSibling.nodeValue === '') br.nextSibling.remove();
  if (!br.nextSibling) br.after(document.createElement('br'));
  composerEditorPlaceCaretAfter(br);
  composerEditorAfterEdit(el);
}

// Insert an atomic attachment/link block (the rich content) at the caret. It is inline-block, so it sits in the
// text flow and Backspace right after it deletes it as one unit (handled in composerEditorBeforeInput).
function composerEditorInsertChip(el, marker) {
  if (!el || el.disabled) return;
  el.focus();
  // Attach at the caret WITHOUT deleting a live selection — a selection sitting inside a .fmt-* span (toggleFormat
  // leaves the formatted word selected) would otherwise be replaced by the marker INSIDE the span (lost text +
  // unbalanced ** on send). Collapse to the selection end first, then escape any trailing fmt span.
  const sel = window.getSelection();
  if (sel && sel.rangeCount && !sel.isCollapsed) { const r = sel.getRangeAt(0); r.collapse(false); sel.removeAllRanges(); sel.addRange(r); }
  composerEditorEscapeTrailingFmt(el); // never drop an attachment marker INSIDE a fmt span (unbalanced ** on send)
  const range = composerEditorRange(el);
  range.deleteContents();
  const block = buildComposerBlock(marker, el);
  range.insertNode(block);
  composerEditorPlaceCaretAfter(block);
  composerEditorAfterEdit(el);
}

// Insert a link chip (the "Insert link" dialog). Restores the caret the dialog stole (savedRange) so the link lands
// where the user was typing, not at the start. If the user had a SELECTION, the link REPLACES it (the selected word
// was pre-filled as the link text). Either way the link must land OUTSIDE any enclosing .fmt-* span: a link chip
// trapped inside **…**/*…*/`…` serializes to `**[label](url)**`, and the recipient's inline regex matches the outer
// **…** first — rendering the marker as literal bold/italic text, a DEAD non-clickable link on the wire.
function composerEditorInsertLinkBlock(el, markup, label, savedRange) {
  if (!el || el.disabled) return;
  el.focus();
  if (savedRange) { const s = window.getSelection(); s.removeAllRanges(); s.addRange(savedRange); }
  const sel = window.getSelection();
  const hadSelection = sel && sel.rangeCount && !sel.isCollapsed;
  if (hadSelection) {
    sel.getRangeAt(0).deleteContents(); // the link REPLACES the selection
    // Caret now sits where the selection was — maybe inside the fmt span it was part of. SPLIT that span at the caret
    // so the link lands AT the selection point and the before/after text keeps its order + formatting (escaping to
    // after the WHOLE span would reverse word order for a non-trailing partial selection).
    composerEditorSplitFmtAtCaret(el);
  } else {
    // Bare caret in a bold/italic word: put the link AFTER the whole word rather than splitting it mid-way.
    composerEditorEscapeTrailingFmt(el);
  }
  const range = composerEditorRange(el);
  range.deleteContents();
  const block = buildComposerLinkBlock(markup, label);
  range.insertNode(block); // lands between the before/after fmt spans (or after a bare word), never inside formatting
  composerEditorPruneEmptyFmt(el); // remove a fmt span the split/deletion emptied BEFORE it serializes to a stray `****`
  composerEditorPlaceCaretAfter(block);
  composerEditorAfterEdit(el);
}

// Re-render the editor's marker blocks against the CURRENT attachments/drafts (after a compression-mode change or
// a removal): rebuilds from the serialized value so every [image N]/[file N]/[check]/[post] atom re-resolves.
// Only called on non-typing panel interactions (caret loss is fine there), never on keystrokes.
function refreshComposerEditorBlocks(el) {
  if (!el || el.dataset?.editorReady !== '1') return;
  el.value = serializeComposerEditor(el);
}

function composerEditorIsAtom(node) {
  return Boolean(node && node.nodeType === 1 && node.dataset && node.dataset.marker);
}

// The atom immediately before (dir<0) or after (dir>0) a COLLAPSED caret, else null.
function composerEditorAdjacentAtom(range, el, dir) {
  const c = range.startContainer;
  const off = range.startOffset;
  if (c === el) {
    const node = dir < 0 ? el.childNodes[off - 1] : el.childNodes[off];
    return composerEditorIsAtom(node) ? node : null;
  }
  if (c.nodeType === 3) {
    if (dir < 0 && off === 0) return composerEditorIsAtom(c.previousSibling) ? c.previousSibling : null;
    if (dir > 0 && off === (c.nodeValue || '').length) return composerEditorIsAtom(c.nextSibling) ? c.nextSibling : null;
  }
  return null;
}

// Delete a marker atom (Backspace/Delete) AND its underlying attachment/draft — otherwise a deleted image would
// still be SENT (composerBlocksFromDraft appends a markerless attachment).
function removeComposerAtom(el, atom) {
  const marker = atom?.dataset?.marker || '';
  const kind = el === publicMessageInput ? 'public' : 'private';
  let m;
  if ((m = marker.match(/^\[(?:image|img)\s+(\d+)\]$/i))) { removeComposerImageAt(kind, Number(m[1]) - 1); return; }
  if ((m = marker.match(/^\[file\s+(\d+)\]$/i))) { removeComposerFileAt(kind, Number(m[1]) - 1); return; }
  if (/^\[post\]$/i.test(marker)) { removeComposerShareAtom(kind); return; }
  atom.remove(); // unknown atom: just drop the node
  composerEditorAfterEdit(el);
}

function removeComposerImageAt(kind, index) {
  if (kind === 'public') publicImageAttachments = publicImageAttachments.filter((_, i) => i !== index);
  else privateImageAttachments = privateImageAttachments.filter((_, i) => i !== index);
  removeImageMarkerForComposer(kind, index); // strips [image index+1] + renumbers; the rebuild resolves the spliced array
  updateImageAttachmentUi(kind);
  refreshComposerCostStatus();
}

// Strip ONE [file N] marker + renumber the ones after it (mirrors removeImageMarkerForComposer) for per-file removal.
function removeFileMarkerForComposer(kind, removedIndex) {
  const editor = kind === 'public' ? publicMessageInput : messageInput;
  if (!editor) return;
  const removedNum = Number(removedIndex) + 1;
  let dropped = false;
  const next = String(editor.value ?? '').replace(/\[file\s+(\d+)\](?!\()/ig, (match, numStr) => {
    const n = Number(numStr);
    if (!dropped && n === removedNum) { dropped = true; return ''; }
    if (n > removedNum) return `[file ${n - 1}]`;
    return match;
  });
  let value = next.replace(/\n{3,}/g, '\n\n');
  if (!value.trim()) value = '';
  editor.value = value;
}

function removeComposerFileAt(kind, index) {
  if (kind === 'public') publicFileAttachments = publicFileAttachments.filter((_, i) => i !== index);
  else privateFileAttachments = privateFileAttachments.filter((_, i) => i !== index);
  removeFileMarkerForComposer(kind, index);
  if (kind === 'public') updatePublicFileAttachmentUi(); else updatePrivateFileAttachmentUi();
  refreshComposerCostStatus();
}


function removeComposerShareAtom(kind) {
  const editor = kind === 'public' ? publicMessageInput : messageInput;
  if (kind === 'public') setPublicShareDraft(null); else setPrivateShareDraft(null);
  removeShareMarkerForComposer(editor); // strips [post] + rebuild
  refreshComposerCostStatus();
}

// Drop attachments whose marker is no longer in `value`, keeping the marker-referenced ones in document order and
// renumbering their markers to 1..K. Returns { changed, value (renumbered), arr (pruned) }. Cheap no-op when every
// attachment still has a marker (the common case). Markers the user typed as LITERAL prose (out of range) are left
// untouched. Backs the reconcile pass that closes the non-collapsed-delete/paste orphan hole.
function reconcileMarkerArray(value, arr, re, fmt) {
  const present = [];
  re.lastIndex = 0;
  let m;
  while ((m = re.exec(value)) !== null) present.push(Number(m[1]));
  const keptIdx = [];
  const seen = new Set();
  for (const n of present) { if (n >= 1 && n <= arr.length && !seen.has(n)) { seen.add(n); keptIdx.push(n - 1); } }
  if (keptIdx.length === arr.length) return { changed: false, value, arr };
  const newArr = keptIdx.map((i) => arr[i]);
  const remap = new Map();
  keptIdx.forEach((oldI, newPos) => remap.set(oldI + 1, newPos + 1));
  const newValue = value.replace(re, (full, numStr) => {
    const n = Number(numStr);
    return remap.has(n) ? fmt(remap.get(n)) : full; // leave out-of-range/literal markers as typed
  });
  return { changed: true, value: newValue, arr: newArr };
}

// Reconcile the attachment arrays/drafts with the markers ACTUALLY present in the editor. A collapsed Backspace on
// an atom syncs itself (removeComposerAtom); this backstops the paths that don't — a non-collapsed delete, Ctrl+A
// then type, cut, or a paste over a selection that spans an atom — where the browser drops the atom node but the
// attachment would otherwise linger and get appended markerless on send. Called from the input handlers.
function reconcileComposerAttachments(el) {
  const kind = el === publicMessageInput ? 'public' : 'private';
  let value = serializeComposerEditor(el);
  let changed = false;
  const imgArr = kind === 'public' ? publicImageAttachments : privateImageAttachments;
  const ri = reconcileMarkerArray(value, imgArr, /\[(?:image|img)\s+(\d+)\]/ig, (n) => `[image ${n}]`);
  if (ri.changed) { changed = true; value = ri.value; if (kind === 'public') publicImageAttachments = ri.arr; else privateImageAttachments = ri.arr; }
  const fileArr = kind === 'public' ? publicFileAttachments : privateFileAttachments;
  const rf = reconcileMarkerArray(value, fileArr, /\[file\s+(\d+)\]/ig, (n) => `[file ${n}]`);
  if (rf.changed) { changed = true; value = rf.value; if (kind === 'public') publicFileAttachments = rf.arr; else privateFileAttachments = rf.arr; }
  if (kind === 'private' && privatePaymentCheckDraft && !/\[(?:check|payment)\](?!\()/i.test(value)) { privatePaymentCheckDraft = null; changed = true; }
  const share = kind === 'public' ? publicShareDraft : privateShareDraft;
  if (share && !/\[post\](?!\()/i.test(value)) { if (kind === 'public') setPublicShareDraft(null); else setPrivateShareDraft(null); changed = true; }
  if (!changed) return false;
  el.value = value; // rebuild once with the pruned arrays + renumbered markers (caret loss OK — a big edit just ran)
  if (kind === 'private') { updatePrivateAttachmentUi(); updatePrivateFileAttachmentUi(); }
  else { updateImageAttachmentUi('public'); updatePublicFileAttachmentUi(); }
  refreshComposerPublishPolicy();
  refreshComposerCostStatus();
  return true;
}

// Toggle an inline format CLASS span (.fmt-bold / .fmt-italic) over the selection. Collapsed selection = no-op
// (no stray markers on mobile). Never inline styles (prod CSP style-src 'self'), never execCommand.
// The word (run of letters/digits/underscore, any script) the collapsed caret sits in, as offsets into its text
// node — so a format toggle with no selection acts on the whole word. Null if the caret is on whitespace/empty.
// The word under the caret, as a range that SPANS fmt-* span / text-node boundaries WITHIN the word — so half a word
// wrapped in bold still selects/toggles the WHOLE word (was single-text-node: it grabbed only the bold or the plain
// half). A word = a run of letters/digits/_; it never crosses a <br>, block boundary, or atom chip. Returns
// {startNode, startOffset, endNode, endOffset, caretInWord} or null.
function composerEditorWordRangeAtCaret(range, el) {
  const caretNode = range.startContainer;
  if (caretNode.nodeType !== 3) return null;
  const root = el || caretNode.parentNode;
  if (!root || !root.contains(caretNode)) return null;
  const isWord = (ch) => ch !== undefined && /[\p{L}\p{N}_]/u.test(ch);
  // Walk inline nodes in order: text nodes (word material) + <br>/atom chips (hard word boundaries). fmt spans are
  // transparent (SKIP descends into their text), so a bold+plain word reads as one contiguous run.
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT, {
    acceptNode(n) {
      if (n.nodeType === 3) {
        // A text node INSIDE an atom chip is the chip's own label (e.g. a link's visible text), NOT editable word
        // material. Reject it — FILTER_ACCEPT on the atom element (below) does NOT prune its subtree, so without this
        // a word abutting a chip (`[docs](…)world`, no separator) would merge the label into the word run: select-word
        // would anchor inside the contenteditable=false chip and Bold/Italic would no-op (range intersects the atom).
        // The atom ELEMENT itself is still accepted and stays a hard word boundary.
        return (n.parentElement && n.parentElement.closest('[data-marker]')) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT;
      }
      // Hard word boundaries — mirror the set serializeComposerEditor turns into a NEWLINE (BR + DIV/P block wrappers)
      // plus atom chips. ACCEPT keeps the element in `seq` (nodeType 1 breaks the contiguous text-run) so a word can't
      // merge across it; the walker still descends into DIV/P (their text is real content on the next line, just not the
      // caret's word). Without DIV/P here a stray block (a WebView inserted one despite the Enter intercept) would let a
      // toggle span the boundary and serialize `**foo\nbar**` — a newline trapped in bold the recipient shows as `**`.
      if (n.nodeName === 'BR' || n.nodeName === 'DIV' || n.nodeName === 'P' || (n.dataset && n.dataset.marker)) return NodeFilter.FILTER_ACCEPT;
      return NodeFilter.FILTER_SKIP;
    },
  });
  const seq = [];
  let n;
  while ((n = walker.nextNode())) seq.push(n);
  const caretIdx = seq.indexOf(caretNode);
  if (caretIdx === -1) return null;
  // The contiguous TEXT-NODE run around the caret, bounded by any <br>/atom in seq.
  let a = caretIdx;
  let b = caretIdx;
  while (a > 0 && seq[a - 1].nodeType === 3) a--;
  while (b < seq.length - 1 && seq[b + 1].nodeType === 3) b++;
  const textNodes = seq.slice(a, b + 1);
  let concat = '';
  const map = []; // global char index -> { node, local }
  let caretGlobal = 0;
  for (const tn of textNodes) {
    if (tn === caretNode) caretGlobal = concat.length + range.startOffset;
    const v = tn.nodeValue || '';
    for (let i = 0; i < v.length; i++) map.push({ node: tn, local: i });
    concat += v;
  }
  let s = caretGlobal;
  let e = caretGlobal;
  while (s > 0 && isWord(concat[s - 1])) s--;
  while (e < concat.length && isWord(concat[e])) e++;
  if (s === e) return null;
  const startPos = map[s];
  const lastPos = map[e - 1];
  return {
    startNode: startPos.node, startOffset: startPos.local,
    endNode: lastPos.node, endOffset: lastPos.local + 1,
    caretInWord: caretGlobal - s,
  };
}

// The single ancestor format span of `className` that FULLY encloses the range (range.commonAncestorContainer is
// inside it), else null. Finds the one-span case (a word, a partial run within one span) — a MULTI-span selection
// (commonAncestorContainer is the editor) returns null and is handled by the fully-formatted path below.
function composerEditorEnclosingFormat(range, className, el) {
  let node = range.commonAncestorContainer;
  while (node && node !== el) {
    if (node.nodeType === 1 && node.classList && node.classList.contains(className)) return node;
    node = node.parentNode;
  }
  return null;
}

// True when EVERY non-empty text run the selection covers already sits inside a `.className` span (so a toggle must
// REMOVE the format); false if any covered text is unformatted (toggle must ADD it) or the selection holds no text.
// Uses cloneContents so a multi-span / select-all / multi-line selection is judged correctly — the old ancestor-walk
// (composerEditorEnclosingFormat) returned null whenever commonAncestorContainer was the editor (any select-all),
// so the toggle could NEVER un-format more than a single enclosing span (owner bug: "select all + Bold stays bold").
function composerEditorSelectionFullyFormatted(range, className, el) {
  // Walk the ACTUAL text nodes the range covers in the live DOM — NOT cloneContents, which DROPS the enclosing span
  // when both range endpoints sit in ONE text node (the collapsed word-toggle case), so it would wrongly report
  // "not formatted" and the toggle would ADD another layer (`****word****`) instead of removing.
  const overlaps = (n) => {
    const nr = document.createRange();
    nr.selectNodeContents(n);
    // range covers >=1 char of n iff range.start < n.end AND range.end > n.start
    return range.compareBoundaryPoints(Range.END_TO_START, nr) < 0
      && range.compareBoundaryPoints(Range.START_TO_END, nr) > 0;
  };
  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, {
    acceptNode: (n) => ((n.nodeValue || '') !== '' && !(n.parentElement && n.parentElement.closest('[data-marker]')) && overlaps(n))
      ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP,
  });
  let n;
  let any = false;
  while ((n = walker.nextNode())) {
    any = true;
    if (!(n.parentElement && n.parentElement.closest('.' + className))) return false;
  }
  return any;
}

// Remove `className` formatting from the selection, however many spans / lines it crosses. extractContents SPLITS a
// span at each range edge (so a partially-selected span keeps its unselected head/tail formatted), then every
// `.className` span in the extracted fragment is unwrapped (its children — including any OTHER-format nested span —
// survive) and the now-plain content is re-inserted and re-selected. Subsumes the old three-way-split + nested-unwrap.
function composerEditorUnformatRange(range, className, el) {
  const frag = range.extractContents();
  frag.querySelectorAll('.' + className).forEach((span) => {
    if (!/\bfmt-/.test(span.className || '')) return;
    while (span.firstChild) span.parentNode.insertBefore(span.firstChild, span);
    span.remove();
  });
  // When the range was wholly inside ONE span's text, extractContents leaves that span EMPTIED and collapses the
  // insertion point INSIDE it — re-inserting there would RE-FORMAT the content (nested `****`). Hoist the insertion
  // point OUT to after the (now-empty) enclosing span; the trailing composerEditorPruneEmptyFmt drops the shell.
  let node = range.startContainer;
  let encl = null;
  while (node && node !== el) {
    if (node.nodeType === 1 && /\bfmt-/.test(node.className || '') && node.classList.contains(className)) encl = node;
    node = node.parentNode;
  }
  if (encl) { range.setStartAfter(encl); range.collapse(true); }
  const first = frag.firstChild;
  const last = frag.lastChild;
  range.insertNode(frag);
  const sel = window.getSelection();
  if (sel && first && last && first.isConnected && last.isConnected) {
    const r = document.createRange();
    r.setStartBefore(first);
    r.setEndAfter(last);
    sel.removeAllRanges();
    sel.addRange(r);
  }
}

function composerEditorToggleFormat(el, className) {
  if (!el || el.disabled) return;
  el.focus();
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return;
  const range = sel.getRangeAt(0);
  if (!el.contains(range.commonAncestorContainer)) return;
  const startedCollapsed = range.collapsed; // a word-toggle (tap-in-word + B): keep the caret where it was afterwards
  let caretInWord = -1; // the caret's offset WITHIN the word, so we can put it back at the same spot after formatting
  if (range.collapsed) {
    // No selection: expand to the WORD under the caret so tapping into a word + B formats the whole word
    // (mobile-friendly — no precise selection, no native menu). Caret on whitespace/empty -> no-op.
    const word = composerEditorWordRangeAtCaret(range, el);
    if (!word) return;
    caretInWord = word.caretInWord; // remember WHERE in the word the caret was, to restore it
    range.setStart(word.startNode, word.startOffset);
    range.setEnd(word.endNode, word.endOffset);
    sel.removeAllRanges();
    sel.addRange(range);
  }
  // Never let a format span swallow an atomic attachment block: extractContents would nest it, and the serialized
  // `**…[image N]…**` splits on the marker into two blocks with unbalanced markers (recipient sees literal `**`).
  for (const block of el.querySelectorAll('[data-marker]')) {
    if (range.intersectsNode(block)) return;
  }
  const enclosing = composerEditorEnclosingFormat(range, className, el);
  if (enclosing) {
    const hasElementChild = Array.from(enclosing.childNodes).some((n) => n.nodeType === 1);
    if (!hasElementChild) {
      // Toggle OFF over the SELECTION ONLY within ONE span (three-way split): the unselected head/tail stay
      // formatted, only the selected middle goes plain. Rebuilds from textContent + offsets so a range wholly
      // inside a single text node splits cleanly (extractContents would merge the head+tail into one span).
      const spanText = enclosing.textContent;
      const pre = document.createRange();
      pre.selectNodeContents(enclosing);
      pre.setEnd(range.startContainer, range.startOffset);
      const startOff = pre.toString().length;
      const endOff = startOff + range.toString().length;
      const head = spanText.slice(0, startOff);
      const mid = spanText.slice(startOff, endOff);
      const tail = spanText.slice(endOff);
      const frag = document.createDocumentFragment();
      if (head) { const s = document.createElement('span'); s.className = className; s.textContent = head; frag.append(s); }
      const midNode = document.createTextNode(mid);
      frag.append(midNode);
      if (tail) { const s = document.createElement('span'); s.className = className; s.textContent = tail; frag.append(s); }
      enclosing.replaceWith(frag);
      const r = document.createRange();
      r.selectNode(midNode);
      sel.removeAllRanges(); sel.addRange(r);
    } else {
      // Nested formatting inside the span (e.g. a .fmt-bold inside this .fmt-italic): unwrap the whole span but
      // KEEP the nested children so the other format survives.
      const parent = enclosing.parentNode;
      const kids = [];
      while (enclosing.firstChild) { kids.push(enclosing.firstChild); parent.insertBefore(enclosing.firstChild, enclosing); }
      parent.removeChild(enclosing);
      if (kids.length) {
        const r = document.createRange();
        r.setStartBefore(kids[0]);
        r.setEndAfter(kids[kids.length - 1]);
        sel.removeAllRanges(); sel.addRange(r);
      }
    }
  } else if (composerEditorSelectionFullyFormatted(range, className, el)) {
    // NO single enclosing span but the selection is ENTIRELY formatted — a MULTI-span / multi-line / select-all run.
    // Unwrap the format from every span across it. (The old code had ONLY the enclosing branch, so a select-all —
    // whose commonAncestorContainer is the editor — found no enclosing span and fell through to ADD: "stays bold".)
    composerEditorUnformatRange(range, className, el);
  } else {
    const span = document.createElement('span');
    span.className = className;
    span.appendChild(range.extractContents());
    range.insertNode(span);
    // Flatten any same-class descendants so serialization doesn't emit doubled markers.
    span.querySelectorAll('.' + className).forEach((n) => { while (n.firstChild) n.parentNode.insertBefore(n.firstChild, n); n.remove(); });
    span.normalize(); // merge the adjacent text nodes flattening leaves behind so caret-restore by offset lands exactly
    const r = document.createRange();
    r.selectNodeContents(span);
    sel.removeAllRanges(); sel.addRange(r);
  }
  // A word-toggle started from a collapsed caret should NOT leave the whole word highlighted — put the caret back
  // WHERE IT WAS within the word (same offset), inside the word's TEXT node. Same-spot means pressing Bold/Italic
  // AGAIN re-finds the word to un-toggle it (composerEditorWordRangeAtCaret needs a text-node caret) and the user's
  // caret doesn't jump to the word end. We do NOT escape the span here — the format-leak on the NEXT Enter/attach-
  // ment/typing is already prevented by the escape in composerEditorInsertLineBreak / composerEditorInsertChip and
  // the insertText bleed guard, so the caret can safely rest in the word.
  if (startedCollapsed && sel.rangeCount) {
    const r = sel.getRangeAt(0);
    // The selection now spans exactly the (re)formatted word. Walk its text nodes IN ORDER (the word may span a nested
    // other-format span — bold OVER a partially-italic word — so the caret's target offset can fall past the FIRST
    // text node; clamping to that node alone lands the caret a char early). Place it at the caretInWord-th char.
    const wordTexts = [];
    const rootEl = r.commonAncestorContainer.nodeType === 1 ? r.commonAncestorContainer : r.commonAncestorContainer.parentNode;
    if (rootEl) {
      const tw = document.createTreeWalker(rootEl, NodeFilter.SHOW_TEXT, { acceptNode: (tn) => r.intersectsNode(tn) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP });
      let tn; while ((tn = tw.nextNode())) wordTexts.push(tn);
    }
    let node = r.startContainer, off = r.startOffset;
    if (wordTexts.length) {
      const want = caretInWord >= 0 ? caretInWord : Infinity; // no caretInWord -> land at the word END
      let acc = 0, placed = false;
      for (const tn of wordTexts) {
        const from = tn === r.startContainer ? r.startOffset : 0;
        const to = tn === r.endContainer ? r.endOffset : tn.nodeValue.length;
        const len = to - from;
        if (acc + len >= want) { node = tn; off = from + (want - acc); placed = true; break; }
        acc += len;
      }
      if (!placed) { const last = wordTexts[wordTexts.length - 1]; node = last; off = last === r.endContainer ? r.endOffset : last.nodeValue.length; }
    } else if (node.nodeType === 1) { // no text nodes matched (defensive) — descend to the first text child
      let c = node.childNodes[off] || node.firstChild;
      while (c && c.nodeType === 1) c = c.firstChild;
      if (c && c.nodeType === 3) { node = c; off = caretInWord >= 0 ? Math.min(caretInWord, c.nodeValue.length) : c.nodeValue.length; }
    }
    const r2 = document.createRange();
    r2.setStart(node, off);
    r2.collapse(true);
    sel.removeAllRanges();
    sel.addRange(r2);
  }
  // Toggling a partially-formatted word (extractContents splits the old span across the word boundary) can leave an
  // EMPTY .fmt-* span behind, which serializes to a stray `****`. Prune it (the caret already rests in the word).
  composerEditorPruneEmptyFmt(el);
  composerEditorAfterEdit(el);
}

// The .fmt-* span whose TRAILING text edge the collapsed caret sits at (text node is the span's last child and
// the caret is at its end) — i.e. the caret is right after a formatted word, so new typing must NOT inherit it.
function composerEditorTrailingFmtSpan(range, el) {
  const node = range.startContainer;
  if (node.nodeType !== 3 || range.startOffset !== node.nodeValue.length) return null;
  let span = node.parentNode;
  if (!(span && span !== el && span.nodeType === 1 && /\bfmt-/.test(span.className || '') && node === span.lastChild)) return null;
  // Climb to the OUTERMOST enclosing fmt span while the caret is still at its trailing edge (this span is its
  // parent's last child): typing after a NESTED run (bold inside italic) must land OUTSIDE both spans, else it
  // inherits the outer format and serializes to unbalanced emphasis (`*…*` straddling the new text).
  while (span.parentNode && span.parentNode !== el && span.parentNode.nodeType === 1
    && /\bfmt-/.test(span.parentNode.className || '') && span === span.parentNode.lastChild) {
    span = span.parentNode;
  }
  return span;
}

// [21] IME composition (and the mobile keyboards / autocorrect that route ordinary typing THROUGH composition)
// bypass the beforeinput bleed guard entirely (composerEditorBeforeInput returns on event.isComposing), so a word
// composed at the trailing edge of a fmt span would inherit the format. Pre-escape the caret OUT of a trailing fmt
// span at compositionstart so the composed text lands plain. Fires ONLY at a true trailing edge
// (composerEditorTrailingFmtSpan) — mid-word composition (editing an existing word) is left untouched.
function composerEditorEscapeFmtForComposition(el) {
  if (!el || el.disabled) return;
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount || !sel.isCollapsed) return;
  const span = composerEditorTrailingFmtSpan(sel.getRangeAt(0), el);
  if (!span) return;
  const r = document.createRange();
  r.setStartAfter(span);
  r.collapse(true);
  sel.removeAllRanges(); sel.addRange(r);
}

// Shared beforeinput for both composer editors: (1) newline via insertParagraph/insertLineBreak so Android
// soft-keyboard Enter (keyCode 229) still lands a clean <br>; (2) a bleed guard — a char typed at the trailing
// edge of a .fmt-* span is inserted OUTSIDE the span (plain) so a word typed after a formatted word is normal.
function composerEditorBeforeInput(el, event) {
  if (event.isComposing) return;
  if (event.inputType === 'insertParagraph' || event.inputType === 'insertLineBreak') {
    event.preventDefault();
    composerEditorInsertLineBreak(el);
    return;
  }
  // Backspace/Delete next to a marker atom removes the atom AND its attachment/draft (some browsers won't delete
  // a contenteditable=false block on their own, and a bare node-delete would orphan the attachment into the send).
  if (event.inputType === 'deleteContentBackward' || event.inputType === 'deleteContentForward') {
    const sel = window.getSelection();
    if (!sel || !sel.rangeCount || !sel.isCollapsed) return;
    const atom = composerEditorAdjacentAtom(sel.getRangeAt(0), el, event.inputType === 'deleteContentBackward' ? -1 : 1);
    if (atom) { event.preventDefault(); removeComposerAtom(el, atom); }
    return;
  }
  // [22] The bleed guard also covers the replacement/composition/autofill insert families (a mobile suggestion
  // commit / desktop autocorrect / autofill), not just plain insertText — else a word inserted at the trailing edge
  // of a fmt span inherits the format. A RANGE-replacing variant (non-collapsed target, e.g. spell-correcting a word
  // IN the span) bails at the isCollapsed check below and is left in place (correctly stays formatted).
  if ((event.inputType === 'insertText' || event.inputType === 'insertReplacementText'
    || event.inputType === 'insertFromComposition' || event.inputType === 'insertFromAutofill')
    && typeof event.data === 'string') {
    const sel = window.getSelection();
    if (!sel || !sel.rangeCount || !sel.isCollapsed) return;
    const span = composerEditorTrailingFmtSpan(sel.getRangeAt(0), el);
    if (!span) return;
    event.preventDefault();
    const textNode = document.createTextNode(event.data);
    span.after(textNode);
    const r = document.createRange();
    r.setStart(textNode, textNode.length);
    r.collapse(true);
    sel.removeAllRanges(); sel.addRange(r);
    composerEditorAfterEdit(el);
  }
}

// Sanitize pasted/dropped content down to text/plain and insert it at the caret (new XSS surface — never trust
// clipboard HTML; only text crosses into the editor). \r\n normalized; the serializer turns \n into <br>.
function composerEditorInsertPlainMultiline(el, text) {
  if (!el || el.disabled) return;
  el.focus();
  // [18] Neutralize marker-like tokens in the pasted TEXT so serialize->composerBlocksFromDraft can't re-parse a
  // pasted `[image 1]` as a real chip's marker (which would bind it to the editor's OWN attachment or drop the text
  // on send). A zero-width space after `[` breaks the marker regex while staying invisible; the `(?!\()` mirrors
  // EDITOR_INLINE_RE so a link label like `[image 1](url)` is left intact.
  let raw = String(text ?? '').replace(/\r\n?/g, '\n');
  raw = raw.replace(/\[((?:image|img)\s+\d+|file\s+\d+|post|check|payment)\](?!\()/gi, '[\u200b$1]');
  composerEditorRange(el).deleteContents(); // collapse any selection at the paste point first
  // [25] Only ESCAPE the caret out of a trailing fmt span when the paste yields a LINK chip (a link chip trapped
  // inside **…**/*…*/`…` is a dead-wire link). Plain/marker text inserts at the REAL caret (mid-word, inheriting the
  // surrounding format) instead of unconditionally jumping to the formatted word's end.
  const hasLink = /\[[^\]\n]{1,200}\]\([^\s()]{1,2000}\)/.test(raw);
  if (hasLink) composerEditorEscapeTrailingFmt(el);
  const range = composerEditorRange(el);
  const frag = document.createDocumentFragment();
  const lines = raw.split('\n');
  lines.forEach((line, index) => {
    if (index > 0) frag.append(document.createElement('br'));
    // Render links + formatting so a link copied FROM the composer round-trips as a live chip (not raw `[label](url)`
    // code). Attachment markers ([image N]/…) stay LITERAL TEXT (renderAttachmentMarkers=false): a live pasted atom
    // would bind to the editor's OWN attachment (phantom dup + delete-the-real-one). Still text/plain: NO clipboard HTML.
    appendEditorInline(frag, line, el, false);
  });
  const last = frag.lastChild;
  range.insertNode(frag);
  if (last) composerEditorPlaceCaretAfter(last);
  composerEditorAfterEdit(el);
}

// Turn a bare <div id> into a live composer editor: contenteditable + the .value/.disabled/.placeholder accessor
// shims that let the ENTIRE textarea-era send pipeline (size plan, submit capture, draft clear/restore, i18n
// placeholder) keep reading/writing it unchanged. Idempotent.
function initComposerEditor(el) {
  if (!el || el.dataset.editorReady === '1') return;
  el.dataset.editorReady = '1';
  el.contentEditable = 'true';
  el.setAttribute('role', 'textbox');
  el.setAttribute('aria-multiline', 'true');
  el.classList.add('composer-input');
  el.classList.toggle('is-empty', serializeComposerEditor(el).trim() === '');
  let disabledFlag = false;
  Object.defineProperty(el, 'value', {
    configurable: true,
    get() { return serializeComposerEditor(this); },
    set(v) { buildComposerEditorDom(this, String(v ?? '')); this.classList.toggle('is-empty', String(v ?? '').trim() === ''); },
  });
  Object.defineProperty(el, 'disabled', {
    configurable: true,
    get() { return disabledFlag; },
    set(v) {
      disabledFlag = Boolean(v);
      this.contentEditable = disabledFlag ? 'false' : 'true';
      this.classList.toggle('is-disabled', disabledFlag);
      if (disabledFlag) this.setAttribute('aria-disabled', 'true'); else this.removeAttribute('aria-disabled');
    },
  });
  Object.defineProperty(el, 'placeholder', {
    configurable: true,
    get() { return this.getAttribute('placeholder') ?? ''; },
    set(v) { this.setAttribute('placeholder', String(v ?? '')); },
  });
}

function privateAttachmentLabelForImage(attachment) {
  return attachment
    ? t('composer.imageAttachmentLabel', { name: attachment.name, kib: Math.ceil(attachment.bytes.length / 1024), mode: attachment.mode.label.toLowerCase() })
    : t('composer.image');
}

function createImageModeSelect(attachment, onChange) {
  const select = document.createElement('select');
  select.setAttribute('aria-label', t('composer.imageCompressionAria'));
  for (const mode of Object.values(IMAGE_COMPRESSION_MODES)) {
    const option = document.createElement('option');
    option.value = mode.id;
    option.textContent = t('composer.imageModeOption', { mode: mode.label, kib: Math.round(mode.maxBytes / 1024) });
    select.append(option);
  }
  select.value = attachment?.mode?.id ?? DEFAULT_IMAGE_COMPRESSION_MODE_ID;
  select.addEventListener('change', onChange);
  return select;
}

function updatePrivateAttachmentUi() {
  const panel = privateAttachmentPanel;
  if (!panel) return;
  const imageAttachments = normalizePrivateImageAttachments(privateImageAttachments);
  const hasAttachments = imageAttachments.length > 0;
  panel.hidden = !hasAttachments;
  panel.classList.toggle('is-list', hasAttachments);
  if (!hasAttachments) {
    panel.replaceChildren();
    return;
  }
  const rows = [];
  imageAttachments.forEach((attachment, index) => {
    const row = document.createElement('div');
    row.className = 'composer-attachment-row';
    const label = document.createElement('span');
    label.className = 'composer-attachment-label';
    label.textContent = privateAttachmentLabelForImage(attachment);
    const modeSelect = createImageModeSelect(attachment, () => {
      recompressPrivateImageAttachment(index, modeSelect.value).catch((error) => console.error(error));
    });
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.textContent = t('common.remove');
    remove.addEventListener('click', () => removeComposerImageAt('private', index));
    row.append(label, modeSelect, remove);
    rows.push(row);
  });
  panel.replaceChildren(...rows);
}

function updateImageAttachmentUi(kind) {
  if (kind === 'private') {
    updatePrivateAttachmentUi();
    return;
  }
  const attachments = normalizePublicImageAttachments(publicImageAttachments);
  const attachment = attachments[0] ?? null;
  const panel = kind === 'public' ? publicAttachmentPanel : privateAttachmentPanel;
  const label = kind === 'public' ? publicAttachmentLabel : privateAttachmentLabel;
  const modeSelect = kind === 'public' ? publicImageModeSelect : privateImageModeSelect;
  if (panel) panel.hidden = attachments.length === 0;
  if (label) {
    label.textContent = attachments.length > 1
      ? tPlural('composer.imagesAttached', attachments.length)
      : attachment
      ? t('composer.imageAttachmentLabel', { name: attachment.name, kib: Math.ceil(attachment.bytes.length / 1024), mode: attachment.mode.label.toLowerCase() })
      : t('composer.noImage');
  }
  if (modeSelect && attachment) modeSelect.value = attachment.mode.id;
}

async function setImageAttachment(kind, file, modeId) {
  const status = kind === 'public' ? publicComposerCostStatus : privateComposerCostStatus;
  const input = kind === 'public' ? publicImageInput : privateImageInput;
  const button = kind === 'public' ? publicImageButton : privateImageButton;
  try {
    if (status) {
      status.textContent = t('composer.preparingImagePreview');
      status.dataset.state = 'short';
    }
    if (button) button.disabled = true;
    const attachment = await requestCompressedImageFile(file, {
      modeId,
      title: kind === 'public' ? t('composer.attachPublicImageTitle') : t('composer.attachPrivateImageTitle'),
      hint: kind === 'public'
        ? t('composer.publicImageHint')
        : t('composer.privateImageHint'),
      submitLabel: t('composer.attachImage'),
      partCounter: kind === 'private' ? privateImageAttachmentPartCount : imageAttachmentPartCount,
      extraRows: [
        { label: t('composer.gramFee'), value: t('composer.feeDependsOnCapsuleCount') },
      ],
    });
    if (!attachment) {
      refreshComposerCostStatus();
      return;
    }
    if (kind === 'public') {
      publicImageAttachments = [...publicImageAttachments, attachment];
      insertImageMarkerForComposer('public', publicImageAttachments.length);
    } else {
      privateImageAttachments = [...privateImageAttachments, attachment];
      insertImageMarkerForComposer('private', privateImageAttachments.length);
    }
    updateImageAttachmentUi(kind);
    refreshComposerPublishPolicy();
  } catch (error) {
    if (kind === 'public') {
      publicImageAttachments = [];
    }
    updateImageAttachmentUi(kind);
    if (status) {
      status.textContent = error?.message ?? t('composer.imageCompressionBlocked');
      status.dataset.state = 'short';
    }
    console.error(error);
  } finally {
    if (input) input.value = '';
    // Re-resolve through the canonical per-surface send-block predicate (a bare wallet check here used to
    // re-enable the attach button on an inactive composer). NOT refreshComposerCostStatus(): that would
    // overwrite the error text the catch branch just put in the status line.
    if (button) button.disabled = kind === 'public' ? publicComposerSendBlocked() : Boolean(privateSendBlockReason());
  }
}

async function recompressPrivateImageAttachment(index, modeId) {
  const attachment = privateImageAttachments[index];
  if (!attachment?.sourceFile) return;
  const status = privateComposerCostStatus;
  try {
    if (status) {
      status.textContent = t('composer.recompressingImage');
      status.dataset.state = 'short';
    }
    const next = await compressImageFile(attachment.sourceFile, modeId);
    privateImageAttachments = privateImageAttachments.map((item, itemIndex) => (
      itemIndex === index ? next : item
    ));
    updateImageAttachmentUi('private');
    refreshComposerEditorBlocks(messageInput); // re-render the inline image at the new compression
    refreshComposerCostStatus();
  } catch (error) {
    if (status) {
      status.textContent = error?.message ?? t('composer.imageCompressionBlocked');
      status.dataset.state = 'short';
    }
    throw error;
  }
}

async function recompressImageAttachment(kind) {
  const attachment = kind === 'public' ? normalizePublicImageAttachments(publicImageAttachments)[0] : privateImageAttachments[0];
  const modeSelect = kind === 'public' ? publicImageModeSelect : privateImageModeSelect;
  if (!attachment?.sourceFile || !modeSelect) return;
  if (kind === 'public') {
    const next = await compressImageFile(attachment.sourceFile, modeSelect.value);
    publicImageAttachments = publicImageAttachments.map((item, index) => (index === 0 ? next : item));
    updateImageAttachmentUi('public');
    refreshComposerEditorBlocks(publicMessageInput); // re-render the inline image at the new compression
    refreshComposerCostStatus();
  } else {
    await recompressPrivateImageAttachment(0, modeSelect.value);
  }
}

function privateComposerPlaceholder({ readOnly = false } = {}) {
  if (!plathoWallet) return t('common.walletRequired');
  if (readOnly) return t('composer.readOnlyChannel');
  return t('composer.privateMessage');
}

function publicComposerPlaceholder() {
  // Always the normal composer placeholder — do NOT surface "wallet required" here; the composer status line below
  // already shows it, and duplicating it in the input placeholder is redundant.
  return publicCommentTarget ? t('composer.publicComment') : t('composer.publicMessage');
}

function refreshComposerPublishPolicy() {
  const canPublish = Boolean(plathoWallet);
  if (composer) composer.dataset.publishMode = canPublish ? 'vault-balance' : 'wallet-required';
  if (messageInput) {
    messageInput.removeAttribute('maxlength');
    messageInput.placeholder = privateComposerPlaceholder({
      readOnly: composer?.dataset.readOnly === 'true',
    });
  }
  if (publicComposer) publicComposer.dataset.publishMode = canPublish ? 'vault-balance' : 'wallet-required';
  if (publicMessageInput) {
    publicMessageInput.removeAttribute('maxlength');
    publicMessageInput.placeholder = publicComposerPlaceholder();
  }
  // Attachment/add-button DISABLED state is NOT written here: it is owned by refreshPrivateSendButtonState /
  // refreshPublicSendButtonState (both run via refreshComposerCostStatus below), keyed to the full send-block
  // predicate — the wallet-only writes this block used to do re-enabled buttons on an inactive composer.
  for (const control of attachmentControls) {
    control.hidden = false;
    if (control.classList?.contains('attachment-button')) {
      control.title = canPublish ? t('composer.attachImage') : t('composer.walletToAttachImages');
    }
  }
  if (paymentCheckButton) {
    paymentCheckButton.title = canPublish ? t('composer.attachPaymentCheck') : t('composer.walletToAttachPaymentCheck');
  }
  if (privateImageModeSelect) {
    privateImageModeSelect.disabled = !canPublish;
  }
  if (publicImageModeSelect) {
    publicImageModeSelect.disabled = !canPublish;
  }
  // updatePrivateSenderModeUi runs inside refreshComposerCostStatus's funnel below (with the send-block
  // reason already computed) — no direct call here, it would just build the send plan once more.
  updateImageAttachmentUi('private');
  updateImageAttachmentUi('public');
  refreshComposerCostStatus();
}

function privateComposerAddMenuVisible() {
  return Boolean(privateComposerAddMenu && !privateComposerAddMenu.hidden);
}

function hidePrivateComposerAddMenu() {
  if (privateComposerAddMenu) privateComposerAddMenu.hidden = true;
  privateComposerAddButton?.setAttribute('aria-expanded', 'false');
}

function showPrivateComposerAddMenu() {
  if (!privateComposerAddMenu || !privateComposerAddButton || privateComposerAddButton.disabled) return;
  privateComposerAddMenu.hidden = false;
  privateComposerAddButton.setAttribute('aria-expanded', 'true');
}

function togglePrivateComposerAddMenu() {
  if (privateComposerAddMenuVisible()) hidePrivateComposerAddMenu();
  else showPrivateComposerAddMenu();
}

function publicComposerAddMenuVisible() {
  return Boolean(publicComposerAddMenu && !publicComposerAddMenu.hidden);
}
function hidePublicComposerAddMenu() {
  if (publicComposerAddMenu) publicComposerAddMenu.hidden = true;
  publicComposerAddButton?.setAttribute('aria-expanded', 'false');
}
function showPublicComposerAddMenu() {
  if (!publicComposerAddMenu || !publicComposerAddButton || publicComposerAddButton.disabled) return;
  publicComposerAddMenu.hidden = false;
  publicComposerAddButton.setAttribute('aria-expanded', 'true');
}
function togglePublicComposerAddMenu() {
  if (publicComposerAddMenuVisible()) hidePublicComposerAddMenu();
  else showPublicComposerAddMenu();
}

function composerBlocksFromDraft(text, attachments = [], paymentDraft = null, replyDraft = privateReplyDraft, fileAttachments = privateFileAttachments, shareDraft = privateShareDraft) {
  const source = String(text ?? '');
  const images = normalizePrivateImageAttachments(attachments);
  const usedImages = new Set();
  const blocks = [];
  const pushText = (value) => {
    const trimmed = String(value ?? '').trim();
    if (trimmed) blocks.push({ type: 'text', text: trimmed });
  };
  const pushImage = (index) => {
    const imageIndex = Number(index) - 1;
    const attachment = images[imageIndex];
    if (!attachment || usedImages.has(imageIndex)) return;
    usedImages.add(imageIndex);
    blocks.push({
      type: 'image',
      attachment,
      bytes: attachment.bytes,
      width: attachment.width,
      height: attachment.height,
      format: attachment.mediaFormat ?? PLATHO_COMPACT_IMAGE_FORMATS.WEBP,
      url: attachment.dataUrl,
      mode: attachment.mode?.id,
      modeLabel: attachment.mode?.label,
    });
  };
  // Shared post (v766): positional via the [post] marker.
  let usedShare = false;
  const pushShare = () => {
    if (!shareDraft?.entryId || usedShare) return;
    usedShare = true;
    blocks.push({ type: 'share', ...shareDraft });
  };
  // File attachments are POSITIONAL like images (v759): attaching inserts a `[file N]` marker at the
  // cursor and the block lands exactly there. Markerless files (older drafts restored from history, or
  // a marker the user hand-deleted while keeping the attachment) still append after the visible
  // content, so nothing already persisted changes meaning.
  const files = Array.isArray(fileAttachments) ? fileAttachments : [];
  const usedFiles = new Set();
  const pushFile = (index) => {
    const fileIndex = Number(index) - 1;
    const file = files[fileIndex];
    if (!file?.bytes?.length || usedFiles.has(fileIndex)) return;
    usedFiles.add(fileIndex);
    blocks.push({ type: 'file', name: file.name, mime: file.mime, bytes: file.bytes });
  };
  let cursor = 0;
  COMPOSER_MARKER_RE.lastIndex = 0;
  for (const match of source.matchAll(COMPOSER_MARKER_RE)) {
    pushText(source.slice(cursor, match.index));
    if (match[1] !== undefined) pushImage(match[1]);
    else if (match[2] !== undefined) pushFile(match[2]);
    else if (match[3] !== undefined) pushShare();
    cursor = match.index + match[0].length;
  }
  pushText(source.slice(cursor));
  images.forEach((_, index) => {
    if (!usedImages.has(index)) pushImage(index + 1);
  });
  files.forEach((_, index) => {
    if (!usedFiles.has(index)) pushFile(index + 1);
  });
  // A markerless share (the [post] marker hand-deleted while the draft stays attached) leads the message —
  // forward-then-comment, and a share-only draft (no typed text) is a legitimate send by itself.
  if (shareDraft?.entryId && !usedShare) {
    usedShare = true;
    blocks.unshift({ type: 'share', ...shareDraft });
  }
  // Swipe-to-reply (v646): the quote rides as the FIRST document block, so the size plan, the optimistic echo,
  // and the wire all carry it from the same draft state (default-param style matches privateImageAttachments).
  if (blocks.length > 0 && replyDraft?.refEntryId !== undefined && replyDraft?.refEntryId !== null) {
    blocks.unshift({ type: 'reply', refEntryId: String(replyDraft.refEntryId), author: replyDraft.author ?? '', snippet: replyDraft.snippet ?? '' });
  }
  return blocks;
}

function displayBlocksFromDocumentBlocks(blocks) {
  return (blocks ?? []).map((block) => {
    if (block.type === 'text') return { type: 'text', text: block.text ?? '' };
    if (block.type === 'image') {
      const bytes = block.bytes instanceof Uint8Array ? block.bytes : new Uint8Array(block.bytes ?? []);
      return {
        type: 'image',
        url: block.url ?? bytesToImageDataUrl(bytes, 'image/webp'),
        bytes: bytes.length,
        width: block.width,
        height: block.height,
        mode: block.mode,
        modeLabel: block.modeLabel,
      };
    }
    // The quote strip data passes through verbatim (denormalized author+snippet; refEntryId for scroll-to-original).
    if (block.type === 'reply') {
      return { type: 'reply', refEntryId: block.refEntryId, author: block.author ?? '', snippet: block.snippet ?? '' };
    }
    // Shared public post (v766): all-string snapshot — display blocks persist through JSON history/caches.
    if (block.type === 'share') {
      return {
        type: 'share',
        entryId: String(block.entryId ?? ''),
        bodyHash: String(block.bodyHash ?? ''),
        authorWallet: String(block.authorWallet ?? ''),
        author: String(block.author ?? ''),
        title: String(block.title ?? ''),
        snippet: String(block.snippet ?? ''),
        hasImage: block.hasImage === true,
        textTruncated: block.textTruncated === true,
      };
    }
    // File attachment (v652): the display block carries a data: URL STRING (never a Uint8Array — display blocks
    // persist through JSON history/caches; the wire bytes only exist here at decode time). The chip renders
    // name + size; the click builds a Blob from the url.
    if (block.type === 'file') {
      const bytes = block.bytes instanceof Uint8Array ? block.bytes : new Uint8Array(block.bytes ?? []);
      return {
        type: 'file',
        name: String(block.name ?? 'file'),
        mime: String(block.mime ?? 'application/octet-stream'),
        size: block.url ? Number(block.size ?? 0) : bytes.length,
        url: block.url ?? `data:${block.mime ?? 'application/octet-stream'};base64,${bytesToBase64(bytes)}`,
      };
    }
    return null;
  }).filter(Boolean);
}

function messageDocumentBytesFromDraft(text, attachments = [], paymentDraft = null, options = {}, replyDraft = privateReplyDraft, fileAttachments = privateFileAttachments, shareDraft = privateShareDraft) {
  const blocks = composerBlocksFromDraft(text, attachments, paymentDraft, replyDraft, fileAttachments, shareDraft);
  if (blocks.length <= 0) return null;
  return encodeMessageDocumentBlocks(blocks, options);
}

// Strip inline markdown MARKERS for a PLAIN-TEXT preview line (the thread list shows thread.preview via textContent,
// which can't render bold, so the raw `**a** **b**` markers were just noise — owner screenshot). **bold**/
// *italic*/`code`/***bi*** -> their text; a [label](url) -> its label; runs of whitespace/newlines collapse to one
// space so a multi-line message previews as one clean line. Display-only (never touches the wire or the bubble
// renderer, which formats from the message's own blocks).
function stripInlineFormatting(text) {
  return String(text ?? '')
    .replace(/\*\*\*([^*\n]+)\*\*\*/g, '$1')
    .replace(/\*\*([^*\n]+)\*\*/g, '$1')
    .replace(/\*([^*\n]+)\*/g, '$1')
    .replace(/`([^`\n]+)`/g, '$1')
    .replace(/\[([^\]\n]{1,200})\]\(([^\s()]{1,2000})\)/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

function messagePreviewFromBlocks(blocks = []) {
  const text = blocks.find((block) => block?.type === 'text' && String(block.text ?? '').trim())?.text;
  if (text) return String(text).trim();
  const imageCount = blocks.filter((block) => block?.type === 'image').length;
  if (imageCount > 0) return imageCount === 1 ? 'Image' : `${imageCount} images`;
  const fileBlocks = blocks.filter((block) => block?.type === 'file');
  if (fileBlocks.length === 1) return String(fileBlocks[0].name ?? 'File');
  if (fileBlocks.length > 1) return `${fileBlocks.length} files`;
  if (blocks.some((block) => block?.type === 'share')) return 'Shared post';
  return '';
}

// Insert an attachment/link/share marker into a composer editor as an atomic chip at the caret.
function insertComposerMarker(editor, marker) {
  if (!editor) return;
  composerEditorInsertChip(editor, marker);
}

// --- Formatting toolbar (v769; WYSIWYG editor v771) --------------------------------------------------------
// The composer is a contenteditable editor (see the WYSIWYG core above); the toolbar buttons drive the live
// Range-based format ops (bold/italic wrap the selection in a .fmt-* span, list prefixes the line). The toolbar
// opens on a deliberate field click and a mousedown-preventDefault keeps the selection when a button is pressed.

function composerToolbarForTextarea(textarea) {
  const form = textarea?.closest?.('.composer');
  return form ? form.querySelector('.composer-toolbar') : null;
}

function showComposerToolbar(textarea) {
  composerToolbarForTextarea(textarea)?.classList.add('is-open');
}

function hideComposerToolbar(textarea) {
  composerToolbarForTextarea(textarea)?.classList.remove('is-open');
}

function applyComposerFormat(editor, format) {
  if (!editor) return;
  switch (format) {
    case 'bold': composerEditorToggleFormat(editor, 'fmt-bold'); break;
    case 'italic': composerEditorToggleFormat(editor, 'fmt-italic'); break;
    case 'select': composerEditorSelectWordAtCaret(editor); break;
    default: break;
  }
}

// Toolbar "Select" button — a TOGGLE. Gives a way to START a text selection precisely (the native selection handles
// then appear and can be dragged to extend) without first summoning the OS selection menu. If text is ALREADY selected
// (e.g. a partial-word selection), the press DESELECTS (collapses to a caret); a SECOND press then re-selects the whole
// word under the caret. From a bare caret it selects the whole word directly.
function composerEditorSelectWordAtCaret(el) {
  if (!el || el.disabled) return;
  el.focus();
  const sel = window.getSelection();
  if (!sel || !sel.rangeCount) return;
  const range = sel.getRangeAt(0);
  if (!el.contains(range.commonAncestorContainer)) return;
  if (!range.collapsed) {
    // Something is selected -> clear it (collapse to the selection start). The next press re-selects the whole word.
    range.collapse(true);
    sel.removeAllRanges();
    sel.addRange(range);
    return;
  }
  const word = composerEditorWordRangeAtCaret(range, el);
  if (!word) return;
  const r = document.createRange();
  r.setStart(word.startNode, word.startOffset);
  r.setEnd(word.endNode, word.endOffset);
  sel.removeAllRanges();
  sel.addRange(r);
}

// Wire ONE toolbar: the ▼ hide button, a mousedown-preventDefault (so a format-button click never blurs the
// textarea and its selection survives), and a delegated click on every [data-format] button.
function setupComposerToolbar(toolbar, textarea, hideButton) {
  if (!toolbar || !textarea) return;
  hideButton?.addEventListener('click', () => hideComposerToolbar(textarea));
  toolbar.addEventListener('mousedown', (event) => {
    // Keep the textarea focused + its selection intact when a toolbar button is pressed. File inputs / the emoji
    // picker / link dialog manage their own focus, so preventing the focus-shift here is safe for them too.
    if (event.target.closest('.composer-toolbar-button, .composer-toolbar-hide, .composer-toolbar-dock, .composer-toolbar-maximize')) event.preventDefault();
  });
  toolbar.addEventListener('click', (event) => {
    const button = event.target.closest('[data-format]');
    if (!button) return;
    event.preventDefault();
    applyComposerFormat(textarea, button.dataset.format);
  });
  // Open on a deliberate click/tap of the field (NOT on focus/tab — the owner: it appears only on field click,
  // and typing must not summon it). ▼ closes it; once open it stays through typing so you can format mid-compose.
  textarea.addEventListener('click', () => showComposerToolbar(textarea));
}

// Composer preview removed in v773: the WYSIWYG editor renders the real content live (image/file/payment/share
// blocks), so a separate preview modal is redundant.

function insertImageMarkerForComposer(kind, index) {
  const marker = `[image ${index}]`;
  insertComposerMarker(kind === 'public' ? publicMessageInput : messageInput, marker);
}

// File markers mirror image markers (v759): attaching inserts `[file N]` at the cursor so the
// attachment has a concrete place in the message instead of silently trailing the body. The public
// composer serves posts AND comments (comment mode = publicCommentTarget set), so both get this.
function insertFileMarkerForComposer(kind, index) {
  insertComposerMarker(kind === 'public' ? publicMessageInput : messageInput, `[file ${index}]`);
}

// File removal is ALL-at-once (one clear button wipes the whole attachment array), so strip EVERY
// `[file N]` marker — a lingering orphan would resolve to zero blocks and just disable send, but it
// reads as content the user has to hand-delete. `(?!\()` keeps labeled links [file 1](url) intact.
function removeAllFileMarkersForComposer(kind) {
  const textarea = kind === 'public' ? publicMessageInput : messageInput;
  if (!textarea) return;
  // Remove each marker LINE locally (the marker + its own leading newline; insertComposerMarker puts
  // markers on their own line), never a global whitespace rewrite — a whole-draft blank-line collapse
  // would destroy deliberate wide spacing in regions that never contained a marker.
  let value = String(textarea.value ?? '').replace(/\n?\[file\s+\d+\](?!\()(?=\n|$)/ig, '');
  value = value.replace(/\[file\s+\d+\](?!\()/ig, ''); // inline leftovers (user-edited placement)
  if (!value.trim()) value = ''; // markers were the only content -> clear (send guard disables)
  textarea.value = value;
}

// Removing an image ATTACHMENT must also drop its "[image N]" text marker (and renumber the markers AFTER it, since the
// attachment array re-indexes down by one) — otherwise an orphaned marker lingers in the composer and sending it builds
// a capsule with no real block -> "Capsule publish payload is missing". removedIndex is the 0-based index removed.
function removeImageMarkerForComposer(kind, removedIndex) {
  const textarea = kind === 'public' ? publicMessageInput : messageInput;
  if (!textarea) return;
  const removedMarkerNum = Number(removedIndex) + 1; // markers are 1-based: [image 1] == attachment index 0
  let droppedOne = false;
  const next = String(textarea.value ?? '').replace(/\[(?:image|img)\s+(\d+)\](?!\()/ig, (match, numStr) => { // (?!\() : never touch a labeled link [image N](url)
    const n = Number(numStr);
    if (!droppedOne && n === removedMarkerNum) { droppedOne = true; return ''; } // drop the removed image's marker (first match)
    if (n > removedMarkerNum) return `[image ${n - 1}]`;                          // renumber the ones after it (array shifted down)
    return match;
  });
  let value = next.replace(/\n{3,}/g, '\n\n'); // collapse the blank line a self-line marker left behind
  if (!value.trim()) value = '';               // the marker was the only content -> clear (also disables send via the guard)
  textarea.value = value;
}


function enforceComposerByteLimit() {
  return;
}

function enforcePublicComposerByteLimit() {
  return;
}

// Download a received FILE block (v652). The display block carries a data: URL string; the Blob is built at
// click time (no persistent objectURLs). Telegram's in-app WebView silently swallows <a download>.click() —
// there we explain instead of silent-failing (a binary can't be "copied manually" like the JSON export).
async function downloadFileBlock(block) {
  const url = String(block?.url ?? '');
  const name = String(block?.name ?? 'file');
  if (!url.startsWith('data:')) return;
  if (isTelegramEnv()) {
    await openActionDialog({
      title: t('dialog.downloadInBrowserTitle'),
      hint: t('dialog.telegramDownloadHint', { name }),
      submitLabel: t('common.ok'),
      fields: [],
    });
    return;
  }
  const comma = url.indexOf(',');
  const binary = atob(url.slice(comma + 1));
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  const blob = new Blob([bytes], { type: block?.mime || 'application/octet-stream' });
  const objectUrl = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = objectUrl;
  link.download = name;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(objectUrl), 0);
}

// A tappable chip for a FILE block (bubble + public surfaces): name + size, click downloads.
function buildFileBlockChip(block) {
  const chip = document.createElement('button');
  chip.type = 'button';
  chip.className = 'message-file-chip';
  const icon = document.createElement('span');
  icon.className = 'icon icon-download';
  const name = document.createElement('span');
  name.className = 'message-file-name';
  name.textContent = String(block.name ?? t('chat.fileFallbackName'));
  const size = document.createElement('span');
  size.className = 'message-file-size';
  size.textContent = imageByteCountLabel(block.size);
  chip.append(icon, name, size);
  chip.title = t('chat.downloadFileTitle', { name: block.name ?? t('chat.fileFallbackName') });
  chip.addEventListener('click', (event) => {
    event.stopPropagation();
    downloadFileBlock(block).catch((error) => console.error(error));
  });
  return chip;
}

async function downloadJsonFile(filename, value) {
  const json = `${JSON.stringify(value, null, 2)}\n`;
  if (isTelegramEnv()) {
    // <a download>.click() silently fails in Telegram's in-app WebView, so the
    // file would never save — surface the content for manual copy instead. Await
    // the copy dialog so a mandatory export step only completes once acknowledged.
    await showTelegramManualExportDialog(filename, json);
    return;
  }
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

function safeWalletKeyFilename(record) {
  const address = storedWalletAddressForCopy(record) || record?.address || 'wallet';
  const safeAddress = String(address).replace(/[^a-zA-Z0-9_-]+/g, '-').slice(0, 24) || 'wallet';
  return `platho-wallet-key-${safeAddress}.json`;
}

function readStoredToncenterApiKey() {
  let key = globalThis.plathoToncenterApiKey ?? null;
  if (key == null) {
    try { key = globalThis.localStorage?.getItem(TONCENTER_API_KEY_STORAGE_KEY) || null; } catch { key = null; }
  }
  return key || null;
}

// The per-user toncenter API key is bundled into the wallet-key backup so restoring the key on another
// device brings the RPC key too. It is ENCRYPTED under the wallet's own recovery phrase (the same secret
// that already protects the wallet), so the backup file carries ZERO plaintext secret material — only the
// holder of the wallet password (→ seed) can recover it. Reuses the wallet PBKDF2/AES-GCM primitives.
async function encryptToncenterApiKeyForBackup(apiKey, unlockedWallet) {
  const phrase = exportPlathoWalletRecoveryPhrase(unlockedWallet);
  if (!phrase) throw new Error('Cannot protect the RPC key without the unlocked wallet');
  const salt = randomStorageBytes(16);
  const iv = randomStorageBytes(12);
  const key = await deriveWalletStorageKey(phrase, salt);
  const ciphertext = new Uint8Array(await walletStorageCrypto().subtle.encrypt(
    { name: 'AES-GCM', iv }, key, new TextEncoder().encode(String(apiKey)),
  ));
  return {
    kdf: PLATHO_WALLET_KDF_NAME,
    iterations: PLATHO_WALLET_KDF_ITERATIONS,
    salt: walletBytesToBase64(salt),
    cipher: PLATHO_WALLET_CIPHER_NAME,
    iv: walletBytesToBase64(iv),
    ciphertext: walletBytesToBase64(ciphertext),
  };
}

async function decryptToncenterApiKeyFromBackup(enc, unlockedWallet) {
  if (!enc || typeof enc.salt !== 'string' || typeof enc.iv !== 'string' || typeof enc.ciphertext !== 'string') {
    return null;
  }
  const phrase = exportPlathoWalletRecoveryPhrase(unlockedWallet);
  if (!phrase) return null;
  const salt = walletBase64ToBytes(enc.salt);
  const iv = walletBase64ToBytes(enc.iv);
  const ciphertext = walletBase64ToBytes(enc.ciphertext);
  const key = await deriveWalletStorageKey(phrase, salt, Number(enc.iterations ?? PLATHO_WALLET_KDF_ITERATIONS));
  const plaintext = await walletStorageCrypto().subtle.decrypt({ name: 'AES-GCM', iv }, key, ciphertext);
  return new TextDecoder().decode(new Uint8Array(plaintext));
}

async function walletKeyBackupFromRecord(record, unlockedWallet = plathoWallet) {
  if (!record || record.kind !== PLATHO_WALLET_STORAGE_KIND) {
    throw new Error('Encrypted wallet key is missing');
  }
  // v3: the toncenter key is encrypted under the wallet seed (see encryptToncenterApiKeyForBackup) so the
  // file holds no plaintext secret. If it can't be encrypted (no unlocked wallet) the key is OMITTED — never
  // written in the clear. Backward-compat: v1 had no key, v2 carried it in plaintext; the importer reads all.
  const toncenterApiKey = readStoredToncenterApiKey();
  let toncenterApiKeyEnc = null;
  if (toncenterApiKey && unlockedWallet) {
    try {
      toncenterApiKeyEnc = await encryptToncenterApiKeyForBackup(toncenterApiKey, unlockedWallet);
    } catch (error) {
      console.error(error);
      toncenterApiKeyEnc = null;
    }
  }
  return {
    kind: PLATHO_WALLET_KEY_BACKUP_KIND,
    version: 3,
    exportedAt: new Date().toISOString(),
    walletAddress: storedWalletAddressForCopy(record),
    encryptedWallet: record,
    ...(toncenterApiKeyEnc ? { toncenterApiKeyEnc } : {}),
  };
}

async function downloadEncryptedWalletKeyBackup(record = readEncryptedPlathoWalletRecord(), unlockedWallet = plathoWallet) {
  if (!record) throw new Error('No encrypted wallet key is stored on this device');
  await downloadJsonFile(safeWalletKeyFilename(record), await walletKeyBackupFromRecord(record, unlockedWallet));
  // The key file (or the Telegram manual-copy dialog) is now saved/acknowledged — clear the backup nudge.
  markWalletKeyBackupDone(storedWalletAddressForCopy(record) || record?.address || null);
}

async function offerEncryptedWalletKeyBackup(reason = t('wallet.backupReasonDefault')) {
  const record = readEncryptedPlathoWalletRecord();
  if (!record) return false;
  const result = await openActionDialog({
    title: t('wallet.saveKeyBackupTitle'),
    hint: reason,
    submitLabel: t('wallet.saveEncryptedKey'),
    dismissOnBackdrop: false,
    fields: [],
    summary: [
      { label: t('wallet.backupRowFile'), value: t('wallet.backupRowFileValue') },
      { label: t('wallet.backupRowPassword'), value: t('wallet.backupRowPasswordValue') },
      { label: t('wallet.backupRowUse'), value: t('wallet.backupRowUseValue') },
      { label: t('wallet.backupRowWhy'), value: t('wallet.backupRowWhyValue') },
    ],
  });
  if (!result) return false;
  // If a toncenter key is set but the wallet is locked, unlock so it can be encrypted into the backup
  // (never written in the clear). If the user cancels, the file still saves — just without the RPC key.
  let unlockedWallet = plathoWallet;
  if (!unlockedWallet && readStoredToncenterApiKey()) {
    unlockedWallet = await requestAndDecryptEncryptedWallet(record, {
      title: t('wallet.protectRpcKeyTitle'),
      hint: t('wallet.protectRpcKeyHint'),
      submitLabel: t('wallet.saveEncryptedKey'),
    });
  }
  await downloadEncryptedWalletKeyBackup(record, unlockedWallet);
  return true;
}

function encryptedWalletRecordFromBackup(value) {
  const record = value?.kind === PLATHO_WALLET_KEY_BACKUP_KIND
    ? value.encryptedWallet
    : value;
  if (!record || record.kind !== PLATHO_WALLET_STORAGE_KIND) {
    throw new Error('This is not a Platho encrypted wallet key file');
  }
  if (typeof record.salt !== 'string' || typeof record.iv !== 'string' || typeof record.ciphertext !== 'string') {
    throw new Error('Encrypted wallet key file is incomplete');
  }
  return record;
}

async function readJsonFile(file) {
  if (!file) return null;
  const text = await file.text();
  return JSON.parse(text);
}

const PLATHO_LOCAL_INDEXED_DB_NAMES = Object.freeze([
  LEGACY_MESSAGE_HISTORY_DB_NAME,
  LEGACY_REPLAY_DB_NAME,
]);

function deleteIndexedDbDatabase(name) {
  return new Promise((resolve) => {
    if (!globalThis.indexedDB) {
      resolve(false);
      return;
    }
    const request = indexedDB.deleteDatabase(name);
    request.onsuccess = () => resolve(true);
    request.onerror = () => resolve(false);
    request.onblocked = () => resolve(false);
  });
}

async function plathoLocalIndexedDbNames() {
  const names = new Set([
    ...PLATHO_LOCAL_INDEXED_DB_NAMES,
    currentMessageHistoryDbName(),
    currentReplayDbName(),
  ]);
  if (globalThis.indexedDB?.databases) {
    try {
      const databases = await indexedDB.databases();
      for (const database of databases ?? []) {
        const name = database?.name;
        if (typeof name !== 'string') continue;
        if (
          name === LEGACY_MESSAGE_HISTORY_DB_NAME
          || name === LEGACY_REPLAY_DB_NAME
          || name.startsWith(`${LEGACY_MESSAGE_HISTORY_DB_NAME}.`)
          || name.startsWith(`${LEGACY_REPLAY_DB_NAME}.`)
        ) {
          names.add(name);
        }
      }
    } catch {
      // Some browsers expose IndexedDB but do not allow database enumeration.
    }
  }
  return [...names];
}

function clearDocumentCookies() {
  for (const item of document.cookie.split(';')) {
    const name = item.split('=')[0]?.trim();
    if (!name) continue;
    document.cookie = `${name}=; Max-Age=0; path=/; SameSite=Lax`;
  }
}

async function clearPlathoLocalData() {
  // The Telegram cloud mirror goes FIRST and FAIL-CLOSED: if it cannot be wiped, the boot right after the
  // reload would silently restore the encrypted wallet from it and the "clear" would be a lie (the local
  // state stays untouched on the throw, so the user just sees "blocked" and can retry).
  if (!(await clearTelegramCloudAppData())) {
    throw new Error('Telegram cloud data could not be cleared');
  }
  localStorageOrNull()?.clear();
  globalThis.sessionStorage?.clear?.();
  clearDocumentCookies();
  await Promise.all((await plathoLocalIndexedDbNames()).map((name) => deleteIndexedDbDatabase(name)));
  if (globalThis.caches?.keys) {
    const keys = await caches.keys();
    await Promise.all(keys.filter((key) => key.startsWith('platho-')).map((key) => caches.delete(key)));
  }
  if (navigator.serviceWorker?.getRegistrations) {
    const registrations = await navigator.serviceWorker.getRegistrations();
    await Promise.all(registrations.map((registration) => registration.unregister()));
  }
}

// The Vault tab is INERT until the account is activated: moving GRAM into the Vault before activation would
// strand it (withdrawing needs the on-chain-registered auth key), and there is no reason to fund it first.
// Shown dark-grey (.is-locked) + disabled with an explanatory title. Activation lives in the PROFILE tab, so
// nothing needed to activate is behind this gate. Re-runs on every refreshMessagingControls (incl. right after
// activation), so it unlocks the moment the account goes active.
function refreshVaultTabLock() {
  const locked = !hasActivePlathoAccount();
  for (const item of railItems) {
    if (item.dataset.tab !== 'vault') continue;
    item.classList.toggle('is-locked', locked);
    item.disabled = locked;
    item.setAttribute('aria-disabled', locked ? 'true' : 'false');
    item.title = locked ? t('vault.activateAccountFirstTooltip') : t('nav.vault');
  }
  // Never sit on a locked Vault view (a stale deep-link / a just-de-activated edge): fall back to Public.
  if (locked && appShell?.dataset.view === 'vault') setView('public');
}

function refreshMessagingControls() {
  const accountActive = hasActivePlathoAccount();
  const appShellReloadPending = pendingServiceWorkerAppShellReload === true;
  const signedActionsReady = accountActive && !appShellReloadPending;
  const thread = activeThread();
  const canEditPrivateDraft = canEditPrivateComposerDraft(thread);
  const canSendPrivate = canAttemptPrivateSend(thread);
  const hasStoredWallet = hasStoredPlathoWalletRecord();
  const hasKnownWallet = Boolean(plathoWallet || hasStoredWallet);
  if (createWalletButton) createWalletButton.disabled = false;
  setText(createWalletStatus, hasKnownWallet ? t('wallet.statusReplace') : t('wallet.statusRecommended'));
  if (importWalletButton) importWalletButton.disabled = false;
  setText(importWalletStatus, hasKnownWallet ? t('wallet.statusReplace') : t('wallet.status24Words'));
  if (unlockWalletButton) {
    unlockWalletButton.disabled = Boolean(plathoWallet) || !hasStoredWallet;
    // Only show the Unlock row when it is actionable (a stored wallet that is currently locked). Hide the
    // dead "unlocked" / "not stored" states rather than showing a disabled row that just takes up space.
    unlockWalletButton.hidden = !(hasStoredWallet && !plathoWallet);
  }
  setText(unlockWalletStatus, storedWalletLockStatus());
  if (changeWalletPasswordButton) changeWalletPasswordButton.disabled = !hasStoredWallet;
  setText(changeWalletPasswordStatus, hasStoredWallet ? t('wallet.statusChange') : t('wallet.statusNotStored'));
  if (receiveWalletTonButton) receiveWalletTonButton.disabled = !currentWalletReceiveAddress();
  setText(receiveWalletTonStatus, currentWalletReceiveAddress() ? 'QR' : t('wallet.statusNoWallet'));
  if (sendWalletTonButton) sendWalletTonButton.disabled = !plathoWallet;
  setText(sendWalletTonStatus, plathoWallet ? t('wallet.statusWallet') : t('wallet.statusUnlock'));
  if (walletTonBalanceButton) walletTonBalanceButton.disabled = !plathoWallet;
  refreshWalletTonProfileStatus();
  if (exportWalletKeyButton) exportWalletKeyButton.disabled = !readEncryptedPlathoWalletRecord();
  setText(exportWalletKeyStatus, readEncryptedPlathoWalletRecord() ? t('wallet.statusEncryptedFile') : t('wallet.statusNotStored'));
  if (importWalletKeyButton) importWalletKeyButton.disabled = false;
  setText(importWalletKeyStatus, hasKnownWallet ? t('wallet.statusReplace') : t('wallet.statusFile'));
  // Keep the toncenter key field in sync with stored state on every messaging refresh — importing a v2 wallet-key
  // backup restores the key into storage, and this guarantees the Profile field reflects it (refreshMessagingControls
  // runs in the import's finally) even if the field was rendered empty before the import completed.
  refreshToncenterKeyUi();
  refreshPrefsSyncUi();
  if (exportWalletSeedButton) exportWalletSeedButton.disabled = !plathoWallet;
  if (copyWalletAddressButton) copyWalletAddressButton.disabled = !(plathoWallet || storedWalletAddressForCopy());
  if (walletDisplayModeSelect) walletDisplayModeSelect.disabled = !plathoWallet;
  // An activation external is in flight from the moment submitVaultRegisterMessagingKeys
  // broadcasts it; the Vault only creates the user a few seconds to ~a minute later.
  // Until current_key_id flips (accountActive), keep the row showing progress and
  // non-clickable instead of reverting to the resting "Activate / fee" state — otherwise
  // the button looks like it ignored the first press and the user re-clicks.
  // queueVaultPostTransactionRefresh clears the flag once activation confirms or its
  // poll horizon elapses; a wallet change resets it.
  if (accountActive) plathoAccountActivationPending = false;
  const activationPending = plathoAccountActivationPending && !accountActive && Boolean(plathoWallet) && !appShellReloadPending;
  if (registerVaultKeysButton) {
    registerVaultKeysButton.disabled = !plathoWallet || accountActive || appShellReloadPending || activationPending;
    // Only show the Activate row while activation is actionable or in progress (wallet unlocked AND the
    // account is not yet active). Hide the dead "active" state (and the no-wallet / reload-app states)
    // instead of a disabled row. The "activating" progress state stays visible (plathoWallet && !accountActive),
    // preserving the deliberate in-flight feedback at lines ~10946-10952.
    registerVaultKeysButton.hidden = !(Boolean(plathoWallet) && !accountActive && !appShellReloadPending);
  }
  setText(vaultDraftStatus, !plathoWallet
    ? t('vault.statusWalletRequired')
    : appShellReloadPending
      ? t('vault.statusReloadApp')
      : accountActive
      ? t('vault.statusActive')
      : activationPending
      ? t('vault.statusActivating')
      : t('vault.activationFeeGram', { fee: plathoAccountActivationFeeLabel() }));
  if (replaceVaultKeysButton) replaceVaultKeysButton.disabled = !plathoWallet || !signedActionsReady;
  if (syncMessagesButton) syncMessagesButton.disabled = !plathoWallet || !signedActionsReady || messageSyncManualInFlight;
  if (mintUsernameButton) mintUsernameButton.disabled = false;
  if (linkUsernameButton) linkUsernameButton.disabled = false;
  if (setAvatarButton) setAvatarButton.disabled = plathoProfileAvatarPending;
  // Secondary composer buttons follow the SEND state, not the draft state (owner: an inactive composer must
  // not show live-looking buttons); the eye + emoji live in the refreshPrivateSendButtonState funnel below.
  // Only the text INPUT stays on the draft predicate (drafting while funding/activating is allowed —
  // PWA-ACTIVATION-02).
  if (paymentCheckButton) paymentCheckButton.disabled = !canSendPrivate;
  if (privateImageButton) privateImageButton.disabled = !canSendPrivate;
  if (privateComposerAddButton) privateComposerAddButton.disabled = !canSendPrivate;
  if (privateSenderModeSelect) privateSenderModeSelect.disabled = !plathoWallet;
  if (messageInput) {
    messageInput.disabled = !canEditPrivateDraft;
  }
  refreshPrivateSendButtonState();
  if (publicMessageInput) publicMessageInput.disabled = !plathoWallet || !signedActionsReady;
  // The comments checkbox (and its label dim class) is owned by refreshPublicSendButtonState — one predicate
  // for the whole public composer row, no scattered weaker writes.
  refreshPublicSendButtonState();
  renderAthFlushStatus();
  for (const button of actionGrid?.querySelectorAll('button[data-action]') ?? []) {
    button.disabled = !plathoWallet || !signedActionsReady;
  }
  railItems.forEach((item) => {
    item.disabled = false;
    item.title = item.getAttribute('aria-label') ?? '';
  });
  // AFTER the blanket rail re-enable above (which would otherwise undo the gate): lock the Vault tab until the
  // account is activated.
  refreshVaultTabLock();
  refreshVaultMoveWidget();
  refreshComposerCostStatus();
  refreshConversationSubtitle();
  refreshMessageActionStatuses({ keepSyncStatus: true });
}

function setView(view) {
  // Switching tabs leaves the composing context — collapse a full-screen composer so its fixed overlay can't cover
  // the tab the user switched to (the rail is reachable via keyboard / TG even though the overlay covers it visually).
  exitComposerMaximize();
  // The Vault tab is gated until activation (see refreshVaultTabLock) — a programmatic/deep-link attempt to
  // open it un-activated falls back to Public.
  if (view === 'vault' && !hasActivePlathoAccount()) view = 'public';
  appShell.dataset.view = view;
  if (view !== 'chats') {
    appShell.dataset.chatOpen = 'false';
  } else {
    // Restore the open conversation when returning to the private tab. On mobile, data-chat-open is the only
    // thing the CSS uses to choose the conversation pane vs the thread list; switching away cleared it, so
    // without this the list shows instead of the chat the user was in. Gate on activeThreadId (the explicit
    // selection), NOT activeThread() which falls back to threads[0] — matches the boot-time logic.
    appShell.dataset.chatOpen = activeThreadId ? 'true' : 'false';
  }
  railItems.forEach((item) => item.classList.toggle('is-active', item.dataset.tab === view));
  panels.forEach((panel) => panel.classList.toggle('is-active', panel.dataset.panel === view));
  if (view === 'chats') {
    // The conversation isn't rendered while this tab is hidden (boot opens on Public — see the guard in
    // renderConversation), so render it now that the strip is visible. Unconditional: renderConversation resolves the
    // active thread (or falls back to threads[0], or the empty state), so the pane is correct the instant the tab
    // opens instead of sitting on a stale "No private chat" until the next sync. It rebuilds with eager images whose
    // load handlers re-anchor to the true bottom as they decode — the same path the chat-list selection uses — so the
    // chat lands at the end.
    conversationStickToBottom = true;
    renderConversation();
  }
  // Switching tabs no longer re-triggers a sync — the unified background loop (scheduleMessageAutoSync) keeps
  // BOTH private messages and the public feed fresh on every tab, so switch-in is instant. setView only renders.
  if (view === 'public') {
    // Restore the open post detail when returning to the Public tab — mirrors the private-tab restore above
    // (data-chat-open from activeThreadId). Switching away leaves publicPane.dataset.postOpen +
    // publicPostDetailItem intact, and renderPublicSurface re-renders the open detail from the cache, so the
    // user lands back on the post they were reading instead of the feed. Back (closeNavOverlay ->
    // closePublicPostDetail) clears that state, so a user who had backed out to the feed still lands on the feed.
    // anchorUnread only applies to the feed scroll, so skip it while a detail (or a channel view) is restored.
    renderPublicSurface({ anchorUnread: publicPane?.dataset?.postOpen !== 'true' && publicPane?.dataset?.channelOpen !== 'true' });
  }
  if (view === 'vault') {
    refreshVaultNow({ includeActivation: true, includeStats: true }).catch((error) => {
      const rateLimited = noteTonRpcRateLimit(error);
      setVaultStatus(rateLimited ? 'RPC busy, retrying' : 'sync blocked');
      if (!isExpectedVaultProviderUnavailable(error)) console.error(error);
    });
  } else {
    scheduleVaultAutoRefresh(2_000);
  }
  if (view === 'profile' && plathoWallet?.address) {
    refreshProfilePaneReads();
  }
}

// Serialize the Profile chain reads (GRAM balance -> ATH stats -> own avatar). Firing them concurrently is
// the iOS-WebKit run-loop-stall pattern fixed for the Vault in v509: 2+ concurrent toncenter reads freeze
// the page (it scrolls via the compositor but taps die — the account-activation freeze). One at a time.
// Shared by the Profile tab's open path and the header sync indicator's tap-to-sync on that tab.
function refreshProfilePaneReads() {
  if (!plathoWallet?.address) return;
  (async () => {
    try { await refreshWalletTonBalanceForProfile(); } catch (error) { if (!noteTonRpcRateLimit(error)) console.error(error); }
    try { await refreshAthProtocolStats(); } catch { /* best effort */ }
    try { await refreshOwnProfileAvatar(); } catch (error) { console.error(error); }
  })();
}

// "Add a contact" plate pinned at the top of the private thread list — the labeled replacement for the old
// search-row "+" (owner: a bare plus is unreadable), and the mirror of the public feed's channels plate. ONE
// persistent node: renderThreads re-inserts it first on every render and the row reconciliation skips it, so
// its listener survives; data-i18n keeps it retranslatable in place (quick-start language switch, no reload).
let privateContactCtaCard = null;
function ensureContactCtaCard() {
  if (privateContactCtaCard) return privateContactCtaCard;
  const card = document.createElement('article');
  card.className = 'feed-item discovery-cta contact-cta';
  const head = document.createElement('div');
  head.className = 'discovery-cta-head';
  const badge = document.createElement('span');
  badge.className = 'discovery-cta-icon';
  const badgeIcon = document.createElement('span');
  badgeIcon.className = 'icon icon-user';
  badge.append(badgeIcon);
  const textWrap = document.createElement('div');
  textWrap.className = 'discovery-cta-text';
  const title = document.createElement('h2');
  title.setAttribute('data-i18n', 'chat.contactCtaTitle');
  title.textContent = t('chat.contactCtaTitle');
  const body = document.createElement('p');
  body.setAttribute('data-i18n', 'chat.contactCtaBody');
  body.textContent = t('chat.contactCtaBody');
  textWrap.append(title, body);
  head.append(badge, textWrap);
  const actions = document.createElement('div');
  actions.className = 'discovery-cta-actions';
  const add = document.createElement('button');
  add.type = 'button';
  add.className = 'discovery-cta-action';
  add.setAttribute('data-i18n', 'chat.contactCtaAction');
  add.textContent = t('chat.contactCtaAction');
  add.addEventListener('click', openNewChatDialog);
  actions.append(add);
  card.append(head, actions);
  privateContactCtaCard = card;
  return card;
}

function renderThreads() {
  const q = search.value.trim().toLowerCase();
  threads.forEach(hydrateThreadDisplayFromContactStore);
  const visibleThreads = threads
    .filter((thread) => {
      // Hide a dialog whose sender is still being identified (claimed but not yet cryptographically verified) so a
      // real dialog only appears once resolved — no "Anonymous …" flicker. Shown after the grace window so a
      // genuinely anonymous or stuck message is never permanently hidden.
      if (isTransientPendingResolutionThread(thread)) return false;
      return `${thread.name} ${thread.preview} ${thread.state} ${threadIdentitySearchText(thread)}`.toLowerCase().includes(q);
    });
  // My notes is PINNED first regardless of activity order — a partition at render time, so no array mutation
  // (chain sync / history restore reorder `threads` freely and must not have to know about the pin). The other
  // dialogs sort by RECENCY (newest activity first, threadLastActivityMs): an active chat rises to the top, a
  // dormant one quietly drifts down — instead of the old insertion order where every NEW chat appeared LAST.
  // Display-order only (a sorted copy): the `threads` array keeps its structural invariants untouched. The sort is
  // stable, so dialogs with equal/unknown activity keep their relative order.
  const ordered = [
    ...visibleThreads.filter((thread) => isSavedMessagesThread(thread)),
    ...visibleThreads
      .filter((thread) => !isSavedMessagesThread(thread))
      .sort((a, b) => threadLastActivityMs(b) - threadLastActivityMs(a)),
  ];
  // F3 (scale): keyed reconciliation instead of innerHTML='' + a full O(chats) teardown/rebuild. renderThreads runs
  // on every sync tick AND every search keystroke, so a user with hundreds of chats otherwise rebuilt every row
  // (avatar + identity label + a fresh click listener each) on each. Now existing rows are REUSED (matched by
  // thread.id), only their mutable content is patched (applyThreadRow), and only added/removed/reordered rows touch
  // the DOM. One-time migration: rows left by the pre-F3 build carry no _refs — drop them so they are rebuilt once.
  // (Checked on the first ROW, not the first child — the contact-CTA plate legitimately carries no _refs.)
  const firstRow = threadList.querySelector(':scope > [data-thread]');
  if (firstRow && !firstRow._refs) threadList.replaceChildren();
  const existingRows = new Map();
  for (const node of Array.from(threadList.children)) {
    const id = node.dataset?.thread;
    if (id && node._refs) existingRows.set(id, node);
    else if (node !== privateContactCtaCard) node.remove();
  }
  const seen = new Set();
  // The add-a-contact plate stays pinned as the FIRST list entry; hidden while a search is filtering the list
  // (results must not be pushed down — mirrors the public discovery plate's search behavior).
  const contactCta = ensureContactCtaCard();
  contactCta.hidden = q.length > 0;
  if (threadList.firstElementChild !== contactCta) threadList.insertBefore(contactCta, threadList.firstElementChild);
  let prev = contactCta;
  for (const thread of ordered) {
    seen.add(thread.id);
    let item = existingRows.get(thread.id);
    if (!item) item = buildThreadRow(thread.id);
    applyThreadRow(item, thread);
    const anchor = prev ? prev.nextElementSibling : threadList.firstElementChild;
    if (item !== anchor) threadList.insertBefore(item, anchor);
    prev = item;
  }
  for (const [id, node] of existingRows) if (!seen.has(id)) node.remove();
}

// Build a reusable thread-list row: the STRUCTURE + a single click listener. The listener resolves its thread by id
// at CLICK time (rows are reused across renders keyed by thread.id, so capturing a thread object would go stale).
function buildThreadRow(threadId) {
  const item = document.createElement('button');
  item.type = 'button';
  item.dataset.thread = threadId;
  const avatar = document.createElement('div');
  avatar.className = 'avatar';
  avatar.setAttribute('aria-hidden', 'true');
  const main = document.createElement('div');
  main.className = 'thread-main';
  const top = document.createElement('div');
  top.className = 'thread-top';
  const name = document.createElement('div');
  const preview = document.createElement('div');
  preview.className = 'thread-preview';
  const state = document.createElement('div');
  state.className = 'thread-state';
  const time = document.createElement('div');
  time.className = 'thread-time';
  const side = document.createElement('div');
  side.className = 'thread-side';
  side.append(time);
  top.append(name);
  main.append(top, preview, state);
  item.append(avatar, main, side);
  item._refs = { avatar, name, preview, state, time, side };
  item.addEventListener('click', () => {
    const thread = threads.find((t) => t.id === item.dataset.thread);
    if (!thread) return;
    // A reply quote references a message of the PREVIOUS dialog — drop it on any switch.
    if (activeThreadId !== thread.id) setPrivateReplyDraft(null);
    activeThreadId = thread.id;
    appShell.dataset.chatOpen = 'true';
    // Re-selecting the CURRENT dialog lands at the end (conversationThreadChanged is false, so renderConversation's
    // open-anchor is not armed and this stickToBottom drives the scroll). Opening a DIFFERENT dialog is owned by
    // renderConversation's open-scroll (latest, or first-unread at the top on overflow) — which needs the unread
    // count, so DO NOT markThreadRead here: renderConversation captures the count and THEN marks the thread read.
    conversationStickToBottom = true;
    renderThreads();
    renderConversation();
    // Re-check this dialog's .ath (has the peer transferred it away?) then reconcile OUR OWN linked .ath — both
    // via the shared username-hygiene queue, so no two username resolves ever run concurrently (v509 iOS
    // freeze). Each is throttled internally; repaints happen only on an actual change.
    queueUsernameHygiene(() => revalidateThreadUsernameVariants(thread));
    queueUsernameHygiene(() => reconcileOwnLinkedUsername());
  });
  return item;
}

// Patch every MUTABLE field of a (new or reused) thread row in place. One apply path for create AND update, so a
// reused row can never diverge from a freshly-built one.
function applyThreadRow(item, thread) {
  const { avatar, name, preview, state, time, side } = item._refs;
  const unread = threadUnreadCount(thread);
  item.className = `thread-item${thread.id === activeThreadId ? ' is-selected' : ''}${unread > 0 ? ' has-unread' : ''}`;
  setThreadAvatarNode(avatar, thread);
  setIdentityLabel(name, thread, 'thread-name identity-label');
  preview.textContent = stripInlineFormatting(thread.preview); // thread.preview is plain text — drop raw **/*/` markers
  state.textContent = thread.state;
  // Real last-message time, not the old constant 'now' word (v654). Computed at render (not cached on the
  // thread) so the today/weekday/date bucket stays correct as days roll over between re-renders.
  const lastMessage = thread.messages?.[thread.messages.length - 1] ?? null;
  const lastMs = lastMessage ? messageCreatedAtMs(lastMessage) : null;
  time.textContent = lastMs !== null ? formatThreadListTimestamp(lastMs) : '';
  // The unread badge lives in `side` after `time`; reconcile it in place (create / update / remove).
  let badge = side.querySelector('.thread-unread-badge');
  if (unread > 0) {
    if (!badge) {
      badge = document.createElement('div');
      badge.className = 'thread-unread-badge';
      side.append(badge);
    }
    // Count-only pill (messenger-canonical): the localized WORD ("unread" in longer languages) doesn't fit the
    // narrow side column and wrapped the badge onto two lines. The pill + its placement already read as "unread";
    // the full localized phrase stays for screen readers via aria-label.
    badge.textContent = unread > 99 ? '99+' : String(unread);
    badge.setAttribute('aria-label', unread > 99 ? t('chat.unreadOverflow') : tPlural('chat.unreadCount', unread));
  } else if (badge) {
    badge.remove();
  }
}

// Conversation scroll behaviour. The view sticks to the bottom by default, so opening a chat (incl. right after a
// reload, once its messages render) lands on the latest, and the user's own new message smooth-scrolls into view.
// Once the reader scrolls up to read history it stops sticking, and a background re-render (sync / status / a
// received message) keeps them where they are instead of yanking the view down. The "at bottom" flag + saved
// position are read from a DEBOUNCED scroll handler, so the transient scroll-to-0 a re-render causes when it
// rebuilds the strip cannot corrupt them — that race is what made the earlier attempts land back at the top.
let lastConversationThreadId = null;
let lastConversationMsgCount = 0;
let conversationStickToBottom = true;
let conversationSavedScrollTop = 0;
// Open-scroll anchor (v740). Replaces the fragile "restore where you were last time in this dialog" (it mislanded a
// long history at the TOP during the multi-render open burst). On OPENING a dialog we always land on the latest, OR —
// when unread messages OVERFLOW the viewport — put the FIRST unread at the top so the reader starts exactly where the
// new messages begin and reads down. conversationOpenScrollUnsettled stays true across the whole open burst (every
// render re-applies the anchor) and clears on the first genuine user scroll. It does NOT change the in-dialog rule: a
// background sync while you read history still keeps your position (the else branch of the render's final rAF).
let conversationOpenFirstUnreadRef = null;
let conversationOpenScrollUnsettled = false;
let conversationProgrammaticScrollAt = 0;
// Set by the private send submit right before it inserts the optimistic own message; the NEXT renderConversation
// consumes it to abandon the open-anchor (the user just sent -> show their message). Precise: keyed on the actual
// send action, NOT on "the tail is an 'out' message" (a late out-of-order INCOMING can leave an 'out' tail and would
// otherwise wrongly clear a first-unread anchor and yank the reader — the v740 review finding).
let ownSendPendingRender = false;
// Per-row structure fingerprint of the last full conversation render — drives the status-only fast path
// (a status tick patches rows in place instead of rebuilding the strip, so the scroller never moves).
let lastConversationRenderSnapshot = null;

// Track the bottom-pin state and position IMMEDIATELY (no debounce): the image-load re-anchor and the
// hidden-strip fallback read these, and a debounced value lags an active gesture — a stale "still pinned"
// snapshot used to yank a reader who had just scrolled up back to the bottom.
function rememberConversationScroll() {
  if (!messageStrip) return;
  // A genuine user scroll during the open window ends the open-anchor (the reader took over). Our OWN programmatic
  // anchor writes also fire this handler, so ignore a scroll event that lands right after one (within 150ms).
  if (conversationOpenScrollUnsettled && Date.now() - conversationProgrammaticScrollAt > 150) {
    conversationOpenScrollUnsettled = false;
  }
  conversationStickToBottom = (messageStrip.scrollHeight - messageStrip.scrollTop - messageStrip.clientHeight) < 24;
  conversationSavedScrollTop = messageStrip.scrollTop;
}
messageStrip?.addEventListener('scroll', rememberConversationScroll, { passive: true });

// The FIRST unread INCOMING message (the oldest of the last `unreadCount` incoming), from the unread count taken
// BEFORE markThreadRead cleared it. Walks the SORTED messages from the tail. null when nothing is unread.
function firstUnreadIncomingMessageRef(thread, unreadCount) {
  const n = Number(unreadCount) || 0;
  if (n <= 0) return null;
  const messages = Array.isArray(thread?.messages) ? thread.messages : [];
  let seenIncoming = 0;
  for (let i = messages.length - 1; i >= 0; i -= 1) {
    if (messages[i]?.type === 'in') {
      seenIncoming += 1;
      if (seenIncoming >= n) return messages[i];
    }
  }
  return null;
}

function setConversationScrollTop(top) {
  if (!messageStrip) return;
  conversationProgrammaticScrollAt = Date.now(); // mark this as OUR write so the scroll listener never reads it as a user scroll
  messageStrip.scrollTop = top;
}

// Apply the open-scroll anchor: land on the latest when the unread fit the last screen (few/no new), else put the
// FIRST unread at the top of the viewport (many new -> read down from there). Idempotent; re-run on every render of
// the open burst so the transient scroll-to-0 a rebuild causes can never leave a long history stuck at the top.
function applyConversationOpenScroll() {
  if (!messageStrip) return;
  const maxScrollTop = Math.max(0, messageStrip.scrollHeight - messageStrip.clientHeight);
  const firstUnreadRow = conversationOpenFirstUnreadRef ? messageStrip.querySelector('[data-first-unread="true"]') : null;
  let anchoredToUnread = false;
  if (firstUnreadRow) {
    const rowTopWithinStrip = messageStrip.scrollTop
      + (firstUnreadRow.getBoundingClientRect().top - messageStrip.getBoundingClientRect().top);
    // The first unread sits ABOVE the last screen (it would be scrolled off the top at the bottom) -> anchor it to top.
    if (rowTopWithinStrip < maxScrollTop - 4) {
      setConversationScrollTop(rowTopWithinStrip);
      anchoredToUnread = true;
    }
  }
  if (!anchoredToUnread) setConversationScrollTop(messageStrip.scrollHeight);
  conversationStickToBottom = !anchoredToUnread;
}

// STATUS-ONLY FAST PATH: when the message list is structurally identical to the last full render (same
// message objects, same rows — only meta text / status changed), patch the existing rows in place. The
// owner's rule: only the act of sending may move the dialog; a status change must never budge it — and a
// full rebuild would kill an active scroll gesture even with a perfect position restore. Anything that can
// change row STRUCTURE (meta node appearing/disappearing, payment action buttons, the manual Retry
// affordance — all derived from the status text) falls through to the full rebuild.
function applyConversationStatusOnlyPatch(thread) {
  const snapshot = lastConversationRenderSnapshot;
  if (!snapshot || snapshot.threadId !== thread.id) return false;
  const messages = Array.isArray(thread.messages) ? thread.messages : [];
  if (snapshot.rows.length !== messages.length) return false;
  if (!messageStrip || messageStrip.children.length !== messages.length) return false;
  for (let i = 0; i < messages.length; i += 1) {
    const row = snapshot.rows[i];
    const message = messages[i];
    if (row.ref !== message) return false;
    const metaText = messageMetaText(message);
    if ((metaText !== '') !== row.hasMeta) return false;
    if (message.payment && metaText !== row.metaText) return false;
    if (Boolean(privateMessageShouldShowManualActions(message)) !== row.showManual) return false;
  }
  for (let i = 0; i < messages.length; i += 1) {
    const row = snapshot.rows[i];
    const message = messages[i];
    const node = messageStrip.children[i];
    const metaText = messageMetaText(message);
    if (metaText !== row.metaText) {
      row.metaText = metaText;
      node.dataset.status = messageStatusKey(message);
      const metaNode = node.querySelector('.message-meta');
      if (metaNode) metaNode.textContent = metaText;
    }
    // A confirming send gains its chain entry id (the swipe-reply anchor) — keep it current without a rebuild.
    if (message.chainEntryId !== undefined && message.chainEntryId !== null) {
      node.dataset.entryId = String(message.chainEntryId);
    }
  }
  return true;
}

function renderConversation() {
  // The conversation pane only exists on the Private (chats) tab. Boot opens on Public and the background sync runs
  // on every tab, so without this guard we'd rebuild the whole strip — decoding every image — into a hidden pane on
  // boot and on each sync from another tab. setView('chats') re-renders on entry, so the pane is always current the
  // instant it becomes visible; rendering it while hidden is pure waste. (This is the "first render into the void"
  // that re-rendering on tab open made redundant.)
  if (appShell?.dataset.view !== 'chats') return;
  const thread = activeThread();
  if (!thread) {
    setAvatarNode(activeAvatar, 'P', null);
    activeTitle.textContent = t('chat.noPrivateChat');
    activeSubtitle.textContent = t('chat.createOrChooseChat');
    messageStrip.innerHTML = '';
    if (identityMenuButton) {
      identityMenuButton.hidden = true;
      identityMenuButton.setAttribute('aria-expanded', 'false');
    }
    if (composer) composer.dataset.readOnly = 'true';
    refreshComposerPublishPolicy();
    if (messageInput) {
      messageInput.disabled = true;
      messageInput.placeholder = plathoWallet ? t('chat.createOrChoosePrivateChat') : t('common.walletRequired');
    }
    if (sendButton) sendButton.disabled = true;
    if (paymentCheckButton) paymentCheckButton.disabled = true;
    if (privateImageButton) privateImageButton.disabled = true;
    if (privateComposerAddButton) privateComposerAddButton.disabled = true;
    if (privateAnonymousButton) privateAnonymousButton.disabled = true;
    if (privateImageModeSelect) privateImageModeSelect.disabled = true;
    lastConversationThreadId = null;
    lastConversationMsgCount = 0;
    conversationStickToBottom = true;
    conversationOpenScrollUnsettled = false;
    conversationOpenFirstUnreadRef = null;
    lastConversationRenderSnapshot = null;
    return;
  }
  // Compute the open + capture the unread count BEFORE markThreadRead clears it, so the open-scroll can anchor to the
  // first unread message.
  const conversationThreadChanged = thread.id !== lastConversationThreadId;
  const conversationOpenUnreadCount = conversationThreadChanged ? threadUnreadCount(thread) : 0;
  // Consume the "user just sent" flag exactly once (the send submit set it right before inserting the optimistic
  // message, so THIS render is the fresh own-send). Precise signal for abandoning the open-anchor — see the flag decl.
  const ownSendScrollToEnd = ownSendPendingRender;
  ownSendPendingRender = false;
  setThreadAvatarNode(activeAvatar, thread);
  if (isThreadConversationVisible(thread) && markThreadRead(thread)) {
    renderThreads();
  }
  renderConversationIdentity(thread);
  activeSubtitle.textContent = conversationSubtitleText(thread);
  // Capture the pre-render scroll state so a background re-render can restore it instead of jumping to the bottom.
  // LIVE scroll state read at render entry. The scroll listener's debounced snapshot lagged an active gesture
  // (the debounce timer reset on every scroll event), so a mid-scroll re-render restored wherever the user was
  // BEFORE the gesture began — the live read is always exact. The saved values remain only as the fallback for
  // renders while the strip is hidden/unmeasurable (a display:none scroller reads 0/0 and loses its position
  // across tab switches).
  const stripMeasurable = messageStrip.clientHeight > 0 && messageStrip.scrollHeight > 0;
  const prevConversationScrollTop = stripMeasurable ? messageStrip.scrollTop : conversationSavedScrollTop;
  // While the open burst is still settling (unsettled), the scroller is mid-rebuild and its scrollTop is transient —
  // do NOT recompute the pin state from it (that transient scroll-to-0 is exactly what mislanded a long history at the
  // top). applyConversationOpenScroll owns the position until the first user scroll clears unsettled.
  if (stripMeasurable && !conversationOpenScrollUnsettled) {
    conversationStickToBottom = (messageStrip.scrollHeight - prevConversationScrollTop - messageStrip.clientHeight) < 24;
    conversationSavedScrollTop = prevConversationScrollTop;
  }
  if (conversationThreadChanged) conversationStickToBottom = true;
  const isReadOnly = thread.readOnly === true;
  const canEditPrivateDraft = canEditPrivateComposerDraft(thread);
  const canSendPrivate = canAttemptPrivateSend(thread);

  if (composer) composer.dataset.readOnly = isReadOnly ? 'true' : 'false';
  refreshComposerPublishPolicy();
  if (messageInput) {
    messageInput.disabled = !canEditPrivateDraft;
    messageInput.placeholder = privateComposerPlaceholder({ readOnly: isReadOnly });
  }
  if (sendButton) sendButton.disabled = !canSendPrivate;
  // Secondary buttons follow the send state (the eye is owned by updatePrivateSenderModeUi below); the input
  // above stays on the draft predicate — see refreshMessagingControls for the rationale.
  if (paymentCheckButton) paymentCheckButton.disabled = !canSendPrivate;
  if (privateImageButton) privateImageButton.disabled = !canSendPrivate;
  if (privateComposerAddButton) privateComposerAddButton.disabled = !canSendPrivate;
  if (privateImageModeSelect) privateImageModeSelect.disabled = isReadOnly || !plathoWallet;

  // refreshPrivateSendButtonState also refreshes the eye (updatePrivateSenderModeUi rides in the funnel).
  refreshPrivateSendButtonState();
  sortThreadMessages(thread);
  if (conversationThreadChanged) {
    // Opening the dialog: set up the open-scroll anchor from the pre-markThreadRead unread count and mark the open
    // burst unsettled so every render re-applies the anchor until the reader scrolls.
    conversationOpenFirstUnreadRef = firstUnreadIncomingMessageRef(thread, conversationOpenUnreadCount);
    conversationOpenScrollUnsettled = true;
  }
  // A fresh outbound message at the tail (the user just sent) is the only re-render that smooth-scrolls to the end.
  const conversationMsgCount = thread.messages.length;
  const conversationLastMsg = thread.messages[conversationMsgCount - 1];
  const conversationNewOutbound = !conversationThreadChanged
    && conversationMsgCount > lastConversationMsgCount
    && conversationLastMsg?.type === 'out';
  // A fresh own-send ABANDONS the open-scroll anchor (the reader typed + sent, so they are at the composer): drop the
  // unsettled state so the rAF takes the newOutbound branch and smooth-scrolls to the sent message, instead of the
  // open-anchor branch re-pinning a first-unread-at-top and leaving the just-sent message off-screen at the bottom.
  // Gated on the PRECISE own-send flag (not conversationNewOutbound): a late out-of-order INCOMING can also leave an
  // 'out' tail with a grown count, and must NOT clear the anchor / yank the reader (the v740 review finding).
  if (ownSendScrollToEnd) conversationOpenScrollUnsettled = false;
  lastConversationThreadId = thread.id;
  lastConversationMsgCount = conversationMsgCount;
  // Status tick with identical structure -> patch in place, scroller COMPLETELY untouched (no rebuild, no
  // scroll writes, no rAF). Only a structural change (new message, payment/manual-action flip) rebuilds.
  if (!conversationThreadChanged && !conversationNewOutbound && applyConversationStatusOnlyPatch(thread)) return;
  const conversationRenderSnapshotRows = [];
  messageStrip.innerHTML = '';
  thread.messages.forEach((message) => {
    const row = document.createElement('div');
    row.className = `message ${message.type}`;
    // Chain anchor: the swipe-to-reply gesture reads it as the reply ref, and reply quotes scroll to it. A
    // not-yet-confirmed optimistic message has none — replying to it is gated until the entry id lands.
    if (message.chainEntryId !== undefined && message.chainEntryId !== null) row.dataset.entryId = String(message.chainEntryId);
    if (message === conversationOpenFirstUnreadRef) row.dataset.firstUnread = 'true';
    const bubble = document.createElement('div');
    bubble.className = 'bubble';
    const blocks = Array.isArray(message.blocks) ? message.blocks : [];
    // The REPLY block renders as a tappable quote strip at the TOP of the bubble (the block loop below ignores
    // its type); scroll target = the same messageStrip.
    const replyBlock = blocks.find((block) => block?.type === 'reply');
    if (replyBlock) bubble.append(buildReplyQuoteNode(replyBlock, messageStrip));
    if (blocks.length > 0) {
      for (const block of blocks) {
        if (block?.type === 'text' && block.text) {
          const text = document.createElement('div');
          text.className = 'message-text-block';
          appendFormattedMessageText(text, block.text);
          bubble.append(text);
        } else if (block?.type === 'image' && block.url) {
          const image = document.createElement('img');
          image.className = 'message-image';
          image.src = block.url;
          image.alt = t('chat.openImageAlt');
          // Lazy: only load images as they near the viewport (lighter for image-heavy chats). The conversation now
          // renders only when its tab is visible (not into a hidden pane), and the load handler below re-anchors to
          // the bottom as each image decodes — so scroll-to-end keeps up as the in-view images load.
          image.loading = 'lazy';
          image.tabIndex = 0;
          image.role = 'button';
          image.title = t('chat.openFullSizeImage');
          image.dataset.fullImageSrc = block.url;
          image.dataset.fullImageMeta = messageImageLightboxMeta(block);
          image.addEventListener('load', () => {
            image.dataset.fullImageMeta = messageImageLightboxMeta(block, image);
            // The real height is known only once the image decodes; if we're pinned to the end, re-anchor there so a
            // late-decoding image can't leave us short of the true bottom.
            if (conversationStickToBottom && messageStrip) messageStrip.scrollTop = messageStrip.scrollHeight;
          }, { once: true });
          bubble.append(image);
        } else if (block?.type === 'file' && block.url) {
          bubble.append(buildFileBlockChip(block));
        } else if (block?.type === 'share' && block.entryId) {
          bubble.append(buildSharedPostEmbed(block));
        }
      }
    } else if (message.text) {
      const text = document.createElement('div');
      text.className = 'message-text-block';
      appendFormattedMessageText(text, message.text);
      bubble.append(text);
    }
    if (blocks.length === 0 && message.attachment?.type === 'image' && message.attachment.url) {
      const image = document.createElement('img');
      image.className = 'message-image';
      image.src = message.attachment.url;
      image.alt = t('chat.openImageAlt');
      // Lazy (see the block-image note above): load as images near the viewport; the load handler re-anchors to the
      // bottom as each decodes.
      image.loading = 'lazy';
      image.tabIndex = 0;
      image.role = 'button';
      image.title = t('chat.openFullSizeImage');
      image.dataset.fullImageSrc = message.attachment.url;
      image.dataset.fullImageMeta = messageImageLightboxMeta(message.attachment);
      image.addEventListener('load', () => {
        image.dataset.fullImageMeta = messageImageLightboxMeta(message.attachment, image);
        if (conversationStickToBottom && messageStrip) messageStrip.scrollTop = messageStrip.scrollHeight;
      }, { once: true });
      bubble.append(image);
    }
    const manualActions = privateMessageManualActionsElement(thread, message);
    const metaText = messageMetaText(message);
    if (metaText) {
      row.dataset.status = messageStatusKey(message);
      const meta = document.createElement('div');
      meta.className = 'message-meta';
      meta.textContent = metaText;
      row.append(bubble, meta);
    } else {
      row.append(bubble);
    }
    if (manualActions) row.append(manualActions);
    appendRowReplyButton(row, beginPrivateReplyForRow);
    appendRowCopyButton(row, copyTextFromContent(message));
    messageStrip.append(row);
    conversationRenderSnapshotRows.push({
      ref: message,
      metaText,
      hasMeta: Boolean(metaText),
      showManual: Boolean(manualActions),
    });
  });
  lastConversationRenderSnapshot = { threadId: thread.id, rows: conversationRenderSnapshotRows };

  // Open burst: apply the anchor SYNCHRONOUSLY now (reading scrollHeight/getBoundingClientRect forces the layout), so
  // the NEXT render in the burst reads the correct scrollTop at its entry instead of a transient 0 — the fix for a
  // long history landing at the top. The rAF below re-applies it after layout/image settle.
  if (conversationOpenScrollUnsettled) applyConversationOpenScroll();

  requestAnimationFrame(() => {
    if (conversationOpenScrollUnsettled) {
      // Still opening — (re)apply the open anchor (latest, or first-unread at the top when the unread overflow).
      applyConversationOpenScroll();
    } else if (ownSendScrollToEnd) {
      // The user just sent — scroll their message into view as a gentle scroll, not a sudden jump. Restore the
      // pre-rebuild position first (instant) so the smooth scroll travels only from there to the new bottom, instead
      // of animating up from the cleared scrollTop=0 (the "flies to the beginning and back" jerk). Gated on the PRECISE
      // own-send flag (not conversationNewOutbound): a late out-of-order INCOMING can leave an 'out' tail with a grown
      // count and must NOT smooth-scroll a reader who has scrolled up to read history to the bottom.
      conversationStickToBottom = true;
      messageStrip.scrollTop = prevConversationScrollTop;
      messageStrip.scrollTo({ top: messageStrip.scrollHeight, behavior: 'smooth' });
    } else if (conversationStickToBottom) {
      // Already reading the latest — stay pinned to the end (instant).
      messageStrip.scrollTop = messageStrip.scrollHeight;
    } else {
      // The reader scrolled up to read history — a background re-render keeps them EXACTLY where they were
      // (the live position captured at render entry, never the lagging debounced snapshot).
      messageStrip.scrollTop = prevConversationScrollTop;
    }
  });
}

