messageInput?.addEventListener('input', (event) => {
  if (!event.isComposing) composerEditorStripNativeFormatting(messageInput); // unwrap browser <b>/inline-style typing-style artifacts
  if (!event.isComposing) composerEditorNormalizeEmptyFmt(messageInput); // drop a span a native delete emptied (S2)
  enforceComposerByteLimit();
  reconcileComposerAttachments(messageInput); // prune attachments whose atom a non-collapsed delete/paste removed
  messageInput.classList.toggle('is-empty', serializeComposerEditor(messageInput).trim() === '');
  refreshComposerCostStatus();
});
messageInput?.addEventListener('keydown', (event) => {
  if (event.isComposing) return; // IME composition (CJK etc.) owns Enter until it commits
  if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
    event.preventDefault();
    composer?.requestSubmit?.();
  }
});
// Newline (insertParagraph/insertLineBreak) + a format-bleed guard, shared with the public composer. In
// beforeinput NOT keydown so Android soft-keyboard Enter (keyCode 229, key!=='Enter') still lands a clean <br>.
messageInput?.addEventListener('beforeinput', (event) => composerEditorBeforeInput(messageInput, event));
messageInput?.addEventListener('compositionstart', () => composerEditorEscapeFmtForComposition(messageInput)); // IME text lands plain after a bold word
messageInput?.addEventListener('click', (event) => composerEditorLinkClick(messageInput, event));
messageInput?.addEventListener('copy', (event) => composerEditorCopySelection(messageInput, event, false));
messageInput?.addEventListener('cut', (event) => composerEditorCopySelection(messageInput, event, true));
messageInput?.addEventListener('paste', (event) => {
  event.preventDefault(); // strip clipboard HTML (XSS surface) — only text/plain crosses into the editor
  composerEditorInsertPlainMultiline(messageInput, event.clipboardData?.getData('text/plain') ?? '');
});
messageInput?.addEventListener('drop', (event) => {
  if (!event.dataTransfer || !Array.from(event.dataTransfer.types || []).includes('text/plain')) return; // let file drops fall through
  event.preventDefault();
  composerEditorInsertPlainMultiline(messageInput, event.dataTransfer.getData('text/plain'));
});
