publicMessageInput?.addEventListener('input', (event) => {
  if (!event.isComposing) composerEditorStripNativeFormatting(publicMessageInput); // unwrap browser <b>/inline-style typing-style artifacts
  if (!event.isComposing) composerEditorNormalizeEmptyFmt(publicMessageInput); // drop a span a native delete emptied (S2)
  enforcePublicComposerByteLimit();
  reconcileComposerAttachments(publicMessageInput); // prune attachments whose atom a non-collapsed delete/paste removed
  publicMessageInput.classList.toggle('is-empty', serializeComposerEditor(publicMessageInput).trim() === '');
  refreshComposerCostStatus();
});
publicMessageInput?.addEventListener('keydown', (event) => {
  if (event.isComposing) return; // IME composition (CJK etc.) owns Enter until it commits
  if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
    event.preventDefault();
    publicComposer?.requestSubmit?.();
  }
});
// Newline + format-bleed guard via beforeinput (not keydown) so Android soft-keyboard Enter (keyCode 229) lands.
publicMessageInput?.addEventListener('beforeinput', (event) => composerEditorBeforeInput(publicMessageInput, event));
publicMessageInput?.addEventListener('compositionstart', () => composerEditorEscapeFmtForComposition(publicMessageInput)); // IME text lands plain after a bold word
publicMessageInput?.addEventListener('click', (event) => composerEditorLinkClick(publicMessageInput, event));
publicMessageInput?.addEventListener('copy', (event) => composerEditorCopySelection(publicMessageInput, event, false));
publicMessageInput?.addEventListener('cut', (event) => composerEditorCopySelection(publicMessageInput, event, true));
publicMessageInput?.addEventListener('paste', (event) => {
  event.preventDefault(); // strip clipboard HTML (XSS surface) — only text/plain crosses into the editor
  composerEditorInsertPlainMultiline(publicMessageInput, event.clipboardData?.getData('text/plain') ?? '');
});
publicMessageInput?.addEventListener('drop', (event) => {
  if (!event.dataTransfer || !Array.from(event.dataTransfer.types || []).includes('text/plain')) return; // let file drops fall through
  event.preventDefault();
  composerEditorInsertPlainMultiline(publicMessageInput, event.dataTransfer.getData('text/plain'));
});

