async function exportEncryptedWalletKeyFile() {
  const record = readEncryptedPlathoWalletRecord();
  if (!record) throw new Error('No encrypted wallet key is stored on this device');
  const unlocked = await requestAndDecryptEncryptedWallet(record, {
    title: t('wallet.exportWalletKey'),
    hint: t('wallet.exportWalletKeyHint'),
    submitLabel: t('wallet.exportWalletKey'),
  });
  if (!unlocked) return false;
  await downloadEncryptedWalletKeyBackup(record, unlocked);
  return true;
}

async function activateImportedEncryptedWalletRecord(wallet, record) {
  prepareWalletScopedRuntimeForWallet(wallet, 'wallet key imported');
  await writeEncryptedPlathoWalletRecord(record);
  plathoWallet = wallet;
  // Importing an encrypted wallet-key backup proves the key is already backed up (the file IS the export), so
  // clear any "key never exported" pending flag for this address -- in localStorage AND its Telegram CloudStorage
  // mirror, which survives a local-data wipe and would otherwise re-flag a freshly imported wallet on next boot.
  // IMPORT is never a backup-pending state.
  markWalletKeyBackupDone(wallet.address);
  localProfileAvatarPointer = readStoredProfileAvatarPointer(wallet.address);
  markWalletUnlocked();
  scheduleWalletAutoLock();
  await bootCrypto();
  // bootCrypto refreshed the avatar at its tail (serialized after sync); fire the vault refresh after it
  // fully settles so the single vault read does not overlap the avatar read on iOS.
  queueVaultRefreshAfterWalletChange();
  refreshMessagingControls();
  renderWalletIdentity(t('wallet.walletKeyImported'));
  return true;
}

async function importEncryptedWalletKeyFile(file) {
  const parsed = await readJsonFile(file);
  const record = encryptedWalletRecordFromBackup(parsed);
  const wallet = await requestAndDecryptEncryptedWallet(record, {
    title: t('wallet.importWalletKey'),
    hint: t('wallet.importWalletKeyHint'),
    submitLabel: t('wallet.importWalletKey'),
  });
  if (!wallet) return false;
  if (!(await confirmWalletReplacement(t('wallet.importWalletKey')))) return false;
  const restored = await activateImportedEncryptedWalletRecord(wallet, record);
  // v2+ backups also carry the user's own toncenter API key — restore it so importing the wallet key on a
  // new device brings the RPC key too. v1 backups (no key) skip this. Keyless toncenter works either way.
  if (restored && parsed?.kind === PLATHO_WALLET_KEY_BACKUP_KIND) {
    let restoredApiKey = null;
    if (parsed.toncenterApiKeyEnc) {
      // v3: encrypted under the wallet seed — decrypt with the just-unlocked wallet.
      try { restoredApiKey = await decryptToncenterApiKeyFromBackup(parsed.toncenterApiKeyEnc, wallet); }
      catch (error) { console.error(error); restoredApiKey = null; }
    } else if (typeof parsed.toncenterApiKey === 'string' && parsed.toncenterApiKey.trim()) {
      restoredApiKey = parsed.toncenterApiKey.trim(); // v2 legacy plaintext backups
    }
    if (restoredApiKey && restoredApiKey.trim()) applyToncenterApiKey(restoredApiKey.trim());
  }
  return restored;
}

async function requestWalletDisplayIdentity(mode) {
  const normalizedMode = normalizeWalletDisplayMode(mode);
  if (normalizedMode === WALLET_DISPLAY_MODES.ADDRESS) return { mode: WALLET_DISPLAY_MODES.ADDRESS, label: '' };
  const suffix = '.ath';
  let feedback = t('username.linkNameHint', { suffix });
  let tone = 'muted';
  const current = normalizedMode === WALLET_DISPLAY_MODES.PLATHO_NFT
    ? readLinkedPlathoUsername(plathoWallet?.address)
    : readWalletDisplayIdentity(plathoWallet?.address);
  let value = current?.mode === normalizedMode ? current.label : '';
  // Quick-pick names this profile is already known to own (linked/minted before) so a multi-username owner can
  // switch without retyping. Only for .ath display; the picked name is still re-verified on submit.
  const knownNames = normalizedMode === WALLET_DISPLAY_MODES.PLATHO_NFT
    ? readKnownPlathoUsernames(plathoWallet?.address)
    : [];
  const fields = [];
  if (knownNames.length > 0) {
    fields.push({
      id: 'pick',
      type: 'select',
      label: t('username.yourLinkedNames'),
      required: false,
      options: [{ value: '', label: t('username.enterNameBelow') }, ...knownNames.map((label) => ({ value: label, label }))],
      value: knownNames.includes(value) ? value : '',
    });
    fields.push({
      id: 'displayName',
      label: t('username.orDifferentName', { suffix }),
      placeholder: t('username.namePlaceholder'),
      autocomplete: 'off',
      required: false,
      value: '',
    });
  } else {
    fields.push({
      id: 'displayName',
      label: WALLET_DISPLAY_MODE_LABELS[normalizedMode],
      placeholder: t('username.namePlaceholder'),
      autocomplete: 'off',
      value,
    });
  }
  // The name is verified IN-PLACE on submit (validateSubmit): the dialog stays open and shows the error inline if
  // the name is not registered / not owned, instead of closing and immediately re-opening (the flicker the owner
  // reported). It only closes once the name passes verification.
  const verified = await openActionDialog({
    title: t('username.linkPlathoName'),
    hint: feedback,
    tone,
    submitLabel: t('username.linkName'),
    fields,
    checkingHint: t('username.verifyingName'),
    summary: (values) => {
      const chosen = (values.displayName?.trim() || values.pick || '').trim();
      return [{
        label: 'Check',
        value: chosen ? t('username.verifyOwnership', { chosen }) : t('username.permanentNameOwned'),
      }];
    },
    validateSubmit: async (values) => {
      const chosen = (values.displayName?.trim() || values.pick || '').trim();
      try {
        const result = await verifyWalletDisplayIdentity(normalizedMode, chosen, plathoWallet);
        if (result?.mode === WALLET_DISPLAY_MODES.PLATHO_NFT && result.label) {
          addKnownPlathoUsername(result.label, plathoWallet?.address);
        }
        return { ok: true, result };
      } catch (error) {
        return { ok: false, error: error?.message || t('username.useVerifiedName', { suffix }) };
      }
    },
  });
  return verified ?? null;
}

async function requestUsernameMintName() {
  let feedback = t('username.mintHint');
  let tone = 'muted';
  let usernameValue = '';
  while (true) {
    const result = await openActionDialog({
      title: t('username.mintPlathoName'),
      hint: feedback,
      tone,
      submitLabel: t('username.createUsername'),
      fields: [{
        id: 'username',
        label: t('username.usernameLabel'),
        placeholder: t('username.mintPlaceholder'),
        autocomplete: 'off',
        value: usernameValue,
      }],
      summary: (values) => {
        const raw = values.username?.trim() || t('common.notSet');
        const lines = [
          { label: t('username.display'), value: canonicalUsernameDisplay(raw) },
          { label: t('username.athPrice'), value: usernameMintPricePreview(raw) },
        ];
        // Show the live ATH balance + an affordability flag — but only when the Vault user (hence the balance)
        // is actually loaded, so we never claim "not enough" against an unknown balance.
        if (currentVaultUserSource()) {
          let priceAtomic = null;
          try { priceAtomic = localUsernameMintPriceAtomic(normalizeUsernameInput(raw)); } catch { priceAtomic = null; }
          const athBalance = currentAthBalanceAtomic();
          const short = priceAtomic !== null && athBalance < priceAtomic;
          lines.push({ label: t('username.yourAth'), value: short ? t('username.athBalanceNotEnough', { amount: formatAthAtomic(athBalance) }) : t('username.athBalance', { amount: formatAthAtomic(athBalance) }) });
        }
        lines.push({ label: t('username.gramHold'), value: t('username.gramHoldValue', { amount: formatTonNanotons(estimatedUsernameMintTonFeeNanotons()) }) });
        lines.push({ label: t('username.route'), value: t('vault.name') });
        return lines;
      },
    });
    if (!result) return null;
    usernameValue = result.username;
    try {
      const username = normalizeUsernameInput(result.username);
      // Up-front ATH affordability gate: don't let the user proceed to review/mint a name they can't pay for
      // (price is by length: 6+ chars = 100 ATH, 5 = 1000, 4 = 10000; <4 already rejected above). Only enforced
      // when the Vault user/balance is loaded; otherwise defer to the authoritative mint-time check.
      const priceAtomic = localUsernameMintPriceAtomic(username);
      if (priceAtomic !== null && currentVaultUserSource()) {
        const athBalance = currentAthBalanceAtomic();
        if (athBalance < priceAtomic) {
          throw new Error(`Insufficient ATH: ${username} costs ${formatAthAtomic(priceAtomic)} ATH, you have ${formatAthAtomic(athBalance)} — top up ATH in Vault`);
        }
      }
      return username;
    } catch (error) {
      feedback = error.message;
      tone = 'error';
    }
  }
}

